	// True for an OnPlay effect that needs the player to hand-pick an enemy: either a non-power effect aimed
	// at "Target" (or Copy Debuffs, which reads a chosen enemy's debuffs), or a power whose trigger watches
	// the "marked target" (the enemy designated when the card is played). Without this, a no-target card that
	// applies a MarkedTarget-watching power never captures which enemy to watch.
	private static bool EffectNeedsManualEnemyTarget(CardExtraEffect e)
	{
		if (e == null || e.GrantToCard || e.Trigger != CardExtraEffectTrigger.OnPlay)
		{
			return false;
		}
		if (IsPowerEffect(e))
		{
			return GetEffectivePowerTriggerFrom(e) == CardExtraEffectPowerTriggerFrom.MarkedTarget;
		}
		return IsValidEffectAmount(e.Kind, e.Amount)
			&& (e.Target == CardExtraEffectTarget.Target || e.Kind == CardExtraEffectKind.CopyDebuffs);
	}

	public static bool RequiresManualEnemyTarget(CardModel card)
	{
		if (card == null)
		{
			return false;
		}

		// Only force manual enemy targeting for cards that otherwise don't pick a creature target.
		// If a card already targets something specific (Self/Osty/All/etc), we treat "Target" as that implied target.
		TargetType targetType = card.TargetType;
		if (targetType != TargetType.None && targetType != TargetType.TargetedNoCreature)
		{
			return false;
		}

		if (TryGetOverride(card.Id, out CardOverride? overrideData))
		{
			IReadOnlyList<CardExtraEffect> overrideEffects = GetEffectiveExtraEffects(card, overrideData!, card.GetSafeCurrentUpgradeLevel() > 0);
			if (overrideEffects.Any(EffectNeedsManualEnemyTarget))
			{
				return true;
			}
		}

		CombatState? combatState = card.GetConcreteCombatState();
		if (combatState != null)
		{
			IReadOnlyList<CardExtraEffect> grantedEffects = GetActiveGrantedExtraEffects(combatState, card);
			if (grantedEffects.Any(EffectNeedsManualEnemyTarget))
			{
				return true;
			}
		}

		Creature? ownerCreature = card.TryGetOwnerCreature();
		if (ownerCreature == null)
		{
			return false;
		}

		CardEditorExtraEffectPower? power = ownerCreature.GetPower<CardEditorExtraEffectPower>();
		return power != null && power.HasOnPlayTargetEffects();
	}

	public static void SetManualTarget(CardModel card, Creature target)
	{
		if (card == null || target == null)
		{
			return;
		}
		ManualTargetHolder holder = _manualTargets.GetOrCreateValue(card);
		holder.Target = target;
		_manualTargetsByCardId[card.Id] = target;
		CardEditorMod.VerboseLog($"[CardEditor] Manual target: {card.Id.Entry} -> {target.Name}");
	}

	public static bool TryGetManualTarget(CardModel card, out Creature? target)
	{
		target = null;
		CardModel? cursor = card;
		for (int i = 0; i < 4 && cursor != null; i++)
		{
			if (_manualTargets.TryGetValue(cursor, out ManualTargetHolder? holder) && holder?.Target != null)
			{
				target = holder.Target;
				return true;
			}
			cursor = cursor.CloneOf;
		}
		if (_manualTargetsByCardId.TryGetValue(card.Id, out Creature? byId) && byId != null)
		{
			target = byId;
			return true;
		}
		return false;
	}

	public static void ClearManualTarget(CardModel card)
	{
		if (card == null)
		{
			return;
		}
		_manualTargets.Remove(card);
		_manualTargetsByCardId.Remove(card.Id);
	}

	private static void RememberLastPlayedCard(CombatState combatState, CardModel card)
	{
		Player? owner = card?.Owner;
		if (combatState == null || card == null || owner == null)
		{
			return;
		}

		LastPlayedCardState state = _lastPlayedCards.GetOrCreateValue(combatState);
		state.CardsByOwner[owner] = card;
	}

	private static CardModel? GetLastPlayedCardForOwner(CombatState combatState, Player owner)
	{
		if (combatState == null || owner == null)
		{
			return null;
		}

		return _lastPlayedCards.TryGetValue(combatState, out LastPlayedCardState? state)
			&& state.CardsByOwner.TryGetValue(owner, out CardModel? card)
			? card
			: null;
	}

