			CardExtraEffectOrbType.Dark => "Dark",
			CardExtraEffectOrbType.Plasma => "Plasma",
			CardExtraEffectOrbType.Glass => "Glass",
			_ => type.ToString()
		};
		return CardEditorLoc.Enum("orbType", type, fallback);
