	internal static bool SupportsValueSourceAmountSource(CardExtraEffectKind kind)
		=> SupportsAppliedEffectRowAmountSource(kind);

	internal static bool TryGetEffectPowerMatchStatus(CardExtraEffectKind kind, out CardExtraEffectEnemyStatus status)
	{
		switch (kind)
		{
			case CardExtraEffectKind.ApplyWeak:
			case CardExtraEffectKind.RemoveWeak:
				status = CardExtraEffectEnemyStatus.Weak;
				return true;
			case CardExtraEffectKind.ApplyFrail:
			case CardExtraEffectKind.RemoveFrail:
				status = CardExtraEffectEnemyStatus.Frail;
				return true;
			case CardExtraEffectKind.ApplyVulnerable:
			case CardExtraEffectKind.RemoveVulnerable:
				status = CardExtraEffectEnemyStatus.Vulnerable;
				return true;
			case CardExtraEffectKind.ApplyPoison:
			case CardExtraEffectKind.RemovePoison:
				status = CardExtraEffectEnemyStatus.Poison;
				return true;
			case CardExtraEffectKind.ApplyDoom:
			case CardExtraEffectKind.RemoveDoom:
				status = CardExtraEffectEnemyStatus.Doom;
				return true;
			case CardExtraEffectKind.ApplyConstrict:
			case CardExtraEffectKind.RemoveConstrict:
				status = CardExtraEffectEnemyStatus.Constrict;
				return true;
			case CardExtraEffectKind.GainArtifact:
			case CardExtraEffectKind.RemoveArtifact:
				status = CardExtraEffectEnemyStatus.Artifact;
				return true;
			case CardExtraEffectKind.GainThorns:
			case CardExtraEffectKind.RemoveThorns:
				status = CardExtraEffectEnemyStatus.Thorns;
				return true;
			case CardExtraEffectKind.GainRegen:
			case CardExtraEffectKind.RemoveRegen:
				status = CardExtraEffectEnemyStatus.Regen;
				return true;
			case CardExtraEffectKind.GainPlating:
			case CardExtraEffectKind.RemovePlating:
				status = CardExtraEffectEnemyStatus.Plating;
				return true;
			case CardExtraEffectKind.GainIntangible:
			case CardExtraEffectKind.RemoveIntangible:
				status = CardExtraEffectEnemyStatus.Intangible;
				return true;
			case CardExtraEffectKind.GainBuffer:
			case CardExtraEffectKind.RemoveBuffer:
				status = CardExtraEffectEnemyStatus.Buffer;
				return true;
			case CardExtraEffectKind.GainVigor:
			case CardExtraEffectKind.RemoveVigor:
				status = CardExtraEffectEnemyStatus.Vigor;
				return true;
			case CardExtraEffectKind.GainBlur:
			case CardExtraEffectKind.RemoveBlur:
				status = CardExtraEffectEnemyStatus.Blur;
				return true;
			case CardExtraEffectKind.GainRitual:
			case CardExtraEffectKind.RemoveRitual:
				status = CardExtraEffectEnemyStatus.Ritual;
				return true;
			case CardExtraEffectKind.GainStrength:
			case CardExtraEffectKind.LoseStrength:
				status = CardExtraEffectEnemyStatus.Strength;
				return true;
			case CardExtraEffectKind.GainDexterity:
			case CardExtraEffectKind.LoseDexterity:
				status = CardExtraEffectEnemyStatus.Dexterity;
				return true;
			case CardExtraEffectKind.GainFocus:
			case CardExtraEffectKind.LoseFocus:
				status = CardExtraEffectEnemyStatus.Focus;
				return true;
			default:
				status = default;
				return false;
		}
	}

	private static bool UsesAppliedEffectRowAmountSource(CardExtraEffect effect)
	{
		return effect != null
			&& SupportsAppliedEffectRowAmountSource(effect.Kind)
			&& effect.AmountSourceMode is CardExtraEffectAmountSourceMode.AppliedEffectRow
				or CardExtraEffectAmountSourceMode.AppliedEffectHpDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectBlockedDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectTotalDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectOverkillDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectTotalAndOverkillDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectInstances
				or CardExtraEffectAmountSourceMode.AppliedEffectKills
				or CardExtraEffectAmountSourceMode.ConfiguredEffectAmount
				or CardExtraEffectAmountSourceMode.ConfiguredEffectInstances;
	}

	private static bool UsesValueSourceAmountSource(CardExtraEffect effect)
	{
		return effect != null
			&& SupportsValueSourceAmountSource(effect.Kind)
			&& effect.AmountSourceMode == CardExtraEffectAmountSourceMode.ValueSource;
	}

	private static bool IsPowerEffect(CardExtraEffect? effect)
		=> effect != null && effect.AsPower && SupportsAsPower(effect.Kind);

	internal static bool IsLegacyOrbSlotKind(CardExtraEffectKind kind)
		=> kind is CardExtraEffectKind.GainOrbSlots or CardExtraEffectKind.LoseOrbSlots;

	internal static CardExtraEffect? NormalizeLegacyOrbSlotEffect(CardExtraEffect? effect)
	{
		if (effect == null || !IsLegacyOrbSlotKind(effect.Kind))
		{
			return effect;
		}

		int amount = effect.Amount < 0 ? GetPositiveSignedMagnitude(effect.Amount) : (effect.Amount == 0 ? 1 : effect.Amount);
		if (effect.Kind == CardExtraEffectKind.GainOrbSlots)
		{
			effect.Kind = CardExtraEffectKind.OrbAction;
			effect.OrbAction = effect.Amount < 0 ? CardExtraEffectOrbAction.RemoveSlots : CardExtraEffectOrbAction.AddSlots;
			effect.OrbScope = effect.OrbAction == CardExtraEffectOrbAction.RemoveSlots && amount >= 99
				? CardExtraEffectOrbScope.All
				: CardExtraEffectOrbScope.Fixed;
			effect.Amount = effect.OrbScope == CardExtraEffectOrbScope.All ? 1 : amount;
			return effect;
		}

		// LoseOrbSlots
		effect.Kind = CardExtraEffectKind.OrbAction;
		effect.OrbAction = effect.Amount < 0 ? CardExtraEffectOrbAction.AddSlots : CardExtraEffectOrbAction.RemoveSlots;
		effect.OrbScope = effect.OrbAction == CardExtraEffectOrbAction.RemoveSlots && amount >= 99
			? CardExtraEffectOrbScope.All
			: CardExtraEffectOrbScope.Fixed;
		effect.Amount = effect.OrbScope == CardExtraEffectOrbScope.All ? 1 : amount;
		return effect;
	}

	internal static CardExtraEffect? NormalizeSignedEffectAmount(CardExtraEffect? effect)
	{
		if (effect == null)
		{
			return effect;
		}

		CardExtraEffect? result = effect;
		bool changed = false;
		if (effect.Amount < 0 && TryGetSignedAmountOppositeKind(effect.Kind, out CardExtraEffectKind oppositeKind))
		{
			result = CloneEffect(effect);
			result.Kind = oppositeKind;
			result.Amount = GetPositiveSignedMagnitude(effect.Amount);
			changed = true;
		}
		else if (effect.Kind == CardExtraEffectKind.OrbAction
			&& effect.Amount < 0
			&& TryGetSignedAmountOppositeOrbAction(effect.OrbAction, out CardExtraEffectOrbAction oppositeOrbAction))
		{
			result = CloneEffect(effect);
			result.OrbAction = oppositeOrbAction;
			result.Amount = GetPositiveSignedMagnitude(effect.Amount);
			changed = true;
		}

		if (effect.BranchEffect != null)
		{
			CardExtraEffect? normalizedBranch = NormalizeSignedEffectAmount(effect.BranchEffect);
			if (!ReferenceEquals(normalizedBranch, effect.BranchEffect))
			{
				if (!changed)
				{
					result = CloneEffect(effect);
					changed = true;
				}

				result!.BranchEffect = normalizedBranch;
			}
		}

		CardExtraEffect? normalizedValueSourceScaling = NormalizeImplicitDefaultValueSourceScaling(result);
		if (!ReferenceEquals(normalizedValueSourceScaling, result))
		{
			result = normalizedValueSourceScaling;
		}

		return result;
	}

	private static CardExtraEffect? NormalizeImplicitDefaultValueSourceScaling(CardExtraEffect? effect)
	{
		if (effect == null
			|| effect.AmountSourceMode != CardExtraEffectAmountSourceMode.ValueSource
			|| effect.ValueSourceMode != CardExtraEffectValueSourceMode.PowerStatus
			|| !CardEditorCustomStatusRegistry.IsCustomStatusId(effect.ValueSourcePowerId)
			|| effect.ScaleMode == CardExtraEffectScaleMode.None)
		{
			return effect;
		}

		bool looksLikeUntouchedDefaultCountConfig =
			effect.ScaleMode == CardExtraEffectScaleMode.PerHistoryCount
			&& effect.CountEvent == CardExtraEffectCountEvent.Played
			&& effect.CountWindow == CardExtraEffectCountWindow.ThisCombat
			&& effect.CountWindowInclusion == CardExtraEffectCountWindowInclusion.IncludeThisTurn
			&& effect.CountComparison == CardExtraEffectCountComparison.None
			&& effect.CountConditionAmount <= 1
			&& effect.CountCardPile == CardExtraEffectCardPile.Hand
			&& effect.CountCardPool == CardGeneratedCardPool.All
			&& effect.CountCardType == CardGeneratedCardType.Any
			&& effect.CountCardFilter == CardExtraEffectCountCardFilter.Any
			&& effect.CountAggregationMode == CardExtraEffectCountAggregationMode.CardCount
			&& !effect.CountUsesCardEffectAmount
			&& !effect.CountExcludeSourceCard
			&& !effect.HistoryScalingIncludesBase
			&& effect.HistoryScalingBaseAmount == null
			&& effect.HistoryScalingCountStep <= 1;
		if (!looksLikeUntouchedDefaultCountConfig)
		{
			return effect;
		}

		CardExtraEffect normalized = CloneEffect(effect);
		normalized.ScaleMode = CardExtraEffectScaleMode.None;
		normalized.CountComparison = CardExtraEffectCountComparison.None;
		return normalized;
	}

	private static bool TryGetSignedAmountOppositeKind(CardExtraEffectKind kind, out CardExtraEffectKind oppositeKind)
	{
		switch (kind)
		{
			case CardExtraEffectKind.GainBlock:
				oppositeKind = CardExtraEffectKind.RemoveBlock;
				return true;
			case CardExtraEffectKind.RemoveBlock:
				oppositeKind = CardExtraEffectKind.GainBlock;
				return true;
			case CardExtraEffectKind.Heal:
