				return true;
			case CardExtraEffectKind.RemoveVulnerable:
				oppositeKind = CardExtraEffectKind.ApplyVulnerable;
				return true;
			case CardExtraEffectKind.ApplyPoison:
				oppositeKind = CardExtraEffectKind.RemovePoison;
