	private static bool TryGetSignedAmountOppositeOrbAction(CardExtraEffectOrbAction action, out CardExtraEffectOrbAction oppositeAction)
	{
		switch (action)
		{
			case CardExtraEffectOrbAction.AddSlots:
				oppositeAction = CardExtraEffectOrbAction.RemoveSlots;
				return true;
			case CardExtraEffectOrbAction.RemoveSlots:
				oppositeAction = CardExtraEffectOrbAction.AddSlots;
				return true;
			default:
				oppositeAction = default;
				return false;
		}
	}

	private static bool SupportsSignedAmountNormalization(CardExtraEffectKind kind)
		=> TryGetSignedAmountOppositeKind(kind, out _);

	private static int GetPositiveSignedMagnitude(int amount)
	{
		long magnitude = Math.Abs((long)amount);
		return magnitude >= int.MaxValue ? int.MaxValue : Math.Max(1, (int)magnitude);
	}

	private static IReadOnlyList<CardExtraEffect> NormalizeSignedEffectAmounts(IReadOnlyList<CardExtraEffect>? effects)
	{
		if (effects == null || effects.Count == 0)
		{
			return Array.Empty<CardExtraEffect>();
		}

		List<CardExtraEffect>? normalized = null;
		for (int i = 0; i < effects.Count; i++)
		{
			CardExtraEffect effect = effects[i];
			if (effect == null)
			{
				normalized?.Add(null!);
				continue;
			}

			CardExtraEffect? normalizedEffect = NormalizeSignedEffectAmount(effect);
			if (!ReferenceEquals(normalizedEffect, effect))
			{
				normalized ??= effects.Take(i).ToList();
				normalized.Add(normalizedEffect!);
			}
			else
			{
				normalized?.Add(effect);
			}
		}

		return normalized ?? effects;
	}

	private static IReadOnlyList<CardExtraEffect> ApplyEffectLimitRows(IReadOnlyList<CardExtraEffect>? effects)
	{
		if (effects == null || effects.Count == 0)
		{
			return Array.Empty<CardExtraEffect>();
		}

		if (!effects.Any(effect => effect?.Kind == CardExtraEffectKind.EffectLimit))
		{
			return effects;
		}

		List<CardExtraEffect> result = effects
			.Where(effect => effect != null && effect.Kind != CardExtraEffectKind.EffectLimit)
			.Select(CloneEffect)
			.ToList();

		if (result.Count == 0)
		{
			return result;
		}

		int limiterIndex = 0;
		foreach (CardExtraEffect limiter in effects.Where(effect => effect?.Kind == CardExtraEffectKind.EffectLimit))
		{
			if (limiter == null)
			{
				continue;
			}

			int limit = Math.Clamp(limiter.AutoPlayLoopLimit, 0, 999);
			if (limit <= 0)
			{
				limiterIndex++;
				continue;
			}

			List<string> targetIds = ParseDelimitedEffectIds(limiter.EffectLimitTargetEffectIds);
			if (targetIds.Count == 0)
			{
				limiterIndex++;
				continue;
			}

			HashSet<string> targetSet = new HashSet<string>(targetIds, StringComparer.Ordinal);
			string limitGroupId = BuildEffectLimitUseLimitGroupId(limiter, limiterIndex);
			foreach (CardExtraEffect target in result)
			{
				if (target == null || target.Kind == CardExtraEffectKind.EffectLimit)
				{
					continue;
				}

				if (string.IsNullOrWhiteSpace(target.EffectId) || !targetSet.Contains(target.EffectId))
				{
					continue;
				}

				target.AutoPlayLoopLimit = limit;
				target.AutoPlayLoopScope = limiter.AutoPlayLoopScope;
				target.UseLimitWindow = limiter.UseLimitWindow;
				target.AutoPlayAllowSelfTrigger = limiter.AutoPlayAllowSelfTrigger;
				target.UseLimitGroupId = limitGroupId;
			}

			limiterIndex++;
		}

		return result;
	}

	private static string BuildEffectLimitUseLimitGroupId(CardExtraEffect limiter, int limiterIndex)
	{
		string id = string.IsNullOrWhiteSpace(limiter?.EffectId)
			? limiterIndex.ToString(CultureInfo.InvariantCulture)
			: limiter!.EffectId!.Trim();
		return $"effect-limit:{id}";
	}

	private static List<string> ParseDelimitedEffectIds(string? text)
	{
		if (string.IsNullOrWhiteSpace(text))
		{
			return new List<string>();
		}

		return text
			.Split(new[] { ';', ',', '|', '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries)
			.Select(id => id.Trim())
			.Where(id => !string.IsNullOrWhiteSpace(id))
			.Distinct(StringComparer.Ordinal)
			.ToList();
	}

	internal static bool IsValidEffectAmount(CardExtraEffectKind kind, int amount)
	{
		return kind switch
		{
			CardExtraEffectKind.DealDamage => amount >= 0,
			CardExtraEffectKind.MultiplyStatStatus => amount >= 1,
			CardExtraEffectKind.GainStatusEqualToStatus => amount >= 1,
			CardExtraEffectKind.CountdownEffect => true,
			CardExtraEffectKind.SelfScaling => amount > 0,
			CardExtraEffectKind.PersistentSelfScaling => amount > 0,
			CardExtraEffectKind.TargetCardMutation => amount > 0,
			CardExtraEffectKind.PersistentTargetCardMutation => amount > 0,
			CardExtraEffectKind.LinkedCardAction => amount > 0,
			CardExtraEffectKind.DelayedPileAction => amount > 0,
			CardExtraEffectKind.ConsumeCardValue => amount > 0,
			CardExtraEffectKind.SelectCardsFromPile => amount > 0,
			CardExtraEffectKind.Quest => amount >= 0,
			CardExtraEffectKind.DisplayNumber => amount is >= -999 and <= 999,
			CardExtraEffectKind.CreatedCardsCostLess => amount == -1 || amount > 0,
			CardExtraEffectKind.CardCostsLess => amount != 0,
			CardExtraEffectKind.CardStarCostsLess => amount != 0,
			CardExtraEffectKind.CardTypeCostsLess => amount != 0,
			CardExtraEffectKind.CardTypeStarCostsLess => amount != 0,
			CardExtraEffectKind.DrawnCardsCostLess => amount != 0,
			CardExtraEffectKind.GeneratedCardsCostLess => amount != 0,
			_ when SupportsSignedAmountNormalization(kind) => true,
			_ => amount >= 0
		};
	}

	private static bool IsRenderableDescriptionEffect(CardExtraEffect? effect)
	{
		if (effect == null)
		{
			return false;
		}
		if (effect.PayloadOnly)
		{
			return false;
		}

		return effect.Kind == CardExtraEffectKind.CreatedCardsCostLess
			? IsRenderableCreatedCardsCostLess(effect)
			: IsValidEffectAmount(effect.Kind, effect.Amount);
	}

	private static bool IsRenderableCreatedCardsCostLess(CardExtraEffect effect)
	{
		if (effect == null || effect.Kind != CardExtraEffectKind.CreatedCardsCostLess)
		{
			return false;
		}

		if (effect.AmountIsX || IsValidEffectAmount(effect.Kind, effect.Amount))
		{
			return true;
		}

		return GetEffectiveCardCostsLessModifier(effect) is CardExtraEffectCostModifier.Free
			or CardExtraEffectCostModifier.FreeToPlay
			or CardExtraEffectCostModifier.HalfCost;
	}

	// One acceptance rule for effects loaded from storage, shared by editor row hydration, preset
	// load, and upgrade rebasing. Raw IsValidEffectAmount alone rejects effects the SAVE path
	// legitimately persists (CreatedCardsCostLess with a Free/FreeToPlay/HalfCost modifier stores
	// Amount=0, and X-amount effects bypass the amount rules) - dropping those on load and then
	// saving the pruned list back is how an unrelated edit used to wipe custom keywords.
	internal static bool IsPersistableEffect(CardExtraEffect? effect)
	{
		if (effect == null)
		{
			return false;
		}

		if (effect.Kind == CardExtraEffectKind.CreatedCardsCostLess)
		{
			return IsRenderableCreatedCardsCostLess(effect);
		}

		return effect.AmountIsX || IsValidEffectAmount(effect.Kind, effect.Amount);
	}

	// Upgrade "extra effects" store deltas for the base slots (index-based). Those deltas can be negative to cancel/remove
	// a base effect on the upgraded version (e.g. base 6 + delta -6 => removed).
	internal static bool IsValidUpgradeDeltaAmount(CardExtraEffectKind kind, int amount)
	{
		return amount != 0;
	}

	internal static bool HasMeaningfulUpgradeBaseSlotDelta(CardExtraEffect effect, bool secondaryNumericFieldsAreDeltas)
	{
		// Back-compat helper for callers that don't have the base effect available.
		// This is intentionally conservative and only checks numeric/delta fields.
		if (effect == null)
		{
			return false;
		}

		if (effect.DisableOnUpgrade || IsValidUpgradeDeltaAmount(effect.Kind, effect.Amount))
		{
			return true;
		}

		if (effect.IncludeSourceCardInSelection
			|| effect.FutureMatchingCards
			|| !string.IsNullOrWhiteSpace(effect.CardSelectionSourceEffectId)
			|| effect.AmountSourceMode != CardExtraEffectAmountSourceMode.Fixed
			|| effect.AmountSourceMultiplier != 1
			|| effect.ValueSourceMode != CardExtraEffectValueSourceMode.Common
			|| effect.ValueSourceActor != CardExtraEffectValueSourceActor.Self
			|| effect.ValueSourceAggregation != CardExtraEffectValueSourceAggregation.Value
			|| effect.ValueSourceKind != CardExtraEffectValueSourceKind.MaxHp
			|| !string.IsNullOrWhiteSpace(effect.ValueSourcePowerId)
			|| effect.ResourceConsumptionMode != CardExtraEffectResourceConsumptionMode.Vigor
			|| (effect.ResourceConsumptionMode == CardExtraEffectResourceConsumptionMode.SpecificStatStatus
				&& effect.ResourceConsumptionStat != CardExtraEffectMultiplierStat.Vigor)
			|| (effect.ResourceConsumptionMode == CardExtraEffectResourceConsumptionMode.SpecificPowerStatus
				&& !string.IsNullOrWhiteSpace(effect.PowerId))
			|| effect.MultiplierSourceMode != CardExtraEffectValueSourceMode.Common
			|| !string.IsNullOrWhiteSpace(effect.MultiplierPowerId)
			|| effect.ConditionProgressDisplay != CardExtraEffectConditionProgressDisplay.Hidden
			|| effect.StatusToStatusMode != CardExtraEffectStatusToStatusMode.Gain
			|| effect.ActivePowerSelection != CardExtraEffectActivePowerSelection.All
			|| effect.PlayPreventionBlockMode != CardExtraEffectPlayPreventionBlockMode.ManualAndAutoPlay
			|| effect.PlayPreventionExemption != CardExtraEffectPlayPreventionExemption.None
			|| effect.GlowColorMode != CardExtraEffectGlowColorMode.Red
			|| !string.IsNullOrWhiteSpace(effect.GlowCustomColor)
			|| effect.QuestMode != CardExtraEffectQuestMode.RunProgress
			|| effect.QuestActIndex != -1
			|| !string.IsNullOrWhiteSpace(effect.QuestEventId))
		{
			return true;
		}

		if (!secondaryNumericFieldsAreDeltas)
		{
			return false;
		}

		return effect.Turns != 0
			|| effect.RepeatIsX
			|| effect.RepeatCount != 0
			|| effect.RepeatScalingExtraTimes != 0
			|| !string.IsNullOrWhiteSpace(effect.CreatureCommandId)
			|| effect.TriggerEveryN != 0
			|| effect.TriggerMaxFires != 0
			|| effect.TriggerMaxTurns != 0
			|| effect.AutoPlayLoopLimit != 0
			|| (effect.AutoPlayLoopLimit != 0 && effect.UseLimitWindow != CardExtraEffectUseLimitWindow.Turn)
			|| effect.PowerStackMode != CardExtraEffectPowerStackMode.Merge
			|| effect.PowerPersistenceMode != CardExtraEffectPowerPersistenceMode.Normal
			|| effect.PotionMode != CardExtraEffectPotionMode.Random
			|| effect.PotionPoolFilter != CardExtraEffectPotionPoolFilter.Vanilla
			|| effect.PotionRarityFilter != CardExtraEffectPotionRarityFilter.Any
			|| !effect.PotionInCombatOnly
			|| effect.PotionAllowDuplicates
			|| !string.IsNullOrWhiteSpace(effect.SpecificPotionId)
			|| effect.CardRewardRarityFilter != CardExtraEffectCardRewardRarityFilter.Any
			|| effect.CardRewardSource != CardExtraEffectCardRewardSource.RoomDefault
			|| effect.CardRewardRarityOdds != CardExtraEffectCardRewardRarityOdds.RoomDefault
			|| effect.CreatedCardsCostDuration != CardCreatedCardsCostDuration.ThisTurn
			|| effect.CreatedCardsCostTurns != 0
			|| effect.CreatedCardsCostResource != CardCreatedCardsCostResource.Energy
			|| GetEffectiveCardCostsLessModifier(effect) != CardExtraEffectCostModifier.Reduce
			|| effect.MatchingCostUseLimitMode != CardExtraEffectMatchingCostUseLimitMode.Unlimited
			|| effect.CardCostsLessTurns != 0
			|| effect.CountTurns != 0
			|| effect.CountConditionAmount != 0
			|| effect.HistoryScalingBaseAmount.GetValueOrDefault() != 0
			|| effect.HistoryScalingCountStep != 0
			|| effect.RepeatScalingExtraTimes != 0
			|| GetEffectiveCountAggregationMode(effect) != CardExtraEffectCountAggregationMode.CardCount
			|| effect.CardGrantTurns != 0
			|| effect.CardSelectionCount != 0
			|| effect.EnchantmentTurns != 0
			|| effect.ConditionalBonusAmount != 0
			|| effect.ConditionalBonusConditionType != CardExtraEffectBranchConditionType.None
			|| effect.ConditionalBonusCondition != CardExtraEffectConditionalBonusCondition.None
			|| !string.IsNullOrWhiteSpace(effect.ConditionalBonusPowerId)
			|| effect.BranchMode != CardExtraEffectBranchMode.None
			|| effect.BranchConditionType != CardExtraEffectBranchConditionType.None
			|| effect.BranchCondition != CardExtraEffectConditionalBonusCondition.None
			|| !string.IsNullOrWhiteSpace(effect.BranchPowerId)
			|| effect.BranchEffect != null
			|| effect.BranchCountTurns != 0
			|| effect.BranchCountCardPool != CardGeneratedCardPool.All
			|| effect.BranchCountCardType != CardGeneratedCardType.Any
			|| effect.BranchCountCardRarity != CardExtraEffectCardRarityFilter.Any
			|| effect.BranchCountCardFilter != CardExtraEffectCountCardFilter.Any
			|| HasBranchCountCardMatchFilter(effect)
			|| GetEffectiveBranchCountAggregationMode(effect) != CardExtraEffectCountAggregationMode.CardCount
			|| effect.BranchCountExcludeSourceCard
			|| effect.BranchCountOrbType != CardExtraEffectOrbType.Any
			|| effect.BranchCountOrbSelection != CardExtraEffectOrbSelection.Leftmost
			|| effect.BranchCountEnemyStatus != CardExtraEffectEnemyStatus.Weak
			|| !string.IsNullOrWhiteSpace(effect.BranchCountPowerId)
			|| effect.BranchCountEnemyIntent != CardExtraEffectEnemyIntent.Attack
			|| !string.IsNullOrWhiteSpace(effect.BranchCountResultEffectId)
			|| effect.BranchCountResultMetric != CardExtraEffectResultMetric.Kills
			|| effect.BranchCountComparison != CardExtraEffectCountComparison.None
			|| effect.BranchCountConditionAmount != 0
			|| effect.PowerTriggerEnemyStatus != CardExtraEffectEnemyStatus.AnyPowerStatus
			|| !string.IsNullOrWhiteSpace(effect.PowerTriggerPowerId)
			|| !string.IsNullOrWhiteSpace(effect.CountPowerId)
			|| !string.IsNullOrWhiteSpace(effect.CountResultEffectId)
			|| effect.CountResultMetric != CardExtraEffectResultMetric.Kills
			|| effect.CountCardRarity != CardExtraEffectCardRarityFilter.Any
			|| effect.CardSelectionRarity != CardExtraEffectCardRarityFilter.Any
			|| effect.TriggerCardRarity != CardExtraEffectCardRarityFilter.Any
			|| !string.IsNullOrWhiteSpace(effect.MatchCustomKeyword)
			|| !string.IsNullOrWhiteSpace(effect.CustomKeywordName)
			|| !string.IsNullOrWhiteSpace(effect.CustomPowerName)
			|| !string.IsNullOrWhiteSpace(effect.CustomPowerDescription)
			|| !string.IsNullOrWhiteSpace(effect.EffectLimitTargetEffectIds)
			|| (effect.Kind == CardExtraEffectKind.ChooseOneEffectSource
				&& GetChooseOneOptions(effect).Count > 0)
			|| (effect.Kind == CardExtraEffectKind.StatefulTransform
				&& (effect.StatefulTransformMode != CardExtraEffectStatefulTransformMode.Transform
					|| effect.StatefulTransformDuration != CardExtraEffectStatefulTransformDuration.ThisCombat
					|| effect.StatefulTransformDurationAmount != 1
					|| !string.IsNullOrWhiteSpace(effect.SpecificCardId)))
			|| (effect.Kind == CardExtraEffectKind.TransformCards
				&& (effect.TransformMode != CardExtraEffectTransformMode.Random || !string.IsNullOrWhiteSpace(effect.SpecificCardId)));
	}

	internal static bool HasMeaningfulUpgradeBaseSlotDelta(CardExtraEffect baseEffect, CardExtraEffect upgradeEffect, bool secondaryNumericFieldsAreDeltas)
	{
		if (upgradeEffect == null)
		{
			return false;
		}

		if (upgradeEffect.DisableOnUpgrade || IsValidUpgradeDeltaAmount(upgradeEffect.Kind, upgradeEffect.Amount))
		{
			return true;
		}

		if (upgradeEffect.IncludeSourceCardInSelection
			|| upgradeEffect.FutureMatchingCards
			|| !string.IsNullOrWhiteSpace(upgradeEffect.CardSelectionSourceEffectId)
			|| upgradeEffect.AmountSourceMode != CardExtraEffectAmountSourceMode.Fixed
			|| upgradeEffect.AmountSourceMultiplier != 1
			|| upgradeEffect.ValueSourceMode != CardExtraEffectValueSourceMode.Common
			|| upgradeEffect.ValueSourceActor != CardExtraEffectValueSourceActor.Self
			|| upgradeEffect.ValueSourceAggregation != CardExtraEffectValueSourceAggregation.Value
			|| upgradeEffect.ValueSourceKind != CardExtraEffectValueSourceKind.MaxHp
			|| !string.IsNullOrWhiteSpace(upgradeEffect.ValueSourcePowerId)
			|| upgradeEffect.ResourceConsumptionMode != CardExtraEffectResourceConsumptionMode.Vigor
			|| (upgradeEffect.ResourceConsumptionMode == CardExtraEffectResourceConsumptionMode.SpecificStatStatus
				&& upgradeEffect.ResourceConsumptionStat != CardExtraEffectMultiplierStat.Vigor)
			|| (upgradeEffect.ResourceConsumptionMode == CardExtraEffectResourceConsumptionMode.SpecificPowerStatus
				&& !string.IsNullOrWhiteSpace(upgradeEffect.PowerId))
			|| upgradeEffect.MultiplierSourceMode != CardExtraEffectValueSourceMode.Common
			|| !string.IsNullOrWhiteSpace(upgradeEffect.MultiplierPowerId)
			|| upgradeEffect.ConditionProgressDisplay != CardExtraEffectConditionProgressDisplay.Hidden
			|| upgradeEffect.StatusToStatusMode != CardExtraEffectStatusToStatusMode.Gain
			|| upgradeEffect.ActivePowerSelection != CardExtraEffectActivePowerSelection.All
			|| upgradeEffect.PlayPreventionBlockMode != CardExtraEffectPlayPreventionBlockMode.ManualAndAutoPlay
			|| upgradeEffect.PlayPreventionExemption != CardExtraEffectPlayPreventionExemption.None
			|| upgradeEffect.GlowColorMode != CardExtraEffectGlowColorMode.Red
			|| !string.IsNullOrWhiteSpace(upgradeEffect.GlowCustomColor)
			|| upgradeEffect.QuestMode != CardExtraEffectQuestMode.RunProgress
			|| upgradeEffect.QuestActIndex != -1
			|| !string.IsNullOrWhiteSpace(upgradeEffect.QuestEventId))
		{
			return true;
		}

		if (secondaryNumericFieldsAreDeltas)
		{
			if (upgradeEffect.Turns != 0
				|| upgradeEffect.RepeatCount != 0
				|| upgradeEffect.RepeatScalingExtraTimes != 0
				|| upgradeEffect.TriggerEveryN != 0
				|| upgradeEffect.TriggerMaxFires != 0
				|| upgradeEffect.TriggerMaxTurns != 0
				|| upgradeEffect.AutoPlayLoopLimit != 0
				|| upgradeEffect.StatefulTransformDurationAmount != 0
				|| (upgradeEffect.AutoPlayLoopLimit != 0 && upgradeEffect.UseLimitWindow != CardExtraEffectUseLimitWindow.Turn)
				|| upgradeEffect.CreatedCardsCostDuration != CardCreatedCardsCostDuration.ThisTurn
				|| upgradeEffect.CreatedCardsCostTurns != 0
				|| upgradeEffect.CreatedCardsCostResource != CardCreatedCardsCostResource.Energy
				|| GetEffectiveCardCostsLessModifier(upgradeEffect) != CardExtraEffectCostModifier.Reduce
				|| upgradeEffect.MatchingCostUseLimitMode != CardExtraEffectMatchingCostUseLimitMode.Unlimited
				|| upgradeEffect.CardCostsLessTurns != 0
				|| upgradeEffect.CountTurns != 0
				|| upgradeEffect.CountConditionAmount != 0
				|| upgradeEffect.HistoryScalingBaseAmount.GetValueOrDefault() != 0
				|| upgradeEffect.HistoryScalingCountStep != 0
				|| upgradeEffect.RepeatScalingExtraTimes != 0
				|| upgradeEffect.CardGrantTurns != 0
				|| upgradeEffect.CardSelectionCount != 0
				|| upgradeEffect.CardSelectionRarity != CardExtraEffectCardRarityFilter.Any
				|| upgradeEffect.TriggerCardRarity != CardExtraEffectCardRarityFilter.Any
				|| upgradeEffect.CountCardRarity != CardExtraEffectCardRarityFilter.Any
				|| upgradeEffect.EnchantmentTurns != 0
				|| upgradeEffect.ConditionalBonusAmount != 0
				|| upgradeEffect.ConditionalBonusConditionType != CardExtraEffectBranchConditionType.None
				|| !string.IsNullOrWhiteSpace(upgradeEffect.ConditionalBonusPowerId)
				|| upgradeEffect.BranchMode != CardExtraEffectBranchMode.None
				|| upgradeEffect.BranchConditionType != CardExtraEffectBranchConditionType.None
				|| upgradeEffect.BranchCondition != CardExtraEffectConditionalBonusCondition.None
				|| !string.IsNullOrWhiteSpace(upgradeEffect.BranchPowerId)
				|| !string.IsNullOrWhiteSpace(upgradeEffect.BranchCountPowerId)
				|| !string.IsNullOrWhiteSpace(upgradeEffect.BranchCountResultEffectId)
				|| upgradeEffect.BranchCountResultMetric != CardExtraEffectResultMetric.Kills
				|| upgradeEffect.BranchCountCardRarity != CardExtraEffectCardRarityFilter.Any
				|| !string.IsNullOrWhiteSpace(upgradeEffect.PowerTriggerPowerId)
				|| !string.IsNullOrWhiteSpace(upgradeEffect.CountPowerId)
				|| !string.IsNullOrWhiteSpace(upgradeEffect.CountResultEffectId)
				|| upgradeEffect.CountResultMetric != CardExtraEffectResultMetric.Kills
				|| !string.IsNullOrWhiteSpace(upgradeEffect.EffectLimitTargetEffectIds)
				|| upgradeEffect.BranchEffect != null)
			{
				return true;
			}
		}
		else
		{
			// If numeric fields are absolute, any non-default value is meaningful. This matches
			// the legacy behavior where upgrades stored absolute values instead of deltas.
			if (upgradeEffect.Turns != 0
				|| upgradeEffect.RepeatCount != 0
				|| upgradeEffect.TriggerEveryN != 0
				|| upgradeEffect.TriggerMaxFires != 0
				|| upgradeEffect.TriggerMaxTurns != 0
				|| upgradeEffect.AutoPlayLoopLimit != 0
				|| upgradeEffect.StatefulTransformDurationAmount != 0
				|| (upgradeEffect.AutoPlayLoopLimit != 0 && upgradeEffect.UseLimitWindow != CardExtraEffectUseLimitWindow.Turn)
				|| upgradeEffect.CreatedCardsCostDuration != CardCreatedCardsCostDuration.ThisTurn
				|| upgradeEffect.CreatedCardsCostTurns != 0
				|| upgradeEffect.CreatedCardsCostResource != CardCreatedCardsCostResource.Energy
				|| GetEffectiveCardCostsLessModifier(upgradeEffect) != CardExtraEffectCostModifier.Reduce
				|| upgradeEffect.MatchingCostUseLimitMode != CardExtraEffectMatchingCostUseLimitMode.Unlimited
				|| upgradeEffect.CardCostsLessTurns != 0
				|| upgradeEffect.CountTurns != 0
				|| upgradeEffect.CountConditionAmount != 0
				|| upgradeEffect.HistoryScalingBaseAmount.GetValueOrDefault() != 0
				|| upgradeEffect.HistoryScalingCountStep != 0
				|| upgradeEffect.RepeatScalingExtraTimes != 0
				|| upgradeEffect.CardGrantTurns != 0
				|| upgradeEffect.CardSelectionCount != 0
				|| upgradeEffect.EnchantmentTurns != 0
				|| upgradeEffect.ConditionalBonusAmount != 0
				|| upgradeEffect.ConditionalBonusConditionType != CardExtraEffectBranchConditionType.None
				|| upgradeEffect.ConditionalBonusCondition != CardExtraEffectConditionalBonusCondition.None
				|| !string.IsNullOrWhiteSpace(upgradeEffect.ConditionalBonusPowerId)
				|| upgradeEffect.BranchMode != CardExtraEffectBranchMode.None
				|| upgradeEffect.BranchConditionType != CardExtraEffectBranchConditionType.None
				|| upgradeEffect.BranchCondition != CardExtraEffectConditionalBonusCondition.None
				|| !string.IsNullOrWhiteSpace(upgradeEffect.BranchPowerId)
				|| !string.IsNullOrWhiteSpace(upgradeEffect.BranchCountPowerId)
				|| !string.IsNullOrWhiteSpace(upgradeEffect.PowerTriggerPowerId)
				|| !string.IsNullOrWhiteSpace(upgradeEffect.CountPowerId)
				|| !string.IsNullOrWhiteSpace(upgradeEffect.EffectLimitTargetEffectIds)
				|| upgradeEffect.BranchEffect != null)
			{
				return true;
			}
		}

		// Support non-numeric overrides for specific kinds where the upgrade UI exposes meaningful changes.
		// This fixes cases like OrbAction: Trigger Passive (One -> All) not persisting on upgrade.
		if (baseEffect != null && baseEffect.Kind == CardExtraEffectKind.OrbAction && upgradeEffect.Kind == CardExtraEffectKind.OrbAction)
		{
			return baseEffect.OrbAction != upgradeEffect.OrbAction
				|| baseEffect.OrbScope != upgradeEffect.OrbScope
				|| baseEffect.OrbType != upgradeEffect.OrbType
				|| baseEffect.OrbSelection != upgradeEffect.OrbSelection
				|| baseEffect.OrbFollowUp != upgradeEffect.OrbFollowUp;
		}

		if (baseEffect != null)
		{
			if (baseEffect.RepeatIsX != upgradeEffect.RepeatIsX)
			{
				return true;
			}

			if (baseEffect.IncludeSourceCardInSelection != upgradeEffect.IncludeSourceCardInSelection)
			{
				return true;
			}

			if (baseEffect.FutureMatchingCards != upgradeEffect.FutureMatchingCards)
			{
				return true;
			}

			if (!string.Equals(baseEffect.CardSelectionSourceEffectId ?? string.Empty, upgradeEffect.CardSelectionSourceEffectId ?? string.Empty, StringComparison.Ordinal))
			{
				return true;
			}

			if (baseEffect.AutoPlayAllowSelfTrigger != upgradeEffect.AutoPlayAllowSelfTrigger)
			{
				return true;
			}

			if (baseEffect.AutoPlayLoopScope != upgradeEffect.AutoPlayLoopScope)
			{
				return true;
			}

			if (baseEffect.UseLimitWindow != upgradeEffect.UseLimitWindow)
			{
				return true;
			}

			if (baseEffect.MatchingCostUseLimitMode != upgradeEffect.MatchingCostUseLimitMode
				|| baseEffect.MatchingCostUseLimit != upgradeEffect.MatchingCostUseLimit)
			{
				return true;
			}

			if (baseEffect.PowerStackMode != upgradeEffect.PowerStackMode)
			{
				return true;
			}

			if (baseEffect.PowerPersistenceMode != upgradeEffect.PowerPersistenceMode)
			{
				return true;
			}

			if (baseEffect.PlayPreventionBlockMode != upgradeEffect.PlayPreventionBlockMode
				|| baseEffect.PlayPreventionExemption != upgradeEffect.PlayPreventionExemption
				|| baseEffect.GlowColorMode != upgradeEffect.GlowColorMode
				|| !string.Equals(baseEffect.GlowCustomColor ?? string.Empty, upgradeEffect.GlowCustomColor ?? string.Empty, StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}

			if (baseEffect.QuestMode != upgradeEffect.QuestMode
				|| baseEffect.QuestActIndex != upgradeEffect.QuestActIndex
				|| !string.Equals(baseEffect.QuestEventId ?? string.Empty, upgradeEffect.QuestEventId ?? string.Empty, StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}

			if (baseEffect.PotionMode != upgradeEffect.PotionMode
				|| baseEffect.PotionPoolFilter != upgradeEffect.PotionPoolFilter
				|| baseEffect.PotionRarityFilter != upgradeEffect.PotionRarityFilter
				|| baseEffect.PotionInCombatOnly != upgradeEffect.PotionInCombatOnly
				|| baseEffect.PotionAllowDuplicates != upgradeEffect.PotionAllowDuplicates
				|| !string.Equals(baseEffect.SpecificPotionId ?? string.Empty, upgradeEffect.SpecificPotionId ?? string.Empty, StringComparison.Ordinal))
			{
				return true;
			}

			if (baseEffect.CardRewardRarityFilter != upgradeEffect.CardRewardRarityFilter
				|| baseEffect.CardRewardSource != upgradeEffect.CardRewardSource
				|| baseEffect.CardRewardRarityOdds != upgradeEffect.CardRewardRarityOdds)
			{
				return true;
			}

			if (!string.Equals(baseEffect.EffectLimitTargetEffectIds ?? string.Empty, upgradeEffect.EffectLimitTargetEffectIds ?? string.Empty, StringComparison.Ordinal))
			{
				return true;
			}

			if (!secondaryNumericFieldsAreDeltas
				&& Math.Max(0, baseEffect.AutoPlayLoopLimit) != Math.Max(0, upgradeEffect.AutoPlayLoopLimit))
			{
				return true;
			}

			if (baseEffect.AmountSourceMode != upgradeEffect.AmountSourceMode
				|| baseEffect.AmountSourceMultiplier != upgradeEffect.AmountSourceMultiplier
				|| !string.Equals(baseEffect.AmountSourceEffectId ?? string.Empty, upgradeEffect.AmountSourceEffectId ?? string.Empty, StringComparison.Ordinal))
			{
				return true;
			}

			if (baseEffect.ValueSourceMode != upgradeEffect.ValueSourceMode
				|| baseEffect.ValueSourceActor != upgradeEffect.ValueSourceActor
				|| baseEffect.ValueSourceAggregation != upgradeEffect.ValueSourceAggregation
				|| baseEffect.ValueSourceKind != upgradeEffect.ValueSourceKind
				|| !string.Equals(baseEffect.ValueSourcePowerId ?? string.Empty, upgradeEffect.ValueSourcePowerId ?? string.Empty, StringComparison.Ordinal))
			{
				return true;
			}

			if (baseEffect.ResourceConsumptionMode != upgradeEffect.ResourceConsumptionMode)
			{
				return true;
			}

			if (baseEffect.MultiplierSourceMode != upgradeEffect.MultiplierSourceMode
				|| !string.Equals(baseEffect.MultiplierPowerId ?? string.Empty, upgradeEffect.MultiplierPowerId ?? string.Empty, StringComparison.Ordinal))
			{
				return true;
			}

			if (baseEffect.ResourceConsumptionStat != upgradeEffect.ResourceConsumptionStat)
			{
				return true;
			}

			if (!string.Equals(baseEffect.PowerId ?? string.Empty, upgradeEffect.PowerId ?? string.Empty, StringComparison.Ordinal))
			{
				return true;
			}

			if (baseEffect.StatusToStatusMode != upgradeEffect.StatusToStatusMode)
			{
				return true;
			}

			if (baseEffect.ActivePowerSelection != upgradeEffect.ActivePowerSelection)
			{
				return true;
			}

			if (baseEffect.CountExcludeSourceCard != upgradeEffect.CountExcludeSourceCard)
			{
				return true;
			}

			if (GetEffectiveCountAggregationMode(baseEffect) != GetEffectiveCountAggregationMode(upgradeEffect))
			{
				return true;
			}

			if (!secondaryNumericFieldsAreDeltas
				&& ResolveHistoryScalingBaseAmount(baseEffect, baseEffect.Amount) != ResolveHistoryScalingBaseAmount(upgradeEffect, upgradeEffect.Amount))
			{
				return true;
			}

			if (!secondaryNumericFieldsAreDeltas
				&& ResolveHistoryScalingCountStep(baseEffect) != ResolveHistoryScalingCountStep(upgradeEffect))
			{
				return true;
			}

			if (!secondaryNumericFieldsAreDeltas
				&& ResolveRepeatScalingExtraTimes(baseEffect) != ResolveRepeatScalingExtraTimes(upgradeEffect))
			{
				return true;
			}

			if (baseEffect.PowerTriggerEnemyStatus != upgradeEffect.PowerTriggerEnemyStatus
				|| !string.Equals(baseEffect.PowerTriggerPowerId ?? string.Empty, upgradeEffect.PowerTriggerPowerId ?? string.Empty, StringComparison.Ordinal)
				|| baseEffect.CountEnemyStatus != upgradeEffect.CountEnemyStatus
				|| !string.Equals(baseEffect.CountPowerId ?? string.Empty, upgradeEffect.CountPowerId ?? string.Empty, StringComparison.Ordinal))
			{
				return true;
			}

			if (baseEffect.UseMoveDestinationForGeneratedCards != upgradeEffect.UseMoveDestinationForGeneratedCards)
			{
				return true;
			}
			if (baseEffect.CreatedCardsCostResource != upgradeEffect.CreatedCardsCostResource)
			{
				return true;
			}
			if (baseEffect.CreatedCardsCostDuration != upgradeEffect.CreatedCardsCostDuration)
			{
				return true;
			}
			if (GetEffectiveCardCostsLessModifier(baseEffect) != GetEffectiveCardCostsLessModifier(upgradeEffect))
			{
				return true;
			}
			if (baseEffect.AdditionalMoveToPiles != upgradeEffect.AdditionalMoveToPiles)
			{
				return true;
			}
			if (baseEffect.CopyMode != upgradeEffect.CopyMode)
			{
				return true;
			}
			if (baseEffect.DelayedPileAction != upgradeEffect.DelayedPileAction
				|| baseEffect.DelayedPileCounterUnit != upgradeEffect.DelayedPileCounterUnit
				|| baseEffect.DelayedPileCounterScope != upgradeEffect.DelayedPileCounterScope)
			{
				return true;
			}

			// Treat CustomKeywordName as "inherit from base" unless explicitly set on the upgrade effect.
			// This prevents upgrades from accidentally "un-fusing" keyword-grouped effects when the delta
			// only changes numbers.
			string? baseKeyword = string.IsNullOrWhiteSpace(baseEffect.CustomKeywordName) ? null : baseEffect.CustomKeywordName.Trim();
			string? upgradeKeyword = string.IsNullOrWhiteSpace(upgradeEffect.CustomKeywordName) ? null : upgradeEffect.CustomKeywordName.Trim();
			if (upgradeKeyword != null && !string.Equals(baseKeyword ?? string.Empty, upgradeKeyword, StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}

			string? basePowerName = string.IsNullOrWhiteSpace(baseEffect.CustomPowerName) ? null : baseEffect.CustomPowerName.Trim();
			string? upgradePowerName = string.IsNullOrWhiteSpace(upgradeEffect.CustomPowerName) ? null : upgradeEffect.CustomPowerName.Trim();
			if (upgradePowerName != null && !string.Equals(basePowerName ?? string.Empty, upgradePowerName, StringComparison.Ordinal))
			{
				return true;
			}

			string? basePowerDescription = string.IsNullOrWhiteSpace(baseEffect.CustomPowerDescription) ? null : baseEffect.CustomPowerDescription.Trim();
			string? upgradePowerDescription = string.IsNullOrWhiteSpace(upgradeEffect.CustomPowerDescription) ? null : upgradeEffect.CustomPowerDescription.Trim();
			if (upgradePowerDescription != null && !string.Equals(basePowerDescription ?? string.Empty, upgradePowerDescription, StringComparison.Ordinal))
			{
				return true;
			}

			if (baseEffect.ConditionalBonusConditionType != upgradeEffect.ConditionalBonusConditionType
				|| baseEffect.ConditionalBonusCondition != upgradeEffect.ConditionalBonusCondition
				|| baseEffect.ConditionalBonusEnemyStatus != upgradeEffect.ConditionalBonusEnemyStatus
				|| !string.Equals(baseEffect.ConditionalBonusPowerId ?? string.Empty, upgradeEffect.ConditionalBonusPowerId ?? string.Empty, StringComparison.Ordinal)
				|| baseEffect.ConditionalBonusEnemyIntent != upgradeEffect.ConditionalBonusEnemyIntent)
			{
				return true;
			}

			if (baseEffect.Kind == CardExtraEffectKind.ChooseOneEffectSource && upgradeEffect.Kind == CardExtraEffectKind.ChooseOneEffectSource)
			{
				if (!ChooseOneOptionsEqual(NormalizeChooseOneOption(baseEffect.ChooseOneOption1, baseEffect.SpecificCardId), NormalizeChooseOneOption(upgradeEffect.ChooseOneOption1, upgradeEffect.SpecificCardId))
					|| !ChooseOneOptionsEqual(NormalizeChooseOneOption(baseEffect.ChooseOneOption2, baseEffect.SpecificCardId2), NormalizeChooseOneOption(upgradeEffect.ChooseOneOption2, upgradeEffect.SpecificCardId2))
					|| !ChooseOneOptionsEqual(NormalizeChooseOneOption(baseEffect.ChooseOneOption3, baseEffect.SpecificCardId3), NormalizeChooseOneOption(upgradeEffect.ChooseOneOption3, upgradeEffect.SpecificCardId3)))
				{
					return true;
				}
			}

			if (baseEffect.BranchMode != upgradeEffect.BranchMode
				|| baseEffect.BranchConditionType != upgradeEffect.BranchConditionType
				|| baseEffect.BranchCondition != upgradeEffect.BranchCondition
				|| baseEffect.BranchEnemyStatus != upgradeEffect.BranchEnemyStatus
				|| !string.Equals(baseEffect.BranchPowerId ?? string.Empty, upgradeEffect.BranchPowerId ?? string.Empty, StringComparison.Ordinal)
				|| baseEffect.BranchEnemyIntent != upgradeEffect.BranchEnemyIntent
				|| baseEffect.BranchCountEvent != upgradeEffect.BranchCountEvent
				|| baseEffect.BranchCountWindow != upgradeEffect.BranchCountWindow
				|| baseEffect.BranchCountWindowInclusion != upgradeEffect.BranchCountWindowInclusion
				|| baseEffect.BranchBlockLostCountingMode != upgradeEffect.BranchBlockLostCountingMode
				|| baseEffect.BranchCountTurns != upgradeEffect.BranchCountTurns
				|| baseEffect.BranchCountCardPile != upgradeEffect.BranchCountCardPile
				|| baseEffect.BranchCountCardPool != upgradeEffect.BranchCountCardPool
				|| baseEffect.BranchCountCardType != upgradeEffect.BranchCountCardType
				|| baseEffect.BranchCountCardFilter != upgradeEffect.BranchCountCardFilter
				|| baseEffect.BranchCountCardMatchMode != upgradeEffect.BranchCountCardMatchMode
				|| !string.Equals(baseEffect.BranchCountMatchCardId ?? string.Empty, upgradeEffect.BranchCountMatchCardId ?? string.Empty, StringComparison.Ordinal)
				|| baseEffect.BranchCountMatchTagKind != upgradeEffect.BranchCountMatchTagKind
				|| baseEffect.BranchCountMatchVanillaTag != upgradeEffect.BranchCountMatchVanillaTag
				|| !string.Equals(baseEffect.BranchCountMatchCustomTag ?? string.Empty, upgradeEffect.BranchCountMatchCustomTag ?? string.Empty, StringComparison.Ordinal)
				|| !string.Equals(baseEffect.BranchCountMatchCustomKeyword ?? string.Empty, upgradeEffect.BranchCountMatchCustomKeyword ?? string.Empty, StringComparison.Ordinal)
				|| GetEffectiveBranchCountAggregationMode(baseEffect) != GetEffectiveBranchCountAggregationMode(upgradeEffect)
				|| baseEffect.BranchCountExcludeSourceCard != upgradeEffect.BranchCountExcludeSourceCard
				|| baseEffect.BranchCountOrbType != upgradeEffect.BranchCountOrbType
				|| baseEffect.BranchCountOrbSelection != upgradeEffect.BranchCountOrbSelection
				|| baseEffect.BranchCountEnemyStatus != upgradeEffect.BranchCountEnemyStatus
				|| !string.Equals(baseEffect.BranchCountPowerId ?? string.Empty, upgradeEffect.BranchCountPowerId ?? string.Empty, StringComparison.Ordinal)
				|| baseEffect.BranchCountEnemyIntent != upgradeEffect.BranchCountEnemyIntent
				|| baseEffect.BranchCountComparison != upgradeEffect.BranchCountComparison
				|| baseEffect.BranchCountConditionAmount != upgradeEffect.BranchCountConditionAmount
				|| !BranchEffectsMatch(baseEffect.BranchEffect, upgradeEffect.BranchEffect))
			{
				return true;
			}

			if (baseEffect.Kind == CardExtraEffectKind.TransformCards && upgradeEffect.Kind == CardExtraEffectKind.TransformCards)
			{
				return baseEffect.TransformMode != upgradeEffect.TransformMode
					|| baseEffect.SpecificCardUpgradeMode != upgradeEffect.SpecificCardUpgradeMode
					|| !string.Equals(baseEffect.SpecificCardId ?? string.Empty, upgradeEffect.SpecificCardId ?? string.Empty, StringComparison.Ordinal);
			}

			if (baseEffect.Kind == CardExtraEffectKind.StatefulTransform && upgradeEffect.Kind == CardExtraEffectKind.StatefulTransform)
			{
				return baseEffect.StatefulTransformMode != upgradeEffect.StatefulTransformMode
					|| baseEffect.StatefulTransformDuration != upgradeEffect.StatefulTransformDuration
					|| baseEffect.SpecificCardUpgradeMode != upgradeEffect.SpecificCardUpgradeMode
					|| (!secondaryNumericFieldsAreDeltas && baseEffect.StatefulTransformDurationAmount != upgradeEffect.StatefulTransformDurationAmount)
					|| !string.Equals(baseEffect.SpecificCardId ?? string.Empty, upgradeEffect.SpecificCardId ?? string.Empty, StringComparison.Ordinal);
			}
		}

		return false;
	}

	// Vanilla-parity surface (bug list #1, Thrash): vanilla cards read OTHER cards' damage/block via
	// DynamicVars ("CalculatedDamage"/"Damage"/"OstyDamage"/"Block" keys - see Thrash.OnPlay, Reap,
	// SeekerStrike) and treat cards without them as 0. Mirror the card's primary on-play
	// DealDamage/GainBlock rows into real vanilla vars; the mod's own text and execution never read
	// these, so they exist purely so vanilla interactions see created cards like real cards.
	internal static IEnumerable<DynamicVar> BuildVanillaParityVars(CardModel card)
	{
		List<DynamicVar> vars = new List<DynamicVar>();
		if (card == null)
		{
			return vars;
		}

		try
		{
			IReadOnlyList<CardExtraEffect> effects = GetEffectsForDescription(card, isUpgradePreview: false);
			bool hasDamage = false;
			bool hasBlock = false;
			foreach (CardExtraEffect effect in effects)
			{
				if (effect == null || effect.PayloadOnly || effect.AmountIsX || effect.Trigger != CardExtraEffectTrigger.OnPlay)
				{
					continue;
				}

				if (!hasDamage
					&& effect.Kind == CardExtraEffectKind.DealDamage
					&& effect.Target != CardExtraEffectTarget.Self
					&& effect.Amount > 0)
				{
					vars.Add(new DamageVar(effect.Amount, ValueProp.Move));
					hasDamage = true;
				}
				else if (!hasBlock
					&& effect.Kind == CardExtraEffectKind.GainBlock
					&& effect.Amount > 0)
				{
					vars.Add(new BlockVar(effect.Amount, ValueProp.Move));
					hasBlock = true;
				}

				if (hasDamage && hasBlock)
				{
					break;
				}
			}
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] BuildVanillaParityVars failed for {card?.Id}: {ex.Message}");
		}

		return vars;
	}

	private static readonly FieldInfo? CardDynamicVarsField =
		typeof(CardModel).GetField("_dynamicVars", BindingFlags.Instance | BindingFlags.NonPublic);

	// Drops the card's materialized DynamicVarSet so the next access re-derives it from CanonicalVars
	// (created cards derive live from the definition store; see BuildVanillaParityVars). Reflection
	// because the cache field is private and canonical instances are immutable - this is a cache
	// reset, not a semantic mutation.
	internal static void InvalidateVanillaParityVars(CardModel? card)
	{
		if (card is not CardEditorCreatedCardBase || CardDynamicVarsField == null)
		{
			return;
		}

		try
		{
			CardDynamicVarsField.SetValue(card, null);
		}
		catch
		{
		}
	}

	public static IReadOnlyList<CardExtraEffect> GetEffectsForDescription(CardModel card, bool isUpgradePreview)
	{
		if (card == null)
		{
			return Array.Empty<CardExtraEffect>();
		}

		if (!HasCardEditorDescriptionSurface(card))
		{
			return Array.Empty<CardExtraEffect>();
		}

		bool considerUpgrade = isUpgradePreview || card.GetSafeCurrentUpgradeLevel() > 0;
		int? upgradeApplicationCountOverride = GetDescriptionUpgradeApplicationCountOverride(card, isUpgradePreview);
		IReadOnlyList<CardExtraEffect> baseEffects = Array.Empty<CardExtraEffect>();

		if (CardEditorUiState.TryGetDraftOverride(card.Id, out CardOverride draft))
		{
			// Draft is authoritative — if the editor is open, don't fall back to stored even if the draft has no valid effects.
			baseEffects = GetEffectiveExtraEffects(card, draft, considerUpgrade, upgradeApplicationCountOverride);
			CardEditorUpgradeDeltaDebugLog.LogEffectiveEffectsResult("Description.GetEffectsForDescription.draft", card, baseEffects);
		}
		else if (CardEditorOverrides.TryGetEffectiveOverride(card, out CardOverride stored))
		{
			baseEffects = GetEffectiveExtraEffects(card, stored, considerUpgrade, upgradeApplicationCountOverride);
			CardEditorUpgradeDeltaDebugLog.LogEffectiveEffectsResult("Description.GetEffectsForDescription.stored", card, baseEffects);
		}

		CombatState? combatState = card.GetConcreteCombatState();
		IReadOnlyList<CardExtraEffect> temporaryEffects = GetActiveGrantedExtraEffects(combatState, card);

		if (temporaryEffects.Count == 0)
		{
			CardEditorUpgradeDeltaDebugLog.LogEffectiveEffectsResult("Description.GetEffectsForDescription.final", card, baseEffects);
			return baseEffects;
		}

		if (baseEffects.Count == 0)
		{
			CardEditorUpgradeDeltaDebugLog.LogEffectiveEffectsResult("Description.GetEffectsForDescription.temporaryOnly", card, temporaryEffects);
			return temporaryEffects;
		}

		List<CardExtraEffect> combined = new List<CardExtraEffect>(baseEffects.Count + temporaryEffects.Count);
		combined.AddRange(baseEffects);
		combined.AddRange(temporaryEffects);
		CardEditorUpgradeDeltaDebugLog.LogEffectiveEffectsResult("Description.GetEffectsForDescription.combined", card, combined);
		return combined;
	}

	private static int? GetDescriptionUpgradeApplicationCountOverride(CardModel? card, bool isUpgradePreview)
	{
		if (!isUpgradePreview || card == null)
		{
			return null;
		}

		// Upgrade previews are usually rendered from a preview clone that has already
		// been upgraded. Use that clone's level as the total application count.
		return Math.Max(1, card.GetSafeCurrentUpgradeLevel());
	}

	internal static bool HasCardEditorDescriptionSurface(CardModel? card, bool includeRuntime = true)
	{
		if (card == null)
		{
			return false;
		}

		if (card is CardEditorCreatedCardBase)
		{
			return true;
		}

		try
		{
			if (CardEditorUiState.TryGetDraftOverride(card.Id, out _))
			{
				return true;
			}
		}
		catch
		{
		}

		try
		{
			if (CardEditorOverrides.TryGetEffectiveOverride(card, out _))
			{
				return true;
			}
		}
		catch
		{
		}

		if (!includeRuntime || !card.IsMutableSafe())
		{
			return false;
		}

		return card.GetConcreteCombatState() != null;
	}

	private static IReadOnlyList<CardExtraEffect> GetActiveGrantedExtraEffects(CombatState? combatState, CardModel card)
	{
		if (combatState == null || card == null)
		{
			return Array.Empty<CardExtraEffect>();
		}

		IReadOnlyList<CardExtraEffect> temporaryEffects = CardEditorTemporaryExtraEffectController.GetEffects(combatState, card);
		IReadOnlyList<CardExtraEffect> auraEffects = CardEditorMatchingCardAuraController.GetVirtualExtraEffects(combatState, card);
		if (temporaryEffects.Count == 0)
		{
			return DistinctGrantedEffects(auraEffects);
		}
		if (auraEffects.Count == 0)
		{
			return DistinctGrantedEffects(temporaryEffects);
		}

		List<CardExtraEffect> combined = new List<CardExtraEffect>(temporaryEffects.Count + auraEffects.Count);
		AddGrantedEffectsDistinct(combined, temporaryEffects);
		AddGrantedEffectsDistinct(combined, auraEffects);
		return combined;
	}

	private static IReadOnlyList<CardExtraEffect> DistinctGrantedEffects(IReadOnlyList<CardExtraEffect> effects)
	{
		if (effects == null || effects.Count <= 1)
		{
			return effects ?? Array.Empty<CardExtraEffect>();
		}

		List<CardExtraEffect> distinct = new List<CardExtraEffect>(effects.Count);
		AddGrantedEffectsDistinct(distinct, effects);
		return distinct;
	}

	private static void AddGrantedEffectsDistinct(List<CardExtraEffect> destination, IReadOnlyList<CardExtraEffect> effects)
	{
		if (destination == null || effects == null)
		{
			return;
		}

		foreach (CardExtraEffect effect in effects)
		{
			if (effect == null || destination.Any(existing => IsDuplicateGrantedEffect(existing, effect)))
			{
				continue;
			}

			destination.Add(effect);
		}
	}

	internal static bool ShouldGlowGoldForConditionalEffects(CardModel card)
	{
		if (card == null)
		{
			return false;
		}

		CombatState? combatState = ResolveCardCombatState(card);
		Creature? ownerCreature = card.TryGetOwnerCreature();
		if (combatState == null || ownerCreature == null)
		{
			return false;
		}

		// Unmodified cards have an empty runtime-effects list, so the loop below could
		// never match; skip the CardPlay allocation and full effects rebuild for them.
		if (!CardEditorRuntimeCaches.HasAnyModSurface(card, combatState))
		{
			return false;
		}

		CardPlay playForConditions = GetPreviewConditionCardPlay(card);
		foreach (CardExtraEffect effect in GetRuntimeEffectsIncludingBorrowedSources(combatState, card))
		{
			if (ShouldGlowGoldForConditionalEffect(card, combatState, ownerCreature, playForConditions, effect))
			{
				return true;
			}
		}

		return false;
	}

	internal static bool TryGetConditionalGlowColor(CardModel card, out Color color)
	{
		color = default;
		if (card == null)
		{
			return false;
		}

		CombatState? combatState = ResolveCardCombatState(card);
		Creature? ownerCreature = card.TryGetOwnerCreature();
		if (combatState == null || ownerCreature == null)
		{
			return false;
		}

		// Unmodified cards have an empty runtime-effects list (see ShouldGlowGoldForConditionalEffects).
		if (!CardEditorRuntimeCaches.HasAnyModSurface(card, combatState))
		{
			return false;
		}

		CardPlay playForConditions = GetPreviewConditionCardPlay(card);
		foreach (CardExtraEffect effect in GetRuntimeEffectsIncludingBorrowedSources(combatState, card))
		{
			if (!IsActivePassiveBehavior(effect, CardExtraEffectKind.ConditionalGlow))
			{
				continue;
			}

			if (HasUsableBranchCondition(effect)
				&& !DoesBranchConditionPass(combatState, ownerCreature, playForConditions, effect))
			{
				continue;
			}

			color = ResolveConditionalGlowColor(effect);
			return true;
		}

		return false;
	}

	private static Color ResolveConditionalGlowColor(CardExtraEffect effect)
	{
		if (effect.GlowColorMode == CardExtraEffectGlowColorMode.Custom
			&& TryParseGlowColor(effect.GlowCustomColor, out Color customColor))
		{
			return customColor;
		}

		return effect.GlowColorMode switch
		{
			CardExtraEffectGlowColorMode.Gold => new Color(1f, 0.784f, 0f, 0.98f),
			CardExtraEffectGlowColorMode.Blue => new Color(0.1f, 0.55f, 1f, 0.98f),
			CardExtraEffectGlowColorMode.Green => new Color(0.2f, 0.9f, 0.42f, 0.98f),
			CardExtraEffectGlowColorMode.Purple => new Color(0.72f, 0.42f, 1f, 0.98f),
			_ => new Color(0.83f, 0f, 0.33f, 0.98f)
		};
	}

	private static bool TryParseGlowColor(string? text, out Color color)
	{
		color = default;
		string value = text?.Trim() ?? string.Empty;
		if (string.IsNullOrWhiteSpace(value))
		{
			return false;
		}

		if (value.StartsWith("#", StringComparison.Ordinal))
		{
			value = value[1..];
		}

		if (value.Length != 6 && value.Length != 8)
		{
			return false;
		}

		if (!uint.TryParse(value, NumberStyles.HexNumber, CultureInfo.InvariantCulture, out uint raw))
		{
			return false;
		}

		byte r;
		byte g;
		byte b;
		byte a;
		if (value.Length == 8)
		{
			r = (byte)((raw >> 24) & 0xFF);
			g = (byte)((raw >> 16) & 0xFF);
			b = (byte)((raw >> 8) & 0xFF);
			a = (byte)(raw & 0xFF);
		}
		else
		{
			r = (byte)((raw >> 16) & 0xFF);
			g = (byte)((raw >> 8) & 0xFF);
			b = (byte)(raw & 0xFF);
			a = 250;
		}

		color = new Color(r / 255f, g / 255f, b / 255f, Math.Clamp(a / 255f, 0.1f, 1f));
		return true;
	}

	private static CardPlay GetPreviewConditionCardPlay(CardModel card)
	{
		return GetPreviewConditionCardPlay(card, null);
	}

	private static CardPlay GetPreviewConditionCardPlay(CardModel card, Creature? target)
	{
		CardPlay? currentPlay = CardEditorCardPlayContext.Current;
		if (currentPlay != null
			&& ReferenceEquals(currentPlay.Card, card)
			&& (target == null || ReferenceEquals(currentPlay.Target, target)))
		{
			return currentPlay;
		}

		return new CardPlay
		{
			Card = card,
			Player = card.Owner,
			Target = target,
			ResultPile = card.TryGetPile()?.Type ?? PileType.None,
			Resources = new ResourceInfo
			{
				EnergySpent = 0,
				EnergyValue = 0,
				StarsSpent = 0,
				StarValue = 0
			},
			IsAutoPlay = true,
			PlayIndex = 0,
			PlayCount = 1
		};
	}

	private static bool ShouldGlowGoldForConditionalEffect(
		CardModel card,
		CombatState combatState,
		Creature ownerCreature,
		CardPlay playForConditions,
		CardExtraEffect effect)
	{
		if (card == null || effect == null)
		{
			return false;
		}

		if (effect.ScaleMode != CardExtraEffectScaleMode.None)
		{
			int count = GetHistoryCountMultiplier(combatState, ownerCreature, playForConditions, effect, card);
			if (DoesCountConditionPass(count, effect))
			{
				if (effect.ScaleMode == CardExtraEffectScaleMode.ConditionOnly)
				{
					return true;
				}

				if (effect.ScaleMode is CardExtraEffectScaleMode.PerHistoryCount or CardExtraEffectScaleMode.RepeatByCount)
				{
					if (effect.CountComparison != CardExtraEffectCountComparison.None)
					{
						return true;
					}

					if (count > 0)
					{
						return true;
					}
				}
			}
		}

		if (GetEffectiveConditionalBonusConditionType(effect) != CardExtraEffectBranchConditionType.None
			&& effect.ConditionalBonusAmount != 0
			&& DoesConditionalBonusPass(combatState, ownerCreature, playForConditions, effect))
		{
			return true;
		}

		if (effect.Kind == CardExtraEffectKind.PlayPermission
			&& HasUsableBranchCondition(effect)
			&& DoesBranchConditionPass(combatState, ownerCreature, playForConditions, effect))
		{
			return true;
		}

		return GetUsableBranchEffect(effect) != null
			&& DoesBranchConditionPass(combatState, ownerCreature, playForConditions, effect);
	}

	private static CombatState? ResolveCardCombatState(CardModel? card)
	{
		CombatState? concrete = card.GetConcreteCombatState();
		if (concrete != null)
		{
			return concrete;
		}

		// Canonical/library cards are immutable and throw if we probe combat ownership while rendering compendium text.
		if (card == null || !card.IsMutable)
		{
			return null;
		}

		return card.TryGetOwnerCreature().GetConcreteCombatState();
	}

	internal static bool HasActiveRuleModifier(CardExtraEffectKind kind, CardModel? card, Creature? target = null)
	{
		if (card == null)
		{
			return false;
		}

		CombatState? combatState = ResolveCardCombatState(card);
		if (combatState != null)
		{
			Creature? ownerCreature = card.TryGetOwnerCreature();
			return CardEditorIgnoreEffectHelpers.HasActiveIgnoreEffect(kind, card, ownerCreature, combatState, target);
		}

		// Version-cached prefilter (same contract as HasActiveIgnoreEffect's): skip the
		// full effects rebuild when the card provably has no row of this kind.
		ulong kindBit = CardEditorRuntimeCaches.MapKindToBit(kind);
		if (kindBit != 0UL && !CardEditorRuntimeCaches.CardMightHaveRuntimeEffectKind(null, card, kindBit))
		{
			return false;
		}

		return GetRuntimeEffectsIncludingBorrowedSources(null, card).Any(effect =>
			effect != null
			&& effect.Kind == kind
			&& !IsPowerEffect(effect)
			&& IsValidEffectAmount(effect.Kind, effect.Amount));
	}

	internal static bool TryGetRuleAdjustedTargetType(CardModel? card, TargetType currentTargetType, out TargetType adjustedTargetType)
	{
		adjustedTargetType = currentTargetType;
		if (card == null)
		{
			return false;
		}

		if (currentTargetType is not (TargetType.AnyEnemy or TargetType.RandomEnemy))
		{
			return false;
		}

		if (!HasActiveRuleModifier(CardExtraEffectKind.HitsAllEnemies, card))
		{
			return false;
		}

		adjustedTargetType = TargetType.AllEnemies;
		return true;
	}

	// Count/history-based glow conditions often change after another card resolves, so repaint the hand explicitly.
	private static void RefreshHandCardVisuals(Player? player)
	{
		CardPile? hand = player?.PlayerCombatState?.Hand;
		if (hand?.Cards == null)
		{
			return;
		}

		foreach (CardModel? handCard in hand.Cards)
		{
			if (handCard == null)
			{
				continue;
			}

			try
			{
				NCard? node = NCard.FindOnTable(handCard);
				if (node != null)
				{
					node.UpdateVisuals(node.DisplayingPile, CardPreviewMode.Normal);
				}
			}
			catch
			{
				// ignored
			}
		}
	}

	private static CardOverride CreateSelfScalingSnapshot(CardModel card)
	{
		CardOverride snapshot = CardEditorOverrides.TryGetEffectiveOverride(card, out CardOverride currentOverride)
			? CardEditorOverrides.Clone(currentOverride)
			: new CardOverride();
		CardUpgradeOverride? preservedUpgradeMetadata = PreserveSelfScalingUpgradeMetadata(card, snapshot.Upgrade);

		try
		{
			snapshot.DynamicVarBaseValues = card.DynamicVars.ToDictionary(kvp => kvp.Key, kvp => kvp.Value.BaseValue, StringComparer.Ordinal);
		}
		catch
		{
			snapshot.DynamicVarBaseValues ??= new Dictionary<string, decimal>(StringComparer.Ordinal);
		}

		bool considerUpgrade = card.GetSafeCurrentUpgradeLevel() > 0;
		IReadOnlyList<CardExtraEffect> currentEffects = Array.Empty<CardExtraEffect>();
		if (CardEditorUiState.TryGetDraftOverride(card.Id, out CardOverride draftOverride))
		{
			currentEffects = GetEffectiveExtraEffects(card, draftOverride, considerUpgrade);
		}
		else if (CardEditorOverrides.TryGetEffectiveOverride(card, out CardOverride effectiveOverride))
		{
			currentEffects = GetEffectiveExtraEffects(card, effectiveOverride, considerUpgrade);
		}

		snapshot.ExtraEffects = currentEffects.Select(CloneEffect).ToList();
		snapshot.Upgrade = preservedUpgradeMetadata;
		return snapshot;
	}

	private static bool HasSelfScalingPreservedUpgradeMetadata(CardUpgradeOverride? upgrade)
	{
		return upgrade != null
			&& (upgrade.EnergyCostDelta.HasValue
				|| upgrade.StarCostDelta.HasValue
				|| upgrade.ReplayCountDelta.HasValue
				|| upgrade.ModifiedBaseTextEnabled.HasValue
				|| !string.IsNullOrWhiteSpace(upgrade.ModifiedBaseText));
	}

	private static CardUpgradeOverride? PreserveSelfScalingUpgradeMetadata(CardModel card, CardUpgradeOverride? currentUpgrade)
	{
		CardUpgradeOverride? source = HasSelfScalingPreservedUpgradeMetadata(currentUpgrade)
			? currentUpgrade
			: null;

		if (source == null
			&& card.Id != ModelId.none
			&& CardEditorOverrides.TryGetEffectiveOverride(card.Id, out CardOverride storedOverride)
			&& HasSelfScalingPreservedUpgradeMetadata(storedOverride.Upgrade))
		{
			source = storedOverride.Upgrade;
		}

		if (source == null)
		{
			return null;
		}

		return new CardUpgradeOverride
		{
			EnergyCostDelta = source.EnergyCostDelta,
			StarCostDelta = source.StarCostDelta,
			ReplayCountDelta = source.ReplayCountDelta,
			ModifiedBaseTextEnabled = source.ModifiedBaseTextEnabled,
			ModifiedBaseText = source.ModifiedBaseText
		};
	}

	private static string? TryResolveSelfScalingDynamicVarKey(CardModel card, string? requestedKey)
	{
		if (card?.DynamicVars == null || string.IsNullOrWhiteSpace(requestedKey))
		{
			return null;
		}

		string trimmedKey = requestedKey.Trim();
		foreach (string key in card.DynamicVars.Keys)
		{
			if (string.Equals(key, trimmedKey, StringComparison.OrdinalIgnoreCase))
			{
				return key;
			}
		}

		return null;
	}

	private static bool TryApplySelfScalingDynamicVarMutation(CardModel card, CardOverride snapshot, string? requestedKey, int delta)
	{
		string? resolvedKey = TryResolveSelfScalingDynamicVarKey(card, requestedKey);
		if (string.IsNullOrWhiteSpace(resolvedKey))
		{
			return false;
		}

		snapshot.DynamicVarBaseValues ??= new Dictionary<string, decimal>(StringComparer.Ordinal);
		decimal currentValue = snapshot.DynamicVarBaseValues.TryGetValue(resolvedKey, out decimal existingValue)
			? existingValue
			: (card.DynamicVars.TryGetValue(resolvedKey, out var dynamicVar) ? dynamicVar.BaseValue : 0m);
		snapshot.DynamicVarBaseValues[resolvedKey] = currentValue + delta;
		return true;
	}

	private sealed class SelfScalingNumberMutation
	{
		public required Func<bool> Apply { get; init; }
	}

	internal sealed class SelfScalingMutationDiff
	{
		internal sealed class EffectFieldDelta
		{
			public string? EffectId { get; set; }
			public int Index { get; set; }
			public CardExtraEffectSelfScalingField Field { get; set; }
			public int Delta { get; set; }
			public int? BaseValue { get; set; }
		}

		public Dictionary<string, decimal> DynamicVarDeltas { get; } = new Dictionary<string, decimal>(StringComparer.Ordinal);
		public Dictionary<string, decimal> DynamicVarBaseValues { get; } = new Dictionary<string, decimal>(StringComparer.Ordinal);
		public List<EffectFieldDelta> EffectFieldDeltas { get; } = new List<EffectFieldDelta>();
		public int EnergyCostDelta { get; set; }
		public int? EnergyCostBaseValue { get; set; }
		public int StarCostDelta { get; set; }
		public int? StarCostBaseValue { get; set; }

		public bool IsEmpty => DynamicVarDeltas.Count == 0
			&& EffectFieldDeltas.Count == 0
			&& EnergyCostDelta == 0
			&& StarCostDelta == 0;
	}

	private static IReadOnlyList<string> GetSelfScalingDynamicVarFilterKeys(CardExtraEffectCountCardFilter filter)
	{
		return filter switch
		{
			CardExtraEffectCountCardFilter.DealDamage => new[] { "Damage", "CalculatedDamage", "ExtraDamage", "OstyDamage" },
			CardExtraEffectCountCardFilter.GainBlock => new[] { "Block" },
			CardExtraEffectCountCardFilter.DrawCards => new[] { "Cards" },
			CardExtraEffectCountCardFilter.GainEnergy => new[] { "Energy" },
			CardExtraEffectCountCardFilter.GainStars => new[] { "Stars" },
			CardExtraEffectCountCardFilter.Heal => new[] { "Heal" },
			CardExtraEffectCountCardFilter.LoseHp => new[] { "HpLoss" },
			CardExtraEffectCountCardFilter.Strength => new[] { "StrengthPower" },
			CardExtraEffectCountCardFilter.Dexterity => new[] { "DexterityPower" },
			CardExtraEffectCountCardFilter.Focus => new[] { "FocusPower" },
			CardExtraEffectCountCardFilter.Weak => new[] { "WeakPower" },
			CardExtraEffectCountCardFilter.Frail => new[] { "FrailPower" },
			CardExtraEffectCountCardFilter.Vulnerable => new[] { "VulnerablePower" },
			CardExtraEffectCountCardFilter.Poison => new[] { "PoisonPower" },
			CardExtraEffectCountCardFilter.Doom => new[] { "DoomPower" },
			CardExtraEffectCountCardFilter.Constrict => new[] { "ConstrictPower" },
			CardExtraEffectCountCardFilter.Artifact => new[] { "ArtifactPower" },
			CardExtraEffectCountCardFilter.Thorns => new[] { "ThornsPower" },
			CardExtraEffectCountCardFilter.Regen => new[] { "RegenPower" },
			CardExtraEffectCountCardFilter.Plating => new[] { "PlatingPower" },
			CardExtraEffectCountCardFilter.Intangible => new[] { "IntangiblePower" },
			CardExtraEffectCountCardFilter.Buffer => new[] { "BufferPower" },
			CardExtraEffectCountCardFilter.Vigor => new[] { "VigorPower" },
			CardExtraEffectCountCardFilter.Blur => new[] { "BlurPower" },
			CardExtraEffectCountCardFilter.Ritual => new[] { "RitualPower" },
			CardExtraEffectCountCardFilter.Summon => new[] { "Summon" },
			CardExtraEffectCountCardFilter.Forge => new[] { "Forge", "CalculatedForge" },
			_ => Array.Empty<string>()
		};
	}

	private static IEnumerable<string> EnumerateSelfScalingDynamicVarKeys(CardModel card, CardExtraEffectCountCardFilter filter)
	{
		if (card?.DynamicVars == null)
		{
			yield break;
		}

		if (filter == CardExtraEffectCountCardFilter.Any)
		{
			foreach (string key in card.DynamicVars.Keys.ToArray())
			{
				yield return key;
			}
			yield break;
		}

		HashSet<string> seen = new HashSet<string>(StringComparer.Ordinal);
		foreach (string requestedKey in GetSelfScalingDynamicVarFilterKeys(filter))
		{
			string? resolvedKey = TryResolveSelfScalingDynamicVarKey(card, requestedKey);
			if (!string.IsNullOrWhiteSpace(resolvedKey) && seen.Add(resolvedKey))
			{
				yield return resolvedKey;
			}
		}
	}

	private static bool DoesSelfScalingEffectRowMatchNumberFilter(CardExtraEffect candidate, CardExtraEffectCountCardFilter filter)
	{
		return filter == CardExtraEffectCountCardFilter.Any
			|| DoesEffectContributeToCountCardFilter(candidate, filter);
	}

	private static bool ShouldIncludeSelfScalingFieldForNumberFilter(CardExtraEffectSelfScalingField field, CardExtraEffectCountCardFilter filter, bool includeRepeats, bool repeatOnly)
	{
		if (repeatOnly)
		{
			return field == CardExtraEffectSelfScalingField.Repeat;
		}

		if (!includeRepeats && field == CardExtraEffectSelfScalingField.Repeat)
		{
			return false;
		}

		// Semantic filters such as Weak/Damage/Cost Effects should mutate the effect's primary number.
		// Otherwise they unexpectedly change helper values like thresholds and durations.
		if (filter != CardExtraEffectCountCardFilter.Any)
		{
			return field is CardExtraEffectSelfScalingField.Amount
				|| (includeRepeats && field == CardExtraEffectSelfScalingField.Repeat);
		}

		return true;
	}

	private static bool TryApplySelfScalingNumberMutations(
		CardModel card,
		CardOverride snapshot,
		CardExtraEffect effect,
		int delta,
		bool includeRepeats,
		bool includeCosts,
		bool repeatOnly,
		MegaCrit.Sts2.Core.Random.Rng? rng)
	{
		CardExtraEffectCountCardFilter filter = effect.SelfScalingNumberFilter;
		List<SelfScalingNumberMutation> mutations = new List<SelfScalingNumberMutation>();

		if (!repeatOnly)
		{
			foreach (string key in EnumerateSelfScalingDynamicVarKeys(card, filter))
			{
				string capturedKey = key;
				mutations.Add(new SelfScalingNumberMutation
				{
					Apply = () => TryApplySelfScalingDynamicVarMutation(card, snapshot, capturedKey, delta)
				});
			}
		}

		if (snapshot.ExtraEffects != null)
		{
			foreach (CardExtraEffect candidate in snapshot.ExtraEffects)
			{
				if (candidate == null
					|| IsSelfScalingKind(candidate.Kind)
					|| !DoesSelfScalingEffectRowMatchNumberFilter(candidate, filter))
				{
					continue;
				}

				foreach (CardExtraEffectSelfScalingField field in Enum.GetValues<CardExtraEffectSelfScalingField>())
				{
					if (!ShouldIncludeSelfScalingFieldForNumberFilter(field, filter, includeRepeats, repeatOnly)
						|| !SupportsSelfScalingEffectRowField(candidate, field))
					{
						continue;
					}

					CardExtraEffect capturedCandidate = candidate;
					CardExtraEffectSelfScalingField capturedField = field;
					mutations.Add(new SelfScalingNumberMutation
					{
						Apply = () => TryApplySelfScalingEffectRowMutation(capturedCandidate, capturedField, delta)
					});
				}
			}
		}

		if (includeCosts && filter == CardExtraEffectCountCardFilter.Any && !repeatOnly)
		{
			mutations.Add(new SelfScalingNumberMutation
			{
				Apply = () => TryApplySelfScalingEnergyCostMutation(card, snapshot, delta)
			});
			mutations.Add(new SelfScalingNumberMutation
			{
				Apply = () => TryApplySelfScalingStarCostMutation(card, snapshot, delta)
			});
		}

		if (mutations.Count == 0)
		{
			return false;
		}

		switch (effect.SelfScalingNumberSelectionMode)
		{
			case CardExtraEffectSelfScalingNumberSelectionMode.First:
				return mutations[0].Apply();
			case CardExtraEffectSelfScalingNumberSelectionMode.Random:
			{
				int index = rng == null ? 0 : rng.NextInt(mutations.Count);
				return mutations[index].Apply();
			}
			default:
			{
				bool mutated = false;
				foreach (SelfScalingNumberMutation mutation in mutations)
				{
					mutated |= mutation.Apply();
				}
				return mutated;
			}
		}
	}

	private static bool TryApplySelfScalingEnergyCostMutation(CardModel card, CardOverride snapshot, int delta)
	{
		if (card == null || snapshot == null || delta == 0)
		{
			return false;
		}
		if (snapshot.EnergyCostX == true || card.EnergyCost.CostsX)
		{
			return false;
		}

		int currentBaseCost;
		try
		{
			currentBaseCost = snapshot.EnergyCost ?? card.EnergyCost.GetWithModifiers(CostModifiers.None);
		}
		catch
		{
			return false;
		}

		if (currentBaseCost < 0)
		{
			return false;
		}

		snapshot.EnergyCostX = false;
		snapshot.EnergyCost = Math.Clamp(currentBaseCost + delta, 0, 99);
		return true;
	}

	private static bool TryApplySelfScalingStarCostMutation(CardModel card, CardOverride snapshot, int delta)
	{
		if (card == null || snapshot == null || delta == 0)
		{
			return false;
		}
		if (snapshot.StarCostX == true || card.HasStarCostX)
		{
			return false;
		}

		int currentBaseCost;
		try
		{
			currentBaseCost = snapshot.StarCost ?? card.BaseStarCost;
		}
		catch
		{
			return false;
		}

		if (currentBaseCost < 0)
		{
			return false;
		}

		snapshot.StarCostX = false;
		snapshot.StarCost = Math.Clamp(currentBaseCost + delta, 0, 99);
		return true;
	}

	private static int GetSelfScalingDelta(CardExtraEffect effect, int resolvedAmount)
	{
		if (effect == null || resolvedAmount == 0)
		{
			return 0;
		}

		return effect.SelfScalingOperation == CardExtraEffectSelfScalingOperation.Decrease
			? -Math.Abs(resolvedAmount)
			: Math.Abs(resolvedAmount);
	}

	private static bool TryResolveSelfScalingDelta(
		CombatState combatState,
		Creature ownerCreature,
		CardPlay cardPlay,
		CardExtraEffect effect,
		int triggerEventAmount,
		out int delta)
	{
		delta = 0;
		if (combatState == null
			|| ownerCreature == null
			|| cardPlay == null
			|| effect == null
			|| (!IsSelfScalingKind(effect.Kind) && effect.Kind != CardExtraEffectKind.LinkedCardAction))
		{
			return false;
		}

		int amount = ResolveConfiguredEffectAmount(combatState, ownerCreature, cardPlay, effect);
		amount = ApplyConditionalBonusAmount(combatState, ownerCreature, cardPlay, effect, amount);
		if (amount <= 0)
		{
			return false;
		}

		if (effect.ScaleMode != CardExtraEffectScaleMode.None)
		{
			int multiplier = GetHistoryCountMultiplier(combatState, ownerCreature, cardPlay, effect);
			if (!DoesCountConditionPass(multiplier, effect))
			{
				return false;
			}

			if (effect.ScaleMode == CardExtraEffectScaleMode.PerHistoryCount)
			{
				int scalingMultiplier = ResolveHistoryScalingMultiplier(effect, multiplier);
				if (scalingMultiplier <= 0 && !effect.HistoryScalingIncludesBase)
				{
					return false;
				}

				long scaled = (long)amount * scalingMultiplier;
				long total = effect.HistoryScalingIncludesBase
					? (long)ResolveHistoryScalingBaseAmount(effect, amount) + scaled
					: scaled;
				amount = total >= int.MaxValue ? int.MaxValue : total <= 0 ? 0 : (int)total;
				if (amount <= 0)
				{
					return false;
				}
			}
		}

		if (effect.PowerTriggerUsesEventAmount)
		{
			int eventAmount = Math.Max(0, triggerEventAmount);
			if (eventAmount <= 0)
			{
				return false;
			}

			long scaledByTriggerAmount = (long)amount * eventAmount;
			if (scaledByTriggerAmount >= int.MaxValue)
			{
				amount = int.MaxValue;
			}
			else if (scaledByTriggerAmount <= 0)
			{
				return false;
			}
			else
			{
				amount = (int)scaledByTriggerAmount;
			}
		}

		int repeats = ResolveRepeatCount(cardPlay, effect);
		if (repeats <= 0)
		{
			return false;
		}
		if (repeats != 1)
		{
			long repeatedAmount = (long)amount * repeats;
			amount = repeatedAmount >= int.MaxValue ? int.MaxValue : repeatedAmount <= 0 ? 0 : (int)repeatedAmount;
			if (amount <= 0)
			{
				return false;
			}
		}

		delta = GetSelfScalingDelta(effect, amount);
		return delta != 0;
	}

	internal static CardModel? ResolveSelfScalingMutationTargetCard(CardModel? card)
	{
		if (card == null)
		{
			return null;
		}

		try
		{
			CardModel? cursor = card;
			for (int i = 0; i < 8 && cursor != null; i++)
			{
				if (!cursor.IsClone || cursor.CloneOf == null)
				{
					return cursor;
				}

				// Self-scaling often fires from a transient play clone. Walk back to the live mutable combat card
				// so the mutation sticks to the card that actually remains in the combat piles.
				if (!cursor.CloneOf.IsMutable)
				{
					return cursor;
				}

				cursor = cursor.CloneOf;
			}
		}
		catch
		{
			// ignored
		}

		return card;
	}

	private static bool TryApplySelfScalingMutationToSnapshot(
		CardModel card,
		CardOverride snapshot,
		CardExtraEffect effect,
		int delta,
		MegaCrit.Sts2.Core.Random.Rng? rng)
	{
		if (card == null || snapshot == null || effect == null || delta == 0)
		{
			return false;
		}

		bool mutated = false;

		switch (effect.SelfScalingTargetType)
		{
			case CardExtraEffectSelfScalingTargetType.BaseDamage:
			case CardExtraEffectSelfScalingTargetType.BaseBlock:
			{
				string requestedKey = effect.SelfScalingTargetType == CardExtraEffectSelfScalingTargetType.BaseDamage ? "Damage" : "Block";
				mutated = TryApplySelfScalingDynamicVarMutation(card, snapshot, requestedKey, delta);
				break;
			}
			case CardExtraEffectSelfScalingTargetType.DynamicVar:
			{
				mutated = TryApplySelfScalingDynamicVarMutation(card, snapshot, effect.SelfScalingDynamicVarKey, delta);
				break;
			}
			case CardExtraEffectSelfScalingTargetType.EffectRowAmount:
			{
				if (!string.IsNullOrWhiteSpace(effect.SelfScalingTargetEffectId) && snapshot.ExtraEffects != null)
				{
					foreach (CardExtraEffect candidate in snapshot.ExtraEffects)
					{
						if (candidate == null
							|| string.IsNullOrWhiteSpace(candidate.EffectId)
							|| !string.Equals(candidate.EffectId, effect.SelfScalingTargetEffectId, StringComparison.Ordinal))
						{
							continue;
						}

						if (TryApplySelfScalingEffectRowMutation(candidate, effect.SelfScalingField, delta))
						{
							mutated = true;
						}
						return mutated;
					}
				}
				break;
			}
			case CardExtraEffectSelfScalingTargetType.AllNumbers:
			{
				mutated = TryApplySelfScalingNumberMutations(card, snapshot, effect, delta, includeRepeats: false, includeCosts: false, repeatOnly: false, rng);
				break;
			}
			case CardExtraEffectSelfScalingTargetType.AllNumbersIncludingRepeats:
			{
				mutated = TryApplySelfScalingNumberMutations(card, snapshot, effect, delta, includeRepeats: true, includeCosts: false, repeatOnly: false, rng);
				break;
			}
			case CardExtraEffectSelfScalingTargetType.EnergyCost:
			{
				mutated = TryApplySelfScalingEnergyCostMutation(card, snapshot, delta);
				break;
			}
			case CardExtraEffectSelfScalingTargetType.StarCost:
			{
				mutated = TryApplySelfScalingStarCostMutation(card, snapshot, delta);
				break;
			}
			case CardExtraEffectSelfScalingTargetType.AllGameplayNumbers:
			{
				mutated = TryApplySelfScalingNumberMutations(card, snapshot, effect, delta, includeRepeats: false, includeCosts: true, repeatOnly: false, rng);
				break;
			}
			case CardExtraEffectSelfScalingTargetType.AllGameplayNumbersIncludingRepeats:
			{
				mutated = TryApplySelfScalingNumberMutations(card, snapshot, effect, delta, includeRepeats: true, includeCosts: true, repeatOnly: false, rng);
				break;
			}
			case CardExtraEffectSelfScalingTargetType.RepeatCounts:
			{
				mutated = TryApplySelfScalingNumberMutations(card, snapshot, effect, delta, includeRepeats: true, includeCosts: false, repeatOnly: true, rng);
				break;
			}
		}

		return mutated;
	}

	private static CardExtraEffectCardCostsLessDuration GetEffectiveSelfScalingDuration(CardExtraEffect effect)
	{
		if (effect == null)
		{
			return CardExtraEffectCardCostsLessDuration.ThisCombat;
		}
		if (effect.Kind is CardExtraEffectKind.PersistentSelfScaling or CardExtraEffectKind.PersistentTargetCardMutation)
		{
			return CardExtraEffectCardCostsLessDuration.Permanent;
		}

		// Older presets stored Self Scaling before the duration dropdown existed. The default enum value is
		// Permanent, but the old non-persistent behavior was "this combat", so preserve that compatibility.
		return effect.CardCostsLessDuration == CardExtraEffectCardCostsLessDuration.Permanent
			? CardExtraEffectCardCostsLessDuration.ThisCombat
			: effect.CardCostsLessDuration;
	}

	private static bool TryGetSnapshotEnergyCost(CardModel card, CardOverride snapshot, out int cost)
	{
		cost = 0;
		if (card == null || snapshot == null)
		{
			return false;
		}
		if (snapshot.EnergyCost.HasValue)
		{
			cost = snapshot.EnergyCost.Value;
			return cost >= 0;
		}
		try
		{
			if (snapshot.EnergyCostX == true || card.EnergyCost.CostsX)
			{
				return false;
			}
			cost = card.EnergyCost.GetWithModifiers(CostModifiers.None);
			return cost >= 0;
		}
		catch
		{
			return false;
		}
	}

	private static bool TryGetSnapshotStarCost(CardModel card, CardOverride snapshot, out int cost)
	{
		cost = 0;
		if (card == null || snapshot == null)
		{
			return false;
		}
		if (snapshot.StarCost.HasValue)
		{
			cost = snapshot.StarCost.Value;
			return cost >= 0;
		}
		try
		{
			if (snapshot.StarCostX == true || card.HasStarCostX)
			{
				return false;
			}
			cost = card.BaseStarCost;
			return cost >= 0;
		}
		catch
		{
			return false;
		}
	}

	private static bool TryGetSelfScalingEffectFieldValue(CardExtraEffect effect, CardExtraEffectSelfScalingField field, out int value)
	{
		value = 0;
		if (effect == null || !SupportsSelfScalingEffectRowField(effect, field))
		{
			return false;
		}

		value = field switch
		{
			CardExtraEffectSelfScalingField.Amount => effect.Amount,
			CardExtraEffectSelfScalingField.Repeat => effect.RepeatCount,
			CardExtraEffectSelfScalingField.SecondaryAmount => effect.ConditionalBonusAmount,
			CardExtraEffectSelfScalingField.Threshold => effect.CountConditionAmount,
			CardExtraEffectSelfScalingField.Duration => GetSelfScalingDurationFieldValue(effect),
			_ => 0
		};
		return true;
	}

	private static int GetSelfScalingDurationFieldValue(CardExtraEffect effect)
	{
		if (effect == null)
		{
			return 0;
		}
		if (IsPowerEffect(effect) && effect.TriggerMaxTurns > 0)
		{
			return effect.TriggerMaxTurns;
		}
		if (effect.CardGrantDuration == CardExtraEffectCardGrantDuration.Turns)
		{
			return effect.CardGrantTurns;
		}
		if (effect.EnchantmentDuration == CardExtraEffectEnchantmentDuration.Turns)
		{
			return effect.EnchantmentTurns;
		}
		if (effect.CardCostsLessDuration == CardExtraEffectCardCostsLessDuration.Turns)
		{
			return effect.CardCostsLessTurns;
		}
		if (effect.CreatedCardsCostDuration == CardCreatedCardsCostDuration.Turns)
		{
			return effect.CreatedCardsCostTurns;
		}
		return 0;
	}

	private static CardExtraEffect? FindMatchingEffectForDiff(IReadOnlyList<CardExtraEffect>? effects, string? effectId, int index)
	{
		if (effects == null || effects.Count == 0)
		{
			return null;
		}
		if (!string.IsNullOrWhiteSpace(effectId))
		{
			foreach (CardExtraEffect effect in effects)
			{
				if (effect != null && string.Equals(effect.EffectId, effectId, StringComparison.Ordinal))
				{
					return effect;
				}
			}
		}
		return index >= 0 && index < effects.Count ? effects[index] : null;
	}

	private static SelfScalingMutationDiff BuildSelfScalingMutationDiff(CardModel card, CardOverride before, CardOverride after)
	{
		SelfScalingMutationDiff diff = new SelfScalingMutationDiff();

		HashSet<string> dynamicKeys = new HashSet<string>(StringComparer.Ordinal);
		if (before.DynamicVarBaseValues != null)
		{
			foreach (string key in before.DynamicVarBaseValues.Keys)
			{
				dynamicKeys.Add(key);
			}
		}
		if (after.DynamicVarBaseValues != null)
		{
			foreach (string key in after.DynamicVarBaseValues.Keys)
			{
				dynamicKeys.Add(key);
			}
		}
		foreach (string key in dynamicKeys)
		{
			decimal beforeValue = before.DynamicVarBaseValues != null && before.DynamicVarBaseValues.TryGetValue(key, out decimal b) ? b : 0m;
			decimal afterValue = after.DynamicVarBaseValues != null && after.DynamicVarBaseValues.TryGetValue(key, out decimal a) ? a : beforeValue;
			decimal delta = afterValue - beforeValue;
			if (delta != 0m)
			{
				diff.DynamicVarDeltas[key] = delta;
				diff.DynamicVarBaseValues[key] = beforeValue;
			}
		}

		List<CardExtraEffect> beforeEffects = before.ExtraEffects ?? new List<CardExtraEffect>();
		List<CardExtraEffect> afterEffects = after.ExtraEffects ?? new List<CardExtraEffect>();
		for (int i = 0; i < afterEffects.Count; i++)
		{
			CardExtraEffect afterEffect = afterEffects[i];
			if (afterEffect == null)
			{
				continue;
			}
			string? effectId = string.IsNullOrWhiteSpace(afterEffect.EffectId) ? null : afterEffect.EffectId;
			CardExtraEffect? beforeEffect = FindMatchingEffectForDiff(beforeEffects, effectId, i);
			if (beforeEffect == null)
			{
				continue;
			}

			foreach (CardExtraEffectSelfScalingField field in Enum.GetValues<CardExtraEffectSelfScalingField>())
			{
				if (!TryGetSelfScalingEffectFieldValue(beforeEffect, field, out int beforeValue)
					|| !TryGetSelfScalingEffectFieldValue(afterEffect, field, out int afterValue))
				{
					continue;
				}
				int delta = afterValue - beforeValue;
				if (delta != 0)
				{
					diff.EffectFieldDeltas.Add(new SelfScalingMutationDiff.EffectFieldDelta
					{
						EffectId = effectId,
						Index = i,
						Field = field,
						Delta = delta,
						BaseValue = beforeValue
					});
				}
			}
		}

		if (TryGetSnapshotEnergyCost(card, before, out int beforeEnergy)
			&& TryGetSnapshotEnergyCost(card, after, out int afterEnergy)
			&& beforeEnergy != afterEnergy)
		{
			diff.EnergyCostDelta = afterEnergy - beforeEnergy;
			diff.EnergyCostBaseValue = beforeEnergy;
		}
		if (TryGetSnapshotStarCost(card, before, out int beforeStar)
			&& TryGetSnapshotStarCost(card, after, out int afterStar)
			&& beforeStar != afterStar)
		{
			diff.StarCostDelta = afterStar - beforeStar;
			diff.StarCostBaseValue = beforeStar;
		}

		return diff;
	}

	internal static SelfScalingMutationDiff BuildSelfScalingMutationDiffFromCurrentCard(CardModel card, CardOverride after)
	{
		if (card == null || after == null)
		{
			return new SelfScalingMutationDiff();
		}

		return BuildSelfScalingMutationDiff(card, CreateSelfScalingSnapshot(card), after);
	}

	internal static void AccumulateSelfScalingMutationDiff(SelfScalingMutationDiff target, SelfScalingMutationDiff delta)
	{
		if (target == null || delta == null || delta.IsEmpty)
		{
			return;
		}

		foreach ((string key, decimal amount) in delta.DynamicVarDeltas)
		{
			if (!target.DynamicVarBaseValues.ContainsKey(key) && delta.DynamicVarBaseValues.TryGetValue(key, out decimal baseValue))
			{
				target.DynamicVarBaseValues[key] = baseValue;
			}

			target.DynamicVarDeltas.TryGetValue(key, out decimal existing);
			decimal combined = existing + amount;
			if (combined == 0m)
			{
				target.DynamicVarDeltas.Remove(key);
				target.DynamicVarBaseValues.Remove(key);
			}
			else
			{
				target.DynamicVarDeltas[key] = combined;
			}
		}

		foreach (SelfScalingMutationDiff.EffectFieldDelta incoming in delta.EffectFieldDeltas)
		{
			if (incoming == null || incoming.Delta == 0)
			{
				continue;
			}

			SelfScalingMutationDiff.EffectFieldDelta? existing = target.EffectFieldDeltas.FirstOrDefault(candidate =>
				candidate != null
				&& candidate.Index == incoming.Index
				&& candidate.Field == incoming.Field
				&& string.Equals(candidate.EffectId ?? string.Empty, incoming.EffectId ?? string.Empty, StringComparison.Ordinal));
			if (existing == null)
			{
				target.EffectFieldDeltas.Add(new SelfScalingMutationDiff.EffectFieldDelta
				{
					EffectId = incoming.EffectId,
					Index = incoming.Index,
					Field = incoming.Field,
					Delta = incoming.Delta,
					BaseValue = incoming.BaseValue
				});
				continue;
			}

			existing.Delta += incoming.Delta;
			existing.BaseValue ??= incoming.BaseValue;
			if (existing.Delta == 0)
			{
				target.EffectFieldDeltas.Remove(existing);
			}
		}

		if (delta.EnergyCostDelta != 0)
		{
			target.EnergyCostBaseValue ??= delta.EnergyCostBaseValue;
			target.EnergyCostDelta += delta.EnergyCostDelta;
			if (target.EnergyCostDelta == 0)
			{
				target.EnergyCostBaseValue = null;
			}
		}

		if (delta.StarCostDelta != 0)
		{
			target.StarCostBaseValue ??= delta.StarCostBaseValue;
			target.StarCostDelta += delta.StarCostDelta;
			if (target.StarCostDelta == 0)
			{
				target.StarCostBaseValue = null;
			}
		}
	}

	internal static bool ApplyTemporarySelfScalingDiff(CardModel? card, SelfScalingMutationDiff diff, int direction)
	{
		if (card == null || diff == null || diff.IsEmpty || direction == 0)
		{
			return false;
		}

		CardModel targetCard = ResolveSelfScalingMutationTargetCard(card) ?? card;
		if (!targetCard.IsMutable)
		{
			return false;
		}

		CardOverride snapshot = CreateSelfScalingSnapshot(targetCard);
		bool mutated = false;

		foreach ((string key, decimal delta) in diff.DynamicVarDeltas)
		{
			snapshot.DynamicVarBaseValues ??= new Dictionary<string, decimal>(StringComparer.Ordinal);
			decimal currentValue = snapshot.DynamicVarBaseValues.TryGetValue(key, out decimal existingValue)
				? existingValue
				: (targetCard.DynamicVars.TryGetValue(key, out var dynamicVar) ? dynamicVar.BaseValue : 0m);
			snapshot.DynamicVarBaseValues[key] = currentValue + (delta * direction);
			mutated = true;
		}

		if (snapshot.ExtraEffects != null)
		{
			foreach (SelfScalingMutationDiff.EffectFieldDelta effectDelta in diff.EffectFieldDeltas)
			{
				CardExtraEffect? targetEffect = FindMatchingEffectForDiff(snapshot.ExtraEffects, effectDelta.EffectId, effectDelta.Index);
				if (targetEffect != null && TryApplySelfScalingEffectRowMutation(targetEffect, effectDelta.Field, effectDelta.Delta * direction))
				{
					mutated = true;
				}
			}
		}

		if (diff.EnergyCostDelta != 0 && TryApplySelfScalingEnergyCostMutation(targetCard, snapshot, diff.EnergyCostDelta * direction))
		{
			mutated = true;
		}
		if (diff.StarCostDelta != 0 && TryApplySelfScalingStarCostMutation(targetCard, snapshot, diff.StarCostDelta * direction))
		{
			mutated = true;
		}
		if (!mutated)
		{
			return false;
		}

		CardEditorOverrides.ApplyOverrideToCard(targetCard, snapshot);
		RecalculateSelfScalingCard(targetCard);
		NotifySelfScalingCostChanged(targetCard, CardExtraEffectSelfScalingTargetType.AllGameplayNumbersIncludingRepeats);
		return true;
	}

	internal static bool ApplyPersistentSelfScalingDiff(CardModel? card, SelfScalingMutationDiff diff)
		=> ApplyPersistentSelfScalingDiffCore(card, diff, resolveTargetCard: true);

	internal static bool ApplyPersistentSelfScalingRuntimeDiff(CardModel? card, SelfScalingMutationDiff diff)
		=> ApplyPersistentSelfScalingDiffCore(card, diff, resolveTargetCard: false);

	private static bool ApplyPersistentSelfScalingDiffCore(CardModel? card, SelfScalingMutationDiff diff, bool resolveTargetCard)
	{
		if (card == null || diff == null || diff.IsEmpty)
		{
			return false;
		}

		using IDisposable restoreScope = CardEditorRunSelfScalingState.PushRestoreSuppression();
		CardModel targetCard = resolveTargetCard
			? ResolveSelfScalingMutationTargetCard(card) ?? card
			: card;
		if (!targetCard.IsMutable)
		{
			return false;
		}

		CardOverride snapshot = CreateSelfScalingSnapshot(targetCard);
		bool mutated = false;

		foreach ((string key, decimal delta) in diff.DynamicVarDeltas)
		{
			snapshot.DynamicVarBaseValues ??= new Dictionary<string, decimal>(StringComparer.Ordinal);
			decimal currentValue = snapshot.DynamicVarBaseValues.TryGetValue(key, out decimal existingValue)
				? existingValue
				: (targetCard.DynamicVars.TryGetValue(key, out var dynamicVar) ? dynamicVar.BaseValue : 0m);
			if (diff.DynamicVarBaseValues.TryGetValue(key, out decimal baseValue) && currentValue != baseValue)
			{
				continue;
			}

			snapshot.DynamicVarBaseValues[key] = currentValue + delta;
			mutated = true;
		}

		if (snapshot.ExtraEffects != null)
		{
			foreach (SelfScalingMutationDiff.EffectFieldDelta effectDelta in diff.EffectFieldDeltas)
			{
				CardExtraEffect? targetEffect = FindMatchingEffectForDiff(snapshot.ExtraEffects, effectDelta.EffectId, effectDelta.Index);
				if (targetEffect == null)
				{
					continue;
				}
				if (effectDelta.BaseValue.HasValue
					&& TryGetSelfScalingEffectFieldValue(targetEffect, effectDelta.Field, out int currentValue)
					&& currentValue != effectDelta.BaseValue.Value)
				{
					continue;
				}
				if (TryApplySelfScalingEffectRowMutation(targetEffect, effectDelta.Field, effectDelta.Delta))
				{
					mutated = true;
				}
			}
		}

		if (diff.EnergyCostDelta != 0
			&& TryGetSnapshotEnergyCost(targetCard, snapshot, out int currentEnergy)
			&& (!diff.EnergyCostBaseValue.HasValue || currentEnergy == diff.EnergyCostBaseValue.Value)
			&& TryApplySelfScalingEnergyCostMutation(targetCard, snapshot, diff.EnergyCostDelta))
		{
			mutated = true;
		}

		if (diff.StarCostDelta != 0
			&& TryGetSnapshotStarCost(targetCard, snapshot, out int currentStar)
			&& (!diff.StarCostBaseValue.HasValue || currentStar == diff.StarCostBaseValue.Value)
			&& TryApplySelfScalingStarCostMutation(targetCard, snapshot, diff.StarCostDelta))
		{
			mutated = true;
		}

		if (!mutated)
		{
			return false;
		}

		CardEditorOverrides.ApplyOverrideToCard(targetCard, snapshot);
		RecalculateSelfScalingCard(targetCard);
		NotifySelfScalingCostChanged(targetCard, CardExtraEffectSelfScalingTargetType.AllGameplayNumbersIncludingRepeats);
		return true;
	}

	private static void RecalculateSelfScalingCard(CardModel card)
	{
		try
		{
			card.DynamicVars.RecalculateForUpgradeOrEnchant();
		}
		catch
		{
		}

		try
		{
			card.Owner?.PlayerCombatState?.RecalculateCardValues();
		}
		catch
		{
		}

		try
		{
			NCard? node = NCard.FindOnTable(card);
			if (node != null)
			{
				if (node.GetParent() is NHandCardHolder handHolder)
				{
					handHolder.UpdateCard();
					return;
				}

				node.UpdateVisuals(node.DisplayingPile, CardPreviewMode.Normal);
			}
		}
		catch
		{
		}
	}

	private static bool ApplySelfScalingMutationToCard(CardModel? card, CardExtraEffect effect, int delta)
	{
		if (card == null || effect == null || !card.IsMutable || delta == 0)
		{
			return false;
		}

		CardModel targetCard = ResolveSelfScalingMutationTargetCard(card) ?? card;
		if (!targetCard.IsMutable)
		{
			return false;
		}

		CardOverride snapshot = CreateSelfScalingSnapshot(targetCard);
		MegaCrit.Sts2.Core.Random.Rng? rng = card.Owner?.RunState?.Rng?.CombatCardSelection;
		if (!TryApplySelfScalingMutationToSnapshot(targetCard, snapshot, effect, delta, rng))
		{
			return false;
		}

		CardEditorOverrides.ApplyOverrideToCard(targetCard, snapshot);
		RecalculateSelfScalingCard(targetCard);
		NotifySelfScalingCostChanged(targetCard, effect.SelfScalingTargetType);

		if (!ReferenceEquals(card, targetCard) && card.IsMutable)
		{
			CardOverride runtimeSnapshot = CreateSelfScalingSnapshot(card);
			if (TryApplySelfScalingMutationToSnapshot(card, runtimeSnapshot, effect, delta, rng))
			{
				CardEditorOverrides.ApplyOverrideToCard(card, runtimeSnapshot);
				RecalculateSelfScalingCard(card);
				NotifySelfScalingCostChanged(card, effect.SelfScalingTargetType);
			}
		}

		return true;
	}

	private static bool ApplyTimedSelfScalingMutationToCard(CombatState combatState, CardModel? card, CardExtraEffect effect, int delta)
	{
		if (combatState == null || card == null || effect == null || !card.IsMutable || delta == 0)
		{
			return false;
		}

		CardModel targetCard = ResolveSelfScalingMutationTargetCard(card) ?? card;
		if (!targetCard.IsMutable)
		{
			return false;
		}

		CardOverride beforeSnapshot = CreateSelfScalingSnapshot(targetCard);
		CardOverride afterSnapshot = CardEditorOverrides.Clone(beforeSnapshot);
		MegaCrit.Sts2.Core.Random.Rng? rng = card.Owner?.RunState?.Rng?.CombatCardSelection;
		if (!TryApplySelfScalingMutationToSnapshot(targetCard, afterSnapshot, effect, delta, rng))
		{
			return false;
		}

		SelfScalingMutationDiff diff = BuildSelfScalingMutationDiff(targetCard, beforeSnapshot, afterSnapshot);
		if (diff.IsEmpty)
		{
			return false;
		}

		CardEditorOverrides.ApplyOverrideToCard(targetCard, afterSnapshot);
		RecalculateSelfScalingCard(targetCard);
		NotifySelfScalingCostChanged(targetCard, effect.SelfScalingTargetType);

		CardEditorTemporarySelfScalingController.Grant(
			combatState,
			targetCard,
			diff,
			GetEffectiveSelfScalingDuration(effect),
			effect.CardCostsLessTurns);
		return true;
	}

	private static bool IsCurrentPlayingRuntimeMutationTarget(CardModel? targetCard, CardModel? currentPlayingCard)
	{
		if (targetCard == null || currentPlayingCard == null)
		{
			return false;
		}
		if (ReferenceEquals(targetCard, currentPlayingCard))
		{
			return true;
		}

		CardModel? resolvedCurrent = ResolveSelfScalingMutationTargetCard(currentPlayingCard);
		if (ReferenceEquals(targetCard, resolvedCurrent))
		{
			return true;
		}

		try
		{
			CardModel? cursor = currentPlayingCard;
			for (int i = 0; i < 8 && cursor != null; i++)
			{
				if (ReferenceEquals(targetCard, cursor))
				{
					return true;
				}
				cursor = cursor.CloneOf;
			}
		}
		catch
		{
			// ignored
		}

		return false;
	}

	private static bool ApplyPersistentSelfScalingMutationToCard(CombatState? combatState, CardModel? card, CardExtraEffect effect, int delta, CardModel? currentPlayingCard = null)
	{
		if (card == null || effect == null || !card.IsMutable || delta == 0)
		{
			return false;
		}

		using IDisposable restoreScope = CardEditorRunSelfScalingState.PushRestoreSuppression();
		CardModel persistentCard = card.DeckVersion is CardModel deckCard && deckCard.IsMutable
			? deckCard
			: card;
		if (persistentCard.Id == null || persistentCard.Id == ModelId.none)
		{
			return ApplySelfScalingMutationToCard(card, effect, delta);
		}

		CardOverride beforePersistentSnapshot = CreateSelfScalingSnapshot(persistentCard);
		CardOverride persistentSnapshot = CardEditorOverrides.Clone(beforePersistentSnapshot);
		CardOverride? beforeRuntimeSnapshot = !ReferenceEquals(card, persistentCard)
			? CreateSelfScalingSnapshot(card)
			: null;
		CardOverride? runtimeSnapshot = beforeRuntimeSnapshot != null
			? CardEditorOverrides.Clone(beforeRuntimeSnapshot)
			: null;
		MegaCrit.Sts2.Core.Random.Rng? rng = card.Owner?.RunState?.Rng?.CombatCardSelection;
		if (!TryApplySelfScalingMutationToSnapshot(persistentCard, persistentSnapshot, effect, delta, rng))
		{
			return false;
		}

		SelfScalingMutationDiff diff = BuildSelfScalingMutationDiff(persistentCard, beforePersistentSnapshot, persistentSnapshot);
		if (diff.IsEmpty)
		{
			return false;
		}

		CardEditorOverrides.ApplyOverrideToCard(persistentCard, persistentSnapshot);
		CardEditorRunSelfScalingState.RecordPersistentMutation(persistentCard, diff);
		RecalculateSelfScalingCard(persistentCard);
		NotifySelfScalingCostChanged(persistentCard, effect.SelfScalingTargetType);

		if (beforeRuntimeSnapshot != null
			&& runtimeSnapshot != null
			&& TryApplySelfScalingMutationToSnapshot(card, runtimeSnapshot, effect, delta, rng))
		{
			if (combatState != null && IsCurrentPlayingRuntimeMutationTarget(card, currentPlayingCard))
			{
				SelfScalingMutationDiff runtimeDiff = BuildSelfScalingMutationDiff(card, beforeRuntimeSnapshot, runtimeSnapshot);
				CardEditorTemporarySelfScalingController.DeferPermanentRuntimeMutation(combatState, card, runtimeDiff);
			}
			else
			{
				CardEditorOverrides.ApplyOverrideToCard(card, runtimeSnapshot);
				RecalculateSelfScalingCard(card);
				NotifySelfScalingCostChanged(card, effect.SelfScalingTargetType);
			}
		}

		return true;
	}

	private static void NotifySelfScalingCostChanged(CardModel card, CardExtraEffectSelfScalingTargetType targetType)
	{
		if (card == null)
		{
			return;
		}

		try
		{
			if (targetType is CardExtraEffectSelfScalingTargetType.StarCost
				or CardExtraEffectSelfScalingTargetType.AllGameplayNumbers
				or CardExtraEffectSelfScalingTargetType.AllGameplayNumbersIncludingRepeats)
			{
				CardEditorOverrides.NotifyStarCostChanged(card);
			}
			if (targetType is CardExtraEffectSelfScalingTargetType.EnergyCost
				or CardExtraEffectSelfScalingTargetType.AllGameplayNumbers
				or CardExtraEffectSelfScalingTargetType.AllGameplayNumbersIncludingRepeats)
			{
				card.InvokeEnergyCostChanged();
			}
		}
		catch
		{
			// ignored
		}
	}

	private static bool SelfScalingRecipientIncludesSource(CardExtraEffectSelfScalingRecipientMode mode)
		=> mode is CardExtraEffectSelfScalingRecipientMode.ThisCard
			or CardExtraEffectSelfScalingRecipientMode.ThisAndSelectedCards
			or CardExtraEffectSelfScalingRecipientMode.ThisAndMatchingCards;

	private static bool SelfScalingRecipientUsesSelection(CardExtraEffectSelfScalingRecipientMode mode)
		=> mode is CardExtraEffectSelfScalingRecipientMode.SelectedCards
			or CardExtraEffectSelfScalingRecipientMode.MatchingCards
			or CardExtraEffectSelfScalingRecipientMode.ThisAndSelectedCards
			or CardExtraEffectSelfScalingRecipientMode.ThisAndMatchingCards;

	private static bool SelfScalingRecipientUsesAllMatches(CardExtraEffectSelfScalingRecipientMode mode)
		=> mode is CardExtraEffectSelfScalingRecipientMode.MatchingCards
			or CardExtraEffectSelfScalingRecipientMode.ThisAndMatchingCards;

	private static async Task<List<CardModel>> ResolveSelfScalingRecipientCards(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay, CardExtraEffect effect)
	{
		List<CardModel> selected = new List<CardModel>();
		if (combatState == null || choiceContext == null || cardPlay?.Card?.Owner == null || effect == null)
		{
			return selected;
		}

		CardModel sourceCard = cardPlay.Card;
		Player owner = sourceCard.Owner;
		HashSet<CardModel> seen = new HashSet<CardModel>(ReferenceEqualityComparer<CardModel>.Instance);

		List<CardModel> Finish()
		{
			CardEditorEffectExecutionAmountContext.ReportCurrentSelectedCards(selected);
			return selected;
		}

		void AddRecipient(CardModel? card)
		{
			if (card == null)
			{
				return;
			}
			CardModel target = ResolveSelfScalingMutationTargetCard(card) ?? card;
			if (target.IsMutable && seen.Add(target))
			{
				selected.Add(target);
			}
		}

		if (SelfScalingRecipientIncludesSource(effect.SelfScalingRecipientMode))
		{
			AddRecipient(sourceCard);
		}

		if (!SelfScalingRecipientUsesSelection(effect.SelfScalingRecipientMode))
		{
			return Finish();
		}

		List<CardModel> candidates = GetCandidatesFromConfiguredPile(
			owner,
			effect,
			sourceCard,
			includeDeck: true,
			requireDeckVersion: false,
			includeCostFilter: true);
		if (candidates.Count == 0)
		{
			return Finish();
		}

		CardExtraEffectCardSelectionMode selectionMode = SelfScalingRecipientUsesAllMatches(effect.SelfScalingRecipientMode)
			? CardExtraEffectCardSelectionMode.All
			: effect.CardSelectionMode;
		int desiredCount = effect.CardSelectionCountIsX ? ResolveXAmountWithPlus(cardPlay, effect.CardSelectionCount) : effect.CardSelectionCount;
		desiredCount = selectionMode == CardExtraEffectCardSelectionMode.All
			? candidates.Count
			: Math.Clamp(desiredCount, 0, candidates.Count);
		if (desiredCount <= 0 && selectionMode != CardExtraEffectCardSelectionMode.SelectedByEffect)
		{
			return Finish();
		}

		PileType fromPileType = effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles
			? PileType.None
			: ResolvePileType(effect.CardSelectionPile);
		List<CardModel> chosen = await SelectCardsFromCandidates(
			choiceContext,
			owner,
			candidates,
			desiredCount,
			selectionMode,
			fromPileType,
			new LocString("gameplay_ui", "CHOOSE_CARD_HEADER"),
			sourceCard,
			excludeSourceCardInHandSelector: true,
			preferHandDiscardSelector: false,
			owner.RunState?.Rng?.CombatCardSelection,
			ResolveCardSelectionOfferCount(effect, cardPlay, desiredCount));

		foreach (CardModel card in chosen)
		{
			AddRecipient(card);
		}

		return Finish();
	}

	private static async Task<bool> ApplySelfScalingMutation(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay, CardExtraEffect effect, int triggerEventAmount)
	{
		Creature? ownerCreature = CardEditorPowerExecutionHostContext.Current ?? cardPlay?.Card?.Owner?.Creature;
		if (ownerCreature == null || !TryResolveSelfScalingDelta(combatState, ownerCreature, cardPlay, effect, triggerEventAmount, out int delta))
		{
			return false;
		}

		List<CardModel> recipients = await ResolveSelfScalingRecipientCards(combatState, choiceContext, cardPlay, effect);
		bool mutated = false;
		CardExtraEffectCardCostsLessDuration duration = GetEffectiveSelfScalingDuration(effect);
		if (duration == CardExtraEffectCardCostsLessDuration.Permanent)
		{
			foreach (CardModel recipient in recipients)
			{
				mutated |= ApplyPersistentSelfScalingMutationToCard(combatState, recipient, effect, delta, cardPlay.Card);
			}
			return mutated;
		}

		foreach (CardModel recipient in recipients)
		{
			mutated |= duration == CardExtraEffectCardCostsLessDuration.ThisCombat
				? ApplySelfScalingMutationToCard(recipient, effect, delta)
				: ApplyTimedSelfScalingMutationToCard(combatState, recipient, effect, delta);
		}
		return mutated;
	}

	private static async Task<bool> ApplyPersistentSelfScalingMutation(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay, CardExtraEffect effect, int triggerEventAmount)
	{
		Creature? ownerCreature = CardEditorPowerExecutionHostContext.Current ?? cardPlay?.Card?.Owner?.Creature;
		if (ownerCreature == null || !TryResolveSelfScalingDelta(combatState, ownerCreature, cardPlay, effect, triggerEventAmount, out int delta))
		{
			return false;
		}

		List<CardModel> recipients = await ResolveSelfScalingRecipientCards(combatState, choiceContext, cardPlay, effect);
		bool mutated = false;
		HashSet<CardModel> mutatedPersistentCards = new HashSet<CardModel>(ReferenceEqualityComparer<CardModel>.Instance);
		foreach (CardModel recipient in recipients)
		{
			CardModel persistentCard = recipient.DeckVersion is CardModel deckCard && deckCard.IsMutable
				? deckCard
				: recipient;
			if (!mutatedPersistentCards.Add(persistentCard))
			{
				continue;
			}
			mutated |= ApplyPersistentSelfScalingMutationToCard(combatState, recipient, effect, delta, cardPlay.Card);
		}
		return mutated;
	}

	private static async Task<bool> ApplyLinkedCardAction(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay, CardExtraEffect effect, int triggerEventAmount)
	{
		if (combatState == null || cardPlay?.Card?.Owner == null || effect == null)
		{
			return false;
		}

		Player owner = cardPlay.Card.Owner;
		Creature? ownerCreature = CardEditorPowerExecutionHostContext.Current ?? owner.Creature;
		if (ownerCreature == null || !TryResolveSelfScalingDelta(combatState, ownerCreature, cardPlay, effect, triggerEventAmount, out int delta))
		{
			return false;
		}

		if (!TryParseSpecificCardId(effect.SpecificCardId ?? string.Empty, out ModelId linkedCardId) || linkedCardId == ModelId.none)
		{
			return false;
		}

		CardModel? canonical = ModelDb.GetByIdOrNull<CardModel>(linkedCardId);
		if (canonical == null)
		{
			return false;
		}

		List<CardModel> existingActiveTargets = GetLinkedCardActionTargets(owner, linkedCardId, includeExhausted: false);
		List<CardModel> generatedCards = new();
		if (existingActiveTargets.Count == 0)
		{
			List<(PileType PileType, CardPilePosition Position)> destinations = GetConfiguredCardCreationDestinations(effect, CardExtraEffectCardPile.Hand, CardExtraEffectCardPilePosition.Bottom)
				.Select(dest => (ResolvePileType(dest.Pile), ResolvePilePosition(dest.Position)))
				.ToList();
			List<(CardPileAddResult Result, PileType PileType)> results = new();
			await AddCanonicalCardToConfiguredDestinations(combatState, owner, canonical, destinations, results, cardPlay.Card, effect, generatedCards);
			if (results.Count > 0)
			{
				PreviewGeneratedPileAdds(results);
			}
		}

		List<CardModel> targets = GetLinkedCardActionTargets(owner, linkedCardId, includeExhausted: true);
		if (targets.Count == 0)
		{
			return generatedCards.Count > 0;
		}

		bool mutated = false;
		CardExtraEffectCardCostsLessDuration duration = GetEffectiveSelfScalingDuration(effect);
		if (duration == CardExtraEffectCardCostsLessDuration.Permanent)
		{
			HashSet<CardModel> mutatedPersistentCards = new HashSet<CardModel>(ReferenceEqualityComparer<CardModel>.Instance);
			foreach (CardModel target in targets)
			{
				CardModel persistentCard = target.DeckVersion is CardModel deckCard && deckCard.IsMutable
					? deckCard
					: target;
				if (mutatedPersistentCards.Add(persistentCard))
				{
					mutated |= ApplyPersistentSelfScalingMutationToCard(combatState, target, effect, delta, cardPlay.Card);
				}
			}
		}
		else
		{
			foreach (CardModel target in targets)
			{
				mutated |= duration == CardExtraEffectCardCostsLessDuration.ThisCombat
					? ApplySelfScalingMutationToCard(target, effect, delta)
					: ApplyTimedSelfScalingMutationToCard(combatState, target, effect, delta);
			}
		}

		CardEditorEffectExecutionAmountContext.ReportCurrentSelectedCards(targets);
		CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(mutated ? targets.Count : 0);
		return mutated || generatedCards.Count > 0;
	}

	private static List<CardModel> GetLinkedCardActionTargets(Player owner, ModelId linkedCardId, bool includeExhausted)
	{
		List<CardModel> targets = new();
		if (owner?.PlayerCombatState?.AllCards == null || linkedCardId == ModelId.none)
		{
			return targets;
		}

		HashSet<CardModel> seen = new HashSet<CardModel>(ReferenceEqualityComparer<CardModel>.Instance);
		foreach (CardModel? candidate in owner.PlayerCombatState.AllCards)
		{
			if (candidate == null || candidate.IsDupe)
			{
				continue;
			}

			if (!includeExhausted && candidate.Pile?.Type == PileType.Exhaust)
			{
				continue;
			}

			CardModel target = ResolveSelfScalingMutationTargetCard(candidate) ?? candidate;
			if (!target.IsMutable || !IsLinkedCardActionTarget(target, candidate, linkedCardId) || !seen.Add(target))
			{
				continue;
			}

			targets.Add(target);
		}

		return targets;
	}

	private static bool IsLinkedCardActionTarget(CardModel target, CardModel candidate, ModelId linkedCardId)
	{
		if (target?.Id == linkedCardId || candidate?.Id == linkedCardId)
		{
			return true;
		}

		try
		{
			return target?.DeckVersion?.Id == linkedCardId || candidate?.DeckVersion?.Id == linkedCardId;
		}
		catch
		{
			return false;
		}
	}

	private static bool TryApplyTriggeredPermanentCardCostsLessToSnapshot(CardModel card, CardOverride snapshot, CardExtraEffect effect)
	{
		if (card == null || snapshot == null || effect == null)
		{
			return false;
		}

		CardExtraEffectCostModifier modifier = GetEffectiveCardCostsLessModifier(effect);
		switch (effect.Kind)
		{
			case CardExtraEffectKind.CardCostsLess:
			{
				if (snapshot.EnergyCostX == true || card.EnergyCost.CostsX)
				{
					return false;
				}

				int currentBaseCost;
				try
				{
					currentBaseCost = snapshot.EnergyCost ?? card.EnergyCost.GetWithModifiers(CostModifiers.None);
				}
				catch
				{
					return false;
				}

				if (!TryGetTriggeredPermanentCardCostsLessBaseCost(currentBaseCost, modifier, effect.Amount, out int mutatedBaseCost))
				{
					return false;
				}

				snapshot.EnergyCostX = false;
				snapshot.EnergyCost = mutatedBaseCost;
				return true;
			}

			case CardExtraEffectKind.CardStarCostsLess:
			{
				if (snapshot.StarCostX == true || card.HasStarCostX)
				{
					return false;
				}

				int currentBaseCost;
				try
				{
					currentBaseCost = snapshot.StarCost ?? card.BaseStarCost;
				}
				catch
				{
					return false;
				}

				if (!TryGetTriggeredPermanentCardCostsLessBaseCost(currentBaseCost, modifier, effect.Amount, out int mutatedBaseCost))
				{
					return false;
				}

				snapshot.StarCostX = false;
				snapshot.StarCost = mutatedBaseCost;
				return true;
			}

			default:
				return false;
		}
	}

	private static bool TryGetTriggeredPermanentCardCostsLessBaseCost(int currentBaseCost, CardExtraEffectCostModifier modifier, int amount, out int mutatedBaseCost)
	{
		mutatedBaseCost = currentBaseCost;
		if (currentBaseCost < 0)
		{
			return false;
		}

		long nextBaseCost = modifier switch
		{
			CardExtraEffectCostModifier.Reduce => (long)currentBaseCost - amount,
			CardExtraEffectCostModifier.Free => 0,
			CardExtraEffectCostModifier.FreeToPlay => 0,
			CardExtraEffectCostModifier.HalfCost => (long)Math.Floor(Math.Max(0, currentBaseCost) / 2m),
			_ => currentBaseCost
		};

		if (modifier is not (CardExtraEffectCostModifier.Reduce
			or CardExtraEffectCostModifier.Free
			or CardExtraEffectCostModifier.FreeToPlay
			or CardExtraEffectCostModifier.HalfCost))
		{
			return false;
		}

		if (nextBaseCost < 0)
		{
			nextBaseCost = 0;
		}
		else if (nextBaseCost > int.MaxValue)
		{
			nextBaseCost = int.MaxValue;
		}

		mutatedBaseCost = (int)nextBaseCost;
		return true;
	}

	private static void NotifyTriggeredPermanentCardCostsLessChanged(CardModel card, CardExtraEffectKind kind)
	{
		if (card == null)
		{
			return;
		}

		try
		{
			if (kind == CardExtraEffectKind.CardStarCostsLess)
			{
				CardEditorOverrides.NotifyStarCostChanged(card);
			}
			else
			{
				card.InvokeEnergyCostChanged();
			}
		}
		catch
		{
			// ignored
		}
	}

	private static bool ApplyPersistentTriggeredCardCostsLessMutation(CardModel? card, CardExtraEffect effect)
	{
		if (card == null || effect == null || !card.IsMutable)
		{
			return false;
		}

		CardModel runtimeTargetCard = ResolveSelfScalingMutationTargetCard(card) ?? card;
		if (!runtimeTargetCard.IsMutable)
		{
			return false;
		}

		CardModel persistentCard = runtimeTargetCard.DeckVersion is CardModel deckCard && deckCard.IsMutable
			? deckCard
			: runtimeTargetCard;
		if (persistentCard.Id == null || persistentCard.Id == ModelId.none)
		{
			CardOverride runtimeOnlySnapshot = CreateSelfScalingSnapshot(runtimeTargetCard);
			if (!TryApplyTriggeredPermanentCardCostsLessToSnapshot(runtimeTargetCard, runtimeOnlySnapshot, effect))
			{
				return false;
			}

			CardEditorOverrides.ApplyOverrideToCard(runtimeTargetCard, runtimeOnlySnapshot);
			NotifyTriggeredPermanentCardCostsLessChanged(runtimeTargetCard, effect.Kind);
			return true;
		}

		CardOverride persistentSnapshot = CreateSelfScalingSnapshot(persistentCard);
		CardOverride? runtimeSnapshot = !ReferenceEquals(runtimeTargetCard, persistentCard)
			? CreateSelfScalingSnapshot(runtimeTargetCard)
			: null;
		if (!TryApplyTriggeredPermanentCardCostsLessToSnapshot(persistentCard, persistentSnapshot, effect))
		{
			return false;
		}

		CardEditorOverrides.Set(persistentCard.Id, persistentSnapshot);
		CardEditorOverrides.ApplyOverrideToCard(persistentCard, persistentSnapshot);
		NotifyTriggeredPermanentCardCostsLessChanged(persistentCard, effect.Kind);

		if (runtimeSnapshot != null && TryApplyTriggeredPermanentCardCostsLessToSnapshot(runtimeTargetCard, runtimeSnapshot, effect))
		{
			CardEditorOverrides.ApplyOverrideToCard(runtimeTargetCard, runtimeSnapshot);
			NotifyTriggeredPermanentCardCostsLessChanged(runtimeTargetCard, effect.Kind);
		}

		return true;
	}

	private static IReadOnlyList<CardExtraEffect> GetRuntimeEffectsIncludingBorrowedSources(CombatState? combatState, CardModel card)
	{
		if (card == null)
		{
			return Array.Empty<CardExtraEffect>();
		}

		List<CardExtraEffect> effects = new List<CardExtraEffect>();
		HashSet<ModelId> effectSourceGuard = new HashSet<ModelId>();
		if (card.Id != null && card.Id != ModelId.none)
		{
			effectSourceGuard.Add(card.Id);
		}

		AppendRuntimeEffectsIncludingBorrowedSources(effects, combatState, card, includeTemporaryEffects: true, effectSourceGuard);
		return effects;
	}

	internal static bool CardHasRuntimeEffectKind(CardModel? card, CardExtraEffectKind kind)
	{
		if (card == null)
		{
			return false;
		}

		return GetRuntimeEffectsIncludingBorrowedSources(card.GetConcreteCombatState(), card).Any(effect =>
			effect != null
			&& effect.Kind == kind
			&& IsValidEffectAmount(effect.Kind, effect.Amount));
	}

	internal static bool ShouldPreventPlayFromEditorRules(CombatState combatState, CardModel card, AutoPlayType autoPlayType, out AbstractModel? preventer)
	{
		preventer = null;
		if (combatState == null || card == null)
		{
			return false;
		}

		Player? owner = card.Owner;
		if (owner == null)
		{
			return false;
		}

		// Version-cached prefilters: only build the effect list for cards that might
		// actually carry PlayPermission/PlayPrevention rows. When the combat has any
		// granted/aura effects the gates conservatively report "might have" and the
		// original full evaluation below runs unchanged.
		if (CardEditorRuntimeCaches.CardMightHaveRuntimeEffectKind(combatState, card, CardEditorRuntimeCaches.PlayPermissionBit))
		{
			foreach (CardExtraEffect effect in GetRuntimeEffectsIncludingBorrowedSources(combatState, card))
			{
				if (!IsActivePassiveBehavior(effect, CardExtraEffectKind.PlayPermission))
				{
					continue;
				}

				if (!DoesBehaviorConditionPass(combatState, card, card, effect))
				{
					preventer = card;
					return true;
				}
			}
		}

		CardPile? hand = PileType.Hand.GetPile(owner);
		if (hand == null)
		{
			return false;
		}

		foreach (CardModel? sourceCard in hand.Cards)
		{
			if (sourceCard == null)
			{
				continue;
			}

			if (!CardEditorRuntimeCaches.CardMightHaveRuntimeEffectKind(combatState, sourceCard, CardEditorRuntimeCaches.PlayPreventionBit))
			{
				continue;
			}

			foreach (CardExtraEffect effect in GetRuntimeEffectsIncludingBorrowedSources(combatState, sourceCard))
			{
				if (!IsActivePassiveBehavior(effect, CardExtraEffectKind.PlayPrevention))
				{
					continue;
				}

				if (effect.PlayPreventionBlockMode == CardExtraEffectPlayPreventionBlockMode.ManualOnly
					&& autoPlayType != AutoPlayType.None)
				{
					continue;
				}

				if (IsPlayPreventionExempt(sourceCard, card, effect))
				{
					continue;
				}

				if (!MatchesAffectedCardFilters(owner, card, effect))
				{
					continue;
				}

				if (!DoesBehaviorConditionPass(combatState, sourceCard, card, effect))
				{
					continue;
				}

				preventer = sourceCard;
				return true;
			}
		}

		return false;
	}

	private static bool IsPlayPreventionExempt(CardModel sourceCard, CardModel card, CardExtraEffect effect)
	{
		return effect.PlayPreventionExemption switch
		{
			CardExtraEffectPlayPreventionExemption.ThisCard => ReferenceEquals(sourceCard, card),
			CardExtraEffectPlayPreventionExemption.MatchingSourceCard => sourceCard.Id == card.Id,
			_ => false
		};
	}

	private static bool IsActivePassiveBehavior(CardExtraEffect? effect, CardExtraEffectKind kind)
	{
		return effect != null
			&& effect.Kind == kind
			&& !effect.AsPower
			&& !effect.GrantToCard
			&& IsValidEffectAmount(effect.Kind, effect.Amount);
	}

	private static bool DoesBehaviorConditionPass(CombatState? combatState, CardModel sourceCard, CardModel eventCard, CardExtraEffect effect)
	{
		if (effect == null)
		{
			return false;
		}

		if (!HasUsableBranchCondition(effect))
		{
			return true;
		}

		CombatState? resolvedCombatState = combatState ?? ResolveCardCombatState(eventCard) ?? ResolveCardCombatState(sourceCard);
		Creature? ownerCreature = sourceCard.TryGetOwnerCreature() ?? eventCard.TryGetOwnerCreature();
		if (resolvedCombatState == null || ownerCreature == null)
		{
			return false;
		}

		CardPlay playForConditions = GetPreviewConditionCardPlay(eventCard ?? sourceCard, eventCard.GetSafeCurrentTarget());

		return DoesBranchConditionPass(resolvedCombatState, ownerCreature, playForConditions, effect);
	}

	private static async Task EvaluateDynamicTransforms(CombatState combatState, PlayerChoiceContext choiceContext, Player? player)
	{
		if (combatState == null || choiceContext == null || player == null)
		{
			return;
		}

		DynamicTransformState state = _dynamicTransformStates.GetOrCreateValue(combatState);
		if (state.IsEvaluating)
		{
			return;
		}

		state.IsEvaluating = true;
		try
		{
			await RevertExpiredDynamicTransforms(combatState, choiceContext, state);
			await ApplyDynamicTransforms(combatState, choiceContext, player, state);
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] Dynamic transform evaluation failed: {ex}");
		}
		finally
		{
			state.IsEvaluating = false;
		}
	}

	private static async Task RevertExpiredDynamicTransforms(CombatState combatState, PlayerChoiceContext choiceContext, DynamicTransformState state)
	{
		for (int i = state.Entries.Count - 1; i >= 0; i--)
		{
			DynamicTransformEntry entry = state.Entries[i];
			if (entry?.Original == null || entry.Replacement == null || entry.Effect == null)
			{
				UnmarkDynamicTransformReplacement(entry?.Replacement);
				state.Entries.RemoveAt(i);
				continue;
			}

			if (!IsDynamicTransformTrackedCardPresent(entry.Replacement))
			{
				UnmarkDynamicTransformReplacement(entry.Replacement);
				state.Entries.RemoveAt(i);
				continue;
			}

			if (DoesBehaviorConditionPass(combatState, entry.Original, entry.Replacement, entry.Effect))
			{
				continue;
			}

			await CardCmd.Transform(
				new List<CardTransformation> { new CardTransformation(entry.Replacement, entry.Original) },
				rng: null,
				CardPreviewStyle.None);
			CardEditorTemporaryEnchantmentController.OnCardTransformed(combatState, entry.Replacement, entry.Original);
			UnmarkDynamicTransformReplacement(entry.Replacement);
			RefreshTransformVisuals(entry.Replacement, entry.Original);
			state.Entries.RemoveAt(i);
		}
	}

	private static async Task ApplyDynamicTransforms(CombatState combatState, PlayerChoiceContext choiceContext, Player player, DynamicTransformState state)
	{
		HashSet<CardModel> activeOriginals = state.Entries
			.Where(entry => entry?.Original != null)
			.Select(entry => entry.Original)
			.ToHashSet(ReferenceEqualityComparer<CardModel>.Instance);
		HashSet<CardModel> activeReplacements = state.Entries
			.Where(entry => entry?.Replacement != null)
			.Select(entry => entry.Replacement)
			.ToHashSet(ReferenceEqualityComparer<CardModel>.Instance);

		foreach (CardModel card in GetDynamicTransformCandidates(player))
		{
			if (card == null || activeOriginals.Contains(card) || activeReplacements.Contains(card))
			{
				continue;
			}

			CardExtraEffect? transformEffect = GetActiveDynamicTransformEffect(combatState, card);
			if (transformEffect == null || !DoesBehaviorConditionPass(combatState, card, card, transformEffect))
			{
				continue;
			}

			CardModel? replacement = CreateDynamicTransformReplacement(combatState, player, card, transformEffect);
			if (replacement == null)
			{
				continue;
			}

			List<CardTransformation> transformations = new List<CardTransformation> { new CardTransformation(card, replacement) };
			await CardCmd.Transform(transformations, rng: null, GetTransformPreviewStyle(transformations));
			CardEditorTemporaryEnchantmentController.OnCardTransformed(combatState, card, replacement);

			DynamicTransformEntry entry = new DynamicTransformEntry
			{
				Original = card,
				Replacement = replacement,
				Effect = CloneEffect(transformEffect)
			};
			MarkDynamicTransformReplacement(replacement, card, transformEffect);
			RefreshTransformVisuals(card, replacement);
			state.Entries.Add(entry);
			activeOriginals.Add(card);
			activeReplacements.Add(replacement);
		}
	}

	private static IEnumerable<CardModel> GetDynamicTransformCandidates(Player player)
	{
		foreach (PileType pileType in GetCombatCardPileTypes())
		{
			CardPile? pile = pileType.GetPile(player);
			if (pile?.Cards == null || pile.Cards.Count == 0)
			{
				continue;
			}

			foreach (CardModel? card in pile.Cards.ToList())
			{
				if (card != null)
				{
					yield return card;
				}
			}
		}
	}

	private static CardExtraEffect? GetActiveDynamicTransformEffect(CombatState combatState, CardModel card)
	{
		foreach (CardExtraEffect effect in GetRuntimeEffectsIncludingBorrowedSources(combatState, card))
		{
			if (IsActivePassiveBehavior(effect, CardExtraEffectKind.DynamicIdentity)
				&& !string.IsNullOrWhiteSpace(effect.SpecificCardId))
			{
				return effect;
			}
		}

		return null;
	}

	private static CardModel? CreateDynamicTransformReplacement(CombatState combatState, Player owner, CardModel original, CardExtraEffect effect)
	{
		if (combatState == null
			|| owner == null
			|| original == null
			|| effect == null
			|| !TryParseSpecificCardId(effect.SpecificCardId ?? string.Empty, out ModelId id)
			|| id == ModelId.none
			|| (original.Id != null && original.Id == id))
		{
			return null;
		}

		CardModel? canonical = ModelDb.GetByIdOrNull<CardModel>(id);
		if (canonical == null)
		{
			return null;
		}

		CardModel replacement = combatState.CreateCard(canonical, owner);
		ApplySpecificCardUpgradeMode(replacement, original, effect);

		return replacement;
	}

	private static void ApplySpecificCardUpgradeMode(CardModel? replacement, CardModel? source, CardExtraEffect? effect)
	{
		if (replacement == null)
		{
			return;
		}

		int requestedUpgrades = effect?.SpecificCardUpgradeMode switch
		{
			CardExtraEffectSpecificCardUpgradeMode.Base => 0,
			CardExtraEffectSpecificCardUpgradeMode.Upgraded => 1,
			_ => source.GetSafeCurrentUpgradeLevel()
		};
		int upgrades = Math.Min(requestedUpgrades, Math.Max(0, replacement.MaxUpgradeLevel));
		if (upgrades <= 0)
		{
			return;
		}

		try
		{
			for (int i = 0; i < upgrades; i++)
			{
				replacement.UpgradeInternal();
				replacement.FinalizeUpgradeInternal();
			}
		}
		catch
		{
		}
	}

	private static bool IsDynamicTransformTrackedCardPresent(CardModel? card)
	{
		return card?.Pile != null
			&& card.Pile.Type is PileType.Hand
				or PileType.Draw
				or PileType.Discard
				or PileType.Exhaust
				or PileType.Play;
	}

	internal static bool IsDynamicTransformReplacement(CardModel? card)
	{
		return card != null
			&& (_dynamicTransformMarkers.TryGetValue(card, out _) || _statefulTransformMarkers.TryGetValue(card, out _))
			&& IsDynamicTransformTrackedCardPresent(card);
	}

	private static void MarkDynamicTransformReplacement(CardModel replacement, CardModel original, CardExtraEffect effect)
	{
		if (replacement == null || original == null || effect == null)
		{
			return;
		}

		UnmarkDynamicTransformReplacement(replacement);
		_dynamicTransformMarkers.Add(replacement, new DynamicTransformMarker
		{
			Original = original,
			Effect = CloneEffect(effect)
		});
		CardEditorRuntimeCacheVersion.Bump();
	}

	private static void UnmarkDynamicTransformReplacement(CardModel? replacement)
	{
		if (replacement != null)
		{
			_dynamicTransformMarkers.Remove(replacement);
			CardEditorRuntimeCacheVersion.Bump();
		}
	}

	// Cheap probe for the runtime-cache gate: dynamic-transform replacements borrow their
	// identity from another card, so treat them as mod-touched everywhere.
	internal static bool HasDynamicTransformMarker(CardModel? card)
	{
		return card != null && _dynamicTransformMarkers.TryGetValue(card, out _);
	}

	internal static void RefreshCardVisuals(CardModel? card)
	{
		if (card == null)
		{
			return;
		}

		try
		{
			NCard? node = NCard.FindOnTable(card);
			if (node != null)
			{
				if (node.GetParent() is NHandCardHolder handHolder)
				{
					handHolder.UpdateCard();
					return;
				}

				node.UpdateVisuals(node.DisplayingPile, CardPreviewMode.Normal);
			}
		}
		catch
		{
		}
	}

	private static CardPreviewStyle GetTransformPreviewStyle(IReadOnlyList<CardTransformation> transformations)
	{
		CardModel? currentCard = CardEditorCardPlayContext.Current?.Card;
		if (currentCard != null && transformations != null && transformations.Any(t => ReferenceEquals(t.Original, currentCard)))
		{
			return CardPreviewStyle.None;
		}

		return CardPreviewStyle.HorizontalLayout;
	}

	private static void RefreshTransformVisuals(CardModel? original, CardModel? replacement)
	{
		if (replacement == null)
		{
			return;
		}

		try
		{
			NCard? staleOriginalNode = original != null ? NCard.FindOnTable(original) : null;
			if (staleOriginalNode != null && GodotObject.IsInstanceValid(staleOriginalNode))
			{
				staleOriginalNode.Model = replacement;
				if (staleOriginalNode.GetParent() is NHandCardHolder handHolder)
				{
					handHolder.UpdateCard();
					return;
				}

				staleOriginalNode.UpdateVisuals(replacement.Pile?.Type ?? staleOriginalNode.DisplayingPile, CardPreviewMode.Normal);
				return;
			}
		}
		catch
		{
		}

		RefreshCardVisuals(replacement);
	}

	private static bool ShouldDeferCurrentlyPlayingSelfTransform(CardTransformation transformation)
	{
		CardModel? currentCard = CardEditorCardPlayContext.Current?.Card;
		return currentCard != null
			&& ReferenceEquals(transformation.Original, currentCard)
			&& transformation.Original.Pile?.Type == PileType.Play;
	}

	private static void DeferCurrentlyPlayingSelfTransform(CardTransformation transformation, MegaCrit.Sts2.Core.Random.Rng? rng)
	{
		CardModel original = transformation.Original;
		void RunAfterPlayed()
		{
			original.Played -= RunAfterPlayed;
			TaskHelper.RunSafely(RunDeferredCurrentlyPlayingSelfTransform(transformation, rng));
		}

		original.Played += RunAfterPlayed;
	}

	private static async Task RunDeferredCurrentlyPlayingSelfTransform(CardTransformation transformation, MegaCrit.Sts2.Core.Random.Rng? rng)
	{
		CardModel original = transformation.Original;
		if (original == null || original.Pile == null || !original.IsTransformable)
		{
			return;
		}

		List<CardPileAddResult> results = (await CardCmd.Transform(
			new List<CardTransformation> { transformation },
			rng,
			CardPreviewStyle.HorizontalLayout)).ToList();

		CardModel? replacement = results.FirstOrDefault().cardAdded;
		CombatState? replacementCombatState = replacement.GetConcreteCombatState();
		if (replacement != null && replacementCombatState != null)
		{
			CardEditorTemporaryEnchantmentController.OnCardTransformed(replacementCombatState, original, replacement);
			RefreshTransformVisuals(original, replacement);
		}
	}

	private static async Task<int> TransformCardsWithCurrentPlayDeferral(
		IReadOnlyList<CardTransformation> transformations,
		MegaCrit.Sts2.Core.Random.Rng? rng,
		CardExtraEffect? randomUpgradeModeEffect = null)
	{
		List<CardTransformation> immediate = new List<CardTransformation>();
		List<CardTransformation> deferred = new List<CardTransformation>();
		foreach (CardTransformation transformation in transformations)
		{
			if (ShouldDeferCurrentlyPlayingSelfTransform(transformation))
			{
				deferred.Add(transformation);
			}
			else
			{
				immediate.Add(transformation);
			}
		}

		int transformed = 0;
		if (immediate.Count > 0)
		{
			IReadOnlyList<CardTransformation> immediateList = immediate;
			List<CardPileAddResult> results = (await CardCmd.Transform(immediateList, rng, GetTransformPreviewStyle(immediateList))).ToList();
			List<CardModel> immediateReplacements = new List<CardModel>(results.Count);
			for (int i = 0; i < immediateList.Count && i < results.Count; i++)
			{
				CardModel? replacement = results[i].cardAdded;
				CombatState? replacementCombatState = replacement.GetConcreteCombatState();
				if (replacement != null && replacementCombatState != null)
				{
					// Random transforms roll the replacement inside vanilla CardCmd.Transform, so the
					// arrive-upgraded choice (bug list #8) can only apply here, after the roll. Only
					// the explicit Upgraded mode acts - MatchSource stays the legacy no-op so existing
					// configs keep their behavior.
					if (randomUpgradeModeEffect?.SpecificCardUpgradeMode == CardExtraEffectSpecificCardUpgradeMode.Upgraded)
					{
						ApplySpecificCardUpgradeMode(replacement, immediateList[i].Original, randomUpgradeModeEffect);
					}
					CardEditorTemporaryEnchantmentController.OnCardTransformed(replacementCombatState, immediateList[i].Original, replacement);
					RefreshTransformVisuals(immediateList[i].Original, replacement);
					immediateReplacements.Add(replacement);
					transformed++;
				}
			}

			// Chainboard C0: downstream SelectedByEffect steps must act on the RESULT cards - the
			// originals published during selection stop existing after the transform. Same
			// re-publish pattern the card generators use.
			if (immediateReplacements.Count > 0)
			{
				CardEditorEffectExecutionAmountContext.ReplaceCurrentSelectedCards(immediateReplacements);
			}
		}

		foreach (CardTransformation transformation in deferred)
		{
			DeferCurrentlyPlayingSelfTransform(transformation, rng);
			transformed++;
		}

		return transformed;
	}

	internal static bool TryGetDynamicIdentitySource(CardModel? card, out CardModel source)
	{
		source = null!;
		if (card != null && _dynamicTransformMarkers.TryGetValue(card, out DynamicTransformMarker? dynamicMarker) && dynamicMarker?.Original != null)
		{
			source = dynamicMarker.Original;
			return true;
		}

		if (card != null && _statefulTransformMarkers.TryGetValue(card, out StatefulTransformMarker? statefulMarker) && statefulMarker?.Entry?.Original != null)
		{
			source = statefulMarker.Entry.Original;
			return true;
		}

		return false;
	}

	private static bool TryGetStatefulTransformMarker(CardModel? card, out StatefulTransformMarker? marker)
	{
		marker = null;
		return card != null
			&& _statefulTransformMarkers.TryGetValue(card, out marker)
			&& marker?.Entry != null
			&& IsStatefulTransformTrackedCardPresent(card);
	}

	private static bool IsStatefulTransformTrackedCardPresent(CardModel? card)
	{
		return IsDynamicTransformTrackedCardPresent(card);
	}

	private static List<StatefulTransformEntry> GetStatefulTransformEntriesSnapshot(StatefulTransformState? state = null)
	{
		List<StatefulTransformEntry> entries = new List<StatefulTransformEntry>();
		void AddEntry(StatefulTransformEntry? entry)
		{
			if (entry != null && !entries.Contains(entry))
			{
				entries.Add(entry);
			}
		}

		foreach (StatefulTransformEntry entry in _statefulTransformEntries)
		{
			AddEntry(entry);
		}

		if (state != null)
		{
			foreach (StatefulTransformEntry entry in state.Entries)
			{
				AddEntry(entry);
			}
		}

		return entries;
	}

	private static void RegisterStatefulTransformEntry(StatefulTransformState state, StatefulTransformEntry entry)
	{
		if (entry == null)
		{
			return;
		}

		if (state != null && !state.Entries.Contains(entry))
		{
			state.Entries.Add(entry);
		}

		if (!_statefulTransformEntries.Contains(entry))
		{
			_statefulTransformEntries.Add(entry);
		}
	}

	private static void UnregisterStatefulTransformEntry(StatefulTransformState? state, StatefulTransformEntry? entry)
	{
		if (entry == null)
		{
			return;
		}

		state?.Entries.Remove(entry);
		_statefulTransformEntries.Remove(entry);
	}

	private static void MarkStatefulTransformReplacement(CardModel replacement, StatefulTransformEntry entry)
	{
		if (replacement == null || entry == null)
		{
			return;
		}

		UnmarkStatefulTransformReplacement(replacement);
		_statefulTransformMarkers.Add(replacement, new StatefulTransformMarker { Entry = entry });
		CardEditorRuntimeCacheVersion.Bump();
	}

	private static void UnmarkStatefulTransformReplacement(CardModel? replacement)
	{
		if (replacement != null)
		{
			_statefulTransformMarkers.Remove(replacement);
			CardEditorRuntimeCacheVersion.Bump();
		}
	}

	// Cheap probe for the runtime-cache gate: does this card carry a stateful-transform
	// marker (which injects a marker effect row into its runtime effect list)?
	internal static bool HasStatefulTransformMarker(CardModel? card)
	{
		return card != null && _statefulTransformMarkers.TryGetValue(card, out _);
	}

	private static void RefreshStatefulTransformDuration(StatefulTransformEntry entry, CardExtraEffect effect)
	{
		if (entry == null || effect == null)
		{
			return;
		}

		entry.Duration = effect.StatefulTransformDuration;
		entry.RemainingTurns = effect.StatefulTransformDuration switch
		{
			CardExtraEffectStatefulTransformDuration.ThisTurn => 1,
			CardExtraEffectStatefulTransformDuration.Turns => Math.Clamp(effect.StatefulTransformDurationAmount, 1, 99),
			_ => 0
		};
		entry.RemainingCombats = effect.StatefulTransformDuration == CardExtraEffectStatefulTransformDuration.Combats
			? Math.Clamp(effect.StatefulTransformDurationAmount, 1, 99)
			: 0;
	}

	private static bool DoesStatefulTransformConditionPass(CombatState combatState, CardModel card, CardPlay cardPlay, CardExtraEffect effect)
	{
		if (combatState == null || card == null || cardPlay == null || effect == null)
		{
			return false;
		}

		Creature? ownerCreature = card.TryGetOwnerCreature() ?? cardPlay.Card.TryGetOwnerCreature();
		if (ownerCreature == null)
		{
			return false;
		}

		if (effect.ScaleMode != CardExtraEffectScaleMode.None)
		{
			int count = GetHistoryCountMultiplier(combatState, ownerCreature, cardPlay, effect, card);
			if (!DoesCountConditionPass(count, effect))
			{
				return false;
			}
		}

		return true;
	}

	private static CardPlay BuildStatefulTransformConditionPlay(CardModel card)
	{
		return GetPreviewConditionCardPlay(card, card.GetSafeCurrentTarget());
	}

	private static bool DoesStatefulTransformRevertConditionPass(CombatState combatState, CardModel card, CardPlay cardPlay, CardExtraEffect effect)
	{
		if (combatState == null || card == null || cardPlay == null || effect == null || !HasUsableBranchCondition(effect))
		{
			return false;
		}

		Creature? ownerCreature = card.TryGetOwnerCreature() ?? cardPlay.Card.TryGetOwnerCreature();
		return ownerCreature != null && DoesBranchConditionPass(combatState, ownerCreature, cardPlay, effect);
	}

	private static async Task ApplyStatefulTransform(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay, CardExtraEffect effect)
	{
		CardModel? card = cardPlay?.Card;
		Player? owner = card.TryGetOwner();
		if (combatState == null
			|| choiceContext == null
			|| card == null
			|| owner == null
			|| effect == null
			|| string.IsNullOrWhiteSpace(effect.SpecificCardId))
		{
			return;
		}

		StatefulTransformState state = _statefulTransformStates.GetOrCreateValue(combatState);
		if (state.IsMutating)
		{
			return;
		}

		state.IsMutating = true;
		try
		{
			if (!DoesStatefulTransformConditionPass(combatState, card, cardPlay, effect))
			{
				return;
			}

			if (TryGetStatefulTransformMarker(card, out StatefulTransformMarker? marker) && marker?.Entry != null)
			{
				bool sameStageEffect = marker.Entry.Effect != null && EffectsMatchExceptAmount(marker.Entry.Effect, effect);
				if (sameStageEffect && effect.StatefulTransformMode == CardExtraEffectStatefulTransformMode.Toggle)
				{
					await RevertStatefulTransform(combatState, state, marker.Entry);
				}
				else if (sameStageEffect)
				{
					RefreshStatefulTransformDuration(marker.Entry, effect);
				}
				else
				{
					await AdvanceStatefulTransform(combatState, state, marker.Entry, owner, card, effect);
				}
				return;
			}

			if (GetStatefulTransformEntriesSnapshot(state).Any(entry => entry != null
				&& (ReferenceEquals(entry.Original, card) || ReferenceEquals(entry.Current, card))))
			{
				return;
			}

			CardModel? replacement = CreateDynamicTransformReplacement(combatState, owner, card, effect);
			if (replacement == null)
			{
				return;
			}

			List<CardTransformation> transformations = new List<CardTransformation>
			{
				new CardTransformation(card, replacement)
			};
			List<CardPileAddResult> results = (await CardCmd.Transform(transformations, rng: null, GetTransformPreviewStyle(transformations))).ToList();
			CardModel appliedReplacement = results.Count > 0 && results[0].cardAdded != null
				? results[0].cardAdded
				: replacement;

			CardEditorTemporaryEnchantmentController.OnCardTransformed(combatState, card, appliedReplacement);
			StatefulTransformEntry entry = new StatefulTransformEntry
			{
				Original = card,
				Current = appliedReplacement,
				Effect = CloneEffect(effect)
			};
			RefreshStatefulTransformDuration(entry, effect);
			MarkStatefulTransformReplacement(appliedReplacement, entry);
			RefreshTransformVisuals(card, appliedReplacement);
			RegisterStatefulTransformEntry(state, entry);
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] Stateful transform failed: {ex}");
		}
		finally
		{
			state.IsMutating = false;
		}
	}

	private static async Task AdvanceStatefulTransform(
		CombatState combatState,
		StatefulTransformState state,
		StatefulTransformEntry entry,
		Player owner,
		CardModel current,
		CardExtraEffect effect)
	{
		if (combatState == null
			|| state == null
			|| entry?.Original == null
			|| owner == null
			|| current == null
			|| effect == null
			|| string.IsNullOrWhiteSpace(effect.SpecificCardId))
		{
			return;
		}

		CardModel? replacement = CreateDynamicTransformReplacement(combatState, owner, current, effect);
		if (replacement == null)
		{
			return;
		}

		List<CardTransformation> transformations = new List<CardTransformation>
		{
			new CardTransformation(current, replacement)
		};
		List<CardPileAddResult> results = (await CardCmd.Transform(transformations, rng: null, GetTransformPreviewStyle(transformations))).ToList();
		CardModel appliedReplacement = results.Count > 0 && results[0].cardAdded != null
			? results[0].cardAdded
			: replacement;

		CardEditorTemporaryEnchantmentController.OnCardTransformed(combatState, current, appliedReplacement);
		UnmarkStatefulTransformReplacement(current);
		entry.Current = appliedReplacement;
		entry.Effect = CloneEffect(effect);
		RefreshStatefulTransformDuration(entry, effect);
		MarkStatefulTransformReplacement(appliedReplacement, entry);
		RefreshTransformVisuals(current, appliedReplacement);
	}

	private static async Task RevertStatefulTransform(CombatState combatState, StatefulTransformState state, StatefulTransformEntry entry)
	{
		if (combatState == null || state == null || entry?.Current == null || entry.Original == null)
		{
			return;
		}

		CardModel current = entry.Current;
		if (!IsStatefulTransformTrackedCardPresent(current))
		{
			UnmarkStatefulTransformReplacement(current);
			UnregisterStatefulTransformEntry(state, entry);
			return;
		}

		try
		{
			await CardCmd.Transform(
				new List<CardTransformation> { new CardTransformation(current, entry.Original) },
				rng: null,
				CardPreviewStyle.None);
			CardEditorTemporaryEnchantmentController.OnCardTransformed(combatState, current, entry.Original);
			RefreshTransformVisuals(current, entry.Original);
		}
		catch (Exception ex)
		{
			// CardCmd.Transform dereferences CombatManager.Instance on its first line, and during
			// combat-end cleanup that singleton is already torn down - so the revert threw a
			// NullReferenceException here and skipped the bookkeeping below, leaking the entry into
			// the next combat. The visual swap is meaningless once combat is over; the bookkeeping
			// is not, so it moved into the finally.
			Log.Warn($"[CardEditor] Stateful transform revert could not swap the card back (state still cleaned up): {ex.Message}");
		}
		finally
		{
			UnmarkStatefulTransformReplacement(current);
			UnregisterStatefulTransformEntry(state, entry);
		}
	}

	private static async Task RunStatefulTransformPostCardPlayed(CombatState combatState, CardPlay cardPlay)
	{
		if (combatState == null || cardPlay?.Card == null)
		{
			return;
		}

		StatefulTransformState state = _statefulTransformStates.GetOrCreateValue(combatState);
		if (state.IsMutating)
		{
			return;
		}

		state.IsMutating = true;
		try
		{
			if (TryGetStatefulTransformMarker(cardPlay.Card, out StatefulTransformMarker? marker) && marker?.Entry != null)
			{
				if (marker.Entry.Duration == CardExtraEffectStatefulTransformDuration.UntilPlayed)
				{
					await RevertStatefulTransform(combatState, state, marker.Entry);
					return;
				}

				if (marker.Entry.Duration == CardExtraEffectStatefulTransformDuration.UntilConditionStops
					&& !DoesStatefulTransformConditionPass(combatState, marker.Entry.Current, cardPlay, marker.Entry.Effect))
				{
					await RevertStatefulTransform(combatState, state, marker.Entry);
				}
			}

			foreach (StatefulTransformEntry entry in GetStatefulTransformEntriesSnapshot(state))
			{
				if (entry?.Current == null || entry.Original == null || entry.Effect == null || !IsStatefulTransformTrackedCardPresent(entry.Current))
				{
					continue;
				}

				if (DoesStatefulTransformRevertConditionPass(combatState, entry.Current, cardPlay, entry.Effect))
				{
					await RevertStatefulTransform(combatState, state, entry);
				}
			}
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] Stateful transform post-play update failed: {ex}");
		}
		finally
		{
			state.IsMutating = false;
		}
	}

	private static async Task EvaluateStatefulTransformConditionStops(CombatState combatState)
	{
		if (combatState == null)
		{
			return;
		}

		StatefulTransformState state = _statefulTransformStates.GetOrCreateValue(combatState);
		if (state.IsMutating || (_statefulTransformEntries.Count == 0 && state.Entries.Count == 0))
		{
			return;
		}

		state.IsMutating = true;
		try
		{
			foreach (StatefulTransformEntry entry in GetStatefulTransformEntriesSnapshot(state))
			{
				if (entry?.Current == null || entry.Original == null || entry.Effect == null || !IsStatefulTransformTrackedCardPresent(entry.Current))
				{
					UnmarkStatefulTransformReplacement(entry?.Current);
					UnregisterStatefulTransformEntry(state, entry);
					continue;
				}

				CardPlay conditionPlay = BuildStatefulTransformConditionPlay(entry.Current);
				if (DoesStatefulTransformRevertConditionPass(combatState, entry.Current, conditionPlay, entry.Effect))
				{
					await RevertStatefulTransform(combatState, state, entry);
					continue;
				}

				if (entry.Duration != CardExtraEffectStatefulTransformDuration.UntilConditionStops)
				{
					continue;
				}

				if (!DoesStatefulTransformConditionPass(combatState, entry.Current, conditionPlay, entry.Effect))
				{
					await RevertStatefulTransform(combatState, state, entry);
				}
			}
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] Stateful transform condition refresh failed: {ex}");
		}
		finally
		{
			state.IsMutating = false;
		}
	}

	internal static async Task RunStatefulTransformsAfterPlayerTurnEnd(CombatState combatState)
	{
		if (combatState == null)
		{
			return;
		}

		StatefulTransformState state = _statefulTransformStates.GetOrCreateValue(combatState);
		if (state.IsMutating || (_statefulTransformEntries.Count == 0 && state.Entries.Count == 0))
		{
			return;
		}

		state.IsMutating = true;
		try
		{
			foreach (StatefulTransformEntry entry in GetStatefulTransformEntriesSnapshot(state))
			{
				if (entry?.Current == null || entry.Original == null || entry.Effect == null || !IsStatefulTransformTrackedCardPresent(entry.Current))
				{
					UnmarkStatefulTransformReplacement(entry?.Current);
					UnregisterStatefulTransformEntry(state, entry);
					continue;
				}

				bool shouldRevert = entry.Duration switch
				{
					_ when DoesStatefulTransformRevertConditionPass(combatState, entry.Current, BuildStatefulTransformConditionPlay(entry.Current), entry.Effect) => true,
					CardExtraEffectStatefulTransformDuration.ThisTurn => true,
					CardExtraEffectStatefulTransformDuration.Turns => --entry.RemainingTurns <= 0,
					CardExtraEffectStatefulTransformDuration.UntilConditionStops => !DoesStatefulTransformConditionPass(combatState, entry.Current, BuildStatefulTransformConditionPlay(entry.Current), entry.Effect),
					_ => false
				};
				if (shouldRevert)
				{
					await RevertStatefulTransform(combatState, state, entry);
				}
			}
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] Stateful transform turn cleanup failed: {ex}");
		}
		finally
		{
			state.IsMutating = false;
		}
	}

	internal static async Task RunStatefulTransformsAfterCombatEnd(CombatState combatState)
	{
		if (combatState == null)
		{
			return;
		}

		StatefulTransformState state = _statefulTransformStates.GetOrCreateValue(combatState);
		if (state.IsMutating || (_statefulTransformEntries.Count == 0 && state.Entries.Count == 0))
		{
			return;
		}

		state.IsMutating = true;
		try
		{
			foreach (StatefulTransformEntry entry in GetStatefulTransformEntriesSnapshot(state))
			{
				// Per-entry guard: this used to be a single try around the whole loop, so the first
				// entry that threw abandoned every remaining entry un-reverted and still registered.
				try
				{
					if (entry?.Current == null || entry.Original == null || entry.Effect == null || !IsStatefulTransformTrackedCardPresent(entry.Current))
					{
						UnmarkStatefulTransformReplacement(entry?.Current);
						UnregisterStatefulTransformEntry(state, entry);
						continue;
					}

					bool shouldRevert = entry.Duration switch
					{
						_ when DoesStatefulTransformRevertConditionPass(combatState, entry.Current, BuildStatefulTransformConditionPlay(entry.Current), entry.Effect) => true,
						CardExtraEffectStatefulTransformDuration.Run => false,
						CardExtraEffectStatefulTransformDuration.Combats => --entry.RemainingCombats <= 0,
						_ => true
					};
					if (shouldRevert)
					{
						await RevertStatefulTransform(combatState, state, entry);
					}
				}
				catch (Exception entryEx)
				{
					Log.Warn($"[CardEditor] Stateful transform combat cleanup failed for one entry (others continue): {entryEx.Message}");
					UnmarkStatefulTransformReplacement(entry?.Current);
					UnregisterStatefulTransformEntry(state, entry);
				}
			}
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] Stateful transform combat cleanup failed: {ex}");
		}
		finally
		{
			state.IsMutating = false;
		}
	}

	private static void AppendStatefulTransformMarkerEffects(List<CardExtraEffect> destination, CardModel templateCard, string? keywordFilter)
	{
		if (destination == null
			|| templateCard == null
			|| !_statefulTransformMarkers.TryGetValue(templateCard, out StatefulTransformMarker? marker)
			|| marker?.Entry?.Effect == null)
		{
			return;
		}

		CardExtraEffect effect = CloneEffect(marker.Entry.Effect);
		if (MatchesCustomKeywordFilter(effect, keywordFilter))
		{
			destination.Add(effect);
		}
	}

	// Vanilla cards declare a hover tip for every power they reference (ExtraHoverTips, e.g.
	// Abrasive); generate the same tips for powers and custom statuses applied by effect rows
	// so hovering the card in hand explains what it applies.
	internal static IReadOnlyList<IHoverTip> GetAppliedPowerHoverTips(CardModel? card, bool isUpgradePreview)
	{
		List<IHoverTip> tips = new();
		if (card == null)
		{
			return tips;
		}

		try
		{
			foreach (CardExtraEffect effect in GetEffectsForDescription(card, isUpgradePreview))
			{
				if (effect == null)
				{
					continue;
				}

				if (effect.AsPower && !string.IsNullOrWhiteSpace(effect.CustomPowerName))
				{
					tips.Add(CardEditorVanillaKeywordSupport.CreateDynamicHoverTip(
						effect.CustomPowerName.Trim(),
						effect.CustomPowerDescription ?? string.Empty));
					continue;
				}

				if (effect.Kind is not (CardExtraEffectKind.ApplyPower or CardExtraEffectKind.GainStatusEqualToStatus)
					|| string.IsNullOrWhiteSpace(effect.PowerId))
				{
					continue;
				}

				if (CardEditorCustomStatusRegistry.IsCustomStatusId(effect.PowerId))
				{
					CardEditorCustomStatusDefinition definition = CardEditorCustomStatusRegistry.Resolve(effect.PowerId);
					tips.Add(CardEditorVanillaKeywordSupport.CreateDynamicHoverTip(
						definition.Name ?? "Custom Status",
						definition.Description ?? string.Empty));
					continue;
				}

				if (TryResolveConfiguredPowerModel(effect.PowerId, out PowerModel? canonical) && canonical != null)
				{
					tips.Add(HoverTipFactory.FromPower(canonical, Math.Max(1, effect.Amount)));
				}
			}
		}
		catch
		{
			// Hover tips are cosmetic; never break card rendering over them.
		}

		return tips;
	}

	internal static IReadOnlyList<IHoverTip> GetAdditionalHoverPreviewTips(CardModel? card)
	{
		if (!HasCardEditorDescriptionSurface(card))
		{
			return Array.Empty<IHoverTip>();
		}

		List<IHoverTip> tips = new List<IHoverTip>();
		CombatState? combatState = ResolveCardCombatState(card);
		foreach (CardExtraEffect effect in GetRuntimeEffectsIncludingBorrowedSources(combatState, card))
		{
			if (!IsActivePassiveBehavior(effect, CardExtraEffectKind.HoverPreview))
			{
				continue;
			}

			if (!DoesBehaviorConditionPass(combatState, card, card, effect))
			{
				continue;
			}

			if (!TryResolveSpecificCardModel(effect.SpecificCardId, card, out CardModel previewCard))
			{
				continue;
			}

			tips.Add(new CardHoverTip(previewCard));
			try
			{
				tips.AddRange(previewCard.HoverTips ?? Array.Empty<IHoverTip>());
			}
			catch
			{
			}
		}

		return tips;
	}

	private static bool TryResolveSpecificCardModel(string? specificCardId, CardModel contextCard, out CardModel card)
	{
		card = null!;
		if (!TryParseSpecificCardId(specificCardId ?? string.Empty, out ModelId sourceId)
			|| sourceId == ModelId.none
			|| (contextCard?.Id != null && sourceId == contextCard.Id))
		{
			return false;
		}

		CardModel? canonical = ModelDb.GetByIdOrNull<CardModel>(sourceId);
		if (canonical == null)
		{
			return false;
		}

		CardModel result;
		try
		{
			result = CardEditorOverrides.BuildPreview(canonical);
		}
		catch
		{
			result = canonical;
		}

		MegaCrit.Sts2.Core.Entities.Players.Player? contextOwner = contextCard.TryGetOwner();
		MegaCrit.Sts2.Core.Entities.Players.Player? resultOwner = result.TryGetOwner();
		if (contextOwner != null && resultOwner == null)
		{
			if (!result.IsMutable)
			{
				try
				{
					result = (CardModel)result.MutableClone();
				}
				catch
				{
				}
			}
			if (result.IsMutable)
			{
				try
				{
					result.Owner = contextOwner;
				}
				catch
				{
				}
			}
		}

		int contextUpgradeLevel = contextCard.GetSafeCurrentUpgradeLevel();
		int resultUpgradeLevel = result.GetSafeCurrentUpgradeLevel();
		if (contextCard != null && contextUpgradeLevel > resultUpgradeLevel)
		{
			try
			{
				if (!result.IsMutable)
				{
					result = (CardModel)result.MutableClone();
				}

				resultUpgradeLevel = result.GetSafeCurrentUpgradeLevel();
				int upgrades = Math.Min(
					Math.Max(0, contextUpgradeLevel - resultUpgradeLevel),
					Math.Max(0, result.MaxUpgradeLevel - resultUpgradeLevel));
				for (int i = 0; i < upgrades; i++)
				{
					result.UpgradeInternal();
					result.FinalizeUpgradeInternal();
				}
			}
			catch
			{
				result = canonical;
			}
		}

		card = result;
		return true;
	}

	internal static bool TryGetCardPlayResultPileOverride(CardModel? card, out PileType pileType, out CardPilePosition position)
	{
		pileType = PileType.None;
		position = CardPilePosition.Bottom;
		if (card == null)
		{
			return false;
		}

		if (_oneShotCardPlayResultPileOverrides.TryGetValue(card, out OneShotCardPlayResultPileOverride? oneShot)
			&& oneShot != null)
		{
			_oneShotCardPlayResultPileOverrides.Remove(card);
			if (IsValidCardPlayResultPileOverride(oneShot.PileType))
			{
				pileType = oneShot.PileType;
				position = oneShot.Position;
				return true;
			}
		}

		CombatState? combatState = card.GetConcreteCombatState();
		foreach (CardExtraEffect effect in GetRuntimeEffectsIncludingBorrowedSources(combatState, card))
		{
			if (effect == null
				|| effect.Kind != CardExtraEffectKind.ResultPileOverride
				|| effect.AsPower
				|| effect.GrantToCard
				|| !IsValidEffectAmount(effect.Kind, effect.Amount))
			{
				continue;
			}

			PileType resolvedPile = ResolvePileType(effect.MoveToPile);
			if (!IsValidCardPlayResultPileOverride(resolvedPile))
			{
				continue;
			}

			pileType = resolvedPile;
			position = ResolvePilePosition(effect.MoveToPosition);
			return true;
		}

		return false;
	}

	internal static void SetOneShotCardPlayResultPileOverride(CardModel? card, PileType pileType, CardPilePosition position)
	{
		if (card == null || !IsValidCardPlayResultPileOverride(pileType))
		{
			return;
		}

		_oneShotCardPlayResultPileOverrides.Remove(card);
		_oneShotCardPlayResultPileOverrides.Add(card, new OneShotCardPlayResultPileOverride
		{
			PileType = pileType,
			Position = position
		});
	}

	internal static void ClearOneShotCardPlayResultPileOverride(CardModel? card)
	{
		if (card != null)
		{
			_oneShotCardPlayResultPileOverrides.Remove(card);
		}
	}

	private static bool IsValidCardPlayResultPileOverride(PileType pileType)
	{
		return pileType is PileType.Hand or PileType.Draw or PileType.Discard or PileType.Exhaust;
	}

	internal static bool CardHasRuntimeResourceConsumptionMode(CardModel? card, CardExtraEffectResourceConsumptionMode mode)
	{
		if (card == null)
		{
			return false;
		}

		return GetRuntimeEffectsIncludingBorrowedSources(card.GetConcreteCombatState(), card).Any(effect =>
			effect != null
			&& effect.Kind == CardExtraEffectKind.DoesNotConsumeVigor
			&& effect.ResourceConsumptionMode == mode
			&& IsValidEffectAmount(effect.Kind, effect.Amount));
	}

internal static bool CardHasRuntimeProtectedMultiplierStat(CardModel? card, CardExtraEffectMultiplierStat stat)
{
	if (card == null)
	{
		return false;
		}

		return GetRuntimeEffectsIncludingBorrowedSources(card.GetConcreteCombatState(), card).Any(effect =>
			effect != null
			&& effect.Kind == CardExtraEffectKind.DoesNotConsumeVigor
			&& IsValidEffectAmount(effect.Kind, effect.Amount)
			&& ((effect.ResourceConsumptionMode == CardExtraEffectResourceConsumptionMode.Vigor
					&& stat == CardExtraEffectMultiplierStat.Vigor)
				|| (effect.ResourceConsumptionMode == CardExtraEffectResourceConsumptionMode.SpecificStatStatus
					&& effect.ResourceConsumptionStat == stat)));
}

internal static bool CardHasRuntimeProtectedConfiguredPower(CardModel? card, ModelId powerId)
{
	if (card == null || powerId == ModelId.none)
	{
		return false;
	}

	return GetRuntimeEffectsIncludingBorrowedSources(card.GetConcreteCombatState(), card).Any(effect =>
	{
		if (effect == null
			|| effect.Kind != CardExtraEffectKind.DoesNotConsumeVigor
			|| !IsValidEffectAmount(effect.Kind, effect.Amount)
			|| effect.ResourceConsumptionMode != CardExtraEffectResourceConsumptionMode.SpecificPowerStatus
			|| string.IsNullOrWhiteSpace(effect.PowerId))
		{
			return false;
		}

		try
		{
			return ModelId.Deserialize(effect.PowerId.Trim()) == powerId;
		}
		catch
		{
			return false;
		}
	});
}

	private static bool TryGetProtectedMultiplierStat(Type? powerType, out CardExtraEffectMultiplierStat stat)
	{
		stat = CardExtraEffectMultiplierStat.Vigor;
		if (powerType == null)
		{
			return false;
		}

		if (powerType == typeof(StrengthPower)) { stat = CardExtraEffectMultiplierStat.Strength; return true; }
		if (powerType == typeof(DexterityPower)) { stat = CardExtraEffectMultiplierStat.Dexterity; return true; }
		if (powerType == typeof(FocusPower)) { stat = CardExtraEffectMultiplierStat.Focus; return true; }
		if (powerType == typeof(WeakPower)) { stat = CardExtraEffectMultiplierStat.Weak; return true; }
		if (powerType == typeof(FrailPower)) { stat = CardExtraEffectMultiplierStat.Frail; return true; }
		if (powerType == typeof(VulnerablePower)) { stat = CardExtraEffectMultiplierStat.Vulnerable; return true; }
		if (powerType == typeof(PoisonPower)) { stat = CardExtraEffectMultiplierStat.Poison; return true; }
		if (powerType == typeof(DoomPower)) { stat = CardExtraEffectMultiplierStat.Doom; return true; }
		if (powerType == typeof(ConstrictPower)) { stat = CardExtraEffectMultiplierStat.Constrict; return true; }
		if (powerType == typeof(ArtifactPower)) { stat = CardExtraEffectMultiplierStat.Artifact; return true; }
		if (powerType == typeof(ThornsPower)) { stat = CardExtraEffectMultiplierStat.Thorns; return true; }
		if (powerType == typeof(RegenPower)) { stat = CardExtraEffectMultiplierStat.Regen; return true; }
		if (powerType == typeof(PlatingPower)) { stat = CardExtraEffectMultiplierStat.Plating; return true; }
		if (powerType == typeof(IntangiblePower)) { stat = CardExtraEffectMultiplierStat.Intangible; return true; }
		if (powerType == typeof(BufferPower)) { stat = CardExtraEffectMultiplierStat.Buffer; return true; }
		if (powerType == typeof(VigorPower)) { stat = CardExtraEffectMultiplierStat.Vigor; return true; }
		if (powerType == typeof(BlurPower)) { stat = CardExtraEffectMultiplierStat.Blur; return true; }
		if (powerType == typeof(RitualPower)) { stat = CardExtraEffectMultiplierStat.Ritual; return true; }

		return false;
	}

private static bool ShouldPreserveSelfProtectedStat(CardPlay? cardPlay, Creature? ownerCreature, CardExtraEffectTarget target, CardExtraEffectMultiplierStat stat)
{
	return cardPlay?.Card != null
		&& ownerCreature != null
		&& target == CardExtraEffectTarget.Self
		&& CardHasRuntimeProtectedMultiplierStat(cardPlay.Card, stat);
}

private static bool ShouldPreserveSelfProtectedConfiguredPower(CardPlay? cardPlay, Creature? ownerCreature, CardExtraEffectTarget target, ModelId powerId)
{
	return cardPlay?.Card != null
		&& ownerCreature != null
		&& target == CardExtraEffectTarget.Self
		&& CardHasRuntimeProtectedConfiguredPower(cardPlay.Card, powerId);
}

private static bool ShouldPreserveSelfProtectedPower(CardPlay? cardPlay, Creature? ownerCreature, CardExtraEffectTarget target, PowerModel? powerModel)
{
	if (powerModel == null)
	{
		return false;
	}

	if (ShouldPreserveSelfProtectedConfiguredPower(cardPlay, ownerCreature, target, powerModel.Id))
	{
		return true;
	}

	return TryGetProtectedMultiplierStat(powerModel.GetType(), out CardExtraEffectMultiplierStat stat)
		&& ShouldPreserveSelfProtectedStat(cardPlay, ownerCreature, target, stat);
}

	private static void AppendRuntimeEffectsIncludingBorrowedSources(
		List<CardExtraEffect> destination,
		CombatState? combatState,
		CardModel templateCard,
		bool includeTemporaryEffects,
		HashSet<ModelId> effectSourceGuard,
		string? keywordFilter = null)
	{
		if (destination == null || templateCard == null)
		{
			return;
		}

		IReadOnlyList<CardExtraEffect> overrideEffects = Array.Empty<CardExtraEffect>();
		if (CardEditorOverrides.TryGetEffectiveOverride(templateCard, out CardOverride overrideData))
		{
			overrideEffects = GetEffectiveExtraEffects(templateCard, overrideData, templateCard.GetSafeCurrentUpgradeLevel() > 0);
		}

		bool hasInlineEffectSources = false;
		foreach (CardExtraEffect effect in overrideEffects)
		{
			if (effect == null)
			{
				continue;
			}
			if (!MatchesCustomKeywordFilter(effect, keywordFilter))
			{
				continue;
			}

			destination.Add(effect);
			if (effect.Kind == CardExtraEffectKind.RunEffectSourceCard)
			{
				// Keep runtime execution single-sourced through ExecuteEffect -> RunSingleEffectSourceOnPlay.
				// If we eagerly splice the source card's runtime effects into the host list here, the host card
				// executes the borrowed source once inline and then a second time through the effect-source runner.
				hasInlineEffectSources = true;
			}
		}

		AppendStatefulTransformMarkerEffects(destination, templateCard, keywordFilter);

		if (templateCard is CardEditorCreatedCardBase && !hasInlineEffectSources)
		{
			List<CardExtraEffect> borrowedEffects = BuildLegacyBorrowedRuntimeEffects(combatState, templateCard, effectSourceGuard, keywordFilter);
			if (borrowedEffects.Count > 0)
			{
				if (CardEditorCreatedCardsStore.GetEffectSourcePlacement(templateCard.Id) == CardEditorEffectSourcePlacement.BeforeCustomEffects)
				{
					destination.InsertRange(0, borrowedEffects);
				}
				else
				{
					destination.AddRange(borrowedEffects);
				}
			}
		}

		if (!includeTemporaryEffects || combatState == null)
		{
			return;
		}

		IReadOnlyList<CardExtraEffect> temporaryEffects = GetActiveGrantedExtraEffects(combatState, templateCard);
		if (temporaryEffects.Count > 0)
		{
			foreach (CardExtraEffect effect in temporaryEffects)
			{
				if (effect == null)
				{
					continue;
				}
				if (!MatchesCustomKeywordFilter(effect, keywordFilter))
				{
					continue;
				}

				destination.Add(effect);
				if (effect.Kind == CardExtraEffectKind.RunEffectSourceCard)
				{
					AppendBorrowedInspectionEffectsFromSourceId(
						destination,
						combatState,
						templateCard,
						effect.SpecificCardId,
						effectSourceGuard,
						effect.CustomKeywordName);
				}
			}
		}
	}

	private static List<CardExtraEffect> BuildLegacyBorrowedRuntimeEffects(CombatState? combatState, CardModel templateCard, HashSet<ModelId> effectSourceGuard, string? keywordFilter = null)
	{
		List<CardExtraEffect> borrowedEffects = new List<CardExtraEffect>();
		foreach (ModelId sourceId in CardEditorCreatedCardEffectSourceSupport.GetRuntimeEffectSourceIds(templateCard, isUpgradePreview: false))
		{
			AppendBorrowedRuntimeEffectsFromSourceId(borrowedEffects, combatState, templateCard, sourceId, effectSourceGuard, keywordFilter);
		}

		return borrowedEffects;
	}

	internal static IReadOnlyList<CardExtraEffect> GetRuntimeEffectsForBorrowedSource(CombatState? combatState, CardModel hostCard, ModelId effectSourceId, string? keywordFilter = null)
	{
		List<CardExtraEffect> borrowedEffects = new List<CardExtraEffect>();
		AppendBorrowedRuntimeEffectsFromSourceId(
			borrowedEffects,
			combatState,
			hostCard,
			effectSourceId,
			new HashSet<ModelId>(),
			keywordFilter);
		return borrowedEffects;
	}

	internal static IReadOnlyList<CardExtraEffect> GetRuntimeEffectsForExecution(CombatState? combatState, CardModel card)
	{
		if (card == null)
		{
			return Array.Empty<CardExtraEffect>();
		}

		if (combatState != null)
		{
			CardEditorRunSelfScalingState.TryRestoreCard(card, combatState.RunState);
			return GetRuntimeEffectsForModifierInspection(combatState, card);
		}

		return GetRuntimeEffectsIncludingBorrowedSources(null, card);
	}

	private static IReadOnlyList<CardExtraEffect> GetRuntimeEffectsForModifierInspection(CombatState combatState, CardModel card)
	{
		if (card == null)
		{
			return Array.Empty<CardExtraEffect>();
		}

		List<CardExtraEffect> effects = new List<CardExtraEffect>();
		HashSet<ModelId> effectSourceGuard = new HashSet<ModelId>();
		if (card.Id != null && card.Id != ModelId.none)
		{
			effectSourceGuard.Add(card.Id);
		}

		AppendRuntimeEffectsForModifierInspection(effects, combatState, card, effectSourceGuard);
		return effects;
	}

	private static void AppendRuntimeEffectsForModifierInspection(
		List<CardExtraEffect> destination,
		CombatState combatState,
		CardModel templateCard,
		HashSet<ModelId> effectSourceGuard,
		string? keywordFilter = null)
	{
		if (destination == null || templateCard == null)
		{
			return;
		}

		IReadOnlyList<CardExtraEffect> overrideEffects = Array.Empty<CardExtraEffect>();
		if (CardEditorOverrides.TryGetEffectiveOverride(templateCard, out CardOverride overrideData))
		{
			overrideEffects = GetEffectiveExtraEffects(templateCard, overrideData, templateCard.GetSafeCurrentUpgradeLevel() > 0);
		}

		bool hasInlineEffectSources = false;
		foreach (CardExtraEffect effect in overrideEffects)
		{
			if (effect == null)
			{
				continue;
			}
			if (!MatchesCustomKeywordFilter(effect, keywordFilter))
			{
				continue;
			}

			destination.Add(effect);
			if (effect.Kind == CardExtraEffectKind.RunEffectSourceCard)
			{
				hasInlineEffectSources = true;
				AppendBorrowedInspectionEffectsFromSourceId(destination, combatState, templateCard, effect.SpecificCardId, effectSourceGuard, effect.CustomKeywordName);
			}
		}

		AppendStatefulTransformMarkerEffects(destination, templateCard, keywordFilter);

		if (templateCard is CardEditorCreatedCardBase && !hasInlineEffectSources)
		{
			List<CardExtraEffect> borrowedEffects = new List<CardExtraEffect>();
			foreach (ModelId sourceId in CardEditorCreatedCardEffectSourceSupport.GetRuntimeEffectSourceIds(templateCard, isUpgradePreview: false))
			{
				AppendBorrowedInspectionEffectsFromSourceId(borrowedEffects, combatState, templateCard, sourceId, effectSourceGuard, keywordFilter);
			}

			if (borrowedEffects.Count > 0)
			{
				if (CardEditorCreatedCardsStore.GetEffectSourcePlacement(templateCard.Id) == CardEditorEffectSourcePlacement.BeforeCustomEffects)
				{
					destination.InsertRange(0, borrowedEffects);
				}
				else
				{
					destination.AddRange(borrowedEffects);
				}
			}
		}

		IReadOnlyList<CardExtraEffect> temporaryEffects = GetActiveGrantedExtraEffects(combatState, templateCard);
		if (temporaryEffects.Count > 0)
		{
			destination.AddRange(temporaryEffects);
		}
	}

	private static void AppendBorrowedInspectionEffectsFromSourceId(
		List<CardExtraEffect> destination,
		CombatState? combatState,
		CardModel hostCard,
		string? effectSourceIdText,
		HashSet<ModelId> effectSourceGuard,
		string? keywordFilter)
	{
		if (!TryParseEffectSourceModelId(effectSourceIdText, out ModelId effectSourceId))
		{
			return;
		}

		AppendBorrowedInspectionEffectsFromSourceId(destination, combatState, hostCard, effectSourceId, effectSourceGuard, keywordFilter);
	}

	private static void AppendBorrowedInspectionEffectsFromSourceId(
		List<CardExtraEffect> destination,
		CombatState? combatState,
		CardModel hostCard,
		ModelId effectSourceId,
		HashSet<ModelId> effectSourceGuard,
		string? keywordFilter)
	{
		if (destination == null || hostCard == null || combatState == null || effectSourceId == null || effectSourceId == ModelId.none)
		{
			return;
		}

		if (!effectSourceGuard.Add(effectSourceId))
		{
			return;
		}

		try
		{
			CardModel? sourceCard = CardEditorCreatedCardEffectSourceSupport.BuildRuntimeEffectSourceCard(hostCard, effectSourceId, isUpgradePreview: false);
			if (sourceCard == null)
			{
				return;
			}

			AppendRuntimeEffectsForModifierInspection(destination, combatState, sourceCard, effectSourceGuard, keywordFilter);
		}
		finally
		{
			effectSourceGuard.Remove(effectSourceId);
		}
	}

	private static void AppendBorrowedRuntimeEffectsFromSourceId(
		List<CardExtraEffect> destination,
		CombatState? combatState,
		CardModel hostCard,
		string? effectSourceIdText,
		HashSet<ModelId> effectSourceGuard,
		string? keywordFilter)
	{
		if (!TryParseEffectSourceModelId(effectSourceIdText, out ModelId effectSourceId))
		{
			return;
		}

		AppendBorrowedRuntimeEffectsFromSourceId(destination, combatState, hostCard, effectSourceId, effectSourceGuard, keywordFilter);
	}

	private static void AppendBorrowedRuntimeEffectsFromSourceId(
		List<CardExtraEffect> destination,
		CombatState? combatState,
		CardModel hostCard,
		ModelId effectSourceId,
		HashSet<ModelId> effectSourceGuard,
		string? keywordFilter)
	{
		if (destination == null || hostCard == null || effectSourceId == null || effectSourceId == ModelId.none)
		{
			return;
		}

		if (!effectSourceGuard.Add(effectSourceId))
		{
			return;
		}

		try
		{
			CardModel? sourceCard = CardEditorCreatedCardEffectSourceSupport.BuildRuntimeEffectSourceCard(hostCard, effectSourceId, isUpgradePreview: false);
			if (sourceCard == null)
			{
				return;
			}

			AppendBorrowedVanillaHookEffects(destination, sourceCard, keywordFilter);
			AppendRuntimeEffectsIncludingBorrowedSources(destination, combatState, sourceCard, includeTemporaryEffects: false, effectSourceGuard, keywordFilter);
		}
		finally
		{
			effectSourceGuard.Remove(effectSourceId);
		}
	}

	private static void AppendBorrowedVanillaHookEffects(List<CardExtraEffect> destination, CardModel sourceCard, string? keywordFilter)
	{
		if (destination == null || sourceCard == null || !string.IsNullOrWhiteSpace(keywordFilter))
		{
			return;
		}

		if (!HasCustomPrePlayPhaseHook(sourceCard))
		{
			return;
		}

		destination.Add(new CardExtraEffect
		{
			Kind = CardExtraEffectKind.AutoPlaySelfFromPile,
			Amount = 1,
			Trigger = CardExtraEffectTrigger.TurnBoundary,
			TurnBoundary = CardExtraEffectTurnBoundary.StartAfterDraw,
			TurnBoundarySide = CardExtraEffectTurnBoundarySide.YourTurn,
			TurnBoundaryCardLocation = CardExtraEffectTurnBoundaryCardLocation.ExhaustPile,
			CardSelectionPile = CardExtraEffectCardPile.ExhaustPile,
			CardSelectionMode = CardExtraEffectCardSelectionMode.All,
			Target = CardExtraEffectTarget.Self
		});
	}

	private static bool HasCustomPrePlayPhaseHook(CardModel sourceCard)
	{
		try
		{
			return HasCustomHookOverride(sourceCard, "AfterAutoPrePlayPhaseEnteredEarly")
				|| HasCustomHookOverride(sourceCard, "BeforePlayPhaseStart");
		}
		catch
		{
			return false;
		}
	}

	private static bool HasCustomHookOverride(CardModel sourceCard, string methodName)
	{
		MethodInfo? method = sourceCard.GetType().GetMethod(
			methodName,
			BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
		return method?.DeclaringType != null
			&& method.DeclaringType != typeof(AbstractModel)
			&& method.DeclaringType != typeof(CardModel);
	}

	private static bool TryParseEffectSourceModelId(string? text, out ModelId id)
	{
		try
		{
			if (string.IsNullOrWhiteSpace(text))
			{
				id = ModelId.none;
				return false;
			}

			id = ModelId.Deserialize(text.Trim());
			return id != null && id != ModelId.none;
		}
		catch
		{
			id = ModelId.none;
			return false;
		}
	}

	private static bool MatchesCustomKeywordFilter(CardExtraEffect? effect, string? keywordFilter)
	{
		string? normalizedFilter = NormalizeCustomKeywordName(keywordFilter);
		if (normalizedFilter == null)
		{
			return true;
		}

		return string.Equals(NormalizeCustomKeywordName(effect?.CustomKeywordName), normalizedFilter, StringComparison.OrdinalIgnoreCase);
	}

	private static string? NormalizeCustomKeywordName(string? value)
	{
		return CardEditorPhraseComposer.NormalizeCustomName(value);
	}

	private static void EnsureGrantPackageKey(CardExtraEffect? effect)
	{
		if (effect == null || !string.IsNullOrWhiteSpace(effect.GrantPackageKey))
		{
			return;
		}

		effect.GrantPackageKey = BuildKeywordEffectSourceGrantPackageKey(effect);
	}

	private static string? GetCanonicalGrantPackageKey(CardExtraEffect? effect)
	{
		if (effect == null)
		{
			return null;
		}

		string key = effect.GrantPackageKey?.Trim() ?? string.Empty;
		if (!string.IsNullOrWhiteSpace(key))
		{
			return key;
		}

		return BuildKeywordEffectSourceGrantPackageKey(effect);
	}

	private static string? BuildKeywordEffectSourceGrantPackageKey(CardExtraEffect? effect)
	{
		if (effect == null || effect.Kind != CardExtraEffectKind.RunEffectSourceCard)
		{
			return null;
		}

		string? keyword = NormalizeCustomKeywordName(effect.CustomKeywordName);
		if (keyword == null)
		{
			return null;
		}

		return "custom-keyword:" + keyword.ToUpperInvariant();
	}

	private static bool ShouldSkipKeywordPackageGrantToCard(CardModel card, CardExtraEffect effect)
	{
		if (card == null || effect == null || effect.Kind != CardExtraEffectKind.RunEffectSourceCard)
		{
			return false;
		}

		string? keyword = NormalizeCustomKeywordName(effect.CustomKeywordName);
		if (keyword == null)
		{
			return false;
		}

		return CardHasCustomKeyword(card, keyword);
	}

	private static string? FormatCustomKeywordCardLine(CardModel card, CardExtraEffect effect, string? keywordName, bool isUpgradePreview)
	{
		if (card == null || effect == null || string.IsNullOrWhiteSpace(keywordName))
		{
			return null;
		}

		if (IsSelfScalingKind(effect.Kind) || effect.Kind == CardExtraEffectKind.LinkedCardAction)
		{
			string amountText = FormatSelfScalingAmountText(card, effect, isUpgradePreview);
			return CardEditorLoc.F(
				"cardText.customKeyword.amount",
				$"[gold]{keywordName}[/gold] {amountText}.",
				("Keyword", keywordName),
				("Amount", amountText));
		}

		return null;
	}

	private static List<DescriptionEffectLine> BuildDescriptionEffectLines(CardModel card, Creature? target, bool isUpgradePreview)
	{
		if (!HasCardEditorDescriptionSurface(card))
		{
			return new List<DescriptionEffectLine>();
		}

		bool considerUpgrade = isUpgradePreview || card.GetSafeCurrentUpgradeLevel() > 0;
		int? upgradeApplicationCountOverride = GetDescriptionUpgradeApplicationCountOverride(card, isUpgradePreview);

		bool hasOverride = TryGetOverrideForDescription(card, considerUpgrade, upgradeApplicationCountOverride, out CardOverride? overrideData, out IReadOnlyList<CardExtraEffect> effectiveEffects);
		CombatState? combatState = card.GetConcreteCombatState();
		IReadOnlyList<CardExtraEffect> temporaryEffects = GetActiveGrantedExtraEffects(combatState, card);

		List<(CardExtraEffect Effect, DescriptionUpgradeComparison UpgradeComparison, bool IsTemporary)> toRender = new List<(CardExtraEffect, DescriptionUpgradeComparison, bool)>();
		if (hasOverride)
		{
			bool wantsUpgradeDiffHighlight = isUpgradePreview;
			List<(CardExtraEffect Effect, DescriptionUpgradeComparison UpgradeComparison)> baseList = wantsUpgradeDiffHighlight
				? BuildUpgradePreviewEffects(overrideData!, effectiveEffects)
				: effectiveEffects.Select(e => (e, DescriptionUpgradeComparison.None)).ToList();
			if (baseList.Count > 0)
			{
				toRender.AddRange(baseList.Select(t => (t.Effect, t.UpgradeComparison, false)));
			}
		}
		if (temporaryEffects.Count > 0)
		{
			toRender.AddRange(temporaryEffects.Select(e => (e, DescriptionUpgradeComparison.None, true)));
		}

		HashSet<string> autoActionPayloadIds = BuildAutoActionPayloadIdSet(toRender.Select(t => t.Effect));
		List<DescriptionEffectLine> lines = new List<DescriptionEffectLine>();
		foreach ((CardExtraEffect effect, DescriptionUpgradeComparison upgradeComparison, bool isTemporary) in toRender)
		{
			if (!IsRenderableDescriptionEffect(effect))
			{
				continue;
			}
			if (IsAutoActionPayloadEffect(effect, autoActionPayloadIds))
			{
				continue;
			}
			if (card.GetConcreteCombatState() != null
				&& isTemporary
				&& effect.Kind == CardExtraEffectKind.CardCostsLess
				&& !IsPowerEffect(effect)
				&& !effect.GrantToCard)
			{
				bool hasMatchingBase = toRender.Any(e =>
					!e.IsTemporary
					&& e.Effect != null
					&& IsEquivalentTimedCardCostsLess(e.Effect, effect));
				if (hasMatchingBase)
				{
					continue;
				}
			}

			string? line = TryFormatLine(card, effect, target, upgradeComparison, isUpgradePreview: isUpgradePreview);
			if (string.IsNullOrWhiteSpace(line))
			{
				continue;
			}

			string? customKeywordName = NormalizeCustomKeywordName(effect.CustomKeywordName);
			lines.Add(new DescriptionEffectLine
			{
				Line = line!,
				CustomKeywordName = customKeywordName,
				CustomKeywordCardLine = FormatCustomKeywordCardLine(card, effect, customKeywordName, isUpgradePreview),
				Trigger = effect.Trigger
			});
		}

		return MergeDescriptionEffectLines(lines);
	}

	internal static IReadOnlyList<string> GetLiveNumberFallbackTokensForDescription(CardModel? card, bool isUpgradePreview)
	{
		if (card == null || !HasCardEditorDescriptionSurface(card))
		{
			return Array.Empty<string>();
		}

		try
		{
			bool considerUpgrade = isUpgradePreview || card.GetSafeCurrentUpgradeLevel() > 0;
			int? upgradeApplicationCountOverride = GetDescriptionUpgradeApplicationCountOverride(card, isUpgradePreview);
			bool hasOverride = TryGetOverrideForDescription(
				card,
				considerUpgrade,
				upgradeApplicationCountOverride,
				out CardOverride? overrideData,
				out IReadOnlyList<CardExtraEffect> effectiveEffects);
			CombatState? combatState = card.GetConcreteCombatState();
			IReadOnlyList<CardExtraEffect> temporaryEffects = GetActiveGrantedExtraEffects(combatState, card);

			List<(CardExtraEffect Effect, bool IsTemporary)> toRender = new List<(CardExtraEffect, bool)>();
			if (hasOverride)
			{
				IEnumerable<CardExtraEffect> baseEffects = isUpgradePreview
					? BuildUpgradePreviewEffects(overrideData!, effectiveEffects).Select(e => e.Effect)
					: effectiveEffects;
				toRender.AddRange(baseEffects.Select(e => (e, false)));
			}
			if (temporaryEffects.Count > 0)
			{
				toRender.AddRange(temporaryEffects.Select(e => (e, true)));
			}

			if (toRender.Count == 0)
			{
				return Array.Empty<string>();
			}

			HashSet<string> autoActionPayloadIds = BuildAutoActionPayloadIdSet(toRender.Select(t => t.Effect));
			List<string> tokens = new List<string>();
			foreach ((CardExtraEffect effect, bool isTemporary) in toRender)
			{
				if (!IsRenderableDescriptionEffect(effect) || ShouldSkipDirectEffect(effect, autoActionPayloadIds))
				{
					continue;
				}
				if (combatState != null
					&& isTemporary
					&& effect.Kind == CardExtraEffectKind.CardCostsLess
					&& !IsPowerEffect(effect)
					&& !effect.GrantToCard
					&& toRender.Any(e => !e.IsTemporary && IsEquivalentTimedCardCostsLess(e.Effect, effect)))
				{
					continue;
				}

				AddLiveNumberFallbackTokensForEffect(effect, tokens);
			}

			return tokens;
		}
		catch
		{
			return Array.Empty<string>();
		}
	}

	internal static IReadOnlyDictionary<string, string> GetStableLiveNumberTokensForDescription(CardModel? card, bool isUpgradePreview)
	{
		if (card == null || !HasCardEditorDescriptionSurface(card))
		{
			return new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
		}

		try
		{
			bool considerUpgrade = isUpgradePreview || card.GetSafeCurrentUpgradeLevel() > 0;
			int? upgradeApplicationCountOverride = GetDescriptionUpgradeApplicationCountOverride(card, isUpgradePreview);
			bool hasOverride = TryGetOverrideForDescription(
				card,
				considerUpgrade,
				upgradeApplicationCountOverride,
				out CardOverride? overrideData,
				out IReadOnlyList<CardExtraEffect> effectiveEffects);
			CombatState? combatState = card.GetConcreteCombatState();
			IReadOnlyList<CardExtraEffect> temporaryEffects = GetActiveGrantedExtraEffects(combatState, card);

			List<(CardExtraEffect Effect, bool IsTemporary)> toRender = new List<(CardExtraEffect, bool)>();
			if (hasOverride)
			{
				IEnumerable<CardExtraEffect> baseEffects = isUpgradePreview
					? BuildUpgradePreviewEffects(overrideData!, effectiveEffects).Select(e => e.Effect)
					: effectiveEffects;
				toRender.AddRange(baseEffects.Where(e => e != null).Select(e => (e, false)));
			}
			if (temporaryEffects.Count > 0)
			{
				toRender.AddRange(temporaryEffects.Where(e => e != null).Select(e => (e, true)));
			}

			if (toRender.Count == 0)
			{
				return new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
			}

			HashSet<string> autoActionPayloadIds = BuildAutoActionPayloadIdSet(toRender.Select(t => t.Effect));
			Dictionary<string, string> tokens = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
			foreach ((CardExtraEffect effect, bool isTemporary) in toRender)
			{
				if (string.IsNullOrWhiteSpace(effect.EffectId)
					|| !IsRenderableDescriptionEffect(effect)
					|| ShouldSkipDirectEffect(effect, autoActionPayloadIds))
				{
					continue;
				}
				if (combatState != null
					&& isTemporary
					&& effect.Kind == CardExtraEffectKind.CardCostsLess
					&& !IsPowerEffect(effect)
					&& !effect.GrantToCard
					&& toRender.Any(e => !e.IsTemporary && IsEquivalentTimedCardCostsLess(e.Effect, effect)))
				{
					continue;
				}

				List<string> values = new List<string>();
				AddLiveNumberFallbackTokensForEffect(effect, values);
				if (values.Count == 0)
				{
					continue;
				}

				for (int i = 0; i < values.Count; i++)
				{
					string token = CardEditorDescriptionNumberHighlighter.BuildStableEffectAmountToken(effect.EffectId, i + 1);
					tokens[token] = values[i];
					if (i == 0)
					{
						tokens[CardEditorDescriptionNumberHighlighter.BuildStableEffectAmountToken(effect.EffectId)] = values[i];
					}
				}
			}

			return tokens;
		}
		catch
		{
			return new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
		}
	}

	internal static IReadOnlyList<string> GetStableLiveNumberTokenIdsForEffect(CardExtraEffect? effect)
	{
		if (effect == null || string.IsNullOrWhiteSpace(effect.EffectId))
		{
			return Array.Empty<string>();
		}

		List<string> values = new List<string>();
		AddLiveNumberFallbackTokensForEffect(effect, values);
		if (values.Count == 0)
		{
			return Array.Empty<string>();
		}

		List<string> tokens = new List<string>(values.Count);
		for (int i = 0; i < values.Count; i++)
		{
			tokens.Add(CardEditorDescriptionNumberHighlighter.BuildStableEffectAmountToken(effect.EffectId, i + 1));
		}
		return tokens;
	}

	private static void AddLiveNumberFallbackTokensForEffect(CardExtraEffect effect, List<string> tokens)
	{
		if (effect == null)
		{
			return;
		}

		switch (effect.Kind)
		{
			case CardExtraEffectKind.AddRandomCardToHand:
			case CardExtraEffectKind.PlayRandomGeneratedCard:
			case CardExtraEffectKind.AddSpecificCardToHand:
				AddPrimaryAmountFallbackToken(effect, tokens);
				return;
			case CardExtraEffectKind.ChooseOneOfThreeCardsToHand:
				AddSelectionFallbackTokens(effect, tokens);
				if (!effect.AmountIsX && effect.Amount > 1)
				{
					AddPrimaryAmountFallbackToken(effect, tokens);
				}
				return;
			case CardExtraEffectKind.AddCardReward:
				AddLiveNumberFallbackToken(tokens, effect.Amount);
				AddSelectionFallbackTokens(effect, tokens);
				return;
			case CardExtraEffectKind.SelectCardsFromPile:
			case CardExtraEffectKind.TargetCardMutation:
			case CardExtraEffectKind.PersistentTargetCardMutation:
			case CardExtraEffectKind.LinkedCardAction:
				AddSelectionFallbackTokens(effect, tokens);
				AddPrimaryAmountFallbackToken(effect, tokens);
				return;
			case CardExtraEffectKind.DisplayNumber:
				AddLiveNumberFallbackToken(tokens, FormatDisplayNumberAmountText(effect));
				return;
			case CardExtraEffectKind.Quest:
				AddPrimaryAmountFallbackToken(effect, tokens);
				if (effect.QuestCompletionLimit > 1)
				{
					AddLiveNumberFallbackToken(tokens, Math.Clamp(effect.QuestCompletionLimit, 1, 999));
				}
				return;
			default:
				AddPrimaryAmountFallbackToken(effect, tokens);
				AddRepeatFallbackToken(effect, tokens);
				return;
		}
	}

	private static void AddPrimaryAmountFallbackToken(CardExtraEffect effect, List<string> tokens)
	{
		if (effect.AmountIsX || !IsValidEffectAmount(effect.Kind, effect.Amount))
		{
			return;
		}

		AddLiveNumberFallbackToken(tokens, effect.Amount);
	}

	private static void AddSelectionFallbackTokens(CardExtraEffect effect, List<string> tokens)
	{
		if (!effect.CardSelectionCountIsX && effect.CardSelectionCount > 0)
		{
			AddLiveNumberFallbackToken(tokens, effect.CardSelectionCount);
		}
		if (effect.CardSelectionOfferCount > 0)
		{
			AddLiveNumberFallbackToken(tokens, effect.CardSelectionOfferCount);
		}
	}

	private static void AddRepeatFallbackToken(CardExtraEffect effect, List<string> tokens)
	{
		if (!effect.RepeatIsX && effect.RepeatCount > 1)
		{
			AddLiveNumberFallbackToken(tokens, effect.RepeatCount);
		}
	}

	private static void AddLiveNumberFallbackToken(List<string> tokens, int value)
	{
		tokens.Add(value.ToString(CultureInfo.InvariantCulture));
	}

	private static void AddLiveNumberFallbackToken(List<string> tokens, string value)
	{
		if (!string.IsNullOrWhiteSpace(value))
		{
			tokens.Add(value);
		}
	}

	private static HashSet<string> BuildAutoActionPayloadIdSet(IEnumerable<CardExtraEffect?> effects)
	{
		HashSet<string> ids = new HashSet<string>(StringComparer.Ordinal);
		if (effects == null)
		{
			return ids;
		}

		foreach (CardExtraEffect? effect in effects)
		{
			if (effect?.Kind is not (CardExtraEffectKind.ConditionalAutoRunEffects or CardExtraEffectKind.CountdownEffect or CardExtraEffectKind.Quest))
			{
				continue;
			}

			foreach (string id in ParseAutoActionEffectIds(effect))
			{
				if (!string.Equals(id, effect.EffectId ?? string.Empty, StringComparison.Ordinal))
				{
					ids.Add(id);
				}
			}
		}

		return ids;
	}

	private static bool IsAutoActionPayloadEffect(CardExtraEffect? effect, HashSet<string>? autoActionPayloadIds)
	{
		return effect != null
			&& autoActionPayloadIds != null
			&& autoActionPayloadIds.Count > 0
			&& !string.IsNullOrWhiteSpace(effect.EffectId)
			&& autoActionPayloadIds.Contains(effect.EffectId);
	}

	private static bool ShouldSkipDirectEffect(CardExtraEffect? effect, HashSet<string>? autoActionPayloadIds)
	{
		return effect == null
			|| effect.PayloadOnly
			|| IsAutoActionPayloadEffect(effect, autoActionPayloadIds);
	}

	private static List<string> ParseAutoActionEffectIds(CardExtraEffect? effect)
	{
		return effect == null ? new List<string>() : ParseDelimitedEffectIds(effect.AutoActionEffectIds);
	}

	internal static string? FormatSingleEffectLine(
		CardModel card,
		CardExtraEffect effect,
		Creature? target = null,
		bool isUpgradePreview = false,
		object? useLimitSourceInstance = null)
	{
		if (card == null || !IsRenderableDescriptionEffect(effect))
		{
			return null;
		}

		IDisposable? useLimitScope = useLimitSourceInstance != null
			? CardEditorAutoPlayLoopGuard.PushUseLimitSourceInstance(useLimitSourceInstance)
			: null;
		try
		{
			string? line = TryFormatLine(card, effect, target, DescriptionUpgradeComparison.None, isUpgradePreview);
			if (string.IsNullOrWhiteSpace(line))
			{
				return null;
			}

			return CardEditorVanillaKeywordSupport.FormatDescription(card, line!, target, isUpgradePreview);
		}
		finally
		{
			useLimitScope?.Dispose();
		}
	}

	private enum DescriptionLineMergeMode
	{
		None = 0,
		SharedPrefix = 1,
		SharedSuffix = 2
	}

	private readonly struct DescriptionUpgradeComparison
	{
		public static readonly DescriptionUpgradeComparison None = new DescriptionUpgradeComparison(0, 0, 0, 0);

		public DescriptionUpgradeComparison(int amount, int repeat, int historyCountStep = 0, int repeatScalingExtraTimes = 0)
		{
			Amount = amount;
			Repeat = repeat;
			HistoryCountStep = historyCountStep;
			RepeatScalingExtraTimes = repeatScalingExtraTimes;
		}

		public int Amount { get; }
		public int Repeat { get; }
		public int HistoryCountStep { get; }
		public int RepeatScalingExtraTimes { get; }
	}

	private static List<DescriptionEffectLine> MergeDescriptionEffectLines(List<DescriptionEffectLine> lines)
	{
		if (lines == null || lines.Count <= 1)
		{
			return lines ?? new List<DescriptionEffectLine>();
		}

		List<DescriptionEffectLine> merged = new List<DescriptionEffectLine>(lines.Count);
		for (int index = 0; index < lines.Count; index++)
		{
			DescriptionEffectLine current = lines[index];
			if (!TryGetMergeParts(current.Line, out DescriptionLineMergeMode mode, out string sharedText, out string payload))
			{
				merged.Add(current);
				continue;
			}

			List<string> payloads = new List<string> { payload };
			int lastMergedIndex = index;
			for (int nextIndex = index + 1; nextIndex < lines.Count; nextIndex++)
			{
				DescriptionEffectLine next = lines[nextIndex];
				if (!string.IsNullOrWhiteSpace(next.CustomKeywordName)
					|| !string.IsNullOrWhiteSpace(current.CustomKeywordName)
					|| next.Trigger != current.Trigger
					|| !TryGetMergeParts(next.Line, out DescriptionLineMergeMode nextMode, out string nextSharedText, out string nextPayload)
					|| nextMode != mode
					|| !string.Equals(nextSharedText, sharedText, StringComparison.Ordinal))
				{
					break;
				}

				payloads.Add(nextPayload);
				lastMergedIndex = nextIndex;
			}

			if (payloads.Count == 1)
			{
				merged.Add(current);
				continue;
			}

			string joinedPayload = JoinDescriptionPayloads(payloads);
			string mergedLine = mode == DescriptionLineMergeMode.SharedPrefix
				? sharedText + joinedPayload + "."
				: joinedPayload + sharedText;

			merged.Add(new DescriptionEffectLine
			{
				Line = mergedLine,
				CustomKeywordName = current.CustomKeywordName,
				CustomKeywordCardLine = current.CustomKeywordCardLine,
				Trigger = current.Trigger
			});

			index = lastMergedIndex;
		}

		return merged;
	}

	private static bool TryGetMergeParts(string line, out DescriptionLineMergeMode mode, out string sharedText, out string payload)
	{
		mode = DescriptionLineMergeMode.None;
		sharedText = string.Empty;
		payload = string.Empty;

		if (string.IsNullOrWhiteSpace(line) || line.Contains('\n'))
		{
			return false;
		}

		string trimmed = line.Trim();
		foreach (string marker in GetMergeSuffixMarkers())
		{
			int suffixIndex = trimmed.IndexOf(marker, StringComparison.Ordinal);
			if (suffixIndex > 0)
			{
				mode = DescriptionLineMergeMode.SharedSuffix;
				sharedText = trimmed[suffixIndex..];
				payload = TrimTrailingPeriod(trimmed[..suffixIndex]);
				return !string.IsNullOrWhiteSpace(payload);
			}
		}

		foreach (string startOfCombatPrefix in GetCombatStartPrefixes())
		{
			if (trimmed.StartsWith(startOfCombatPrefix, StringComparison.Ordinal))
			{
				mode = DescriptionLineMergeMode.SharedPrefix;
				sharedText = startOfCombatPrefix;
				payload = TrimTrailingPeriod(trimmed[sharedText.Length..]);
				return !string.IsNullOrWhiteSpace(payload);
			}
		}

		if (StartsWithAny(trimmed, GetPrefixMergeMarkers()))
		{
			foreach (string separator in GetPrefixMergeSeparators())
			{
				int separatorIndex = trimmed.IndexOf(separator, StringComparison.Ordinal);
				if (separatorIndex > 0)
				{
					mode = DescriptionLineMergeMode.SharedPrefix;
					sharedText = trimmed[..(separatorIndex + separator.Length)];
					payload = TrimTrailingPeriod(trimmed[(separatorIndex + separator.Length)..]);
					return !string.IsNullOrWhiteSpace(payload);
				}
			}
		}

		return false;
	}

	private static string JoinDescriptionPayloads(IReadOnlyList<string> payloads)
	{
		if (payloads == null || payloads.Count == 0)
		{
			return string.Empty;
		}
		if (payloads.Count == 1)
		{
			return payloads[0];
		}
		if (payloads.Count == 2)
		{
			if (IsChineseLocalizationActive())
			{
				return payloads[0] + "和" + payloads[1];
			}
			return payloads[0] + " and " + LowercaseFirst(payloads[1]);
		}

		if (IsChineseLocalizationActive())
		{
			return string.Join("、", payloads.Take(payloads.Count - 1))
				+ "和"
				+ payloads[^1];
		}

		return string.Join(", ", payloads.Take(payloads.Count - 1))
			+ ", and "
			+ LowercaseFirst(payloads[^1]);
	}

	private static string TrimTrailingPeriod(string text)
	{
		string trimmed = text?.Trim() ?? string.Empty;
		if (trimmed.EndsWith(".", StringComparison.Ordinal) || trimmed.EndsWith("。", StringComparison.Ordinal))
		{
			return trimmed[..^1];
		}

		return trimmed;
	}

	private static bool IsChineseLocalizationActive()
	{
		string language = LocManager.Instance?.Language ?? string.Empty;
		return language.StartsWith("zh", StringComparison.OrdinalIgnoreCase);
	}

	private static bool StartsWithAny(string text, IReadOnlyList<string> prefixes)
	{
		foreach (string prefix in prefixes)
		{
			if (text.StartsWith(prefix, StringComparison.Ordinal))
			{
				return true;
			}
		}

		return false;
	}

	private static IReadOnlyList<string> GetMergeSuffixMarkers()
	{
		return IsChineseLocalizationActive()
			? new[] { "。你在", "（你在", "，你在" }
			: new[] { " for each " };
	}

	private static IReadOnlyList<string> GetCombatStartPrefixes()
	{
		return IsChineseLocalizationActive()
			? new[] { "[gold]战斗开始时[/gold]：" }
			: new[] { "[gold]Start Of Combat[/gold]: " };
	}

	private static IReadOnlyList<string> GetPrefixMergeMarkers()
	{
		return IsChineseLocalizationActive()
			? new[] { "如果", "每当", "在", "每", "本场战斗中", "从下个", "从你的下个", "战斗开始时" }
			: new[] { "If ", "Whenever ", "At the ", "After ", "Every " };
	}

	private static IReadOnlyList<string> GetPrefixMergeSeparators()
	{
		return IsChineseLocalizationActive()
			? new[] { "，", "：" }
			: new[] { ", ", ": " };
	}

	internal static IReadOnlyList<CardExtraEffectKeywordSummary> GetCustomKeywordSummaries(CardModel card, Creature? target = null, bool isUpgradePreview = false)
	{
		List<DescriptionEffectLine> lines = BuildDescriptionEffectLines(card, target, isUpgradePreview);
		if (lines.Count == 0)
		{
			return Array.Empty<CardExtraEffectKeywordSummary>();
		}

		List<string> orderedNames = new List<string>();
		Dictionary<string, List<string>> groupedLines = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
		foreach (DescriptionEffectLine line in lines)
		{
			string? keywordName = line.CustomKeywordName;
			if (string.IsNullOrWhiteSpace(keywordName))
			{
				continue;
			}

			if (!groupedLines.TryGetValue(keywordName, out List<string>? group))
			{
				group = new List<string>();
				groupedLines[keywordName] = group;
				orderedNames.Add(keywordName);
			}

			group.Add(line.Line);
		}

		if (orderedNames.Count == 0)
		{
			return Array.Empty<CardExtraEffectKeywordSummary>();
		}

		List<CardExtraEffectKeywordSummary> summaries = new List<CardExtraEffectKeywordSummary>(orderedNames.Count);
		foreach (string name in orderedNames)
		{
			if (!groupedLines.TryGetValue(name, out List<string>? group) || group.Count == 0)
			{
				continue;
			}

			summaries.Add(new CardExtraEffectKeywordSummary
			{
				Name = name,
				Description = string.Join('\n', group)
			});
		}

		if (lines.Any(line => line.Trigger == CardExtraEffectTrigger.DeckPassiveCombatStart))
		{
			summaries.Add(new CardExtraEffectKeywordSummary
			{
				Name = GetDeckPassiveCombatStartKeywordTitle(),
				Description = GetDeckPassiveCombatStartKeywordDescription()
			});
		}

		if (lines.Any(line => line.Trigger == CardExtraEffectTrigger.DeckPassiveCombatEnd))
		{
			summaries.Add(new CardExtraEffectKeywordSummary
			{
				Name = GetDeckPassiveCombatEndKeywordTitle(),
				Description = GetDeckPassiveCombatEndKeywordDescription()
			});
		}

		if (lines.Any(line => line.Line.Contains("[gold]" + GetPlayableKeywordTitle() + "[/gold]", StringComparison.Ordinal)))
		{
			summaries.Add(new CardExtraEffectKeywordSummary
			{
				Name = GetPlayableKeywordTitle(),
				Description = GetPlayableKeywordDescription()
			});
		}

		if (lines.Any(line => line.Line.Contains("[gold]" + GetAllCardsKeywordTitle() + "[/gold]", StringComparison.Ordinal)))
		{
			summaries.Add(new CardExtraEffectKeywordSummary
			{
				Name = GetAllCardsKeywordTitle(),
				Description = GetAllCardsKeywordDescription()
			});
		}

		return summaries;
	}

	private static bool TryGetOverride(ModelId cardId, out CardOverride? overrideData)
	{
		if (CardEditorUiState.TryGetDraftOverride(cardId, out CardOverride draft))
		{
			overrideData = draft;
			return true;
		}
		if (CardEditorOverrides.TryGet(cardId, out CardOverride stored))
		{
			overrideData = stored;
			return true;
		}
		overrideData = null;
		return false;
	}

	public static bool TryAppendDescription(CardModel card, ref string description, Creature? target = null, bool isUpgradePreview = false)
	{
		List<DescriptionEffectLine> renderedLines = BuildDescriptionEffectLines(card, target, isUpgradePreview);
		if (renderedLines.Count == 0)
		{
			return false;
		}

		List<string> lines = new List<string>();
		HashSet<string> emittedKeywordGroups = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (DescriptionEffectLine renderedLine in renderedLines)
		{
			if (!string.IsNullOrWhiteSpace(renderedLine.CustomKeywordName))
			{
				if (emittedKeywordGroups.Add(renderedLine.CustomKeywordName))
				{
					lines.Add(!string.IsNullOrWhiteSpace(renderedLine.CustomKeywordCardLine)
						? renderedLine.CustomKeywordCardLine!
						: "[gold]" + renderedLine.CustomKeywordName + "[/gold].");
				}
				continue;
			}

			lines.Add(renderedLine.Line);
		}
		if (lines.Count == 0)
		{
			return false;
		}

		string appendBlock = string.Join('\n', lines);
		string formattedAppendBlock = CardEditorVanillaKeywordSupport.FormatDescription(appendBlock);
		if (string.IsNullOrEmpty(description))
		{
			description = appendBlock;
			return true;
		}

		// Some mod combinations re-enter public description APIs after the private path has
		// already appended our extra-effect block. Only suppress an exact duplicate block at
		// the end of the description so intentional repeated effect lines remain untouched.
		string comparisonDescription = description.TrimEnd('\r', '\n');
		bool exactRawBlock = comparisonDescription.Equals(appendBlock, StringComparison.Ordinal);
		bool rawBlockAtEnd = exactRawBlock || comparisonDescription.EndsWith("\n" + appendBlock, StringComparison.Ordinal);
		bool exactFormattedBlock = !string.Equals(formattedAppendBlock, appendBlock, StringComparison.Ordinal)
			&& comparisonDescription.Equals(formattedAppendBlock, StringComparison.Ordinal);
		bool formattedBlockAtEnd = exactFormattedBlock
			|| (!string.Equals(formattedAppendBlock, appendBlock, StringComparison.Ordinal)
				&& comparisonDescription.EndsWith("\n" + formattedAppendBlock, StringComparison.Ordinal));
		bool currentDescriptionIsBaseText = (rawBlockAtEnd || formattedBlockAtEnd)
			&& DescriptionMatchesBaseWithoutExtraEffects(card, target, isUpgradePreview, comparisonDescription);
		bool alreadyEndsWithRawBlock = rawBlockAtEnd && !currentDescriptionIsBaseText;
		bool alreadyEndsWithFormattedBlock = !string.Equals(formattedAppendBlock, appendBlock, StringComparison.Ordinal)
			&& formattedBlockAtEnd
			&& !currentDescriptionIsBaseText;
		if (alreadyEndsWithRawBlock || alreadyEndsWithFormattedBlock)
		{
			return false;
		}

		description += "\n" + appendBlock;
		return true;
	}

	internal static bool HasAppendableDescriptionLines(CardModel card, Creature? target = null, bool isUpgradePreview = false)
	{
		return BuildDescriptionEffectLines(card, target, isUpgradePreview).Count > 0;
	}

	private static bool DescriptionMatchesBaseWithoutExtraEffects(
		CardModel card,
		Creature? target,
		bool isUpgradePreview,
		string comparisonDescription)
	{
		if (card == null || card is CardEditorCreatedCardBase)
		{
			return false;
		}

		bool previousSuppressExtraEffects = CardEditorVanillaDescriptionOverrideSupport.SuppressExtraEffectDescriptionAppend;
		CardEditorVanillaDescriptionOverrideSupport.SuppressExtraEffectDescriptionAppend = true;
		try
		{
			string baseDescription = isUpgradePreview
				? card.GetDescriptionForUpgradePreview()
				: card.GetDescriptionForPile(PileType.None, target);
			string comparisonBase = (baseDescription ?? string.Empty).TrimEnd('\r', '\n');
			return comparisonBase.Equals(comparisonDescription, StringComparison.Ordinal);
		}
		catch
		{
			return false;
		}
		finally
		{
			CardEditorVanillaDescriptionOverrideSupport.SuppressExtraEffectDescriptionAppend = previousSuppressExtraEffects;
		}
	}

	private static bool TryGetOverrideForDescription(CardModel card, bool considerUpgrade, int? upgradeApplicationCountOverride, out CardOverride? overrideData, out IReadOnlyList<CardExtraEffect> effects)
	{
		overrideData = null;
		effects = Array.Empty<CardExtraEffect>();

		if (CardEditorUiState.TryGetDraftOverride(card.Id, out CardOverride draft))
		{
			// Draft is authoritative — if the editor is open, don't fall back to stored even if the draft has no valid effects.
			IReadOnlyList<CardExtraEffect> draftEffects = GetEffectiveExtraEffects(card, draft, considerUpgrade, upgradeApplicationCountOverride);
			if (draftEffects.Count > 0)
			{
				overrideData = draft;
				effects = draftEffects;
				return true;
			}
			return false;
		}

		if (CardEditorOverrides.TryGetEffectiveOverride(card, out CardOverride stored))
		{
			IReadOnlyList<CardExtraEffect> storedEffects = GetEffectiveExtraEffects(card, stored, considerUpgrade, upgradeApplicationCountOverride);
			if (storedEffects.Count > 0)
			{
				overrideData = stored;
				effects = storedEffects;
				return true;
			}
		}

		return false;
	}

	private static List<(CardExtraEffect Effect, DescriptionUpgradeComparison UpgradeComparison)> BuildUpgradePreviewEffects(CardOverride overrideData, IReadOnlyList<CardExtraEffect> effectiveEffects)
	{
		if (overrideData == null || effectiveEffects == null || effectiveEffects.Count == 0)
		{
			return new List<(CardExtraEffect, DescriptionUpgradeComparison)>();
		}

		IReadOnlyList<CardExtraEffect>? baseEffects = overrideData.ExtraEffects;
		IReadOnlyList<CardExtraEffect>? upgradeEffects = overrideData.Upgrade?.ExtraEffects;

		if (upgradeEffects == null || upgradeEffects.Count == 0)
		{
			return effectiveEffects.Select(e => (e, DescriptionUpgradeComparison.None)).ToList();
		}

		if (baseEffects == null || baseEffects.Count == 0)
		{
			return effectiveEffects.Select(e => (e, GetUpgradeComparison(baseEffect: null, upgradedEffect: e))).ToList();
		}

		List<(CardExtraEffect Effect, DescriptionUpgradeComparison UpgradeComparison)> result = new List<(CardExtraEffect, DescriptionUpgradeComparison)>(effectiveEffects.Count);
		bool[] usedBaseSlots = new bool[baseEffects.Count];
		for (int i = 0; i < effectiveEffects.Count; i++)
		{
			CardExtraEffect upgradedEffect = effectiveEffects[i];
			if (upgradedEffect == null)
			{
				result.Add((null!, DescriptionUpgradeComparison.None));
				continue;
			}

			int baseSlotIndex = ResolveEquivalentBaseSlotIndex(baseEffects, upgradedEffect, i, usedBaseSlots);
			CardExtraEffect? baseEffect = null;
			if (baseSlotIndex >= 0 && baseSlotIndex < baseEffects.Count)
			{
				usedBaseSlots[baseSlotIndex] = true;
				baseEffect = baseEffects[baseSlotIndex];
			}

			result.Add((upgradedEffect, GetUpgradeComparison(baseEffect, upgradedEffect)));
		}

		return result;
	}

	private static UpgradeEffectAlignment AlignUpgradeEffectsToBaseSlots(IReadOnlyList<CardExtraEffect> baseEffects, IReadOnlyList<CardExtraEffect> upgradeEffects)
	{
		int baseCount = baseEffects?.Count ?? 0;
		int upgradeCount = upgradeEffects?.Count ?? 0;
		CardExtraEffect?[] baseSlotEffects = new CardExtraEffect?[baseCount];
		int[] upgradeIndexToBaseSlot = Enumerable.Repeat(-1, upgradeCount).ToArray();

		if (baseCount == 0 || upgradeCount == 0)
		{
			return new UpgradeEffectAlignment
			{
				BaseSlotEffects = baseSlotEffects,
				UpgradeIndexToBaseSlot = upgradeIndexToBaseSlot,
				LastMatchedUpgradeIndex = -1
			};
		}

		bool[] usedBaseSlots = new bool[baseCount];
		int lastMatchedUpgradeIndex = -1;
		for (int i = 0; i < upgradeCount; i++)
		{
			CardExtraEffect? upgradeEffect = upgradeEffects[i];
			if (upgradeEffect == null)
			{
				continue;
			}

			int baseSlotIndex = ResolveUpgradeBaseSlotIndex(baseEffects, upgradeEffect, preferredIndex: i, usedBaseSlots);
			if (baseSlotIndex < 0)
			{
				continue;
			}

			usedBaseSlots[baseSlotIndex] = true;
			baseSlotEffects[baseSlotIndex] = upgradeEffect;
			upgradeIndexToBaseSlot[i] = baseSlotIndex;
			lastMatchedUpgradeIndex = i;
		}

		return new UpgradeEffectAlignment
		{
			BaseSlotEffects = baseSlotEffects,
			UpgradeIndexToBaseSlot = upgradeIndexToBaseSlot,
			LastMatchedUpgradeIndex = lastMatchedUpgradeIndex
		};
	}

	internal static (CardExtraEffect?[] BaseSlotEffects, List<CardExtraEffect> AbsoluteEffects) AlignUpgradeEffectsForEditor(IReadOnlyList<CardExtraEffect> baseEffects, IReadOnlyList<CardExtraEffect> upgradeEffects)
	{
		UpgradeEffectAlignment alignment = AlignUpgradeEffectsToBaseSlots(baseEffects, upgradeEffects);
		List<CardExtraEffect> absoluteEffects = new List<CardExtraEffect>();
		for (int i = 0; i < (upgradeEffects?.Count ?? 0); i++)
		{
			CardExtraEffect? upgradeEffect = upgradeEffects[i];
			if (upgradeEffect == null || alignment.UpgradeIndexToBaseSlot[i] >= 0)
			{
				continue;
			}

			if (!ShouldTreatUnmatchedUpgradeEffectAsAbsolute(baseEffects?.Count ?? 0, i, alignment.LastMatchedUpgradeIndex))
			{
				continue;
			}

			if (!upgradeEffect.DisableOnUpgrade && IsPersistableEffect(upgradeEffect))
			{
				absoluteEffects.Add(CloneEffect(upgradeEffect));
			}
		}

		return (alignment.BaseSlotEffects, absoluteEffects);
	}

	internal static List<CardExtraEffect>? RebaseUpgradeEffectsAfterBaseEdit(
		IReadOnlyList<CardExtraEffect>? oldBaseEffects,
		IReadOnlyList<CardExtraEffect>? newBaseEffects,
		IReadOnlyList<CardExtraEffect>? existingUpgradeEffects)
	{
		if (existingUpgradeEffects == null || existingUpgradeEffects.Count == 0)
		{
			return null;
		}

		int oldBaseCount = oldBaseEffects?.Count ?? 0;
		int newBaseCount = newBaseEffects?.Count ?? 0;
		List<CardExtraEffect> rebased = Enumerable.Repeat<CardExtraEffect>(null!, newBaseCount).ToList();
		List<CardExtraEffect> absoluteEffects = new List<CardExtraEffect>();
		bool[] usedNewBaseSlots = new bool[newBaseCount];

		for (int i = 0; i < existingUpgradeEffects.Count; i++)
		{
			CardExtraEffect? existingUpgradeEffect = existingUpgradeEffects[i];
			if (existingUpgradeEffect == null)
			{
				continue;
			}

			if (i < oldBaseCount)
			{
				CardExtraEffect? oldBaseEffect = oldBaseEffects?[i];
				if (oldBaseEffect == null || newBaseCount == 0)
				{
					continue;
				}

				int newBaseSlotIndex = ResolveEquivalentBaseSlotIndex(newBaseEffects!, oldBaseEffect, preferredIndex: i, usedNewBaseSlots);
				if (newBaseSlotIndex < 0)
				{
					continue;
				}

				usedNewBaseSlots[newBaseSlotIndex] = true;
				rebased[newBaseSlotIndex] = CloneEffect(existingUpgradeEffect);
				continue;
			}

			if (!existingUpgradeEffect.DisableOnUpgrade && IsPersistableEffect(existingUpgradeEffect))
			{
				absoluteEffects.Add(CloneEffect(existingUpgradeEffect));
			}
		}

		if (absoluteEffects.Count > 0)
		{
			rebased.AddRange(absoluteEffects);
		}

		return rebased.Any(effect => effect != null) ? rebased : null;
	}

	internal static bool ShouldTreatUnmatchedUpgradeEffectAsAbsolute(int baseCount, int upgradeIndex, int lastMatchedUpgradeIndex)
	{
		if (upgradeIndex < 0)
		{
			return false;
		}

		if (lastMatchedUpgradeIndex >= 0)
		{
			return upgradeIndex > lastMatchedUpgradeIndex;
		}

		return upgradeIndex >= baseCount;
	}

	private static int ResolveUpgradeBaseSlotIndex(IReadOnlyList<CardExtraEffect> baseEffects, CardExtraEffect upgradeEffect, int preferredIndex, bool[] usedBaseSlots)
	{
		if (baseEffects == null || upgradeEffect == null || baseEffects.Count == 0)
		{
			return -1;
		}

		if (preferredIndex >= 0
			&& preferredIndex < baseEffects.Count
			&& (usedBaseSlots == null || preferredIndex >= usedBaseSlots.Length || !usedBaseSlots[preferredIndex])
			&& CanUsePreferredUpgradeBaseSlot(baseEffects[preferredIndex], upgradeEffect))
		{
			return preferredIndex;
		}

		for (int i = 0; i < baseEffects.Count; i++)
		{
			if (usedBaseSlots != null && i < usedBaseSlots.Length && usedBaseSlots[i])
			{
				continue;
			}
			if (LooksLikeSameUpgradeBaseSlot(baseEffects[i], upgradeEffect))
			{
				return i;
			}
		}

		for (int i = 0; i < baseEffects.Count; i++)
		{
			if (usedBaseSlots != null && i < usedBaseSlots.Length && usedBaseSlots[i])
			{
				continue;
			}
			if (CanUsePreferredUpgradeBaseSlot(baseEffects[i], upgradeEffect))
			{
				return i;
			}
		}

		return -1;
	}

	private static int ResolveEquivalentBaseSlotIndex(IReadOnlyList<CardExtraEffect> candidateBaseEffects, CardExtraEffect referenceBaseEffect, int preferredIndex, bool[] usedBaseSlots)
	{
		if (candidateBaseEffects == null || referenceBaseEffect == null || candidateBaseEffects.Count == 0)
		{
			return -1;
		}

		if (preferredIndex >= 0
			&& preferredIndex < candidateBaseEffects.Count
			&& (usedBaseSlots == null || preferredIndex >= usedBaseSlots.Length || !usedBaseSlots[preferredIndex])
			&& LooksLikeSameUpgradeBaseSlot(candidateBaseEffects[preferredIndex], referenceBaseEffect))
		{
			return preferredIndex;
		}

		for (int i = 0; i < candidateBaseEffects.Count; i++)
		{
			if (usedBaseSlots != null && i < usedBaseSlots.Length && usedBaseSlots[i])
			{
				continue;
			}
			if (LooksLikeSameUpgradeBaseSlot(candidateBaseEffects[i], referenceBaseEffect))
			{
				return i;
			}
		}

		for (int i = 0; i < candidateBaseEffects.Count; i++)
		{
			if (usedBaseSlots != null && i < usedBaseSlots.Length && usedBaseSlots[i])
			{
				continue;
			}
			if (CanUsePreferredUpgradeBaseSlot(candidateBaseEffects[i], referenceBaseEffect))
			{
				return i;
			}
		}

		return -1;
	}

	private static bool CanUsePreferredUpgradeBaseSlot(CardExtraEffect baseEffect, CardExtraEffect upgradeEffect)
	{
		if (baseEffect == null || upgradeEffect == null)
		{
			return false;
		}

		if (baseEffect.Kind != upgradeEffect.Kind)
		{
			return false;
		}

		string? upgradeKeyword = NormalizeCustomKeywordName(upgradeEffect.CustomKeywordName);
		if (upgradeKeyword != null)
		{
			string? baseKeyword = NormalizeCustomKeywordName(baseEffect.CustomKeywordName);
			if (!string.Equals(baseKeyword ?? string.Empty, upgradeKeyword, StringComparison.OrdinalIgnoreCase))
			{
				return false;
			}
		}

		string? upgradePowerName = string.IsNullOrWhiteSpace(upgradeEffect.CustomPowerName) ? null : upgradeEffect.CustomPowerName.Trim();
		if (upgradePowerName != null)
		{
			string? basePowerName = string.IsNullOrWhiteSpace(baseEffect.CustomPowerName) ? null : baseEffect.CustomPowerName.Trim();
			if (!string.Equals(basePowerName ?? string.Empty, upgradePowerName, StringComparison.Ordinal))
			{
				return false;
			}
		}

		string? upgradePowerDescription = string.IsNullOrWhiteSpace(upgradeEffect.CustomPowerDescription) ? null : upgradeEffect.CustomPowerDescription.Trim();
		if (upgradePowerDescription != null)
		{
			string? basePowerDescription = string.IsNullOrWhiteSpace(baseEffect.CustomPowerDescription) ? null : baseEffect.CustomPowerDescription.Trim();
			if (!string.Equals(basePowerDescription ?? string.Empty, upgradePowerDescription, StringComparison.Ordinal))
			{
				return false;
			}
		}

		return true;
	}

	private static bool LooksLikeSameUpgradeBaseSlot(CardExtraEffect baseEffect, CardExtraEffect upgradeEffect)
	{
		if (baseEffect == null || upgradeEffect == null)
		{
			return false;
		}

		// CustomKeywordName is presentation/grouping only. Treat it as inherited from base unless the
		// upgrade explicitly sets it, otherwise keyword-fused effects fail to match and get duplicated.
		string? upgradeKeyword = NormalizeCustomKeywordName(upgradeEffect.CustomKeywordName);
		if (upgradeKeyword != null)
		{
			string? baseKeyword = NormalizeCustomKeywordName(baseEffect.CustomKeywordName);
			if (!string.Equals(baseKeyword ?? string.Empty, upgradeKeyword, StringComparison.OrdinalIgnoreCase))
			{
				return false;
			}
		}

		string? upgradePowerName = string.IsNullOrWhiteSpace(upgradeEffect.CustomPowerName) ? null : upgradeEffect.CustomPowerName.Trim();
		if (upgradePowerName != null)
		{
			string? basePowerName = string.IsNullOrWhiteSpace(baseEffect.CustomPowerName) ? null : baseEffect.CustomPowerName.Trim();
			if (!string.Equals(basePowerName ?? string.Empty, upgradePowerName, StringComparison.Ordinal))
			{
				return false;
			}
		}

		string? upgradePowerDescription = string.IsNullOrWhiteSpace(upgradeEffect.CustomPowerDescription) ? null : upgradeEffect.CustomPowerDescription.Trim();
		if (upgradePowerDescription != null)
		{
			string? basePowerDescription = string.IsNullOrWhiteSpace(baseEffect.CustomPowerDescription) ? null : baseEffect.CustomPowerDescription.Trim();
			if (!string.Equals(basePowerDescription ?? string.Empty, upgradePowerDescription, StringComparison.Ordinal))
			{
				return false;
			}
		}

		return baseEffect.Kind == upgradeEffect.Kind
			&& baseEffect.Target == upgradeEffect.Target
			&& baseEffect.AmountIsX == upgradeEffect.AmountIsX
			&& baseEffect.Trigger == upgradeEffect.Trigger
			&& baseEffect.PowerTriggerCountEvent == upgradeEffect.PowerTriggerCountEvent
			&& baseEffect.PowerTriggerEnemyStatus == upgradeEffect.PowerTriggerEnemyStatus
			&& string.Equals(baseEffect.PowerTriggerPowerId ?? string.Empty, upgradeEffect.PowerTriggerPowerId ?? string.Empty, StringComparison.Ordinal)
			&& baseEffect.TurnBoundary == upgradeEffect.TurnBoundary
			&& baseEffect.TurnBoundarySide == upgradeEffect.TurnBoundarySide
			&& baseEffect.TurnBoundaryCardLocation == upgradeEffect.TurnBoundaryCardLocation
			&& baseEffect.Timing == upgradeEffect.Timing
			&& baseEffect.Duration == upgradeEffect.Duration
			&& baseEffect.AsPower == upgradeEffect.AsPower
			&& baseEffect.TriggerCardPool == upgradeEffect.TriggerCardPool
			&& baseEffect.TriggerCardType == upgradeEffect.TriggerCardType
			&& baseEffect.TriggerCardFilter == upgradeEffect.TriggerCardFilter
			&& baseEffect.CardCostsLessDuration == upgradeEffect.CardCostsLessDuration
			&& baseEffect.CardCostsLessMode == upgradeEffect.CardCostsLessMode
			&& baseEffect.CardCostsLessModifier == upgradeEffect.CardCostsLessModifier
			&& baseEffect.GeneratedCardPool == upgradeEffect.GeneratedCardPool
			&& baseEffect.GeneratedCardType == upgradeEffect.GeneratedCardType
			&& baseEffect.ScaleMode == upgradeEffect.ScaleMode
			&& baseEffect.CountEvent == upgradeEffect.CountEvent
			&& baseEffect.CountWindow == upgradeEffect.CountWindow
			&& baseEffect.CountWindowInclusion == upgradeEffect.CountWindowInclusion
			&& baseEffect.BlockLostCountingMode == upgradeEffect.BlockLostCountingMode
			&& baseEffect.CountCardPile == upgradeEffect.CountCardPile
			&& baseEffect.CountCardPool == upgradeEffect.CountCardPool
			&& baseEffect.CountCardType == upgradeEffect.CountCardType
			&& baseEffect.CountCardFilter == upgradeEffect.CountCardFilter
			&& baseEffect.CountOnlyBlockCards == upgradeEffect.CountOnlyBlockCards
			&& GetEffectiveCountAggregationMode(baseEffect) == GetEffectiveCountAggregationMode(upgradeEffect)
			&& baseEffect.CountOrbType == upgradeEffect.CountOrbType
			&& baseEffect.CountOrbSelection == upgradeEffect.CountOrbSelection
			&& baseEffect.CountEnemyStatus == upgradeEffect.CountEnemyStatus
			&& string.Equals(baseEffect.CountPowerId ?? string.Empty, upgradeEffect.CountPowerId ?? string.Empty, StringComparison.Ordinal)
			&& baseEffect.CountEnemyIntent == upgradeEffect.CountEnemyIntent
			&& baseEffect.CountComparison == upgradeEffect.CountComparison
			&& baseEffect.HistoryScalingIncludesBase == upgradeEffect.HistoryScalingIncludesBase
			&& baseEffect.RepeatScalingReplacesBase == upgradeEffect.RepeatScalingReplacesBase
			&& ResolveHistoryScalingCountStep(baseEffect) == ResolveHistoryScalingCountStep(upgradeEffect)
			&& ResolveRepeatScalingExtraTimes(baseEffect) == ResolveRepeatScalingExtraTimes(upgradeEffect)
			&& baseEffect.RepeatIsX == upgradeEffect.RepeatIsX
			&& baseEffect.GrantToCard == upgradeEffect.GrantToCard
			&& baseEffect.CardSelectionMode == upgradeEffect.CardSelectionMode
			&& baseEffect.CardSelectionCountIsX == upgradeEffect.CardSelectionCountIsX
			&& baseEffect.CardSelectionPile == upgradeEffect.CardSelectionPile
			&& string.Equals(baseEffect.CardSelectionSourceEffectId ?? string.Empty, upgradeEffect.CardSelectionSourceEffectId ?? string.Empty, StringComparison.Ordinal)
			&& baseEffect.CardGrantDuration == upgradeEffect.CardGrantDuration
			&& string.Equals(baseEffect.EnchantmentId ?? string.Empty, upgradeEffect.EnchantmentId ?? string.Empty, StringComparison.Ordinal)
			&& baseEffect.EnchantmentDuration == upgradeEffect.EnchantmentDuration
			&& baseEffect.MoveToPile == upgradeEffect.MoveToPile
			&& baseEffect.MoveToPosition == upgradeEffect.MoveToPosition
			&& baseEffect.UseMoveDestinationForGeneratedCards == upgradeEffect.UseMoveDestinationForGeneratedCards
			&& baseEffect.AdditionalMoveToPiles == upgradeEffect.AdditionalMoveToPiles
			&& baseEffect.CopyMode == upgradeEffect.CopyMode
			&& baseEffect.DelayedPileAction == upgradeEffect.DelayedPileAction
			&& baseEffect.DelayedPileCounterUnit == upgradeEffect.DelayedPileCounterUnit
			&& baseEffect.DelayedPileCounterScope == upgradeEffect.DelayedPileCounterScope
			&& baseEffect.DrawnFromPile == upgradeEffect.DrawnFromPile
			&& string.Equals(baseEffect.SpecificCardId ?? string.Empty, upgradeEffect.SpecificCardId ?? string.Empty, StringComparison.Ordinal)
			&& baseEffect.SpecificCardUpgradeMode == upgradeEffect.SpecificCardUpgradeMode
			&& baseEffect.TransformMode == upgradeEffect.TransformMode
			&& baseEffect.ConditionalBonusConditionType == upgradeEffect.ConditionalBonusConditionType
			&& baseEffect.ConditionalBonusCondition == upgradeEffect.ConditionalBonusCondition
			&& baseEffect.ConditionalBonusEnemyStatus == upgradeEffect.ConditionalBonusEnemyStatus
			&& string.Equals(baseEffect.ConditionalBonusPowerId ?? string.Empty, upgradeEffect.ConditionalBonusPowerId ?? string.Empty, StringComparison.Ordinal)
			&& baseEffect.ConditionalBonusEnemyIntent == upgradeEffect.ConditionalBonusEnemyIntent
			&& baseEffect.BranchMode == upgradeEffect.BranchMode
			&& baseEffect.BranchCondition == upgradeEffect.BranchCondition
			&& baseEffect.BranchEnemyStatus == upgradeEffect.BranchEnemyStatus
			&& string.Equals(baseEffect.BranchPowerId ?? string.Empty, upgradeEffect.BranchPowerId ?? string.Empty, StringComparison.Ordinal)
			&& baseEffect.BranchEnemyIntent == upgradeEffect.BranchEnemyIntent
			&& BranchEffectsMatch(baseEffect.BranchEffect, upgradeEffect.BranchEffect)
			&& string.Equals(baseEffect.PowerId ?? string.Empty, upgradeEffect.PowerId ?? string.Empty, StringComparison.Ordinal)
			&& baseEffect.OrbAction == upgradeEffect.OrbAction
			&& baseEffect.OrbType == upgradeEffect.OrbType
			&& baseEffect.OrbSelection == upgradeEffect.OrbSelection
			&& baseEffect.OrbFollowUp == upgradeEffect.OrbFollowUp
			&& baseEffect.OrbScope == upgradeEffect.OrbScope
			&& baseEffect.OstyAction == upgradeEffect.OstyAction
			&& baseEffect.CreatureCommand == upgradeEffect.CreatureCommand
			&& string.Equals(baseEffect.CreatureCommandId ?? string.Empty, upgradeEffect.CreatureCommandId ?? string.Empty, StringComparison.Ordinal)
			&& baseEffect.MultiplierStat == upgradeEffect.MultiplierStat
			&& baseEffect.MultiplierSourceMode == upgradeEffect.MultiplierSourceMode
			&& string.Equals(baseEffect.MultiplierPowerId ?? string.Empty, upgradeEffect.MultiplierPowerId ?? string.Empty, StringComparison.Ordinal)
			&& baseEffect.GrantedKeyword == upgradeEffect.GrantedKeyword
			&& baseEffect.GrantedKeywordRemove == upgradeEffect.GrantedKeywordRemove
			&& baseEffect.CardMatchMode == upgradeEffect.CardMatchMode
			&& string.Equals(baseEffect.MatchCardId ?? string.Empty, upgradeEffect.MatchCardId ?? string.Empty, StringComparison.Ordinal)
			&& baseEffect.MatchTagKind == upgradeEffect.MatchTagKind
			&& baseEffect.MatchVanillaTag == upgradeEffect.MatchVanillaTag
			&& string.Equals(baseEffect.MatchCustomTag ?? string.Empty, upgradeEffect.MatchCustomTag ?? string.Empty, StringComparison.Ordinal)
			&& string.Equals(baseEffect.MatchCustomKeyword ?? string.Empty, upgradeEffect.MatchCustomKeyword ?? string.Empty, StringComparison.Ordinal)
			&& baseEffect.NameFilterEnabled == upgradeEffect.NameFilterEnabled
			&& string.Equals(baseEffect.NameFilterText ?? string.Empty, upgradeEffect.NameFilterText ?? string.Empty, StringComparison.Ordinal)
			&& baseEffect.CostFilterEnabled == upgradeEffect.CostFilterEnabled
			&& baseEffect.CostFilterMode == upgradeEffect.CostFilterMode
			&& baseEffect.CostFilterMax == upgradeEffect.CostFilterMax;
	}

	private static int NormalizeUpgradeDiffAmount(CardExtraEffect effect)
	{
		if (effect == null)
		{
			return 0;
		}

		// CreatedCardsCostLess used -1 as a sentinel that means "free"; preserve that in upgrade comparisons.
		if (effect.Kind == CardExtraEffectKind.CreatedCardsCostLess
			&& GetEffectiveCardCostsLessModifier(effect) == CardExtraEffectCostModifier.Free)
		{
			return 0;
		}

		return effect.Amount;
	}

	private static int GetUpgradeHighlightComparison(CardExtraEffect? baseEffect, CardExtraEffect? upgradedEffect)
	{
		if (upgradedEffect == null)
		{
			return 0;
		}

		// Vanilla upgrade previews mark every changed value green regardless of direction
		// (DynamicVar.WasJustUpgraded forces the diff positive), so changed => green here too.
		if (upgradedEffect.AmountIsX)
		{
			int basePlus = baseEffect?.AmountXPlus ?? 0;
			return upgradedEffect.AmountXPlus == basePlus ? 0 : 1;
		}

		int upgradedAmount = NormalizeUpgradeDiffAmount(upgradedEffect);
		int baseAmount = baseEffect != null ? NormalizeUpgradeDiffAmount(baseEffect) : 0;
		return upgradedAmount == baseAmount ? 0 : 1;
	}

	private static DescriptionUpgradeComparison GetUpgradeComparison(CardExtraEffect? baseEffect, CardExtraEffect? upgradedEffect)
	{
		return new DescriptionUpgradeComparison(
			GetUpgradeHighlightComparison(baseEffect, upgradedEffect),
			GetUpgradeRepeatHighlightComparison(baseEffect, upgradedEffect),
			GetUpgradeHistoryCountStepHighlightComparison(baseEffect, upgradedEffect),
			GetUpgradeRepeatScalingExtraTimesHighlightComparison(baseEffect, upgradedEffect));
	}

	private static int GetUpgradeHistoryCountStepHighlightComparison(CardExtraEffect? baseEffect, CardExtraEffect? upgradedEffect)
	{
		if (baseEffect == null
			|| upgradedEffect == null
			|| upgradedEffect.ScaleMode is not (CardExtraEffectScaleMode.PerHistoryCount or CardExtraEffectScaleMode.RepeatByCount))
		{
			return 0;
		}

		int baseStep = ResolveHistoryScalingCountStep(baseEffect);
		int upgradedStep = ResolveHistoryScalingCountStep(upgradedEffect);
		// Changed => green, matching vanilla upgrade-preview semantics.
		return baseStep == upgradedStep ? 0 : 1;
	}

	private static int GetUpgradeRepeatScalingExtraTimesHighlightComparison(CardExtraEffect? baseEffect, CardExtraEffect? upgradedEffect)
	{
		if (baseEffect == null
			|| upgradedEffect == null
			|| upgradedEffect.ScaleMode != CardExtraEffectScaleMode.RepeatByCount
			|| !SupportsRepeat(upgradedEffect.Kind))
		{
			return 0;
		}

		int baseExtraTimes = ResolveRepeatScalingExtraTimes(baseEffect);
		int upgradedExtraTimes = ResolveRepeatScalingExtraTimes(upgradedEffect);
		// Changed => green, matching vanilla upgrade-preview semantics.
		return baseExtraTimes == upgradedExtraTimes ? 0 : 1;
	}

	private static int GetUpgradeRepeatHighlightComparison(CardExtraEffect? baseEffect, CardExtraEffect? upgradedEffect)
	{
		if (upgradedEffect == null || !SupportsRepeat(upgradedEffect.Kind))
		{
			return 0;
		}

		if (upgradedEffect.RepeatIsX)
		{
			int basePlus = baseEffect?.RepeatIsX == true ? baseEffect.RepeatCount : 0;
			return upgradedEffect.RepeatCount == basePlus ? 0 : 1;
		}

		int baseRepeat = baseEffect != null && !baseEffect.RepeatIsX
			? Math.Clamp(baseEffect.RepeatCount <= 0 ? 1 : baseEffect.RepeatCount, 1, 99)
			: 1;
		int upgradedRepeat = Math.Clamp(upgradedEffect.RepeatCount <= 0 ? 1 : upgradedEffect.RepeatCount, 1, 99);
		// Changed => green, matching vanilla upgrade-preview semantics.
		return upgradedRepeat == baseRepeat ? 0 : 1;
	}


	// How a Hook.AfterCardPlayed invocation should be split around the vanilla listeners.
	internal enum CardPlayHookPhase
	{
		// Everything in one pass (legacy behavior).
		Combined = 0,
		// Pre-original: ONLY the plain Immediate OnPlay rows, so an overridden vanilla card's
		// added rows resolve as part of its own play — before "whenever you play a card"
		// reactions (Monologue/Tender) — like printed card text would.
		ImmediateRowsOnly = 1,
		// Post-original: everything else (power entries, Fatal, scheduling, cleanup).
		AfterPlayReactions = 2,
	}

	public static async Task RunAfterCardPlayed(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay, CardPlayHookPhase phase = CardPlayHookPhase.Combined)
	{
		CardModel card = cardPlay.Card;
		if (card == null)
		{
			return;
		}
		bool immediateRowsPhase = phase != CardPlayHookPhase.AfterPlayReactions;
		bool reactionsPhase = phase != CardPlayHookPhase.ImmediateRowsOnly;
		using IDisposable _ = CardEditorCardPlayContext.PushScoped(cardPlay);
		// Split-pipeline session continuity: the immediate phase's session is stashed per
		// CardPlay and re-adopted by the reactions phase, so reaction-time consumers (deferred
		// self-scaling, end-of-play Fatal, triggered cost-less, selected-card chaining) resolve
		// amounts from the rows the play actually ran — like the legacy single-session pass.
		using IDisposable __ = CardEditorEffectExecutionAmountContext.PushSessionScopedForCardPlayPhase(
			cardPlay,
			stashForReactions: phase == CardPlayHookPhase.ImmediateRowsOnly,
			adoptStashed: phase == CardPlayHookPhase.AfterPlayReactions);
		List<CardExtraEffect>? triggeredCardCostsLessToApplyAfter = null;
		List<CardExtraEffect>? deferredSelfScaling = null;
		bool isCreatedCard = card is CardEditorCreatedCardBase;
		SharedAttackContextScope? sharedAttack = null;
		try
		{
			IReadOnlyList<CardExtraEffect> effects = GetRuntimeEffectsIncludingBorrowedSources(combatState, card);
			if (effects.Count == 0)
			{
				return;
			}

			HashSet<string> autoActionPayloadIds = BuildAutoActionPayloadIdSet(effects);
			// Overridden vanilla cards share one attack context across their damage rows like
			// created cards do. The scope MUST be constructed inline here (not inside an awaited
			// factory) so the AsyncLocal ambient value flows into the awaited row execution; the
			// context itself is created lazily by the first landing row.
			sharedAttack = immediateRowsPhase
				&& !isCreatedCard
				&& ShouldOpenSharedAttackScope(combatState, choiceContext, cardPlay, effects, autoActionPayloadIds)
				? new SharedAttackContextScope(cardPlay, new SharedAttackContextHolder())
				: null;
			List<CardExtraEffect>? powerEffectsToAdd = null;
			foreach (CardExtraEffect effect in effects)
			{
				if (ShouldSkipDirectEffect(effect, autoActionPayloadIds)
					|| CardEditorAutoPlayLoopGuard.ShouldSuppressEffect(card, effect)
					|| !IsValidEffectAmount(effect.Kind, effect.Amount))
				{
					continue;
				}

				if (IsPowerEffect(effect))
				{
					if (reactionsPhase)
					{
						(powerEffectsToAdd ??= new List<CardExtraEffect>()).Add(effect);
					}
					continue;
				}

				if (effect.Trigger != CardExtraEffectTrigger.OnPlay)
				{
					continue;
				}

				if (IsSelfScalingKind(effect.Kind))
				{
					if (isCreatedCard)
					{
						// Created-card OnPlay effects already execute during CardModel.OnPlay.
						// Running self-scaling again in the after-play hook applies the delta twice.
						continue;
					}
					if (reactionsPhase)
					{
						(deferredSelfScaling ??= new List<CardExtraEffect>()).Add(effect);
					}
					continue;
				}

				// Created cards execute their non-power OnPlay effects during CardModel.OnPlay so they resolve before
				// AfterCardPlayed powers (e.g. "Whenever you play a card, gain Vigor") trigger.
				if (isCreatedCard)
				{
					if (reactionsPhase
						&& effect.Kind is (CardExtraEffectKind.CardCostsLess or CardExtraEffectKind.CardStarCostsLess) && !effect.GrantToCard)
					{
						if (IsTriggeredCardCostsLessDefinition(effect))
						{
							(triggeredCardCostsLessToApplyAfter ??= new List<CardExtraEffect>()).Add(effect);
						}
					}
					continue;
				}

				if (effect.Kind is (CardExtraEffectKind.CardCostsLess or CardExtraEffectKind.CardStarCostsLess) && !effect.GrantToCard)
				{
					if (reactionsPhase && IsTriggeredCardCostsLessDefinition(effect))
					{
						(triggeredCardCostsLessToApplyAfter ??= new List<CardExtraEffect>()).Add(effect);
					}
					continue;
				}

				if (effect.Timing == CardExtraEffectTiming.Immediate)
				{
					if (immediateRowsPhase)
					{
						await ExecuteEffect(combatState, choiceContext, cardPlay, effect);
					}
				}
				else if (reactionsPhase)
				{
					Creature? lockedTarget = null;
					Player? owner = cardPlay.Card.Owner;
					if (effect.Target == CardExtraEffectTarget.Target && owner?.Creature != null)
					{
						lockedTarget = ResolveSingleTarget(combatState, owner.Creature, cardPlay);
					}
					CardEditorExtraEffectScheduler.Schedule(combatState, cardPlay, effect, lockedTarget);
				}
			}

			// Close the play's attack BEFORE the reactions below: Fatal-trigger rows must not
			// join the play's own context, and an AfterAttack-trigger power granted by this very
			// play must not fire off the play's bracketing context when it disposes. Unregister
			// runs here in THIS method's body — a restore inside the awaited dispose would never
			// flow back up, leaving a stale disposed context visible to the Fatal rows.
			if (sharedAttack != null)
			{
				sharedAttack.Unregister();
				await sharedAttack.DisposeContextAsync();
				sharedAttack = null;
			}

			if (!reactionsPhase)
			{
				return;
			}

			bool didTriggerFatal = DidCardPlayTriggerFatal(cardPlay);
			if (didTriggerFatal && CardEditorEffectExecutionAmountContext.TryMarkFatalTriggered(cardPlay))
			{
				await RunForCardPlayTrigger(combatState, choiceContext, cardPlay, effects, CardExtraEffectTrigger.Fatal);
			}

			if (deferredSelfScaling != null)
			{
				foreach (CardExtraEffect effect in deferredSelfScaling)
				{
					await ExecuteEffect(combatState, choiceContext, cardPlay, effect);
				}
			}

			if (powerEffectsToAdd != null && powerEffectsToAdd.Count > 0)
			{
				Dictionary<Creature, List<CardExtraEffect>> powerEffectsByHost = new Dictionary<Creature, List<CardExtraEffect>>();
				foreach (CardExtraEffect powerEffect in powerEffectsToAdd)
				{
					IReadOnlyList<Creature> hostCreatures = ResolvePowerHostCreatures(combatState, cardPlay, powerEffect);
					if (hostCreatures.Count == 0)
					{
						continue;
					}

					foreach (Creature hostCreature in hostCreatures)
					{
						if (hostCreature == null)
						{
							continue;
						}

						if (!powerEffectsByHost.TryGetValue(hostCreature, out List<CardExtraEffect>? hostEffects))
						{
							hostEffects = new List<CardExtraEffect>();
							powerEffectsByHost[hostCreature] = hostEffects;
						}

						hostEffects.Add(powerEffect);
					}
				}

				foreach ((Creature hostCreature, List<CardExtraEffect> hostEffects) in powerEffectsByHost)
				{
					CardEditorExtraEffectPower? power = hostCreature.GetPower<CardEditorExtraEffectPower>();
					if (power == null)
					{
						power = await PowerCmd.Apply<CardEditorExtraEffectPower>(hostCreature, 1, hostCreature, cardPlay.Card);
					}
					if (power != null)
					{
						await power.AddPowerEffects(cardPlay.Card, hostEffects, cardPlay);
					}
				}
			}
		}
		finally
		{
			// Exception path only: the normal flow closes (and nulls) the scope right after the
			// row loop above.
			if (sharedAttack != null)
			{
				sharedAttack.Unregister();
				await sharedAttack.DisposeContextAsync();
				sharedAttack = null;
			}

			// Expiry/bookkeeping belongs to the post-play phase; the pre-play row phase must not
			// expire "until played" grants or remember the play before the vanilla listeners ran.
			if (reactionsPhase)
			{
				if (cardPlay.IsLastInSeries)
				{
					ClearManualTarget(card);
					CardEditorTemporaryExtraEffectController.OnAfterCardPlayed(combatState, card);
					CardEditorTemporaryKeywordController.OnAfterCardPlayed(combatState, card);
					CardEditorTemporaryEnchantmentController.OnAfterCardPlayed(combatState, card);
					CardEditorTemporaryReplayController.OnAfterCardPlayed(combatState, card);
					CardEditorTemporarySelfScalingController.OnAfterCardPlayed(combatState, card);
					CardEditorMatchingCardAuraController.OnAfterCardPlayed(combatState, card);
					CardEditorCardTypeCostAuras.OnAfterCardPlayed(combatState, card);
					RefreshHandCardVisuals(card.Owner);
					await RunStatefulTransformPostCardPlayed(combatState, cardPlay);
					await EvaluateStatefulTransformConditionStops(combatState);
					await EvaluateDynamicTransforms(combatState, choiceContext, card.Owner);
					if (triggeredCardCostsLessToApplyAfter != null)
					{
						foreach (CardExtraEffect effect in triggeredCardCostsLessToApplyAfter)
						{
							ApplyTriggeredCardCostsLess(combatState, card, effect, cardPlay);
						}
					}
				}

				RememberLastPlayedCard(combatState, card);
			}
		}
	}

	/// <summary>
	/// Runs created-card OnPlay effects during <c>CardModel.OnPlay</c> so they resolve before base-game AfterCardPlayed triggers.
	/// This avoids custom cards gaining Vigor (or similar on-play power triggers) before their own damage/effects resolve.
	/// </summary>
	internal static async Task RunCreatedCardOnPlayDuringCardPlay(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay)
	{
		CardModel? card = cardPlay?.Card;
		if (combatState == null || choiceContext == null || card == null)
		{
			return;
		}

		try
		{
			IReadOnlyList<CardExtraEffect> effects = GetRuntimeEffectsIncludingBorrowedSources(combatState, card);
			await RunResolvedOnPlayEffectsDuringCardPlay(combatState, choiceContext, cardPlay, effects);
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] Created card OnPlay extra effects failed: {ex}");
		}
	}

	internal static async Task RunResolvedOnPlayEffectsDuringCardPlay(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay, IReadOnlyList<CardExtraEffect> effects)
	{
		CardModel? card = cardPlay?.Card;
		if (combatState == null || choiceContext == null || card == null || effects == null || effects.Count == 0)
		{
			return;
		}

		Creature? ownerCreature = card.TryGetOwnerCreature();
		VigorPreserver? vigor = null;
		int remainingImmediateDamageEffects = 0;
		List<CardExtraEffect>? deferredSelfScaling = null;
		using IDisposable _ = CardEditorEffectExecutionAmountContext.PushSessionScoped();
		HashSet<string> autoActionPayloadIds = BuildAutoActionPayloadIdSet(effects);
		// One attack context for all damage rows: latched powers (Gigantification, Vigor) then
		// treat the whole play as a single attack, which also retires the Vigor restore hack.
		// The scope MUST be constructed inline here (not inside an awaited factory) so the
		// AsyncLocal ambient value flows into the awaited row execution below; the context
		// itself is created lazily by the first landing row.
		SharedAttackContextScope? sharedAttack = ShouldOpenSharedAttackScope(combatState, choiceContext, cardPlay, effects, autoActionPayloadIds)
			? new SharedAttackContextScope(cardPlay, new SharedAttackContextHolder())
			: null;
		if (ownerCreature != null && sharedAttack == null)
		{
			remainingImmediateDamageEffects = effects.Count(e =>
				e != null
				&& !ShouldSkipDirectEffect(e, autoActionPayloadIds)
				&& !IsPowerEffect(e)
				&& !CardEditorAutoPlayLoopGuard.ShouldSuppressEffect(card, e)
				&& e.Trigger == CardExtraEffectTrigger.OnPlay
				&& e.Timing == CardExtraEffectTiming.Immediate
				&& e.Kind == CardExtraEffectKind.DealDamage
				&& IsValidEffectAmount(e.Kind, e.Amount));

			if (remainingImmediateDamageEffects > 1)
			{
				vigor = VigorPreserver.TryCreate(ownerCreature, cardPlay.Card);
			}
		}

		try
		{
			foreach (CardExtraEffect effect in effects)
			{
				if (ShouldSkipDirectEffect(effect, autoActionPayloadIds)
					|| IsPowerEffect(effect)
					|| CardEditorAutoPlayLoopGuard.ShouldSuppressEffect(card, effect)
					|| !IsValidEffectAmount(effect.Kind, effect.Amount)
					|| effect.Trigger != CardExtraEffectTrigger.OnPlay)
				{
					continue;
				}

				// Triggered CardCostsLess definitions intentionally apply after the play finishes.
				if (effect.Kind is (CardExtraEffectKind.CardCostsLess or CardExtraEffectKind.CardStarCostsLess) && !effect.GrantToCard)
				{
					continue;
				}

				if (IsSelfScalingKind(effect.Kind))
				{
					(deferredSelfScaling ??= new List<CardExtraEffect>()).Add(effect);
					continue;
				}

				if (effect.Timing == CardExtraEffectTiming.Immediate)
				{
					await ExecuteEffect(combatState, choiceContext, cardPlay, effect);

					if (vigor != null
						&& effect.Kind == CardExtraEffectKind.DealDamage
						&& effect.Timing == CardExtraEffectTiming.Immediate)
					{
						remainingImmediateDamageEffects = Math.Max(0, remainingImmediateDamageEffects - 1);
						if (remainingImmediateDamageEffects > 0)
						{
							await vigor.RestoreIfConsumed();
						}
					}
				}
				else
				{
					Creature? lockedTarget = null;
					Player? owner = cardPlay.Card.Owner;
					if (effect.Target == CardExtraEffectTarget.Target && owner?.Creature != null)
					{
						lockedTarget = ResolveSingleTarget(combatState, owner.Creature, cardPlay);
					}
					CardEditorExtraEffectScheduler.Schedule(combatState, cardPlay, effect, lockedTarget);
				}
			}
		}
		finally
		{
			// Close the play's attack BEFORE deferred self-scaling and the Fatal trigger below:
			// the play's single Hook.AfterAttack belongs at the end of its damage rows, and
			// Fatal-trigger damage must not join the play's own (by then closing) context.
			// Unregister runs here in THIS method's body — a restore inside the awaited dispose
			// would never flow back up, leaving a stale disposed context visible below.
			if (sharedAttack != null)
			{
				sharedAttack.Unregister();
				await sharedAttack.DisposeContextAsync();
				sharedAttack = null;
			}
		}

		if (deferredSelfScaling != null)
		{
			foreach (CardExtraEffect effect in deferredSelfScaling)
			{
				await ExecuteEffect(combatState, choiceContext, cardPlay, effect);
			}
		}

		if (vigor != null)
		{
			await vigor.FinalizeRestores();
		}

		await RunFatalForCreatedCardOnPlayIfNeeded(combatState, choiceContext, cardPlay, effects);
	}

	private static async Task RunFatalForCreatedCardOnPlayIfNeeded(
		CombatState combatState,
		PlayerChoiceContext choiceContext,
		CardPlay cardPlay,
		IReadOnlyList<CardExtraEffect> effects)
	{
		if (combatState == null
			|| choiceContext == null
			|| cardPlay?.Card == null
			|| effects == null
			|| effects.Count == 0
			|| CardEditorEffectExecutionAmountContext.HasFatalTriggered(cardPlay))
		{
			return;
		}

		List<DamageResult> currentResults = CardEditorEffectExecutionAmountContext.SnapshotCurrentPlayDamageResults();
		if (!DamageResultsTriggerFatal(cardPlay, currentResults) && !DidCardPlayTriggerFatal(cardPlay))
		{
			return;
		}

		await RunFatalForCardPlayNow(combatState, choiceContext, cardPlay);
	}

	// Plays whose immediate rows already ran appended to the card's own OnPlay (per-card OnPlay
	// postfix, CardEditorOverrideOnPlayPatcher): the AfterCardPlayed hook then runs only the
	// reactions phase for them. Keyed by CardPlay instance — the vanilla play loop creates a
	// fresh CardPlay per iteration and passes the same instance to Hook.AfterCardPlayed, so the
	// two phases align one-to-one even for multi-play cards and nested auto-plays.
	private static readonly ConditionalWeakTable<CardPlay, object> _immediateRowsRanDuringOnPlay = new();

	internal static void MarkImmediateRowsRanDuringOnPlay(CardPlay? cardPlay)
	{
		if (cardPlay != null)
		{
			_immediateRowsRanDuringOnPlay.GetOrCreateValue(cardPlay);
		}
	}

	internal static bool DidImmediateRowsRunDuringOnPlay(CardPlay? cardPlay)
		=> cardPlay != null && _immediateRowsRanDuringOnPlay.TryGetValue(cardPlay, out _);

	// Ambient AttackContext spanning all immediate damage rows of ONE card play, so latched
	// "next attack" powers (Gigantification, Vigor) treat the whole play as a single attack —
	// like vanilla loop cards (EchoingSlash) — instead of latching and paying once per row.
	// Keyed by CardPlay so nested auto-plays never join an outer play's context. The context
	// itself is created LAZILY by the first row that lands a hit: heap mutation of the holder
	// flows across awaits (only AsyncLocal WRITES are copy-on-write), so a play whose counted
	// rows all fizzle at runtime never fires BeforeAttack/AfterAttack and never burns latched
	// Vigor/Gigantification — matching the old per-row no-command behavior. Rows are awaited
	// strictly sequentially within a play; the ??= creation has no concurrent callers.
	private sealed class SharedAttackContextHolder
	{
		public AttackContext? Context;
	}

	private static readonly AsyncLocal<(CardPlay Play, SharedAttackContextHolder Holder)?> _sharedAttackContext = new();

	private static SharedAttackContextHolder? GetSharedAttackContextHolder(CardPlay? cardPlay)
	{
		(CardPlay Play, SharedAttackContextHolder Holder)? current = _sharedAttackContext.Value;
		return cardPlay != null && current != null && ReferenceEquals(current.Value.Play, cardPlay)
			? current.Value.Holder
			: null;
	}

	// Decides WITHOUT creating or registering anything: the caller constructs
	// SharedAttackContextScope INLINE in its own body (AsyncLocal writes made inside an awaited
	// async method never flow back to the caller — .NET ExecutionContext copy-on-write), and the
	// AttackContext is then created just-in-time by the first landing row.
	private static bool ShouldOpenSharedAttackScope(
		CombatState combatState,
		PlayerChoiceContext choiceContext,
		CardPlay cardPlay,
		IReadOnlyList<CardExtraEffect> effects,
		HashSet<string> autoActionPayloadIds)
	{
		CardModel? card = cardPlay?.Card;
		if (combatState == null || choiceContext == null || card == null || effects == null)
		{
			return false;
		}

		// Count only rows that will execute POWERED: opening a (powered) context for a play whose
		// damage rows are all Unpowered (Self-damage, damage-result echoes) would latch and burn
		// Vigor/Gigantification for zero benefit. The Self check must use the EFFECTIVE target —
		// on a TargetType.Self card a row authored as "Target" resolves to Self and runs Unpowered.
		int poweredImmediateDamageRows = effects.Count(e =>
			e != null
			&& !ShouldSkipDirectEffect(e, autoActionPayloadIds)
			&& !IsPowerEffect(e)
			&& !CardEditorAutoPlayLoopGuard.ShouldSuppressEffect(card, e)
			&& e.Trigger == CardExtraEffectTrigger.OnPlay
			&& e.Timing == CardExtraEffectTiming.Immediate
			&& e.Kind == CardExtraEffectKind.DealDamage
			&& !e.GrantToCard
			&& GetEffectiveResolvedTarget(cardPlay, e.Target) != CardExtraEffectTarget.Self
			&& !UsesDamageResultAmountSource(e)
			&& IsValidEffectAmount(e.Kind, e.Amount));
		return poweredImmediateDamageRows >= 2;
	}

	// NOT IAsyncDisposable on purpose: closing is a two-step the CALLER must perform inline in
	// its own method body — Unregister() first (an AsyncLocal restore made inside an awaited
	// DisposeAsync would never flow back up, leaving a stale, already-disposed context visible
	// to whatever the caller runs next, e.g. Fatal-trigger damage rows), THEN await
	// DisposeContextAsync() to fire the play's single Hook.AfterAttack — which is skipped
	// entirely when no row ever landed a hit (the lazy holder is still empty).
	private sealed class SharedAttackContextScope
	{
		private readonly (CardPlay Play, SharedAttackContextHolder Holder)? _previous;
		private readonly SharedAttackContextHolder _holder;

		public SharedAttackContextScope(CardPlay cardPlay, SharedAttackContextHolder holder)
		{
			_previous = _sharedAttackContext.Value;
			_holder = holder;
			_sharedAttackContext.Value = (cardPlay, holder);
		}

		public void Unregister()
		{
			_sharedAttackContext.Value = _previous;
		}

		public ValueTask DisposeContextAsync()
			=> _holder.Context is { } context ? context.DisposeAsync() : default;
	}

	// Joins the play's shared attack holder when one is registered (never owns it); otherwise
	// owns a context of its own. In BOTH modes the context is created lazily by Ensure() right
	// before the first hit, so loops that never land a hit never fire BeforeAttack/AfterAttack
	// (no Vigor/Gigantification burn on all-fizzle repeats).
	private sealed class AttackContextLease : IAsyncDisposable
	{
		private readonly CombatState _combatState;
		private readonly PlayerChoiceContext _choiceContext;
		private readonly CardPlay _cardPlay;
		private readonly SharedAttackContextHolder? _sharedHolder;
		private AttackContext? _owned;

		public AttackContextLease(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay)
		{
			_combatState = combatState;
			_choiceContext = choiceContext;
			_cardPlay = cardPlay;
			_sharedHolder = GetSharedAttackContextHolder(cardPlay);
		}

		public async ValueTask<AttackContext> Ensure()
		{
			if (_sharedHolder != null)
			{
				return _sharedHolder.Context ??= await AttackCommand.CreateContextAsync(_combatState, _choiceContext, _cardPlay);
			}
			return _owned ??= await AttackCommand.CreateContextAsync(_combatState, _choiceContext, _cardPlay);
		}

		public async ValueTask DisposeAsync()
		{
			if (_owned is { } owned)
			{
				await owned.DisposeAsync();
			}
		}
	}

	// Executes one DealDamage row inside the play's shared attack context, replicating the
	// AttackCommand semantics (per-hit target re-roll / living re-filter) via CreatureCmd.Damage.
	// The context is created lazily on the first hit that is about to land.
	private static async Task ExecuteDamageRowInSharedContext(
		CombatState combatState,
		PlayerChoiceContext choiceContext,
		CardPlay cardPlay,
		CardExtraEffect effect,
		Creature ownerCreature,
		int amount,
		int repeats,
		CardExtraEffectTarget resolvedTarget,
		bool preserveSelfHp,
		SharedAttackContextHolder holder)
	{
		ValueProp damageProps = ValueProp.Move;
		if (UsesDamageResultAmountSource(effect) || resolvedTarget == CardExtraEffectTarget.Self)
		{
			damageProps |= ValueProp.Unpowered;
		}

		int safeRepeats = Math.Clamp(repeats <= 0 ? 1 : repeats, 1, 99);

		// Single targets resolve ONCE (like the AttackCommand path this replaces): re-resolving
		// per repeat would consume a CombatTargets roll per hit and redirect to random enemies
		// when the locked target dies, instead of simply stopping.
		Creature? lockedSingleTarget = null;
		bool usesSingleTarget = resolvedTarget is not (CardExtraEffectTarget.AllEnemies
			or CardExtraEffectTarget.RandomEnemy
			or CardExtraEffectTarget.Self);
		if (usesSingleTarget)
		{
			Creature? single = ResolveSingleTarget(combatState, ownerCreature, cardPlay);
			if (single == null || (preserveSelfHp && ReferenceEquals(single, ownerCreature)))
			{
				return;
			}

			lockedSingleTarget = single;
		}

		List<DamageResult> allResults = new List<DamageResult>();
		for (int repeatIndex = 0; repeatIndex < safeRepeats; repeatIndex++)
		{
			if (!ownerCreature.IsAlive)
			{
				break;
			}

			if (usesSingleTarget && (lockedSingleTarget == null || !lockedSingleTarget.IsAlive))
			{
				break;
			}

			List<Creature> targets;
			switch (resolvedTarget)
			{
				case CardExtraEffectTarget.AllEnemies:
					targets = ResolveTargets(combatState, ownerCreature, cardPlay, CardExtraEffectTarget.AllEnemies)
						.Where(c => c != null && c.IsAlive)
						.ToList();
					break;
				case CardExtraEffectTarget.RandomEnemy:
				{
					// Vanilla re-rolls the random target per hit from the CombatTargets stream.
					// PetOwner fallback matches AttackCommand: pet attackers (Osty) have no Player.
					List<Creature> living = ResolveTargets(combatState, ownerCreature, cardPlay, CardExtraEffectTarget.AllEnemies)
						.Where(c => c != null && c.IsAlive)
						.ToList();
					Creature? rolled = living.Count > 0
						? (ownerCreature.Player ?? ownerCreature.PetOwner)?.RunState?.Rng?.CombatTargets?.NextItem(living)
						: null;
					targets = rolled != null ? new List<Creature> { rolled } : new List<Creature>();
					break;
				}
				case CardExtraEffectTarget.Self:
					targets = preserveSelfHp ? new List<Creature>() : new List<Creature> { ownerCreature };
					break;
				default:
					targets = new List<Creature> { lockedSingleTarget! };
					break;
			}

			if (targets.Count == 0)
			{
				continue;
			}

			// JIT: fire the play's single Hook.BeforeAttack only when a hit is actually about
			// to land — vanilla fires it before the first damage computation (AttackContext
			// CreateAsync / AttackCommand.Execute), so this preserves Vigor/Gigantification
			// ModifyDamage on this very hit while all-fizzle plays never latch at all.
			AttackContext attackContext = holder.Context ??= await AttackCommand.CreateContextAsync(combatState, choiceContext, cardPlay);
			IEnumerable<DamageResult> rawResults = await CreatureCmd.Damage(choiceContext, targets, amount, damageProps, ownerCreature, cardPlay.Card, cardPlay);
			List<DamageResult> results = rawResults?.Where(r => r != null).ToList() ?? new List<DamageResult>();
			if (results.Count == 0)
			{
				continue;
			}

			attackContext.AddHit(results);
			allResults.AddRange(results);
		}

		if (allResults.Count > 0)
		{
			CardEditorEffectExecutionAmountContext.ReportCurrentDamageResults(allResults);
			int totalDamage = ClampLongToInt(allResults.Sum(r => (long)Math.Max(0, r.TotalDamage)));
			int blockedDamage = ClampLongToInt(allResults.Sum(r => (long)Math.Max(0, r.BlockedDamage)));
			int overkillDamage = ClampLongToInt(allResults.Sum(r => (long)Math.Max(0, r.OverkillDamage)));
			int damageInstances = allResults.Count(r => r.TotalDamage > 0);
			CardEditorEffectExecutionAmountContext.ReportCurrentDamageTotals(totalDamage, damageInstances, blockedDamage, overkillDamage);
			await RunFatalImmediatelyForDamageResultsIfNeeded(
				combatState,
				choiceContext,
				cardPlay,
				GetRuntimeEffectsIncludingBorrowedSources(combatState, cardPlay.Card),
				ownerCreature,
				allResults);
		}
	}

	private sealed class VigorPreserver
	{
		private readonly Creature _target;
		private readonly Creature _applier;
		private readonly CardModel _cardSource;
		private readonly int _startAmount;
		private int _restoredAmount;

		private VigorPreserver(Creature target, CardModel cardSource, int startAmount)
		{
			_target = target;
			_applier = target;
			_cardSource = cardSource;
			_startAmount = startAmount;
		}

		public static VigorPreserver? TryCreate(Creature target, CardModel cardSource)
		{
			if (target == null || cardSource == null)
			{
				return null;
			}
			VigorPower? power = target.GetPower<VigorPower>();
			int amount = power?.Amount ?? 0;
			return amount > 0 ? new VigorPreserver(target, cardSource, amount) : null;
		}

		public async Task RestoreIfConsumed()
		{
			VigorPower? current = _target.GetPower<VigorPower>();
			int currentAmount = current?.Amount ?? 0;
			if (currentAmount >= _startAmount)
			{
				return;
			}

			int need = _startAmount - currentAmount;
			if (need <= 0)
			{
				return;
			}

			try
			{
				_ = await PowerCmd.Apply<VigorPower>(_target, need, _applier, _cardSource);
				_restoredAmount += need;
			}
			catch
			{
			}
		}

		public async Task FinalizeRestores()
		{
			if (_restoredAmount <= 0)
			{
				return;
			}

			VigorPower? power = _target.GetPower<VigorPower>();
			if (power == null)
			{
				return;
			}

			try
			{
				if (power.Amount <= _restoredAmount)
				{
					await PowerCmd.Remove(power);
				}
				else
				{
					await PowerCmd.ModifyAmount(power, -_restoredAmount, _applier, _cardSource);
				}
			}
			catch
			{
			}
		}
	}

