	private static async Task RunForTurnBoundary(CombatState combatState, PlayerChoiceContext choiceContext, CardModel card, CardExtraEffectTurnBoundary boundary, CardExtraEffectTurnBoundarySide side)
	{
		if (combatState == null || choiceContext == null || card == null)
		{
			return;
		}

		try
		{
			using IDisposable _ = CardEditorEffectExecutionAmountContext.PushSessionScoped();
			List<CardExtraEffect> effects = GetRuntimeEffectsIncludingBorrowedSources(combatState, card).ToList();
			if (effects.Count == 0)
			{
				return;
			}
			HashSet<string> autoActionPayloadIds = BuildAutoActionPayloadIdSet(effects);

			CardPlay syntheticPlay = new CardPlay
			{
				Card = card,
				Player = card.Owner,
				Target = null,
				ResultPile = card.Pile?.Type ?? PileType.None,
				Resources = new ResourceInfo
				{
					EnergySpent = 0,
					EnergyValue = 0,
					StarsSpent = 0,
					StarValue = 0
				},
				IsAutoPlay = true,
				PlayIndex = 0,
				PlayCount = 1
			};

			foreach (CardExtraEffect effect in effects)
			{
				if (ShouldSkipDirectEffect(effect, autoActionPayloadIds)
					|| IsPowerEffect(effect)
					|| !IsValidEffectAmount(effect.Kind, effect.Amount)
					|| !DoesTurnBoundaryMatch(effect, boundary, side, card))
				{
					continue;
				}

				CardExtraEffect? normalizedSelfPileAuto = NormalizeSelfPileAutoEffect(effect);
				if (normalizedSelfPileAuto?.Kind is CardExtraEffectKind.ConditionalAutoPlayFromPile or CardExtraEffectKind.ConditionalAutoDrawFromPile or CardExtraEffectKind.ConditionalAutoRunEffects)
				{
					if (await TryRunSelfPileAutoEffect(combatState, choiceContext, card, normalizedSelfPileAuto))
					{
						return;
					}
					continue;
				}

				if (effect.Kind is (CardExtraEffectKind.CardCostsLess or CardExtraEffectKind.CardStarCostsLess) && !effect.GrantToCard)
				{
					if (IsTriggeredCardCostsLessDefinition(effect))
					{
						ApplyTriggeredCardCostsLess(combatState, card, effect, syntheticPlay);
					}
					continue;
				}

				if (effect.Timing == CardExtraEffectTiming.Immediate)
				{
					await ExecuteEffect(combatState, choiceContext, syntheticPlay, effect);
				}
				else
				{
					Creature? lockedTarget = null;
					Player? owner = card.Owner;
					if (effect.Target == CardExtraEffectTarget.Target && owner?.Creature != null)
					{
						lockedTarget = ResolveSingleTarget(combatState, owner.Creature, syntheticPlay);
					}
					CardEditorExtraEffectScheduler.Schedule(combatState, syntheticPlay, effect, lockedTarget);
				}
			}
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] Extra turn-boundary effects (boundary={boundary}, side={side}) failed: {ex}");
		}
	}

	private static async Task RunForCardPlayTrigger(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay, IReadOnlyList<CardExtraEffect> effects, CardExtraEffectTrigger trigger)
	{
		if (combatState == null || choiceContext == null || cardPlay?.Card == null || effects == null || effects.Count == 0)
		{
			return;
		}

		using IDisposable _ = CardEditorEffectExecutionAmountContext.PushSessionScoped();
		using IDisposable fatalScope = CardEditorFatalExecutionContext.PushScopedIf(trigger == CardExtraEffectTrigger.Fatal);
		// Fatal rows are a SEPARATE attack: vanilla kill bonuses (Feed/TheHunt/HandOfGreed/
		// KnockoutBlow/Sunder) run after the killing attack's Execute() — after its
		// Hook.AfterAttack — so kill-triggered Fatal damage must open its own context, never
		// join this play's still-open one (reachable via nested borrowed-source re-entry,
		// mid-row immediate Fatal, and the AfterDeath final-kill path). Written inline in THIS
		// body so it flows down into the awaited rows; ExecutionContext copy-on-write means it
		// never flows back to the caller, whose ambient pair is intact on return — no restore
		// needed. That guarantee holds only while this method stays async.
		if (trigger == CardExtraEffectTrigger.Fatal
			&& _sharedAttackContext.Value is { } maskedSharedPair
			&& ReferenceEquals(maskedSharedPair.Play, cardPlay))
		{
			_sharedAttackContext.Value = null;
		}
		HashSet<string> autoActionPayloadIds = BuildAutoActionPayloadIdSet(effects);
		foreach (CardExtraEffect effect in effects)
		{
			if (ShouldSkipDirectEffect(effect, autoActionPayloadIds)
				|| IsPowerEffect(effect)
				|| CardEditorAutoPlayLoopGuard.ShouldSuppressEffect(cardPlay.Card, effect)
				|| !IsValidEffectAmount(effect.Kind, effect.Amount)
				|| effect.Trigger != trigger)
			{
				continue;
			}

			if (effect.Kind is (CardExtraEffectKind.CardCostsLess or CardExtraEffectKind.CardStarCostsLess) && !effect.GrantToCard)
			{
				if (IsTriggeredCardCostsLessDefinition(effect))
				{
					ApplyTriggeredCardCostsLess(combatState, cardPlay.Card, effect, cardPlay);
				}
				continue;
			}

			if (effect.Timing == CardExtraEffectTiming.Immediate)
			{
				await ExecuteEffect(combatState, choiceContext, cardPlay, effect);
			}
			else
			{
				Creature? lockedTarget = null;
				Player? owner = cardPlay.Card.Owner;
				if (effect.Target == CardExtraEffectTarget.Target && owner?.Creature != null)
				{
					lockedTarget = ResolveSingleTarget(combatState, owner.Creature, cardPlay);
				}
				CardEditorExtraEffectScheduler.Schedule(combatState, cardPlay, effect, lockedTarget);
			}
		}
	}

	private static bool DidCardPlayTriggerFatal(CardPlay cardPlay)
	{
		if (cardPlay?.Card?.Owner?.Creature == null)
		{
			return false;
		}

		CombatHistory? history = CombatManager.Instance?.History;
		if (history == null)
		{
			return false;
		}

		CombatSide ownerSide = cardPlay.Card.Owner.Creature.Side;
		foreach (CombatHistoryEntry entry in history.Entries.Reverse())
		{
			if (entry is CardPlayStartedEntry startedEntry)
			{
				// Only consider damage entries that occurred during this specific CardPlay.
				// Once we hit the start marker for this play, we stop scanning history.
				if (ReferenceEquals(startedEntry.CardPlay, cardPlay))
				{
					break;
				}
				continue;
			}

			if (entry is not DamageReceivedEntry damageEntry)
			{
				continue;
			}

			bool matchesSource = ReferenceEquals(damageEntry.CardSource, cardPlay.Card)
				|| (damageEntry.CardSource == null && ReferenceEquals(damageEntry.Dealer, cardPlay.Card.Owner.Creature));
			if (!matchesSource
				|| damageEntry.Result == null
				|| !damageEntry.Result.WasTargetKilled
				|| damageEntry.Receiver == null
				|| damageEntry.Receiver.Side == ownerSide)
			{
				continue;
			}

			if (damageEntry.Receiver.Powers.All(p => p.ShouldOwnerDeathTriggerFatal()))
			{
				return true;
			}
		}

		Creature? target = cardPlay.Target;
		if (target != null
			&& target.Side != ownerSide
			&& target.IsDead
			&& target.Powers.All(p => p.ShouldOwnerDeathTriggerFatal()))
		{
			return true;
		}

		return false;
	}

	private static bool DamageResultsTriggerFatal(CardPlay? cardPlay, IEnumerable<DamageResult>? results)
	{
		if (cardPlay?.Card?.Owner?.Creature == null || results == null)
		{
			return false;
		}

		CombatSide ownerSide = cardPlay.Card.Owner.Creature.Side;
		foreach (DamageResult? result in results)
		{
			Creature? receiver = result?.Receiver;
			if (receiver == null
				|| receiver.Side == ownerSide
				|| result == null
				|| !result.WasTargetKilled)
			{
				continue;
			}

			if (receiver.Powers.All(power => power.ShouldOwnerDeathTriggerFatal()))
			{
				return true;
			}
		}

		return false;
	}

	private static bool IsCombatEndingKill(CombatState? combatState, Creature? ownerCreature, IEnumerable<DamageResult>? results)
	{
		if (combatState == null || ownerCreature == null || results == null)
		{
			return false;
		}

		HashSet<Creature> killed = new HashSet<Creature>(ReferenceEqualityComparer<Creature>.Instance);
		foreach (DamageResult? result in results)
		{
			Creature? receiver = result?.Receiver;
			if (receiver != null
				&& result != null
				&& result.WasTargetKilled
				&& receiver.Side != ownerCreature.Side)
			{
				killed.Add(receiver);
			}
		}

		if (killed.Count == 0)
		{
			return false;
		}

		foreach (Creature opponent in combatState.GetOpponentsOf(ownerCreature))
		{
			if (opponent == null)
			{
				continue;
			}

			if (opponent.IsAlive && !killed.Contains(opponent))
			{
				return false;
			}
		}

		return true;
	}

	private static async Task RunFatalImmediatelyForDamageResultsIfNeeded(
		CombatState combatState,
		PlayerChoiceContext choiceContext,
		CardPlay cardPlay,
		IReadOnlyList<CardExtraEffect> effects,
		Creature ownerCreature,
		IEnumerable<DamageResult>? results)
	{
		if (combatState == null
			|| choiceContext == null
			|| cardPlay?.Card == null
			|| effects == null
			|| effects.Count == 0
			|| ownerCreature == null
			|| !DamageResultsTriggerFatal(cardPlay, results)
			|| !IsCombatEndingKill(combatState, ownerCreature, results)
			|| !CardEditorEffectExecutionAmountContext.TryMarkFatalTriggered(cardPlay))
		{
			return;
		}

		await RunForCardPlayTrigger(combatState, choiceContext, cardPlay, effects, CardExtraEffectTrigger.Fatal);
	}

	internal static async Task RunFatalForCardPlayNow(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay)
	{
		if (combatState == null
			|| choiceContext == null
			|| cardPlay?.Card == null
			|| !CardEditorEffectExecutionAmountContext.TryMarkFatalTriggered(cardPlay))
		{
			return;
		}

		IReadOnlyList<CardExtraEffect> effects = GetRuntimeEffectsIncludingBorrowedSources(combatState, cardPlay.Card);
		if (effects.Count == 0)
		{
			return;
		}

		await RunForCardPlayTrigger(combatState, choiceContext, cardPlay, effects, CardExtraEffectTrigger.Fatal);
	}

	private static readonly PileType[] SelfPileAutoPileTypes =
	{
		PileType.Hand,
		PileType.Exhaust,
		PileType.Discard,
		PileType.Draw,
		PileType.Deck
	};

	private static List<CardModel> SnapshotSelfPileAutoCards(Player player)
	{
		List<CardModel> cards = new List<CardModel>();
		if (player == null)
		{
			return cards;
		}

		HashSet<CardModel> seen = new HashSet<CardModel>(ReferenceEqualityComparer<CardModel>.Instance);
		foreach (PileType pileType in SelfPileAutoPileTypes)
		{
			CardPile? pile = pileType.GetPile(player);
			if (pile?.Cards == null || pile.Cards.Count == 0)
			{
				continue;
			}

			foreach (CardModel card in pile.Cards.Where(c => c != null).ToList())
			{
				if (seen.Add(card))
				{
					cards.Add(card);
				}
			}
		}

		return cards;
	}

	// Cheap pre-scan for the drawn/discarded/exhausted trigger patches: true when any card
	// in the swept piles might carry a self-pile auto row (AutoPlay/AutoDraw/AutoRun kinds).
	// Conservative (never false while a candidate exists): per-card answers are version-
	// cached and any combat grant flips the whole check to true.
	internal static bool HasAnySelfPileAutoCandidates(CombatState combatState, Player player)
	{
		if (combatState == null || player == null)
		{
			return false;
		}

		if (CardEditorRuntimeCaches.CombatHasAnyGrantedEffects(combatState))
		{
			return true;
		}

		foreach (PileType pileType in SelfPileAutoPileTypes)
		{
			CardPile? pile = pileType.GetPile(player);
			if (pile?.Cards == null || pile.Cards.Count == 0)
			{
				continue;
			}

			foreach (CardModel? card in pile.Cards)
			{
				if (card != null
					&& CardEditorRuntimeCaches.CardMightHaveRuntimeEffectKind(combatState, card, CardEditorRuntimeCaches.SelfPileAutoBits))
				{
					return true;
				}
			}
		}

		return false;
	}

	public static async Task RunAutoPlaySelfFromPile(CombatState combatState, PlayerChoiceContext choiceContext, Player player, CardExtraEffectTrigger trigger)
	{
		if (combatState == null || choiceContext == null || player == null)
		{
			return;
		}

		foreach (CardModel card in SnapshotSelfPileAutoCards(player))
		{
			await TryAutoPlaySelfFromPile(combatState, choiceContext, card, trigger);
		}
	}

	private static async Task TryAutoPlaySelfFromPile(CombatState combatState, PlayerChoiceContext choiceContext, CardModel card, CardExtraEffectTrigger trigger)
	{
		// Card may have been moved by a previous auto-play
		CardPile? cardPile = card.Pile;
		if (cardPile == null || cardPile.Type == PileType.Play)
		{
			return;
		}

		// Version-cached prefilter: skip the effects rebuild for cards that provably
		// carry no self-pile auto rows (the overwhelmingly common case).
		if (!CardEditorRuntimeCaches.CardMightHaveRuntimeEffectKind(combatState, card, CardEditorRuntimeCaches.SelfPileAutoBits))
		{
			return;
		}

		List<CardExtraEffect> effects = new List<CardExtraEffect>();
		foreach (CardExtraEffect e in GetRuntimeEffectsIncludingBorrowedSources(combatState, card))
		{
			// Power-hosted auto rows (Whenever and other power triggers) execute through the
			// power pipeline; sweeping them here too would double-fire them.
			if (IsPowerEffect(e))
			{
				continue;
			}
			CardExtraEffect? normalized = NormalizeSelfPileAutoEffect(e);
			if (normalized?.Kind == CardExtraEffectKind.ConditionalAutoPlayFromPile)
			{
				effects.Add(normalized);
			}
		}

		foreach (CardExtraEffect effect in effects)
		{
			if (!DoesTriggerMatch(effect, trigger, card))
			{
				continue;
			}

			if (await TryRunSelfPileAutoEffect(combatState, choiceContext, card, effect))
			{
				return; // Only auto-play once per card per trigger
			}
		}
	}

	public static async Task RunAutoDrawSelfFromPile(CombatState combatState, PlayerChoiceContext choiceContext, Player player, CardExtraEffectTrigger trigger)
	{
		if (combatState == null || choiceContext == null || player == null)
		{
			return;
		}

		await RunAutoRunEffectRowsFromPile(combatState, choiceContext, player, trigger);

		foreach (CardModel card in SnapshotSelfPileAutoCards(player))
		{
			await TryAutoDrawSelfFromPile(combatState, choiceContext, card, trigger);
		}
	}

	public static async Task RunAutoRunEffectRowsFromPile(CombatState combatState, PlayerChoiceContext choiceContext, Player player, CardExtraEffectTrigger trigger)
	{
		if (combatState == null || choiceContext == null || player == null)
		{
			return;
		}

		foreach (CardModel card in SnapshotSelfPileAutoCards(player))
		{
			await TryAutoRunEffectRowsFromPile(combatState, choiceContext, card, trigger);
		}
	}

	private static async Task TryAutoRunEffectRowsFromPile(CombatState combatState, PlayerChoiceContext choiceContext, CardModel card, CardExtraEffectTrigger trigger)
	{
		CardPile? cardPile = card.Pile;
		if (cardPile == null || cardPile.Type == PileType.Play)
		{
			return;
		}

		// Version-cached prefilter (see TryAutoPlaySelfFromPile).
		if (!CardEditorRuntimeCaches.CardMightHaveRuntimeEffectKind(combatState, card, CardEditorRuntimeCaches.SelfPileAutoBits))
		{
			return;
		}

		List<CardExtraEffect> effects = new List<CardExtraEffect>();
		foreach (CardExtraEffect e in GetRuntimeEffectsIncludingBorrowedSources(combatState, card))
		{
			// Power-hosted auto rows execute through the power pipeline (no double-fire).
			if (IsPowerEffect(e))
			{
				continue;
			}
			CardExtraEffect? normalized = NormalizeSelfPileAutoEffect(e);
			if (normalized?.Kind == CardExtraEffectKind.ConditionalAutoRunEffects)
			{
				effects.Add(normalized);
			}
		}

		foreach (CardExtraEffect effect in effects)
		{
			if (!DoesTriggerMatch(effect, trigger, card))
			{
				continue;
			}

			if (await TryRunSelfPileAutoEffect(combatState, choiceContext, card, effect))
			{
				return;
			}
		}
	}

	private static async Task TryAutoDrawSelfFromPile(CombatState combatState, PlayerChoiceContext choiceContext, CardModel card, CardExtraEffectTrigger trigger)
	{
		CardPile? cardPile = card.Pile;
		if (cardPile == null || cardPile.Type == PileType.Hand || cardPile.Type == PileType.Play)
		{
			return;
		}

		// Version-cached prefilter (see TryAutoPlaySelfFromPile).
		if (!CardEditorRuntimeCaches.CardMightHaveRuntimeEffectKind(combatState, card, CardEditorRuntimeCaches.SelfPileAutoBits))
		{
			return;
		}

		List<CardExtraEffect> effects = new List<CardExtraEffect>();
		foreach (CardExtraEffect e in GetRuntimeEffectsIncludingBorrowedSources(combatState, card))
		{
			// Power-hosted auto rows execute through the power pipeline (no double-fire).
			if (IsPowerEffect(e))
			{
				continue;
			}
			CardExtraEffect? normalized = NormalizeSelfPileAutoEffect(e);
			if (normalized?.Kind == CardExtraEffectKind.ConditionalAutoDrawFromPile)
			{
				effects.Add(normalized);
			}
		}

		foreach (CardExtraEffect effect in effects)
		{
			if (!DoesTriggerMatch(effect, trigger, card))
			{
				continue;
			}

			if (await TryRunSelfPileAutoEffect(combatState, choiceContext, card, effect))
			{
				return; // Only draw once per card per trigger
			}
		}
	}

	private static async Task<bool> TryRunSelfPileAutoEffect(CombatState combatState, PlayerChoiceContext choiceContext, CardModel card, CardExtraEffect effect)
	{
		CardExtraEffect? normalized = NormalizeSelfPileAutoEffect(effect);
		if (normalized?.Kind is not (CardExtraEffectKind.ConditionalAutoPlayFromPile or CardExtraEffectKind.ConditionalAutoDrawFromPile or CardExtraEffectKind.ConditionalAutoRunEffects))
		{
			return false;
		}
		// Power-hosted activations were already counted (and tokened) by ExecuteOrSchedulePowerEffect
		// with a precount mark; without the handshake the activation's OWN token would self-suppress
		// its first execution (Allow Self Trigger unticked) and the inner action would double-count
		// the chain caps. Nested re-entries from the played card's hooks are NEW activations with
		// their own precount tokens, so suppression and chain accounting still apply one level down.
		bool activationPrecounted = CardEditorAutoPlayLoopGuard.IsAutoPlayEffectPrecounted(combatState, card?.Owner, card, normalized);
		if (!activationPrecounted && CardEditorAutoPlayLoopGuard.ShouldSuppressEffect(card, normalized))
		{
			return false;
		}

		CardPile? currentPile = card?.Pile;
		if (currentPile == null || currentPile.Type == PileType.Play)
		{
			return false;
		}

		if (normalized.CardSelectionPile != CardExtraEffectCardPile.AllPiles)
		{
			PileType requiredType = ResolvePileType(normalized.CardSelectionPile);
			if (currentPile.Type != requiredType)
			{
				return false;
			}
		}

		if (!IsCardAtConfiguredPilePosition(card, normalized.CardSelectionMode))
		{
			return false;
		}

		if (normalized.Kind == CardExtraEffectKind.ConditionalAutoDrawFromPile && currentPile.Type == PileType.Hand)
		{
			return false;
		}

		if (normalized.ScaleMode != CardExtraEffectScaleMode.None)
		{
			if (CardEditorConditionalFromPileFiredTracker.HasFired(combatState, card))
			{
				return false;
			}

			int count = GetHistoryCountMultiplier(combatState, card.TryGetOwnerCreature(), null, normalized, card);
			if (!DoesCountConditionPass(count, normalized))
			{
				return false;
			}

			CardEditorConditionalFromPileFiredTracker.MarkFired(combatState, card);
		}

		// SINGLE Use Limit consumption point for auto actions, AFTER every precondition gate so a
		// non-matching trigger firing never burns a use. Power-hosted rows skip the generic
		// ExecuteEffect consumption for exactly this reason; the power path's per-entry instance
		// key still applies because PushUseLimitSourceInstance's ambient value flows down here.
		// Card-hosted rows previously consumed only via the silent ExecuteEffect no-op pass
		// (double-fast, never gating) — this consumes once and actually enforces the limit.
		if (!CardEditorAutoPlayLoopGuard.TryConsumeEffectUseLimit(combatState, card?.Owner, card, normalized))
		{
			return false;
		}

		if (normalized.Kind == CardExtraEffectKind.ConditionalAutoPlayFromPile)
		{
			await AutoPlayCardFromEffect(combatState, choiceContext, card.Owner, card, normalized, card, activationPrecounted);
		}
		else if (normalized.Kind == CardExtraEffectKind.ConditionalAutoDrawFromPile)
		{
			// The draw variant historically had no guard entry at all; chain-count it like its
			// siblings (skipped when the power path already counted this activation).
			if (!CardEditorAutoPlayLoopGuard.TryEnterAutoPlayEffect(combatState, card.Owner, card, normalized, out IDisposable drawScope, consumeActivation: !activationPrecounted))
			{
				return false;
			}
			using (drawScope)
			{
				await DrawCardFromPileToHand(choiceContext, card);
			}
		}
		else
		{
			await RunSelectedAutoActionEffectRows(combatState, choiceContext, card, normalized, activationPrecounted);
		}

		return true;
	}

	private static async Task DrawCardFromPileToHand(PlayerChoiceContext choiceContext, CardModel card)
	{
		if (choiceContext == null || card == null)
		{
			return;
		}

		Player? owner = card.Owner;
		if (owner == null)
		{
			return;
		}

		await CardPileCmd.Add(card, PileType.Hand);
		CombatState? combatState = owner.Creature.GetConcreteCombatState() ?? card.GetConcreteCombatState();
		if (combatState != null)
		{
			CombatManager.Instance.History.CardDrawn(combatState, card, fromHandDraw: false);
			await Hook.AfterCardDrawn(combatState, choiceContext, card, fromHandDraw: false);
		}
		card.InvokeDrawn();
	}

	private static async Task AutoPlayCardFromEffect(
		CombatState? combatState,
		PlayerChoiceContext choiceContext,
		Player? owner,
		CardModel? sourceCard,
		CardExtraEffect? sourceEffect,
		CardModel card,
		bool activationPrecounted = false)
	{
		if (choiceContext == null || card == null)
		{
			return;
		}

		if (!CardEditorAutoPlayLoopGuard.TryEnterAutoPlay(combatState, owner ?? card.Owner, sourceCard, sourceEffect, card, out IDisposable scope, consumeActivation: !activationPrecounted))
		{
			return;
		}

		using (scope)
		{
			await AutoPlayCardUsingVanillaSelections(choiceContext, card, owner ?? card.Owner);
		}
	}

	private static async Task RunSelectedAutoActionEffectRows(CombatState combatState, PlayerChoiceContext choiceContext, CardModel card, CardExtraEffect autoEffect, bool activationPrecounted = false)
	{
		List<string> selectedIds = ParseAutoActionEffectIds(autoEffect);
		if (combatState == null || choiceContext == null || card == null || selectedIds.Count == 0)
		{
			return;
		}

		if (!CardEditorAutoPlayLoopGuard.TryEnterAutoPlayEffect(combatState, card.Owner, card, autoEffect, out IDisposable autoScope, consumeActivation: !activationPrecounted))
		{
			return;
		}

		using (autoScope)
		{
			Dictionary<string, CardExtraEffect> runtimeEffectsById = GetRuntimeEffectsIncludingBorrowedSources(combatState, card)
				.Where(e => e != null && !string.IsNullOrWhiteSpace(e.EffectId))
				.GroupBy(e => e.EffectId!, StringComparer.Ordinal)
				.ToDictionary(g => g.Key, g => g.First(), StringComparer.Ordinal);

			CardPlay syntheticPlay = new CardPlay
			{
				Card = card,
				Player = card.Owner,
				Target = null,
				ResultPile = card.Pile?.Type ?? PileType.None,
				Resources = new ResourceInfo
				{
					EnergySpent = 0,
					EnergyValue = 0,
					StarsSpent = 0,
					StarValue = 0
				},
				IsAutoPlay = true,
				PlayIndex = 0,
				PlayCount = 1
			};

			foreach (string id in selectedIds)
			{
				if (string.Equals(id, AutoActionVanillaOnPlayTargetId, StringComparison.Ordinal))
				{
					await RunVanillaOnPlayPayload(choiceContext, syntheticPlay);
					continue;
				}

				if (string.Equals(id, autoEffect.EffectId ?? string.Empty, StringComparison.Ordinal)
					|| !runtimeEffectsById.TryGetValue(id, out CardExtraEffect? payload)
					|| payload.Kind is CardExtraEffectKind.ConditionalAutoPlayFromPile
						or CardExtraEffectKind.ConditionalAutoDrawFromPile
						or CardExtraEffectKind.ConditionalAutoRunEffects
						or CardExtraEffectKind.AutoPlaySelfFromPile
						or CardExtraEffectKind.AutoDrawSelfFromPile
						or CardExtraEffectKind.Quest
					|| !IsValidEffectAmount(payload.Kind, payload.Amount))
				{
					continue;
				}

				CardExtraEffect runnable = CloneEffect(payload);
				runnable.Trigger = CardExtraEffectTrigger.OnPlay;
				runnable.AsPower = false;
				if (CardEditorAutoPlayLoopGuard.ShouldSuppressEffect(card, runnable))
				{
					continue;
				}

				if (runnable.Timing == CardExtraEffectTiming.Immediate)
				{
					await ExecuteEffect(combatState, choiceContext, syntheticPlay, runnable);
				}
				else
				{
					Creature? lockedTarget = null;
					Player? owner = card.Owner;
					if (runnable.Target == CardExtraEffectTarget.Target && owner?.Creature != null)
					{
						lockedTarget = ResolveSingleTarget(combatState, owner.Creature, syntheticPlay);
					}
					CardEditorExtraEffectScheduler.Schedule(combatState, syntheticPlay, runnable, lockedTarget);
				}
			}
		}
	}

	private static async Task RunVanillaOnPlayPayload(PlayerChoiceContext choiceContext, CardPlay syntheticPlay)
	{
		CardModel? card = syntheticPlay?.Card;
		if (card == null || card is CardEditorCreatedCardBase)
		{
			return;
		}

		try
		{
			MethodInfo? onPlay = ResolveCardOnPlayMethod(card.GetType());
			if (onPlay == null)
			{
				return;
			}

			object? result;
			// Suppress the override-OnPlay postfix for this reflective call: the payload row's
			// own play already runs the card's override rows — composing them here re-runs them.
			using (CardEditorReflectiveOnPlayGuard.PushScoped())
			{
				result = onPlay.Invoke(card, new object?[] { choiceContext, syntheticPlay });
			}
			if (result is Task task)
			{
				await task;
			}
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] Auto action vanilla payload failed for {card.Id}: {ex}");
		}
	}

	private static MethodInfo? ResolveCardOnPlayMethod(Type? cardType)
	{
		for (Type? cursor = cardType; cursor != null; cursor = cursor.BaseType)
		{
			MethodInfo? method = cursor.GetMethod("OnPlay", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (method != null)
			{
				return method;
			}
		}

		return null;
	}

	public static async Task RunConditionalAutoFromPile(CombatState combatState, PlayerChoiceContext choiceContext, Player player)
	{
		if (combatState == null || choiceContext == null || player == null)
		{
			return;
		}

		foreach (CardModel card in SnapshotSelfPileAutoCards(player))
		{
			await TryConditionalAutoFromPile(combatState, choiceContext, card);
		}
	}

	private static async Task TryConditionalAutoFromPile(CombatState combatState, PlayerChoiceContext choiceContext, CardModel card)
	{
		CardPile? cardPile = card.Pile;
		if (cardPile == null || cardPile.Type == PileType.Play)
		{
			return;
		}

		if (CardEditorConditionalFromPileFiredTracker.HasFired(combatState, card))
		{
			return;
		}

		List<CardExtraEffect> effects = new List<CardExtraEffect>();
		foreach (CardExtraEffect e in GetRuntimeEffectsIncludingBorrowedSources(combatState, card))
		{
			// Power-hosted auto rows execute through the power pipeline (no double-fire).
			if (IsPowerEffect(e))
			{
				continue;
			}
			if (e?.Kind is CardExtraEffectKind.ConditionalAutoPlayFromPile or CardExtraEffectKind.ConditionalAutoDrawFromPile or CardExtraEffectKind.ConditionalAutoRunEffects)
			{
				effects.Add(e);
			}
		}

		foreach (CardExtraEffect effect in effects)
		{
			if (CardEditorAutoPlayLoopGuard.ShouldSuppressEffect(card, effect))
			{
				continue;
			}

			CardPile? currentPile = card.Pile;
			if (currentPile == null || currentPile.Type == PileType.Play)
			{
				continue;
			}

			if (effect.CardSelectionPile != CardExtraEffectCardPile.AllPiles)
			{
				PileType requiredType = ResolvePileType(effect.CardSelectionPile);
				if (currentPile.Type != requiredType)
				{
					continue;
				}
			}

			if (effect.Kind == CardExtraEffectKind.ConditionalAutoDrawFromPile && currentPile.Type == PileType.Hand)
			{
				continue;
			}

			int threshold = Math.Max(1, effect.Amount);
			int count = GetHistoryCountMultiplier(combatState, card.TryGetOwnerCreature(), null, effect, card);
			if (count < threshold)
			{
				continue;
			}

			CardEditorConditionalFromPileFiredTracker.MarkFired(combatState, card);

			// Same single consumption point semantics as TryRunSelfPileAutoEffect.
			if (!CardEditorAutoPlayLoopGuard.TryConsumeEffectUseLimit(combatState, card.Owner, card, effect))
			{
				continue;
			}

			if (effect.Kind == CardExtraEffectKind.ConditionalAutoPlayFromPile)
			{
				await AutoPlayCardFromEffect(combatState, choiceContext, card.Owner, card, effect, card);
			}
			else if (effect.Kind == CardExtraEffectKind.ConditionalAutoDrawFromPile)
			{
				if (!CardEditorAutoPlayLoopGuard.TryEnterAutoPlayEffect(combatState, card.Owner, card, effect, out IDisposable drawScope))
				{
					continue;
				}
				using (drawScope)
				{
					await DrawCardFromPileToHand(choiceContext, card);
				}
			}
			else
			{
				await RunSelectedAutoActionEffectRows(combatState, choiceContext, card, effect);
			}
			return;
		}
	}

	private static async Task RunForTrigger(CombatState combatState, PlayerChoiceContext choiceContext, CardModel card, CardExtraEffectTrigger trigger, Creature? eventTarget = null)
	{
		if (combatState == null || choiceContext == null || card == null)
		{
			return;
		}

		using IDisposable _ = CardEditorCardPlayContext.PushScoped(new CardPlay
		{
			Card = card,
			Player = card.Owner,
			Target = eventTarget,
			ResultPile = card.Pile?.Type ?? PileType.None,
			Resources = new ResourceInfo
			{
				EnergySpent = 0,
				EnergyValue = 0,
				StarsSpent = 0,
				StarValue = 0
			},
			IsAutoPlay = true,
			PlayIndex = 0,
			PlayCount = 1
		});
		using IDisposable __ = CardEditorEffectExecutionAmountContext.PushSessionScoped();

		try
		{
			List<CardExtraEffect> effects = GetRuntimeEffectsIncludingBorrowedSources(combatState, card).ToList();
			if (effects.Count == 0)
			{
				return;
			}
			HashSet<string> autoActionPayloadIds = BuildAutoActionPayloadIdSet(effects);

			CardPlay syntheticPlay = new CardPlay
			{
				Card = card,
				Player = card.Owner,
				Target = eventTarget,
				ResultPile = card.Pile?.Type ?? PileType.None,
				Resources = new ResourceInfo
				{
					EnergySpent = 0,
					EnergyValue = 0,
					StarsSpent = 0,
					StarValue = 0
				},
				IsAutoPlay = true,
				PlayIndex = 0,
				PlayCount = 1
			};

			foreach (CardExtraEffect effect in effects)
			{
				if (ShouldSkipDirectEffect(effect, autoActionPayloadIds)
					|| IsPowerEffect(effect)
					|| !IsValidEffectAmount(effect.Kind, effect.Amount)
					|| !DoesTriggerMatch(effect, trigger, card))
				{
					continue;
				}

				if (effect.Kind is (CardExtraEffectKind.CardCostsLess or CardExtraEffectKind.CardStarCostsLess) && !effect.GrantToCard)
				{
					if (IsTriggeredCardCostsLessDefinition(effect))
					{
						CardEditorMod.VerboseLog($"[CardEditor][CostLessTrigger] observed={trigger} card={card?.Id} pile={card?.Pile?.Type} amount={effect.Amount} amountIsX={effect.AmountIsX} duration={effect.CardCostsLessDuration} mode={effect.CardCostsLessMode} boundary={effect.TurnBoundary}/{effect.TurnBoundarySide}/{effect.TurnBoundaryCardLocation}");
						ApplyTriggeredCardCostsLess(combatState, card, effect, syntheticPlay);
					}
					continue;
				}

				if (effect.Timing == CardExtraEffectTiming.Immediate)
				{
					await ExecuteEffect(combatState, choiceContext, syntheticPlay, effect);
				}
				else
				{
					Creature? lockedTarget = null;
					Player? owner = card.Owner;
					if (effect.Target == CardExtraEffectTarget.Target && owner?.Creature != null)
					{
						lockedTarget = ResolveSingleTarget(combatState, owner.Creature, syntheticPlay);
					}
					CardEditorExtraEffectScheduler.Schedule(combatState, syntheticPlay, effect, lockedTarget);
				}
			}
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] Extra effects (trigger={trigger}) failed: {ex}");
		}
		finally
		{
			await EvaluateStatefulTransformConditionStops(combatState);
			await EvaluateDynamicTransforms(combatState, choiceContext, card.Owner);
		}
	}

	internal static bool DoesTriggerMatch(CardExtraEffect effect, CardExtraEffectTrigger observedTrigger, CardModel card)
	{
		if (effect == null)
		{
			return false;
		}
		if (IsMovedToPileTrigger(effect.Trigger) || IsMovedToPileTrigger(observedTrigger))
		{
			return DoesMovedPileTriggerMatch(effect, observedTrigger, card);
		}
		if (effect.Trigger == observedTrigger
			|| (observedTrigger == CardExtraEffectTrigger.EndOfTurnInHand && effect.Trigger == CardExtraEffectTrigger.EndOfTurn))
		{
			return true;
		}
		if (effect.Trigger != CardExtraEffectTrigger.TurnBoundary)
		{
			return false;
		}
		if (!TryMapObservedTurnBoundaryTrigger(observedTrigger, out CardExtraEffectTurnBoundary boundary, out CardExtraEffectTurnBoundarySide side))
		{
			return false;
		}
		if (effect.TurnBoundary != boundary)
		{
			return false;
		}
		if (effect.TurnBoundarySide != CardExtraEffectTurnBoundarySide.Both && effect.TurnBoundarySide != side)
		{
			return false;
		}
		if (effect.TurnBoundaryCardLocation != CardExtraEffectTurnBoundaryCardLocation.Any
			&& !IsCardInTurnBoundaryLocation(card, effect.TurnBoundaryCardLocation))
		{
			return false;
		}
		return true;
	}

	private static bool DoesMovedPileTriggerMatch(CardExtraEffect effect, CardExtraEffectTrigger observedTrigger, CardModel card)
	{
		if (effect == null || effect.Trigger != observedTrigger || !IsMovedToPileTrigger(effect.Trigger) || card?.Pile == null)
		{
			return false;
		}
		if (effect.CardSelectionPile != CardExtraEffectCardPile.AllPiles
			&& card.Pile.Type != ResolvePileType(effect.CardSelectionPile))
		{
			return false;
		}

		return effect.Trigger switch
		{
			CardExtraEffectTrigger.OnMovedToTopOfPile => IsCardAtTopOfPile(card),
			CardExtraEffectTrigger.OnMovedToBottomOfPile => IsCardAtBottomOfPile(card),
			_ => false
		};
	}

	internal static bool DoesTurnBoundaryMatch(CardExtraEffect effect, CardExtraEffectTurnBoundary boundary, CardExtraEffectTurnBoundarySide side, CardModel card)
	{
		if (effect == null || effect.Trigger != CardExtraEffectTrigger.TurnBoundary)
		{
			return false;
		}
		if (effect.TurnBoundary != boundary)
		{
			return false;
		}
		if (effect.TurnBoundarySide != CardExtraEffectTurnBoundarySide.Both && effect.TurnBoundarySide != side)
		{
			return false;
		}
		if (effect.TurnBoundaryCardLocation != CardExtraEffectTurnBoundaryCardLocation.Any
			&& !IsCardInTurnBoundaryLocation(card, effect.TurnBoundaryCardLocation))
		{
			return false;
		}
		return true;
	}

	private static bool TryMapObservedTurnBoundaryTrigger(CardExtraEffectTrigger observedTrigger, out CardExtraEffectTurnBoundary boundary, out CardExtraEffectTurnBoundarySide side)
	{
		switch (observedTrigger)
		{
			case CardExtraEffectTrigger.StartOfTurn:
				boundary = CardExtraEffectTurnBoundary.Start;
				side = CardExtraEffectTurnBoundarySide.YourTurn;
				return true;
			case CardExtraEffectTrigger.EndOfTurn:
			case CardExtraEffectTrigger.EndOfTurnInHand:
				boundary = CardExtraEffectTurnBoundary.End;
				side = CardExtraEffectTurnBoundarySide.YourTurn;
				return true;
			case CardExtraEffectTrigger.StartOfEnemyTurn:
				boundary = CardExtraEffectTurnBoundary.Start;
				side = CardExtraEffectTurnBoundarySide.EnemyTurn;
				return true;
			case CardExtraEffectTrigger.EndOfEnemyTurn:
				boundary = CardExtraEffectTurnBoundary.End;
				side = CardExtraEffectTurnBoundarySide.EnemyTurn;
				return true;
			default:
				boundary = default;
				side = default;
				return false;
		}
	}

	private static bool IsCardInTurnBoundaryLocation(CardModel card, CardExtraEffectTurnBoundaryCardLocation location)
	{
		if (card?.Pile == null)
		{
			return false;
		}
		return location switch
		{
			CardExtraEffectTurnBoundaryCardLocation.Hand => card.Pile.Type == PileType.Hand,
			CardExtraEffectTurnBoundaryCardLocation.DrawPile => card.Pile.Type == PileType.Draw,
			CardExtraEffectTurnBoundaryCardLocation.DiscardPile => card.Pile.Type == PileType.Discard,
			CardExtraEffectTurnBoundaryCardLocation.ExhaustPile => card.Pile.Type == PileType.Exhaust,
			_ => true
		};
	}

	private static void ApplyTriggeredCardCostsLess(CombatState combatState, CardModel card, CardExtraEffect effect, CardPlay? triggerPlay = null)
	{
		if (combatState == null || card == null || effect == null)
		{
			return;
		}
		if (!IsValidEffectAmount(effect.Kind, effect.Amount))
		{
			return;
		}

		CardPlay effectivePlay = triggerPlay ?? new CardPlay
		{
			Card = card,
			Player = card.Owner,
			Target = null,
			ResultPile = card.Pile?.Type ?? PileType.None,
			Resources = new ResourceInfo
			{
				EnergySpent = 0,
				EnergyValue = 0,
				StarsSpent = 0,
				StarValue = 0
			},
			IsAutoPlay = true,
			PlayIndex = 0,
			PlayCount = 1
		};
		Creature? ownerCreature = CardEditorPowerExecutionHostContext.Current ?? card.TryGetOwnerCreature();
		if (ownerCreature == null || !TryResolveSignedAmountForCostEffect(combatState, ownerCreature, effectivePlay, effect, out int signedAmount))
		{
			return;
		}

		CardExtraEffect active = CloneEffect(effect);
		active.Amount = signedAmount;
		active.AmountIsX = false;
		active.AmountXPlus = 0;
		active.Trigger = CardExtraEffectTrigger.OnPlay;
		active.Timing = CardExtraEffectTiming.Immediate;
		active.Turns = 1;
		active.GrantToCard = false;
		active.CardCostsLessMode = CardExtraEffectCardCostsLessMode.Passive;

		if (active.CardCostsLessDuration == CardExtraEffectCardCostsLessDuration.Permanent)
		{
			if (ApplyPersistentTriggeredCardCostsLessMutation(card, active))
			{
				CardEditorMod.VerboseLog($"[CardEditor][ApplyTriggeredCostLess] card={card.Id} pile={card.Pile?.Type} mutable={card.IsMutable} clone={card.IsClone} cloneOf={card.CloneOf?.Id} duration=Permanent amount={active.Amount} modifier={GetEffectiveCardCostsLessModifier(active)} persistent=True");
				return;
			}

			Log.Warn($"[CardEditor][ApplyTriggeredCostLess] Permanent trigger could not persist on {card?.Id}; falling back to combat-only grant.");
		}

		CardExtraEffectCardGrantDuration duration = effect.CardCostsLessDuration switch
		{
			CardExtraEffectCardCostsLessDuration.ThisTurn => CardExtraEffectCardGrantDuration.ThisTurn,
			CardExtraEffectCardCostsLessDuration.ThisCombat => CardExtraEffectCardGrantDuration.ThisCombat,
			CardExtraEffectCardCostsLessDuration.UntilPlayed => CardExtraEffectCardGrantDuration.UntilPlayed,
			CardExtraEffectCardCostsLessDuration.Turns => CardExtraEffectCardGrantDuration.Turns,
			_ => CardExtraEffectCardGrantDuration.ThisCombat
		};
		int turns = duration == CardExtraEffectCardGrantDuration.Turns
			? Math.Clamp(effect.CardCostsLessTurns, 1, 99)
			: 1;
		// Stack repeated triggers (e.g. "Costs 1 less each time it's played") by merging into an equivalent existing grant when possible.
		if (!CardEditorTemporaryExtraEffectController.TryStackTimedCardCostsLess(combatState, card, active, duration, turns))
		{
			CardEditorTemporaryExtraEffectController.Grant(combatState, card, active, duration, turns);
		}
		CardEditorMod.VerboseLog($"[CardEditor][ApplyTriggeredCostLess] card={card.Id} pile={card.Pile?.Type} mutable={card.IsMutable} clone={card.IsClone} cloneOf={card.CloneOf?.Id} duration={duration} turns={turns} amount={active.Amount} modifier={GetEffectiveCardCostsLessModifier(active)}");
		NotifyTriggeredPermanentCardCostsLessChanged(card, active.Kind);
	}

	private static string GetSelfScalingTargetLabel(CardModel card, CardExtraEffect effect, bool isUpgradePreview)
	{
		return effect.SelfScalingTargetType switch
		{
			CardExtraEffectSelfScalingTargetType.BaseDamage => CardEditorLoc.T("cardText.selfScaling.baseDamage", "this card's damage"),
			CardExtraEffectSelfScalingTargetType.BaseBlock => CardEditorLoc.T("cardText.selfScaling.baseBlock", "this card's block"),
			CardExtraEffectSelfScalingTargetType.DynamicVar => BuildSelfScalingDynamicVarLabel(effect),
			CardExtraEffectSelfScalingTargetType.EffectRowAmount => BuildSelfScalingEffectRowFieldLabel(card, effect, isUpgradePreview),
			CardExtraEffectSelfScalingTargetType.AllNumbers => CardEditorLoc.T("cardText.selfScaling.allNumbers", "all effect numbers on this card"),
			CardExtraEffectSelfScalingTargetType.AllNumbersIncludingRepeats => CardEditorLoc.T("cardText.selfScaling.allNumbersIncludingRepeats", "all effect numbers and repeat counts on this card"),
			CardExtraEffectSelfScalingTargetType.EnergyCost => CardEditorLoc.T("cardText.selfScaling.energyCost", "this card's energy cost"),
			CardExtraEffectSelfScalingTargetType.StarCost => CardEditorLoc.T("cardText.selfScaling.starCost", "this card's star cost"),
			CardExtraEffectSelfScalingTargetType.AllGameplayNumbers => CardEditorLoc.T("cardText.selfScaling.allGameplayNumbers", "all gameplay numbers on this card"),
			CardExtraEffectSelfScalingTargetType.AllGameplayNumbersIncludingRepeats => CardEditorLoc.T("cardText.selfScaling.allGameplayNumbersIncludingRepeats", "all gameplay numbers and repeat counts on this card"),
			CardExtraEffectSelfScalingTargetType.RepeatCounts => CardEditorLoc.T("cardText.selfScaling.repeatCounts", "this card's repeat counts"),
			_ => CardEditorLoc.T("cardText.selfScaling.baseDamage", "this card's damage")
		};
	}

	private static bool SelfScalingTargetSupportsNumberFilter(CardExtraEffectSelfScalingTargetType targetType)
	{
		return targetType is CardExtraEffectSelfScalingTargetType.AllNumbers
			or CardExtraEffectSelfScalingTargetType.AllNumbersIncludingRepeats
			or CardExtraEffectSelfScalingTargetType.AllGameplayNumbers
			or CardExtraEffectSelfScalingTargetType.AllGameplayNumbersIncludingRepeats
			or CardExtraEffectSelfScalingTargetType.RepeatCounts;
	}

	private static string GetSelfScalingNumberFilterSuffix(CardExtraEffect effect)
	{
		if (effect == null
			|| effect.SelfScalingNumberFilter == CardExtraEffectCountCardFilter.Any
			|| !SelfScalingTargetSupportsNumberFilter(effect.SelfScalingTargetType))
		{
			return string.Empty;
		}

		string filterLabel = CountCardFilterLabel(effect.SelfScalingNumberFilter);
		return CardEditorLoc.F(
			"cardText.selfScaling.numberFilterSuffix",
			$" matching {filterLabel}",
			("Filter", filterLabel));
	}

	private static string GetSelfScalingNumberSelectionPrefix(CardExtraEffect effect)
	{
		if (effect == null || !SelfScalingTargetSupportsNumberFilter(effect.SelfScalingTargetType))
		{
			return string.Empty;
		}

		return effect.SelfScalingNumberSelectionMode switch
		{
			CardExtraEffectSelfScalingNumberSelectionMode.First => CardEditorLoc.T("cardText.selfScaling.numberSelection.first", "the first "),
			CardExtraEffectSelfScalingNumberSelectionMode.Random => CardEditorLoc.T("cardText.selfScaling.numberSelection.random", "a random "),
			_ => string.Empty
		};
	}

	private static string GetSelfScalingTargetLabelWithNumberSelection(CardModel card, CardExtraEffect effect, bool isUpgradePreview)
	{
		if (effect == null || effect.SelfScalingNumberSelectionMode == CardExtraEffectSelfScalingNumberSelectionMode.All)
		{
			return GetSelfScalingTargetLabel(card, effect!, isUpgradePreview) + GetSelfScalingNumberFilterSuffix(effect!);
		}

		string noun = effect.SelfScalingTargetType switch
		{
			CardExtraEffectSelfScalingTargetType.RepeatCounts => CardEditorLoc.T("cardText.selfScaling.singleRepeatCount", "repeat count"),
			CardExtraEffectSelfScalingTargetType.AllGameplayNumbers or CardExtraEffectSelfScalingTargetType.AllGameplayNumbersIncludingRepeats => CardEditorLoc.T("cardText.selfScaling.singleGameplayNumber", "gameplay number"),
			_ => CardEditorLoc.T("cardText.selfScaling.singleEffectNumber", "effect number")
		};
		string filterSuffix = GetSelfScalingNumberFilterSuffix(effect);
		return effect.SelfScalingNumberSelectionMode == CardExtraEffectSelfScalingNumberSelectionMode.Random
			? CardEditorLoc.F(
				"cardText.selfScaling.randomNumber",
				$"one random {noun}{filterSuffix}",
				("Number", noun),
				("FilterSuffix", filterSuffix))
			: CardEditorLoc.F(
				"cardText.selfScaling.firstNumber",
				$"the first {noun}{filterSuffix}",
				("Number", noun),
				("FilterSuffix", filterSuffix));
	}

	private static string BuildSelfScalingDynamicVarLabel(CardExtraEffect effect)
	{
		string? key = effect?.SelfScalingDynamicVarKey?.Trim();
		if (string.IsNullOrWhiteSpace(key))
		{
			return CardEditorLoc.T("cardText.selfScaling.selectedNumber", "the selected number");
		}

		if (string.Equals(key, "Damage", StringComparison.OrdinalIgnoreCase))
		{
			return CardEditorLoc.T("cardText.selfScaling.baseDamage", "this card's damage");
		}

		if (string.Equals(key, "Block", StringComparison.OrdinalIgnoreCase))
		{
			return CardEditorLoc.T("cardText.selfScaling.baseBlock", "this card's block");
		}

		return CardEditorLoc.F(
			"cardText.selfScaling.dynamicVar",
			$"this card's {key}",
			("Var", key));
	}

	private static bool TryGetEffectRowForDescription(CardModel card, string? effectId, bool isUpgradePreview, out CardExtraEffect matched)
	{
		matched = null!;
		if (card == null || string.IsNullOrWhiteSpace(effectId))
		{
			return false;
		}

		string trimmedEffectId = effectId.Trim();
		foreach (CardExtraEffect candidate in GetEffectsForDescription(card, isUpgradePreview))
		{
			if (candidate == null
				|| string.IsNullOrWhiteSpace(candidate.EffectId)
				|| !string.Equals(candidate.EffectId, trimmedEffectId, StringComparison.Ordinal))
			{
				continue;
			}

			matched = candidate;
			return true;
		}

		return false;
	}

	private static string ResolveSelfScalingEffectRowLabel(CardModel card, CardExtraEffect effect, bool isUpgradePreview)
	{
		if (!TryGetEffectRowForDescription(card, effect.SelfScalingTargetEffectId, isUpgradePreview, out CardExtraEffect candidate))
		{
			return CardEditorLoc.T("cardText.selfScaling.effectRow", "this effect");
		}

		return candidate.Kind switch
		{
			CardExtraEffectKind.DealDamage => CardEditorLoc.T("cardText.selfScaling.damageEffect", "this card's damage effect"),
			CardExtraEffectKind.GainBlock => CardEditorLoc.T("cardText.selfScaling.blockEffect", "this card's block effect"),
			_ => CardEditorLoc.Enum(
				"effectKind",
				candidate.Kind,
				Definitions.FirstOrDefault(def => def.Kind == candidate.Kind)?.Label ?? candidate.Kind.ToString())
		};
	}

	private static string GetSelfScalingFieldLabel(CardExtraEffectSelfScalingField field)
	{
		return field switch
		{
			CardExtraEffectSelfScalingField.Repeat => CardEditorLoc.T("cardText.selfScaling.field.repeat", "repeat count"),
			CardExtraEffectSelfScalingField.SecondaryAmount => CardEditorLoc.T("cardText.selfScaling.field.secondaryAmount", "secondary amount"),
			CardExtraEffectSelfScalingField.Threshold => CardEditorLoc.T("cardText.selfScaling.field.threshold", "threshold"),
			CardExtraEffectSelfScalingField.Duration => CardEditorLoc.T("cardText.selfScaling.field.duration", "duration"),
			_ => CardEditorLoc.T("cardText.selfScaling.field.amount", "amount")
		};
	}

	private static string BuildSelfScalingEffectRowFieldLabel(CardModel card, CardExtraEffect effect, bool isUpgradePreview)
	{
		string rowLabel = ResolveSelfScalingEffectRowLabel(card, effect, isUpgradePreview);
		if (effect.SelfScalingField == CardExtraEffectSelfScalingField.Amount)
		{
			return rowLabel;
		}

		string fieldLabel = GetSelfScalingFieldLabel(effect.SelfScalingField);
		return CardEditorLoc.F(
			"cardText.selfScaling.effectRowField",
			$"{rowLabel}'s {fieldLabel}",
			("Row", rowLabel),
			("Field", fieldLabel));
	}

	private static string FormatSelfScalingDurationSuffix(CardExtraEffect effect)
	{
		CardExtraEffectCardCostsLessDuration duration = GetEffectiveSelfScalingDuration(effect);
		return duration switch
		{
			CardExtraEffectCardCostsLessDuration.Permanent => CardEditorLoc.T(
				"cardText.selfScaling.duration.permanent",
				" for the rest of the run"),
			CardExtraEffectCardCostsLessDuration.ThisTurn => CardEditorLoc.T(
				"cardText.selfScaling.duration.thisTurn",
				" this turn"),
			CardExtraEffectCardCostsLessDuration.UntilPlayed => CardEditorLoc.T(
				"cardText.selfScaling.duration.untilPlayed",
				" until played"),
			CardExtraEffectCardCostsLessDuration.Turns => CardEditorLoc.F(
				"cardText.selfScaling.duration.forTurns",
				$" for {Math.Max(1, effect.CardCostsLessTurns).ToString(CultureInfo.InvariantCulture)} turns",
				("Turns", Math.Max(1, effect.CardCostsLessTurns))),
			_ => CardEditorLoc.T(
				"cardText.selfScaling.duration.thisCombat",
				" for this combat")
		};
	}

	private static string FormatSelfScalingAmountText(CardModel card, CardExtraEffect effect, bool isUpgradePreview)
	{
		if (effect == null)
		{
			return "0";
		}

		if (UsesAppliedEffectRowAmountSource(effect))
		{
			return ApplyAmountSourceMultiplierToReference(effect, ResolveAppliedAmountReferenceText(card, effect, isUpgradePreview));
		}

		if (UsesValueSourceAmountSource(effect))
		{
			return ApplyAmountSourceMultiplierToReference(effect, ResolveValueSourceReferenceText(effect));
		}

		if (!effect.AmountIsX)
		{
			return effect.Amount.ToString(CultureInfo.InvariantCulture);
		}

		return effect.AmountXPlus == 0
			? "X"
			: $"X{(effect.AmountXPlus > 0 ? "+" : string.Empty)}{effect.AmountXPlus.ToString(CultureInfo.InvariantCulture)}";
	}

	internal static string FormatDisplayNumberLabel(CardExtraEffect? effect)
	{
		string? label = effect?.CustomPowerName?.Trim();
		return string.IsNullOrWhiteSpace(label)
			? CardEditorLoc.T("cardText.displayNumber.defaultLabel", "Display Number")
			: label;
	}

	internal static string FormatDisplayNumberAmountText(CardExtraEffect? effect, int upgradeHighlightComparison = 0)
	{
		if (effect == null)
		{
			return "0";
		}

		string amountText;
		if (effect.AmountIsX)
		{
			amountText = FormatXPlusText(effect.AmountXPlus);
		}
		else
		{
			int amount = effect.Amount;
			amountText = amount > 0
				? "+" + amount.ToString(CultureInfo.InvariantCulture)
				: amount.ToString(CultureInfo.InvariantCulture);
		}

		return upgradeHighlightComparison == 0
			? amountText
			: StsTextUtilities.HighlightChangeText(amountText, upgradeHighlightComparison);
	}

	internal static string FormatDisplayNumberLine(CardExtraEffect effect, int upgradeHighlightComparison = 0)
	{
		string label = FormatDisplayNumberLabel(effect);
		string amountText = FormatDisplayNumberAmountText(effect, upgradeHighlightComparison);
		return CardEditorLoc.F(
			"cardText.displayNumber",
			$"{label} {amountText}.",
			("Label", label),
			("Amount", amountText));
	}

	private static string FormatSelfScalingLine(CardModel card, CardExtraEffect effect, bool isUpgradePreview)
	{
		string verb = effect.SelfScalingOperation == CardExtraEffectSelfScalingOperation.Decrease ? "decrease" : "increase";
		string targetLabel = GetSelfScalingTargetLabelWithNumberSelection(card, effect, isUpgradePreview);
		string amountText = FormatSelfScalingAmountText(card, effect, isUpgradePreview);
		string durationSuffix = FormatSelfScalingDurationSuffix(effect);
		bool selectedByEffect = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect;
		string recipientSuffix = effect.SelfScalingRecipientMode switch
		{
			CardExtraEffectSelfScalingRecipientMode.SelectedCards => selectedByEffect
				? CardEditorLoc.T("cardText.selfScaling.recipient.selectedByEffect", " on those cards")
				: CardEditorLoc.T("cardText.selfScaling.recipient.selected", " on selected cards"),
			CardExtraEffectSelfScalingRecipientMode.MatchingCards => selectedByEffect
				? CardEditorLoc.T("cardText.selfScaling.recipient.selectedByEffect", " on those cards")
				: CardEditorLoc.T("cardText.selfScaling.recipient.matching", " on matching cards"),
			CardExtraEffectSelfScalingRecipientMode.ThisAndSelectedCards => selectedByEffect
				? CardEditorLoc.T("cardText.selfScaling.recipient.thisAndSelectedByEffect", " on this card and those cards")
				: CardEditorLoc.T("cardText.selfScaling.recipient.thisAndSelected", " on this card and selected cards"),
			CardExtraEffectSelfScalingRecipientMode.ThisAndMatchingCards => selectedByEffect
				? CardEditorLoc.T("cardText.selfScaling.recipient.thisAndSelectedByEffect", " on this card and those cards")
				: CardEditorLoc.T("cardText.selfScaling.recipient.thisAndMatching", " on this card and matching cards"),
			_ => string.Empty
		};
		string action = $"{verb} {targetLabel} by {amountText}{durationSuffix}{recipientSuffix}";
		if (effect.ScaleMode != CardExtraEffectScaleMode.None)
		{
			action = effect.ScaleMode == CardExtraEffectScaleMode.PerHistoryCount && SupportsHistoryScaling(effect.Kind)
				? TrimTrailingSentencePunctuation(ApplyHistoryScalingSuffix(card, action, effect))
				: TrimTrailingSentencePunctuation(ApplyHistoryConditionPrefix(card, action, effect));
		}

		string actionLine = $"{UppercaseFirst(action)}.";
		if (IsPowerEffect(effect))
		{
			return ApplyPowerTriggerPrefix(actionLine, effect, card);
		}
		if (effect.Trigger == CardExtraEffectTrigger.TurnBoundary)
		{
			return FormatTurnBoundaryTrigger(effect, LowercaseFirst(actionLine));
		}
		if (effect.Trigger != CardExtraEffectTrigger.OnPlay)
		{
			return ApplyTriggerPrefix(actionLine, effect, card);
		}

		return $"When played, {LowercaseFirst(action)}.";
	}

	private static string FormatLinkedCardActionLine(CardModel card, CardExtraEffect effect, bool isUpgradePreview)
	{
		string actionName = NormalizeCustomKeywordName(effect.CustomKeywordName)
			?? CardEditorLoc.T("cardText.linkedCardAction.defaultAction", "Link");
		string amountText = FormatSelfScalingAmountText(card, effect, isUpgradePreview);
		string cardName = BuildSpecificCardReferenceText(effect?.SpecificCardId, GetCardReferenceDisplayMode(effect));
		string destination = BuildGeneratedDestinationText(GetConfiguredCardCreationDestinations(effect, CardExtraEffectCardPile.Hand, CardExtraEffectCardPilePosition.Bottom));
		string verb = effect.SelfScalingOperation == CardExtraEffectSelfScalingOperation.Decrease
			? CardEditorLoc.T("cardText.selfScaling.decrease", "decrease")
			: CardEditorLoc.T("cardText.selfScaling.increase", "increase");
		string mutationTarget = GetLinkedCardActionMutationTargetLabel(card, effect, isUpgradePreview);

		string line = CardEditorLoc.F(
			"cardText.linkedCardAction",
			$"[gold]{actionName}[/gold] {amountText}: if no {cardName} exists in combat, add one into {destination}. Then {verb} {mutationTarget} on all matching combat copies by {amountText}.",
			("Action", actionName),
			("Amount", amountText),
			("Card", cardName),
			("Destination", destination),
			("Verb", verb),
			("Target", mutationTarget));
		return ApplyTriggerPrefix(line, effect, card);
	}

	private static string GetLinkedCardActionMutationTargetLabel(CardModel card, CardExtraEffect effect, bool isUpgradePreview)
	{
		string targetLabel = GetSelfScalingTargetLabelWithNumberSelection(card, effect, isUpgradePreview);
		targetLabel = targetLabel
			.Replace("this card's ", string.Empty, StringComparison.OrdinalIgnoreCase)
			.Replace("on this card", string.Empty, StringComparison.OrdinalIgnoreCase)
			.Trim();
		return string.IsNullOrWhiteSpace(targetLabel)
			? CardEditorLoc.T("cardText.linkedCardAction.mutationTarget", "the chosen number")
			: targetLabel;
	}

	private static string? FormatScalingStageLine(CardModel card, Creature? target, CardExtraEffect effect, bool isUpgradePreview)
	{
		if (card == null || effect == null)
		{
			return null;
		}

		string conditionText = BuildCountConditionClause(card, effect);
		if (string.IsNullOrWhiteSpace(conditionText))
		{
			return null;
		}

		string? payloadLine = BuildEffectSourceReferenceLine(card, target, isUpgradePreview, effect);
		if (string.IsNullOrWhiteSpace(payloadLine))
		{
			return null;
		}

		if (!payloadLine.Contains('\n'))
		{
			string inlinePayload = LowercaseFirst(TrimTrailingSentencePunctuation(payloadLine));
			return CardEditorLoc.F(
				"cardText.scalingStage.inline",
				$"If {conditionText}, {inlinePayload}.",
				("Condition", conditionText),
				("Effect", inlinePayload));
		}

			return CardEditorLoc.F(
				"cardText.scalingStage",
				$"If {conditionText},\n{payloadLine}",
				("Condition", conditionText),
				("Effect", payloadLine));
		}

	private static string GetAppliedAmountSourcePlaceholder(CardExtraEffectKind kind)
	{
		return kind is CardExtraEffectKind.Summon or CardExtraEffectKind.Forge or CardExtraEffectKind.CreateRandomPotion or CardExtraEffectKind.AddCardReward or CardExtraEffectKind.AddRelicReward
			? CardEditorLoc.T("cardText.amountSource.thatMany", "that many")
			: CardEditorLoc.T("cardText.amountSource.thatMuch", "that much");
	}

	private static string GetAmountSourceStatusName(CardExtraEffectEnemyStatus status)
	{
		return status switch
		{
			CardExtraEffectEnemyStatus.Weak => "Weak",
			CardExtraEffectEnemyStatus.Frail => "Frail",
			CardExtraEffectEnemyStatus.Vulnerable => "Vulnerable",
			CardExtraEffectEnemyStatus.Poison => "Poison",
			CardExtraEffectEnemyStatus.Doom => "Doom",
			CardExtraEffectEnemyStatus.Constrict => "Constrict",
			CardExtraEffectEnemyStatus.Artifact => "Artifact",
			CardExtraEffectEnemyStatus.Thorns => "Thorns",
			CardExtraEffectEnemyStatus.Regen => "Regen",
			CardExtraEffectEnemyStatus.Plating => "Plating",
			CardExtraEffectEnemyStatus.Intangible => "Intangible",
			CardExtraEffectEnemyStatus.Buffer => "Buffer",
			CardExtraEffectEnemyStatus.Vigor => "Vigor",
			CardExtraEffectEnemyStatus.Blur => "Blur",
			CardExtraEffectEnemyStatus.Ritual => "Ritual",
			CardExtraEffectEnemyStatus.Strength => "Strength",
			CardExtraEffectEnemyStatus.Dexterity => "Dexterity",
			CardExtraEffectEnemyStatus.Focus => "Focus",
			_ => "status"
		};
	}

	private static string ResolveAppliedAmountReferenceText(CardModel card, CardExtraEffect effect, bool isUpgradePreview)
	{
		if (effect.AmountSourceMode == CardExtraEffectAmountSourceMode.AppliedEffectRow
			&& TryDecodeVanillaDynamicAmountSource(effect.AmountSourceEffectId, out string dynamicKey))
		{
			return BuildSelfScalingDynamicVarLabel(new CardExtraEffect { SelfScalingDynamicVarKey = dynamicKey });
		}

		if (!TryGetEffectRowForDescription(card, effect.AmountSourceEffectId, isUpgradePreview, out CardExtraEffect candidate))
		{
			return effect.AmountSourceMode switch
			{
				CardExtraEffectAmountSourceMode.AppliedEffectHpDamage => CardEditorLoc.T("cardText.amountSource.selectedEffectHpDamage", "the HP damage from that effect"),
				CardExtraEffectAmountSourceMode.AppliedEffectBlockedDamage => CardEditorLoc.T("cardText.amountSource.selectedEffectBlockedDamage", "the blocked damage from that effect"),
				CardExtraEffectAmountSourceMode.AppliedEffectTotalDamage => CardEditorLoc.T("cardText.amountSource.selectedEffectTotalDamage", "the total damage from that effect"),
				CardExtraEffectAmountSourceMode.AppliedEffectOverkillDamage => CardEditorLoc.T("cardText.amountSource.selectedEffectOverkillDamage", "the overkill damage from that effect"),
				CardExtraEffectAmountSourceMode.AppliedEffectTotalAndOverkillDamage => CardEditorLoc.T("cardText.amountSource.selectedEffectTotalAndOverkillDamage", "the total plus overkill damage from that effect"),
				CardExtraEffectAmountSourceMode.AppliedEffectInstances => CardEditorLoc.T("cardText.amountSource.selectedEffectInstances", "the number of times that effect applies"),
				CardExtraEffectAmountSourceMode.AppliedEffectKills => CardEditorLoc.T("cardText.amountSource.selectedEffectKills", "the kills from that effect"),
				CardExtraEffectAmountSourceMode.ConfiguredEffectAmount => CardEditorLoc.T("cardText.amountSource.selectedEffectConfiguredAmount", "the configured amount from that effect"),
				CardExtraEffectAmountSourceMode.ConfiguredEffectInstances => CardEditorLoc.T("cardText.amountSource.selectedEffectConfiguredCount", "the configured count from that effect"),
				_ => CardEditorLoc.T("cardText.amountSource.selectedEffect", "the amount from that effect")
			};
		}

		if (effect.AmountSourceMode == CardExtraEffectAmountSourceMode.AppliedEffectHpDamage)
		{
			return candidate.Kind == CardExtraEffectKind.DealDamage
				? CardEditorLoc.T("cardText.amountSource.hpDamageDealt", "the HP damage dealt")
				: CardEditorLoc.T("cardText.amountSource.selectedEffectHpDamage", "the HP damage from that effect");
		}

		if (effect.AmountSourceMode == CardExtraEffectAmountSourceMode.AppliedEffectBlockedDamage)
		{
			return candidate.Kind == CardExtraEffectKind.DealDamage
				? CardEditorLoc.T("cardText.amountSource.blockedDamage", "the blocked damage")
				: CardEditorLoc.T("cardText.amountSource.selectedEffectBlockedDamage", "the blocked damage from that effect");
		}

		if (effect.AmountSourceMode == CardExtraEffectAmountSourceMode.AppliedEffectTotalDamage)
		{
			return candidate.Kind == CardExtraEffectKind.DealDamage
				? CardEditorLoc.T("cardText.amountSource.totalDamageDealt", "the total damage dealt")
				: CardEditorLoc.T("cardText.amountSource.selectedEffectTotalDamage", "the total damage from that effect");
		}

		if (effect.AmountSourceMode == CardExtraEffectAmountSourceMode.AppliedEffectOverkillDamage)
		{
			return candidate.Kind == CardExtraEffectKind.DealDamage
				? CardEditorLoc.T("cardText.amountSource.overkillDamage", "the overkill damage")
				: CardEditorLoc.T("cardText.amountSource.selectedEffectOverkillDamage", "the overkill damage from that effect");
		}

		if (effect.AmountSourceMode == CardExtraEffectAmountSourceMode.AppliedEffectTotalAndOverkillDamage)
		{
			return candidate.Kind == CardExtraEffectKind.DealDamage
				? CardEditorLoc.T("cardText.amountSource.totalAndOverkillDamage", "the total plus overkill damage")
				: CardEditorLoc.T("cardText.amountSource.selectedEffectTotalAndOverkillDamage", "the total plus overkill damage from that effect");
		}

		if (effect.AmountSourceMode == CardExtraEffectAmountSourceMode.AppliedEffectKills)
		{
			return candidate.Kind == CardExtraEffectKind.DealDamage
				? CardEditorLoc.T("cardText.amountSource.kills", "the kills")
				: CardEditorLoc.T("cardText.amountSource.selectedEffectKills", "the kills from that effect");
		}

		if (effect.AmountSourceMode == CardExtraEffectAmountSourceMode.AppliedEffectInstances)
		{
			return candidate.Kind == CardExtraEffectKind.DealDamage
				? CardEditorLoc.T("cardText.amountSource.damageHits", "the number of damage hits")
				: CardEditorLoc.T("cardText.amountSource.selectedEffectInstances", "the number of times that effect applies");
		}

		if (effect.AmountSourceMode == CardExtraEffectAmountSourceMode.ConfiguredEffectAmount)
		{
			return CardEditorLoc.T("cardText.amountSource.configuredAmount", "the configured amount");
		}

		if (effect.AmountSourceMode == CardExtraEffectAmountSourceMode.ConfiguredEffectInstances)
		{
			return CardEditorLoc.T("cardText.amountSource.configuredCount", "the configured count");
		}

		if (TryGetEffectPowerMatchStatus(candidate.Kind, out CardExtraEffectEnemyStatus status))
		{
			string statusName = GetAmountSourceStatusName(status);
			string verb = candidate.Kind switch
			{
				CardExtraEffectKind.RemoveWeak
					or CardExtraEffectKind.RemoveFrail
					or CardExtraEffectKind.RemoveVulnerable
					or CardExtraEffectKind.RemovePoison
					or CardExtraEffectKind.RemoveDoom
					or CardExtraEffectKind.RemoveConstrict
					or CardExtraEffectKind.RemoveArtifact
					or CardExtraEffectKind.RemoveThorns
					or CardExtraEffectKind.RemoveRegen
					or CardExtraEffectKind.RemovePlating
					or CardExtraEffectKind.RemoveIntangible
					or CardExtraEffectKind.RemoveBuffer
					or CardExtraEffectKind.RemoveVigor
					or CardExtraEffectKind.RemoveBlur
					or CardExtraEffectKind.RemoveRitual => "removed",
				CardExtraEffectKind.LoseStrength
					or CardExtraEffectKind.LoseDexterity
					or CardExtraEffectKind.LoseFocus => "lost",
				CardExtraEffectKind.GainStrength
					or CardExtraEffectKind.GainDexterity
					or CardExtraEffectKind.GainFocus
					or CardExtraEffectKind.GainArtifact
					or CardExtraEffectKind.GainThorns
					or CardExtraEffectKind.GainRegen
					or CardExtraEffectKind.GainPlating
					or CardExtraEffectKind.GainIntangible
					or CardExtraEffectKind.GainBuffer
					or CardExtraEffectKind.GainVigor
					or CardExtraEffectKind.GainBlur
					or CardExtraEffectKind.GainRitual => "gained",
				_ => "applied"
			};
			return $"the {statusName} {verb}";
		}

		string fallbackRowLabel = ResolveSelfScalingEffectRowLabel(card, new CardExtraEffect { SelfScalingTargetEffectId = candidate.EffectId }, isUpgradePreview);
		return candidate.Kind switch
		{
			CardExtraEffectKind.RunEffectSourceCard => CardEditorLoc.F(
				"cardText.amountSource.effectSourceApplied",
				$"the amount from {ResolveSpecificCardTitle(candidate.SpecificCardId) ?? candidate.SpecificCardId?.Trim() ?? CardEditorLoc.T("cardText.amountSource.selectedEffect", "the amount from that effect")}",
				("Card", ResolveSpecificCardTitle(candidate.SpecificCardId) ?? candidate.SpecificCardId?.Trim() ?? CardEditorLoc.T("cardText.amountSource.selectedEffect", "the amount from that effect"))),
				CardExtraEffectKind.DealDamage => CardEditorLoc.T("cardText.amountSource.hpDamageDealt", "the HP damage dealt"),
				CardExtraEffectKind.GainBlock => CardEditorLoc.T("cardText.amountSource.blockGained", "the Block gained"),
			CardExtraEffectKind.Heal => CardEditorLoc.T("cardText.amountSource.hpHealed", "the HP healed"),
			CardExtraEffectKind.LoseHp => CardEditorLoc.T("cardText.amountSource.hpLost", "the HP lost"),
			CardExtraEffectKind.GainMaxHp => CardEditorLoc.T("cardText.amountSource.maxHpGained", "the Max HP gained"),
			CardExtraEffectKind.LoseMaxHp => CardEditorLoc.T("cardText.amountSource.maxHpLost", "the Max HP lost"),
			CardExtraEffectKind.GainEnergy => CardEditorLoc.T("cardText.amountSource.energyGained", "the Energy gained"),
			CardExtraEffectKind.LoseEnergy => CardEditorLoc.T("cardText.amountSource.energyLost", "the Energy lost"),
			CardExtraEffectKind.GainStars => CardEditorLoc.T("cardText.amountSource.starsGained", "the Stars gained"),
			CardExtraEffectKind.LoseStars => CardEditorLoc.T("cardText.amountSource.starsLost", "the Stars lost"),
			CardExtraEffectKind.GainGold => CardEditorLoc.T("cardText.amountSource.goldGained", "the Gold gained"),
			CardExtraEffectKind.LoseGold => CardEditorLoc.T("cardText.amountSource.goldLost", "the Gold lost"),
			CardExtraEffectKind.Summon => CardEditorLoc.T("cardText.amountSource.amountSummoned", "the amount summoned"),
			CardExtraEffectKind.Forge => CardEditorLoc.T("cardText.amountSource.amountForged", "the amount forged"),
			CardExtraEffectKind.CreateRandomPotion => CardEditorLoc.T("cardText.amountSource.potionsObtained", "the Potions obtained"),
			CardExtraEffectKind.AddCardReward => CardEditorLoc.T("cardText.amountSource.cardRewardOptions", "the card reward options"),
			CardExtraEffectKind.AddRelicReward => CardEditorLoc.T("cardText.amountSource.relicRewards", "the relic rewards"),
			CardExtraEffectKind.RemoveBlock => CardEditorLoc.T("cardText.amountSource.blockRemoved", "the Block removed"),
			CardExtraEffectKind.ApplyPower => CardEditorLoc.T("cardText.amountSource.powerApplied", "the amount from that effect"),
			CardExtraEffectKind.RemovePower => CardEditorLoc.T("cardText.amountSource.powerRemoved", "the amount from that effect"),
			_ => CardEditorLoc.F(
				"cardText.amountSource.effectRowAmount",
				$"the amount from {fallbackRowLabel}",
				("Row", fallbackRowLabel))
		};
	}

	private static string BuildAppliedAmountSourceSuffix(CardModel card, CardExtraEffect effect, bool isUpgradePreview)
	{
		string referenceText = ApplyAmountSourceMultiplierToReference(effect, ResolveAppliedAmountReferenceText(card, effect, isUpgradePreview));
		return CardEditorLoc.F(
			"cardText.amountSource.suffix",
			$"Equal to {referenceText}.",
			("Amount", referenceText));
	}

	private static string ApplyAmountSourceMultiplierToReference(CardExtraEffect effect, string referenceText)
	{
		if (effect == null || string.IsNullOrWhiteSpace(referenceText))
		{
			return referenceText;
		}

		decimal multiplier = Math.Clamp(effect.AmountSourceMultiplier <= 0m ? 1m : effect.AmountSourceMultiplier, 0.01m, 999m);
		if (multiplier == 1m)
		{
			return referenceText;
		}
		string multiplierText = FormatAmountSourceMultiplier(multiplier);

		return CardEditorLoc.F(
			"cardText.amountSource.multiplied",
			$"{multiplierText} times {referenceText}",
			("Multiplier", multiplierText),
			("Source", referenceText));
	}

	private static string FormatAmountSourceMultiplier(decimal multiplier)
		=> multiplier.ToString("0.###", CultureInfo.InvariantCulture);

	private static string ResolveValueSourceReferenceText(CardExtraEffect effect)
	{
		string valueLabel = effect.ValueSourceMode == CardExtraEffectValueSourceMode.PowerStatus
			? (ResolvePowerTitle(effect.ValueSourcePowerId) ?? CardEditorLoc.T("cardText.power.unknown", "Unknown Power"))
			: ValueSourceKindLabel(effect.ValueSourceKind);
		return effect.ValueSourceActor switch
		{
			CardExtraEffectValueSourceActor.Self => CardEditorLoc.F(
				"cardText.valueSource.self",
				$"your {valueLabel}",
				("Value", valueLabel)),
			CardExtraEffectValueSourceActor.Target => CardEditorLoc.F(
				"cardText.valueSource.target",
				$"the target's {valueLabel}",
				("Value", valueLabel)),
			CardExtraEffectValueSourceActor.EventActor => CardEditorLoc.F(
				"cardText.valueSource.eventActor",
				$"the trigger creature's {valueLabel}",
				("Value", valueLabel)),
			CardExtraEffectValueSourceActor.AllEnemies => ResolveGroupedValueSourceReferenceText(effect.ValueSourceAggregation, valueLabel, CardEditorLoc.T("cardText.valueSource.allEnemies", "ALL enemies")),
			CardExtraEffectValueSourceActor.AllAllies => ResolveGroupedValueSourceReferenceText(effect.ValueSourceAggregation, valueLabel, CardEditorLoc.T("cardText.valueSource.allAllies", "ALL players")),
			_ => CardEditorLoc.F(
				"cardText.valueSource.self",
				$"your {valueLabel}",
				("Value", valueLabel))
		};
	}

	private static string ResolveGroupedValueSourceReferenceText(CardExtraEffectValueSourceAggregation aggregation, string valueLabel, string actorLabel)
	{
		CardExtraEffectValueSourceAggregation effectiveAggregation = aggregation == CardExtraEffectValueSourceAggregation.Value
			? CardExtraEffectValueSourceAggregation.Sum
			: aggregation;
		return effectiveAggregation switch
		{
			CardExtraEffectValueSourceAggregation.Highest => CardEditorLoc.F(
				"cardText.valueSource.group.highest",
				$"the highest {valueLabel} among {actorLabel}",
				("Value", valueLabel),
				("Actor", actorLabel)),
			CardExtraEffectValueSourceAggregation.Lowest => CardEditorLoc.F(
				"cardText.valueSource.group.lowest",
				$"the lowest {valueLabel} among {actorLabel}",
				("Value", valueLabel),
				("Actor", actorLabel)),
			CardExtraEffectValueSourceAggregation.Average => CardEditorLoc.F(
				"cardText.valueSource.group.average",
				$"the average {valueLabel} among {actorLabel}",
				("Value", valueLabel),
				("Actor", actorLabel)),
				_ => CardEditorLoc.F(
					"cardText.valueSource.group.sum",
					$"the total {valueLabel} on {actorLabel}",
					("Value", valueLabel),
					("Actor", actorLabel))
			};
		}

	private static string BuildValueSourceAmountSuffix(CardExtraEffect effect)
	{
		string referenceText = ApplyAmountSourceMultiplierToReference(effect, ResolveValueSourceReferenceText(effect));
		return CardEditorLoc.F(
			"cardText.valueSource.suffix",
			$"Equal to {referenceText}.",
			("Amount", referenceText));
	}

	private static string? TryFormatDirectDynamicAmountSourceLine(CardModel card, CardExtraEffect effect, string referenceText, string? powerDurationSuffix)
	{
		if (card == null || effect == null || string.IsNullOrWhiteSpace(referenceText))
		{
			return null;
		}

		string suffixPart = BuildSuffixPart(powerDurationSuffix);

		return effect.Kind switch
		{
			CardExtraEffectKind.DealDamage => effect.Target switch
			{
				CardExtraEffectTarget.AllEnemies => $"Deal damage equal to {referenceText} to ALL enemies.",
				CardExtraEffectTarget.OtherEnemies => $"Deal damage equal to {referenceText} to other enemies.",
				CardExtraEffectTarget.RandomEnemy => $"Deal damage equal to {referenceText} to a random enemy.",
				CardExtraEffectTarget.Self => $"Take damage equal to {referenceText}.",
				CardExtraEffectTarget.AllAllies => $"Deal damage equal to {referenceText} to ALL players.",
				CardExtraEffectTarget.AnyAlly => $"Deal damage equal to {referenceText} to another player.",
				CardExtraEffectTarget.AnyPlayer => $"Deal damage equal to {referenceText} to any player.",
				_ => $"Deal damage equal to {referenceText}."
			},
				CardExtraEffectKind.CardDealsExtraDamage => $"This card deals bonus damage equal to {referenceText}.",
			CardExtraEffectKind.GainBlock => effect.Target switch
			{
				CardExtraEffectTarget.AllEnemies => $"ALL enemies gain [gold]Block[/gold] equal to {referenceText}.",
				CardExtraEffectTarget.OtherEnemies => $"Other enemies gain [gold]Block[/gold] equal to {referenceText}.",
