	private static string FormatMoveCardsBetweenPiles(CardModel? card, CardExtraEffect effect, int amount, string amountText)
	{
		if (effect == null)
		{
			return string.Empty;
		}
		bool hasSelectionCriteria = HasCardSelectionCriteria(effect);

		if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.ThisCard)
		{
			string thisTo = GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition);
			string thisResult = UsesEventCardThisCardWording(effect)
				? CardEditorLoc.F("cardText.moveCards.eventCard", $"Move it to {thisTo}.", ("To", thisTo))
				: CardEditorLoc.F("cardText.moveCards.thisCard", $"Move this card to {thisTo}.", ("To", thisTo));
			return BuildCostFilteredText(card, AppendCardSelectionNote(thisResult, effect), effect);
		}
		if (effect.CardSelectionMode is CardExtraEffectCardSelectionMode.Top or CardExtraEffectCardSelectionMode.Bottom)
		{
			string position = GetPositionalSelectionLabel(effect.CardSelectionMode);
			string posFrom = effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles
				? CardEditorLoc.T("cardText.pile.anywhere", "anywhere")
				: GetCardPilePossessive(effect.CardSelectionPile);
			string posTo = GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition);
			string posResult = amount == 1
				? CardEditorLoc.F("cardText.moveCards.positional.one", $"Move the {position} card of {posFrom} to {posTo}.", ("Position", position), ("From", posFrom), ("To", posTo))
				: CardEditorLoc.F("cardText.moveCards.positional.many", $"Move the {position} {amountText} cards of {posFrom} to {posTo}.", ("Position", position), ("Amount", amountText), ("From", posFrom), ("To", posTo));
			return BuildCostFilteredText(card, AppendCardSelectionNote(posResult, effect), effect);
		}
		if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect)
		{
			// Linked rows act on the upstream step's published cards, so drop the "from {pile}"
			// clause but keep the vanilla verb shortcuts for the discard/exhaust destinations.
			string selectedResult;
			if (effect.CardSelectionPile == CardExtraEffectCardPile.Hand && effect.MoveToPile == CardExtraEffectCardPile.DiscardPile)
			{
				selectedResult = CardEditorLoc.T("cardText.discard.selected", "Discard those cards.");
			}
			else if (effect.MoveToPile == CardExtraEffectCardPile.ExhaustPile)
			{
				selectedResult = CardEditorLoc.T("cardText.exhaust.selected", "Exhaust those cards.");
			}
			else
			{
				string selectedTo = GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition);
				selectedResult = CardEditorLoc.F("cardText.moveCards.selected", $"Move those cards to {selectedTo}.", ("To", selectedTo));
			}
			selectedResult = AppendCardSelectionNote(selectedResult, effect);
			return BuildCostFilteredText(card, selectedResult, effect);
		}

		// Prefer vanilla wording for common movement patterns (discard/exhaust) so it reads naturally and matches synergies.
		if (!hasSelectionCriteria && effect.CardSelectionPile == CardExtraEffectCardPile.Hand && effect.MoveToPile == CardExtraEffectCardPile.DiscardPile)
		{
			bool random = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.Random;
			bool all = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All;
			bool upTo = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.UpTo;
			string discardResult;
			if (all)
			{
				discardResult = CardEditorLoc.T("cardText.discard.hand", "Discard your hand.");
			}
			else if (upTo)
			{
				discardResult = CardEditorLoc.F("cardText.discard.upTo", $"Discard up to {amountText} cards.", ("Amount", amountText));
			}
			else if (amount == 1)
			{
				discardResult = random
					? CardEditorLoc.T("cardText.discard.randomOne", "Discard a random card.")
					: CardEditorLoc.T("cardText.discard.one", "Discard a card.");
			}
			else
			{
				discardResult = random
					? CardEditorLoc.F("cardText.discard.randomMany", $"Discard {amountText} random cards.", ("Amount", amountText))
					: CardEditorLoc.F("cardText.discard.many", $"Discard {amountText} cards.", ("Amount", amountText));
			}

			discardResult = AppendCardSelectionNote(discardResult, effect);
			return BuildCostFilteredText(card, discardResult, effect);
		}
		if (!hasSelectionCriteria && effect.CardSelectionPile == CardExtraEffectCardPile.Hand && effect.MoveToPile == CardExtraEffectCardPile.ExhaustPile)
		{
			bool random = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.Random;
			bool all = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All;
			bool upTo = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.UpTo;
			string exhaustResult;
			if (all)
			{
				exhaustResult = CardEditorLoc.T("cardText.exhaust.hand", "Exhaust your hand.");
			}
			else if (upTo)
			{
				exhaustResult = CardEditorLoc.F("cardText.exhaust.upTo", $"Exhaust up to {amountText} cards.", ("Amount", amountText));
			}
			else if (amount == 1)
			{
				exhaustResult = random
					? CardEditorLoc.T("cardText.exhaust.randomOne", "Exhaust a random card.")
					: CardEditorLoc.T("cardText.exhaust.one", "Exhaust a card.");
			}
			else
			{
				exhaustResult = random
					? CardEditorLoc.F("cardText.exhaust.randomMany", $"Exhaust {amountText} random cards.", ("Amount", amountText))
					: CardEditorLoc.F("cardText.exhaust.many", $"Exhaust {amountText} cards.", ("Amount", amountText));
			}

			exhaustResult = AppendCardSelectionNote(exhaustResult, effect);
			return BuildCostFilteredText(card, exhaustResult, effect);
		}

		string from = effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles
			? CardEditorLoc.T("cardText.pile.anywhere", "anywhere")
			: GetCardPilePossessive(effect.CardSelectionPile);
		string to = GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition);

		string moveResult;
		if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All)
		{
			moveResult = CardEditorLoc.F("cardText.moveCards.all", $"Move all cards from {from} to {to}.", ("From", from), ("To", to));
		}
		else if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.UpTo)
		{
			moveResult = CardEditorLoc.F("cardText.moveCards.upTo", $"Move up to {amountText} cards from {from} to {to}.", ("Amount", amountText), ("From", from), ("To", to));
		}
		else if (effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles)
		{
			bool random = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.Random;
			if (random)
			{
				moveResult = amount == 1
					? CardEditorLoc.F("cardText.moveCards.anywhere.random.one", $"Move a random card from any pile to {to}.", ("To", to))
					: CardEditorLoc.F("cardText.moveCards.anywhere.random.many", $"Move {amountText} random cards from any pile to {to}.", ("Amount", amountText), ("To", to));
			}
			else
			{
				moveResult = amount == 1
					? CardEditorLoc.F("cardText.moveCards.anywhere.one", $"Choose a card from any pile and move it to {to}.", ("To", to))
					: CardEditorLoc.F("cardText.moveCards.anywhere.many", $"Choose {amountText} cards from any pile and move them to {to}.", ("Amount", amountText), ("To", to));
			}
		}
		else
		{
			bool random = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.Random;
			if (random)
			{
				moveResult = amount == 1
					? CardEditorLoc.F("cardText.moveCards.random.one", $"Move a random card from {from} to {to}.", ("From", from), ("To", to))
					: CardEditorLoc.F("cardText.moveCards.random.many", $"Move {amountText} random cards from {from} to {to}.", ("Amount", amountText), ("From", from), ("To", to));
			}
			else
			{
				moveResult = amount == 1
					? CardEditorLoc.F("cardText.moveCards.one", $"Move a card from {from} to {to}.", ("From", from), ("To", to))
					: CardEditorLoc.F("cardText.moveCards.many", $"Move {amountText} cards from {from} to {to}.", ("Amount", amountText), ("From", from), ("To", to));
			}
		}
		moveResult = AppendCardSelectionNote(moveResult, effect);
		return BuildCostFilteredText(card, moveResult, effect);
	}

	private static string FormatDelayedPileAction(CardModel? card, CardExtraEffect effect, int amount, string amountText)
	{
		if (effect == null)
		{
			return string.Empty;
		}

		string unit = GetDelayedPileCounterUnitText(effect.DelayedPileCounterUnit, amount);
		string delay = CardEditorLoc.F("cardText.delayedPileAction.delay", $"After {amountText} {unit}", ("Amount", amountText), ("Unit", unit));
		string from = effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles
			? CardEditorLoc.T("cardText.pile.anywhere", "anywhere")
			: GetCardPilePossessive(effect.CardSelectionPile);
		bool thisCard = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.ThisCard;
		bool selectedByEffect = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect;
		string selected = thisCard
			? CardEditorLoc.T("cardText.thisCard", "this card")
			: BuildDelayedPileSelectionText(effect);

		// Linked rows act on the upstream step's published cards, so drop the "from {pile}" clause.
		string action = effect.DelayedPileAction switch
		{
			CardExtraEffectDelayedPileAction.Discard => thisCard
				? CardEditorLoc.F("cardText.delayedPileAction.discard.self", $"discard {selected} from {from}", ("Card", selected), ("From", from))
				: selectedByEffect
					? CardEditorLoc.F("cardText.delayedPileAction.discard.selected", $"discard {selected}", ("Cards", selected))
					: CardEditorLoc.F("cardText.delayedPileAction.discard", $"discard {selected} from {from}", ("Cards", selected), ("From", from)),
			CardExtraEffectDelayedPileAction.Exhaust => thisCard
				? CardEditorLoc.F("cardText.delayedPileAction.exhaust.self", $"exhaust {selected} from {from}", ("Card", selected), ("From", from))
				: selectedByEffect
					? CardEditorLoc.F("cardText.delayedPileAction.exhaust.selected", $"exhaust {selected}", ("Cards", selected))
					: CardEditorLoc.F("cardText.delayedPileAction.exhaust", $"exhaust {selected} from {from}", ("Cards", selected), ("From", from)),
			CardExtraEffectDelayedPileAction.RemoveFromDeck => thisCard
				? CardEditorLoc.T("cardText.delayedPileAction.removeDeck.self", "remove this card from your deck")
				: selectedByEffect
					? CardEditorLoc.F("cardText.delayedPileAction.removeDeck.selected", $"remove the deck versions of {selected}", ("Cards", selected))
					: CardEditorLoc.F("cardText.delayedPileAction.removeDeck", $"remove the deck versions of {selected} from {from}", ("Cards", selected), ("From", from)),
			_ => thisCard
				? CardEditorLoc.F("cardText.delayedPileAction.move.self", $"move {selected} from {from} to {GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition)}", ("Card", selected), ("From", from), ("To", GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition)))
				: selectedByEffect
					? CardEditorLoc.F("cardText.delayedPileAction.move.selected", $"move {selected} to {GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition)}", ("Cards", selected), ("To", GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition)))
					: CardEditorLoc.F("cardText.delayedPileAction.move", $"move {selected} from {from} to {GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition)}", ("Cards", selected), ("From", from), ("To", GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition)))
		};

		string result = CardEditorLoc.F("cardText.delayedPileAction", $"{delay}, {action}.", ("Delay", delay), ("Action", action));
		if (effect.DelayedPileCounterScope == CardExtraEffectDelayedPileCounterScope.Run)
		{
			result = AppendSentenceNote(result, CardEditorLoc.T("cardText.delayedPileAction.persistentNote", "This counter persists across combats."));
		}

		result = AppendCardSelectionNote(result, effect);
		return BuildCostFilteredText(card, result, effect);
	}

	private static string BuildDelayedPileSelectionText(CardExtraEffect effect)
	{
		string descriptor = BuildCardSelectionDescriptor(effect, plural: true, preferAllCardsKeyword: true);
		return effect.CardSelectionMode switch
		{
			CardExtraEffectCardSelectionMode.All => CardEditorLoc.F("cardText.delayedPileAction.selection.all", $"all matching {descriptor}", ("Cards", descriptor)),
			CardExtraEffectCardSelectionMode.Random => CardEditorLoc.F("cardText.delayedPileAction.selection.random", $"a random matching {descriptor}", ("Cards", descriptor)),
			CardExtraEffectCardSelectionMode.Top => CardEditorLoc.F("cardText.delayedPileAction.selection.top", $"the top matching {descriptor}", ("Cards", descriptor)),
			CardExtraEffectCardSelectionMode.Bottom => CardEditorLoc.F("cardText.delayedPileAction.selection.bottom", $"the bottom matching {descriptor}", ("Cards", descriptor)),
			CardExtraEffectCardSelectionMode.UpTo => CardEditorLoc.F("cardText.delayedPileAction.selection.upTo", $"up to one matching {descriptor}", ("Cards", descriptor)),
			CardExtraEffectCardSelectionMode.SelectedByEffect => CardEditorLoc.T("cardText.delayedPileAction.selection.selected", "those cards"),
			_ => CardEditorLoc.F("cardText.delayedPileAction.selection.choose", $"a matching {descriptor}", ("Cards", descriptor))
		};
	}

	private static string GetDelayedPileCounterUnitText(CardExtraEffectDelayedPileCounterUnit unit, int amount)
	{
		return unit switch
		{
			CardExtraEffectDelayedPileCounterUnit.Turns => amount == 1
				? CardEditorLoc.T("cardText.delayedPileAction.unit.turn.one", "turn")
				: CardEditorLoc.T("cardText.delayedPileAction.unit.turn.many", "turns"),
			CardExtraEffectDelayedPileCounterUnit.Combats => amount == 1
				? CardEditorLoc.T("cardText.delayedPileAction.unit.combat.one", "combat")
				: CardEditorLoc.T("cardText.delayedPileAction.unit.combat.many", "combats"),
			_ => amount == 1
				? CardEditorLoc.T("cardText.delayedPileAction.unit.trigger.one", "trigger")
				: CardEditorLoc.T("cardText.delayedPileAction.unit.trigger.many", "triggers")
		};
	}

	private static string AppendSentenceNote(string text, string note)
	{
		if (string.IsNullOrWhiteSpace(note))
		{
			return text ?? string.Empty;
		}
		if (string.IsNullOrWhiteSpace(text))
		{
			return note;
		}
		return text.EndsWith(' ')
			? text + note
			: text + " " + note;
	}

	private static string FormatShuffleDrawPile()
	{
		return CardEditorLoc.T("cardText.shuffleDrawDiscard", "Shuffle your discard pile into your draw pile.");
	}

	private static string FormatResultPileOverride(CardExtraEffect effect)
	{
		string destination = GetCardPileDestination(effect?.MoveToPile ?? CardExtraEffectCardPile.DiscardPile, effect?.MoveToPosition ?? CardExtraEffectCardPilePosition.Bottom);
		return CardEditorLoc.F(
			"cardText.resultPileOverride",
			$"This card goes to {destination} after play.",
			("Destination", destination));
	}

	private static string FormatPlayPermission(CardModel? card, CardExtraEffect effect)
	{
		string condition = BuildBranchConditionText(card, effect);
		if (string.IsNullOrWhiteSpace(condition))
		{
			return CardEditorLoc.T("cardText.playPermission.always", "Can be played.");
		}

		return CardEditorLoc.F(
			"cardText.playPermission.condition",
			$"Can only be played if {condition}.",
			("Condition", condition));
	}

	private static string FormatPlayPrevention(CardModel? card, CardExtraEffect effect)
	{
		string descriptor = BuildAffectedCardDescriptor(effect, plural: true);
		string condition = BuildBranchConditionText(card, effect);
		string blockSuffix = effect.PlayPreventionBlockMode == CardExtraEffectPlayPreventionBlockMode.ManualOnly
			? CardEditorLoc.T("cardText.playPrevention.manualOnlySuffix", " Manual plays only.")
			: string.Empty;
		string exemptionSuffix = effect.PlayPreventionExemption switch
		{
			CardExtraEffectPlayPreventionExemption.ThisCard => CardEditorLoc.T("cardText.playPrevention.exceptThisSuffix", " Except this card."),
			CardExtraEffectPlayPreventionExemption.MatchingSourceCard => CardEditorLoc.T("cardText.playPrevention.exceptMatchingSuffix", " Except matching cards."),
			_ => string.Empty
		};
		if (string.IsNullOrWhiteSpace(condition))
		{
			return CardEditorLoc.F(
				"cardText.playPrevention.always",
				$"While this is in hand, {descriptor} cannot be played.{blockSuffix}{exemptionSuffix}",
				("Cards", descriptor),
				("BlockSuffix", blockSuffix),
				("ExemptionSuffix", exemptionSuffix));
		}

		return CardEditorLoc.F(
			"cardText.playPrevention.condition",
			$"While this is in hand, {descriptor} cannot be played if {condition}.{blockSuffix}{exemptionSuffix}",
			("Cards", descriptor),
			("Condition", condition),
			("BlockSuffix", blockSuffix),
			("ExemptionSuffix", exemptionSuffix));
	}

	private static string FormatConditionalGlow(CardModel? card, CardExtraEffect effect)
	{
		string color = GlowColorModeLabel(effect.GlowColorMode).ToLowerInvariant();
		if (effect.GlowColorMode == CardExtraEffectGlowColorMode.Custom
			&& !string.IsNullOrWhiteSpace(effect.GlowCustomColor))
		{
			color = effect.GlowCustomColor.Trim();
		}

		string condition = BuildBranchConditionText(card, effect);
		if (string.IsNullOrWhiteSpace(condition))
		{
			return CardEditorLoc.F(
				"cardText.conditionalGlow.always",
				$"Glows {color}.",
				("Color", color));
		}

		return CardEditorLoc.F(
			"cardText.conditionalGlow.condition",
			$"Glows {color} if {condition}.",
			("Color", color),
			("Condition", condition));
	}

	private static string BuildAffectedCardDescriptor(CardExtraEffect effect, bool plural)
	{
		CardExtraEffect descriptorEffect = CloneEffect(effect ?? new CardExtraEffect());
		descriptorEffect.CardSelectionPool = effect?.TriggerCardPool ?? CardGeneratedCardPool.All;
		descriptorEffect.CardSelectionType = effect?.TriggerCardType ?? CardGeneratedCardType.Any;
		descriptorEffect.CardSelectionRarity = effect?.TriggerCardRarity ?? CardExtraEffectCardRarityFilter.Any;
		descriptorEffect.CardSelectionFilter = effect?.TriggerCardFilter ?? CardExtraEffectCountCardFilter.Any;
		return BuildCardSelectionDescriptor(descriptorEffect, plural, preferAllCardsKeyword: true);
	}

	private static string FormatUpgradeCardsInPile(CardModel? card, CardExtraEffect effect, int amount, string amountText, string? durationSuffix = null)
	{
		string pile = GetCardPileLocation(effect.CardSelectionPile);
		bool random = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.Random;
		bool all = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All;
		bool upTo = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.UpTo;
		bool selectedByEffect = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect;

		string result;
		if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.ThisCard)
		{
			result = UsesEventCardThisCardWording(effect)
				? CardEditorLoc.T("cardText.upgradeFromPile.eventCard", "Upgrade it.")
				: CardEditorLoc.T("cardText.upgradeFromPile.thisCard", "Upgrade this card.");
		}
		else if (selectedByEffect)
		{
			// Linked rows upgrade the upstream step's published cards, so drop the " {pile}" clause.
			result = CardEditorLoc.T("cardText.upgradeFromPile.selected", "Upgrade those cards.");
		}
		else if (effect.CardSelectionMode is CardExtraEffectCardSelectionMode.Top or CardExtraEffectCardSelectionMode.Bottom)
		{
			string position = GetPositionalSelectionLabel(effect.CardSelectionMode);
			result = amount == 1
				? CardEditorLoc.F("cardText.upgradeFromPile.positional.one", $"Upgrade the {position} card {pile}.", ("Position", position), ("Pile", pile))
				: CardEditorLoc.F("cardText.upgradeFromPile.positional.many", $"Upgrade the {position} {amountText} cards {pile}.", ("Position", position), ("Amount", amountText), ("Pile", pile));
		}
		else if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.EachPile
			&& effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles)
		{
			result = amount == 1
				? CardEditorLoc.T("cardText.upgradeFromPile.eachPile.one", "Upgrade a card in each pile.")
				: CardEditorLoc.F("cardText.upgradeFromPile.eachPile.many", $"Upgrade up to {amountText} cards in each pile.", ("Amount", amountText));
		}
		else if (all)
		{
			result = CardEditorLoc.F("cardText.upgradeFromPile.all", $"Upgrade all upgradable cards {pile}.", ("Pile", pile));
		}
		else if (upTo)
		{
			result = CardEditorLoc.F("cardText.upgradeFromPile.upTo", $"Upgrade up to {amountText} cards {pile}.", ("Amount", amountText), ("Pile", pile));
		}
		else if (amount == 1)
		{
			result = random
				? CardEditorLoc.F("cardText.upgradeFromPile.random.one", $"Upgrade a random card {pile}.", ("Pile", pile))
				: CardEditorLoc.F("cardText.upgradeFromPile.choose.one", $"Upgrade a card {pile}.", ("Pile", pile));
		}
		else
		{
			result = random
				? CardEditorLoc.F("cardText.upgradeFromPile.random.many", $"Upgrade {amountText} random cards {pile}.", ("Amount", amountText), ("Pile", pile))
				: CardEditorLoc.F("cardText.upgradeFromPile.choose.many", $"Upgrade {amountText} cards {pile}.", ("Amount", amountText), ("Pile", pile));
		}

		result = AppendCardSelectionNote(result, effect);
		result = BuildCostFilteredText(card, result, effect);
		if (durationSuffix == null)
		{
			return result;
		}

		return CardEditorLoc.F(
			"cardText.upgradeFromPile.duration",
			$"{result} {durationSuffix}.",
			("Line", result),
			("Duration", durationSuffix));
	}

	// "It ..." wording is used by ThisCard text branches on power rows whose trigger delivers
	// the event card to this kind's execution (the power prefix supplies the "Whenever you
	// discard a card," clause); everywhere else ThisCard resolves to the HOST card and keeps
	// the "this card" wording.
	private static bool UsesEventCardThisCardWording(CardExtraEffect effect)
		=> effect != null
			&& IsPowerEffect(effect)
			&& PowerTriggerProvidesTriggeringCard(effect.Trigger, effect.PowerTriggerCountEvent)
			&& ThisCardSelectionUsesExecutionCard(effect.Kind);

	private static string GetPositionalSelectionLabel(CardExtraEffectCardSelectionMode mode)
		=> mode == CardExtraEffectCardSelectionMode.Top
			? CardEditorLoc.T("cardText.selection.position.top", "top")
			: CardEditorLoc.T("cardText.selection.position.bottom", "bottom");

	private static string FormatGrantKeywordToPile(CardExtraEffect effect, int amount, string amountText)
	{
		string keyword = GrantedKeywordLabel(effect.GrantedKeyword);
		string pile = GetCardPileLocationForTarget(effect.CardSelectionPile, effect.Target);
		string durationText = GetCardGrantDurationText(effect);
		string futureText = effect.FutureMatchingCards
			? CardEditorLoc.T("cardText.grant.futureMatching", ", including future matching cards")
			: string.Empty;
		bool all = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All;
		bool random = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.Random;
		bool upTo = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.UpTo;
		bool selectedByEffect = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect;

		if (effect.GrantedKeywordRemove)
		{
			string removeResult;
			if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.ThisCard)
			{
				removeResult = UsesEventCardThisCardWording(effect)
					? CardEditorLoc.F("cardText.removeKeyword.eventCard", $"It loses {keyword}.", ("Keyword", keyword))
					: CardEditorLoc.F("cardText.removeKeyword.thisCard", $"This card loses {keyword}.", ("Keyword", keyword));
			}
			else if (selectedByEffect)
			{
				removeResult = CardEditorLoc.F("cardText.removeKeyword.selected", $"Those cards lose {keyword}.", ("Keyword", keyword));
			}
			else if (effect.CardSelectionMode is CardExtraEffectCardSelectionMode.Top or CardExtraEffectCardSelectionMode.Bottom)
			{
				string position = GetPositionalSelectionLabel(effect.CardSelectionMode);
				removeResult = amount == 1
					? CardEditorLoc.F("cardText.removeKeyword.positional.one", $"The {position} card {pile} loses {keyword}.", ("Position", position), ("Pile", pile), ("Keyword", keyword))
					: CardEditorLoc.F("cardText.removeKeyword.positional.many", $"The {position} {amountText} cards {pile} lose {keyword}.", ("Position", position), ("Amount", amountText), ("Pile", pile), ("Keyword", keyword));
			}
			else if (all)
			{
				removeResult = CardEditorLoc.F("cardText.removeKeyword.all", $"All cards {pile} lose {keyword}.", ("Pile", pile), ("Keyword", keyword));
			}
			else if (upTo)
			{
				removeResult = CardEditorLoc.F("cardText.removeKeyword.upTo", $"Choose up to {amountText} cards {pile}. They lose {keyword}.", ("Amount", amountText), ("Pile", pile), ("Keyword", keyword));
			}
			else if (amount == 1)
			{
				removeResult = random
					? CardEditorLoc.F("cardText.removeKeyword.random.one", $"A random card {pile} loses {keyword}.", ("Pile", pile), ("Keyword", keyword))
					: CardEditorLoc.F("cardText.removeKeyword.one", $"Choose a card {pile}. It loses {keyword}.", ("Pile", pile), ("Keyword", keyword));
			}
			else
			{
				removeResult = random
					? CardEditorLoc.F("cardText.removeKeyword.random.many", $"{amountText} random cards {pile} lose {keyword}.", ("Amount", amountText), ("Pile", pile), ("Keyword", keyword))
					: CardEditorLoc.F("cardText.removeKeyword.many", $"Choose {amountText} cards {pile}. They lose {keyword}.", ("Amount", amountText), ("Pile", pile), ("Keyword", keyword));
			}

			return AppendCardSelectionNote(removeResult, effect);
		}

		string result;
		if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.ThisCard)
		{
			result = UsesEventCardThisCardWording(effect)
				? CardEditorLoc.F("cardText.grantKeyword.eventCard", $"It gains {keyword} {durationText}.", ("Keyword", keyword), ("Duration", durationText))
				: CardEditorLoc.F("cardText.grantKeyword.thisCard", $"This card gains {keyword} {durationText}.", ("Keyword", keyword), ("Duration", durationText));
		}
		else if (selectedByEffect)
		{
			result = CardEditorLoc.F("cardText.grantKeyword.selected", $"Those cards gain {keyword} {durationText}{futureText}.", ("Keyword", keyword), ("Duration", durationText), ("Future", futureText));
		}
		else if (effect.CardSelectionMode is CardExtraEffectCardSelectionMode.Top or CardExtraEffectCardSelectionMode.Bottom)
		{
			string position = GetPositionalSelectionLabel(effect.CardSelectionMode);
			result = amount == 1
				? CardEditorLoc.F("cardText.grantKeyword.positional.one", $"The {position} card {pile} gains {keyword} {durationText}{futureText}.", ("Position", position), ("Pile", pile), ("Keyword", keyword), ("Duration", durationText), ("Future", futureText))
				: CardEditorLoc.F("cardText.grantKeyword.positional.many", $"The {position} {amountText} cards {pile} gain {keyword} {durationText}{futureText}.", ("Position", position), ("Amount", amountText), ("Pile", pile), ("Keyword", keyword), ("Duration", durationText), ("Future", futureText));
		}
		else if (all)
		{
			result = CardEditorLoc.F("cardText.grantKeyword.all", $"All cards {pile} gain {keyword} {durationText}{futureText}.", ("Pile", pile), ("Keyword", keyword), ("Duration", durationText), ("Future", futureText));
		}
		else if (upTo)
		{
			result = CardEditorLoc.F("cardText.grantKeyword.upTo", $"Choose up to {amountText} cards {pile}. They gain {keyword} {durationText}{futureText}.", ("Amount", amountText), ("Pile", pile), ("Keyword", keyword), ("Duration", durationText), ("Future", futureText));
		}
		else if (amount == 1)
		{
			result = random
				? CardEditorLoc.F("cardText.grantKeyword.random.one", $"A random card {pile} gains {keyword} {durationText}{futureText}.", ("Pile", pile), ("Keyword", keyword), ("Duration", durationText), ("Future", futureText))
				: CardEditorLoc.F("cardText.grantKeyword.one", $"Choose a card {pile}. It gains {keyword} {durationText}{futureText}.", ("Pile", pile), ("Keyword", keyword), ("Duration", durationText), ("Future", futureText));
		}
		else
		{
			result = random
				? CardEditorLoc.F("cardText.grantKeyword.random.many", $"{amountText} random cards {pile} gain {keyword} {durationText}{futureText}.", ("Amount", amountText), ("Pile", pile), ("Keyword", keyword), ("Duration", durationText), ("Future", futureText))
				: CardEditorLoc.F("cardText.grantKeyword.many", $"Choose {amountText} cards {pile}. They gain {keyword} {durationText}{futureText}.", ("Amount", amountText), ("Pile", pile), ("Keyword", keyword), ("Duration", durationText), ("Future", futureText));
		}

		return AppendCardSelectionNote(result, effect);
	}

