	private static string FormatTransformCards(CardModel? card, CardExtraEffect effect, int amount, string amountText)
	{
		if (effect == null)
		{
			return string.Empty;
		}

		bool randomPick = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.Random;
		bool all = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All;
		bool upTo = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.UpTo;
		bool thisCard = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.ThisCard;
		bool selectedByEffect = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect;

		string pileSuffix = string.Empty;
		if (effect.CardSelectionPile != CardExtraEffectCardPile.Hand)
		{
			string pile = GetCardPilePossessive(effect.CardSelectionPile);
			pileSuffix = CardEditorLoc.F("cardText.transform.fromPile", $" from {pile}", ("Pile", pile));
		}

		string intoText;
		if (effect.TransformMode == CardExtraEffectTransformMode.SpecificCard)
		{
			string cardName = BuildSpecificTransformCardReferenceText(effect);
			intoText = CardEditorLoc.F("cardText.transform.intoSpecific", $" into {cardName}", ("Card", cardName));
		}
		else
		{
			intoText = CardEditorLoc.T("cardText.transform.intoRandom", " into random cards");
		}

		string result;
		if (thisCard)
		{
			// Transform resolves ThisCard via the effect-source context (host card on power
			// rows too), so the "this card" wording is always accurate here.
			result = CardEditorLoc.F("cardText.transform.thisCard", $"Transform this card{intoText}.", ("Into", intoText));
		}
		else if (selectedByEffect)
		{
			// Linked rows transform the upstream step's published cards, so drop the " from {pile}" clause.
			result = CardEditorLoc.F("cardText.transform.selected", $"Transform those cards{intoText}.", ("Into", intoText));
		}
		else if (effect.CardSelectionMode is CardExtraEffectCardSelectionMode.Top or CardExtraEffectCardSelectionMode.Bottom)
		{
			string position = GetPositionalSelectionLabel(effect.CardSelectionMode);
			result = amount == 1
				? CardEditorLoc.F("cardText.transform.positional.one", $"Transform the {position} card{pileSuffix}{intoText}.", ("Position", position), ("PileSuffix", pileSuffix), ("Into", intoText))
				: CardEditorLoc.F("cardText.transform.positional.many", $"Transform the {position} {amountText} cards{pileSuffix}{intoText}.", ("Position", position), ("Amount", amountText), ("PileSuffix", pileSuffix), ("Into", intoText));
		}
		else if (all)
		{
			result = CardEditorLoc.F("cardText.transform.all", $"Transform all cards{pileSuffix}{intoText}.", ("PileSuffix", pileSuffix), ("Into", intoText));
		}
		else if (upTo)
		{
			result = CardEditorLoc.F("cardText.transform.upTo", $"Transform up to {amountText} cards{pileSuffix}{intoText}.", ("Amount", amountText), ("PileSuffix", pileSuffix), ("Into", intoText));
		}
		else if (amount == 1)
		{
			result = randomPick
				? CardEditorLoc.F("cardText.transform.randomOne", $"Transform a random card{pileSuffix}{intoText}.", ("PileSuffix", pileSuffix), ("Into", intoText))
				: CardEditorLoc.F("cardText.transform.one", $"Transform a card{pileSuffix}{intoText}.", ("PileSuffix", pileSuffix), ("Into", intoText));
		}
		else
		{
			result = randomPick
				? CardEditorLoc.F("cardText.transform.randomMany", $"Transform {amountText} random cards{pileSuffix}{intoText}.", ("Amount", amountText), ("PileSuffix", pileSuffix), ("Into", intoText))
				: CardEditorLoc.F("cardText.transform.many", $"Transform {amountText} cards{pileSuffix}{intoText}.", ("Amount", amountText), ("PileSuffix", pileSuffix), ("Into", intoText));
		}

		result = AppendCardSelectionNote(result, effect);
		return BuildCostFilteredText(card, result, effect);
	}

	private static string? FormatDynamicTransform(CardModel? card, CardExtraEffect effect)
	{
		if (effect == null || string.IsNullOrWhiteSpace(effect.SpecificCardId))
		{
			return null;
		}

		string cardName = BuildSpecificTransformCardReferenceText(effect);
		if (HasUsableBranchCondition(effect))
		{
			string condition = BuildBranchConditionText(card, effect);
			if (!string.IsNullOrWhiteSpace(condition))
			{
				return CardEditorLoc.F(
					"cardText.dynamicTransform.condition",
					$"While {condition}, transform this card into {cardName}. Transform it back when that stops being true.",
					("Condition", condition),
					("Card", cardName));
			}
		}

		return CardEditorLoc.F(
			"cardText.dynamicTransform.always",
			$"Transform this card into {cardName}.",
			("Card", cardName));
	}

	private static string? FormatStatefulTransform(CardModel? card, CardExtraEffect effect)
	{
		if (effect == null || string.IsNullOrWhiteSpace(effect.SpecificCardId))
		{
			return null;
		}

		string cardName = BuildSpecificTransformCardReferenceText(effect);
		string durationText = FormatStatefulTransformDuration(effect);
		string action = effect.StatefulTransformMode == CardExtraEffectStatefulTransformMode.Toggle
			? CardEditorLoc.F(
				"cardText.statefulTransform.toggle",
				$"Transform this card into {cardName}{durationText}, then transform it back when this effect toggles again.",
				("Card", cardName),
				("Duration", durationText))
			: CardEditorLoc.F(
				"cardText.statefulTransform.transform",
				$"Transform this card into {cardName}{durationText}.",
				("Card", cardName),
				("Duration", durationText));

		List<string> conditions = new List<string>();
		if (effect.ScaleMode != CardExtraEffectScaleMode.None)
		{
			string countCondition = BuildCountConditionClause(card, effect);
			if (!string.IsNullOrWhiteSpace(countCondition))
			{
				conditions.Add(countCondition);
			}
		}
		string result;
		if (conditions.Count == 0)
		{
			result = action;
		}
		else
		{
			string conditionText = string.Join(CardEditorLoc.T("cardText.condition.join.and", " and "), conditions);
			result = CardEditorLoc.F(
				"cardText.statefulTransform.condition",
				$"If {conditionText}, {LowercaseFirst(action)}",
				("Condition", conditionText),
				("Action", LowercaseFirst(action)));
		}

		if (HasUsableBranchCondition(effect))
		{
			string revertCondition = BuildBranchConditionText(card, effect);
			if (!string.IsNullOrWhiteSpace(revertCondition))
			{
				result += " " + CardEditorLoc.F(
					"cardText.statefulTransform.returnCondition",
					$"Transform it back when {revertCondition}.",
					("Condition", revertCondition));
			}
		}

		return result;
	}

	private static string FormatStatefulTransformDuration(CardExtraEffect effect)
	{
		int amount = Math.Clamp(effect?.StatefulTransformDurationAmount ?? 1, 1, 99);
		return effect?.StatefulTransformDuration switch
		{
			CardExtraEffectStatefulTransformDuration.ThisTurn => CardEditorLoc.T("cardText.statefulTransform.duration.thisTurn", " until end of turn"),
			CardExtraEffectStatefulTransformDuration.Turns => CardEditorLoc.F("cardText.statefulTransform.duration.turns", $" for {amount} turn{(amount == 1 ? string.Empty : "s")}", ("Amount", amount.ToString(CultureInfo.InvariantCulture)), ("Plural", amount == 1 ? string.Empty : "s")),
			CardExtraEffectStatefulTransformDuration.Combats => CardEditorLoc.F("cardText.statefulTransform.duration.combats", $" for {amount} combat{(amount == 1 ? string.Empty : "s")}", ("Amount", amount.ToString(CultureInfo.InvariantCulture)), ("Plural", amount == 1 ? string.Empty : "s")),
			CardExtraEffectStatefulTransformDuration.Run => CardEditorLoc.T("cardText.statefulTransform.duration.run", " for the run"),
			CardExtraEffectStatefulTransformDuration.UntilPlayed => CardEditorLoc.T("cardText.statefulTransform.duration.untilPlayed", " until it is played"),
			CardExtraEffectStatefulTransformDuration.UntilConditionStops => CardEditorLoc.T("cardText.statefulTransform.duration.untilConditionStops", " until the condition stops being true"),
			_ => CardEditorLoc.T("cardText.statefulTransform.duration.thisCombat", " this combat")
		};
	}

	private static string FormatEvokeOrbs(int amount, string amountText, bool linkedAmount = false)
	{
		// Vanilla STS2 wording (Dualcast/Multi-Cast): "Evoke your rightmost Orb [N times]".
		if (linkedAmount)
		{
			// Linked/value-sourced amounts force grammarAmount to 2; the "twice" shortcut would
			// assert a literal count, so render the reference wording instead. The shared
			// "Equal to ..." suffix is appended by the dispatch afterwards.
			return CardEditorLoc.T("cardText.evoke.thatMany", "[gold]Evoke[/gold] your rightmost Orb that many times.");
		}

		if (amount == 1)
		{
			return CardEditorLoc.T("cardText.evoke.one", "[gold]Evoke[/gold] your rightmost Orb.");
		}

		if (amount == 2)
		{
			return CardEditorLoc.T("cardText.evoke.twice", "[gold]Evoke[/gold] your rightmost Orb twice.");
		}

		return CardEditorLoc.F("cardText.evoke.many", $"[gold]Evoke[/gold] your rightmost Orb {amountText} times.", ("Amount", amountText));
	}

	private static string FormatOrbAction(CardExtraEffect effect, int amount, string amountText)
	{
		if (effect == null)
		{
			return string.Empty;
		}

		if (effect.OrbAction == CardExtraEffectOrbAction.AddSlots)
		{
			return amount == 1 ? "Gain 1 Orb Slot." : $"Gain {amountText} Orb Slots.";
		}

		if (effect.OrbAction == CardExtraEffectOrbAction.RemoveSlots)
		{
			if (effect.OrbScope == CardExtraEffectOrbScope.All)
				return "Lose all Orb Slots.";
			return amount == 1 ? "Lose 1 Orb Slot." : $"Lose {amountText} Orb Slots.";
		}

		if (effect.OrbAction == CardExtraEffectOrbAction.Channel)
		{
			return effect.OrbType == CardExtraEffectOrbType.Any
				? FormatChannelRandomOrb(amountText, amount)
				: FormatChannelOrb(amountText, amount, effect.OrbType.ToString());
		}

		if (effect.OrbAction == CardExtraEffectOrbAction.TriggerPassive)
		{
			string orbTypeTitle = GetOrbTypeTitle(effect.OrbType);
			string orbTypePrefix = string.IsNullOrWhiteSpace(orbTypeTitle) ? string.Empty : orbTypeTitle + " ";

			// Vanilla wording (Darkness): "Trigger the passive ability of all [gold]Dark[/gold] Orbs."
			if (effect.OrbScope == CardExtraEffectOrbScope.All)
			{
				return $"Trigger the passive ability of all {orbTypePrefix}Orbs.";
			}

			string selectionWord = effect.OrbSelection switch
			{
				CardExtraEffectOrbSelection.Rightmost => "rightmost",
				CardExtraEffectOrbSelection.Middle => "middle",
				_ => "leftmost"
			};

			return amount == 1
				? $"Trigger the passive ability of your {selectionWord} {orbTypePrefix}Orb."
				: $"Trigger the passive ability of your {selectionWord} {orbTypePrefix}Orb {amountText} times.";
		}

		string actionText = effect.OrbAction == CardExtraEffectOrbAction.Remove ? "Lose" : "Evoke";
		string orbTypeText = GetOrbTypeTitle(effect.OrbType);
		string orbPrefix = string.IsNullOrWhiteSpace(orbTypeText) ? string.Empty : orbTypeText + " ";

		if (effect.OrbScope == CardExtraEffectOrbScope.All)
		{
			string allLine = $"{actionText} all {orbPrefix}Orbs.";
			if (effect.OrbAction == CardExtraEffectOrbAction.Evoke && effect.OrbFollowUp == CardExtraEffectOrbFollowUp.ChannelSameType)
			{
				allLine = allLine.TrimEnd('.') + ", then [gold]Channel[/gold] the same Orb type.";
			}
			return allLine;
		}

		string selectionText = effect.OrbSelection switch
		{
			CardExtraEffectOrbSelection.Rightmost => "rightmost",
			CardExtraEffectOrbSelection.Middle => "middle",
			_ => "leftmost"
		};
		string orbWord = amount == 1 ? "Orb" : "Orbs";

		string line = amount == 1
			? $"{actionText} your {selectionText} {orbPrefix}{orbWord}."
			: $"{actionText} {amountText} {selectionText} {orbPrefix}{orbWord}.";

		if (effect.OrbAction == CardExtraEffectOrbAction.Evoke && effect.OrbFollowUp == CardExtraEffectOrbFollowUp.ChannelSameType)
		{
			line = line.TrimEnd('.') + ", then [gold]Channel[/gold] the same Orb type.";
		}

		return line;
	}

	private static string FormatOstyAction(CardExtraEffect effect, int amount, string amountText)
	{
		if (effect == null)
		{
			return string.Empty;
		}
		return effect.OstyAction switch
		{
			// Vanilla wording: "[gold]Osty[/gold] deals X damage." / "heals X HP." / "dies."
			CardExtraEffectOstyAction.Attack => $"[gold]Osty[/gold] deals {amountText} damage.",
			CardExtraEffectOstyAction.AttackAll => $"[gold]Osty[/gold] deals {amountText} damage to ALL enemies.",
			CardExtraEffectOstyAction.Heal => $"[gold]Osty[/gold] heals {amountText} HP.",
			CardExtraEffectOstyAction.Kill => "[gold]Osty[/gold] dies.",
			_ => string.Empty
		};
	}

	private static string FormatCreatureCommand(CardExtraEffect effect, string amountText)
	{
		if (effect == null)
		{
			return string.Empty;
		}

		string commandId = GetEffectiveCreatureCommandId(effect);
		CreatureCommandRuntimeSpec? spec = FindCreatureCommandRuntimeSpec(commandId);
		string label = spec?.Label ?? FormatCreatureCommandMethodLabel(commandId);
		// Target/Self keep the historical imperative lines; every other target gets an explicit
		// vanilla-verbiage subject so the text always says who the command hits.
		string ObjectLine(string verb) => effect.Target switch
		{
			CardExtraEffectTarget.AllEnemies => $"{verb} ALL enemies.",
			CardExtraEffectTarget.OtherEnemies => $"{verb} other enemies.",
			CardExtraEffectTarget.RandomEnemy => $"{verb} a random enemy.",
			CardExtraEffectTarget.AllAllies => $"{verb} ALL players.",
			CardExtraEffectTarget.AnyAlly => $"{verb} another player.",
			CardExtraEffectTarget.AnyPlayer => $"{verb} any player.",
			CardExtraEffectTarget.Self => $"{verb} yourself.",
			_ => $"{verb}."
		};
		string SubjectLine(string selfImperative, string thirdSingular, string thirdPlural) => effect.Target switch
		{
			CardExtraEffectTarget.AllEnemies => $"ALL enemies {thirdPlural}.",
			CardExtraEffectTarget.OtherEnemies => $"Other enemies {thirdPlural}.",
			CardExtraEffectTarget.RandomEnemy => $"A random enemy {thirdSingular}.",
			CardExtraEffectTarget.AllAllies => $"ALL players {thirdPlural}.",
			CardExtraEffectTarget.AnyAlly => $"Another player {thirdSingular}.",
			CardExtraEffectTarget.AnyPlayer => $"Any player {thirdSingular}.",
			_ => $"{selfImperative}."
		};
		string SetLine(string what) => effect.Target switch
		{
			CardExtraEffectTarget.AllEnemies => $"Set ALL enemies' {what} to {amountText}.",
			CardExtraEffectTarget.OtherEnemies => $"Set other enemies' {what} to {amountText}.",
			CardExtraEffectTarget.RandomEnemy => $"Set a random enemy's {what} to {amountText}.",
			CardExtraEffectTarget.AllAllies => $"Set ALL players' {what} to {amountText}.",
			CardExtraEffectTarget.AnyAlly => $"Set another player's {what} to {amountText}.",
			CardExtraEffectTarget.AnyPlayer => $"Set any player's {what} to {amountText}.",
			_ => $"Set {what} to {amountText}."
		};

		return commandId switch
		{
			nameof(CreatureCmd.Stun) => effect.Target is CardExtraEffectTarget.Target or CardExtraEffectTarget.EventTarget ? "Stun." : ObjectLine("[gold]Stun[/gold]"),
			nameof(CreatureCmd.Kill) => effect.Target is CardExtraEffectTarget.Target or CardExtraEffectTarget.EventTarget ? "Kill." : ObjectLine("Kill"),
			nameof(CreatureCmd.Escape) => effect.Target switch
			{
				CardExtraEffectTarget.AllEnemies => "ALL enemies escape.",
				CardExtraEffectTarget.OtherEnemies => "Other enemies escape.",
				CardExtraEffectTarget.RandomEnemy => "A random enemy escapes.",
				CardExtraEffectTarget.AllAllies => "ALL players escape.",
				CardExtraEffectTarget.AnyAlly => "Another player escapes.",
				CardExtraEffectTarget.AnyPlayer => "Any player escapes.",
				CardExtraEffectTarget.Self => "You escape.",
				_ => "Target escapes."
			},
			nameof(CreatureCmd.GainBlock) => FormatGainBlock(effect.Target, amountText),
			nameof(CreatureCmd.LoseBlock) => SubjectLine($"Remove {amountText} [gold]Block[/gold]", $"loses {amountText} [gold]Block[/gold]", $"lose {amountText} [gold]Block[/gold]"),
			nameof(CreatureCmd.Heal) => SubjectLine($"Heal {amountText} HP", $"heals {amountText} HP", $"heal {amountText} HP"),
			nameof(CreatureCmd.GainMaxHp) => SubjectLine($"Gain {amountText} Max HP", $"gains {amountText} Max HP", $"gain {amountText} Max HP"),
			nameof(CreatureCmd.LoseMaxHp) => SubjectLine($"Lose {amountText} Max HP", $"loses {amountText} Max HP", $"lose {amountText} Max HP"),
			nameof(CreatureCmd.SetCurrentHp) => SetLine("current HP"),
			nameof(CreatureCmd.SetMaxHp) => SetLine("Max HP"),
			nameof(CreatureCmd.SetMaxAndCurrentHp) => SetLine("Max and current HP"),
			_ => spec?.UsesAmount == true ? $"{label} {amountText}." : $"{label}."
		};
	}

	private static string FormatAddCopyOfThisCard(CardExtraEffect effect, int amount, string amountText)
	{
		if (effect == null)
		{
			return string.Empty;
		}

		string to = BuildGeneratedDestinationText(GetConfiguredCardCreationDestinations(effect, CardExtraEffectCardPile.DrawPile, CardExtraEffectCardPilePosition.Top));

		return amount == 1
			? CardEditorLoc.F("cardText.copyThisCard.one", $"Add a copy of this card into {to}.", ("To", to))
			: CardEditorLoc.F("cardText.copyThisCard.many", $"Add {amountText} copies of this card into {to}.", ("Amount", amountText), ("To", to));
	}

