	private static string FormatCopyCardsFromPileToDeck(CardModel? card, CardExtraEffect effect, int amount, string amountText, bool exact = false)
	{
		if (effect == null)
		{
			return string.Empty;
		}

		string from = effect.CardSelectionPile == CardExtraEffectCardPile.Deck
			? CardEditorLoc.T("cardText.deck", "your deck")
			: GetCardPilePossessive(effect.CardSelectionPile);
		string to = BuildGeneratedDestinationText(GetCopyCardDestinations(effect));
		bool all = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All;
		bool upTo = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.UpTo;
		bool random = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.Random;
		bool selectedByEffect = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect;
		bool copiesPerSelectedCard = effect.CopyMode == CardExtraEffectCopyMode.AmountCopiesPerSelectedCard;

		string result;
		if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.ThisCard)
		{
			string subject = UsesEventCardThisCardWording(effect)
				? CardEditorLoc.T("cardText.selection.itSubject", "it")
				: CardEditorLoc.T("cardText.selection.thisCardSubject", "this card");
			result = amount == 1
				? (exact
					? CardEditorLoc.F("cardText.copyPileToDeck.exact.thisCard.one", $"Add an exact copy of {subject} to {to}.", ("Subject", subject), ("To", to))
					: CardEditorLoc.F("cardText.copyPileToDeck.thisCard.one", $"Add a copy of {subject} to {to}.", ("Subject", subject), ("To", to)))
				: (exact
					? CardEditorLoc.F("cardText.copyPileToDeck.exact.thisCard.many", $"Add {amountText} exact copies of {subject} to {to}.", ("Amount", amountText), ("Subject", subject), ("To", to))
					: CardEditorLoc.F("cardText.copyPileToDeck.thisCard.many", $"Add {amountText} copies of {subject} to {to}.", ("Amount", amountText), ("Subject", subject), ("To", to)));
		}
		else if (copiesPerSelectedCard)
		{
			if (all)
			{
				result = amount == 1
					? (exact
						? CardEditorLoc.F("cardText.copyPileToDeck.exact.amountEach.all.one", $"Add an exact copy of each card from {from} to {to}.", ("From", from), ("To", to))
						: CardEditorLoc.F("cardText.copyPileToDeck.amountEach.all.one", $"Add a copy of each card from {from} to {to}.", ("From", from), ("To", to)))
					: (exact
						? CardEditorLoc.F("cardText.copyPileToDeck.exact.amountEach.all.many", $"Add {amountText} exact copies of each card from {from} to {to}.", ("Amount", amountText), ("From", from), ("To", to))
						: CardEditorLoc.F("cardText.copyPileToDeck.amountEach.all.many", $"Add {amountText} copies of each card from {from} to {to}.", ("Amount", amountText), ("From", from), ("To", to)));
			}
			else if (selectedByEffect)
			{
				result = amount == 1
					? (exact
						? CardEditorLoc.F("cardText.copyPileToDeck.exact.amountEach.selected.one", $"Add an exact copy of each selected card to {to}.", ("To", to))
						: CardEditorLoc.F("cardText.copyPileToDeck.amountEach.selected.one", $"Add a copy of each selected card to {to}.", ("To", to)))
					: (exact
						? CardEditorLoc.F("cardText.copyPileToDeck.exact.amountEach.selected.many", $"Add {amountText} exact copies of each selected card to {to}.", ("Amount", amountText), ("To", to))
						: CardEditorLoc.F("cardText.copyPileToDeck.amountEach.selected.many", $"Add {amountText} copies of each selected card to {to}.", ("Amount", amountText), ("To", to)));
			}
			else
			{
				string selectionText = upTo
					? CardEditorLoc.T("cardText.selection.upToMatching", "up to the selected number of matching cards")
					: random
						? CardEditorLoc.T("cardText.selection.randomMatching", "the selected number of random matching cards")
						: CardEditorLoc.T("cardText.selection.chosenMatching", "the selected matching cards");
				result = amount == 1
					? (exact
						? CardEditorLoc.F("cardText.copyPileToDeck.exact.amountEach.choose.one", $"Choose from {from}. Add an exact copy of each selected card to {to}.", ("From", from), ("To", to))
						: CardEditorLoc.F("cardText.copyPileToDeck.amountEach.choose.one", $"Choose from {from}. Add a copy of each selected card to {to}.", ("From", from), ("To", to)))
					: (exact
						? CardEditorLoc.F("cardText.copyPileToDeck.exact.amountEach.choose.many", $"Choose {selectionText} from {from}. Add {amountText} exact copies of each selected card to {to}.", ("Selection", selectionText), ("Amount", amountText), ("From", from), ("To", to))
						: CardEditorLoc.F("cardText.copyPileToDeck.amountEach.choose.many", $"Choose {selectionText} from {from}. Add {amountText} copies of each selected card to {to}.", ("Selection", selectionText), ("Amount", amountText), ("From", from), ("To", to)));
			}
		}
		else if (selectedByEffect)
		{
			result = exact
				? CardEditorLoc.F("cardText.copyPileToDeck.exact.selected", $"Add exact copies of the selected cards to {to}.", ("To", to))
				: CardEditorLoc.F("cardText.copyPileToDeck.selected", $"Add copies of the selected cards to {to}.", ("To", to));
		}
		else if (all)
		{
			result = exact
				? CardEditorLoc.F("cardText.copyPileToDeck.exact.all", $"Add exact copies of all cards from {from} to {to}.", ("From", from), ("To", to))
				: CardEditorLoc.F("cardText.copyPileToDeck.all", $"Add copies of all cards from {from} to {to}.", ("From", from), ("To", to));
		}
		else if (upTo)
		{
			result = exact
				? CardEditorLoc.F("cardText.copyPileToDeck.exact.upTo", $"Add exact copies of up to {amountText} cards from {from} to {to}.", ("Amount", amountText), ("From", from), ("To", to))
				: CardEditorLoc.F("cardText.copyPileToDeck.upTo", $"Add copies of up to {amountText} cards from {from} to {to}.", ("Amount", amountText), ("From", from), ("To", to));
		}
		else if (amount == 1)
		{
			result = exact
				? (random
					? CardEditorLoc.F("cardText.copyPileToDeck.exact.random.one", $"Add an exact copy of a random card from {from} to {to}.", ("From", from), ("To", to))
					: CardEditorLoc.F("cardText.copyPileToDeck.exact.choose.one", $"Choose a card from {from}. Add an exact copy to {to}.", ("From", from), ("To", to)))
				: (random
					? CardEditorLoc.F("cardText.copyPileToDeck.random.one", $"Add a copy of a random card from {from} to {to}.", ("From", from), ("To", to))
					: CardEditorLoc.F("cardText.copyPileToDeck.choose.one", $"Choose a card from {from}. Add a copy to {to}.", ("From", from), ("To", to)));
		}
		else
		{
			result = exact
				? (random
					? CardEditorLoc.F("cardText.copyPileToDeck.exact.random.many", $"Add exact copies of {amountText} random cards from {from} to {to}.", ("Amount", amountText), ("From", from), ("To", to))
					: CardEditorLoc.F("cardText.copyPileToDeck.exact.choose.many", $"Choose {amountText} cards from {from}. Add exact copies to {to}.", ("Amount", amountText), ("From", from), ("To", to)))
				: (random
					? CardEditorLoc.F("cardText.copyPileToDeck.random.many", $"Add copies of {amountText} random cards from {from} to {to}.", ("Amount", amountText), ("From", from), ("To", to))
					: CardEditorLoc.F("cardText.copyPileToDeck.choose.many", $"Choose {amountText} cards from {from}. Add copies to {to}.", ("Amount", amountText), ("From", from), ("To", to)));
		}

		result = AppendCardSelectionNote(result, effect);
		return BuildCostFilteredText(card, result, effect);
	}

	private static string FormatSelectCardsFromPile(CardModel? card, CardExtraEffect effect, int amount, string amountText)
	{
		if (effect == null)
		{
			return string.Empty;
		}

		string from = effect.CardSelectionPile == CardExtraEffectCardPile.Deck
			? CardEditorLoc.T("cardText.deck", "your deck")
			: GetCardPilePossessive(effect.CardSelectionPile);
		bool all = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All;
		bool upTo = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.UpTo;
		bool random = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.Random;

		string result;
		if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.ThisCard)
		{
			result = UsesEventCardThisCardWording(effect)
				? CardEditorLoc.T("cardText.selectPile.eventCard", "Select it.")
				: CardEditorLoc.T("cardText.selectPile.thisCard", "Select this card.");
		}
		else if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect)
		{
			// Linked rows re-publish the upstream step's cards (optionally re-filtered by the
			// notes appended below), so reference the link instead of a fresh pile pick.
			result = CardEditorLoc.T("cardText.selectPile.selected", "Select those cards.");
		}
		else if (effect.CardSelectionMode is CardExtraEffectCardSelectionMode.Top or CardExtraEffectCardSelectionMode.Bottom)
		{
			string position = GetPositionalSelectionLabel(effect.CardSelectionMode);
			result = amount == 1
				? CardEditorLoc.F("cardText.selectPile.positional.one", $"Select the {position} card of {from}.", ("Position", position), ("From", from))
				: CardEditorLoc.F("cardText.selectPile.positional.many", $"Select the {position} {amountText} cards of {from}.", ("Position", position), ("Amount", amountText), ("From", from));
		}
		else if (all)
		{
			result = CardEditorLoc.F("cardText.selectPile.all", $"Select all matching cards from {from}.", ("From", from));
		}
		else if (upTo)
		{
			result = CardEditorLoc.F("cardText.selectPile.upTo", $"Select up to {amountText} cards from {from}.", ("Amount", amountText), ("From", from));
		}
		else if (amount == 1)
		{
			result = random
				? CardEditorLoc.F("cardText.selectPile.random.one", $"Select a random card from {from}.", ("From", from))
				: CardEditorLoc.F("cardText.selectPile.choose.one", $"Choose a card from {from}.", ("From", from));
		}
		else
		{
			result = random
				? CardEditorLoc.F("cardText.selectPile.random.many", $"Select {amountText} random cards from {from}.", ("Amount", amountText), ("From", from))
				: CardEditorLoc.F("cardText.selectPile.choose.many", $"Choose {amountText} cards from {from}.", ("Amount", amountText), ("From", from));
		}

		result = AppendCardSelectionNote(result, effect);
		return BuildCostFilteredText(card, result, effect);
	}

	private static string FormatRemoveCardsFromDeck(CardModel? card, CardExtraEffect effect, int amount, string amountText)
	{
		if (effect == null)
		{
			return string.Empty;
		}

		bool fromDeck = effect.CardSelectionPile == CardExtraEffectCardPile.Deck;
		string source = fromDeck ? CardEditorLoc.T("cardText.deck", "your deck") : GetCardPilePossessive(effect.CardSelectionPile);
		bool all = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All;
		bool upTo = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.UpTo;
		bool random = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.Random;

		string result;
		if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.ThisCard)
		{
			result = UsesEventCardThisCardWording(effect)
				? CardEditorLoc.T("cardText.removeDeck.eventCard", "Remove it from your deck.")
				: CardEditorLoc.T("cardText.removeDeck.thisCard", "Remove this card from your deck.");
		}
		else if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect)
		{
			// Linked rows remove the upstream step's published cards, not a fresh pile choice.
			result = fromDeck
				? CardEditorLoc.T("cardText.removeDeck.selected", "Remove those cards from your deck.")
				: CardEditorLoc.T("cardText.removeDeckFromPile.selected", "Remove the deck versions of those cards.");
		}
		else if (fromDeck)
		{
			if (all)
			{
				result = CardEditorLoc.T("cardText.removeDeck.all", "Remove all matching cards from your deck.");
			}
			else if (upTo)
			{
				result = CardEditorLoc.F("cardText.removeDeck.upTo", $"Remove up to {amountText} cards from your deck.", ("Amount", amountText));
			}
			else if (amount == 1)
			{
				result = random
					? CardEditorLoc.T("cardText.removeDeck.random.one", "Remove a random card from your deck.")
					: CardEditorLoc.T("cardText.removeDeck.choose.one", "Choose a card to remove from your deck.");
			}
			else
			{
				result = random
					? CardEditorLoc.F("cardText.removeDeck.random.many", $"Remove {amountText} random cards from your deck.", ("Amount", amountText))
					: CardEditorLoc.F("cardText.removeDeck.choose.many", $"Choose {amountText} cards to remove from your deck.", ("Amount", amountText));
			}
		}
		else if (all)
		{
			result = CardEditorLoc.F("cardText.removeDeckFromPile.all", $"Remove the deck versions of all cards from {source}.", ("Source", source));
		}
		else if (upTo)
		{
			result = CardEditorLoc.F("cardText.removeDeckFromPile.upTo", $"Remove the deck versions of up to {amountText} cards from {source}.", ("Amount", amountText), ("Source", source));
		}
		else if (amount == 1)
		{
			result = random
				? CardEditorLoc.F("cardText.removeDeckFromPile.random.one", $"Remove the deck version of a random card from {source}.", ("Source", source))
				: CardEditorLoc.F("cardText.removeDeckFromPile.choose.one", $"Choose a card from {source}. Remove its deck version.", ("Source", source));
		}
		else
		{
			result = random
				? CardEditorLoc.F("cardText.removeDeckFromPile.random.many", $"Remove the deck versions of {amountText} random cards from {source}.", ("Amount", amountText), ("Source", source))
				: CardEditorLoc.F("cardText.removeDeckFromPile.choose.many", $"Choose {amountText} cards from {source}. Remove their deck versions.", ("Amount", amountText), ("Source", source));
		}

		result = AppendCardSelectionNote(result, effect);
		return BuildCostFilteredText(card, result, effect);
	}

	private static bool GeneratedCardsGoToHand(CardExtraEffect? effect)
	{
		List<(CardExtraEffectCardPile Pile, CardExtraEffectCardPilePosition Position)> destinations = GetGeneratedCardDestinations(effect, CardExtraEffectCardPile.Hand, CardExtraEffectCardPilePosition.Bottom);
		return destinations.Count == 1 && destinations[0].Pile == CardExtraEffectCardPile.Hand;
	}

	private static string GetGeneratedCardDestination(CardExtraEffect? effect)
	{
		return BuildGeneratedDestinationText(GetGeneratedCardDestinations(effect, CardExtraEffectCardPile.Hand, CardExtraEffectCardPilePosition.Bottom));
	}

	private static List<(CardExtraEffectCardPile Pile, CardExtraEffectCardPilePosition Position)> GetConfiguredCardCreationDestinations(CardExtraEffect? effect, CardExtraEffectCardPile defaultPile, CardExtraEffectCardPilePosition defaultPosition)
	{
		CardExtraEffectCardPile primaryPile = effect?.MoveToPile ?? defaultPile;
		CardExtraEffectCardPilePosition primaryPosition = effect?.MoveToPosition ?? defaultPosition;

		List<(CardExtraEffectCardPile Pile, CardExtraEffectCardPilePosition Position)> destinations = new()
		{
			(primaryPile, primaryPosition)
		};

		CardExtraEffectAdditionalMoveToPiles extras = effect?.AdditionalMoveToPiles ?? CardExtraEffectAdditionalMoveToPiles.None;
		foreach (CardExtraEffectCardPile pile in new[] { CardExtraEffectCardPile.Hand, CardExtraEffectCardPile.DrawPile, CardExtraEffectCardPile.DiscardPile, CardExtraEffectCardPile.ExhaustPile })
		{
			CardExtraEffectAdditionalMoveToPiles flag = AdditionalMoveToPileFlag(pile);
			if (flag == CardExtraEffectAdditionalMoveToPiles.None || !extras.HasFlag(flag) || pile == primaryPile)
			{
				continue;
			}

			CardExtraEffectCardPilePosition position = pile == CardExtraEffectCardPile.DrawPile
				? primaryPosition
				: CardExtraEffectCardPilePosition.Bottom;
			destinations.Add((pile, position));
		}

		return destinations;
	}

	private static List<(CardExtraEffectCardPile Pile, CardExtraEffectCardPilePosition Position)> GetCopyCardDestinations(CardExtraEffect? effect)
	{
		// Legacy copy-from-pile effects were always deck-bound and never saved an explicit destination.
		// Keep that behavior until the effect is re-saved with an opted-in configured destination.
		return effect != null && effect.UseMoveDestinationForGeneratedCards
			? GetConfiguredCardCreationDestinations(effect, CardExtraEffectCardPile.Deck, CardExtraEffectCardPilePosition.Top)
			: new List<(CardExtraEffectCardPile Pile, CardExtraEffectCardPilePosition Position)>
			{
				(CardExtraEffectCardPile.Deck, CardExtraEffectCardPilePosition.Top)
			};
	}

	private static CardExtraEffectAdditionalMoveToPiles AdditionalMoveToPileFlag(CardExtraEffectCardPile pile)
	{
		return pile switch
		{
			CardExtraEffectCardPile.Hand => CardExtraEffectAdditionalMoveToPiles.Hand,
			CardExtraEffectCardPile.DrawPile => CardExtraEffectAdditionalMoveToPiles.DrawPile,
			CardExtraEffectCardPile.DiscardPile => CardExtraEffectAdditionalMoveToPiles.DiscardPile,
			CardExtraEffectCardPile.ExhaustPile => CardExtraEffectAdditionalMoveToPiles.ExhaustPile,
			_ => CardExtraEffectAdditionalMoveToPiles.None
		};
	}

	private static List<(CardExtraEffectCardPile Pile, CardExtraEffectCardPilePosition Position)> GetGeneratedCardDestinations(CardExtraEffect? effect, CardExtraEffectCardPile defaultPile, CardExtraEffectCardPilePosition defaultPosition)
	{
		CardExtraEffectCardPile primaryPile = effect == null || !effect.UseMoveDestinationForGeneratedCards
			? defaultPile
			: effect.MoveToPile;
		CardExtraEffectCardPilePosition primaryPosition = effect == null || !effect.UseMoveDestinationForGeneratedCards
			? defaultPosition
			: effect.MoveToPosition;

		List<(CardExtraEffectCardPile Pile, CardExtraEffectCardPilePosition Position)> destinations = new()
		{
			(primaryPile, primaryPosition)
		};

		CardExtraEffectAdditionalMoveToPiles extras = effect?.AdditionalMoveToPiles ?? CardExtraEffectAdditionalMoveToPiles.None;
		foreach (CardExtraEffectCardPile pile in new[] { CardExtraEffectCardPile.Hand, CardExtraEffectCardPile.DrawPile, CardExtraEffectCardPile.DiscardPile, CardExtraEffectCardPile.ExhaustPile })
		{
			CardExtraEffectAdditionalMoveToPiles flag = AdditionalMoveToPileFlag(pile);
			if (flag == CardExtraEffectAdditionalMoveToPiles.None || !extras.HasFlag(flag) || pile == primaryPile)
			{
				continue;
			}

			CardExtraEffectCardPilePosition position = pile == CardExtraEffectCardPile.DrawPile
				? primaryPosition
				: CardExtraEffectCardPilePosition.Bottom;
			destinations.Add((pile, position));
		}

		return destinations;
	}

	private static string BuildGeneratedDestinationText(IReadOnlyList<(CardExtraEffectCardPile Pile, CardExtraEffectCardPilePosition Position)> destinations)
	{
		if (destinations == null || destinations.Count == 0)
		{
			return GetCardPileDestination(CardExtraEffectCardPile.Hand, CardExtraEffectCardPilePosition.Bottom);
		}

		List<string> labels = destinations
			.Select(dest => GetCardPileDestination(dest.Pile, dest.Position))
			.Distinct(StringComparer.Ordinal)
			.ToList();
		if (labels.Count == 1)
		{
			return labels[0];
		}
		if (labels.Count == 2)
		{
			return labels[0] + " and " + labels[1];
		}

		return string.Join(", ", labels.Take(labels.Count - 1)) + ", and " + labels[^1];
	}

	private static string FormatCardStarCostDelta(int signedAmount, string? durationSuffix, int upgradeHighlightComparison)
	{
		int magnitude = Math.Abs(signedAmount);
		string amountText = BuildStarIcons(magnitude);
		if (upgradeHighlightComparison != 0)
		{
			amountText = StsTextUtilities.HighlightChangeText(amountText, upgradeHighlightComparison);
		}

		bool isLess = signedAmount > 0;
		string lessOrMore = isLess
			? CardEditorLoc.T("cardText.costDelta.less", "less")
			: CardEditorLoc.T("cardText.costDelta.more", "more");

		if (durationSuffix != null)
		{
			return CardEditorLoc.F(
				"cardText.cardStarCostDelta.duration",
				$"This card costs {amountText} {lessOrMore} {durationSuffix}.",
				("Amount", amountText),
				("LessOrMore", lessOrMore),
				("Stars", string.Empty),
				("Duration", durationSuffix));
		}

		return CardEditorLoc.F(
			"cardText.cardStarCostDelta",
			$"This card costs {amountText} {lessOrMore}.",
			("Amount", amountText),
			("LessOrMore", lessOrMore),
			("Stars", string.Empty));
	}

	private static string FormatCardStarCostDeltaText(string amountText, bool isLess, string? durationSuffix, int upgradeHighlightComparison)
	{
		if (upgradeHighlightComparison != 0)
		{
			amountText = StsTextUtilities.HighlightChangeText(amountText, upgradeHighlightComparison);
		}

		string lessOrMore = isLess
			? CardEditorLoc.T("cardText.costDelta.less", "less")
			: CardEditorLoc.T("cardText.costDelta.more", "more");

		if (durationSuffix != null)
		{
			return CardEditorLoc.F(
				"cardText.cardStarCostDelta.duration",
				$"This card costs {amountText} {lessOrMore} {durationSuffix}.",
				("Amount", amountText),
				("LessOrMore", lessOrMore),
				("Stars", string.Empty),
				("Duration", durationSuffix));
		}

		return CardEditorLoc.F(
			"cardText.cardStarCostDelta",
			$"This card costs {amountText} {lessOrMore}.",
			("Amount", amountText),
			("LessOrMore", lessOrMore),
			("Stars", string.Empty));
	}

	private static string FormatAddSpecificCardToHand(CardExtraEffect effect, int amount, string amountText)
	{
		string cardName = BuildSpecificCardReferenceText(effect?.SpecificCardId, GetCardReferenceDisplayMode(effect));
		string destination = BuildGeneratedDestinationText(GetConfiguredCardCreationDestinations(effect, CardExtraEffectCardPile.DrawPile, CardExtraEffectCardPilePosition.Top));
		return amount == 1
			? CardEditorLoc.F("cardText.addSpecificCard.one", $"Add a {cardName} into {destination}.", ("Card", cardName), ("Destination", destination))
			: CardEditorLoc.F("cardText.addSpecificCard.many", $"Add {amountText} copies of {cardName} into {destination}.", ("Amount", amountText), ("Card", cardName), ("Destination", destination));
	}

	private static string FormatFetchSpecificCardToHand(CardExtraEffect effect, int amount, string amountText)
	{
		string cardName = BuildSpecificCardReferenceText(effect?.SpecificCardId, GetCardReferenceDisplayMode(effect));
		string destination = GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition);
		bool all = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All;
		if (all)
			return CardEditorLoc.F("cardText.fetchSpecificCard.all", $"Put all copies of {cardName} into your {destination} from any pile.", ("Card", cardName), ("Destination", destination));
		return amount == 1
			? CardEditorLoc.F("cardText.fetchSpecificCard.one", $"Put {cardName} into your {destination} from any pile.", ("Card", cardName), ("Destination", destination))
			: CardEditorLoc.F("cardText.fetchSpecificCard.many", $"Put up to {amountText} copies of {cardName} into your {destination} from any pile.", ("Amount", amountText), ("Card", cardName), ("Destination", destination));
	}

	private static string FormatPlayCardFromPile(CardModel? card, CardExtraEffect effect, int amount, string amountText)
	{
		if (UsesSelectedCardReplay(effect))
		{
			int replayCount = ResolveSelectedCardReplayCount(effect);
			string replayText = replayCount.ToString(CultureInfo.InvariantCulture);
			string selectedCards = amount == 1
				? CardEditorLoc.T("cardText.playSelected.card", "the selected card")
				: CardEditorLoc.T("cardText.playSelected.cards", "each selected card");
			string selectedResult = replayCount == 1
				? CardEditorLoc.F("cardText.playSelected.once", $"Play {selectedCards}.", ("Cards", selectedCards))
				: CardEditorLoc.F("cardText.playSelected.replay", $"Play {selectedCards} {replayText} times.", ("Cards", selectedCards), ("Times", replayText));
			if (effect.AutoPlayForceExhaust)
			{
				selectedResult = AppendSentenceNote(selectedResult, CardEditorLoc.T("cardText.playFromPile.forceExhaust", "The played card exhausts."));
			}
			return BuildCostFilteredText(card, selectedResult, effect);
		}

		string pile = GetCardPilePossessive(effect.CardSelectionPile);
		bool random = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.Random;
		bool all = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All;
		bool upTo = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.UpTo;
		bool top = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.Top;
		bool topOffer = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.TopOffer;
		bool bottom = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.Bottom;
		string offerCountText = effect.CardSelectionOfferCountIsX
			? FormatXPlusText(effect.CardSelectionOfferCount)
			: Math.Max(0, effect.CardSelectionOfferCount).ToString(CultureInfo.InvariantCulture);
		string result;
		if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.ThisCard)
		{
			// PlayCardFromPile resolves ThisCard via the effect-source context (host card on
			// power rows too), so the wording is always "this card".
			result = CardEditorLoc.T("cardText.playFromPile.thisCard", "Play this card.");
		}
		else if (all)
		{
			result = CardEditorLoc.F("cardText.playFromPile.all", $"Play all cards from {pile}.", ("Pile", pile));
		}
		else if (upTo)
		{
			result = CardEditorLoc.F("cardText.playFromPile.upTo.many", $"Play up to {amountText} cards from {pile}.", ("Amount", amountText), ("Pile", pile));
		}
		else if (top)
		{
			result = amount == 1
				? CardEditorLoc.F("cardText.playFromPile.top.one", $"Play the top card of {pile}.", ("Pile", pile))
				: CardEditorLoc.F("cardText.playFromPile.top.many", $"Play the top {amountText} cards of {pile}.", ("Amount", amountText), ("Pile", pile));
		}
		else if (topOffer)
		{
			result = CardEditorLoc.F(
				"cardText.playFromPile.topOffer",
				$"Choose {amountText} of the top {offerCountText} cards of {pile} to play.",
				("Amount", amountText),
				("OfferCount", offerCountText),
				("Pile", pile));
		}
		else if (bottom)
		{
			result = amount == 1
				? CardEditorLoc.F("cardText.playFromPile.bottom.one", $"Play the bottom card of {pile}.", ("Pile", pile))
				: CardEditorLoc.F("cardText.playFromPile.bottom.many", $"Play the bottom {amountText} cards of {pile}.", ("Amount", amountText), ("Pile", pile));
		}
		else if (amount == 1)
		{
			result = random
				? CardEditorLoc.F("cardText.playFromPile.random.one", $"Play a random card from {pile}.", ("Pile", pile))
				: CardEditorLoc.F("cardText.playFromPile.choose.one", $"Play a card from {pile}.", ("Pile", pile));
		}
		else
		{
			result = random
				? CardEditorLoc.F("cardText.playFromPile.random.many", $"Play {amountText} random cards from {pile}.", ("Amount", amountText), ("Pile", pile))
				: CardEditorLoc.F("cardText.playFromPile.choose.many", $"Play {amountText} cards from {pile}.", ("Amount", amountText), ("Pile", pile));
		}
		result = AppendCardSelectionNote(result, effect);
		if (effect.AutoPlayForceExhaust)
		{
			result = AppendSentenceNote(result, CardEditorLoc.T("cardText.playFromPile.forceExhaust", "The played card exhausts."));
		}
		return BuildCostFilteredText(card, result, effect);
	}

	private static string FormatConsumeCardValue(CardModel? card, CardExtraEffect effect, int amount, string amountText)
	{
		if (effect == null)
		{
			return string.Empty;
		}

		string from = effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles
			? CardEditorLoc.T("cardText.pile.anywhere", "anywhere")
			: GetCardPilePossessive(effect.CardSelectionPile);
		bool thisCard = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.ThisCard;
		bool selectedByEffect = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect;
		string selected = thisCard
			? CardEditorLoc.T("cardText.thisCard", "this card")
			: BuildDelayedPileSelectionText(effect);
		string value = ConsumedCardValueSourceLabel(effect.ConsumedCardValueSource).ToLowerInvariant();
		string target = SelfScalingTargetTypeLabel(effect.SelfScalingTargetType).ToLowerInvariant();
		// Linked rows consume the upstream step's published cards, so drop the "from {pile}" clause.
		string action = effect.ConsumedCardAction switch
		{
			CardExtraEffectConsumedCardAction.None => selectedByEffect
				? CardEditorLoc.F("cardText.consumeCardValue.action.read.selected", $"read {selected}", ("Cards", selected))
				: CardEditorLoc.F("cardText.consumeCardValue.action.read", $"read {selected} from {from}", ("Cards", selected), ("From", from)),
			CardExtraEffectConsumedCardAction.Discard => selectedByEffect
				? CardEditorLoc.F("cardText.consumeCardValue.action.discard.selected", $"discard {selected}", ("Cards", selected))
				: CardEditorLoc.F("cardText.consumeCardValue.action.discard", $"discard {selected} from {from}", ("Cards", selected), ("From", from)),
			CardExtraEffectConsumedCardAction.Exhaust => selectedByEffect
				? CardEditorLoc.F("cardText.consumeCardValue.action.exhaust.selected", $"exhaust {selected}", ("Cards", selected))
				: CardEditorLoc.F("cardText.consumeCardValue.action.exhaust", $"exhaust {selected} from {from}", ("Cards", selected), ("From", from)),
			CardExtraEffectConsumedCardAction.RemoveFromDeck => thisCard
				? CardEditorLoc.T("cardText.consumeCardValue.action.removeDeck.self", "remove this card from your deck")
				: selectedByEffect
					? CardEditorLoc.F("cardText.consumeCardValue.action.removeDeck.selected", $"remove the deck versions of {selected}", ("Cards", selected))
					: CardEditorLoc.F("cardText.consumeCardValue.action.removeDeck", $"remove the deck versions of {selected} from {from}", ("Cards", selected), ("From", from)),
			_ => selectedByEffect
				? CardEditorLoc.F(
					"cardText.consumeCardValue.action.move.selected",
					$"move {selected} to {GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition)}",
					("Cards", selected),
					("To", GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition)))
				: CardEditorLoc.F(
					"cardText.consumeCardValue.action.move",
					$"move {selected} from {from} to {GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition)}",
					("Cards", selected),
					("From", from),
					("To", GetCardPileDestination(effect.MoveToPile, effect.MoveToPosition)))
		};

		string result = selectedByEffect
			? CardEditorLoc.F(
				"cardText.consumeCardValue.selected",
				$"{CapitalizeFirst(action)}. Add their {value} to this card's {target}.",
				("Action", CapitalizeFirst(action)),
				("Value", value),
				("Target", target))
			: CardEditorLoc.F(
				"cardText.consumeCardValue",
				$"{CapitalizeFirst(action)}. Add its {value} to this card's {target}.",
				("Action", CapitalizeFirst(action)),
				("Value", value),
				("Target", target));
		result = AppendCardSelectionNote(result, effect);
		return BuildCostFilteredText(card, result, effect);
	}

	private static string CapitalizeFirst(string text)
	{
		if (string.IsNullOrEmpty(text))
		{
			return text;
		}

		return char.ToUpperInvariant(text[0]) + text[1..];
	}

	private static string SelfScalingTargetTypeLabel(CardExtraEffectSelfScalingTargetType targetType)
	{
		return targetType switch
		{
			CardExtraEffectSelfScalingTargetType.BaseDamage => "damage",
			CardExtraEffectSelfScalingTargetType.BaseBlock => "Block",
			CardExtraEffectSelfScalingTargetType.EffectRowAmount => "chosen effect row",
			CardExtraEffectSelfScalingTargetType.DynamicVar => "chosen number",
			CardExtraEffectSelfScalingTargetType.EnergyCost => "Energy cost",
			CardExtraEffectSelfScalingTargetType.StarCost => "Star cost",
			CardExtraEffectSelfScalingTargetType.RepeatCounts => "repeat counts",
			CardExtraEffectSelfScalingTargetType.AllGameplayNumbers => "gameplay numbers",
			CardExtraEffectSelfScalingTargetType.AllGameplayNumbersIncludingRepeats => "gameplay numbers and repeats",
			CardExtraEffectSelfScalingTargetType.AllNumbersIncludingRepeats => "numbers and repeats",
			_ => "numbers"
		};
	}

	private static string FormatAutoPlaySelfFromPile(CardExtraEffect effect)
	{
		string pile = GetCardPileLocationWithSelectionMode(effect.CardSelectionPile, effect.CardSelectionMode);
		if (IsPowerEffect(effect))
		{
			// Power-hosted rows (Whenever and other power triggers) get their trigger wording
			// from ApplyPowerTriggerPrefix — emit only the action clause (no double prefix).
			return CardEditorLoc.F(
				"cardText.autoPlaySelf.powerAction",
				$"If this is {pile}, play it.",
				("Pile", pile));
		}
		return effect.Trigger switch
		{
			CardExtraEffectTrigger.OnDraw => CardEditorLoc.F(
				"cardText.autoPlaySelf.onDraw",
				$"Whenever a card is drawn, if this is {pile}, play it.",
				("Pile", pile)),
			CardExtraEffectTrigger.OnDiscard => CardEditorLoc.F(
				"cardText.autoPlaySelf.onDiscard",
				$"Whenever a card is discarded, if this is {pile}, play it.",
				("Pile", pile)),
			CardExtraEffectTrigger.OnExhaust => CardEditorLoc.F(
				"cardText.autoPlaySelf.onExhaust",
				$"Whenever a card is exhausted, if this is {pile}, play it.",
				("Pile", pile)),
			CardExtraEffectTrigger.EndOfTurn => CardEditorLoc.F(
				"cardText.autoPlaySelf.endOfTurn",
				$"At the end of your turn, if this is {pile}, play it.",
				("Pile", pile)),
			CardExtraEffectTrigger.StartOfEnemyTurn => CardEditorLoc.F(
				"cardText.autoPlaySelf.startOfEnemyTurn",
				$"At the start of the enemy turn, if this is {pile}, play it.",
				("Pile", pile)),
			CardExtraEffectTrigger.OnPlay => CardEditorLoc.F(
				"cardText.autoPlaySelf.onPlay",
				$"Whenever a card is played, if this is {pile}, play it.",
				("Pile", pile)),
			CardExtraEffectTrigger.OnMovedToTopOfPile => CardEditorLoc.F(
				"cardText.autoPlaySelf.onMovedToTop",
				$"Whenever this is moved to {GetCardPileBoundary(effect.CardSelectionPile, top: true)}, play it.",
				("Pile", GetCardPileBoundary(effect.CardSelectionPile, top: true))),
			CardExtraEffectTrigger.OnMovedToBottomOfPile => CardEditorLoc.F(
				"cardText.autoPlaySelf.onMovedToBottom",
				$"Whenever this is moved to {GetCardPileBoundary(effect.CardSelectionPile, top: false)}, play it.",
				("Pile", GetCardPileBoundary(effect.CardSelectionPile, top: false))),
			CardExtraEffectTrigger.TurnBoundary => FormatSelfPileAutoTurnBoundary(effect, pile, "play", isPlay: true),
			_ => CardEditorLoc.F(
				"cardText.autoPlaySelf.startOfTurn",
				$"At the start of your turn, if this is {pile}, play it.",
				("Pile", pile))
		};
	}

	private static string FormatSelfPileAutoTurnBoundary(CardExtraEffect effect, string pile, string action, bool isPlay, bool usePayloadAsAction = false)
	{
		string when = BuildSelfPileAutoTurnBoundaryWhenClause(effect);
		string key = isPlay
			? "cardText.autoPlaySelf.turnBoundary"
			: "cardText.autoDrawSelf.turnBoundary";
		if (usePayloadAsAction)
		{
			return CardEditorLoc.F(
				"cardText.autoRunEffectRows.turnBoundary",
				$"{when}, if this is {pile}, {action}.",
				("When", when),
				("Pile", pile),
				("Action", action));
		}
		return CardEditorLoc.F(
			key,
			$"{when}, if this is {pile}, {action} it.",
			("When", when),
			("Pile", pile),
			("Action", action));
	}

	private static string BuildSelfPileAutoTurnBoundaryWhenClause(CardExtraEffect effect)
	{
		string sideText = effect.TurnBoundarySide switch
		{
			CardExtraEffectTurnBoundarySide.EnemyTurn => CardEditorLoc.T("cardText.selfPileAuto.turnBoundary.side.enemyTurn", "the enemy turn"),
			CardExtraEffectTurnBoundarySide.Both => CardEditorLoc.T("cardText.selfPileAuto.turnBoundary.side.eachTurn", "each turn"),
			_ => CardEditorLoc.T("cardText.selfPileAuto.turnBoundary.side.yourTurn", "your turn")
		};

		return effect.TurnBoundary switch
		{
			CardExtraEffectTurnBoundary.Start => CardEditorLoc.F(
				"cardText.selfPileAuto.turnBoundary.startBeforeDraw",
				$"At the start of {sideText}",
				("Side", sideText)),
			CardExtraEffectTurnBoundary.StartAfterDraw => CardEditorLoc.F(
				"cardText.selfPileAuto.turnBoundary.startAfterDraw",
				$"At the start of {sideText} after draw",
				("Side", sideText)),
			CardExtraEffectTurnBoundary.EndAfterDiscard => CardEditorLoc.F(
				"cardText.selfPileAuto.turnBoundary.endAfterDiscard",
				$"At the end of {sideText} after discard",
				("Side", sideText)),
			_ => CardEditorLoc.F(
				"cardText.selfPileAuto.turnBoundary.endBeforeDiscard",
				$"At the end of {sideText} before discard",
				("Side", sideText))
		};
	}

	private static string FormatDrawCards(CardExtraEffect effect, int grammarAmount, string amountText)
	{
		CardExtraEffect displayEffect = GetGrantPayloadViewEffect(effect);
		CardExtraEffectCardPile sourcePile = GetEffectiveDrawSourcePile(displayEffect);
		bool hasSelectionCriteria = displayEffect != null && HasCardSelectionCriteria(displayEffect);
		bool selectedByEffect = displayEffect != null && displayEffect.CardSelectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect;
		if (selectedByEffect)
		{
			// Linked rows draw the upstream step's published cards. Keep the "Draw " prefix so
			// ApplyPlayerDrawSubject's player-target rewrite still applies.
			return CardEditorLoc.T("cardText.drawCards.selected", "Draw those cards.");
		}
		if (hasSelectionCriteria || sourcePile != CardExtraEffectCardPile.DrawPile)
		{
			string descriptor = hasSelectionCriteria
				? BuildCardSelectionDescriptor(displayEffect, plural: grammarAmount != 1)
				: (grammarAmount == 1 ? "card" : "cards");
			string sourceText = sourcePile == CardExtraEffectCardPile.AllPiles
				? CardEditorLoc.T("cardText.pile.anywhere", "any pile")
				: GetCardPilePossessive(sourcePile);
			return CardEditorLoc.F(
				"cardText.drawCards.filtered",
				$"Draw {amountText} {descriptor} from {sourceText}.",
				("Amount", amountText),
				("Descriptor", descriptor),
				("Source", sourceText));
		}

		string cardOrCards = grammarAmount == 1 ? "card" : "cards";
		return CardEditorLoc.F(
			"cardText.drawCards",
			$"Draw {amountText} {cardOrCards}.",
			("Amount", amountText),
			("CardWord", cardOrCards));
	}

	private static string FormatDrawCardsThatCostLess(CardModel card, CardExtraEffect effect, int grammarAmount, string amountText, string? durationSuffix)
	{
		CardExtraEffect displayEffect = GetGrantPayloadViewEffect(effect);
		int costLess = displayEffect.CardSelectionCount > 0 ? displayEffect.CardSelectionCount : 1;
		string costLessText = BuildEnergyIcons(card, costLess);
		string subject = grammarAmount == 1 ? "it" : "they";
		string subjectCap = char.ToUpperInvariant(subject[0]) + subject[1..];
		string cardOrCards = grammarAmount == 1 ? "card" : "cards";
		CardExtraEffectCardPile sourcePile = GetEffectiveDrawSourcePile(displayEffect);
		if (displayEffect != null && displayEffect.CardSelectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect)
		{
			// Linked rows draw the upstream step's published cards. Keep the "Draw " prefix so
			// ApplyPlayerDrawSubject's player-target rewrite still applies.
			if (durationSuffix != null)
			{
				return CardEditorLoc.F(
					"cardText.drawCostLess.selected.duration",
					$"Draw those cards. They cost {costLessText} less {durationSuffix}.",
					("CostLess", costLessText),
					("Duration", durationSuffix));
			}

			return CardEditorLoc.F(
				"cardText.drawCostLess.selected",
				$"Draw those cards. They cost {costLessText} less.",
				("CostLess", costLessText));
		}
		if ((displayEffect != null && HasCardSelectionCriteria(displayEffect)) || sourcePile != CardExtraEffectCardPile.DrawPile)
		{
			string descriptor = displayEffect != null && HasCardSelectionCriteria(displayEffect)
				? BuildCardSelectionDescriptor(displayEffect, plural: grammarAmount != 1)
				: cardOrCards;
			string sourceText = sourcePile == CardExtraEffectCardPile.AllPiles
				? CardEditorLoc.T("cardText.pile.anywhere", "any pile")
				: GetCardPilePossessive(sourcePile);
			if (durationSuffix != null)
			{
				return CardEditorLoc.F(
					"cardText.drawCostLess.filtered.duration",
					$"Draw {amountText} {descriptor} from {sourceText}. {subjectCap} cost {costLessText} less {durationSuffix}.",
					("Amount", amountText),
					("Descriptor", descriptor),
					("Source", sourceText),
					("CostLess", costLessText),
					("SubjectCap", subjectCap),
					("Duration", durationSuffix));
			}

			return CardEditorLoc.F(
				"cardText.drawCostLess.filtered",
				$"Draw {amountText} {descriptor} from {sourceText}. {subjectCap} cost {costLessText} less.",
				("Amount", amountText),
				("Descriptor", descriptor),
				("Source", sourceText),
				("CostLess", costLessText),
				("SubjectCap", subjectCap));
		}
		if (durationSuffix != null)
		{
			return CardEditorLoc.F(
				"cardText.drawCostLess.duration",
				$"Draw {amountText} {cardOrCards}. {subjectCap} cost {costLessText} less {durationSuffix}.",
				("Amount", amountText),
				("CardWord", cardOrCards),
				("CostLess", costLessText),
				("SubjectCap", subjectCap),
				("Duration", durationSuffix));
		}
		return CardEditorLoc.F(
			"cardText.drawCostLess",
			$"Draw {amountText} {cardOrCards}. {subjectCap} cost {costLessText} less.",
			("Amount", amountText),
			("CardWord", cardOrCards),
			("CostLess", costLessText),
			("SubjectCap", subjectCap));
	}

