		{
			CardExtraEffectCardSelectionMode.Top => CardEditorLoc.F(
				"cardText.pile.atTopOfSelected",
				$"at {GetCardPileBoundary(pile, top: true)}",
				("Pile", GetCardPileBoundary(pile, top: true))),
			CardExtraEffectCardSelectionMode.Bottom => CardEditorLoc.F(
				"cardText.pile.atBottomOfSelected",
				$"at {GetCardPileBoundary(pile, top: false)}",
				("Pile", GetCardPileBoundary(pile, top: false))),
			_ => GetCardPileLocation(pile)
		};
	}

	private static string GetCardPileDestination(CardExtraEffectCardPile pile, CardExtraEffectCardPilePosition position)
	{
		if (pile == CardExtraEffectCardPile.DrawPile)
		{
			string pileLabel = CardPileLabel(pile);
			return position switch
			{
				CardExtraEffectCardPilePosition.Top => CardEditorLoc.F("cardText.pile.topOf", $"the top of your {pileLabel}", ("Pile", pileLabel)),
				CardExtraEffectCardPilePosition.Bottom => CardEditorLoc.F("cardText.pile.bottomOf", $"the bottom of your {pileLabel}", ("Pile", pileLabel)),
				_ => GetCardPilePossessive(pile)
			};
		}

		return GetCardPilePossessive(pile);
	}

	private static string BuildGeneratedCardFilter(CardExtraEffect effect, bool plural)
	{
		string poolAdj = BuildGeneratedPoolAdjective(effect.GeneratedCardPool);

		string typeAdj = effect.GeneratedCardType switch
		{
			CardGeneratedCardType.Attack => GeneratedCardTypeLabel(CardGeneratedCardType.Attack) + " ",
			CardGeneratedCardType.Skill => GeneratedCardTypeLabel(CardGeneratedCardType.Skill) + " ",
			CardGeneratedCardType.Power => GeneratedCardTypeLabel(CardGeneratedCardType.Power) + " ",
			CardGeneratedCardType.Playable => "[gold]" + GetPlayableKeywordTitle() + "[/gold] ",
			CardGeneratedCardType.Status when !PoolImpliesGeneratedType(effect.GeneratedCardPool, CardGeneratedCardType.Status) => GeneratedCardTypeLabel(CardGeneratedCardType.Status) + " ",
			CardGeneratedCardType.Curse when !PoolImpliesGeneratedType(effect.GeneratedCardPool, CardGeneratedCardType.Curse) => GeneratedCardTypeLabel(CardGeneratedCardType.Curse) + " ",
			CardGeneratedCardType.Quest when !PoolImpliesGeneratedType(effect.GeneratedCardPool, CardGeneratedCardType.Quest) => GeneratedCardTypeLabel(CardGeneratedCardType.Quest) + " ",
			CardGeneratedCardType.NonAttack => GeneratedCardTypeLabel(CardGeneratedCardType.NonAttack) + " ",
			CardGeneratedCardType.NonSkill => GeneratedCardTypeLabel(CardGeneratedCardType.NonSkill) + " ",
			CardGeneratedCardType.NonPower => GeneratedCardTypeLabel(CardGeneratedCardType.NonPower) + " ",
			_ => string.Empty
		};

		string prefix = (poolAdj + typeAdj).Trim();
		return string.IsNullOrEmpty(prefix) ? string.Empty : prefix + " ";
	}

	private static string BuildGeneratedCardCustomTagSuffix(CardExtraEffect effect)
	{
		string tag = effect.GeneratedCardCustomTag?.Trim() ?? string.Empty;
		return string.IsNullOrWhiteSpace(tag)
			? string.Empty
			: CardEditorLoc.F("cardText.generate.customTagSuffix", " with \"{Tag}\" tag", ("Tag", tag));
	}

	private static string BuildGeneratedPoolAdjective(CardGeneratedCardPool pool)
	{
		return IsNamedGeneratedPool(pool) ? GeneratedCardPoolLabel(pool) + " " : string.Empty;
	}

	private static bool IsNamedGeneratedPool(CardGeneratedCardPool pool)
	{
		return pool is CardGeneratedCardPool.Colorless
			or CardGeneratedCardPool.Ironclad
			or CardGeneratedCardPool.Silent
			or CardGeneratedCardPool.Defect
			or CardGeneratedCardPool.Regent
			or CardGeneratedCardPool.Necrobinder
			or CardGeneratedCardPool.Ancient
			or CardGeneratedCardPool.Status
			or CardGeneratedCardPool.Curse
			or CardGeneratedCardPool.Quest
			or CardGeneratedCardPool.Token
			or CardGeneratedCardPool.Event;
	}

	private static bool PoolImpliesGeneratedType(CardGeneratedCardPool pool, CardGeneratedCardType type)
	{
		return (pool == CardGeneratedCardPool.Status && type == CardGeneratedCardType.Status)
			|| (pool == CardGeneratedCardPool.Curse && type == CardGeneratedCardType.Curse)
			|| (pool == CardGeneratedCardPool.Quest && type == CardGeneratedCardType.Quest);
	}

	private static bool IsUnrestrictedGeneratedPool(CardGeneratedCardPool pool)
	{
		return pool is CardGeneratedCardPool.All or CardGeneratedCardPool.AllPools;
	}

	private static string BuildGeneratedCardPoolSuffix(CardGeneratedCardPool pool)
	{
		return pool switch
		{
			CardGeneratedCardPool.OtherColors => CardEditorLoc.T("cardText.poolSuffix.otherColors", " from other characters"),
			CardGeneratedCardPool.Any => CardEditorLoc.T("cardText.poolSuffix.allColors", " from any character"),
			CardGeneratedCardPool.All => CardEditorLoc.T("cardText.poolSuffix.allPools", " from all cards"),
			CardGeneratedCardPool.AllPools => CardEditorLoc.T("cardText.poolSuffix.allCardPools", " from all card pools"),
			_ => string.Empty
		};
	}

	private static string BuildCountScalingPoolSuffix(CardGeneratedCardPool pool)
	{
		// For non-generation text, generic "cards" already means literally all cards.
		// Keep the explicit suffix for "any character" because it excludes Colorless/Ancient.
		if (pool == CardGeneratedCardPool.All || pool == CardGeneratedCardPool.AllPools)
		{
			return string.Empty;
		}

		return pool switch
		{
			CardGeneratedCardPool.Default => CardEditorLoc.T("cardText.poolSuffix.yourColor", " of your color"),
			CardGeneratedCardPool.OtherColors => CardEditorLoc.T("cardText.poolSuffix.otherColors", " from other characters"),
			CardGeneratedCardPool.Any => CardEditorLoc.T("cardText.poolSuffix.allColors", " from any character"),
			_ => string.Empty
		};
	}

	// Target-aware pile wording for grant effects: a grant aimed at an ally/other player reads
	// "in an ally's hand" rather than the default "in your hand". Non-friendly targets fall back to
	// the shared (self) wording so unrelated callers and self-grants are unchanged.
	private static string GetCardPileLocationForTarget(CardExtraEffectCardPile pile, CardExtraEffectTarget target)
	{
		if (target is not (CardExtraEffectTarget.AnyAlly or CardExtraEffectTarget.AllAllies or CardExtraEffectTarget.AnyPlayer))
		{
			return GetCardPileLocation(pile);
		}

		string owner = target == CardExtraEffectTarget.AnyPlayer
			? CardEditorLoc.T("cardText.pile.owner.player", "a player's")
			: CardEditorLoc.T("cardText.pile.owner.ally", "an ally's");

		return pile switch
		{
			CardExtraEffectCardPile.Hand => CardEditorLoc.F("cardText.pile.inHandOf", $"in {owner} hand", ("Owner", owner)),
			CardExtraEffectCardPile.DrawPile => CardEditorLoc.F("cardText.pile.inDrawPileOf", $"in {owner} draw pile", ("Owner", owner)),
			CardExtraEffectCardPile.DiscardPile => CardEditorLoc.F("cardText.pile.inDiscardPileOf", $"in {owner} discard pile", ("Owner", owner)),
			CardExtraEffectCardPile.ExhaustPile => CardEditorLoc.F("cardText.pile.inExhaustPileOf", $"in {owner} exhaust pile", ("Owner", owner)),
			CardExtraEffectCardPile.Deck => CardEditorLoc.F("cardText.pile.inDeckOf", $"in {owner} deck", ("Owner", owner)),
			CardExtraEffectCardPile.AllPiles => CardEditorLoc.T("cardText.pile.inAnyPile", "in any pile"),
			_ => CardEditorLoc.F("cardText.pile.inHandOf", $"in {owner} hand", ("Owner", owner))
		};
	}

	private static string GetCardPileLocation(CardExtraEffectCardPile pile)
	{
		return pile switch
		{
			CardExtraEffectCardPile.Hand => CardEditorLoc.T("cardText.pile.inHand", "in your hand"),
			CardExtraEffectCardPile.DrawPile => CardEditorLoc.T("cardText.pile.inDrawPile", "in your draw pile"),
			CardExtraEffectCardPile.DiscardPile => CardEditorLoc.T("cardText.pile.inDiscardPile", "in your discard pile"),
			CardExtraEffectCardPile.ExhaustPile => CardEditorLoc.T("cardText.pile.inExhaustPile", "in your exhaust pile"),
			CardExtraEffectCardPile.AllPiles => CardEditorLoc.T("cardText.pile.inAnyPile", "in any pile"),
			CardExtraEffectCardPile.Deck => CardEditorLoc.T("cardText.pile.inDeck", "in your deck"),
			_ => CardEditorLoc.T("cardText.pile.inHand", "in your hand")
		};
	}

	private static void TryGetScaledAmountText(CardModel card, CardExtraEffect effect, int baseAmount, Creature? target, int upgradeHighlightComparison, out string amountText)
	{
		amountText = baseAmount.ToString(CultureInfo.InvariantCulture);

		try
		{
			CardModel modifierCard = CardEditorBorrowedEffectSourceDamageHelper.ResolveRuntimePlayedCard(card) ?? card;
			ValueProp props = ValueProp.Move;

			decimal enchanted = baseAmount;
			if (modifierCard.Enchantment != null)
			{
				if (effect.Kind == CardExtraEffectKind.DealDamage)
				{
					enchanted += modifierCard.Enchantment.EnchantDamageAdditive(enchanted, props);
					enchanted *= modifierCard.Enchantment.EnchantDamageMultiplicative(enchanted, props);
				}
				else if (effect.Kind == CardExtraEffectKind.GainBlock)
				{
					enchanted += EnchantBlockAdditiveCompat(modifierCard.Enchantment, enchanted, props);
					enchanted *= EnchantBlockMultiplicativeCompat(modifierCard.Enchantment, enchanted, props);
				}
			}

			decimal preview = enchanted;
			// The vanilla hooks re-apply the card's enchantment internally, so they must receive the
			// RAW base amount (vanilla DamageVar feeds BaseValue into Hook.ModifyDamage the same way);
			// passing the enchanted value would double-count the bonus.
			if (TryGetHookedMoveAmountPreview(card, effect, baseAmount, target, out decimal hookedPreview))
			{
				preview = hookedPreview;
			}

			int previewInt = (int)preview;
			// Vanilla compares the live preview against the ENCHANTED value, not the raw base: an
			// enchanted card's boosted number is its new plain baseline, not permanently green —
			// except while previewing an enchantment offer, where the boost itself shows green.
			decimal comparisonBaseline = modifierCard.IsEnchantmentPreview ? baseAmount : enchanted;
			int comparison = upgradeHighlightComparison != 0 ? upgradeHighlightComparison : previewInt.CompareTo((int)comparisonBaseline);
			amountText = StsTextUtilities.HighlightChangeText(previewInt.ToString(CultureInfo.InvariantCulture), comparison);
		}
		catch
		{
			amountText = baseAmount.ToString(CultureInfo.InvariantCulture);
		}
	}

	private static decimal EnchantBlockAdditiveCompat(EnchantmentModel enchantment, decimal originalBlock, ValueProp props)
	{
		return InvokeDecimalEnchantmentMethodCompat(enchantment, nameof(EnchantmentModel.EnchantBlockAdditive), originalBlock, props, 0m);
	}

	private static decimal EnchantBlockMultiplicativeCompat(EnchantmentModel enchantment, decimal originalBlock, ValueProp props)
	{
		return InvokeDecimalEnchantmentMethodCompat(enchantment, nameof(EnchantmentModel.EnchantBlockMultiplicative), originalBlock, props, 1m);
	}

	private static decimal InvokeDecimalEnchantmentMethodCompat(EnchantmentModel enchantment, string methodName, decimal originalAmount, ValueProp props, decimal fallback)
	{
		try
		{
			MethodInfo? method = enchantment.GetType().GetMethod(
					methodName,
					BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
					binder: null,
					types: new[] { typeof(decimal), typeof(ValueProp) },
					modifiers: null)
				?? enchantment.GetType().GetMethod(
					methodName,
					BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
					binder: null,
					types: new[] { typeof(decimal) },
					modifiers: null);

			if (method == null)
			{
				return fallback;
			}

			object? result = method.GetParameters().Length == 2
				? method.Invoke(enchantment, new object[] { originalAmount, props })
				: method.Invoke(enchantment, new object[] { originalAmount });

			return result == null ? fallback : Convert.ToDecimal(result, CultureInfo.InvariantCulture);
		}
		catch
		{
			return fallback;
		}
	}

	private static bool TryGetScaledPowerAmountText(CardModel card, CardExtraEffect effect, int baseAmount, Creature? target, int upgradeHighlightComparison, out string amountText)
	{
		amountText = baseAmount.ToString(CultureInfo.InvariantCulture);

		try
		{
			if (!TryResolveAppliedPowerPreviewModel(effect, out PowerModel? canonicalPower, out bool displayAbsoluteAmount)
				|| canonicalPower == null)
			{
				return false;
			}

			CardModel modifierCard = CardEditorBorrowedEffectSourceDamageHelper.ResolveRuntimePlayedCard(card) ?? card;
			Player? owner = modifierCard.Owner;
			Creature? ownerCreature = owner?.Creature;
			CombatState? combatState = modifierCard.GetConcreteCombatState();
			if (!ShouldRunGlobalHooks(modifierCard)
				|| ownerCreature == null
				|| combatState == null
				|| !combatState.ContainsCreature(ownerCreature))
			{
				return false;
			}

			decimal baseForHook = displayAbsoluteAmount ? -baseAmount : baseAmount;
			IReadOnlyList<Creature?> previewTargets = ResolvePreviewTargetsForEffect(combatState, ownerCreature, modifierCard, target, effect.Target, ownerCreature);
			decimal preview = baseForHook;
			if (_modifyPowerAmountGivenHook.Value == null)
			{
				return false;
			}
			if (!TryGetUniformHookedPreview(previewTargets, previewTarget =>
				TryInvokeModifyPowerAmountGivenHook(combatState, canonicalPower, ownerCreature, baseForHook, previewTarget, modifierCard, out decimal hookedPreview)
					? hookedPreview
					: baseForHook, out preview))
			{
				Creature? fallbackTarget = effect.Target == CardExtraEffectTarget.Self
					? ownerCreature
					: effect.Target == CardExtraEffectTarget.Target
						? target
						: null;
				if (!TryInvokeModifyPowerAmountGivenHook(combatState, canonicalPower, ownerCreature, baseForHook, fallbackTarget, modifierCard, out preview))
				{
					return false;
				}
			}

			int previewInt = (int)preview;
			int displayPreview = displayAbsoluteAmount ? Math.Abs(previewInt) : previewInt;
			int comparison = upgradeHighlightComparison != 0 ? upgradeHighlightComparison : displayPreview.CompareTo(baseAmount);
			amountText = StsTextUtilities.HighlightChangeText(displayPreview.ToString(CultureInfo.InvariantCulture), comparison);
			return true;
		}
		catch
		{
			amountText = baseAmount.ToString(CultureInfo.InvariantCulture);
			return false;
		}
	}

	private static readonly Lazy<MethodInfo?> _modifyPowerAmountGivenHook = new(FindModifyPowerAmountGivenHook);

	private static MethodInfo? FindModifyPowerAmountGivenHook()
	{
		try
		{
			return typeof(Hook).GetMethods(BindingFlags.Public | BindingFlags.Static)
				.FirstOrDefault(method =>
				{
					if (!string.Equals(method.Name, "ModifyPowerAmountGiven", StringComparison.Ordinal)
						|| method.ReturnType != typeof(decimal))
					{
						return false;
					}

					ParameterInfo[] parameters = method.GetParameters();
					return parameters.Length >= 7
						&& typeof(PowerModel).IsAssignableFrom(parameters[1].ParameterType)
						&& typeof(Creature).IsAssignableFrom(parameters[2].ParameterType)
						&& parameters[3].ParameterType == typeof(decimal)
						&& typeof(CardModel).IsAssignableFrom(parameters[5].ParameterType);
				});
		}
		catch
		{
			return null;
		}
	}

	private static bool TryInvokeModifyPowerAmountGivenHook(
		CombatState combatState,
		PowerModel power,
		Creature giver,
		decimal amount,
		Creature? target,
		CardModel card,
		out decimal result)
	{
		result = amount;
		MethodInfo? method = _modifyPowerAmountGivenHook.Value;
		if (method == null)
		{
			return false;
		}

		try
		{
			ParameterInfo[] parameters = method.GetParameters();
			object?[] args = new object?[parameters.Length];
			args[0] = combatState;
			args[1] = power;
			args[2] = giver;
			args[3] = amount;
			args[4] = target;
			args[5] = card;
			for (int i = 6; i < args.Length; i++)
			{
				args[i] = null;
			}

			if (!IsReflectionArgumentCompatible(parameters[0].ParameterType, combatState)
				|| !IsReflectionArgumentCompatible(parameters[1].ParameterType, power)
				|| !IsReflectionArgumentCompatible(parameters[2].ParameterType, giver)
				|| !IsReflectionArgumentCompatible(parameters[4].ParameterType, target)
				|| !IsReflectionArgumentCompatible(parameters[5].ParameterType, card))
			{
				return false;
			}

			object? value = method.Invoke(null, args);
			if (value is decimal decimalValue)
			{
				result = decimalValue;
				return true;
			}
		}
		catch
		{
		}

		return false;
	}

	private static bool IsReflectionArgumentCompatible(Type parameterType, object? value)
	{
		if (parameterType.IsByRef)
		{
			return true;
		}
		if (value == null)
		{
			return !parameterType.IsValueType || Nullable.GetUnderlyingType(parameterType) != null;
		}
		return parameterType.IsInstanceOfType(value);
	}

	private static bool TryGetHookedMoveAmountPreview(CardModel card, CardExtraEffect effect, int baseAmount, Creature? target, out decimal preview)
	{
		preview = baseAmount;

		CardModel modifierCard = CardEditorBorrowedEffectSourceDamageHelper.ResolveRuntimePlayedCard(card) ?? card;
		Player? owner = modifierCard.Owner;
		Creature? ownerCreature = owner?.Creature;
		CombatState? combatState = modifierCard.GetConcreteCombatState();
		if (!ShouldRunGlobalHooks(modifierCard) || ownerCreature == null || combatState == null)
		{
			return false;
		}

		bool isOstyAttack = effect.Kind == CardExtraEffectKind.OstyAction
			&& effect.OstyAction is CardExtraEffectOstyAction.Attack or CardExtraEffectOstyAction.AttackAll;

		if (effect.Kind == CardExtraEffectKind.DealDamage || isOstyAttack)
		{
			// Self/ally-directed damage is not an attack: the runtime deals it flat, so the preview must
			// not pick up Strength/Vulnerable/Weak. Skip the damage hook and let the enchanted base show.
			if (!isOstyAttack
				&& GetEffectivePreviewTarget(modifierCard, effect.Target) is CardExtraEffectTarget.Self
					or CardExtraEffectTarget.AnyPlayer or CardExtraEffectTarget.AnyAlly or CardExtraEffectTarget.AllAllies)
			{
				return false;
			}

			if (owner?.RunState == null)
			{
				return false;
			}

			Creature? effectiveDealer = isOstyAttack ? owner.Osty : ownerCreature;
			if (effectiveDealer == null)
			{
				return false;
			}

			CardExtraEffectTarget requestedTarget = isOstyAttack && effect.OstyAction == CardExtraEffectOstyAction.AttackAll
				? CardExtraEffectTarget.AllEnemies
				: effect.Target;
			CardExtraEffectTarget effectiveRequestedTarget = GetEffectivePreviewTarget(modifierCard, requestedTarget);
			CardPreviewMode visualPreviewMode = CardEditorCardVisualPreviewContext.GetPreviewMode(modifierCard);
			Creature? selfTarget = isOstyAttack ? owner.Osty : ownerCreature;
			if (ShouldResolveConcreteMovePreviewTargets(modifierCard, requestedTarget, target, visualPreviewMode))
			{
				IReadOnlyList<Creature?> previewTargets = ResolvePreviewTargetsForEffect(combatState, ownerCreature, modifierCard, target, requestedTarget, selfTarget);
				if (TryGetUniformHookedPreview(previewTargets, previewTarget =>
					Hook.ModifyDamage(owner.RunState, combatState, previewTarget, effectiveDealer, baseAmount, ValueProp.Move, modifierCard, cardPlay: null, ModifyDamageHookType.All, CardPreviewMode.Normal, out IEnumerable<AbstractModel> _), out preview))
				{
					return true;
				}
			}

			Creature? fallbackTarget = effectiveRequestedTarget switch
			{
				CardExtraEffectTarget.Self => selfTarget,
				CardExtraEffectTarget.Target => target,
				_ => null
			};
			CardPreviewMode previewMode = ShouldUseMultiCreatureMovePreview(modifierCard, requestedTarget, visualPreviewMode)
				? CardPreviewMode.MultiCreatureTargeting
				: CardPreviewMode.Normal;
			preview = Hook.ModifyDamage(owner.RunState, combatState, fallbackTarget, effectiveDealer, baseAmount, ValueProp.Move, modifierCard, cardPlay: null, ModifyDamageHookType.All, previewMode, out IEnumerable<AbstractModel> _);
			return true;
		}

		if (effect.Kind == CardExtraEffectKind.GainBlock)
		{
			IReadOnlyList<Creature?> previewTargets = ResolvePreviewTargetsForEffect(combatState, ownerCreature, modifierCard, target, effect.Target, ownerCreature);
			if (TryGetUniformHookedPreview(previewTargets, previewTarget =>
				previewTarget != null
					? Hook.ModifyBlock(combatState, previewTarget, baseAmount, ValueProp.Move, modifierCard, cardPlay: null, out IEnumerable<AbstractModel> _)
					: baseAmount, out preview))
			{
				return true;
			}

			Creature? fallbackTarget = effect.Target == CardExtraEffectTarget.Self
				? ownerCreature
				: effect.Target == CardExtraEffectTarget.Target
					? target
					: null;
			if (fallbackTarget == null)
			{
				return false;
			}

			preview = Hook.ModifyBlock(combatState, fallbackTarget, baseAmount, ValueProp.Move, modifierCard, cardPlay: null, out IEnumerable<AbstractModel> _);
			return true;
		}

		return false;
	}

	private static bool ShouldResolveConcreteMovePreviewTargets(CardModel card, CardExtraEffectTarget requestedTarget, Creature? hoveredTarget, CardPreviewMode previewMode)
	{
		CardExtraEffectTarget effectiveTarget = GetEffectivePreviewTarget(card, requestedTarget);
		return effectiveTarget switch
		{
			CardExtraEffectTarget.Self => true,
			CardExtraEffectTarget.AllEnemies or CardExtraEffectTarget.RandomEnemy => previewMode == CardPreviewMode.MultiCreatureTargeting,
			CardExtraEffectTarget.OtherEnemies => previewMode == CardPreviewMode.MultiCreatureTargeting && hoveredTarget != null,
			CardExtraEffectTarget.AllAllies => previewMode == CardPreviewMode.MultiCreatureTargeting,
			CardExtraEffectTarget.AnyPlayer => hoveredTarget != null,
			CardExtraEffectTarget.AnyAlly => hoveredTarget != null,
			_ => hoveredTarget != null
		};
	}

	private static bool ShouldUseMultiCreatureMovePreview(CardModel card, CardExtraEffectTarget requestedTarget, CardPreviewMode previewMode)
	{
		if (previewMode != CardPreviewMode.MultiCreatureTargeting)
		{
			return false;
		}

		CardExtraEffectTarget effectiveTarget = GetEffectivePreviewTarget(card, requestedTarget);
		return effectiveTarget is CardExtraEffectTarget.AllEnemies or CardExtraEffectTarget.RandomEnemy;
	}

	private static bool TryGetUniformHookedPreview(IReadOnlyList<Creature?> targets, Func<Creature?, decimal> previewForTarget, out decimal preview)
	{
		preview = 0m;
		if (targets.Count == 0)
		{
			return false;
		}

		bool found = false;
		int firstInt = 0;
		foreach (Creature? target in targets)
		{
			if (target == null)
			{
				continue;
			}

			decimal candidate = previewForTarget(target);
			int candidateInt = (int)candidate;
			if (!found)
			{
				found = true;
				firstInt = candidateInt;
				preview = candidate;
				continue;
			}

			if (candidateInt != firstInt)
			{
				return false;
			}
		}

		return found;
	}

	private static IReadOnlyList<Creature?> ResolvePreviewTargetsForEffect(
		CombatState combatState,
		Creature ownerCreature,
		CardModel card,
		Creature? hoveredTarget,
		CardExtraEffectTarget requestedTarget,
		Creature? selfTarget)
	{
		CardExtraEffectTarget effectiveTarget = GetEffectivePreviewTarget(card, requestedTarget);
		switch (effectiveTarget)
		{
			case CardExtraEffectTarget.Self:
				return selfTarget != null && selfTarget.IsAlive ? new Creature?[] { selfTarget } : Array.Empty<Creature?>();
			case CardExtraEffectTarget.AllEnemies:
			case CardExtraEffectTarget.RandomEnemy:
				return combatState.GetOpponentsOf(ownerCreature).Where(c => c != null && c.IsAlive).Cast<Creature?>().ToList();
			case CardExtraEffectTarget.OtherEnemies:
			{
				IEnumerable<Creature> source = hoveredTarget != null
					? combatState.GetTeammatesOf(hoveredTarget)
					: combatState.GetOpponentsOf(ownerCreature);
				return source.Where(c => c != null && c.IsAlive && !ReferenceEquals(c, hoveredTarget)).Cast<Creature?>().ToList();
			}
			case CardExtraEffectTarget.EventTarget:
				return hoveredTarget != null && hoveredTarget.IsAlive ? new Creature?[] { hoveredTarget } : Array.Empty<Creature?>();
			case CardExtraEffectTarget.AllAllies:
				return ResolveFriendlyGroupTargets(combatState, ownerCreature, includeSelf: true).Cast<Creature?>().ToList();
			case CardExtraEffectTarget.AnyPlayer:
				if (hoveredTarget != null && IsFriendlyTarget(ownerCreature, hoveredTarget, includeSelf: true))
				{
					return new Creature?[] { hoveredTarget };
				}
				return ownerCreature.IsAlive ? new Creature?[] { ownerCreature } : Array.Empty<Creature?>();
			case CardExtraEffectTarget.AnyAlly:
				if (hoveredTarget != null && IsFriendlyTarget(ownerCreature, hoveredTarget, includeSelf: false))
				{
					return new Creature?[] { hoveredTarget };
				}
				return ResolveFriendlyGroupTargets(combatState, ownerCreature, includeSelf: false).Take(1).Cast<Creature?>().ToList();
			default:
				return hoveredTarget != null && hoveredTarget.IsAlive ? new Creature?[] { hoveredTarget } : Array.Empty<Creature?>();
		}
	}

	private static CardExtraEffectTarget GetEffectivePreviewTarget(CardModel card, CardExtraEffectTarget requestedTarget)
	{
		if (requestedTarget != CardExtraEffectTarget.Target || card == null)
		{
			return requestedTarget;
		}

		return card.TargetType switch
		{
			TargetType.Self => CardExtraEffectTarget.Self,
			TargetType.RandomEnemy => CardExtraEffectTarget.RandomEnemy,
			TargetType.AllEnemies => CardExtraEffectTarget.AllEnemies,
			TargetType.AnyAlly => CardExtraEffectTarget.AnyAlly,
			TargetType.AllAllies => CardExtraEffectTarget.AllAllies,
			TargetType.AnyPlayer => CardExtraEffectTarget.AnyPlayer,
			_ => requestedTarget
		};
	}

	private static bool TryResolveAppliedPowerPreviewModel(CardExtraEffect effect, out PowerModel? canonicalPower, out bool displayAbsoluteAmount)
	{
		displayAbsoluteAmount = false;
		canonicalPower = effect.Kind switch
		{
			CardExtraEffectKind.GainStrength => ModelDb.Power<StrengthPower>(),
			CardExtraEffectKind.LoseStrength => ModelDb.Power<StrengthPower>(),
			CardExtraEffectKind.GainDexterity => ModelDb.Power<DexterityPower>(),
			CardExtraEffectKind.LoseDexterity => ModelDb.Power<DexterityPower>(),
			CardExtraEffectKind.GainFocus => ModelDb.Power<FocusPower>(),
			CardExtraEffectKind.LoseFocus => ModelDb.Power<FocusPower>(),
			CardExtraEffectKind.ApplyWeak => ModelDb.Power<WeakPower>(),
			CardExtraEffectKind.ApplyFrail => ModelDb.Power<FrailPower>(),
			CardExtraEffectKind.ApplyVulnerable => ModelDb.Power<VulnerablePower>(),
			CardExtraEffectKind.ApplyPoison => ModelDb.Power<PoisonPower>(),
			CardExtraEffectKind.ApplyDoom => ModelDb.Power<DoomPower>(),
			CardExtraEffectKind.ApplyConstrict => ModelDb.Power<ConstrictPower>(),
			CardExtraEffectKind.GainArtifact => ModelDb.Power<ArtifactPower>(),
			CardExtraEffectKind.GainThorns => ModelDb.Power<ThornsPower>(),
			CardExtraEffectKind.GainRegen => ModelDb.Power<RegenPower>(),
			CardExtraEffectKind.GainPlating => ModelDb.Power<PlatingPower>(),
			CardExtraEffectKind.GainIntangible => ModelDb.Power<IntangiblePower>(),
			CardExtraEffectKind.GainBuffer => ModelDb.Power<BufferPower>(),
			CardExtraEffectKind.GainVigor => ModelDb.Power<VigorPower>(),
			CardExtraEffectKind.GainBlur => ModelDb.Power<BlurPower>(),
			CardExtraEffectKind.GainRitual => ModelDb.Power<RitualPower>(),
			_ => null
		};

		if (effect.Kind is CardExtraEffectKind.LoseStrength or CardExtraEffectKind.LoseDexterity or CardExtraEffectKind.LoseFocus)
		{
			displayAbsoluteAmount = true;
		}

		if (canonicalPower != null)
		{
			return true;
		}

		if (effect.Kind == CardExtraEffectKind.ApplyPower)
		{
			return TryResolveConfiguredPowerModel(effect.PowerId, out canonicalPower) && canonicalPower != null;
		}

		return false;
	}

	private static bool ShouldRunGlobalHooks(CardModel card)
	{
		if (card == null || card.GetConcreteCombatState() == null)
		{
			return false;
		}

		PileType? pileType = card.Pile?.Type;
		if (pileType == PileType.Hand || pileType == PileType.Play)
		{
			return true;
		}

		return card.UpgradePreviewType == CardUpgradePreviewType.Combat;
	}

	private static string ApplyTiming(string line, CardExtraEffectTiming timing, int turns)
	{
		if (timing == CardExtraEffectTiming.Immediate || turns < 0)
		{
			return line;
		}

		string prefix = timing switch
		{
			CardExtraEffectTiming.StartOfTurn => turns == 0
				? CardEditorLoc.T("cardText.timing.start.eachTurnCombatPrefix", "At the start of each turn this combat: ")
				: (turns == 1
					? CardEditorLoc.T("cardText.timing.start.nextTurnPrefix", "At the start of your next turn: ")
					: CardEditorLoc.F("cardText.timing.start.nextTurnsPrefix", $"At the start of your next {turns.ToString(CultureInfo.InvariantCulture)} turns: ", ("Turns", turns))),
			CardExtraEffectTiming.EndOfTurn => turns == 0
				? CardEditorLoc.T("cardText.timing.end.startingNextTurnEachCombatPrefix", "Starting next turn, at the end of each turn this combat: ")
				: (turns == 1
					? CardEditorLoc.T("cardText.timing.end.nextTurnPrefix", "At the end of your next turn: ")
					: CardEditorLoc.F("cardText.timing.end.nextTurnsPrefix", $"At the end of your next {turns.ToString(CultureInfo.InvariantCulture)} turns: ", ("Turns", turns))),
			CardExtraEffectTiming.EndOfThisTurn => turns == 0
				? CardEditorLoc.T("cardText.timing.endEachCombatPrefix", "At the end of each turn this combat: ")
				: (turns == 1
					? CardEditorLoc.T("cardText.timing.endThisTurnPrefix", "At the end of this turn: ")
					: (turns == 2
						? CardEditorLoc.T("cardText.timing.endThisTurnAndNextPrefix", "At the end of this turn and your next turn: ")
						: CardEditorLoc.F("cardText.timing.endThisTurnAndNextTurnsPrefix", $"At the end of this turn and your next {(turns - 1).ToString(CultureInfo.InvariantCulture)} turns: ", ("Turns", turns - 1)))),
			CardExtraEffectTiming.StartOfEnemyTurn => turns == 0
				? CardEditorLoc.T("cardText.timing.enemyStart.eachTurnCombatPrefix", "At the start of each enemy turn this combat: ")
				: (turns == 1
					? CardEditorLoc.T("cardText.timing.enemyStart.nextTurnPrefix", "At the start of the next enemy turn: ")
					: CardEditorLoc.F("cardText.timing.enemyStart.nextTurnsPrefix", $"At the start of the next {turns.ToString(CultureInfo.InvariantCulture)} enemy turns: ", ("Turns", turns))),
			CardExtraEffectTiming.EndOfEnemyTurn => turns == 0
				? CardEditorLoc.T("cardText.timing.enemyEnd.startingNextTurnEachCombatPrefix", "Starting next enemy turn, at the end of each enemy turn this combat: ")
				: (turns == 1
					? CardEditorLoc.T("cardText.timing.enemyEnd.nextTurnPrefix", "At the end of the next enemy turn: ")
					: CardEditorLoc.F("cardText.timing.enemyEnd.nextTurnsPrefix", $"At the end of the next {turns.ToString(CultureInfo.InvariantCulture)} enemy turns: ", ("Turns", turns))),
			CardExtraEffectTiming.StartOfAnyTurn => turns == 0
				? CardEditorLoc.T("cardText.timing.anyStart.eachTurnCombatPrefix", "At the start of each turn this combat: ")
				: (turns == 1
					? CardEditorLoc.T("cardText.timing.anyStart.nextTurnPrefix", "At the start of the next turn: ")
					: CardEditorLoc.F("cardText.timing.anyStart.nextTurnsPrefix", $"At the start of the next {turns.ToString(CultureInfo.InvariantCulture)} turns: ", ("Turns", turns))),
			CardExtraEffectTiming.EndOfAnyTurn => turns == 0
				? CardEditorLoc.T("cardText.timing.anyEnd.startingNextTurnEachCombatPrefix", "Starting next turn, at the end of each turn this combat: ")
				: (turns == 1
					? CardEditorLoc.T("cardText.timing.anyEnd.nextTurnPrefix", "At the end of the next turn: ")
					: CardEditorLoc.F("cardText.timing.anyEnd.nextTurnsPrefix", $"At the end of the next {turns.ToString(CultureInfo.InvariantCulture)} turns: ", ("Turns", turns))),
			CardExtraEffectTiming.EndOfThisAnyTurn => turns == 0
				? CardEditorLoc.T("cardText.timing.anyEndEachCombatPrefix", "At the end of each turn this combat: ")
				: (turns == 1
					? CardEditorLoc.T("cardText.timing.anyEndThisTurnPrefix", "At the end of this turn: ")
					: (turns == 2
						? CardEditorLoc.T("cardText.timing.anyEndThisTurnAndNextPrefix", "At the end of this turn and the next turn: ")
						: CardEditorLoc.F("cardText.timing.anyEndThisTurnAndNextTurnsPrefix", $"At the end of this turn and the next {(turns - 1).ToString(CultureInfo.InvariantCulture)} turns: ", ("Turns", turns - 1)))),
			_ => string.Empty
		};

		return string.IsNullOrEmpty(prefix) ? line : prefix + line;
	}

	private static string BuildEnergyIcons(CardModel? card, int amount)
	{
		string icon = BuildEnergyIcon(card);
		if (amount <= 0 || amount >= 4)
		{
			return amount.ToString(CultureInfo.InvariantCulture) + icon;
		}
		return string.Concat(Enumerable.Repeat(icon, amount));
	}

	private static string BuildStarIcons(int amount)
	{
		string icon = StarIconsFormatter.starIconSprite;
		if (amount <= 0 || amount >= 4)
		{
			return amount.ToString(CultureInfo.InvariantCulture) + icon;
		}
		return string.Concat(Enumerable.Repeat(icon, amount));
	}

	private static string PowerTitle(string powerName, string fallback)
	{
		if (string.IsNullOrWhiteSpace(powerName))
		{
			return fallback;
		}

		try
		{
			string key = powerName.Trim().ToUpperInvariant() + "_POWER.title";
			if (LocString.Exists("powers", key))
			{
				string? title = new LocString("powers", key).GetFormattedText();
				if (!string.IsNullOrWhiteSpace(title))
				{
					return title!;
				}
			}
		}
		catch
		{
		}

		return fallback;
	}

	private static string OrbTitle(string orbName, string fallback)
	{
		if (string.IsNullOrWhiteSpace(orbName))
		{
			return fallback;
		}

		try
		{
			string key = orbName.Trim().ToUpperInvariant() + "_ORB.title";
			if (LocString.Exists("orbs", key))
			{
				string? title = new LocString("orbs", key).GetFormattedText();
				if (!string.IsNullOrWhiteSpace(title))
				{
					return title!;
				}
			}
		}
		catch
		{
		}

		return fallback;
	}

	private static string GetOrbTypeTitle(CardExtraEffectOrbType type)
	{
		return type switch
		{
			CardExtraEffectOrbType.Lightning => OrbTitle("Lightning", "Lightning"),
			CardExtraEffectOrbType.Frost => OrbTitle("Frost", "Frost"),
			CardExtraEffectOrbType.Dark => OrbTitle("Dark", "Dark"),
			CardExtraEffectOrbType.Plasma => OrbTitle("Plasma", "Plasma"),
			CardExtraEffectOrbType.Glass => OrbTitle("Glass", "Glass"),
			_ => string.Empty
		};
	}

	internal static bool IsLegacyOrbChannelKind(CardExtraEffectKind kind)
	{
		return kind is CardExtraEffectKind.ChannelLightning
			or CardExtraEffectKind.ChannelFrost
			or CardExtraEffectKind.ChannelDark
			or CardExtraEffectKind.ChannelPlasma
			or CardExtraEffectKind.ChannelGlass
			or CardExtraEffectKind.ChannelRandomOrb;
	}

	internal static CardExtraEffect? NormalizeLegacyOrbChannelEffect(CardExtraEffect? effect)
	{
		if (effect == null || !IsLegacyOrbChannelKind(effect.Kind))
		{
			return effect;
		}

		CardExtraEffect normalized = CloneEffect(effect);
		normalized.Kind = CardExtraEffectKind.OrbAction;
		normalized.OrbAction = CardExtraEffectOrbAction.Channel;
		normalized.OrbSelection = CardExtraEffectOrbSelection.Leftmost;
		normalized.OrbFollowUp = CardExtraEffectOrbFollowUp.None;
		normalized.OrbType = effect.Kind switch
		{
			CardExtraEffectKind.ChannelLightning => CardExtraEffectOrbType.Lightning,
			CardExtraEffectKind.ChannelFrost => CardExtraEffectOrbType.Frost,
			CardExtraEffectKind.ChannelDark => CardExtraEffectOrbType.Dark,
			CardExtraEffectKind.ChannelPlasma => CardExtraEffectOrbType.Plasma,
			CardExtraEffectKind.ChannelGlass => CardExtraEffectOrbType.Glass,
			_ => CardExtraEffectOrbType.Any
		};
		return normalized;
	}

	internal static bool IsLegacyEvokeOrbsKind(CardExtraEffectKind kind)
	{
		return kind == CardExtraEffectKind.EvokeOrbs;
	}

	internal static CardExtraEffect? NormalizeLegacyEvokeOrbsEffect(CardExtraEffect? effect)
	{
		if (effect == null || !IsLegacyEvokeOrbsKind(effect.Kind))
		{
			return effect;
		}

		CardExtraEffect normalized = CloneEffect(effect);
		normalized.Kind = CardExtraEffectKind.OrbAction;
		normalized.OrbAction = CardExtraEffectOrbAction.Evoke;
		normalized.OrbType = CardExtraEffectOrbType.Any;
		normalized.OrbSelection = CardExtraEffectOrbSelection.Leftmost;
		normalized.OrbFollowUp = CardExtraEffectOrbFollowUp.None;
		return normalized;
	}

	internal static bool IsLegacySelfPileAutoKind(CardExtraEffectKind kind)
	{
		return kind is CardExtraEffectKind.AutoPlaySelfFromPile or CardExtraEffectKind.AutoDrawSelfFromPile;
	}

	internal static bool IsSelfPileAutoEffectKind(CardExtraEffectKind kind)
		=> kind is CardExtraEffectKind.AutoPlaySelfFromPile
			or CardExtraEffectKind.AutoDrawSelfFromPile
			or CardExtraEffectKind.ConditionalAutoPlayFromPile
			or CardExtraEffectKind.ConditionalAutoDrawFromPile
			or CardExtraEffectKind.ConditionalAutoRunEffects;

	internal static CardExtraEffect? NormalizeSelfPileAutoEffect(CardExtraEffect? effect)
	{
		if (effect == null)
		{
			return null;
		}

		if (effect.Kind is not CardExtraEffectKind.AutoPlaySelfFromPile
			and not CardExtraEffectKind.AutoDrawSelfFromPile
			and not CardExtraEffectKind.ConditionalAutoPlayFromPile
			and not CardExtraEffectKind.ConditionalAutoDrawFromPile
			and not CardExtraEffectKind.ConditionalAutoRunEffects)
		{
			return effect;
		}

		CardExtraEffect normalized = CloneEffect(effect);
		if (effect.Kind == CardExtraEffectKind.AutoPlaySelfFromPile)
		{
			normalized.Kind = CardExtraEffectKind.ConditionalAutoPlayFromPile;
			normalized.ScaleMode = CardExtraEffectScaleMode.None;
			normalized.CountComparison = CardExtraEffectCountComparison.None;
			normalized.CountConditionAmount = 0;
			normalized.ConditionProgressDisplay = CardExtraEffectConditionProgressDisplay.Hidden;
			normalized.Amount = 1;
			normalized.AmountIsX = false;
			normalized.AmountXPlus = 0;
			return normalized;
		}

		if (effect.Kind == CardExtraEffectKind.AutoDrawSelfFromPile)
		{
			normalized.Kind = CardExtraEffectKind.ConditionalAutoDrawFromPile;
			normalized.ScaleMode = CardExtraEffectScaleMode.None;
			normalized.CountComparison = CardExtraEffectCountComparison.None;
			normalized.CountConditionAmount = 0;
			normalized.ConditionProgressDisplay = CardExtraEffectConditionProgressDisplay.Hidden;
			normalized.Amount = 1;
			normalized.AmountIsX = false;
			normalized.AmountXPlus = 0;
			return normalized;
		}

		if (normalized.ScaleMode != CardExtraEffectScaleMode.None
			&& normalized.CountComparison == CardExtraEffectCountComparison.None
			&& normalized.CountConditionAmount <= 0)
		{
			normalized.ScaleMode = CardExtraEffectScaleMode.ConditionOnly;
			normalized.CountComparison = CardExtraEffectCountComparison.AtLeast;
			normalized.CountConditionAmount = Math.Max(1, normalized.Amount);
			normalized.Amount = 1;
			normalized.AmountIsX = false;
			normalized.AmountXPlus = 0;
		}

		return normalized;
	}

	private static string BuildSuffixPart(string? suffix)
	{
		string period = CardEditorLoc.T("cardText.punctuation.period", ".");

		if (string.IsNullOrWhiteSpace(suffix))
		{
			return CardEditorLoc.F("cardText.suffix.noSuffix", period, ("Period", period));
		}

		return CardEditorLoc.F("cardText.suffix.withPeriod", $" {suffix}{period}", ("Suffix", suffix), ("Period", period));
	}

