	private static int ResolveRepeatCount(CardPlay cardPlay, CardExtraEffect effect)
	{
		if (effect == null || effect.GrantToCard || !SupportsRepeat(effect.Kind))
		{
			return 1;
		}

		int baseRepeat = ResolveBaseRepeatCount(cardPlay, effect);
		if (effect.ScaleMode == CardExtraEffectScaleMode.RepeatByCount)
		{
			CardModel? card = cardPlay?.Card;
			CombatState? combatState = card.GetConcreteCombatState();
			Creature? ownerCreature = card?.Owner?.Creature;
			if (combatState != null && ownerCreature != null)
			{
				int rawCount = Math.Max(0, GetHistoryCountMultiplier(combatState, ownerCreature, cardPlay, effect, card));
				return ComputeRepeatByCountTotal(effect, baseRepeat, rawCount, out _);
			}
			if (RepeatScalingReplacesBaseEffective(effect))
			{
				// Count source unavailable means a total of zero, not a free base execution.
				return 0;
			}
		}

		return baseRepeat;
	}

	// The self-result dynamic repeat loop must keep its bootstrap hit: its count is always 0
	// before the first hit, so replacing the base would make the effect permanently unable to fire.
	private static bool RepeatScalingReplacesBaseEffective(CardExtraEffect effect)
		=> effect.RepeatScalingReplacesBase && !UsesCurrentEffectResultRepeat(effect);

	// Single source of truth for the Repeat-by-Count total, shared by execution and card text
	// so the displayed repeat count can never diverge from what actually runs.
	private static int ComputeRepeatByCountTotal(CardExtraEffect effect, int baseRepeat, int rawCount, out bool countPasses)
	{
		bool replacesBase = RepeatScalingReplacesBaseEffective(effect);
		countPasses = effect.CountComparison == CardExtraEffectCountComparison.None || DoesCountConditionPass(rawCount, effect);
		if (!countPasses)
		{
			return replacesBase ? 0 : baseRepeat;
		}

		int rawSteps = rawCount / ResolveHistoryScalingCountStep(effect);
		int scaledRepeats = rawSteps * ResolveRepeatScalingExtraTimes(effect);
		long totalRepeats = replacesBase ? scaledRepeats : (long)baseRepeat + scaledRepeats;
		return totalRepeats >= 99 ? 99 : totalRepeats <= 0 ? 0 : (int)totalRepeats;
	}

	private static int ResolveBaseRepeatCount(CardPlay? cardPlay, CardExtraEffect effect)
	{
		if (effect.RepeatIsX)
		{
			return Math.Clamp(cardPlay != null ? ResolveXAmountWithPlus(cardPlay, effect.RepeatCount) : Math.Max(0, effect.RepeatCount), 0, 99);
		}

		if (effect.RepeatCount < 0)
		{
			return 0;
		}

		int count = effect.RepeatCount <= 0 ? 1 : effect.RepeatCount;
		return Math.Clamp(count, 1, 99);
	}

	private static string ApplyRepeatSuffix(CardModel? card, string baseLine, CardExtraEffect effect, int upgradeHighlightComparison = 0)
	{
		if (string.IsNullOrWhiteSpace(baseLine) || effect == null || effect.GrantToCard || !SupportsRepeat(effect.Kind))
		{
			return baseLine;
		}

		bool scalesRepeat = effect.ScaleMode == CardExtraEffectScaleMode.RepeatByCount;
		bool hasRepeat = scalesRepeat || effect.RepeatIsX || effect.RepeatCount > 1;
		if (!hasRepeat)
		{
			return baseLine;
		}

		int baseRepeat = ResolveBaseRepeatCount(cardPlay: null, effect);
		int repeatComparison = upgradeHighlightComparison;
		int? resolvedRepeat = null;
		CombatState? repeatCombatState = scalesRepeat ? card.GetConcreteCombatState() : null;
		Creature? repeatOwnerCreature = repeatCombatState != null ? card.TryGetOwnerCreature() : null;
		if (scalesRepeat && repeatCombatState != null && repeatOwnerCreature != null)
		{
			int rawCount = Math.Max(0, GetHistoryCountMultiplier(repeatCombatState, repeatOwnerCreature, cardPlay: null, effect, card));
			resolvedRepeat = ComputeRepeatByCountTotal(effect, baseRepeat, rawCount, out bool countPasses);
			if (countPasses && repeatComparison == 0)
			{
				repeatComparison = resolvedRepeat.Value.CompareTo(baseRepeat);
			}
		}

		if (!resolvedRepeat.HasValue && scalesRepeat && RepeatScalingReplacesBaseEffective(effect))
		{
			// Out of combat there is no count to resolve and no base hit to describe;
			// the scaling rule line carries the "X times per ..." wording instead.
			return baseLine;
		}

		string repeatSuffix;
		if (resolvedRepeat.HasValue)
		{
			string timesText = resolvedRepeat.Value.ToString(CultureInfo.InvariantCulture);
			if (repeatComparison != 0)
			{
				timesText = StsTextUtilities.HighlightChangeText(timesText, repeatComparison);
			}
			repeatSuffix = resolvedRepeat.Value == 1
				? CardEditorLoc.T("cardText.repeat.once", "once")
				: CardEditorLoc.F("cardText.repeat.times", $"{timesText} times", ("Times", timesText));
		}
		else if (effect.RepeatIsX)
		{
			string timesText = FormatXPlusText(effect.RepeatCount);
			if (upgradeHighlightComparison != 0)
			{
				timesText = StsTextUtilities.HighlightChangeText(timesText, upgradeHighlightComparison);
			}

			repeatSuffix = CardEditorLoc.F("cardText.repeat.xPlusTimes", $"{timesText} times", ("Times", timesText));
		}
		else if (effect.RepeatCount == 2)
		{
			repeatSuffix = CardEditorLoc.T("cardText.repeat.twice", "twice");
		}
		else if (scalesRepeat && baseRepeat == 1)
		{
			repeatSuffix = CardEditorLoc.T("cardText.repeat.once", "once");
		}
		else
		{
			string timesText = baseRepeat.ToString(CultureInfo.InvariantCulture);
			if (upgradeHighlightComparison != 0)
			{
				timesText = StsTextUtilities.HighlightChangeText(timesText, upgradeHighlightComparison);
			}

			repeatSuffix = CardEditorLoc.F("cardText.repeat.times", $"{timesText} times", ("Times", timesText));
		}

		string[] split = baseLine.Split('\n', 2);
		string first = split[0];

		int lastSentencePunctuation = Math.Max(
			Math.Max(first.LastIndexOf('.'), first.LastIndexOf('。')),
			Math.Max(
				Math.Max(first.LastIndexOf('!'), first.LastIndexOf('！')),
				Math.Max(first.LastIndexOf('?'), first.LastIndexOf('？'))));
		first = lastSentencePunctuation >= 0
			? first.Insert(lastSentencePunctuation, " " + repeatSuffix)
			: first + " " + repeatSuffix;

		return split.Length == 2 ? first + "\n" + split[1] : first;
	}

	private static string ApplyEffectUseLimitSuffix(CardModel? card, string baseLine, CardExtraEffect effect, bool isUpgradePreview)
	{
		if (string.IsNullOrWhiteSpace(baseLine)
			|| effect == null
			|| effect.AutoPlayLoopLimit <= 0)
		{
			return baseLine;
		}

		int limit = Math.Clamp(effect.AutoPlayLoopLimit, 1, 999);
		string suffix = TryBuildLiveEffectUseLimitSuffix(card, effect, limit, isUpgradePreview, out string liveSuffix)
			? liveSuffix
			: BuildStaticEffectUseLimitSuffix(effect, limit);

		return InsertFirstLineSuffix(baseLine, suffix);
	}

	private static bool TryBuildLiveEffectUseLimitSuffix(
		CardModel? card,
		CardExtraEffect effect,
		int limit,
		bool isUpgradePreview,
		out string suffix)
	{
		suffix = string.Empty;
		if (card == null || isUpgradePreview)
		{
			return false;
		}

		CombatState? combatState = null;
		try
		{
			combatState = card.GetConcreteCombatState();
		}
		catch
		{
		}

		if (combatState == null)
		{
			return false;
		}

		int remaining = CardEditorAutoPlayLoopGuard.GetRemainingEffectUses(combatState, card.Owner, card, effect);
		if (remaining < 0)
		{
			return false;
		}

		string remainingText = StsTextUtilities.HighlightChangeText(
			remaining.ToString(CultureInfo.InvariantCulture),
			remaining.CompareTo(limit));
		string unitText = remaining == 1
			? CardEditorLoc.T("cardText.autoPlayLoopLimit.useSingular", "use")
			: CardEditorLoc.T("cardText.autoPlayLoopLimit.usePlural", "uses");
		string scopeText = BuildUseLimitScopeText(effect.AutoPlayLoopScope);
		string windowText = BuildUseLimitLiveWindowText(effect.UseLimitWindow);

		suffix = CardEditorLoc.F(
			"cardText.effectUseLimit.left",
			$" (up to {remainingText} {scopeText}{unitText} left {windowText})",
			("Remaining", remainingText),
			("Scope", scopeText.TrimEnd()),
			("Unit", unitText),
			("Window", windowText));
		return true;
	}

	private static string BuildStaticEffectUseLimitSuffix(CardExtraEffect effect, int limit)
	{
		string limitText = limit.ToString(CultureInfo.InvariantCulture);
		string scopeText = BuildUseLimitScopeText(effect.AutoPlayLoopScope);
		string windowText = BuildUseLimitStaticWindowText(effect.UseLimitWindow);
		return CardEditorLoc.F(
			"cardText.effectUseLimit.static",
			$" (up to {limitText} {scopeText}uses {windowText})",
			("Limit", limitText),
			("Scope", scopeText.TrimEnd()),
			("Window", windowText));
	}

	private static string BuildUseLimitScopeText(CardExtraEffectAutoPlayLoopScope scope)
	{
		return scope switch
		{
			CardExtraEffectAutoPlayLoopScope.AllCopies => CardEditorLoc.T("cardText.effectUseLimit.scope.shared", "shared "),
			CardExtraEffectAutoPlayLoopScope.EquivalentEffect => CardEditorLoc.T("cardText.effectUseLimit.scope.equivalent", "equivalent "),
			CardExtraEffectAutoPlayLoopScope.Global => CardEditorLoc.T("cardText.effectUseLimit.scope.global", "global "),
			_ => string.Empty
		};
	}

	private static string BuildUseLimitLiveWindowText(CardExtraEffectUseLimitWindow window)
	{
		return window switch
		{
			CardExtraEffectUseLimitWindow.Combat => CardEditorLoc.T("cardText.effectUseLimit.window.thisCombat", "this combat"),
			CardExtraEffectUseLimitWindow.Run => CardEditorLoc.T("cardText.effectUseLimit.window.thisRun", "this run"),
			_ => CardEditorLoc.T("cardText.effectUseLimit.window.thisTurn", "this turn")
		};
	}

	private static string BuildUseLimitStaticWindowText(CardExtraEffectUseLimitWindow window)
	{
		return window switch
		{
			CardExtraEffectUseLimitWindow.Combat => CardEditorLoc.T("cardText.effectUseLimit.window.eachCombat", "each combat"),
			CardExtraEffectUseLimitWindow.Run => CardEditorLoc.T("cardText.effectUseLimit.window.perRun", "per run"),
			_ => CardEditorLoc.T("cardText.effectUseLimit.window.eachTurn", "each turn")
		};
	}

	private static string InsertFirstLineSuffix(string baseLine, string suffix)
	{
		string[] split = baseLine.Split('\n', 2);
		string first = split[0];
		int lastSentencePunctuation = Math.Max(
			Math.Max(first.LastIndexOf('.'), first.LastIndexOf('\u3002')),
			Math.Max(
				Math.Max(first.LastIndexOf('!'), first.LastIndexOf('\uFF01')),
				Math.Max(first.LastIndexOf('?'), first.LastIndexOf('\uFF1F'))));
		first = lastSentencePunctuation >= 0
			? first.Insert(lastSentencePunctuation, suffix)
			: first + suffix;

		return split.Length == 2 ? first + "\n" + split[1] : first;
	}

	private static string? GetConditionalBonusPowerText(CardExtraEffect effect)
	{
		string? powerName = effect?.Kind switch
		{
			CardExtraEffectKind.GainStrength or CardExtraEffectKind.LoseStrength => "Strength",
			CardExtraEffectKind.GainDexterity or CardExtraEffectKind.LoseDexterity => "Dexterity",
			CardExtraEffectKind.GainFocus or CardExtraEffectKind.LoseFocus => "Focus",
			CardExtraEffectKind.ApplyWeak or CardExtraEffectKind.RemoveWeak => "Weak",
			CardExtraEffectKind.ApplyFrail or CardExtraEffectKind.RemoveFrail => "Frail",
			CardExtraEffectKind.ApplyVulnerable or CardExtraEffectKind.RemoveVulnerable => "Vulnerable",
			CardExtraEffectKind.ApplyPoison or CardExtraEffectKind.RemovePoison => "Poison",
			CardExtraEffectKind.ApplyDoom or CardExtraEffectKind.RemoveDoom => "Doom",
			CardExtraEffectKind.ApplyConstrict or CardExtraEffectKind.RemoveConstrict => "Constrict",
			CardExtraEffectKind.GainArtifact or CardExtraEffectKind.RemoveArtifact => "Artifact",
			CardExtraEffectKind.GainThorns or CardExtraEffectKind.RemoveThorns => "Thorns",
			CardExtraEffectKind.GainRegen or CardExtraEffectKind.RemoveRegen => "Regen",
			CardExtraEffectKind.GainPlating or CardExtraEffectKind.RemovePlating => "Plating",
			CardExtraEffectKind.GainIntangible or CardExtraEffectKind.RemoveIntangible => "Intangible",
			CardExtraEffectKind.GainBuffer or CardExtraEffectKind.RemoveBuffer => "Buffer",
			CardExtraEffectKind.GainVigor or CardExtraEffectKind.RemoveVigor => "Vigor",
			CardExtraEffectKind.GainBlur or CardExtraEffectKind.RemoveBlur => "Blur",
			CardExtraEffectKind.GainRitual or CardExtraEffectKind.RemoveRitual => "Ritual",
			CardExtraEffectKind.ApplyPower or CardExtraEffectKind.RemovePower or CardExtraEffectKind.GainStatusEqualToStatus => ResolvePowerTitle(effect.PowerId),
			_ => null
		};

		return string.IsNullOrWhiteSpace(powerName) ? null : $"[gold]{powerName}[/gold]";
	}

	private static string BuildConditionalBonusActionText(CardModel? card, CardExtraEffect effect, int bonus)
	{
		int magnitude = Math.Abs(bonus);
		string amountText = magnitude.ToString(CultureInfo.InvariantCulture);
		string direction = bonus > 0 ? "more" : "less";
		string moreOrLess = bonus > 0
			? CardEditorLoc.T("cardText.conditional.more", "more")
			: CardEditorLoc.T("cardText.conditional.less", "less");

		string? powerText = GetConditionalBonusPowerText(effect);
		return effect.Kind switch
		{
			CardExtraEffectKind.DealDamage or CardExtraEffectKind.CardDealsExtraDamage => FormatConditionalBonusAction(
				$"cardText.conditional.action.damage.{direction}",
				$"deal {amountText} {moreOrLess} damage",
				("Amount", amountText)),
			CardExtraEffectKind.GainBlock => FormatConditionalBonusAction(
				$"cardText.conditional.action.gainBlock.{direction}",
				$"gain {amountText} {moreOrLess} [gold]Block[/gold]",
				("Amount", amountText)),
			CardExtraEffectKind.RemoveBlock => FormatConditionalBonusAction(
				$"cardText.conditional.action.removeBlock.{direction}",
				$"remove {amountText} {moreOrLess} [gold]Block[/gold]",
				("Amount", amountText)),
			CardExtraEffectKind.Heal => FormatConditionalBonusAction(
				$"cardText.conditional.action.heal.{direction}",
				$"heal {amountText} {moreOrLess} HP",
				("Amount", amountText)),
			CardExtraEffectKind.LoseHp => FormatConditionalBonusAction(
				$"cardText.conditional.action.loseHp.{direction}",
				$"lose {amountText} {moreOrLess} HP",
				("Amount", amountText)),
			CardExtraEffectKind.GainMaxHp => FormatConditionalBonusAction(
				$"cardText.conditional.action.gainMaxHp.{direction}",
				$"gain {amountText} {moreOrLess} Max HP",
				("Amount", amountText)),
			CardExtraEffectKind.LoseMaxHp => FormatConditionalBonusAction(
				$"cardText.conditional.action.loseMaxHp.{direction}",
				$"lose {amountText} {moreOrLess} Max HP",
				("Amount", amountText)),
			CardExtraEffectKind.GainEnergy => FormatConditionalBonusAction(
				$"cardText.conditional.action.gainEnergy.{direction}",
				$"gain {BuildEnergyIcons(card, magnitude)} {moreOrLess}",
				("Amount", BuildEnergyIcons(card, magnitude))),
			CardExtraEffectKind.LoseEnergy => FormatConditionalBonusAction(
				$"cardText.conditional.action.loseEnergy.{direction}",
				$"lose {BuildEnergyIcons(card, magnitude)} {moreOrLess}",
				("Amount", BuildEnergyIcons(card, magnitude))),
			CardExtraEffectKind.GainStars => FormatConditionalBonusAction(
				$"cardText.conditional.action.gainStars.{direction}",
				$"gain {BuildStarIcons(magnitude)} {moreOrLess}",
				("Amount", BuildStarIcons(magnitude))),
			CardExtraEffectKind.LoseStars => FormatConditionalBonusAction(
				$"cardText.conditional.action.loseStars.{direction}",
				$"lose {BuildStarIcons(magnitude)} {moreOrLess}",
				("Amount", BuildStarIcons(magnitude))),
			CardExtraEffectKind.GainGold => FormatConditionalBonusAction(
				$"cardText.conditional.action.gainGold.{direction}",
				$"gain {amountText} {moreOrLess} Gold",
				("Amount", amountText)),
			CardExtraEffectKind.LoseGold => FormatConditionalBonusAction(
				$"cardText.conditional.action.loseGold.{direction}",
				$"lose {amountText} {moreOrLess} Gold",
				("Amount", amountText)),
			CardExtraEffectKind.ApplyPower or CardExtraEffectKind.ApplyWeak or CardExtraEffectKind.ApplyFrail
				or CardExtraEffectKind.ApplyVulnerable or CardExtraEffectKind.ApplyPoison
				or CardExtraEffectKind.ApplyDoom or CardExtraEffectKind.ApplyConstrict
					when powerText != null => FormatConditionalBonusAction(
						$"cardText.conditional.action.applyPower.{direction}",
						$"apply {amountText} {moreOrLess} {powerText}",
						("Amount", amountText),
						("Power", powerText)),
			CardExtraEffectKind.GainStrength or CardExtraEffectKind.GainDexterity or CardExtraEffectKind.GainFocus
				or CardExtraEffectKind.GainArtifact or CardExtraEffectKind.GainThorns or CardExtraEffectKind.GainRegen
				or CardExtraEffectKind.GainPlating or CardExtraEffectKind.GainIntangible or CardExtraEffectKind.GainBuffer
				or CardExtraEffectKind.GainVigor or CardExtraEffectKind.GainBlur or CardExtraEffectKind.GainRitual
					when powerText != null => FormatConditionalBonusAction(
						$"cardText.conditional.action.gainPower.{direction}",
						$"gain {amountText} {moreOrLess} {powerText}",
						("Amount", amountText),
						("Power", powerText)),
			CardExtraEffectKind.GainStatusEqualToStatus when powerText != null => effect.StatusToStatusMode == CardExtraEffectStatusToStatusMode.Lose
				? FormatConditionalBonusAction(
					$"cardText.conditional.action.losePower.{direction}",
					$"lose {amountText} {moreOrLess} {powerText}",
					("Amount", amountText),
					("Power", powerText))
				: FormatConditionalBonusAction(
					$"cardText.conditional.action.gainPower.{direction}",
					$"gain {amountText} {moreOrLess} {powerText}",
					("Amount", amountText),
					("Power", powerText)),
			CardExtraEffectKind.LoseStrength or CardExtraEffectKind.LoseDexterity or CardExtraEffectKind.LoseFocus
				or CardExtraEffectKind.RemoveWeak or CardExtraEffectKind.RemoveFrail or CardExtraEffectKind.RemoveVulnerable
				or CardExtraEffectKind.RemovePoison or CardExtraEffectKind.RemoveDoom or CardExtraEffectKind.RemoveConstrict
				or CardExtraEffectKind.RemoveArtifact or CardExtraEffectKind.RemoveThorns or CardExtraEffectKind.RemoveRegen
				or CardExtraEffectKind.RemovePlating or CardExtraEffectKind.RemoveIntangible or CardExtraEffectKind.RemoveBuffer
				or CardExtraEffectKind.RemoveVigor or CardExtraEffectKind.RemoveBlur or CardExtraEffectKind.RemoveRitual
				or CardExtraEffectKind.RemovePower
					when powerText != null => FormatConditionalBonusAction(
						$"cardText.conditional.action.losePower.{direction}",
						$"lose {amountText} {moreOrLess} {powerText}",
						("Amount", amountText),
						("Power", powerText)),
			CardExtraEffectKind.MultiplyStatStatus => bonus > 0
				? FormatConditionalBonusAction(
					"cardText.conditional.action.multiplier.more",
					$"increase this multiplier by {amountText}",
					("Amount", amountText))
				: FormatConditionalBonusAction(
					"cardText.conditional.action.multiplier.less",
					$"reduce this multiplier by {amountText}",
					("Amount", amountText)),
			_ => bonus > 0
				? FormatConditionalBonusAction(
					"cardText.conditional.action.effect.more",
					$"increase this effect by {amountText}",
					("Amount", amountText))
				: FormatConditionalBonusAction(
					"cardText.conditional.action.effect.less",
					$"reduce this effect by {amountText}",
					("Amount", amountText))
		};
	}

	private static string FormatConditionalBonusAction(string key, string fallback, params (string Name, object? Value)[] args)
	{
		return CardEditorLoc.F(key, fallback, args);
	}

	private static string ApplyConditionalBonusSuffix(CardModel? card, string baseLine, CardExtraEffect effect)
	{
		if (string.IsNullOrWhiteSpace(baseLine) || effect == null)
		{
			return baseLine;
		}

		int bonus = effect.ConditionalBonusAmount;
		if (bonus == 0)
		{
			return baseLine;
		}

		string conditionText = BuildConditionalBonusConditionText(null, effect);
		if (string.IsNullOrWhiteSpace(conditionText))
		{
			return baseLine;
		}

		string bonusText = BuildConditionalBonusActionText(card, effect, bonus);

		string suffix = CardEditorLoc.F(
			"cardText.conditional.bonus",
			$"If {conditionText}, {bonusText}.",
			("Condition", conditionText),
			("Bonus", bonusText));

		string[] split = baseLine.Split('\n', 2);
		string first = split[0].TrimEnd();
		bool endsWithSentencePunctuation = first.EndsWith('.')
			|| first.EndsWith('。')
			|| first.EndsWith('!')
			|| first.EndsWith('！')
			|| first.EndsWith('?')
			|| first.EndsWith('？');
		first = endsWithSentencePunctuation ? first + " " + suffix : first + ". " + suffix;
		return split.Length == 2 ? first + "\n" + split[1] : first;
	}

	private static CardExtraEffectBranchConditionType GetEffectiveConditionalBonusConditionType(CardExtraEffect? effect)
	{
		if (effect == null)
		{
			return CardExtraEffectBranchConditionType.None;
		}

		if (effect.ConditionalBonusConditionType != CardExtraEffectBranchConditionType.None)
		{
			return effect.ConditionalBonusConditionType;
		}

		if (effect.ConditionalBonusCondition == CardExtraEffectConditionalBonusCondition.None)
		{
			return CardExtraEffectBranchConditionType.None;
		}

		return IsTriggerAttackResultCondition(effect.ConditionalBonusCondition)
			? CardExtraEffectBranchConditionType.AttackResult
			: CardExtraEffectBranchConditionType.TargetCheck;
	}

	private static string BuildConditionalBonusConditionText(CardModel? card, CardExtraEffect effect)
	{
		return GetEffectiveConditionalBonusConditionType(effect) switch
		{
			CardExtraEffectBranchConditionType.TargetCheck => BuildConditionalConditionText(
				effect.ConditionalBonusCondition,
				effect.ConditionalBonusEnemyStatus,
				effect.ConditionalBonusEnemyIntent,
				effect.ConditionalBonusPowerId),
			CardExtraEffectBranchConditionType.HistoryCount => BuildCountConditionClause(card, effect),
			CardExtraEffectBranchConditionType.AttackResult => BuildTriggerAttackResultConditionText(effect.ConditionalBonusCondition),
			_ => string.Empty
		};
	}

	private static bool DoesConditionalBonusPass(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffect effect)
	{
		return GetEffectiveConditionalBonusConditionType(effect) switch
		{
			CardExtraEffectBranchConditionType.TargetCheck => DoesConditionalConditionPass(
				combatState,
				ownerCreature,
				cardPlay,
				effect.ConditionalBonusCondition,
				effect.ConditionalBonusEnemyStatus,
				effect.ConditionalBonusEnemyIntent,
				effect.ConditionalBonusPowerId),
			CardExtraEffectBranchConditionType.HistoryCount => DoesCountConditionPass(
				GetHistoryCountMultiplier(combatState, ownerCreature, cardPlay, effect),
				effect),
			CardExtraEffectBranchConditionType.AttackResult => DoesTriggerAttackResultConditionPass(effect.ConditionalBonusCondition),
			_ => false
		};
	}

	private static string ApplyConditionalBranchSuffix(CardModel card, Creature? target, string baseLine, CardExtraEffect effect, int upgradeHighlightComparison, bool isUpgradePreview)
	{
		if (string.IsNullOrWhiteSpace(baseLine) || effect == null)
		{
			return baseLine;
		}

		CardExtraEffect? branchEffect = GetUsableBranchEffect(effect);
		if (branchEffect == null)
		{
			return baseLine;
		}

		string conditionText = BuildBranchConditionText(card, effect);
		if (string.IsNullOrWhiteSpace(conditionText))
		{
			return baseLine;
		}

		string? branchLine = TryFormatLine(card, branchEffect, target, new DescriptionUpgradeComparison(upgradeHighlightComparison, 0), isUpgradePreview);
		if (string.IsNullOrWhiteSpace(branchLine))
		{
			branchLine = BuildBranchFallbackLine(branchEffect);
			if (string.IsNullOrWhiteSpace(branchLine))
			{
				return baseLine;
			}
		}

		string branchEffectText = TrimTrailingSentencePunctuation(branchLine);
		string suffix = effect.BranchMode switch
		{
			CardExtraEffectBranchMode.InsteadIf => CardEditorLoc.F(
				"cardText.branch.instead",
				branchLine.Contains('\n')
					? $"If {conditionText}, instead:\n{branchEffectText}"
					: $"If {conditionText}, {LowercaseFirst(branchEffectText)} instead.",
				("Condition", conditionText),
				("Effect", branchEffectText)),
			CardExtraEffectBranchMode.AlsoIf => CardEditorLoc.F(
				"cardText.branch.also",
				branchLine.Contains('\n')
					? $"If {conditionText}, also:\n{branchEffectText}"
					: $"If {conditionText}, also {LowercaseFirst(branchEffectText)}.",
				("Condition", conditionText),
				("Effect", branchEffectText)),
			_ => string.Empty
		};

		return string.IsNullOrWhiteSpace(suffix) ? baseLine : baseLine + "\n" + suffix;
	}

	private static string? BuildBranchFallbackLine(CardExtraEffect branchEffect)
	{
		if (branchEffect == null)
		{
			return null;
		}

		if (branchEffect.Kind == CardExtraEffectKind.RunEffectSourceCard
			&& !string.IsNullOrWhiteSpace(branchEffect.SpecificCardId))
		{
			string cardName = GetCardReferenceDisplayMode(branchEffect) == CardExtraEffectCardReferenceDisplayMode.FullText
				? BuildSpecificCardReferenceText(branchEffect.SpecificCardId, CardExtraEffectCardReferenceDisplayMode.FullText)
				: (ResolveSpecificCardTitle(branchEffect.SpecificCardId) ?? branchEffect.SpecificCardId.Trim());
			return CardEditorLoc.F(
				"cardText.branch.effectSourceFallback",
				$"run {cardName}",
				("Card", cardName));
		}

		string fallbackLabel = Definitions.FirstOrDefault(def => def.Kind == branchEffect.Kind)?.Label
			?? branchEffect.Kind.ToString();
		string localizedLabel = CardEditorLoc.T($"effectKind.{branchEffect.Kind}", fallbackLabel);
		return CardEditorLoc.F(
			"cardText.branch.effectKindFallback",
			$"{localizedLabel}",
			("Effect", localizedLabel));
	}

	private static string BuildBranchConditionText(CardModel? card, CardExtraEffect effect)
	{
		if (effect == null)
		{
			return string.Empty;
		}

		return effect.BranchConditionType switch
		{
			CardExtraEffectBranchConditionType.TargetCheck => BuildConditionalConditionText(effect.BranchCondition, effect.BranchEnemyStatus, effect.BranchEnemyIntent, effect.BranchPowerId),
			CardExtraEffectBranchConditionType.HistoryCount => TryBuildBranchCountConditionEffect(effect, out CardExtraEffect branchCountEffect)
				? BuildCountConditionClause(card, branchCountEffect)
				: string.Empty,
			CardExtraEffectBranchConditionType.Fatal => CardEditorLoc.T("cardText.branch.condition.fatal", "[gold]Fatal[/gold]"),
			CardExtraEffectBranchConditionType.AttackResult => BuildTriggerAttackResultConditionText(effect.BranchCondition),
			_ => string.Empty
		};
	}

	private static string BuildConditionalConditionText(
		CardExtraEffectConditionalBonusCondition condition,
		CardExtraEffectEnemyStatus enemyStatus,
		CardExtraEffectEnemyIntent enemyIntent,
		string? powerId = null)
	{
		string statusLabel = !string.IsNullOrWhiteSpace(powerId)
			? (ResolvePowerTitle(powerId) ?? CardEditorLoc.T("cardText.power.unknown", "Unknown Power"))
			: EnemyStatusLabel(enemyStatus);

		return condition switch
		{
			CardExtraEffectConditionalBonusCondition.TargetHasBlock => CardEditorLoc.T("cardText.conditional.targetHasBlock", "the target has Block"),
			CardExtraEffectConditionalBonusCondition.TargetHasStatus => CardEditorLoc.F(
				"cardText.conditional.targetHasStatus",
				$"the target has {statusLabel}",
				("Status", statusLabel)),
			CardExtraEffectConditionalBonusCondition.TargetHasIntent => CardEditorLoc.F(
				"cardText.conditional.targetHasIntent",
				$"the target intends to {EnemyIntentLabel(enemyIntent)}",
				("Intent", EnemyIntentLabel(enemyIntent))),
			CardExtraEffectConditionalBonusCondition.SelfHasBlock => CardEditorLoc.T("cardText.conditional.selfHasBlock", "you have Block"),
			CardExtraEffectConditionalBonusCondition.SelfHasStatus => CardEditorLoc.F(
				"cardText.conditional.selfHasStatus",
				$"you have {statusLabel}",
				("Status", statusLabel)),
			CardExtraEffectConditionalBonusCondition.TargetHasNoBlock => CardEditorLoc.T("cardText.conditional.targetHasNoBlock", "the target has no Block"),
			CardExtraEffectConditionalBonusCondition.SelfHasNoBlock => CardEditorLoc.T("cardText.conditional.selfHasNoBlock", "you have no Block"),
			CardExtraEffectConditionalBonusCondition.TargetLacksStatus => CardEditorLoc.F(
				"cardText.conditional.targetLacksStatus",
				$"the target does not have {statusLabel}",
				("Status", statusLabel)),
			CardExtraEffectConditionalBonusCondition.SelfLacksStatus => CardEditorLoc.F(
				"cardText.conditional.selfLacksStatus",
				$"you do not have {statusLabel}",
				("Status", statusLabel)),
			CardExtraEffectConditionalBonusCondition.TargetIntentIsNot => CardEditorLoc.F(
				"cardText.conditional.targetIntentIsNot",
				$"the target does not intend to {EnemyIntentLabel(enemyIntent)}",
				("Intent", EnemyIntentLabel(enemyIntent))),
			CardExtraEffectConditionalBonusCondition.TargetIsDamaged => CardEditorLoc.T("cardText.conditional.targetIsDamaged", "the target is damaged"),
			CardExtraEffectConditionalBonusCondition.SelfIsDamaged => CardEditorLoc.T("cardText.conditional.selfIsDamaged", "you are damaged"),
			CardExtraEffectConditionalBonusCondition.TargetIsBloodied => CardEditorLoc.T("cardText.conditional.targetIsBloodied", "the target is bloodied"),
			CardExtraEffectConditionalBonusCondition.SelfIsBloodied => CardEditorLoc.T("cardText.conditional.selfIsBloodied", "you are bloodied"),
			CardExtraEffectConditionalBonusCondition.TargetIsFullHp => CardEditorLoc.T("cardText.conditional.targetIsFullHp", "the target is at full HP"),
			CardExtraEffectConditionalBonusCondition.SelfIsFullHp => CardEditorLoc.T("cardText.conditional.selfIsFullHp", "you are at full HP"),
			CardExtraEffectConditionalBonusCondition.TargetIsNotBloodied => CardEditorLoc.T("cardText.conditional.targetIsNotBloodied", "the target is not bloodied"),
			CardExtraEffectConditionalBonusCondition.SelfIsNotBloodied => CardEditorLoc.T("cardText.conditional.selfIsNotBloodied", "you are not bloodied"),
			CardExtraEffectConditionalBonusCondition.TargetHasLessHpThanYou => CardEditorLoc.T("cardText.conditional.targetHasLessHpThanYou", "the target has less HP than you"),
			CardExtraEffectConditionalBonusCondition.TargetHasMoreHpThanYou => CardEditorLoc.T("cardText.conditional.targetHasMoreHpThanYou", "the target has more HP than you"),
			CardExtraEffectConditionalBonusCondition.TargetHasLessBlockThanYou => CardEditorLoc.T("cardText.conditional.targetHasLessBlockThanYou", "the target has less Block than you"),
			CardExtraEffectConditionalBonusCondition.TargetHasMoreBlockThanYou => CardEditorLoc.T("cardText.conditional.targetHasMoreBlockThanYou", "the target has more Block than you"),
			CardExtraEffectConditionalBonusCondition.TriggerAttackFullyBlocked => BuildTriggerAttackResultConditionText(condition),
			CardExtraEffectConditionalBonusCondition.TriggerAttackNotFullyBlocked => BuildTriggerAttackResultConditionText(condition),
			CardExtraEffectConditionalBonusCondition.TriggerAttackDealtHpDamage => BuildTriggerAttackResultConditionText(condition),
			CardExtraEffectConditionalBonusCondition.TriggerAttackWasBlocked => BuildTriggerAttackResultConditionText(condition),
			CardExtraEffectConditionalBonusCondition.TriggerAttackPartiallyBlocked => BuildTriggerAttackResultConditionText(condition),
			CardExtraEffectConditionalBonusCondition.TriggerAttackBrokeBlock => BuildTriggerAttackResultConditionText(condition),
			_ => string.Empty
		};
	}

	private static string BuildTriggerAttackResultConditionText(CardExtraEffectConditionalBonusCondition condition)
	{
		return condition switch
		{
			CardExtraEffectConditionalBonusCondition.TriggerAttackFullyBlocked => CardEditorLoc.T("cardText.conditional.triggerAttackFullyBlocked", "the triggering attack was fully blocked"),
			CardExtraEffectConditionalBonusCondition.TriggerAttackNotFullyBlocked => CardEditorLoc.T("cardText.conditional.triggerAttackNotFullyBlocked", "the triggering attack was not fully blocked"),
			CardExtraEffectConditionalBonusCondition.TriggerAttackDealtHpDamage => CardEditorLoc.T("cardText.conditional.triggerAttackDealtHpDamage", "the triggering attack dealt HP damage"),
			CardExtraEffectConditionalBonusCondition.TriggerAttackWasBlocked => CardEditorLoc.T("cardText.conditional.triggerAttackWasBlocked", "the triggering attack was blocked"),
			CardExtraEffectConditionalBonusCondition.TriggerAttackPartiallyBlocked => CardEditorLoc.T("cardText.conditional.triggerAttackPartiallyBlocked", "the triggering attack was partially blocked"),
			CardExtraEffectConditionalBonusCondition.TriggerAttackBrokeBlock => CardEditorLoc.T("cardText.conditional.triggerAttackBrokeBlock", "the triggering attack broke Block"),
			_ => string.Empty
		};
	}

	private static bool HasUsableBranchCondition(CardExtraEffect effect)
	{
		if (effect == null)
		{
			return false;
		}

		return effect.BranchConditionType switch
		{
			CardExtraEffectBranchConditionType.TargetCheck => effect.BranchCondition != CardExtraEffectConditionalBonusCondition.None,
			CardExtraEffectBranchConditionType.HistoryCount => true,
			CardExtraEffectBranchConditionType.Fatal => true,
			CardExtraEffectBranchConditionType.AttackResult => IsTriggerAttackResultCondition(effect.BranchCondition),
			_ => false
		};
	}

	private static bool TryBuildBranchCountConditionEffect(CardExtraEffect effect, out CardExtraEffect branchCountEffect)
	{
		branchCountEffect = null!;
		if (effect == null || effect.BranchConditionType != CardExtraEffectBranchConditionType.HistoryCount)
		{
			return false;
		}

		branchCountEffect = new CardExtraEffect
		{
			ScaleMode = CardExtraEffectScaleMode.ConditionOnly,
			CountEvent = effect.BranchCountEvent,
			CountWindow = effect.BranchCountWindow,
			CountWindowInclusion = effect.BranchCountWindowInclusion,
			BlockLostCountingMode = effect.BranchBlockLostCountingMode,
			CountTurns = effect.BranchCountTurns,
			CountCardPile = effect.BranchCountCardPile,
			CountCardPool = effect.BranchCountCardPool,
			CountCardType = effect.BranchCountCardType,
			CountCardRarity = effect.BranchCountCardRarity,
			CountCardFilter = effect.BranchCountCardFilter,
			CardMatchMode = HasBranchCountCardMatchFilter(effect) ? effect.BranchCountCardMatchMode : effect.CardMatchMode,
			MatchCardId = HasBranchCountCardMatchFilter(effect) ? effect.BranchCountMatchCardId : effect.MatchCardId,
			MatchTagKind = HasBranchCountCardMatchFilter(effect) ? effect.BranchCountMatchTagKind : effect.MatchTagKind,
			MatchVanillaTag = HasBranchCountCardMatchFilter(effect) ? effect.BranchCountMatchVanillaTag : effect.MatchVanillaTag,
			MatchCustomTag = HasBranchCountCardMatchFilter(effect) ? effect.BranchCountMatchCustomTag : effect.MatchCustomTag,
			MatchCustomKeyword = HasBranchCountCardMatchFilter(effect) ? effect.BranchCountMatchCustomKeyword : effect.MatchCustomKeyword,
			CountAggregationMode = GetEffectiveBranchCountAggregationMode(effect),
			CountExcludeSourceCard = effect.BranchCountExcludeSourceCard,
			CountOrbType = effect.BranchCountOrbType,
			CountOrbSelection = effect.BranchCountOrbSelection,
			CountEnemyStatus = effect.BranchCountEnemyStatus,
			CountPowerId = effect.BranchCountPowerId,
			CountEnemyIntent = effect.BranchCountEnemyIntent,
			CountDamageTarget = effect.BranchCountDamageTarget,
			CountDamageDealer = effect.BranchCountDamageDealer,
			CountDamageSource = effect.BranchCountDamageSource,
			CountDamageAggregation = effect.BranchCountDamageAggregation,
			CountDamageCurrentInclusion = effect.BranchCountDamageCurrentInclusion,
			CountResultEffectId = effect.BranchCountResultEffectId,
			CountResultMetric = effect.BranchCountResultMetric,
			CountComparison = effect.BranchCountComparison,
			CountConditionAmount = effect.BranchCountConditionAmount,
			CostFilterEnabled = effect.CostFilterEnabled,
			CostFilterMode = effect.CostFilterMode,
			CostFilterMax = effect.CostFilterMax,
			CountOnlyBlockCards = effect.BranchCountCardFilter == CardExtraEffectCountCardFilter.GainBlock,
			CountUsesCardEffectAmount = GetEffectiveBranchCountAggregationMode(effect) == CardExtraEffectCountAggregationMode.MatchingEffectAmount
		};
		return true;
	}

	private static bool HasBranchCountCardMatchFilter(CardExtraEffect effect)
	{
		if (effect == null)
		{
			return false;
		}

		return effect.BranchCountCardMatchMode switch
		{
			CardExtraEffectCardMatchMode.CardId => !string.IsNullOrWhiteSpace(effect.BranchCountMatchCardId),
			CardExtraEffectCardMatchMode.NameContains => !string.IsNullOrWhiteSpace(effect.BranchCountMatchCardId),
			CardExtraEffectCardMatchMode.Tag when effect.BranchCountMatchTagKind == CardExtraEffectCardMatchTagKind.Custom => !string.IsNullOrWhiteSpace(effect.BranchCountMatchCustomTag),
			CardExtraEffectCardMatchMode.Tag => effect.BranchCountMatchVanillaTag != CardTag.None,
			CardExtraEffectCardMatchMode.CustomKeyword => !string.IsNullOrWhiteSpace(effect.BranchCountMatchCustomKeyword),
			_ => false
		};
	}

	internal static CardExtraEffect? NormalizeLegacyDynamicTransformEffect(CardExtraEffect? effect)
	{
		if (effect == null || effect.Kind != CardExtraEffectKind.DynamicIdentity)
		{
			return effect;
		}

		CardExtraEffect normalized = CloneEffect(effect);
		normalized.Kind = CardExtraEffectKind.StatefulTransform;
		normalized.StatefulTransformMode = CardExtraEffectStatefulTransformMode.Transform;
		normalized.StatefulTransformDuration = CardExtraEffectStatefulTransformDuration.UntilConditionStops;
		normalized.StatefulTransformDurationAmount = Math.Clamp(normalized.StatefulTransformDurationAmount <= 0 ? 1 : normalized.StatefulTransformDurationAmount, 1, 99);

		if (TryBuildBranchCountConditionEffect(effect, out CardExtraEffect conditionEffect))
		{
			CopyCountCondition(normalized, conditionEffect);
			normalized.BranchMode = CardExtraEffectBranchMode.None;
			normalized.BranchConditionType = CardExtraEffectBranchConditionType.None;
			normalized.BranchCondition = CardExtraEffectConditionalBonusCondition.None;
			normalized.BranchPowerId = null;
			normalized.BranchEffect = null;
		}

		return normalized;
	}

	private static void CopyCountCondition(CardExtraEffect destination, CardExtraEffect source)
	{
		if (destination == null || source == null)
		{
			return;
		}

		destination.ScaleMode = source.ScaleMode;
		destination.CountEvent = source.CountEvent;
		destination.CountWindow = source.CountWindow;
		destination.CountWindowInclusion = source.CountWindowInclusion;
		destination.BlockLostCountingMode = source.BlockLostCountingMode;
		destination.CountTurns = source.CountTurns;
		destination.CountCardPile = source.CountCardPile;
		destination.CountCardPool = source.CountCardPool;
		destination.CountCardType = source.CountCardType;
		destination.CountCardRarity = source.CountCardRarity;
		destination.CountCardFilter = source.CountCardFilter;
		destination.CountOnlyBlockCards = source.CountOnlyBlockCards;
		destination.CountAggregationMode = source.CountAggregationMode;
		destination.CountUsesCardEffectAmount = source.CountUsesCardEffectAmount;
		destination.CountExcludeSourceCard = source.CountExcludeSourceCard;
		destination.CountOrbType = source.CountOrbType;
		destination.CountOrbSelection = source.CountOrbSelection;
		destination.CountEnemyStatus = source.CountEnemyStatus;
		destination.CountPowerId = source.CountPowerId;
		destination.CountEnemyIntent = source.CountEnemyIntent;
		destination.CountDamageTarget = source.CountDamageTarget;
		destination.CountDamageDealer = source.CountDamageDealer;
		destination.CountDamageSource = source.CountDamageSource;
		destination.CountDamageAggregation = source.CountDamageAggregation;
		destination.CountDamageCurrentInclusion = source.CountDamageCurrentInclusion;
		destination.CountResultEffectId = source.CountResultEffectId;
		destination.CountResultMetric = source.CountResultMetric;
		destination.CountComparison = source.CountComparison;
		destination.CountConditionAmount = source.CountConditionAmount;
		destination.CostFilterEnabled = source.CostFilterEnabled;
		destination.CostFilterMode = source.CostFilterMode;
		destination.CostFilterMax = source.CostFilterMax;
	}

	private static bool DoesConditionalConditionPass(
		CombatState combatState,
		Creature ownerCreature,
		CardPlay cardPlay,
		CardExtraEffectConditionalBonusCondition condition,
		CardExtraEffectEnemyStatus enemyStatus,
		CardExtraEffectEnemyIntent enemyIntent,
		string? powerId = null)
	{
		if (combatState == null || ownerCreature == null || cardPlay == null || condition == CardExtraEffectConditionalBonusCondition.None)
		{
			return false;
		}

		Creature? target = GetTargetCheckCreature(cardPlay);
		return condition switch
		{
			CardExtraEffectConditionalBonusCondition.TargetHasBlock => target != null && target.Block > 0,
			CardExtraEffectConditionalBonusCondition.TargetHasStatus => target != null && EnemyHasConfiguredStatus(target, enemyStatus, powerId),
			CardExtraEffectConditionalBonusCondition.TargetHasIntent => target != null && EnemyHasIntent(target, enemyIntent),
			CardExtraEffectConditionalBonusCondition.SelfHasBlock => ownerCreature.Block > 0,
			CardExtraEffectConditionalBonusCondition.SelfHasStatus => CreatureHasConfiguredStatus(ownerCreature, enemyStatus, powerId),
			CardExtraEffectConditionalBonusCondition.TargetHasNoBlock => target != null && target.Block <= 0,
			CardExtraEffectConditionalBonusCondition.SelfHasNoBlock => ownerCreature.Block <= 0,
			CardExtraEffectConditionalBonusCondition.TargetLacksStatus => target != null && !EnemyHasConfiguredStatus(target, enemyStatus, powerId),
			CardExtraEffectConditionalBonusCondition.SelfLacksStatus => !CreatureHasConfiguredStatus(ownerCreature, enemyStatus, powerId),
			CardExtraEffectConditionalBonusCondition.TargetIntentIsNot => target != null && !EnemyHasIntent(target, enemyIntent),
			CardExtraEffectConditionalBonusCondition.TargetIsDamaged => target != null && target.CurrentHp < target.MaxHp,
			CardExtraEffectConditionalBonusCondition.SelfIsDamaged => ownerCreature.CurrentHp < ownerCreature.MaxHp,
			CardExtraEffectConditionalBonusCondition.TargetIsBloodied => target != null && target.CurrentHp * 2 <= target.MaxHp,
			CardExtraEffectConditionalBonusCondition.SelfIsBloodied => ownerCreature.CurrentHp * 2 <= ownerCreature.MaxHp,
			CardExtraEffectConditionalBonusCondition.TargetIsFullHp => target != null && target.CurrentHp >= target.MaxHp,
			CardExtraEffectConditionalBonusCondition.SelfIsFullHp => ownerCreature.CurrentHp >= ownerCreature.MaxHp,
			CardExtraEffectConditionalBonusCondition.TargetIsNotBloodied => target != null && target.CurrentHp * 2 > target.MaxHp,
			CardExtraEffectConditionalBonusCondition.SelfIsNotBloodied => ownerCreature.CurrentHp * 2 > ownerCreature.MaxHp,
			CardExtraEffectConditionalBonusCondition.TargetHasLessHpThanYou => target != null && target.CurrentHp < ownerCreature.CurrentHp,
			CardExtraEffectConditionalBonusCondition.TargetHasMoreHpThanYou => target != null && target.CurrentHp > ownerCreature.CurrentHp,
			CardExtraEffectConditionalBonusCondition.TargetHasLessBlockThanYou => target != null && target.Block < ownerCreature.Block,
			CardExtraEffectConditionalBonusCondition.TargetHasMoreBlockThanYou => target != null && target.Block > ownerCreature.Block,
			CardExtraEffectConditionalBonusCondition.TriggerAttackFullyBlocked => DoesTriggerAttackResultConditionPass(condition),
			CardExtraEffectConditionalBonusCondition.TriggerAttackNotFullyBlocked => DoesTriggerAttackResultConditionPass(condition),
			CardExtraEffectConditionalBonusCondition.TriggerAttackDealtHpDamage => DoesTriggerAttackResultConditionPass(condition),
			CardExtraEffectConditionalBonusCondition.TriggerAttackWasBlocked => DoesTriggerAttackResultConditionPass(condition),
			CardExtraEffectConditionalBonusCondition.TriggerAttackPartiallyBlocked => DoesTriggerAttackResultConditionPass(condition),
			CardExtraEffectConditionalBonusCondition.TriggerAttackBrokeBlock => DoesTriggerAttackResultConditionPass(condition),
			_ => false
		};
	}

	internal static bool IsTriggerAttackResultCondition(CardExtraEffectConditionalBonusCondition condition)
	{
		return condition is CardExtraEffectConditionalBonusCondition.TriggerAttackFullyBlocked
			or CardExtraEffectConditionalBonusCondition.TriggerAttackNotFullyBlocked
			or CardExtraEffectConditionalBonusCondition.TriggerAttackDealtHpDamage
			or CardExtraEffectConditionalBonusCondition.TriggerAttackWasBlocked
			or CardExtraEffectConditionalBonusCondition.TriggerAttackPartiallyBlocked
			or CardExtraEffectConditionalBonusCondition.TriggerAttackBrokeBlock;
	}

	private static bool DoesTriggerAttackResultConditionPass(CardExtraEffectConditionalBonusCondition condition)
	{
		if (!IsTriggerAttackResultCondition(condition))
		{
			return false;
		}

		List<DamageResult> results = CardEditorEffectExecutionAmountContext.SnapshotTriggerAttackDamageResults();
		if (results.Count == 0)
		{
			return false;
		}

		return condition switch
		{
			CardExtraEffectConditionalBonusCondition.TriggerAttackFullyBlocked => results.Any(IsFullyBlockedDamageResult),
			CardExtraEffectConditionalBonusCondition.TriggerAttackNotFullyBlocked => results.Any(result => result != null && Math.Max(0, result.TotalDamage) > 0 && !IsFullyBlockedDamageResult(result)),
			CardExtraEffectConditionalBonusCondition.TriggerAttackDealtHpDamage => results.Any(result => result != null && Math.Max(0, result.UnblockedDamage) > 0),
			CardExtraEffectConditionalBonusCondition.TriggerAttackWasBlocked => results.Any(result => result != null && Math.Max(0, result.BlockedDamage) > 0),
			CardExtraEffectConditionalBonusCondition.TriggerAttackPartiallyBlocked => results.Any(result => result != null && Math.Max(0, result.BlockedDamage) > 0 && Math.Max(0, result.UnblockedDamage) > 0),
			CardExtraEffectConditionalBonusCondition.TriggerAttackBrokeBlock => results.Any(result => result != null && result.WasBlockBroken),
			_ => false
		};
	}

	private static bool IsFullyBlockedDamageResult(DamageResult? result)
	{
		if (result == null)
		{
			return false;
		}

		return result.WasFullyBlocked
			|| (Math.Max(0, result.TotalDamage) > 0
				&& Math.Max(0, result.BlockedDamage) > 0
				&& Math.Max(0, result.UnblockedDamage) <= 0);
	}

	private static bool DoesBranchConditionPass(
		CombatState combatState,
		Creature ownerCreature,
		CardPlay cardPlay,
		CardExtraEffect effect)
	{
		if (effect == null || combatState == null || ownerCreature == null || cardPlay == null)
		{
			return false;
		}

		return effect.BranchConditionType switch
		{
			CardExtraEffectBranchConditionType.TargetCheck => DoesConditionalConditionPass(
				combatState,
				ownerCreature,
				cardPlay,
				effect.BranchCondition,
				effect.BranchEnemyStatus,
				effect.BranchEnemyIntent,
				effect.BranchPowerId),
			CardExtraEffectBranchConditionType.HistoryCount => TryBuildBranchCountConditionEffect(effect, out CardExtraEffect branchCountEffect)
				&& DoesCountConditionPass(GetHistoryCountMultiplier(combatState, ownerCreature, cardPlay, branchCountEffect), branchCountEffect),
			CardExtraEffectBranchConditionType.Fatal => DidCardPlayTriggerFatal(cardPlay),
			CardExtraEffectBranchConditionType.AttackResult => DoesTriggerAttackResultConditionPass(effect.BranchCondition),
			_ => false
		};
	}

	private static CardExtraEffect? GetUsableBranchEffect(CardExtraEffect effect)
	{
		if (effect == null
			|| effect.BranchMode == CardExtraEffectBranchMode.None
			|| !HasUsableBranchCondition(effect)
			|| effect.BranchEffect == null)
		{
			return null;
		}

		if (effect.BranchEffect.Kind == CardExtraEffectKind.RunEffectSourceCard
			&& string.IsNullOrWhiteSpace(effect.BranchEffect.SpecificCardId))
		{
			return null;
		}

		return effect.BranchEffect;
	}

	private static int GetMultipliedAmount(int currentAmount, int factor)
	{
		if (factor <= 1)
		{
			return currentAmount;
		}

		long multiplied = (long)currentAmount * factor;
		if (multiplied > int.MaxValue)
		{
			return int.MaxValue;
		}
		if (multiplied < int.MinValue)
		{
			return int.MinValue;
		}

		return (int)multiplied;
	}

	private static int GetMultiplierDelta(int currentAmount, int factor)
	{
		return GetMultipliedAmount(currentAmount, factor) - currentAmount;
	}

	private static async Task MultiplyMatchingTemporaryPowers(Creature target, ModelId underlyingPowerId, Type trackerType, int factor, Creature applier, CardModel? cardSource)
	{
		List<PowerModel> temporaryPowers = target.Powers
			.Where(power => power != null && ((power is ITemporaryPower temporary && Equals(temporary.InternallyAppliedPower.Id, underlyingPowerId)) || trackerType.IsInstanceOfType(power)))
			.ToList();

		foreach (PowerModel power in temporaryPowers)
		{
			int delta = GetMultiplierDelta(power.Amount, factor);
			if (delta == 0)
			{
				continue;
			}

			if (power is ITemporaryPower)
			{
				CardEditorTemporaryPowerCompat.IgnoreNextInternalApplication(power);
			}

			await PowerCmd.ModifyAmount(power, delta, applier, cardSource);
		}
	}

	private static async Task MultiplyPowerWithTemporaryTracking<TPower>(Creature target, Type trackerType, int factor, Creature applier, CardModel? cardSource)
		where TPower : PowerModel
	{
		TPower? power = target.GetPower<TPower>();
		if (power == null || power.Amount == 0)
		{
			return;
		}

		int delta = GetMultiplierDelta(power.Amount, factor);
		if (delta == 0)
		{
			return;
		}

		await PowerCmd.ModifyAmount(power, delta, applier, cardSource);
		await MultiplyMatchingTemporaryPowers(target, power.Id, trackerType, factor, applier, cardSource);
	}

	private static async Task ReducePowerWithTemporaryTracking<TPower, TTracker>(Creature target, int amount, Creature applier, CardModel? cardSource)
		where TPower : PowerModel
		where TTracker : PowerModel
	{
		if (target == null || amount <= 0)
		{
			return;
		}

		if (cardSource?.Owner?.Creature != null
			&& ReferenceEquals(target, cardSource.Owner.Creature)
			&& ((TryGetProtectedMultiplierStat(typeof(TPower), out CardExtraEffectMultiplierStat protectedStat)
					&& CardHasRuntimeProtectedMultiplierStat(cardSource, protectedStat))
				|| CardHasRuntimeProtectedConfiguredPower(cardSource, ModelDb.GetId<TPower>())))
		{
			return;
		}

		TPower? power = target.GetPower<TPower>();
		TTracker? tracker = target.GetPower<TTracker>();
		int currentAmount = power?.Amount ?? 0;
		if (currentAmount <= 0)
		{
			if (tracker != null)
			{
				await PowerCmd.Remove(tracker);
			}
			return;
		}

		int removedAmount = Math.Min(amount, currentAmount);
		if (removedAmount >= currentAmount)
		{
			if (power != null)
			{
				await PowerCmd.Remove(power);
			}
			if (tracker != null)
			{
				await PowerCmd.Remove(tracker);
			}
			return;
		}

		if (power != null)
		{
			await PowerCmd.ModifyAmount(power, -removedAmount, applier, cardSource);
		}

		if (tracker == null)
		{
			return;
		}

		if (tracker.Amount <= removedAmount)
		{
			await PowerCmd.Remove(tracker);
		}
		else
		{
			await PowerCmd.ModifyAmount(tracker, -removedAmount, applier, cardSource);
		}
	}

	private static async Task RemovePowerFromTargets<TPower, TTracker>(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffectTarget target, int amount)
		where TPower : PowerModel
		where TTracker : PowerModel
	{
		foreach (Creature creature in ResolveTargets(combatState, ownerCreature, cardPlay, target))
		{
			await ReducePowerWithTemporaryTracking<TPower, TTracker>(creature, amount, ownerCreature, cardPlay.Card);
		}
	}

	private static async Task<bool> TryRemoveKnownConfiguredPowerFromTargets(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffect effect, int amount)
	{
		if (effect == null
			|| string.IsNullOrWhiteSpace(effect.PowerId)
			|| !TryResolveConfiguredPowerModel(effect.PowerId, out PowerModel? canonical)
			|| canonical?.Id == null
			|| canonical.Id == ModelId.none)
		{
			return false;
		}

		ModelId powerId = canonical.Id;
		if (powerId == ModelDb.GetId<StrengthPower>())
		{
			await RemovePowerFromTargets<StrengthPower, CardEditorTempStrengthTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<DexterityPower>())
		{
			await RemovePowerFromTargets<DexterityPower, CardEditorTempDexterityTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<FocusPower>())
		{
			await RemovePowerFromTargets<FocusPower, CardEditorTempFocusTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<WeakPower>())
		{
			await RemovePowerFromTargets<WeakPower, CardEditorTempWeakTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<FrailPower>())
		{
			await RemovePowerFromTargets<FrailPower, CardEditorTempFrailTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<VulnerablePower>())
		{
			await RemovePowerFromTargets<VulnerablePower, CardEditorTempVulnerableTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<PoisonPower>())
		{
			await RemovePowerFromTargets<PoisonPower, CardEditorTempPoisonTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<DoomPower>())
		{
			await RemovePowerFromTargets<DoomPower, CardEditorTempDoomTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<ArtifactPower>())
		{
			await RemovePowerFromTargets<ArtifactPower, CardEditorTempArtifactTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<ThornsPower>())
		{
			await RemovePowerFromTargets<ThornsPower, CardEditorTempThornsTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<RegenPower>())
		{
			await RemovePowerFromTargets<RegenPower, CardEditorTempRegenTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<PlatingPower>())
		{
			await RemovePowerFromTargets<PlatingPower, CardEditorTempPlatingTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<IntangiblePower>())
		{
			await RemovePowerFromTargets<IntangiblePower, CardEditorTempIntangibleTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<BufferPower>())
		{
			await RemovePowerFromTargets<BufferPower, CardEditorTempBufferTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<VigorPower>())
		{
			await RemovePowerFromTargets<VigorPower, CardEditorTempVigorTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<BlurPower>())
		{
			await RemovePowerFromTargets<BlurPower, CardEditorTempBlurTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<RitualPower>())
		{
			await RemovePowerFromTargets<RitualPower, CardEditorTempRitualTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}
		if (powerId == ModelDb.GetId<ConstrictPower>())
		{
			await RemovePowerFromTargets<ConstrictPower, CardEditorTempConstrictTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
			return true;
		}

		return false;
	}

	private static async Task RemoveCustomStatusBehaviorEntries(Creature? target, string? powerId)
	{
		if (target == null || !CardEditorCustomStatusRegistry.IsCustomStatusId(powerId))
		{
			return;
		}

		CardEditorExtraEffectPower? behaviorPower = target.GetPower<CardEditorExtraEffectPower>();
		if (behaviorPower != null)
		{
			await behaviorPower.RemoveCustomStatusBehaviorEffects(powerId);
		}
	}

	private static async Task ReduceConfiguredPower(Creature? target, string? powerId, int amount, Creature applier, CardModel? cardSource, CardPlay cardPlay, CardExtraEffectTarget requestedTarget)
	{
		if (target == null || string.IsNullOrWhiteSpace(powerId) || amount <= 0)
		{
			return;
		}

		List<PowerModel> matchingPowers = target.Powers?
			.Where(power => PowerMatchesConfiguredPowerId(power, powerId))
			.ToList() ?? new List<PowerModel>();
		foreach (PowerModel power in matchingPowers)
		{
			if (power == null || ShouldPreserveSelfProtectedPower(cardPlay, applier, requestedTarget, power))
			{
				continue;
			}

			int currentAmount = power.Amount;
			bool removeFully = power.StackType == PowerStackType.Single || currentAmount <= 0 || amount >= currentAmount;
			if (power is ITemporaryPower)
			{
				CardEditorTemporaryPowerCompat.IgnoreNextInternalApplication(power);
			}

			if (removeFully)
			{
				await PowerCmd.Remove(power);
				if (power is CardEditorCustomStatusPower)
				{
					await RemoveCustomStatusBehaviorEntries(target, powerId);
				}
				continue;
			}

			await PowerCmd.ModifyAmount(power, -amount, applier, cardSource);
			if (power is CardEditorCustomStatusPower reducedStatus)
			{
				SyncCustomStatusBehaviorStacks(target, reducedStatus);
			}
		}
	}

	private static async Task RemoveConfiguredPowerFromTargets(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffect effect, int amount)
	{
		if (effect == null || string.IsNullOrWhiteSpace(effect.PowerId) || amount <= 0)
		{
			return;
		}

		if (await TryRemoveKnownConfiguredPowerFromTargets(combatState, ownerCreature, cardPlay, effect, amount))
		{
			return;
		}

		foreach (Creature creature in ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target))
		{
			await ReduceConfiguredPower(creature, effect.PowerId, amount, ownerCreature, cardPlay.Card, cardPlay, effect.Target);
		}
	}

	private static async Task CleanseDebuffs(Creature target, Creature applier, CardModel? cardSource)
	{
		await ReducePowerWithTemporaryTracking<WeakPower, CardEditorTempWeakTrackerPower>(target, int.MaxValue, applier, cardSource);
		await ReducePowerWithTemporaryTracking<FrailPower, CardEditorTempFrailTrackerPower>(target, int.MaxValue, applier, cardSource);
		await ReducePowerWithTemporaryTracking<VulnerablePower, CardEditorTempVulnerableTrackerPower>(target, int.MaxValue, applier, cardSource);
		await ReducePowerWithTemporaryTracking<PoisonPower, CardEditorTempPoisonTrackerPower>(target, int.MaxValue, applier, cardSource);
		await ReducePowerWithTemporaryTracking<DoomPower, CardEditorTempDoomTrackerPower>(target, int.MaxValue, applier, cardSource);
		await ReducePowerWithTemporaryTracking<ConstrictPower, CardEditorTempConstrictTrackerPower>(target, int.MaxValue, applier, cardSource);
		await CleanseRemainingPowersByType(target, PowerType.Debuff, applier, cardSource);
	}

	private static async Task CleanseBuffs(Creature target, Creature applier, CardModel? cardSource)
	{
		await ReducePowerWithTemporaryTracking<ArtifactPower, CardEditorTempArtifactTrackerPower>(target, int.MaxValue, applier, cardSource);
		await ReducePowerWithTemporaryTracking<ThornsPower, CardEditorTempThornsTrackerPower>(target, int.MaxValue, applier, cardSource);
		await ReducePowerWithTemporaryTracking<RegenPower, CardEditorTempRegenTrackerPower>(target, int.MaxValue, applier, cardSource);
		await ReducePowerWithTemporaryTracking<PlatingPower, CardEditorTempPlatingTrackerPower>(target, int.MaxValue, applier, cardSource);
		await ReducePowerWithTemporaryTracking<IntangiblePower, CardEditorTempIntangibleTrackerPower>(target, int.MaxValue, applier, cardSource);
		await ReducePowerWithTemporaryTracking<BufferPower, CardEditorTempBufferTrackerPower>(target, int.MaxValue, applier, cardSource);
		await ReducePowerWithTemporaryTracking<VigorPower, CardEditorTempVigorTrackerPower>(target, int.MaxValue, applier, cardSource);
		await ReducePowerWithTemporaryTracking<BlurPower, CardEditorTempBlurTrackerPower>(target, int.MaxValue, applier, cardSource);
		await ReducePowerWithTemporaryTracking<RitualPower, CardEditorTempRitualTrackerPower>(target, int.MaxValue, applier, cardSource);
		await CleanseRemainingPowersByType(target, PowerType.Buff, applier, cardSource);
	}

	// Vanilla "remove all debuffs/buffs" effects enumerate by PowerType (Misery, IllusionPower),
	// so they also catch powers outside any fixed list: No Draw, negative stats, custom statuses.
	// Runs AFTER the tracker-aware typed removals; only visible powers qualify so the mod's
	// invisible infrastructure powers are never swept.
	private static async Task CleanseRemainingPowersByType(Creature target, PowerType type, Creature applier, CardModel? cardSource)
	{
		// Exclusion must be type-based, not IsVisible-based: IsVisible is NetId-dependent (false for
		// a co-op teammate's powers on other clients), which would desync cleanses. Sweep vanilla
		// powers and custom statuses; never the mod's own infrastructure powers (behavior holders,
		// temp/duration/persistence trackers, cosmetic mirrors).
		List<PowerModel> matching = target?.Powers?
			.Where(power => power != null
				&& (power is CardEditorCustomStatusPower
					|| power.GetType().Assembly != typeof(CardEditorExtraEffects).Assembly)
				&& power.GetTypeForAmount(power.Amount) == type)
			.ToList() ?? new List<PowerModel>();
		foreach (PowerModel power in matching)
		{
			if (power is ITemporaryPower)
			{
				CardEditorTemporaryPowerCompat.IgnoreNextInternalApplication(power);
			}

			await PowerCmd.Remove(power);
			if (power is CardEditorCustomStatusPower customStatus)
			{
				await RemoveCustomStatusBehaviorEntries(target, customStatus.CustomStatusId);
			}
		}
	}

	private static async Task MultiplyBlock(Creature target, int factor, CardPlay cardPlay)
	{
		int currentBlock = target.Block;
		if (currentBlock <= 0)
		{
			return;
		}

		int delta = GetMultiplierDelta(currentBlock, factor);
		if (delta > 0)
		{
			await CreatureCmd.GainBlock(target, delta, ValueProp.Move, cardPlay);
		}
	}

	private static async Task MultiplyStatStatus(Creature target, CardExtraEffectMultiplierStat stat, int factor, Creature applier, CardModel? cardSource, CardPlay cardPlay)
	{
		if (target == null || factor <= 1)
		{
			return;
		}

		switch (stat)
		{
			case CardExtraEffectMultiplierStat.Block:
				await MultiplyBlock(target, factor, cardPlay);
				break;
			case CardExtraEffectMultiplierStat.Strength:
				await MultiplyPowerWithTemporaryTracking<StrengthPower>(target, typeof(CardEditorTempStrengthTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Dexterity:
				await MultiplyPowerWithTemporaryTracking<DexterityPower>(target, typeof(CardEditorTempDexterityTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Focus:
				await MultiplyPowerWithTemporaryTracking<FocusPower>(target, typeof(CardEditorTempFocusTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Weak:
				await MultiplyPowerWithTemporaryTracking<WeakPower>(target, typeof(CardEditorTempWeakTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Frail:
				await MultiplyPowerWithTemporaryTracking<FrailPower>(target, typeof(CardEditorTempFrailTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Vulnerable:
				await MultiplyPowerWithTemporaryTracking<VulnerablePower>(target, typeof(CardEditorTempVulnerableTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Poison:
				await MultiplyPowerWithTemporaryTracking<PoisonPower>(target, typeof(CardEditorTempPoisonTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Doom:
				await MultiplyPowerWithTemporaryTracking<DoomPower>(target, typeof(CardEditorTempDoomTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Constrict:
				await MultiplyPowerWithTemporaryTracking<ConstrictPower>(target, typeof(CardEditorTempConstrictTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Artifact:
				await MultiplyPowerWithTemporaryTracking<ArtifactPower>(target, typeof(CardEditorTempArtifactTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Thorns:
				await MultiplyPowerWithTemporaryTracking<ThornsPower>(target, typeof(CardEditorTempThornsTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Regen:
				await MultiplyPowerWithTemporaryTracking<RegenPower>(target, typeof(CardEditorTempRegenTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Plating:
				await MultiplyPowerWithTemporaryTracking<PlatingPower>(target, typeof(CardEditorTempPlatingTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Intangible:
				await MultiplyPowerWithTemporaryTracking<IntangiblePower>(target, typeof(CardEditorTempIntangibleTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Buffer:
				await MultiplyPowerWithTemporaryTracking<BufferPower>(target, typeof(CardEditorTempBufferTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Vigor:
				await MultiplyPowerWithTemporaryTracking<VigorPower>(target, typeof(CardEditorTempVigorTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Blur:
				await MultiplyPowerWithTemporaryTracking<BlurPower>(target, typeof(CardEditorTempBlurTrackerPower), factor, applier, cardSource);
				break;
			case CardExtraEffectMultiplierStat.Ritual:
				await MultiplyPowerWithTemporaryTracking<RitualPower>(target, typeof(CardEditorTempRitualTrackerPower), factor, applier, cardSource);
				break;
		}
	}

	private static async Task MultiplyConfiguredPowerStatus(Creature target, CardExtraEffect effect, int factor, Creature applier, CardModel? cardSource, CardPlay cardPlay)
	{
		if (target == null || effect == null || factor <= 1)
		{
			return;
		}

		if (CardEditorCustomStatusRegistry.IsCustomStatusId(effect.MultiplierPowerId))
		{
			CardEditorCustomStatusPower? customStatus = FindCustomStatusPower(target, effect.MultiplierPowerId);
			if (customStatus == null || customStatus.Amount == 0)
			{
				return;
			}

			int customDelta = GetMultiplierDelta(customStatus.Amount, factor);
			if (customDelta != 0)
			{
				await PowerCmd.ModifyAmount(customStatus, customDelta, applier, cardSource);
			}
			return;
		}

		if (!TryResolveConfiguredPowerModel(effect.MultiplierPowerId, out PowerModel? canonical) || canonical == null)
		{
			return;
		}

		if (ShouldPreserveSelfProtectedPower(cardPlay, applier, effect.Target, canonical))
		{
			return;
		}

		if (TryGetProtectedMultiplierStat(canonical.GetType(), out CardExtraEffectMultiplierStat builtInStat))
		{
			await MultiplyStatStatus(target, builtInStat, factor, applier, cardSource, cardPlay);
			return;
		}

		PowerModel? active = target.Powers?.FirstOrDefault(power => power != null
			&& (Equals(power.Id, canonical.Id)
				|| (power is ITemporaryPower temporary && Equals(temporary.InternallyAppliedPower?.Id, canonical.Id))));
		if (active == null || active.Amount == 0)
		{
			return;
		}

		int delta = GetMultiplierDelta(active.Amount, factor);
		if (delta == 0)
		{
			return;
		}

		if (active is ITemporaryPower)
		{
			CardEditorTemporaryPowerCompat.IgnoreNextInternalApplication(active);
		}

		await PowerCmd.ModifyAmount(active, delta, applier, cardSource);
	}

	private static async Task MultiplyStatStatus(Creature target, CardExtraEffect effect, int factor, Creature applier, CardModel? cardSource, CardPlay cardPlay)
	{
		if (target == null || effect == null || factor <= 1)
		{
			return;
		}

		if (effect.MultiplierSourceMode == CardExtraEffectValueSourceMode.PowerStatus)
		{
			await MultiplyConfiguredPowerStatus(target, effect, factor, applier, cardSource, cardPlay);
			return;
		}

		await MultiplyStatStatus(target, effect.MultiplierStat, factor, applier, cardSource, cardPlay);
	}

	private static async Task CopyDebuffsFromTarget(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffect effect)
	{
		if (combatState == null || ownerCreature == null || cardPlay?.Card == null || effect == null)
		{
			return;
		}

		Creature? source = ResolveSingleTarget(combatState, ownerCreature, cardPlay);
		if (source == null || !source.IsAlive)
		{
			return;
		}

		List<PowerModel> originalDebuffs = source.Powers?
			.Where(power => power != null && power.TypeForCurrentAmount == PowerType.Debuff)
			.Select(power => (PowerModel)power.ClonePreservingMutability())
			.ToList() ?? new List<PowerModel>();
		if (originalDebuffs.Count == 0)
		{
			return;
		}

		List<Creature> destinations = ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target)
			.Where(creature => creature != null && creature.IsAlive && !ReferenceEquals(creature, source))
			.ToList();
		if (destinations.Count == 0)
		{
			return;
		}

		foreach (Creature destination in destinations)
		{
			foreach (PowerModel snapshot in originalDebuffs)
			{
				if (snapshot == null || snapshot.Amount == 0)
				{
					continue;
				}

				PowerModel? active = destination.GetPowerById(snapshot.Id);
				if (active != null && !IsPowerInstanced(active))
				{
					PrepareCopiedTemporaryPower(active);
					await PowerCmd.ModifyAmount(active, snapshot.Amount, ownerCreature, cardPlay.Card);
				}
				else
				{
					PowerModel copy = (PowerModel)snapshot.ClonePreservingMutability();
					PrepareCopiedTemporaryPower(copy);
					await PowerCmd.Apply(copy, destination, snapshot.Amount, ownerCreature, cardPlay.Card);
				}
			}
		}
	}

	private static async Task CopyBuffsFromTarget(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffect effect)
	{
		if (combatState == null || ownerCreature == null || cardPlay?.Card == null || effect == null)
		{
			return;
		}

		// Source = the explicit card target if there is one, otherwise the owner (deterministic). Previously
		// this used ResolveSingleTarget, which on a no-target card fell through to a RANDOM enemy.
		Creature? source = cardPlay.Target ?? ownerCreature;
		if (source == null || !source.IsAlive)
		{
			return;
		}

		List<PowerModel> originalBuffs = source.Powers?
			.Where(power => power != null && power.TypeForCurrentAmount == PowerType.Buff
				// Never copy the mod's own invisible infrastructure powers (behavior holders, temp/duration/
				// persistence trackers); only vanilla buffs and visible custom statuses, mirroring the cleanse path.
				&& (power is CardEditorCustomStatusPower || power.GetType().Assembly != typeof(CardEditorExtraEffects).Assembly))
			.Select(power => (PowerModel)power.ClonePreservingMutability())
			.ToList() ?? new List<PowerModel>();
		if (originalBuffs.Count == 0)
		{
			return;
		}

		List<Creature> destinations = ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target)
			.Where(creature => creature != null && creature.IsAlive && !ReferenceEquals(creature, source))
			.ToList();
		if (destinations.Count == 0)
		{
			return;
		}

		foreach (Creature destination in destinations)
		{
			foreach (PowerModel snapshot in originalBuffs)
			{
				if (snapshot == null || snapshot.Amount == 0)
				{
					continue;
				}

				PowerModel? active = destination.GetPowerById(snapshot.Id);
				if (active != null && !IsPowerInstanced(active))
				{
					PrepareCopiedTemporaryPower(active);
					await PowerCmd.ModifyAmount(active, snapshot.Amount, ownerCreature, cardPlay.Card);
				}
				else
				{
					PowerModel copy = (PowerModel)snapshot.ClonePreservingMutability();
					PrepareCopiedTemporaryPower(copy);
					await PowerCmd.Apply(copy, destination, snapshot.Amount, ownerCreature, cardPlay.Card);
				}
			}
		}
	}

	private static void PrepareCopiedTemporaryPower(PowerModel power)
	{
		if (power is ITemporaryPower)
		{
			CardEditorTemporaryPowerCompat.IgnoreNextInternalApplication(power);
		}
	}

	private static bool IsPowerInstanced(PowerModel power)
	{
		return power != null && power.InstanceType != PowerInstanceType.None;
	}

	private static async Task ModifyActivePowers(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffect effect, int amount)
	{
		if (combatState == null || ownerCreature == null || cardPlay?.Card == null || effect == null)
		{
			return;
		}

		int safeAmount = Math.Max(0, amount);
		foreach (Creature target in ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target))
		{
			if (target == null || !target.IsAlive)
			{
				continue;
			}

			List<PowerModel> matches = target.Powers?
				.Where(power => power != null
					&& power.Amount != 0
					&& PowerMatchesConfiguredStatus(power, effect.PowerTriggerEnemyStatus, effect.PowerTriggerPowerId))
				.ToList() ?? new List<PowerModel>();
			if (matches.Count == 0)
			{
				continue;
			}

			IEnumerable<PowerModel> selected = effect.ActivePowerSelection switch
			{
				CardExtraEffectActivePowerSelection.First => matches.Take(1),
				CardExtraEffectActivePowerSelection.Random => PickRandomActivePower(ownerCreature, matches),
				_ => matches
			};

			foreach (PowerModel power in selected)
			{
				if (power == null)
				{
					continue;
				}

				int delta = effect.StatusToStatusMode switch
				{
					CardExtraEffectStatusToStatusMode.Lose => -safeAmount,
					CardExtraEffectStatusToStatusMode.Set => safeAmount - power.Amount,
					CardExtraEffectStatusToStatusMode.Remove => -power.Amount,
					_ => safeAmount
				};
				if (delta == 0)
				{
					continue;
				}

				if (power is ITemporaryPower)
				{
					CardEditorTemporaryPowerCompat.IgnoreNextInternalApplication(power);
				}
				if (power is CardEditorCustomStatusPower customStatus
					&& CardEditorCustomStatusRegistry.IsCustomStatusId(effect.PowerTriggerPowerId))
				{
					customStatus.SyncDefinition(CardEditorCustomStatusRegistry.Resolve(effect.PowerTriggerPowerId));
				}

				await PowerCmd.ModifyAmount(power, delta, ownerCreature, cardPlay.Card);
				if (power is CardEditorCustomStatusPower modifiedStatus)
				{
					SyncCustomStatusBehaviorStacks(target, modifiedStatus);
				}
			}
		}
	}

	private static IEnumerable<PowerModel> PickRandomActivePower(Creature ownerCreature, IReadOnlyList<PowerModel> powers)
	{
		if (powers == null || powers.Count == 0)
		{
			yield break;
		}

		PowerModel? picked = null;
		try
		{
			picked = ownerCreature?.Player?.RunState?.Rng?.CombatTargets?.NextItem(powers);
		}
		catch
		{
			picked = powers[0];
		}

		if (picked != null)
		{
			yield return picked;
		}
	}

	private static async Task ScheduleCountdownEffectRows(CombatState combatState, CardPlay cardPlay, CardExtraEffect countdownEffect, Creature ownerCreature)
	{
		if (combatState == null || cardPlay?.Card == null || countdownEffect == null || ownerCreature == null)
		{
			return;
		}

		List<string> selectedIds = ParseAutoActionEffectIds(countdownEffect);
		if (selectedIds.Count == 0)
		{
			return;
		}

		Dictionary<string, CardExtraEffect> runtimeEffectsById = GetRuntimeEffectsIncludingBorrowedSources(combatState, cardPlay.Card)
			.Where(e => e != null && !string.IsNullOrWhiteSpace(e.EffectId))
			.GroupBy(e => e.EffectId!, StringComparer.Ordinal)
			.ToDictionary(g => g.Key, g => g.First(), StringComparer.Ordinal);

		CardExtraEffectTiming timing = countdownEffect.Timing == CardExtraEffectTiming.Immediate
			? CardExtraEffectTiming.EndOfTurn
			: countdownEffect.Timing;
		int turns = Math.Max(1, countdownEffect.Turns);
		List<CardEditorCountdownEffectPower.PayloadEntry> payloads = new List<CardEditorCountdownEffectPower.PayloadEntry>();

		foreach (string id in selectedIds)
		{
			if (string.IsNullOrWhiteSpace(id)
				|| string.Equals(id, countdownEffect.EffectId ?? string.Empty, StringComparison.Ordinal)
				|| !runtimeEffectsById.TryGetValue(id, out CardExtraEffect? payload)
				|| payload.Kind is CardExtraEffectKind.ConditionalAutoPlayFromPile
					or CardExtraEffectKind.ConditionalAutoDrawFromPile
					or CardExtraEffectKind.ConditionalAutoRunEffects
					or CardExtraEffectKind.AutoPlaySelfFromPile
					or CardExtraEffectKind.AutoDrawSelfFromPile
					or CardExtraEffectKind.EffectLimit
					or CardExtraEffectKind.CountdownEffect
				|| !IsValidEffectAmount(payload.Kind, payload.Amount))
			{
				continue;
			}

			CardExtraEffect runnable = CloneForDeferredExecution(cardPlay, payload);
			runnable.Trigger = CardExtraEffectTrigger.OnPlay;
			runnable.AsPower = false;
			runnable.Timing = CardExtraEffectTiming.Immediate;
			runnable.Turns = 0;

			Creature? lockedTarget = null;
			if (runnable.Target == CardExtraEffectTarget.Target)
			{
				lockedTarget = ResolveSingleTarget(combatState, ownerCreature, cardPlay);
			}

			payloads.Add(new CardEditorCountdownEffectPower.PayloadEntry(runnable, lockedTarget));
		}

		if (payloads.Count == 0)
		{
			return;
		}

		Player? owner = cardPlay.Card.Owner;
		if (owner == null)
		{
			return;
		}

		CardEditorCountdownEffectPower.PayloadSpec payloadSpec = new CardEditorCountdownEffectPower.PayloadSpec(
			card: CreateDeferredExecutionCardSnapshot(owner, cardPlay.Card),
			sourceCardInstance: cardPlay.Card,
			payloads: payloads,
			selectedCardsByEffectId: CardEditorEffectExecutionAmountContext.CaptureCurrentSelectedCards(cloneCards: true),
			resources: cardPlay.Resources,
			resultPile: cardPlay.ResultPile,
			timing: timing,
			executionHost: ownerCreature,
			useLimitSourceInstance: cardPlay.Card,
			triggerEventAmount: 1,
			payloadDescription: FormatCountdownPayload(cardPlay.Card, countdownEffect, isUpgradePreview: false));

		using IDisposable _ = CardEditorCountdownEffectPower.PushPendingPayload(payloadSpec);
		await PowerCmd.Apply<CardEditorCountdownEffectPower>(ownerCreature, turns, ownerCreature, cardPlay.Card);
	}

	internal static async Task ExecuteCountdownPayloads(CombatState combatState, PlayerChoiceContext choiceContext, CardEditorCountdownEffectPower.PayloadSpec payload)
	{
		if (combatState == null || choiceContext == null || payload?.Card == null || payload.Payloads.Count == 0)
		{
			return;
		}

		try
		{
			using IDisposable _ = CardEditorEffectSourceContext.PushScoped(payload.SourceCardInstance ?? payload.Card);
			using IDisposable __ = CardEditorPowerExecutionHostContext.PushScoped(payload.ExecutionHost);
			using IDisposable ___ = CardEditorAutoPlayLoopGuard.PushUseLimitSourceInstance(payload.UseLimitSourceInstance ?? payload.Card);
			using IDisposable ____ = CardEditorEffectExecutionAmountContext.PushSessionScoped();
			using IDisposable selectedScope = CardEditorEffectExecutionAmountContext.PushSelectedCardsScoped(payload.SelectedCardsByEffectId);

			foreach (CardEditorCountdownEffectPower.PayloadEntry entry in payload.Payloads)
			{
				if (entry?.Effect == null
					|| !IsValidEffectAmount(entry.Effect.Kind, entry.Effect.Amount)
					|| CardEditorAutoPlayLoopGuard.ShouldSuppressEffect(payload.Card, entry.Effect))
				{
					continue;
				}

				CardPlay play = new CardPlay
				{
					Card = payload.Card,
					Player = payload.Card.Owner,
					Target = entry.LockedTarget,
					ResultPile = payload.ResultPile,
					Resources = payload.Resources,
					IsAutoPlay = true,
					PlayIndex = 0,
					PlayCount = 1
				};

				using IDisposable _____ = CardEditorCardPlayContext.PushScoped(play);
				await ExecuteEffect(combatState, choiceContext, play, CloneEffect(entry.Effect), payload.TriggerEventAmount);
			}
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] Countdown effect payload failed: {ex}");
		}
	}

	internal static CardModel CreateDeferredExecutionCardSnapshot(Player owner, CardModel sourceCard)
	{
		if (owner == null || sourceCard == null)
		{
			return sourceCard;
		}

		try
		{
			CardModel snapshot = owner.RunState.CloneCard(sourceCard);
			if (snapshot == null)
			{
				return sourceCard;
			}

			try
			{
				snapshot.Owner = sourceCard.Owner;
			}
			catch
			{
			}

			if (CardEditorOverrides.TryGetEffectiveOverride(sourceCard, out CardOverride effectiveOverride))
			{
				CardEditorOverrides.SetInstanceOverride(snapshot, effectiveOverride);
			}

			return snapshot;
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] Failed cloning deferred effect card snapshot for {sourceCard.Id}: {ex}");
			return sourceCard;
		}
	}

	private static int GetMultiplierStatAmount(Creature target, CardExtraEffectMultiplierStat stat)
	{
		if (target == null)
		{
			return 0;
		}

		return stat switch
		{
			CardExtraEffectMultiplierStat.Block => (int)Math.Max(0, target.Block),
			CardExtraEffectMultiplierStat.Strength => Math.Max(0, target.GetPowerAmount<StrengthPower>()),
			CardExtraEffectMultiplierStat.Dexterity => Math.Max(0, target.GetPowerAmount<DexterityPower>()),
			CardExtraEffectMultiplierStat.Focus => Math.Max(0, target.GetPowerAmount<FocusPower>()),
			CardExtraEffectMultiplierStat.Weak => Math.Max(0, target.GetPowerAmount<WeakPower>()),
			CardExtraEffectMultiplierStat.Frail => Math.Max(0, target.GetPowerAmount<FrailPower>()),
			CardExtraEffectMultiplierStat.Vulnerable => Math.Max(0, target.GetPowerAmount<VulnerablePower>()),
			CardExtraEffectMultiplierStat.Poison => Math.Max(0, target.GetPowerAmount<PoisonPower>()),
			CardExtraEffectMultiplierStat.Doom => Math.Max(0, target.GetPowerAmount<DoomPower>()),
			CardExtraEffectMultiplierStat.Constrict => Math.Max(0, target.GetPowerAmount<ConstrictPower>()),
			CardExtraEffectMultiplierStat.Artifact => Math.Max(0, target.GetPowerAmount<ArtifactPower>()),
			CardExtraEffectMultiplierStat.Thorns => Math.Max(0, target.GetPowerAmount<ThornsPower>()),
			CardExtraEffectMultiplierStat.Regen => Math.Max(0, target.GetPowerAmount<RegenPower>()),
			CardExtraEffectMultiplierStat.Plating => Math.Max(0, target.GetPowerAmount<PlatingPower>()),
			CardExtraEffectMultiplierStat.Intangible => Math.Max(0, target.GetPowerAmount<IntangiblePower>()),
			CardExtraEffectMultiplierStat.Buffer => Math.Max(0, target.GetPowerAmount<BufferPower>()),
			CardExtraEffectMultiplierStat.Vigor => Math.Max(0, target.GetPowerAmount<VigorPower>()),
			CardExtraEffectMultiplierStat.Blur => Math.Max(0, target.GetPowerAmount<BlurPower>()),
			CardExtraEffectMultiplierStat.Ritual => Math.Max(0, target.GetPowerAmount<RitualPower>()),
			_ => 0
		};
	}

	private static bool TryResolveConfiguredPowerModel(string? powerId, out PowerModel? canonical)
	{
		canonical = null;
		if (string.IsNullOrWhiteSpace(powerId) || CardEditorCustomStatusRegistry.IsCustomStatusId(powerId))
		{
			return false;
		}

		try
		{
			ModelId parsed = ModelId.Deserialize(powerId.Trim());
			canonical = ModelDb.GetByIdOrNull<PowerModel>(parsed);
		}
		catch
		{
			canonical = null;
		}

		return canonical != null;
	}

	private static CardEditorCustomStatusPower? FindCustomStatusPower(Creature? creature, string? powerId)
	{
		if (creature == null || !CardEditorCustomStatusRegistry.IsCustomStatusId(powerId))
		{
			return null;
		}

		return creature.Powers?
			.OfType<CardEditorCustomStatusPower>()
			.FirstOrDefault(power => power != null && power.MatchesConfiguredId(powerId));
	}

	private static bool TargetAlreadyHasCustomStatus(Creature? target, string? powerId)
		=> FindCustomStatusPower(target, powerId) != null;

	private static async Task ApplyCustomStatusPower(Creature? target, string? powerId, int amount, Creature? applier, CardModel? cardSource, CardExtraEffect? effect = null)
	{
		if (target == null || !CardEditorCustomStatusRegistry.IsCustomStatusId(powerId) || amount == 0)
		{
			return;
		}

		CardEditorCustomStatusDefinition definition = CardEditorCustomStatusRegistry.Resolve(powerId);
		CardEditorCustomStatusPower? active = FindCustomStatusPower(target, powerId);
		bool targetAlreadyHadPower = active != null;
		if (active != null)
		{
			active.SyncDefinition(definition);
			await PowerCmd.ModifyAmount(active, amount, applier, cardSource);
			ApplyDurationTickPolicy(active, effect, targetAlreadyHadPower);
			if (amount > 0)
			{
				await EnsureCustomStatusBehaviorPower(target, definition, applier, cardSource, Math.Max(1, active.Amount));
			}
			else
			{
				SyncCustomStatusBehaviorStacks(target, active);
			}
			return;
		}

		if (amount < 0)
		{
			return;
		}

		using IDisposable _ = CardEditorCustomStatusPower.PushPendingPayload(definition);
		CardEditorCustomStatusPower? applied = await PowerCmd.Apply<CardEditorCustomStatusPower>(target, amount, applier, cardSource);
		ApplyDurationTickPolicy(applied, effect, targetAlreadyHadPower);
		await EnsureCustomStatusBehaviorPower(target, definition, applier, cardSource, Math.Max(1, amount));
	}

	// Vanilla parity (bug list #4): behavior fires per stack, so the behavior entries' StackCount
	// must follow the status power's current Amount whenever it changes.
	private static void SyncCustomStatusBehaviorStacks(Creature? target, CardEditorCustomStatusPower? status)
	{
		if (target == null || status == null || string.IsNullOrWhiteSpace(status.CustomStatusId))
		{
			return;
		}

		try
		{
			target.GetPower<CardEditorExtraEffectPower>()?.SyncCustomStatusBehaviorStacks(status.CustomStatusId, Math.Max(1, status.Amount));
		}
		catch
		{
		}
	}

	private static async Task EnsureCustomStatusBehaviorPower(
		Creature target,
		CardEditorCustomStatusDefinition definition,
		Creature? applier,
		CardModel? cardSource,
		int stacks = 1)
	{
		if (target == null || definition == null || definition.BehaviorEffects.Count == 0)
		{
			return;
		}

		CardModel? behaviorSourceCard = BuildCustomStatusBehaviorSourceCard(definition, applier, cardSource);
		if (behaviorSourceCard == null)
		{
			return;
		}

		CardEditorExtraEffectPower? behaviorPower = target.GetPower<CardEditorExtraEffectPower>();
		if (behaviorPower == null)
		{
			behaviorPower = await PowerCmd.Apply<CardEditorExtraEffectPower>(target, 1, target, behaviorSourceCard, silent: true);
		}
		if (behaviorPower != null)
		{
			await behaviorPower.AddCustomStatusBehaviorEffects(behaviorSourceCard, definition.Id, definition.BehaviorEffects, stacks);
		}
	}

	private static CardModel? BuildCustomStatusBehaviorSourceCard(
		CardEditorCustomStatusDefinition definition,
		Creature? applier,
		CardModel? fallbackCard)
	{
		CardModel? sourceCard = null;
		if (definition.SourceCardId is ModelId sourceCardId && sourceCardId != ModelId.none)
		{
			try
			{
				CardModel? canonical = ModelDb.GetByIdOrNull<CardModel>(sourceCardId);
				if (canonical != null)
				{
					sourceCard = CardEditorOverrides.BuildPreview(canonical);
				}
			}
			catch
			{
				sourceCard = null;
			}
		}

		sourceCard ??= fallbackCard;
		if (sourceCard != null)
		{
			try
			{
				sourceCard.Owner = applier?.Player ?? fallbackCard?.Owner;
			}
			catch
			{
			}
		}

		return sourceCard;
	}

	private static async Task ExecuteCreatureCommand(PlayerChoiceContext choiceContext, CardPlay cardPlay, CardExtraEffect effect, int amount, Creature target)
	{
		CreatureCommandRuntimeSpec? spec = FindCreatureCommandRuntimeSpec(GetEffectiveCreatureCommandId(effect));
		if (spec == null)
		{
			return;
		}

		ParameterInfo[] parameters = spec.Method.GetParameters();
		object?[] args = new object?[parameters.Length];
		for (int i = 0; i < parameters.Length; i++)
		{
			ParameterInfo parameter = parameters[i];
			Type type = parameter.ParameterType;
			if (type == typeof(Creature))
			{
				args[i] = target;
			}
			else if (type == typeof(PlayerChoiceContext))
			{
				args[i] = choiceContext;
			}
			else if (type == typeof(CardPlay))
			{
				args[i] = cardPlay;
			}
			else if (type == typeof(CardModel))
			{
				args[i] = cardPlay.Card;
			}
			else if (type == typeof(ValueProp))
			{
				args[i] = ValueProp.Move;
			}
			else if (type == typeof(decimal))
			{
				args[i] = (decimal)amount;
			}
			else if (type == typeof(bool))
			{
				args[i] = string.Equals(parameter.Name, "isFromCard", StringComparison.OrdinalIgnoreCase)
					? true
					: parameter.HasDefaultValue ? parameter.DefaultValue : false;
			}
			else if (type == typeof(string))
			{
				args[i] = parameter.HasDefaultValue ? parameter.DefaultValue : null;
			}
		}

		object? result = spec.Method.Invoke(null, args);
		if (result is Task task)
		{
			await task;
		}
	}

private static async Task GainStatusEqualToStatus(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffect effect, int factor)
{
	if (effect == null || factor <= 0)
	{
			return;
		}

		bool appliesCustomStatus = CardEditorCustomStatusRegistry.IsCustomStatusId(effect.PowerId);
		if (!TryResolveConfiguredPowerModel(effect.PowerId, out PowerModel? canonical) || canonical == null)
		{
			if (!appliesCustomStatus)
			{
				return;
			}
		}

		foreach (Creature target in ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target))
		{
			if (target == null)
			{
				continue;
			}

			int sourceAmount = GetConfiguredMultiplierSourceAmount(target, effect);
			if (sourceAmount <= 0)
			{
				continue;
			}

			long total = (long)sourceAmount * factor;
			if (total <= 0)
			{
				continue;
			}

			int appliedAmount = total >= int.MaxValue ? int.MaxValue : (int)total;
			if (effect.StatusToStatusMode == CardExtraEffectStatusToStatusMode.Lose)
			{
				// Losing must reduce an EXISTING power: applying a negative amount to a target
				// without the power creates a live phantom instance with negative stacks.
				await ReduceConfiguredPower(target, effect.PowerId, appliedAmount, ownerCreature, cardPlay.Card, cardPlay, effect.Target);
				continue;
			}

			if (appliesCustomStatus)
			{
				await ApplyCustomStatusPower(target, effect.PowerId, appliedAmount, ownerCreature, cardPlay.Card, effect);
			}
			else if (canonical != null)
			{
				PowerModel power = canonical.ToMutable();
				await PowerCmd.Apply(power, target, appliedAmount, ownerCreature, cardPlay.Card);
			}
		}
	}

	internal static Task ExecuteEffect(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay, CardExtraEffect effect, int triggerEventAmount = 1)
		=> ExecuteEffect(combatState, choiceContext, cardPlay, effect, branchDepth: 0, triggerEventAmount: triggerEventAmount);

	private static async Task ExecuteEffect(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay, CardExtraEffect effect, int branchDepth, int triggerEventAmount)
	{
		if (effect == null || branchDepth > MaxBranchDepth)
		{
			return;
		}

		effect = NormalizeSignedEffectAmount(effect) ?? effect;
		if (!IsValidEffectAmount(effect.Kind, effect.Amount))
		{
			return;
		}
		if (effect.Kind == CardExtraEffectKind.EffectLimit)
		{
			return;
		}
		// Auto-action rows: only POWER-hosted rows execute through this generic path (Whenever
		// and the other power triggers); non-power rows run via their dedicated card-hosted
		// runners and reaching here was a silent no-op — return BEFORE the Use Limit consumption
		// below, which used to double-consume for limit-bearing rows.
		if (IsSelfPileAutoEffectKind(effect.Kind) && !IsPowerEffect(effect))
		{
			return;
		}

		CardModel? card = cardPlay?.Card;
		Player? owner = card?.Owner;
		Creature? ownerCreature = owner?.Creature;
		CardModel? limitSourceCard = CardEditorEffectSourceContext.Current ?? card;
		Player? limitOwner = owner ?? limitSourceCard?.Owner;
		// Auto-action rows consume their Use Limit inside TryRunSelfPileAutoEffect AFTER the
		// pile/position/condition gates — consuming here would burn a use on every trigger
		// firing even when the action doesn't match (card in the wrong pile, condition unmet).
		// During an EachTarget fan-out the per-target re-runs (_eachTargetCurrent != null) must NOT re-consume
		// the use limit: the outer call already consumed one use for the whole effect.
		if (_eachTargetCurrent == null
			&& !IsSelfPileAutoEffectKind(effect.Kind)
			&& !CardEditorAutoPlayLoopGuard.TryConsumeEffectUseLimit(combatState, limitOwner, limitSourceCard, effect))
		{
			return;
		}

		CardExtraEffect? branchEffect = GetUsableBranchEffect(effect);
		ownerCreature = CardEditorPowerExecutionHostContext.Current ?? ownerCreature;

		// "Each Target (its own value)": re-run this effect once per resolved target so the existing
		// single-target path computes its amount from that target's own stat. Opt-in via ValueSourceActor.
		if (effect.ValueSourceActor == CardExtraEffectValueSourceActor.EachTarget && _eachTargetCurrent == null && ownerCreature != null)
		{
			foreach (Creature eachTarget in ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target).Where(c => c != null && c.IsAlive).ToList())
			{
				_eachTargetCurrent = eachTarget;
				try
				{
					await ExecuteEffect(combatState, choiceContext, cardPlay, effect, branchDepth + 1, triggerEventAmount);
				}
				finally
				{
					_eachTargetCurrent = null;
				}
			}
			return;
		}
		bool shouldRunBranch = branchEffect != null
			&& effect.Kind != CardExtraEffectKind.DrawAndCheck
			&& cardPlay != null
			&& ownerCreature != null
			&& DoesBranchConditionPass(
				combatState,
				ownerCreature,
				cardPlay,
				effect);

		if (shouldRunBranch && effect.BranchMode == CardExtraEffectBranchMode.InsteadIf)
		{
			await ExecuteEffect(combatState, choiceContext, cardPlay, branchEffect!, branchDepth + 1, triggerEventAmount);
			return;
		}

		await ExecuteEffectCore(combatState, choiceContext, cardPlay, effect, triggerEventAmount);

		if (shouldRunBranch && effect.BranchMode == CardExtraEffectBranchMode.AlsoIf)
		{
			await ExecuteEffect(combatState, choiceContext, cardPlay, branchEffect!, branchDepth + 1, triggerEventAmount);
		}
	}

	// Set while an EachTarget effect is being fanned out per resolved target: the one creature currently
	// being processed. Both ResolveTargets and the EachTarget value source resolve to it, so the existing
	// single-target execution path applies the effect to that creature using that creature's own stat.
	[System.ThreadStatic]
	private static Creature? _eachTargetCurrent;

	// Bounds DrawAndCheck branch nesting (the kind-switch method has no branchDepth); also feeds
	// ExecuteEffect's own MaxBranchDepth cap.
	[System.ThreadStatic]
	private static int _drawAndCheckBranchDepth;

	private static IEnumerable<Creature> ResolveValueSourceCreatures(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffect effect)
	{
		if (combatState == null || ownerCreature == null || cardPlay == null || effect == null)
		{
			return Array.Empty<Creature>();
		}

		return effect.ValueSourceActor switch
		{
			CardExtraEffectValueSourceActor.Self => new[] { ownerCreature },
			CardExtraEffectValueSourceActor.Target => ResolveSingleTarget(combatState, ownerCreature, cardPlay) is Creature target && target != null
				? new[] { target }
				: Array.Empty<Creature>(),
			CardExtraEffectValueSourceActor.EventActor => cardPlay.Target != null
				? new[] { cardPlay.Target }
				: Array.Empty<Creature>(),
			CardExtraEffectValueSourceActor.AllEnemies => combatState.GetOpponentsOf(ownerCreature).Where(c => c != null && c.IsAlive),
			CardExtraEffectValueSourceActor.AllAllies => ResolveFriendlyGroupTargets(combatState, ownerCreature, includeSelf: true),
			CardExtraEffectValueSourceActor.EachTarget => _eachTargetCurrent != null ? new[] { _eachTargetCurrent } : Array.Empty<Creature>(),
			_ => new[] { ownerCreature }
		};
	}

	private static CardExtraEffectMultiplierStat? TryMapValueSourceKindToMultiplierStat(CardExtraEffectValueSourceKind kind)
	{
		return kind switch
		{
			CardExtraEffectValueSourceKind.Block => CardExtraEffectMultiplierStat.Block,
			CardExtraEffectValueSourceKind.Strength => CardExtraEffectMultiplierStat.Strength,
			CardExtraEffectValueSourceKind.Dexterity => CardExtraEffectMultiplierStat.Dexterity,
			CardExtraEffectValueSourceKind.Focus => CardExtraEffectMultiplierStat.Focus,
			CardExtraEffectValueSourceKind.Weak => CardExtraEffectMultiplierStat.Weak,
			CardExtraEffectValueSourceKind.Frail => CardExtraEffectMultiplierStat.Frail,
			CardExtraEffectValueSourceKind.Vulnerable => CardExtraEffectMultiplierStat.Vulnerable,
			CardExtraEffectValueSourceKind.Poison => CardExtraEffectMultiplierStat.Poison,
			CardExtraEffectValueSourceKind.Doom => CardExtraEffectMultiplierStat.Doom,
			CardExtraEffectValueSourceKind.Constrict => CardExtraEffectMultiplierStat.Constrict,
			CardExtraEffectValueSourceKind.Artifact => CardExtraEffectMultiplierStat.Artifact,
			CardExtraEffectValueSourceKind.Thorns => CardExtraEffectMultiplierStat.Thorns,
			CardExtraEffectValueSourceKind.Regen => CardExtraEffectMultiplierStat.Regen,
			CardExtraEffectValueSourceKind.Plating => CardExtraEffectMultiplierStat.Plating,
			CardExtraEffectValueSourceKind.Intangible => CardExtraEffectMultiplierStat.Intangible,
			CardExtraEffectValueSourceKind.Buffer => CardExtraEffectMultiplierStat.Buffer,
			CardExtraEffectValueSourceKind.Vigor => CardExtraEffectMultiplierStat.Vigor,
			CardExtraEffectValueSourceKind.Blur => CardExtraEffectMultiplierStat.Blur,
			CardExtraEffectValueSourceKind.Ritual => CardExtraEffectMultiplierStat.Ritual,
			_ => null
		};
	}

	private static int GetSpecificPowerValueSourceAmount(Creature creature, string? powerId)
	{
		if (CardEditorCustomStatusRegistry.IsCustomStatusId(powerId))
		{
			CardEditorCustomStatusPower? customStatus = FindCustomStatusPower(creature, powerId);
			if (customStatus == null)
			{
				return 0;
			}

			return Math.Max(0, customStatus.Amount);
		}

		if (creature == null || !TryResolveConfiguredPowerModel(powerId, out PowerModel? canonical) || canonical == null)
		{
			return 0;
		}

		PowerModel? active = creature.Powers?.FirstOrDefault(power => power != null && Equals(power.Id, canonical.Id));
		if (active == null)
		{
			return 0;
		}

		int amount = Math.Max(0, active.Amount);
		if (amount > 0)
		{
			return amount;
		}

		return active.StackType == PowerStackType.Single ? 1 : 0;
	}

	private static int GetConfiguredMultiplierSourceAmount(Creature target, CardExtraEffect effect)
	{
		if (target == null || effect == null)
		{
			return 0;
		}

		return effect.MultiplierSourceMode == CardExtraEffectValueSourceMode.PowerStatus
			? GetSpecificPowerValueSourceAmount(target, effect.MultiplierPowerId)
			: GetMultiplierStatAmount(target, effect.MultiplierStat);
	}

	private static int GetValueSourceAmount(Creature creature, CardExtraEffectValueSourceKind kind)
	{
		if (creature == null)
		{
			return 0;
		}

		return kind switch
		{
			CardExtraEffectValueSourceKind.CurrentHp => Math.Max(0, creature.CurrentHp),
			CardExtraEffectValueSourceKind.MaxHp => Math.Max(0, creature.MaxHp),
			CardExtraEffectValueSourceKind.MissingHp => Math.Max(0, creature.MaxHp - creature.CurrentHp),
			_ => TryMapValueSourceKindToMultiplierStat(kind) is CardExtraEffectMultiplierStat stat
				? GetMultiplierStatAmount(creature, stat)
				: 0
		};
	}

	private static int GetValueSourceAmount(Creature creature, CardExtraEffect effect)
	{
		if (effect == null || creature == null)
		{
			return 0;
		}

		return effect.ValueSourceMode == CardExtraEffectValueSourceMode.PowerStatus
			? GetSpecificPowerValueSourceAmount(creature, effect.ValueSourcePowerId)
			: GetValueSourceAmount(creature, effect.ValueSourceKind);
	}

	private static int AggregateValueSourceAmounts(IReadOnlyList<int> values, CardExtraEffectValueSourceAggregation aggregation)
	{
		if (values == null || values.Count == 0)
		{
			return 0;
		}

		return aggregation switch
		{
			CardExtraEffectValueSourceAggregation.Sum => ClampLongToInt(values.Aggregate(0L, (sum, value) => sum + Math.Max(0, value))),
			CardExtraEffectValueSourceAggregation.Highest => Math.Max(0, values.Max()),
			CardExtraEffectValueSourceAggregation.Lowest => Math.Max(0, values.Min()),
			CardExtraEffectValueSourceAggregation.Average => Math.Max(0, (int)Math.Round(values.Average(value => Math.Max(0, value)), MidpointRounding.AwayFromZero)),
			_ => Math.Max(0, values[0])
		};
	}

	private static int ResolveValueSourceAmount(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffect effect)
	{
		List<int> values = ResolveValueSourceCreatures(combatState, ownerCreature, cardPlay, effect)
			.Where(creature => creature != null)
			.Select(creature => GetValueSourceAmount(creature, effect))
			.ToList();

		if (values.Count == 0)
		{
			return 0;
		}

		bool usesGroupAggregation = effect.ValueSourceActor is CardExtraEffectValueSourceActor.AllEnemies or CardExtraEffectValueSourceActor.AllAllies;
		CardExtraEffectValueSourceAggregation aggregation = usesGroupAggregation
			? (effect.ValueSourceAggregation == CardExtraEffectValueSourceAggregation.Value
				? CardExtraEffectValueSourceAggregation.Sum
				: effect.ValueSourceAggregation)
			: CardExtraEffectValueSourceAggregation.Value;
		return AggregateValueSourceAmounts(values, aggregation);
	}

	private static int ResolveConfiguredEffectAmount(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffect effect)
	{
		if (UsesAppliedEffectRowAmountSource(effect))
		{
			if (effect.AmountSourceMode == CardExtraEffectAmountSourceMode.AppliedEffectRow
				&& TryResolveVanillaDynamicAmountSource(cardPlay?.Card, effect.AmountSourceEffectId, out int vanillaAmount))
			{
				return ScaleAmountSourceAmount(vanillaAmount, effect);
			}

			int sourceAmount = effect.AmountSourceMode switch
			{
				CardExtraEffectAmountSourceMode.AppliedEffectHpDamage => CardEditorEffectExecutionAmountContext.TryGetAppliedAmount(effect.AmountSourceEffectId, out int hpDamageAmount)
					? hpDamageAmount
					: 0,
				CardExtraEffectAmountSourceMode.AppliedEffectBlockedDamage => CardEditorEffectExecutionAmountContext.TryGetBlockedDamageAmount(effect.AmountSourceEffectId, out int blockedDamageAmount)
					? blockedDamageAmount
					: 0,
				CardExtraEffectAmountSourceMode.AppliedEffectTotalDamage => CardEditorEffectExecutionAmountContext.TryGetTotalDamageAmount(effect.AmountSourceEffectId, out int totalDamageAmount)
					? totalDamageAmount
					: 0,
				CardExtraEffectAmountSourceMode.AppliedEffectOverkillDamage => CardEditorEffectExecutionAmountContext.TryGetOverkillDamageAmount(effect.AmountSourceEffectId, out int overkillDamageAmount)
					? overkillDamageAmount
					: 0,
				CardExtraEffectAmountSourceMode.AppliedEffectTotalAndOverkillDamage => ResolveTotalAndOverkillDamageAmount(effect.AmountSourceEffectId),
				CardExtraEffectAmountSourceMode.AppliedEffectKills => CardEditorEffectExecutionAmountContext.TryGetKillCount(effect.AmountSourceEffectId, out int killCount)
					? killCount
					: 0,
				CardExtraEffectAmountSourceMode.AppliedEffectInstances => CardEditorEffectExecutionAmountContext.TryGetAppliedCount(effect.AmountSourceEffectId, out int appliedCount)
					? appliedCount
					: 0,
				CardExtraEffectAmountSourceMode.ConfiguredEffectAmount => CardEditorEffectExecutionAmountContext.TryGetConfiguredAmount(effect.AmountSourceEffectId, out int configuredAmount)
					? configuredAmount
					: 0,
				CardExtraEffectAmountSourceMode.ConfiguredEffectInstances => CardEditorEffectExecutionAmountContext.TryGetConfiguredCount(effect.AmountSourceEffectId, out int configuredCount)
					? configuredCount
					: 0,
				_ => CardEditorEffectExecutionAmountContext.TryGetAppliedAmount(effect.AmountSourceEffectId, out int appliedAmount)
					? appliedAmount
					: 0
			};
			return ScaleAmountSourceAmount(sourceAmount, effect);
		}

		if (UsesValueSourceAmountSource(effect))
		{
			return ScaleAmountSourceAmount(ResolveValueSourceAmount(combatState, ownerCreature, cardPlay, effect), effect);
		}

		return effect.AmountIsX
			? ResolveXAmountWithPlus(cardPlay, effect.AmountXPlus)
			: effect.Amount;
	}

	private static int ResolveTotalAndOverkillDamageAmount(string? effectId)
	{
		int total = CardEditorEffectExecutionAmountContext.TryGetTotalDamageAmount(effectId, out int totalDamageAmount)
			? totalDamageAmount
			: 0;
		int overkill = CardEditorEffectExecutionAmountContext.TryGetOverkillDamageAmount(effectId, out int overkillDamageAmount)
			? overkillDamageAmount
			: 0;
		return ClampLongToInt((long)Math.Max(0, total) + Math.Max(0, overkill));
	}

	private static int ScaleAmountSourceAmount(int sourceAmount, CardExtraEffect effect)
	{
		if (sourceAmount <= 0 || effect == null)
		{
			return 0;
		}

		decimal multiplier = Math.Clamp(effect.AmountSourceMultiplier <= 0m ? 1m : effect.AmountSourceMultiplier, 0.01m, 999m);
		decimal total = sourceAmount * multiplier;
		if (total >= int.MaxValue)
		{
			return int.MaxValue;
		}

		return Math.Max(0, (int)decimal.Round(total, 0, MidpointRounding.AwayFromZero));
	}

	internal static bool TryDecodeVanillaDynamicAmountSource(string? encodedSource, out string key)
	{
		key = string.Empty;
		if (string.IsNullOrWhiteSpace(encodedSource)
			|| !encodedSource.Trim().StartsWith(VanillaDynamicAmountSourcePrefix, StringComparison.Ordinal))
		{
			return false;
		}

		key = encodedSource.Trim().Substring(VanillaDynamicAmountSourcePrefix.Length).Trim();
		return !string.IsNullOrWhiteSpace(key);
	}

	internal static string EncodeVanillaDynamicAmountSource(string key)
		=> VanillaDynamicAmountSourcePrefix + (key ?? string.Empty).Trim();

	private static bool TryResolveVanillaDynamicAmountSource(CardModel? card, string? encodedSource, out int amount)
	{
		amount = 0;
		if (card?.DynamicVars == null || !TryDecodeVanillaDynamicAmountSource(encodedSource, out string key))
		{
			return false;
		}

		foreach ((string candidateKey, var dynamicVar) in card.DynamicVars)
		{
			if (!string.Equals(candidateKey, key, StringComparison.OrdinalIgnoreCase))
			{
				continue;
			}

			amount = Math.Max(0, (int)decimal.Round(dynamicVar.BaseValue, 0, MidpointRounding.AwayFromZero));
			return true;
		}

		return false;
	}

	private static bool EffectUsesTargetCountForAppliedAmount(CardExtraEffectKind kind)
	{
		return kind is CardExtraEffectKind.GainBlock
			or CardExtraEffectKind.DealDamage
			or CardExtraEffectKind.Heal
			or CardExtraEffectKind.LoseHp
			or CardExtraEffectKind.GainStrength
			or CardExtraEffectKind.LoseStrength
			or CardExtraEffectKind.GainDexterity
			or CardExtraEffectKind.LoseDexterity
			or CardExtraEffectKind.GainFocus
			or CardExtraEffectKind.LoseFocus
			or CardExtraEffectKind.ApplyWeak
			or CardExtraEffectKind.ApplyFrail
			or CardExtraEffectKind.ApplyVulnerable
			or CardExtraEffectKind.ApplyPoison
			or CardExtraEffectKind.ApplyDoom
			or CardExtraEffectKind.RemoveWeak
			or CardExtraEffectKind.RemoveFrail
			or CardExtraEffectKind.RemoveVulnerable
			or CardExtraEffectKind.RemovePoison
			or CardExtraEffectKind.RemoveDoom
			or CardExtraEffectKind.GainArtifact
			or CardExtraEffectKind.GainThorns
			or CardExtraEffectKind.GainRegen
			or CardExtraEffectKind.GainPlating
			or CardExtraEffectKind.GainIntangible
			or CardExtraEffectKind.GainBuffer
			or CardExtraEffectKind.GainVigor
			or CardExtraEffectKind.GainBlur
			or CardExtraEffectKind.GainRitual
			or CardExtraEffectKind.RemoveArtifact
			or CardExtraEffectKind.RemoveThorns
			or CardExtraEffectKind.RemoveRegen
			or CardExtraEffectKind.RemovePlating
			or CardExtraEffectKind.RemoveIntangible
			or CardExtraEffectKind.RemoveBuffer
			or CardExtraEffectKind.RemoveVigor
			or CardExtraEffectKind.RemoveBlur
			or CardExtraEffectKind.RemoveRitual
			or CardExtraEffectKind.ApplyConstrict
			or CardExtraEffectKind.RemoveConstrict
			or CardExtraEffectKind.ApplyPower
			or CardExtraEffectKind.RemovePower
			or CardExtraEffectKind.GainStatusEqualToStatus
			or CardExtraEffectKind.RemoveBlock;
	}

	private static int EstimateAppliedTargetCount(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffectTarget requestedTarget)
	{
		CardExtraEffectTarget target = GetEffectiveResolvedTarget(cardPlay, requestedTarget);
		return target switch
		{
			CardExtraEffectTarget.Self => 1,
			CardExtraEffectTarget.AllAllies => ResolveFriendlyGroupTargets(combatState, ownerCreature, includeSelf: true).Count(),
			CardExtraEffectTarget.AnyPlayer => ResolveFriendlySingleTarget(combatState, ownerCreature, cardPlay, includeSelf: true) != null ? 1 : 0,
			CardExtraEffectTarget.AnyAlly => ResolveFriendlySingleTarget(combatState, ownerCreature, cardPlay, includeSelf: false) != null ? 1 : 0,
			CardExtraEffectTarget.AllEnemies => combatState.GetOpponentsOf(ownerCreature).Count(c => c.IsAlive),
			CardExtraEffectTarget.OtherEnemies => ResolveOtherEnemyTargets(combatState, ownerCreature, cardPlay).Count(),
			CardExtraEffectTarget.RandomEnemy => combatState.GetOpponentsOf(ownerCreature).Any(c => c.IsAlive) ? 1 : 0,
			CardExtraEffectTarget.EventTarget => cardPlay?.Target != null ? 1 : 0,
			_ => ResolveSingleTarget(combatState, ownerCreature, cardPlay) != null ? 1 : 0
		};
	}

	private static int EstimateFallbackAppliedAmount(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffect effect, int amount, int repeats)
	{
		if (effect == null || amount <= 0 || repeats <= 0)
		{
			return 0;
		}

		long total = amount;
		if (EffectUsesTargetCountForAppliedAmount(effect.Kind))
		{
			total *= Math.Max(0, EstimateAppliedTargetCount(combatState, ownerCreature, cardPlay, effect.Target));
		}

		total *= Math.Max(1, repeats);
		if (total >= int.MaxValue)
		{
			return int.MaxValue;
		}

		return total <= 0 ? 0 : (int)total;
	}

	private static int EstimateFallbackAppliedCount(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffect effect, int amount, int repeats)
	{
		if (effect == null || amount <= 0 || repeats <= 0)
		{
			return 0;
		}

		long total = EffectUsesTargetCountForAppliedAmount(effect.Kind)
			? Math.Max(0, EstimateAppliedTargetCount(combatState, ownerCreature, cardPlay, effect.Target))
			: 1;
		total *= Math.Max(1, repeats);
		return total >= int.MaxValue ? int.MaxValue : total <= 0 ? 0 : (int)total;
	}

	private static int ResolveRunEffectSourceExecutionCount(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffect effect)
	{
		if (effect == null)
		{
			return 0;
		}

		int executionCount = 1;
		if (effect.ScaleMode != CardExtraEffectScaleMode.None)
		{
			int multiplier = GetHistoryCountMultiplier(combatState, ownerCreature, cardPlay, effect);
			if (!DoesCountConditionPass(multiplier, effect))
			{
				return 0;
			}

			if (effect.ScaleMode == CardExtraEffectScaleMode.PerHistoryCount)
			{
				int scalingMultiplier = ResolveHistoryScalingMultiplier(effect, multiplier);
				if (scalingMultiplier <= 0 && !effect.HistoryScalingIncludesBase)
				{
					return 0;
				}

				long totalExecutions = effect.HistoryScalingIncludesBase
					? 1L + scalingMultiplier
					: scalingMultiplier;
				executionCount = totalExecutions >= 99 ? 99 : (int)totalExecutions;
			}
		}

		int repeats = ResolveRepeatCount(cardPlay, effect);
		if (repeats <= 0)
		{
			return 0;
		}

		long combined = (long)executionCount * repeats;
		return combined >= 99 ? 99 : combined <= 0 ? 0 : (int)combined;
	}

	private static bool UsesCurrentEffectResultRepeat(CardExtraEffect effect)
	{
		if (effect == null
			|| effect.Kind != CardExtraEffectKind.DealDamage
			|| effect.ScaleMode != CardExtraEffectScaleMode.RepeatByCount
			|| effect.CountEvent != CardExtraEffectCountEvent.EffectResult)
		{
			return false;
		}

		string configuredId = effect.CountResultEffectId?.Trim() ?? string.Empty;
		return string.IsNullOrWhiteSpace(configuredId)
			|| (!string.IsNullOrWhiteSpace(effect.EffectId)
				&& string.Equals(configuredId, effect.EffectId.Trim(), StringComparison.Ordinal));
	}

	private static int GetDamageResultMetricAmount(IEnumerable<DamageResult>? results, CardExtraEffectResultMetric metric)
	{
		if (results == null)
		{
			return 0;
		}

		long total = 0;
		foreach (DamageResult? result in results)
		{
			if (result == null)
			{
				continue;
			}

			total += metric switch
			{
				CardExtraEffectResultMetric.AppliedCount => result.TotalDamage > 0 ? 1 : 0,
				CardExtraEffectResultMetric.HpDamage => Math.Max(0, result.UnblockedDamage),
				CardExtraEffectResultMetric.BlockedDamage => Math.Max(0, result.BlockedDamage),
				CardExtraEffectResultMetric.TotalDamage => Math.Max(0, result.TotalDamage),
				CardExtraEffectResultMetric.OverkillDamage => Math.Max(0, result.OverkillDamage),
				CardExtraEffectResultMetric.TotalAndOverkillDamage => (long)Math.Max(0, result.TotalDamage) + Math.Max(0, result.OverkillDamage),
				CardExtraEffectResultMetric.Kills => result.WasTargetKilled ? 1 : 0,
				_ => Math.Max(0, result.UnblockedDamage)
			};

			if (total >= int.MaxValue)
			{
				return int.MaxValue;
			}
		}

		return ClampLongToInt(total);
	}

	internal static List<DamageResult> FlattenDamageResults(object? rawResults)
	{
		List<DamageResult> results = new();
		AddDamageResults(rawResults, results);
		return results;
	}

	private static void AddDamageResults(object? value, List<DamageResult> results)
	{
		if (value == null)
		{
			return;
		}

		if (value is DamageResult result)
		{
			results.Add(result);
			return;
		}

		if (value is System.Collections.IEnumerable enumerable && value is not string)
		{
			foreach (object? item in enumerable)
			{
				AddDamageResults(item, results);
			}
		}
	}

	private static int ResolveDynamicResultRepeatAdds(CardExtraEffect effect, int resultCount)
	{
		if (resultCount <= 0)
		{
			return 0;
		}

		if (effect.CountComparison != CardExtraEffectCountComparison.None
			&& !DoesCountConditionPass(resultCount, effect))
		{
			return 0;
		}

		int steps = resultCount / ResolveHistoryScalingCountStep(effect);
		if (steps <= 0)
		{
			return 0;
		}

		long repeats = (long)steps * ResolveRepeatScalingExtraTimes(effect);
		return repeats >= 99 ? 99 : (int)repeats;
	}

	private static async Task ExecuteDynamicResultRepeatDamage(
		CombatState combatState,
		PlayerChoiceContext choiceContext,
		CardPlay cardPlay,
		CardExtraEffect effect,
		Creature ownerCreature,
		int amount,
		int baseRepeats)
	{
		if (combatState == null || choiceContext == null || cardPlay?.Card == null || effect == null || ownerCreature == null || amount <= 0)
		{
			return;
		}

		int pending = Math.Clamp(baseRepeats <= 0 ? 1 : baseRepeats, 1, 99);
		int executed = 0;
		bool preserveSelfHp = CardHasRuntimeResourceConsumptionMode(cardPlay.Card, CardExtraEffectResourceConsumptionMode.SelfHpAndSelfDamage);

		// Result-derived amounts already include Strength/Vigor from the source hit — running
		// them powered double-dips. Self-damage never benefits from the owner's powers either.
		ValueProp damageProps = ValueProp.Move;
		if (UsesDamageResultAmountSource(effect) || GetEffectiveResolvedTarget(cardPlay, effect.Target) == CardExtraEffectTarget.Self)
		{
			damageProps |= ValueProp.Unpowered;
		}

		await using AttackContextLease attackContextLease = new AttackContextLease(combatState, choiceContext, cardPlay);
		while (pending > 0 && executed < 99)
		{
			pending--;
			executed++;

			// A dead dealer must stop, not deal: CreatureCmd.Damage synthesizes per-target
			// results for dead dealers, which would feed phantom hits into the context.
			if (!ownerCreature.IsAlive)
			{
				break;
			}

			List<Creature> targets = ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target)
				.Where(c => c != null && c.IsAlive)
				.ToList();
			if (preserveSelfHp)
			{
				targets = targets.Where(target => !ReferenceEquals(target, ownerCreature)).ToList();
			}
			if (targets.Count == 0)
			{
				continue;
			}

			AttackContext attackContext = await attackContextLease.Ensure();
			IEnumerable<DamageResult> rawResults = await CreatureCmd.Damage(choiceContext, targets, amount, damageProps, ownerCreature, cardPlay.Card, cardPlay);
			List<DamageResult> results = rawResults?.Where(r => r != null).ToList() ?? new List<DamageResult>();
			if (results.Count <= 0)
			{
				continue;
			}

			attackContext.AddHit(results);
			CardEditorEffectExecutionAmountContext.ReportCurrentDamageResults(results);
			int totalDamage = ClampLongToInt(results.Sum(r => (long)Math.Max(0, r.TotalDamage)));
			int blockedDamage = ClampLongToInt(results.Sum(r => (long)Math.Max(0, r.BlockedDamage)));
			int overkillDamage = ClampLongToInt(results.Sum(r => (long)Math.Max(0, r.OverkillDamage)));
			int damageInstances = results.Count(r => r.TotalDamage > 0);
			CardEditorEffectExecutionAmountContext.ReportCurrentDamageTotals(totalDamage, damageInstances, blockedDamage, overkillDamage);
			await RunFatalImmediatelyForDamageResultsIfNeeded(
				combatState,
				choiceContext,
				cardPlay,
				GetRuntimeEffectsIncludingBorrowedSources(combatState, cardPlay.Card),
				ownerCreature,
				results);

			int resultCount = GetDamageResultMetricAmount(results, effect.CountResultMetric);
			int addedRepeats = ResolveDynamicResultRepeatAdds(effect, resultCount);
			if (addedRepeats > 0)
			{
				pending = Math.Min(99 - executed, pending + addedRepeats);
			}
		}
	}

	private static async Task ExecuteOtherEnemiesDamage(
		CombatState combatState,
		PlayerChoiceContext choiceContext,
		CardPlay cardPlay,
		CardExtraEffect effect,
		Creature ownerCreature,
		int amount,
		int repeats,
		bool preserveSelfHp)
	{
		if (combatState == null || choiceContext == null || cardPlay?.Card == null || effect == null || ownerCreature == null || amount <= 0)
		{
			return;
		}

		int safeRepeats = Math.Clamp(repeats <= 0 ? 1 : repeats, 1, 99);
		ValueProp damageProps = UsesDamageResultAmountSource(effect)
			? ValueProp.Unpowered | ValueProp.Move
			: ValueProp.Move;

		await using AttackContextLease attackContextLease = new AttackContextLease(combatState, choiceContext, cardPlay);
		for (int repeatIndex = 0; repeatIndex < safeRepeats; repeatIndex++)
		{
			// A dead dealer must stop, not deal: CreatureCmd.Damage synthesizes per-target
			// results for dead dealers, which would feed phantom hits into the context.
			if (!ownerCreature.IsAlive)
			{
				break;
			}

			List<Creature> targets = ResolveTargets(combatState, ownerCreature, cardPlay, CardExtraEffectTarget.OtherEnemies)
				.Where(c => c != null && c.IsAlive)
				.ToList();
			if (preserveSelfHp)
			{
				targets = targets.Where(target => !ReferenceEquals(target, ownerCreature)).ToList();
			}
			if (targets.Count == 0)
			{
				continue;
			}

			AttackContext attackContext = await attackContextLease.Ensure();
			IEnumerable<DamageResult> rawResults = await CreatureCmd.Damage(choiceContext, targets, amount, damageProps, ownerCreature, cardPlay.Card, cardPlay);
			List<DamageResult> results = rawResults?.Where(r => r != null).ToList() ?? new List<DamageResult>();
			if (results.Count <= 0)
			{
				continue;
			}

			attackContext.AddHit(results);
			CardEditorEffectExecutionAmountContext.ReportCurrentDamageResults(results);
			int totalDamage = ClampLongToInt(results.Sum(r => (long)Math.Max(0, r.TotalDamage)));
			int blockedDamage = ClampLongToInt(results.Sum(r => (long)Math.Max(0, r.BlockedDamage)));
			int overkillDamage = ClampLongToInt(results.Sum(r => (long)Math.Max(0, r.OverkillDamage)));
			int damageInstances = results.Count(r => r.TotalDamage > 0);
			CardEditorEffectExecutionAmountContext.ReportCurrentDamageTotals(totalDamage, damageInstances, blockedDamage, overkillDamage);
			await RunFatalImmediatelyForDamageResultsIfNeeded(
				combatState,
				choiceContext,
				cardPlay,
				GetRuntimeEffectsIncludingBorrowedSources(combatState, cardPlay.Card),
				ownerCreature,
				results);
		}
	}

	private static bool UsesDamageResultAmountSource(CardExtraEffect effect)
	{
		return effect?.AmountSourceMode is CardExtraEffectAmountSourceMode.AppliedEffectHpDamage
			or CardExtraEffectAmountSourceMode.AppliedEffectBlockedDamage
			or CardExtraEffectAmountSourceMode.AppliedEffectTotalDamage
			or CardExtraEffectAmountSourceMode.AppliedEffectOverkillDamage
			or CardExtraEffectAmountSourceMode.AppliedEffectTotalAndOverkillDamage;
	}

	private static async Task ExecutePerTargetConditionalDamage(
		CombatState combatState,
		PlayerChoiceContext choiceContext,
		CardPlay cardPlay,
		CardExtraEffect effect,
		Creature ownerCreature,
		CardExtraEffectTarget targetMode,
		int repeats,
		int triggerEventAmount,
		bool preserveSelfHp)
	{
		if (combatState == null || choiceContext == null || cardPlay?.Card == null || effect == null || ownerCreature == null)
		{
			return;
		}

		int safeRepeats = Math.Clamp(repeats <= 0 ? 1 : repeats, 1, 99);
		ValueProp damageProps = UsesDamageResultAmountSource(effect)
			? ValueProp.Unpowered | ValueProp.Move
			: ValueProp.Move;

		await using AttackContextLease attackContextLease = new AttackContextLease(combatState, choiceContext, cardPlay);
		for (int repeatIndex = 0; repeatIndex < safeRepeats; repeatIndex++)
		{
			// A dead dealer must stop, not deal (phantom synthetic results otherwise).
			if (!ownerCreature.IsAlive)
			{
				break;
			}

			List<Creature> targets = ResolveTargets(combatState, ownerCreature, cardPlay, targetMode)
				.Where(c => c != null && c.IsAlive)
				.ToList();
			if (preserveSelfHp)
			{
				targets = targets.Where(target => !ReferenceEquals(target, ownerCreature)).ToList();
			}

			foreach (Creature target in targets)
			{
				CardPlay targetedPlay = BuildTargetedConditionCardPlay(cardPlay, target);
				if (!TryResolveExecutableEffectAmount(
					combatState,
					ownerCreature,
					targetedPlay,
					effect,
					triggerEventAmount,
					applyConditionalBonus: true,
					out int targetAmount)
					|| targetAmount <= 0)
				{
					continue;
				}

				AttackContext attackContext = await attackContextLease.Ensure();
				IEnumerable<DamageResult> rawResults = await CreatureCmd.Damage(choiceContext, target, targetAmount, damageProps, ownerCreature, cardPlay.Card, cardPlay);
				List<DamageResult> results = rawResults?.Where(r => r != null).ToList() ?? new List<DamageResult>();
				if (results.Count <= 0)
				{
					continue;
				}

				attackContext.AddHit(results);
				CardEditorEffectExecutionAmountContext.ReportCurrentDamageResults(results);
				int totalDamage = ClampLongToInt(results.Sum(r => (long)Math.Max(0, r.TotalDamage)));
				int blockedDamage = ClampLongToInt(results.Sum(r => (long)Math.Max(0, r.BlockedDamage)));
				int overkillDamage = ClampLongToInt(results.Sum(r => (long)Math.Max(0, r.OverkillDamage)));
				int damageInstances = results.Count(r => r.TotalDamage > 0);
				CardEditorEffectExecutionAmountContext.ReportCurrentDamageTotals(totalDamage, damageInstances, blockedDamage, overkillDamage);
				await RunFatalImmediatelyForDamageResultsIfNeeded(
					combatState,
					choiceContext,
					targetedPlay,
					GetRuntimeEffectsIncludingBorrowedSources(combatState, cardPlay.Card),
					ownerCreature,
					results);
			}
		}
	}

	private static async Task ExecuteEffectCore(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay, CardExtraEffect effect, int triggerEventAmount)
	{
		CardModel card = cardPlay.Card;
		Player? owner = card.Owner;
		if (owner == null)
		{
			return;
		}
		Creature ownerCreature = CardEditorPowerExecutionHostContext.Current ?? owner.Creature;
		if (ownerCreature == null)
		{
			return;
		}

		// Power-hosted auto-action rows (Whenever and other power triggers) dispatch to the same
		// shared runner the card-hosted triggers use — all 3 unified variants identically.
		// cardPlay.Card is already the HOST card (UsesSourceCardForImmediatePowerExecution); the
		// EffectSourceContext fallback covers scheduler entries executing against a snapshot
		// clone (the live host instance is pushed when the scheduled entry runs).
		if (IsSelfPileAutoEffectKind(effect.Kind))
		{
			CardExtraEffect? selfPileAuto = NormalizeSelfPileAutoEffect(effect);
			if (selfPileAuto != null)
			{
				CardModel autoHost = CardEditorEffectSourceContext.Current ?? card;
				await TryRunSelfPileAutoEffect(combatState, choiceContext, autoHost, selfPileAuto);
			}
			return;
		}

		if (effect.GrantToCard)
		{
			if (effect.Kind == CardExtraEffectKind.EnchantCard)
			{
				await EnchantSelectedCards(combatState, choiceContext, cardPlay, effect);
				return;
			}

			if (effect.Kind == CardExtraEffectKind.GrantReplay)
			{
				await GrantReplayToSelectedCards(combatState, choiceContext, cardPlay, effect);
				return;
			}

			await GrantEffectToCard(combatState, choiceContext, cardPlay, effect);
			return;
		}

		if (effect.Kind == CardExtraEffectKind.EnchantCard)
		{
			EnchantSourceCard(combatState, cardPlay, effect);
			return;
		}

		if (effect.Kind == CardExtraEffectKind.DisplayNumber)
		{
			return;
		}

		if (effect.Kind is CardExtraEffectKind.CardTypeCostsLess or CardExtraEffectKind.CardTypeStarCostsLess)
		{
			if (!TryResolveSignedAmountForCostEffect(combatState, ownerCreature, cardPlay, effect, out int signedAmount))
			{
				return;
			}

			CardExtraEffect resolved = CloneEffect(effect);
			resolved.Amount = signedAmount;
			resolved.AmountIsX = false;
			resolved.AmountXPlus = 0;
			CardEditorCardTypeCostAuras.Apply(combatState, owner, resolved);
			card.InvokeEnergyCostChanged();
			return;
		}

		if (effect.Kind is CardExtraEffectKind.DrawnCardsCostLess or CardExtraEffectKind.GeneratedCardsCostLess)
		{
			if (!TryResolveSignedAmountForCostEffect(combatState, ownerCreature, cardPlay, effect, out int signedAmount))
			{
				return;
			}

			CardExtraEffect resolved = CloneEffect(effect);
			resolved.Amount = signedAmount;
			resolved.AmountIsX = false;
			resolved.AmountXPlus = 0;
			CardEditorDrawnGeneratedCostController.Apply(combatState, owner, resolved);
			return;
		}

		if (effect.Kind is (CardExtraEffectKind.CardCostsLess or CardExtraEffectKind.CardStarCostsLess)
			&& !effect.GrantToCard
			&& IsTriggeredCardCostsLessDefinition(effect))
		{
			ApplyTriggeredCardCostsLess(combatState, card, effect, cardPlay);
			return;
		}

		if (effect.Kind == CardExtraEffectKind.LinkedCardAction)
		{
			await ApplyLinkedCardAction(combatState, choiceContext, cardPlay, effect, triggerEventAmount);
			return;
		}

		if (effect.Kind is CardExtraEffectKind.SelfScaling or CardExtraEffectKind.TargetCardMutation)
		{
			await ApplySelfScalingMutation(combatState, choiceContext, cardPlay, effect, triggerEventAmount);
			return;
		}

		if (effect.Kind is CardExtraEffectKind.PersistentSelfScaling or CardExtraEffectKind.PersistentTargetCardMutation)
		{
			await ApplyPersistentSelfScalingMutation(combatState, choiceContext, cardPlay, effect, triggerEventAmount);
			return;
		}

		if (effect.Kind == CardExtraEffectKind.ScalingStage)
		{
			if (!TryParseSpecificCardId(effect.SpecificCardId ?? string.Empty, out ModelId stageSourceId) || stageSourceId == ModelId.none)
			{
				return;
			}

			int stageCount = GetHistoryCountMultiplier(combatState, ownerCreature, cardPlay, effect);
			if (!DoesCountConditionPass(stageCount, effect))
			{
				return;
			}

			await CardEditorCreatedCardEffectSourceSupport.RunSingleEffectSourceOnPlay(
				card,
				choiceContext,
				cardPlay,
				stageSourceId,
				GetScalingStageRuntimeInstanceKey(card, effect),
				effect.CustomKeywordName);
			return;
		}

		if (effect.Kind == CardExtraEffectKind.StatefulTransform)
		{
			await ApplyStatefulTransform(combatState, choiceContext, cardPlay, effect);
			return;
		}

		if (effect.Kind == CardExtraEffectKind.EndTurn)
		{
			PlayerCmd.EndTurn(owner, canBackOut: false);
			return;
		}

		if (effect.Kind == CardExtraEffectKind.RunEffectSourceCard)
		{
			string? idStr = effect.SpecificCardId;
			if (string.IsNullOrWhiteSpace(idStr))
			{
				return;
			}

			if (!TryParseSpecificCardId(idStr, out ModelId sourceId) || sourceId == ModelId.none)
			{
				return;
			}

			int executionCount = ResolveRunEffectSourceExecutionCount(combatState, ownerCreature, cardPlay, effect);
			if (executionCount <= 0)
			{
				return;
			}

			string runtimeKeyBase = GetRunEffectSourceRuntimeInstanceKey(card, effect);
			for (int i = 0; i < executionCount; i++)
			{
				string runtimeKey = executionCount == 1
					? runtimeKeyBase
					: $"{runtimeKeyBase}|grant{i.ToString(CultureInfo.InvariantCulture)}";
				await CardEditorCreatedCardEffectSourceSupport.RunSingleEffectSourceOnPlay(
					card,
					choiceContext,
					cardPlay,
					sourceId,
					runtimeKey,
					effect.CustomKeywordName);
			}
			return;
		}

		if (effect.Kind == CardExtraEffectKind.ChooseOneEffectSource)
		{
			await ChooseOneEffectSourceCard(choiceContext, owner, card, cardPlay, effect);
			return;
		}

		if (effect.Kind == CardExtraEffectKind.ShuffleDrawPile)
		{
			await CardPileCmd.Shuffle(choiceContext, owner);
			return;
		}

		if (effect.Kind == CardExtraEffectKind.ResultPileOverride)
		{
			// Passive card-play result overrides are read by Hook.ModifyCardPlayResultLocation.
			return;
		}

		if (effect.Kind is CardExtraEffectKind.PlayPermission
			or CardExtraEffectKind.PlayPrevention
			or CardExtraEffectKind.ConditionalGlow
			or CardExtraEffectKind.Quest
			or CardExtraEffectKind.HoverPreview
			or CardExtraEffectKind.DynamicIdentity)
		{
			// Passive editor rules are evaluated by hook/render/hover patches instead of as direct commands.
			return;
		}

		bool deferConditionalBonusByTarget = ShouldApplyConditionalBonusPerResolvedTarget(effect, cardPlay);
		if (!TryResolveExecutableEffectAmount(
			combatState,
			ownerCreature,
			cardPlay,
			effect,
			triggerEventAmount,
			applyConditionalBonus: !deferConditionalBonusByTarget,
			out int amount))
		{
			return;
		}

		int repeats = ResolveRepeatCount(cardPlay, effect);
		if (repeats <= 0)
		{
			return;
		}

		int fallbackAppliedAmount = EstimateFallbackAppliedAmount(combatState, ownerCreature, cardPlay, effect, amount, repeats);
		int fallbackAppliedCount = EstimateFallbackAppliedCount(combatState, ownerCreature, cardPlay, effect, amount, repeats);
		using IDisposable amountScope = CardEditorEffectExecutionAmountContext.PushEffectScoped(effect, fallbackAppliedAmount, fallbackAppliedCount);

		// For damage, use a single AttackCommand with a hit-count so on-attack hooks (e.g. Vigor) behave like vanilla multi-hit cards.
		// Doing separate AttackCommands per repeat would consume "next attack" bonuses on the first hit only.
		if (effect.Kind == CardExtraEffectKind.DealDamage)
		{
			if (UsesCurrentEffectResultRepeat(effect))
			{
				await ExecuteDynamicResultRepeatDamage(combatState, choiceContext, cardPlay, effect, ownerCreature, amount, repeats);
				return;
			}

			bool preserveSelfHp = CardHasRuntimeResourceConsumptionMode(cardPlay.Card, CardExtraEffectResourceConsumptionMode.SelfHpAndSelfDamage);
			bool playAttackerAnim = card is CardEditorCreatedCardBase
				&& !IsPowerEffect(effect)
				&& !cardPlay.IsAutoPlay;
			CardExtraEffectTarget resolvedDamageTarget = GetEffectiveResolvedTarget(cardPlay, effect.Target);
			if (resolvedDamageTarget == CardExtraEffectTarget.OtherEnemies)
			{
				if (deferConditionalBonusByTarget)
				{
					await ExecutePerTargetConditionalDamage(
						combatState,
						choiceContext,
						cardPlay,
						effect,
						ownerCreature,
						CardExtraEffectTarget.OtherEnemies,
						repeats,
						triggerEventAmount,
						preserveSelfHp);
				}
				else
				{
					await ExecuteOtherEnemiesDamage(combatState, choiceContext, cardPlay, effect, ownerCreature, amount, repeats, preserveSelfHp);
				}
				return;
			}
			if (resolvedDamageTarget == CardExtraEffectTarget.AllEnemies && deferConditionalBonusByTarget)
			{
				await ExecutePerTargetConditionalDamage(
					combatState,
					choiceContext,
					cardPlay,
					effect,
					ownerCreature,
					CardExtraEffectTarget.AllEnemies,
					repeats,
					triggerEventAmount,
					preserveSelfHp);
				return;
			}

			SharedAttackContextHolder? sharedAttackHolder = GetSharedAttackContextHolder(cardPlay);
			if (sharedAttackHolder != null)
			{
				// Multi-damage-row plays share ONE attack context so latched powers
				// (Gigantification, Vigor) treat the whole card play as a single attack.
				await ExecuteDamageRowInSharedContext(combatState, choiceContext, cardPlay, effect, ownerCreature, amount, repeats, resolvedDamageTarget, preserveSelfHp, sharedAttackHolder);
				return;
			}

			var attack = DamageCmd.Attack(amount).FromCard(cardPlay.Card, cardPlay).WithHitCount(repeats);
			if (UsesDamageResultAmountSource(effect))
			{
				// "Damage equal to damage dealt" already includes Strength/Vigor from the source hit;
				// vanilla echo damage (Omnislice) is Unpowered so the bonuses are never added twice.
				attack.Unpowered();
			}
			if (!playAttackerAnim)
			{
				// Most vanilla Attack cards already play their own animation. Suppress animation here to avoid double-attacks.
				// For created/custom cards (which have no built-in OnPlay), allow the attack animation so the card feels "real".
				attack.WithNoAttackerAnim();
			}

			switch (resolvedDamageTarget)
			{
				case CardExtraEffectTarget.AllEnemies:
					attack.TargetingAllOpponentsCompat(combatState);
					break;
				case CardExtraEffectTarget.RandomEnemy:
					attack.TargetingRandomOpponentsCompat(combatState);
					break;
				case CardExtraEffectTarget.Self:
					if (preserveSelfHp)
					{
						return;
					}
					// Vanilla self-damage ("Take X damage", e.g. Burn) is never a powered attack:
					// your own Strength/Vigor must not scale it and it must not latch attack buffs.
					attack.Unpowered();
					attack.Targeting(ownerCreature);
					break;
				default:
				{
					Creature? resolvedTarget = ResolveSingleTarget(combatState, ownerCreature, cardPlay);
					if (resolvedTarget == null)
					{
						return;
					}
					if (preserveSelfHp && ReferenceEquals(resolvedTarget, ownerCreature))
					{
						return;
					}
					attack.Targeting(resolvedTarget);
					break;
				}
			}

			if (attack.IsSingleTargeted || attack.IsMultiTargeted)
			{
				await attack.Execute(choiceContext);
				List<DamageResult> results = FlattenDamageResults(attack.GetResultsCompat());
				if (results.Count > 0)
				{
					CardEditorEffectExecutionAmountContext.ReportCurrentDamageResults(results);
					int totalDamage = ClampLongToInt(results.Sum(r => (long)Math.Max(0, r.TotalDamage)));
					int blockedDamage = ClampLongToInt(results.Sum(r => (long)Math.Max(0, r.BlockedDamage)));
					int overkillDamage = ClampLongToInt(results.Sum(r => (long)Math.Max(0, r.OverkillDamage)));
					int damageInstances = results.Count(r => r.TotalDamage > 0);
					CardEditorEffectExecutionAmountContext.ReportCurrentDamageTotals(totalDamage, damageInstances, blockedDamage, overkillDamage);
					await RunFatalImmediatelyForDamageResultsIfNeeded(
						combatState,
						choiceContext,
						cardPlay,
						GetRuntimeEffectsIncludingBorrowedSources(combatState, cardPlay.Card),
						ownerCreature,
						results);
				}
			}
			return;
		}

		// Osty attacks: one AttackCommand with a hit count, exactly like vanilla multi-hit cards.
		// Running one command per repeat fires Hook.BeforeAttack/AfterAttack BETWEEN hits, so
		// once-per-attack reactions (Phantasmal Gardener's Skittish block, latched attack buffs)
		// interpose mid-flurry - vanilla resolves the whole flurry first, then reacts.
		if (effect.Kind == CardExtraEffectKind.OstyAction
			&& effect.OstyAction is CardExtraEffectOstyAction.Attack or CardExtraEffectOstyAction.AttackAll)
		{
			if (!Osty.CheckMissingWithAnim(owner))
			{
				if (effect.OstyAction == CardExtraEffectOstyAction.Attack)
				{
					Creature? ostyAttackTarget = ResolveSingleTarget(combatState, ownerCreature, cardPlay);
					if (ostyAttackTarget != null)
					{
						await DamageCmd.Attack(amount).FromOsty(owner.Osty!, cardPlay.Card, cardPlay).WithHitCount(repeats).Targeting(ostyAttackTarget).Execute(choiceContext);
					}
				}
				else
				{
					await DamageCmd.Attack(amount).FromOsty(owner.Osty!, cardPlay.Card, cardPlay).WithHitCount(repeats).TargetingAllOpponentsCompat(combatState).Execute(choiceContext);
				}
			}
			return;
		}

		for (int repeatIndex = 0; repeatIndex < repeats; repeatIndex++)
		{
		switch (effect.Kind)
		{
			case CardExtraEffectKind.GainBlock:
			{
				foreach (Creature target in ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target))
				{
					await CreatureCmd.GainBlock(target, amount, ValueProp.Move, cardPlay);
				}
				break;
			}
			case CardExtraEffectKind.MultiplyStatStatus:
			{
				foreach (Creature target in ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target))
				{
					await MultiplyStatStatus(target, effect, amount, ownerCreature, cardPlay.Card, cardPlay);
				}
				break;
			}
			case CardExtraEffectKind.LoseHp:
			{
				List<Creature> targets = ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target).Where(c => c != null).ToList();
				if (CardHasRuntimeResourceConsumptionMode(cardPlay.Card, CardExtraEffectResourceConsumptionMode.SelfHpAndSelfDamage))
				{
					targets = targets.Where(target => !ReferenceEquals(target, ownerCreature)).ToList();
				}
				if (targets.Count > 0)
				{
					// P5 value bus: LoseHp results feed the chain metrics like DealDamage's do -
					// "draw cards equal to Kills from row 1" now works off an HP-loss row.
					IEnumerable<DamageResult> loseHpRawResults = await CreatureCmd.Damage(choiceContext, targets, amount, DamageProps.cardHpLoss, ownerCreature, cardPlay.Card, cardPlay);
					List<DamageResult> loseHpResults = loseHpRawResults?.Where(r => r != null).ToList() ?? new List<DamageResult>();
					if (loseHpResults.Count > 0)
					{
						CardEditorEffectExecutionAmountContext.ReportCurrentDamageResults(loseHpResults);
						CardEditorEffectExecutionAmountContext.ReportCurrentDamageTotals(
							ClampLongToInt(loseHpResults.Sum(r => (long)Math.Max(0, r.TotalDamage))),
							loseHpResults.Count(r => r.TotalDamage > 0),
							ClampLongToInt(loseHpResults.Sum(r => (long)Math.Max(0, r.BlockedDamage))),
							ClampLongToInt(loseHpResults.Sum(r => (long)Math.Max(0, r.OverkillDamage))));
					}
				}
				break;
			}
			case CardExtraEffectKind.GainMaxHp:
			{
				await CreatureCmd.GainMaxHp(ownerCreature, amount);
				break;
			}
			case CardExtraEffectKind.LoseMaxHp:
			{
				await CreatureCmd.LoseMaxHp(choiceContext, ownerCreature, amount, isFromCard: true);
				break;
			}
			case CardExtraEffectKind.ApplyPower:
			{
				if (CardEditorCustomStatusRegistry.IsCustomStatusId(effect.PowerId))
				{
					foreach (Creature target in ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target))
					{
						bool targetAlreadyHadPower = TargetAlreadyHasCustomStatus(target, effect.PowerId);
						await ApplyCustomStatusPower(target, effect.PowerId, amount, ownerCreature, cardPlay.Card, effect);
						await TrackConfiguredPowerPersistence(combatState, target, effect.PowerId, amount, effect);
						await TrackConfiguredPowerDuration(combatState, target, effect.PowerId, amount, effect.Duration, targetAlreadyHadPower);
					}
					break;
				}

				if (!TryResolveConfiguredPowerModel(effect.PowerId, out PowerModel? canonical) || canonical == null)
				{
					break;
				}

				foreach (Creature target in ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target))
				{
					if (target == null)
					{
						continue;
					}
					bool targetAlreadyHadPower = TargetAlreadyHasPower(target, canonical);
					PowerModel power = canonical.ToMutable();
					ApplyDurationTickPolicy(power, effect, targetAlreadyHadPower);
					await PowerCmd.Apply(power, target, amount, ownerCreature, cardPlay.Card);
					// Re-apply AFTER Apply unconditionally: the engine sets SkipNextDurationTick for
					// fresh player-side debuffs inside Apply, which would clobber TickNormally.
					PowerModel? activePower = GetActivePowerById(target, power);
					if (activePower != null)
					{
						ApplyDurationTickPolicy(activePower, effect, targetAlreadyHadPower);
					}
					await TrackConfiguredPowerPersistence(combatState, target, effect.PowerId, amount, effect);
					await TrackConfiguredPowerDuration(combatState, target, effect.PowerId, amount, effect.Duration, targetAlreadyHadPower);
				}
				break;
			}
			case CardExtraEffectKind.RemovePower:
			{
				await RemoveConfiguredPowerFromTargets(combatState, ownerCreature, cardPlay, effect, amount);
				break;
			}
			case CardExtraEffectKind.CopyDebuffs:
			{
				await CopyDebuffsFromTarget(combatState, ownerCreature, cardPlay, effect);
				break;
			}
			case CardExtraEffectKind.CopyBuffs:
			{
				await CopyBuffsFromTarget(combatState, ownerCreature, cardPlay, effect);
				break;
			}
			case CardExtraEffectKind.ApplyMarked:
			{
				foreach (Creature markTarget in ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target))
				{
					if (markTarget != null && markTarget.IsAlive)
					{
						await PowerCmd.Apply<CardEditorMarkedPower>(markTarget, amount, ownerCreature, cardPlay?.Card);
					}
				}
				break;
			}
			case CardExtraEffectKind.ModifyActivePower:
			{
				await ModifyActivePowers(combatState, ownerCreature, cardPlay, effect, amount);
				break;
			}
			case CardExtraEffectKind.CountdownEffect:
			{
				await ScheduleCountdownEffectRows(combatState, cardPlay, effect, ownerCreature);
				break;
			}
			case CardExtraEffectKind.CreatureCommand:
			{
				foreach (Creature target in ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target))
				{
					if (target == null)
					{
						continue;
					}
					await ExecuteCreatureCommand(choiceContext, cardPlay, effect, amount, target);
				}
				break;
			}
			case CardExtraEffectKind.GainStatusEqualToStatus:
			{
				await GainStatusEqualToStatus(combatState, ownerCreature, cardPlay, effect, amount);
				break;
			}
			case CardExtraEffectKind.DrawCards:
			{
				int drawnCount = 0;
				foreach (Player targetPlayer in ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect))
				{
					drawnCount += (await DrawMatchingCards(choiceContext, targetPlayer, amount, effect)).Count;
				}
				CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(drawnCount);
				break;
			}
			case CardExtraEffectKind.DrawAndCheck:
			{
				bool drewMatch = false;
				foreach (Player checkPlayer in ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect))
				{
					foreach (CardModel drawnCard in await DrawMatchingCards(choiceContext, checkPlayer, amount, effect))
					{
						if (drawnCard != null && MatchesGeneratedCardType(drawnCard, effect.BranchCountCardType))
						{
							drewMatch = true;
						}
					}
				}
				if (drewMatch && _drawAndCheckBranchDepth < 5)
				{
					CardExtraEffect? drawBranch = GetUsableBranchEffect(effect);
					if (drawBranch != null)
					{
						_drawAndCheckBranchDepth++;
						try
						{
							await ExecuteEffect(combatState, choiceContext, cardPlay, drawBranch, _drawAndCheckBranchDepth, triggerEventAmount);
						}
						finally
						{
							_drawAndCheckBranchDepth--;
						}
					}
				}
				break;
			}
			case CardExtraEffectKind.DrawUntilHandSize:
			{
				int drawnToHand = 0;
				foreach (Player targetPlayer in ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect))
				{
					int handCount = targetPlayer?.PlayerCombatState?.Hand?.Cards?.Count ?? 0;
					int needed = amount - handCount;
					if (needed > 0)
					{
						drawnToHand += (await DrawMatchingCards(choiceContext, targetPlayer, needed, effect)).Count;
					}
				}
				CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(drawnToHand);
				break;
			}
			case CardExtraEffectKind.DrawCardsThatCostLess:
			{
				int drawnCount = 0;
				foreach (Player targetPlayer in ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect))
				{
					List<CardModel> drawnCards = await DrawMatchingCards(choiceContext, targetPlayer, amount, effect);
					drawnCount += drawnCards.Count;

					int costLess = effect.CardSelectionCount > 0 ? effect.CardSelectionCount : 1;
					if (costLess != 0)
					{
						foreach (CardModel drawnCard in drawnCards)
						{
							CardEditorDrawnGeneratedCostController.StampCostReductionForCard(combatState, drawnCard, effect, costLess);
							drawnCard.InvokeEnergyCostChanged();
						}
					}
				}
				CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(drawnCount);
				break;
			}
			case CardExtraEffectKind.GainEnergy:
			{
				foreach (Player targetPlayer in ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect))
				{
					await PlayerCmd.GainEnergy(amount, targetPlayer);
				}
				break;
			}
			case CardExtraEffectKind.LoseEnergy:
			{
				foreach (Player targetPlayer in ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect))
				{
					await PlayerCmd.LoseEnergy(amount, targetPlayer);
				}
				break;
			}
			case CardExtraEffectKind.GainStars:
			{
				foreach (Player targetPlayer in ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect))
				{
					await PlayerCmd.GainStars(amount, targetPlayer);
				}
				break;
			}
			case CardExtraEffectKind.LoseStars:
			{
				foreach (Player targetPlayer in ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect))
				{
					await PlayerCmd.LoseStars(amount, targetPlayer);
				}
				break;
			}
			case CardExtraEffectKind.Heal:
			{
				foreach (Creature target in ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target))
				{
					await CreatureCmd.Heal(target, amount);
				}
				break;
			}
			case CardExtraEffectKind.GainStrength:
			{
				await ApplyPowerWithDuration<StrengthPower, CardEditorTempStrengthTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.LoseStrength:
			{
				if (ShouldPreserveSelfProtectedStat(cardPlay, ownerCreature, effect.Target, CardExtraEffectMultiplierStat.Strength)
					|| ShouldPreserveSelfProtectedConfiguredPower(cardPlay, ownerCreature, effect.Target, ModelDb.GetId<StrengthPower>()))
				{
					break;
				}
				int delta = -amount;
				await ApplyPowerWithDuration<StrengthPower, CardEditorTempStrengthTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, delta, effect);
				break;
			}
			case CardExtraEffectKind.GainDexterity:
			{
				await ApplyPowerWithDuration<DexterityPower, CardEditorTempDexterityTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.LoseDexterity:
			{
				if (ShouldPreserveSelfProtectedStat(cardPlay, ownerCreature, effect.Target, CardExtraEffectMultiplierStat.Dexterity)
					|| ShouldPreserveSelfProtectedConfiguredPower(cardPlay, ownerCreature, effect.Target, ModelDb.GetId<DexterityPower>()))
				{
					break;
				}
				int delta = -amount;
				await ApplyPowerWithDuration<DexterityPower, CardEditorTempDexterityTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, delta, effect);
				break;
			}
			case CardExtraEffectKind.GainFocus:
			{
				await ApplyPowerWithDuration<FocusPower, CardEditorTempFocusTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.LoseFocus:
			{
				if (ShouldPreserveSelfProtectedStat(cardPlay, ownerCreature, effect.Target, CardExtraEffectMultiplierStat.Focus)
					|| ShouldPreserveSelfProtectedConfiguredPower(cardPlay, ownerCreature, effect.Target, ModelDb.GetId<FocusPower>()))
				{
					break;
				}
				int delta = -amount;
				await ApplyPowerWithDuration<FocusPower, CardEditorTempFocusTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, delta, effect);
				break;
			}
			case CardExtraEffectKind.ApplyWeak:
			{
				await ApplyPowerWithDuration<WeakPower, CardEditorTempWeakTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemoveWeak:
			{
				await RemovePowerFromTargets<WeakPower, CardEditorTempWeakTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.ApplyFrail:
			{
				await ApplyPowerWithDuration<FrailPower, CardEditorTempFrailTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemoveFrail:
			{
				await RemovePowerFromTargets<FrailPower, CardEditorTempFrailTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.ApplyVulnerable:
			{
				// Vanilla keeps SkipNextDurationTick even for self-applied debuffs (Doubt/Shame rely
				// on it), so Vulnerable uses the same pipeline as every other status — which also
				// restores duration tracking AND persistence handling dropped by the old special case.
				await ApplyPowerWithDuration<VulnerablePower, CardEditorTempVulnerableTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemoveVulnerable:
			{
				await RemovePowerFromTargets<VulnerablePower, CardEditorTempVulnerableTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.ApplyPoison:
			{
				await ApplyPowerWithDuration<PoisonPower, CardEditorTempPoisonTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemovePoison:
			{
				await RemovePowerFromTargets<PoisonPower, CardEditorTempPoisonTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.ApplyDoom:
			{
				await ApplyPowerWithDuration<DoomPower, CardEditorTempDoomTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemoveDoom:
			{
				await RemovePowerFromTargets<DoomPower, CardEditorTempDoomTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.GainArtifact:
			{
				await ApplyPowerWithDuration<ArtifactPower, CardEditorTempArtifactTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemoveArtifact:
			{
				await RemovePowerFromTargets<ArtifactPower, CardEditorTempArtifactTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.GainThorns:
			{
				await ApplyPowerWithDuration<ThornsPower, CardEditorTempThornsTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemoveThorns:
			{
				await RemovePowerFromTargets<ThornsPower, CardEditorTempThornsTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.GainRegen:
			{
				await ApplyPowerWithDuration<RegenPower, CardEditorTempRegenTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemoveRegen:
			{
				await RemovePowerFromTargets<RegenPower, CardEditorTempRegenTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.GainPlating:
			{
				await ApplyPowerWithDuration<PlatingPower, CardEditorTempPlatingTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemovePlating:
			{
				await RemovePowerFromTargets<PlatingPower, CardEditorTempPlatingTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.GainIntangible:
			{
				await ApplyPowerWithDuration<IntangiblePower, CardEditorTempIntangibleTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemoveIntangible:
			{
				await RemovePowerFromTargets<IntangiblePower, CardEditorTempIntangibleTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.GainBuffer:
			{
				await ApplyPowerWithDuration<BufferPower, CardEditorTempBufferTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemoveBuffer:
			{
				await RemovePowerFromTargets<BufferPower, CardEditorTempBufferTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.GainVigor:
			{
				await ApplyPowerWithDuration<VigorPower, CardEditorTempVigorTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemoveVigor:
			{
				await RemovePowerFromTargets<VigorPower, CardEditorTempVigorTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.GainBlur:
			{
				await ApplyPowerWithDuration<BlurPower, CardEditorTempBlurTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemoveBlur:
			{
				await RemovePowerFromTargets<BlurPower, CardEditorTempBlurTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.GainRitual:
			{
				await ApplyPowerWithDuration<RitualPower, CardEditorTempRitualTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemoveRitual:
			{
				await RemovePowerFromTargets<RitualPower, CardEditorTempRitualTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.ApplyConstrict:
			{
				await ApplyPowerWithDuration<ConstrictPower, CardEditorTempConstrictTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount, effect);
				break;
			}
			case CardExtraEffectKind.RemoveConstrict:
			{
				await RemovePowerFromTargets<ConstrictPower, CardEditorTempConstrictTrackerPower>(combatState, ownerCreature, cardPlay, effect.Target, amount);
				break;
			}
			case CardExtraEffectKind.CleanseDebuffs:
			{
				foreach (Creature target in ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target))
				{
					await CleanseDebuffs(target, ownerCreature, cardPlay.Card);
				}
				break;
			}
			case CardExtraEffectKind.CleanseBuffs:
			{
				foreach (Creature target in ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target))
				{
					await CleanseBuffs(target, ownerCreature, cardPlay.Card);
				}
				break;
			}
			case CardExtraEffectKind.AddRandomCardToHand:
			{
				CardModel? effectSourceCard = CardEditorEffectSourceContext.Current ?? cardPlay?.Card;
				await AddRandomCardsToHand(combatState, owner, cardPlay, amount, effect.GeneratedCardPool, effect.GeneratedCardType, effect, effectSourceCard);
				break;
			}
			case CardExtraEffectKind.ChooseOneOfThreeCardsToHand:
			{
				CardModel? effectSourceCard = CardEditorEffectSourceContext.Current ?? cardPlay?.Card;
				await ChooseOneOfThreeCardsToHand(combatState, choiceContext, owner, cardPlay, amount, effect.GeneratedCardPool, effect.GeneratedCardType, effect, effectSourceCard);
				break;
			}
			case CardExtraEffectKind.PlayRandomGeneratedCard:
			{
				CardModel? effectSourceCard = CardEditorEffectSourceContext.Current ?? cardPlay?.Card;
				await PlayRandomGeneratedCards(combatState, choiceContext, owner, amount, effect.GeneratedCardPool, effect.GeneratedCardType, effect, effectSourceCard);
				break;
			}
			case CardExtraEffectKind.CreateRandomPotion:
			{
				await CreatePotions(owner, effect, amount);
				break;
			}
			case CardExtraEffectKind.AddCardReward:
			{
				AddCombatCardReward(owner, effect, amount);
				break;
			}
			case CardExtraEffectKind.AddRelicReward:
			{
				AddCombatRelicReward(owner, amount);
				break;
			}
			case CardExtraEffectKind.Summon:
			{
				await OstyCmd.Summon(choiceContext, owner, amount, cardPlay.Card);
				break;
			}
			case CardExtraEffectKind.OstyAction:
			{
				if (!Osty.CheckMissingWithAnim(owner))
				{
					switch (effect.OstyAction)
					{
						case CardExtraEffectOstyAction.Attack:
						{
							Creature? attackTarget = ResolveSingleTarget(combatState, ownerCreature, cardPlay);
							if (attackTarget != null)
							{
								await DamageCmd.Attack(amount).FromOsty(owner.Osty, cardPlay.Card, cardPlay).Targeting(attackTarget).Execute(choiceContext);
							}
							break;
						}
						case CardExtraEffectOstyAction.AttackAll:
							await DamageCmd.Attack(amount).FromOsty(owner.Osty, cardPlay.Card, cardPlay).TargetingAllOpponentsCompat(combatState).Execute(choiceContext);
							break;
						case CardExtraEffectOstyAction.Heal:
							await CreatureCmd.Heal(owner.Osty, amount);
							break;
						case CardExtraEffectOstyAction.Kill:
							if (owner.IsOstyAlive)
							{
								await CreatureCmd.Kill(owner.Osty);
							}
							break;
					}
				}
				break;
			}
			case CardExtraEffectKind.Forge:
			{
				await ForgeCmd.Forge(amount, owner, cardPlay.Card);
				break;
			}
			case CardExtraEffectKind.ChannelLightning:
			{
				for (int i = 0; i < amount; i++)
				{
					await OrbCmd.Channel<LightningOrb>(choiceContext, owner);
				}
				break;
			}
			case CardExtraEffectKind.ChannelFrost:
			{
				for (int i = 0; i < amount; i++)
				{
					await OrbCmd.Channel<FrostOrb>(choiceContext, owner);
				}
				break;
			}
			case CardExtraEffectKind.ChannelDark:
			{
				for (int i = 0; i < amount; i++)
				{
					await OrbCmd.Channel<DarkOrb>(choiceContext, owner);
				}
				break;
			}
			case CardExtraEffectKind.ChannelPlasma:
			{
				for (int i = 0; i < amount; i++)
				{
					await OrbCmd.Channel<PlasmaOrb>(choiceContext, owner);
				}
				break;
			}
			case CardExtraEffectKind.ChannelGlass:
			{
				for (int i = 0; i < amount; i++)
				{
					await OrbCmd.Channel<GlassOrb>(choiceContext, owner);
				}
				break;
			}
			case CardExtraEffectKind.ChannelRandomOrb:
			{
				for (int i = 0; i < amount; i++)
				{
					OrbModel orb = OrbModel.GetRandomOrb(owner.RunState.Rng.CombatOrbGeneration).ToMutable();
					await OrbCmd.Channel(choiceContext, orb, owner);
				}
				break;
			}
			case CardExtraEffectKind.GainOrbSlots:
			{
				await OrbCmd.AddSlots(owner, amount);
				break;
			}
			case CardExtraEffectKind.LoseOrbSlots:
			{
				OrbCmd.RemoveSlots(owner, amount);
				break;
			}
			case CardExtraEffectKind.RemoveBlock:
			{
				foreach (Creature target in ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target))
				{
					if (target == null || target.Block <= 0)
					{
						continue;
					}
					if (cardPlay?.Card != null
						&& ownerCreature != null
						&& ReferenceEquals(target, ownerCreature)
						&& CardHasRuntimeProtectedMultiplierStat(cardPlay.Card, CardExtraEffectMultiplierStat.Block))
					{
						continue;
					}

					await CreatureCmd.LoseBlock(choiceContext, target, Math.Min((decimal)amount, target.Block), ownerCreature);
				}
				break;
			}
			case CardExtraEffectKind.MoveCardsBetweenPiles:
			{
				await MoveCardsBetweenPiles(choiceContext, owner, amount, effect, sourceCard: cardPlay?.Card);
				break;
			}
			case CardExtraEffectKind.DelayedPileAction:
			{
				CardModel? effectSourceCard = CardEditorEffectSourceContext.Current ?? cardPlay?.Card;
				await DelayedPileAction(choiceContext, combatState, owner, amount, effect, sourceCard: effectSourceCard);
				break;
			}
			case CardExtraEffectKind.UpgradeCardsInPile:
			{
				await UpgradeCardsInPile(choiceContext, combatState, owner, amount, effect, sourceCard: cardPlay?.Card);
				break;
			}
			case CardExtraEffectKind.DiscardCards:
			{
				await DiscardCards(choiceContext, owner, amount, effect, sourceCard: cardPlay?.Card);
				break;
			}
			case CardExtraEffectKind.ExhaustCards:
			{
				await ExhaustCards(choiceContext, owner, amount, effect, sourceCard: cardPlay?.Card);
				break;
			}
			case CardExtraEffectKind.TransformCards:
			{
				CardModel? transformSourceCard = CardEditorEffectSourceContext.Current ?? cardPlay?.Card;
				await TransformCards(choiceContext, owner, amount, effect, sourceCard: transformSourceCard);
				break;
			}
			case CardExtraEffectKind.EvokeOrbs:
			{
				// Vanilla multi-evoke (Dualcast/Multi-Cast/Quadcast) evokes the SAME rightmost orb
				// N times, dequeuing only on the final evoke — a lone Dark orb pays out N times.
				for (int i = 0; i < amount; i++)
				{
					await OrbCmd.EvokeNext(choiceContext, owner, dequeue: i == amount - 1);
				}
				break;
			}
			case CardExtraEffectKind.OrbAction:
			{
				if (effect.OrbAction == CardExtraEffectOrbAction.AddSlots)
				{
					await OrbCmd.AddSlots(owner, amount);
					break;
				}
				if (effect.OrbAction == CardExtraEffectOrbAction.RemoveSlots)
				{
					if (effect.OrbScope == CardExtraEffectOrbScope.All)
						OrbCmd.RemoveSlots(owner, owner.PlayerCombatState.OrbQueue.Capacity);
					else
						OrbCmd.RemoveSlots(owner, amount);
					break;
				}

				Creature? orbPassiveTarget = null;
				if (effect.OrbAction == CardExtraEffectOrbAction.TriggerPassive
					&& effect.Target == CardExtraEffectTarget.Target
					&& ownerCreature != null)
				{
					orbPassiveTarget = ResolveSingleTarget(combatState, ownerCreature, cardPlay);
				}

				if (effect.OrbScope == CardExtraEffectOrbScope.All
					&& (effect.OrbAction == CardExtraEffectOrbAction.Evoke
						|| effect.OrbAction == CardExtraEffectOrbAction.Remove
						|| effect.OrbAction == CardExtraEffectOrbAction.TriggerPassive))
				{
					await ExecuteOrbActionAll(choiceContext, owner, effect, orbPassiveTarget);
					break;
				}
				for (int i = 0; i < amount; i++)
				{
					if (effect.OrbAction == CardExtraEffectOrbAction.Channel)
					{
						await ChannelOrb(choiceContext, owner, effect);
						continue;
					}

					OrbModel? operatedOrb = await ExecuteOrbAction(choiceContext, owner, effect, orbPassiveTarget);
					if (operatedOrb == null)
					{
						break;
					}

					if (effect.OrbAction == CardExtraEffectOrbAction.Evoke
						&& effect.OrbFollowUp == CardExtraEffectOrbFollowUp.ChannelSameType)
					{
						OrbModel? followUpOrb = CreateOrbModelLike(operatedOrb);
						if (followUpOrb != null)
						{
							await OrbCmd.Channel(choiceContext, followUpOrb, owner);
						}
					}
				}
				break;
			}
			case CardExtraEffectKind.AddCopyOfThisCard:
			{
				await AddCopiesOfThisCard(cardPlay, amount, effect);
				break;
			}
			case CardExtraEffectKind.AddExactCopyOfThisCardToDeck:
			{
				await AddExactCopiesOfThisCardToDeck(cardPlay, amount);
				break;
			}
			case CardExtraEffectKind.CopyCardsFromPileToDeck:
			{
				await CopyCardsFromPileToDeck(choiceContext, owner, cardPlay, amount, effect, sourceCard: cardPlay?.Card);
				break;
			}
			case CardExtraEffectKind.CopyExactCardsFromPileToDeck:
			{
				await CopyCardsFromPileToDeck(choiceContext, owner, cardPlay, amount, effect, sourceCard: cardPlay?.Card, exact: true);
				break;
			}
			case CardExtraEffectKind.SelectCardsFromPile:
			{
				await SelectCardsFromPile(choiceContext, owner, amount, effect, sourceCard: cardPlay?.Card);
				break;
			}
			case CardExtraEffectKind.RemoveCardsFromDeck:
			{
				await RemoveCardsFromDeck(choiceContext, owner, amount, effect, sourceCard: cardPlay?.Card);
				break;
			}
			case CardExtraEffectKind.AddSpecificCardToHand:
			{
				CardModel? effectSourceCard = CardEditorEffectSourceContext.Current ?? cardPlay?.Card;
				await AddSpecificCardsToHand(combatState, owner, cardPlay, amount, effect, effectSourceCard);
				break;
			}
			case CardExtraEffectKind.FetchSpecificCardToHand:
			{
				await FetchSpecificCardsToHand(combatState, owner, amount, effect, cardPlay?.Card);
				break;
			}
			case CardExtraEffectKind.PlayCardFromPile:
			{
				CardModel? effectSourceCard = CardEditorEffectSourceContext.Current ?? cardPlay?.Card;
				await PlayCardsFromPile(combatState, choiceContext, owner, amount, effect, sourceCard: effectSourceCard);
				break;
			}
			case CardExtraEffectKind.ConsumeCardValue:
			{
				CardModel? effectSourceCard = CardEditorEffectSourceContext.Current ?? cardPlay?.Card;
				await ConsumeCardValue(combatState, choiceContext, owner, cardPlay, amount, effect, sourceCard: effectSourceCard);
				break;
			}
			case CardExtraEffectKind.CardTypeCostsLess:
			case CardExtraEffectKind.CardTypeStarCostsLess:
			{
				foreach (Player targetPlayer in ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect))
				{
					CardEditorCardTypeCostAuras.Apply(combatState, targetPlayer, effect);
				}
				break;
			}
			case CardExtraEffectKind.DrawnCardsCostLess:
			case CardExtraEffectKind.GeneratedCardsCostLess:
			{
				foreach (Player targetPlayer in ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect))
				{
					CardEditorDrawnGeneratedCostController.Apply(combatState, targetPlayer, effect);
				}
				break;
			}
			case CardExtraEffectKind.GeneratedCardsUpgraded:
			case CardExtraEffectKind.CardsInPileUpgradedAura:
			{
				foreach (Player targetPlayer in ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect))
				{
					CardEditorUpgradeAuraController.Apply(combatState, targetPlayer, effect);
				}
				break;
			}
			case CardExtraEffectKind.CardCostsLess:
			case CardExtraEffectKind.CardStarCostsLess:
			case CardExtraEffectKind.IgnoreBlock:
			case CardExtraEffectKind.IgnoreDamageModifiers:
			case CardExtraEffectKind.IgnoreDamageCaps:
			case CardExtraEffectKind.IgnoreDamageNegation:
			case CardExtraEffectKind.IgnoreEnemyDamageReductions:
			case CardExtraEffectKind.HitsAllEnemies:
			{
				break;
			}
			case CardExtraEffectKind.GrantKeywordToPile:
			{
				// Honor the effect target instead of always using the caster's own hand. ResolveTargetPlayers
				// returns [owner] for Self, the chosen ally for AnyAlly/AnyPlayer/AllAllies, and no players for
				// enemy targets (grant becomes a no-op - you cannot grant a keyword into an enemy's pile). The
				// card selection uses the shared RunState RNG / synced player choice, so this stays MP-safe.
				foreach (Player targetPlayer in ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect))
				{
					await GrantKeywordToCards(choiceContext, combatState, targetPlayer, amount, effect, sourceCard: cardPlay?.Card);
				}
				break;
			}
			case CardExtraEffectKind.GainGold:
			{
				foreach (Player targetPlayer in ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect))
				{
					PlayerCmd.GainGold(amount, targetPlayer);
				}
				break;
			}
			case CardExtraEffectKind.LoseGold:
			{
				foreach (Player targetPlayer in ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect))
				{
					await PlayerCmd.LoseGold(amount, targetPlayer);
				}
				break;
			}
			case CardExtraEffectKind.UpgradeDeckCards:
			{
				await UpgradeDeckCards(owner, amount, effect);
				break;
			}
		}
		}
	}

	private static async Task ChannelOrb(PlayerChoiceContext choiceContext, Player player, CardExtraEffect effect)
	{
		switch (effect.OrbType)
		{
			case CardExtraEffectOrbType.Lightning:
				await OrbCmd.Channel<LightningOrb>(choiceContext, player);
				break;
			case CardExtraEffectOrbType.Frost:
				await OrbCmd.Channel<FrostOrb>(choiceContext, player);
				break;
			case CardExtraEffectOrbType.Dark:
				await OrbCmd.Channel<DarkOrb>(choiceContext, player);
				break;
			case CardExtraEffectOrbType.Plasma:
				await OrbCmd.Channel<PlasmaOrb>(choiceContext, player);
				break;
			case CardExtraEffectOrbType.Glass:
				await OrbCmd.Channel<GlassOrb>(choiceContext, player);
				break;
			default:
			{
				OrbModel orb = OrbModel.GetRandomOrb(player.RunState.Rng.CombatOrbGeneration).ToMutable();
				await OrbCmd.Channel(choiceContext, orb, player);
				break;
			}
		}
	}

	private static async Task<OrbModel?> ExecuteOrbAction(PlayerChoiceContext choiceContext, Player player, CardExtraEffect effect)
		=> await ExecuteOrbAction(choiceContext, player, effect, passiveTarget: null);

	private static async Task<OrbModel?> ExecuteOrbAction(PlayerChoiceContext choiceContext, Player player, CardExtraEffect effect, Creature? passiveTarget)
	{
		OrbModel? orb = SelectOrb(player, effect);
		if (orb == null)
		{
			return null;
		}

		if (effect.OrbAction == CardExtraEffectOrbAction.Remove)
		{
			RemoveOrb(player, orb);
			return orb;
		}
		if (effect.OrbAction == CardExtraEffectOrbAction.TriggerPassive)
		{
			await TriggerOrbPassive(choiceContext, orb, passiveTarget);
			return orb;
		}

		await EvokeOrb(choiceContext, player, orb);
		return orb;
	}

	private static OrbModel? SelectOrb(Player player, CardExtraEffect effect)
	{
		if (player?.PlayerCombatState?.OrbQueue?.Orbs == null)
		{
			return null;
		}

		List<OrbModel> matchingOrbs = player.PlayerCombatState.OrbQueue.Orbs
			.Where(orb => orb != null && OrbMatchesType(orb, effect.OrbType))
			.ToList();

		if (matchingOrbs.Count == 0)
		{
			return null;
		}

		return effect.OrbSelection switch
		{
			CardExtraEffectOrbSelection.Rightmost => matchingOrbs[0],
			CardExtraEffectOrbSelection.Middle => matchingOrbs[(matchingOrbs.Count - 1) / 2],
			_ => matchingOrbs[matchingOrbs.Count - 1]
		};
	}

	private static bool OrbMatchesType(OrbModel orb, CardExtraEffectOrbType type)
	{
		return type switch
		{
			CardExtraEffectOrbType.Lightning => orb is LightningOrb,
			CardExtraEffectOrbType.Frost => orb is FrostOrb,
			CardExtraEffectOrbType.Dark => orb is DarkOrb,
			CardExtraEffectOrbType.Plasma => orb is PlasmaOrb,
			CardExtraEffectOrbType.Glass => orb is GlassOrb,
			_ => true
		};
	}

	private static async Task EvokeOrb(PlayerChoiceContext choiceContext, Player player, OrbModel orb)
	{
		if (CombatManager.Instance.IsOverOrEnding)
		{
			return;
		}

		var orbQueue = player.PlayerCombatState.OrbQueue;
		if (!orbQueue.Remove(orb))
		{
			return;
		}

		NCombatRoom.Instance?.GetCreatureNode(player.Creature)?.OrbManager?.EvokeOrbAnim(orb);
		choiceContext.PushModel(orb);
		IEnumerable<Creature> targets = await orb.Evoke(choiceContext);
		choiceContext.PopModel(orb);
		await Hook.AfterOrbEvoked(choiceContext, player.Creature.GetConcreteCombatState(), orb, targets);
		orb.RemoveInternal();
	}

	private static async Task TriggerOrbPassive(PlayerChoiceContext choiceContext, OrbModel orb, Creature? target)
	{
		if (CombatManager.Instance.IsOverOrEnding)
		{
			return;
		}

		if (choiceContext == null || orb == null)
		{
			return;
		}

		// Most orb passives cannot target a creature; Lightning is the exception.
		if (orb is not LightningOrb)
		{
			target = null;
		}

		await OrbCmd.Passive(choiceContext, orb, target);
	}

	private static void RemoveOrb(Player player, OrbModel orb)
	{
		if (CombatManager.Instance.IsOverOrEnding)
		{
			return;
		}

		var orbQueue = player.PlayerCombatState.OrbQueue;
		if (!orbQueue.Remove(orb))
		{
			return;
		}

		NCombatRoom.Instance?.GetCreatureNode(player.Creature)?.OrbManager?.EvokeOrbAnim(orb);
		orb.RemoveInternal();
	}

	private static async Task ExecuteOrbActionAll(PlayerChoiceContext choiceContext, Player player, CardExtraEffect effect, Creature? passiveTarget)
	{
		List<OrbModel> orbs = player.PlayerCombatState.OrbQueue.Orbs
			.Where(orb => orb != null && OrbMatchesType(orb, effect.OrbType))
			.ToList();

		foreach (OrbModel orb in orbs)
		{
			if (effect.OrbAction == CardExtraEffectOrbAction.Remove)
			{
				RemoveOrb(player, orb);
			}
			else if (effect.OrbAction == CardExtraEffectOrbAction.TriggerPassive)
			{
				await TriggerOrbPassive(choiceContext, orb, passiveTarget);
			}
			else
			{
				await EvokeOrb(choiceContext, player, orb);
				if (effect.OrbFollowUp == CardExtraEffectOrbFollowUp.ChannelSameType)
				{
					OrbModel? followUpOrb = CreateOrbModelLike(orb);
					if (followUpOrb != null)
					{
						await OrbCmd.Channel(choiceContext, followUpOrb, player);
					}
				}
			}
		}
	}

	private static OrbModel? CreateOrbModelLike(OrbModel orb)
	{
		return orb switch
		{
			LightningOrb => ModelDb.Orb<LightningOrb>().ToMutable(),
			FrostOrb => ModelDb.Orb<FrostOrb>().ToMutable(),
			DarkOrb => ModelDb.Orb<DarkOrb>().ToMutable(),
			PlasmaOrb => ModelDb.Orb<PlasmaOrb>().ToMutable(),
			GlassOrb => ModelDb.Orb<GlassOrb>().ToMutable(),
			_ => null
		};
	}

	private static void EnchantSourceCard(CombatState combatState, CardPlay cardPlay, CardExtraEffect effect)
	{
		CardModel? card = cardPlay?.Card;
		if (combatState == null || card == null || effect == null)
		{
			return;
		}
		if (!TryResolveEffectEnchantmentId(effect, out ModelId enchantmentId))
		{
			return;
		}

		int amount = effect.AmountIsX
			? ResolveXAmountWithPlus(cardPlay, effect.AmountXPlus)
			: effect.Amount;
		if (amount <= 0)
		{
			return;
		}
		if (!CanEffectEnchantmentApplyToCard(enchantmentId, card))
		{
			return;
		}

		Creature? ownerCreature = card.TryGetOwnerCreature();
		if (ownerCreature == null)
		{
			return;
		}

		if (effect.ScaleMode != CardExtraEffectScaleMode.None)
		{
			int multiplier = GetHistoryCountMultiplier(combatState, ownerCreature, cardPlay, effect);
			if (!DoesCountConditionPass(multiplier, effect))
			{
				return;
			}

			if (effect.ScaleMode == CardExtraEffectScaleMode.ConditionOnly)
			{
				multiplier = 1;
			}

			if (effect.ScaleMode == CardExtraEffectScaleMode.PerHistoryCount)
			{
				int scalingMultiplier = ResolveHistoryScalingMultiplier(effect, multiplier);
				if (scalingMultiplier <= 0 && !effect.HistoryScalingIncludesBase)
				{
					return;
				}

				long scaled = (long)amount * scalingMultiplier;
				long total = effect.HistoryScalingIncludesBase
					? (long)ResolveHistoryScalingBaseAmount(effect, amount) + scaled
					: scaled;
				amount = total >= int.MaxValue ? int.MaxValue : (int)total;
				if (amount <= 0)
				{
					return;
				}
			}
		}

		CardEditorTemporaryEnchantmentController.Apply(combatState, card, enchantmentId, amount, effect.EnchantmentDuration, effect.EnchantmentTurns);
	}

	private static async Task EnchantSelectedCards(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay, CardExtraEffect effect)
	{
		if (combatState == null || choiceContext == null || cardPlay?.Card?.Owner == null || effect == null)
		{
			return;
		}
		if (!TryResolveEffectEnchantmentId(effect, out ModelId enchantmentId))
		{
			return;
		}

		CardModel sourceCard = cardPlay.Card;
		Player owner = sourceCard.Owner;

		List<CardModel> candidates;
		if (effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles)
		{
			HashSet<CardModel> unique = new HashSet<CardModel>(ReferenceEqualityComparer<CardModel>.Instance);
			foreach (PileType pileType in new[] { PileType.Hand, PileType.Draw, PileType.Discard, PileType.Exhaust })
			{
				CardPile? pile = pileType.GetPile(owner);
				if (pile == null)
				{
					continue;
				}
				foreach (CardModel card in pile.Cards)
				{
					if (card == null || ReferenceEquals(card, sourceCard))
					{
						continue;
					}
					if (!MatchesCardSelectionFilters(owner, card, effect))
					{
						continue;
					}
					if (!CanEffectEnchantmentApplyToCard(enchantmentId, card))
					{
						continue;
					}
					unique.Add(card);
				}
			}
			candidates = unique.ToList();
		}
		else
		{
			PileType fromPileType = ResolvePileType(effect.CardSelectionPile);
			CardPile fromPile = fromPileType.GetPile(owner);
			if (fromPile == null)
			{
				return;
			}

			candidates = fromPile.Cards
				.Where(c => c != null && !ReferenceEquals(c, sourceCard))
				.Where(c => MatchesCardSelectionFilters(owner, c, effect))
				.Where(c => CanEffectEnchantmentApplyToCard(enchantmentId, c))
				.ToList();
		}
		if (candidates.Count == 0)
		{
			return;
		}

		int desiredCount = effect.CardSelectionCountIsX ? ResolveXAmountWithPlus(cardPlay, effect.CardSelectionCount) : effect.CardSelectionCount;
		desiredCount = Math.Clamp(desiredCount, 0, 99);

		List<CardModel> selected;
		if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All)
		{
			selected = candidates;
		}
		else if (effect.CardSelectionMode is CardExtraEffectCardSelectionMode.RandomOffer
			or CardExtraEffectCardSelectionMode.TopOffer)
		{
			if (desiredCount <= 0)
			{
				return;
			}
			PileType selectorPileType = effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles
				? PileType.None
				: ResolvePileType(effect.CardSelectionPile);
			selected = await SelectCardsFromCandidates(
				choiceContext,
				owner,
				candidates,
				Math.Min(desiredCount, candidates.Count),
				effect.CardSelectionMode,
				selectorPileType,
				new LocString("gameplay_ui", "CHOOSE_CARD_HEADER"),
				sourceCard,
				ShouldExcludeSourceCardFromSelection(effect),
				preferHandDiscardSelector: false,
				owner.RunState?.Rng?.CombatCardSelection,
				ResolveCardSelectionOfferCount(effect, cardPlay, Math.Min(desiredCount, candidates.Count)));
		}
		else if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.Random)
		{
			if (desiredCount <= 0)
			{
				return;
			}
			selected = PickRandomDistinct(candidates, Math.Min(desiredCount, candidates.Count), owner.RunState?.Rng?.CombatCardSelection);
		}
		else if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.UpTo)
		{
			if (desiredCount <= 0)
			{
				return;
			}
			int maxCount = Math.Min(desiredCount, candidates.Count);
			CardSelectorPrefs prefs = new CardSelectorPrefs(new LocString("gameplay_ui", "CHOOSE_CARD_HEADER"), 0, maxCount) { Cancelable = true };
			selected = (await CardSelectCmd.FromSimpleGrid(choiceContext, candidates, owner, prefs)).OfType<CardModel>().ToList();
		}
		else
		{
			if (desiredCount <= 0)
			{
				return;
			}
			CardSelectorPrefs prefs = new CardSelectorPrefs(new LocString("gameplay_ui", "CHOOSE_CARD_HEADER"), Math.Min(desiredCount, candidates.Count));
			selected = (await CardSelectCmd.FromSimpleGrid(choiceContext, candidates, owner, prefs)).OfType<CardModel>().ToList();
		}

		if (selected.Count == 0)
		{
			return;
		}

		int amount = effect.AmountIsX
			? ResolveXAmountWithPlus(cardPlay, effect.AmountXPlus)
			: effect.Amount;
		if (amount <= 0)
		{
			return;
		}

		Creature? ownerCreature = owner.Creature;
		if (ownerCreature == null)
		{
			return;
		}

		if (effect.ScaleMode != CardExtraEffectScaleMode.None)
		{
			int multiplier = GetHistoryCountMultiplier(combatState, ownerCreature, cardPlay, effect);
			if (!DoesCountConditionPass(multiplier, effect))
			{
				return;
			}

			if (effect.ScaleMode == CardExtraEffectScaleMode.ConditionOnly)
			{
				multiplier = 1;
			}

			if (effect.ScaleMode == CardExtraEffectScaleMode.PerHistoryCount)
			{
				int scalingMultiplier = ResolveHistoryScalingMultiplier(effect, multiplier);
				if (scalingMultiplier <= 0 && !effect.HistoryScalingIncludesBase)
				{
					return;
				}

				long scaled = (long)amount * scalingMultiplier;
				long total = effect.HistoryScalingIncludesBase
					? (long)ResolveHistoryScalingBaseAmount(effect, amount) + scaled
					: scaled;
				amount = total >= int.MaxValue ? int.MaxValue : (int)total;
				if (amount <= 0)
				{
					return;
				}
			}
		}

		foreach (CardModel card in selected)
		{
			if (card == null)
			{
				continue;
			}
			if (!CanEffectEnchantmentApplyToCard(enchantmentId, card))
			{
				continue;
			}

			CardEditorTemporaryEnchantmentController.Apply(combatState, card, enchantmentId, amount, effect.EnchantmentDuration, effect.EnchantmentTurns);
		}
	}

	private static async Task GrantReplayToSelectedCards(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay, CardExtraEffect effect)
	{
		if (combatState == null || choiceContext == null || cardPlay?.Card?.Owner == null || effect == null)
		{
			return;
		}

		CardModel sourceCard = cardPlay.Card;
		Player owner = sourceCard.Owner;
		bool useFutureAura = effect.FutureMatchingCards && effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All;

		List<CardModel> candidates = GetCandidatesFromConfiguredPile(
			owner,
			effect,
			sourceCard,
			includeDeck: false,
			requireDeckVersion: false,
			includeCostFilter: true)
			.Where(card => card != null && !card.Keywords.Contains(effect.GrantedKeyword))
			.ToList();
		if (candidates.Count == 0 && !useFutureAura)
		{
			return;
		}

		int desiredCount = effect.CardSelectionCountIsX ? ResolveXAmountWithPlus(cardPlay, effect.CardSelectionCount) : effect.CardSelectionCount;
		desiredCount = Math.Clamp(desiredCount, 0, 99);

		PileType fromPileType = effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles
			? PileType.None
			: ResolvePileType(effect.CardSelectionPile);
		List<CardModel> selected = candidates.Count == 0
			? new List<CardModel>()
			: await SelectCardsFromCandidates(
				choiceContext,
				owner,
				candidates,
				Math.Min(desiredCount, candidates.Count),
				effect.CardSelectionMode,
				fromPileType,
				new LocString("gameplay_ui", "CHOOSE_CARD_HEADER"),
				sourceCard,
				ShouldExcludeSourceCardFromSelection(effect),
				preferHandDiscardSelector: false,
				owner.RunState?.Rng?.CombatCardSelection,
				ResolveCardSelectionOfferCount(effect, cardPlay, Math.Min(desiredCount, candidates.Count)));

		if (selected.Count == 0 && !useFutureAura)
		{
			return;
		}

		int amount = effect.AmountIsX
			? ResolveXAmountWithPlus(cardPlay, effect.AmountXPlus)
			: effect.Amount;
		if (amount == 0)
		{
			return;
		}

		Creature? ownerCreature = owner.Creature;
		if (ownerCreature == null)
		{
			return;
		}

		if (effect.ScaleMode != CardExtraEffectScaleMode.None)
		{
			int multiplier = GetHistoryCountMultiplier(combatState, ownerCreature, cardPlay, effect);
			if (!DoesCountConditionPass(multiplier, effect))
			{
				return;
			}

			if (effect.ScaleMode == CardExtraEffectScaleMode.ConditionOnly)
			{
				multiplier = 1;
			}

			if (effect.ScaleMode == CardExtraEffectScaleMode.PerHistoryCount)
			{
				int scalingMultiplier = ResolveHistoryScalingMultiplier(effect, multiplier);
				if (scalingMultiplier <= 0 && !effect.HistoryScalingIncludesBase)
				{
					return;
				}

				long scaled = (long)amount * scalingMultiplier;
				long total = effect.HistoryScalingIncludesBase
					? (long)ResolveHistoryScalingBaseAmount(effect, amount) + scaled
					: scaled;
				amount = total >= int.MaxValue ? int.MaxValue : (int)total;
				if (amount == 0)
				{
					return;
				}
			}
		}

		if (useFutureAura)
		{
			CardEditorMatchingCardAuraController.ApplyReplayAura(combatState, owner, effect, sourceCard, selected, amount);
			return;
		}

		foreach (CardModel card in selected)
		{
			if (card == null)
			{
				continue;
			}

			CardEditorTemporaryReplayController.Apply(combatState, card, amount, effect.CardGrantDuration, effect.CardGrantTurns);

			try
			{
				card.InvokeEnergyCostChanged();

				NCard? node = NCard.FindOnTable(card);
				if (node != null)
				{
					node.UpdateVisuals(node.DisplayingPile, CardPreviewMode.Normal);
				}
			}
			catch
			{
				// ignored
			}
		}
	}

	private static bool CanEffectEnchantmentApplyToCard(ModelId enchantmentId, CardModel card)
	{
		if (card == null || enchantmentId == ModelId.none)
		{
			return false;
		}

		EnchantmentModel? enchantment = ModelDb.GetByIdOrNull<EnchantmentModel>(enchantmentId);
		return enchantment != null && enchantment.CanEnchant(card);
	}

	private static async Task GrantEffectToCard(CombatState combatState, PlayerChoiceContext choiceContext, CardPlay cardPlay, CardExtraEffect effect)
	{
		if (combatState == null || choiceContext == null || cardPlay?.Card?.Owner == null || effect == null)
		{
			return;
		}

		CardModel sourceCard = cardPlay.Card;
		Player owner = sourceCard.Owner;
		bool useFutureAura = effect.FutureMatchingCards && effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All;

		List<CardModel> candidates = GetCandidatesFromConfiguredPile(
			owner,
			effect,
			sourceCard,
			includeDeck: false,
			requireDeckVersion: false,
			includeCostFilter: false);
		if (candidates.Count == 0 && !useFutureAura)
		{
			return;
		}

		int desiredCount = effect.CardSelectionCountIsX ? ResolveXAmountWithPlus(cardPlay, effect.CardSelectionCount) : effect.CardSelectionCount;
		desiredCount = Math.Clamp(desiredCount, 0, 99);

		PileType fromPileType = effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles
			? PileType.None
			: ResolvePileType(effect.CardSelectionPile);
		List<CardModel> selected = candidates.Count == 0
			? new List<CardModel>()
			: await SelectCardsFromCandidates(
				choiceContext,
				owner,
				candidates,
				Math.Min(desiredCount, candidates.Count),
				effect.CardSelectionMode,
				fromPileType,
				new LocString("gameplay_ui", "CHOOSE_CARD_HEADER"),
				sourceCard,
				ShouldExcludeSourceCardFromSelection(effect),
				preferHandDiscardSelector: false,
				owner.RunState?.Rng?.CombatCardSelection,
				ResolveCardSelectionOfferCount(effect, cardPlay, Math.Min(desiredCount, candidates.Count)));

		if (selected.Count == 0 && !useFutureAura)
		{
			return;
		}

		if (useFutureAura)
		{
			CardEditorMatchingCardAuraController.ApplyExtraEffectAura(combatState, owner, effect, sourceCard, selected);
			return;
		}

		foreach (CardModel card in selected)
		{
			if (card == null)
			{
				continue;
			}

			CardExtraEffect effectToGrant = CloneEffectForGrantPayload(effect);
			EnsureGrantPackageKey(effectToGrant);
			if (ShouldSkipKeywordPackageGrantToCard(card, effectToGrant))
			{
				CardEditorMod.VerboseLog($"[CardEditor][TempEffectGrant] keyword package duplicate ignored card={card.Id} package={GetCanonicalGrantPackageKey(effectToGrant)}");
				continue;
			}

			if (IsSelfScalingKind(effect.Kind))
			{
				effectToGrant.SelfScalingRecipientMode = CardExtraEffectSelfScalingRecipientMode.ThisCard;
			}
			CardEditorTemporaryExtraEffectController.Grant(
				combatState,
				card,
				effectToGrant,
				effect.CardGrantDuration,
				effect.CardGrantTurns);
			try
			{
				card.InvokeEnergyCostChanged();

				NCard? node = NCard.FindOnTable(card);
				if (node != null)
				{
					node.UpdateVisuals(node.DisplayingPile, CardPreviewMode.Normal);
				}
			}
			catch
			{
				// ignored
			}
		}
	}

	private static CardExtraEffect GetGrantPayloadViewEffect(CardExtraEffect effect)
	{
		return effect != null && effect.GrantToCard
			? CloneEffectForGrantPayload(effect)
			: effect;
	}

	private static CardExtraEffect CloneEffectForGrantPayload(CardExtraEffect source)
	{
		CardExtraEffect payload = CloneEffect(source);
		payload.GrantToCard = false;
		NormalizeGrantedPayloadSelection(payload);
		return payload;
	}

	// P4: pile/deck-action payloads KEEP their authored selection filters when granted - the old
	// unconditional strip turned "discard a Skill" into "discard any card" and, for removals,
	// "remove all Curses" into "remove your whole deck". Simple payload kinds still clear stale
	// filter state; draw kinds keep their dedicated reshaping below.
	private static bool GrantPayloadKeepsSelectionFilters(CardExtraEffectKind kind)
		=> kind is CardExtraEffectKind.MoveCardsBetweenPiles
			or CardExtraEffectKind.PlayCardFromPile
			or CardExtraEffectKind.DiscardCards
			or CardExtraEffectKind.ExhaustCards
			or CardExtraEffectKind.UpgradeCardsInPile
			or CardExtraEffectKind.SelectCardsFromPile
			or CardExtraEffectKind.ConsumeCardValue
			or CardExtraEffectKind.DelayedPileAction
			or CardExtraEffectKind.TransformCards
			or CardExtraEffectKind.CopyCardsFromPileToDeck
			or CardExtraEffectKind.CopyExactCardsFromPileToDeck
			or CardExtraEffectKind.RemoveCardsFromDeck
			or CardExtraEffectKind.UpgradeDeckCards
			or CardExtraEffectKind.GrantKeywordToPile;

	private static void NormalizeGrantedPayloadSelection(CardExtraEffect effect)
	{
		if (effect == null)
		{
			return;
		}

		if (!GrantPayloadKeepsSelectionFilters(effect.Kind))
		{
			ClearCardSelectionFilters(effect);
		}

		if (effect.Kind is CardExtraEffectKind.DrawCards or CardExtraEffectKind.DrawCardsThatCostLess)
		{
			// P2 selection bus: a granted draw payload that consumes "the cards selected by row N"
			// keeps its chain (the source row executes in the same recipient play session); only
			// interactive/random selections are normalized to the classic granted-draw shape.
			if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect
				&& !string.IsNullOrWhiteSpace(effect.CardSelectionSourceEffectId))
			{
				effect.CardSelectionPile = CardExtraEffectCardPile.DrawPile;
				effect.IncludeSourceCardInSelection = false;
				effect.FutureMatchingCards = false;
				return;
			}

			effect.CardSelectionPile = CardExtraEffectCardPile.DrawPile;
			effect.CardSelectionMode = CardExtraEffectCardSelectionMode.Choose;
			effect.CardSelectionSourceEffectId = null;
			effect.IncludeSourceCardInSelection = false;
			effect.FutureMatchingCards = false;
		}
	}

	private static void ClearCardSelectionFilters(CardExtraEffect effect)
	{
		effect.CardSelectionPool = CardGeneratedCardPool.All;
		effect.CardSelectionType = CardGeneratedCardType.Any;
		effect.CardSelectionRarity = CardExtraEffectCardRarityFilter.Any;
		effect.CardSelectionFilter = CardExtraEffectCountCardFilter.Any;
		effect.CardMatchMode = CardExtraEffectCardMatchMode.Any;
		effect.MatchCardId = null;
		effect.MatchTagKind = CardExtraEffectCardMatchTagKind.Vanilla;
		effect.MatchVanillaTag = CardTag.None;
		effect.MatchCustomTag = null;
		effect.MatchCustomKeyword = null;
		effect.NameFilterEnabled = false;
		effect.NameFilterText = null;
		effect.CostFilterEnabled = false;
		effect.CostFilterMode = CardExtraEffectCostFilterMode.AtMost;
		effect.CostFilterMax = 0;
	}

	internal static bool SupportsIncludingSourceCardInSelection(CardExtraEffectKind kind)
	{
		return kind is CardExtraEffectKind.MoveCardsBetweenPiles
			or CardExtraEffectKind.UpgradeCardsInPile
			or CardExtraEffectKind.DiscardCards
			or CardExtraEffectKind.ExhaustCards
			or CardExtraEffectKind.TransformCards
			or CardExtraEffectKind.DelayedPileAction
			or CardExtraEffectKind.CopyCardsFromPileToDeck
			or CardExtraEffectKind.CopyExactCardsFromPileToDeck
			or CardExtraEffectKind.SelectCardsFromPile
			or CardExtraEffectKind.RemoveCardsFromDeck
			or CardExtraEffectKind.PlayCardFromPile
			or CardExtraEffectKind.FetchSpecificCardToHand
			or CardExtraEffectKind.GrantKeywordToPile
			or CardExtraEffectKind.GrantReplay
			or CardExtraEffectKind.EnchantCard
			or CardExtraEffectKind.RunEffectSourceCard
			or CardExtraEffectKind.SelfScaling
			or CardExtraEffectKind.PersistentSelfScaling
			or CardExtraEffectKind.TargetCardMutation
			or CardExtraEffectKind.PersistentTargetCardMutation;
	}

	private static bool ShouldIncludeSourceCardInSelection(CardExtraEffect? effect)
	{
		return effect != null
			&& (effect.IncludeSourceCardInSelection || effect.CardSelectionMode == CardExtraEffectCardSelectionMode.ThisCard)
			&& SupportsIncludingSourceCardInSelection(effect.Kind);
	}

	private static bool ShouldExcludeSourceCardFromSelection(CardExtraEffect? effect)
	{
		return !ShouldIncludeSourceCardInSelection(effect);
	}

	private static CardModel? ResolveSourceCardSelectionCandidate(CardExtraEffect effect, CardModel? sourceCard, bool requireDeckVersion)
	{
		if (!ShouldIncludeSourceCardInSelection(effect) || sourceCard == null)
		{
			return null;
		}

		if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.ThisCard)
		{
			return sourceCard;
		}

		if (requireDeckVersion || effect.CardSelectionPile == CardExtraEffectCardPile.Deck)
		{
			return sourceCard.DeckVersion;
		}

		return sourceCard;
	}

	private static bool CanIncludeSourceCardCandidate(Player owner, CardExtraEffect effect, CardModel? sourceCard, bool requireDeckVersion, bool includeCostFilter)
	{
		CardModel? candidate = ResolveSourceCardSelectionCandidate(effect, sourceCard, requireDeckVersion);
		return candidate != null && MatchesCardSelectionFilters(owner, candidate, effect, includeCostFilter);
	}

	private static bool AllowsZeroAmountWhenSelectingAll(CardExtraEffect effect)
	{
		if (effect == null)
		{
			return false;
		}

		if (effect.Kind == CardExtraEffectKind.OrbAction
			&& effect.OrbScope == CardExtraEffectOrbScope.All
			&& effect.OrbAction is CardExtraEffectOrbAction.Evoke
				or CardExtraEffectOrbAction.Remove
				or CardExtraEffectOrbAction.RemoveSlots
				or CardExtraEffectOrbAction.TriggerPassive)
		{
			return true;
		}

		if (effect.CardSelectionMode != CardExtraEffectCardSelectionMode.All)
		{
			return false;
		}

		return effect.Kind is CardExtraEffectKind.MoveCardsBetweenPiles
			or CardExtraEffectKind.UpgradeCardsInPile
			or CardExtraEffectKind.UpgradeDeckCards
			or CardExtraEffectKind.DiscardCards
			or CardExtraEffectKind.ExhaustCards
			or CardExtraEffectKind.TransformCards
			or CardExtraEffectKind.CopyCardsFromPileToDeck
			or CardExtraEffectKind.CopyExactCardsFromPileToDeck
			or CardExtraEffectKind.SelectCardsFromPile
			or CardExtraEffectKind.RemoveCardsFromDeck
			or CardExtraEffectKind.FetchSpecificCardToHand
			or CardExtraEffectKind.PlayCardFromPile;
	}

	private static async Task<List<CardModel>> SelectCardsFromCandidates(
		PlayerChoiceContext choiceContext,
		Player owner,
		IReadOnlyList<CardModel> candidates,
		int count,
		CardExtraEffectCardSelectionMode selectionMode,
		PileType fromPileType,
		LocString prompt,
		CardModel? sourceCard,
		bool excludeSourceCardInHandSelector,
		bool preferHandDiscardSelector,
		MegaCrit.Sts2.Core.Random.Rng? shuffleRng,
		int randomOfferCount = 0,
		CardExtraEffect? sourceEffect = null)
	{
		if (choiceContext == null
			|| owner == null
			|| candidates == null
			|| candidates.Count == 0
			|| (count <= 0 && selectionMode != CardExtraEffectCardSelectionMode.SelectedByEffect))
		{
			return new List<CardModel>();
		}

		if (selectionMode == CardExtraEffectCardSelectionMode.All)
		{
			return ReportSelectedCards(candidates.Where(c => c != null).ToList());
		}

		if (selectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect)
		{
			return ReportSelectedCards(candidates.Where(c => c != null).ToList());
		}

		if (selectionMode == CardExtraEffectCardSelectionMode.ThisCard)
		{
			return ReportSelectedCards(sourceCard != null && candidates.Any(candidate => ReferenceEquals(candidate, sourceCard))
				? new List<CardModel> { sourceCard }
				: new List<CardModel>());
		}

		if (selectionMode == CardExtraEffectCardSelectionMode.Random)
		{
			return ReportSelectedCards(PickRandomDistinct(candidates, count, shuffleRng));
		}

		if (selectionMode == CardExtraEffectCardSelectionMode.RandomOffer)
		{
			int offerCount = randomOfferCount > 0 ? randomOfferCount : count;
			offerCount = Math.Clamp(offerCount, Math.Max(1, count), candidates.Count);
			List<CardModel> offered = PickRandomDistinct(candidates, offerCount, shuffleRng);
			if (offered.Count <= count)
			{
				return ReportSelectedCards(offered);
			}

			CardSelectorPrefs offerPrefs = new CardSelectorPrefs(prompt, count);
			return ReportSelectedCards((await CardSelectCmd.FromSimpleGrid(choiceContext, offered, owner, offerPrefs)).OfType<CardModel>().ToList());
		}

		if (selectionMode == CardExtraEffectCardSelectionMode.TopOffer)
		{
			int offerCount = randomOfferCount > 0 ? randomOfferCount : count;
			offerCount = Math.Clamp(offerCount, Math.Max(1, count), candidates.Count);
			List<CardModel> offered = candidates.Where(c => c != null).Take(offerCount).ToList();
			if (offered.Count <= count)
			{
				return ReportSelectedCards(offered);
			}

			CardSelectorPrefs offerPrefs = new CardSelectorPrefs(prompt, count);
			return ReportSelectedCards((await CardSelectCmd.FromSimpleGrid(choiceContext, offered, owner, offerPrefs)).OfType<CardModel>().ToList());
		}

		if (selectionMode == CardExtraEffectCardSelectionMode.Top)
		{
			return ReportSelectedCards(candidates.Where(c => c != null).Take(count).ToList());
		}

		if (selectionMode == CardExtraEffectCardSelectionMode.Bottom)
		{
			return ReportSelectedCards(candidates.Where(c => c != null).Reverse().Take(count).Reverse().ToList());
		}

		bool isUpTo = selectionMode == CardExtraEffectCardSelectionMode.UpTo;
		CardSelectorPrefs prefs = isUpTo
			? new CardSelectorPrefs(prompt, 0, count) { Cancelable = true }
			: new CardSelectorPrefs(prompt, count);

		bool canUseHandSelector = fromPileType == PileType.Hand
			&& (sourceCard == null || excludeSourceCardInHandSelector);
		if (canUseHandSelector)
		{
			CardModel? source = ResolveHandSelectionUiSource(sourceEffect, sourceCard, excludeSourceCardInHandSelector);
			HashSet<CardModel> candidateSet = new HashSet<CardModel>(candidates.Where(c => c != null), ReferenceEqualityComparer<CardModel>.Instance);
			if (candidateSet.Count == 0)
			{
				// A null filter would make FromHand treat EVERY hand card as selectable.
				return ReportSelectedCards(new List<CardModel>());
			}
			Func<CardModel, bool>? filter = (CardModel c) => c != null && candidateSet.Contains(c);

			IEnumerable<CardModel> selected = preferHandDiscardSelector
				? await CardSelectCmd.FromHandForDiscard(choiceContext, owner, prefs, filter, source)
				: await CardSelectCmd.FromHand(choiceContext, owner, prefs, filter, source);

			return ReportSelectedCards(selected.Where(c => c != null).ToList());
		}

		return ReportSelectedCards((await CardSelectCmd.FromSimpleGrid(choiceContext, candidates, owner, prefs)).OfType<CardModel>().ToList());
	}

	private static CardModel? ResolveHandSelectionUiSource(CardExtraEffect? effect, CardModel? sourceCard, bool excludeSourceCardInHandSelector)
	{
		if (!excludeSourceCardInHandSelector || sourceCard == null)
		{
			return null;
		}

		if (effect == null)
		{
			return null;
		}

		// Vanilla hand selection keeps picked card nodes in a temporary holder until
		// source.ExecutionFinished. Timed/power effects use synthetic sources that are
		// not normal resolving hand cards, so waiting on them can strand selected cards.
		// Scheduled executions (Timing = start/end of turn) still carry Trigger==OnPlay but run
		// with a source card that already finished playing (or a pile-less snapshot), whose
		// ExecutionFinished never fires again - the picked card then never leaves the selected
		// strip ("chosen card does not return to hand at turn start"). Attach only when the
		// source card is genuinely mid-play RIGHT NOW; otherwise release immediately.
		return ShouldKeepHandSelectionAttachedToSource(effect) && sourceCard.Pile?.Type == PileType.Play
			? sourceCard
			: null;
	}

	private static bool ShouldKeepHandSelectionAttachedToSource(CardExtraEffect effect)
	{
		return effect != null
			&& !IsPowerEffect(effect)
			&& effect.Trigger == CardExtraEffectTrigger.OnPlay;
	}

	private static bool IsInteractiveCardSelectionMode(CardExtraEffectCardSelectionMode selectionMode)
	{
		return selectionMode is CardExtraEffectCardSelectionMode.Choose
			or CardExtraEffectCardSelectionMode.UpTo
			or CardExtraEffectCardSelectionMode.RandomOffer
			or CardExtraEffectCardSelectionMode.TopOffer;
	}

	private static async Task YieldAfterInteractiveHandSelectionIfNeeded(CardExtraEffect effect, IReadOnlyList<CardModel> selected)
	{
		if (effect == null
			|| selected == null
			|| !IsInteractiveCardSelectionMode(effect.CardSelectionMode)
			|| !selected.Any(card => card?.Pile?.Type == PileType.Hand))
		{
			return;
		}

		await Task.Yield();
	}

	private static int ResolveCardSelectionOfferCount(CardExtraEffect? effect, CardPlay? cardPlay, int fallbackCount)
	{
		if (effect == null
			|| effect.CardSelectionMode is not (CardExtraEffectCardSelectionMode.RandomOffer
				or CardExtraEffectCardSelectionMode.TopOffer))
		{
			return 0;
		}

		int offerCount = effect.CardSelectionOfferCountIsX && cardPlay != null
			? ResolveXAmountWithPlus(cardPlay, effect.CardSelectionOfferCount)
			: effect.CardSelectionOfferCount;
		if (offerCount <= 0)
		{
			offerCount = fallbackCount;
		}
		return Math.Clamp(offerCount, 0, 999);
	}

	private static List<CardModel> ReportSelectedCards(List<CardModel> selected)
	{
		CardEditorEffectExecutionAmountContext.ReportCurrentSelectedCards(selected);
		return selected;
	}

	private static CardExtraEffectCardPile GetEffectiveDrawSourcePile(CardExtraEffect effect)
	{
		if (effect == null || effect.CardSelectionPile == CardExtraEffectCardPile.Hand)
		{
			return CardExtraEffectCardPile.DrawPile;
		}

		return effect.CardSelectionPile;
	}

	private static async Task<List<CardModel>> DrawMatchingCards(PlayerChoiceContext choiceContext, Player owner, int amount, CardExtraEffect effect)
	{
		if (choiceContext == null || owner == null || effect == null || amount <= 0)
		{
			return new List<CardModel>();
		}

		CardExtraEffectCardPile sourcePile = GetEffectiveDrawSourcePile(effect);
		bool consumesSelection = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.SelectedByEffect
			&& !string.IsNullOrWhiteSpace(effect.CardSelectionSourceEffectId);
		bool useCustomDrawRouting = consumesSelection || HasCardSelectionCriteria(effect) || sourcePile != CardExtraEffectCardPile.DrawPile;
		if (!useCustomDrawRouting)
		{
			List<CardModel> drawn = (await CardPileCmd.Draw(choiceContext, amount, owner)).Where(c => c != null).ToList();
			CardEditorEffectExecutionAmountContext.ReportCurrentSelectedCards(drawn);
			return drawn;
		}

		// P2 selection bus: "draw THOSE cards" - consume a prior row's published selection instead
		// of filter-matching. The same manual-draw pipeline below runs (ShouldDraw gate, history,
		// AfterCardDrawn, InvokeDrawn), so a consumed draw is a real draw.
		Queue<CardModel>? selectedQueue = null;
		if (consumesSelection)
		{
			selectedQueue = new Queue<CardModel>(
				GetCandidatesFromSelectedEffectSource(owner, effect, sourceCard: null, includeDeck: false, requireDeckVersion: false, includeCostFilter: false)
					.Where(card => card?.Pile != null && card.Pile.Type is PileType.Draw or PileType.Discard or PileType.Exhaust));
		}

		List<CardModel> drawnCards = new List<CardModel>();
		CardPile? handPile = PileType.Hand.GetPile(owner);
		CardPile? drawPile = PileType.Draw.GetPile(owner);
		CardPile? discardPile = PileType.Discard.GetPile(owner);
		CardPile? exhaustPile = PileType.Exhaust.GetPile(owner);
		CardPile? deckPile = PileType.Deck.GetPile(owner);
		if (handPile == null || drawPile == null)
		{
			return drawnCards;
		}

		// Filtered draws are still draws: respect the vanilla draw gate (No Draw powers etc.)
		// exactly like CardPileCmd.Draw does.
		if (!Hook.ShouldDraw(owner.Creature.CombatState, owner, fromHandDraw: false, out AbstractModel drawModifier))
		{
			await Hook.AfterPreventingDraw(owner.Creature.CombatState, drawModifier);
			return drawnCards;
		}

		int drawsRequested = Math.Max(0, amount);
		for (int i = 0; i < drawsRequested; i++)
		{
			if (CombatManager.Instance.IsOverOrEnding)
			{
				break;
			}

			if (handPile.Cards.Count >= 10)
			{
				ThinkCmd.Play(new LocString("combat_messages", "HAND_FULL"), owner.Creature, 2.0);
				break;
			}

			if (selectedQueue == null && sourcePile == CardExtraEffectCardPile.DrawPile)
			{
				await CardPileCmd.ShuffleIfNecessary(choiceContext, owner);
			}

			CardModel? matchingCard;
			if (selectedQueue != null)
			{
				// A selected card may have moved (played/drawn by an earlier iteration's hooks);
				// skip anything no longer in a draw-able pile.
				matchingCard = null;
				while (selectedQueue.Count > 0)
				{
					CardModel candidate = selectedQueue.Dequeue();
					if (candidate?.Pile != null && candidate.Pile.Type is PileType.Draw or PileType.Discard or PileType.Exhaust)
					{
						matchingCard = candidate;
						break;
					}
				}
			}
			else
			{
				matchingCard = sourcePile switch
				{
					CardExtraEffectCardPile.DrawPile => drawPile.Cards.FirstOrDefault(card => card != null && MatchesCardSelectionFilters(owner, card, effect)),
					CardExtraEffectCardPile.DiscardPile => discardPile?.Cards.FirstOrDefault(card => card != null && MatchesCardSelectionFilters(owner, card, effect)),
					CardExtraEffectCardPile.ExhaustPile => exhaustPile?.Cards.FirstOrDefault(card => card != null && MatchesCardSelectionFilters(owner, card, effect)),
					CardExtraEffectCardPile.Deck => deckPile?.Cards.FirstOrDefault(card => card != null && MatchesCardSelectionFilters(owner, card, effect)),
					CardExtraEffectCardPile.AllPiles => new[] { drawPile, discardPile, exhaustPile, deckPile }
						.Where(pile => pile != null)
						.SelectMany(pile => pile!.Cards)
						.FirstOrDefault(card => card != null && MatchesCardSelectionFilters(owner, card, effect)),
					_ => drawPile.Cards.FirstOrDefault(card => card != null && MatchesCardSelectionFilters(owner, card, effect))
				};
			}
			if (matchingCard == null)
			{
				// An exhausted selection chain ends quietly; only filter-draws warn on empty piles.
				if (selectedQueue == null)
				{
					bool anyCardsRemaining = new[] { drawPile, discardPile, exhaustPile, deckPile }
						.Where(pile => pile != null)
						.SelectMany(pile => pile!.Cards)
						.Any();
					if (!anyCardsRemaining)
					{
						ThinkCmd.Play(new LocString("combat_messages", "NO_DRAW"), owner.Creature, 2.0);
					}
				}
				break;
			}

			drawnCards.Add(matchingCard);
			await CardPileCmd.Add(matchingCard, PileType.Hand);
			CombatManager.Instance.History.CardDrawn(owner.Creature.GetConcreteCombatState(), matchingCard, fromHandDraw: false);
			await Hook.AfterCardDrawn(owner.Creature.GetConcreteCombatState(), choiceContext, matchingCard, fromHandDraw: false);
			matchingCard.InvokeDrawn();
		}

		CardEditorEffectExecutionAmountContext.ReportCurrentSelectedCards(drawnCards);
		return drawnCards;
	}

	private static async Task MoveCardsBetweenPiles(PlayerChoiceContext choiceContext, Player owner, int amount, CardExtraEffect effect, CardModel? sourceCard)
	{
		if (choiceContext == null || owner == null || effect == null)
		{
			return;
		}

		PileType fromPileType = effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles
			? PileType.None
			: ResolvePileType(effect.CardSelectionPile);
		PileType toPileType = ResolvePileType(effect.MoveToPile);

		List<CardModel> candidates = GetCandidatesFromConfiguredPile(
			owner,
			effect,
			sourceCard,
			includeDeck: false,
			requireDeckVersion: false,
			includeCostFilter: true);

		if (candidates.Count == 0)
		{
			return;
		}

		int count = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All
			? candidates.Count
			: Math.Max(0, Math.Min(amount, candidates.Count));
		if (count <= 0)
		{
			return;
		}

		LocString prompt = toPileType switch
		{
			PileType.Discard => CardSelectorPrefs.DiscardSelectionPrompt,
			PileType.Exhaust => CardSelectorPrefs.ExhaustSelectionPrompt,
			_ => new LocString("gameplay_ui", "CHOOSE_CARD_HEADER")
		};
		List<CardModel> selected = await SelectCardsFromCandidates(
			choiceContext,
			owner,
			candidates,
			count,
			effect.CardSelectionMode,
			fromPileType,
			prompt,
			sourceCard,
			ShouldExcludeSourceCardFromSelection(effect),
			preferHandDiscardSelector: toPileType == PileType.Discard,
			owner.RunState?.Rng?.CombatCardSelection,
			ResolveCardSelectionOfferCount(effect, null, count));

		if (selected.Count == 0)
		{
			return;
		}

		// Use vanilla pipelines where possible so discard/exhaust synergies work (history + hooks).
		if (toPileType == PileType.Discard)
		{
			await CardCmd.Discard(choiceContext, selected);
			CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(selected.Count);
			return;
		}
		if (toPileType == PileType.Exhaust)
		{
			int exhausted = 0;
			foreach (CardModel card in selected)
			{
				if (card != null)
				{
					await CardCmd.Exhaust(choiceContext, card);
					exhausted++;
				}
			}
			CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(exhausted);
			return;
		}

		CardPilePosition position = ResolvePilePosition(effect.MoveToPosition);
		int moved = 0;
		foreach (CardModel card in selected)
		{
			if (card != null)
			{
				await CardPileCmd.Add(card, toPileType, position);
				moved++;
			}
		}
		CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(moved);
	}

	private static async Task DelayedPileAction(PlayerChoiceContext choiceContext, CombatState combatState, Player owner, int threshold, CardExtraEffect effect, CardModel? sourceCard)
	{
		if (choiceContext == null || combatState == null || owner == null || effect == null || threshold <= 0)
		{
			return;
		}

		bool removeFromDeck = effect.DelayedPileAction == CardExtraEffectDelayedPileAction.RemoveFromDeck;
		bool selectingDeckDirectly = effect.CardSelectionPile == CardExtraEffectCardPile.Deck;
		List<CardModel> candidates = removeFromDeck && !selectingDeckDirectly
			? GetCandidatesFromConfiguredPile(owner, effect, sourceCard, includeDeck: false, requireDeckVersion: true, includeCostFilter: true)
			: GetCandidatesFromConfiguredPile(owner, effect, sourceCard, includeDeck: selectingDeckDirectly, requireDeckVersion: false, includeCostFilter: true);
		if (candidates.Count == 0)
		{
			return;
		}

		string counterKey = BuildDelayedPileActionCounterKey(effect, sourceCard);
		bool persistent = effect.DelayedPileCounterScope == CardExtraEffectDelayedPileCounterScope.Run;
		List<CardModel> eligible = new List<CardModel>();
		foreach (CardModel candidate in candidates)
		{
			if (candidate == null)
			{
				continue;
			}

			int count = CardEditorRunCardCounterState.Increment(combatState, candidate, counterKey, persistent);
			if (count >= threshold)
			{
				eligible.Add(candidate);
			}
		}

		if (eligible.Count == 0)
		{
			return;
		}

		int actionCount = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All
			? eligible.Count
			: 1;
		PileType fromPileType = effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles
			? PileType.None
			: ResolvePileType(effect.CardSelectionPile);
		LocString prompt = effect.DelayedPileAction switch
		{
			CardExtraEffectDelayedPileAction.Discard => CardSelectorPrefs.DiscardSelectionPrompt,
			CardExtraEffectDelayedPileAction.Exhaust => CardSelectorPrefs.ExhaustSelectionPrompt,
			CardExtraEffectDelayedPileAction.RemoveFromDeck => CardSelectorPrefs.RemoveSelectionPrompt,
			_ => new LocString("gameplay_ui", "CHOOSE_CARD_HEADER")
		};

		List<CardModel> selected = await SelectCardsFromCandidates(
			choiceContext,
			owner,
			eligible,
			actionCount,
			effect.CardSelectionMode,
			fromPileType,
			prompt,
			sourceCard,
			ShouldExcludeSourceCardFromSelection(effect),
			preferHandDiscardSelector: effect.DelayedPileAction == CardExtraEffectDelayedPileAction.Discard,
			owner.RunState?.Rng?.CombatCardSelection,
			ResolveCardSelectionOfferCount(effect, null, actionCount));

		if (selected.Count == 0)
		{
			return;
		}

		await ExecuteDelayedPileAction(choiceContext, owner, selected, effect);
		CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(selected.Count);
		foreach (CardModel card in selected)
		{
			CardEditorRunCardCounterState.Clear(combatState, card, counterKey, persistent);
		}
	}

	private static async Task ExecuteDelayedPileAction(PlayerChoiceContext choiceContext, Player owner, IReadOnlyList<CardModel> selected, CardExtraEffect effect)
	{
		if (choiceContext == null || owner == null || selected == null || selected.Count == 0 || effect == null)
		{
			return;
		}

		switch (effect.DelayedPileAction)
		{
			case CardExtraEffectDelayedPileAction.Discard:
			{
				List<CardModel> combatCards = selected.Where(card => card?.Pile?.Type.IsCombatPile() == true).ToList();
				if (combatCards.Count > 0)
				{
					await CardCmd.Discard(choiceContext, combatCards);
				}
				break;
			}
			case CardExtraEffectDelayedPileAction.Exhaust:
			{
				foreach (CardModel card in selected)
				{
					if (card?.Pile?.Type.IsCombatPile() == true)
					{
						await CardCmd.Exhaust(choiceContext, card);
					}
				}
				break;
			}
			case CardExtraEffectDelayedPileAction.RemoveFromDeck:
			{
				CardPile? deckPile = PileType.Deck.GetPile(owner);
				if (deckPile == null)
				{
					break;
				}

				HashSet<CardModel> deckCards = new HashSet<CardModel>(ReferenceEqualityComparer<CardModel>.Instance);
				foreach (CardModel selectedCard in selected)
				{
					CardModel? deckCard = selectedCard?.Pile?.Type == PileType.Deck
						? selectedCard
						: selectedCard?.DeckVersion;
					if (deckCard != null && deckCard.Pile?.Type == PileType.Deck && deckPile.Cards.Contains(deckCard))
					{
						deckCards.Add(deckCard);
					}
				}
				if (deckCards.Count > 0)
				{
					await CardPileCmd.RemoveFromDeck(deckCards.ToList(), showPreview: true);
				}
				break;
			}
			default:
			{
				PileType toPileType = ResolvePileType(effect.MoveToPile);
				CardPilePosition position = ResolvePilePosition(effect.MoveToPosition);
				foreach (CardModel card in selected)
				{
					if (card != null)
					{
						await CardPileCmd.Add(card, toPileType, position);
					}
				}
				break;
			}
		}
	}

	private static string BuildDelayedPileActionCounterKey(CardExtraEffect effect, CardModel? sourceCard)
	{
		string effectId = !string.IsNullOrWhiteSpace(effect?.EffectId)
			? effect.EffectId!
			: $"{effect?.Kind}:{(int)(effect?.DelayedPileAction ?? CardExtraEffectDelayedPileAction.Move)}:{(int)(effect?.CardSelectionPile ?? CardExtraEffectCardPile.Hand)}:{(int)(effect?.CardSelectionMode ?? CardExtraEffectCardSelectionMode.Choose)}";
		string sourceId = sourceCard?.Id?.ToString() ?? "none";
		return $"delayed-pile|{sourceId}|{effectId}";
	}

	private static async Task UpgradeCardsInPile(PlayerChoiceContext choiceContext, CombatState? combatState, Player owner, int amount, CardExtraEffect effect, CardModel? sourceCard)
	{
		if (choiceContext == null || owner == null || effect == null)
		{
			return;
		}

		if (effect.CardSelectionMode == CardExtraEffectCardSelectionMode.EachPile
			&& effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles)
		{
			await UpgradeCardsInEachPile(choiceContext, combatState, owner, amount, effect, sourceCard);
			return;
		}

		PileType fromPileType = effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles
			? PileType.None
			: ResolvePileType(effect.CardSelectionPile);

		List<CardModel> candidates = GetCandidatesFromConfiguredPile(
			owner,
			effect,
			sourceCard,
			includeDeck: false,
			requireDeckVersion: false,
			includeCostFilter: false)
			.Where(card => card != null && card.IsUpgradable)
			.ToList();

		if (candidates.Count == 0)
		{
			return;
		}

		int count = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All
			? candidates.Count
			: Math.Max(0, Math.Min(amount, candidates.Count));
		if (count <= 0)
		{
			return;
		}

		List<CardModel> selected = await SelectCardsFromCandidates(
			choiceContext,
			owner,
			candidates,
			count,
			effect.CardSelectionMode,
			fromPileType,
			CardSelectorPrefs.UpgradeSelectionPrompt,
			sourceCard,
			ShouldExcludeSourceCardFromSelection(effect),
			preferHandDiscardSelector: false,
			owner.RunState?.Rng?.CombatCardSelection,
			ResolveCardSelectionOfferCount(effect, null, count));

		if (selected.Count == 0)
		{
			return;
		}

		int upgraded = UpgradeCardsWithFatalFinalKillFallback(selected, GetCardModificationPreviewStyle(selected.Count));
		CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(upgraded);

		var duration = effect.CardCostsLessDuration;
		if (duration != CardExtraEffectCardCostsLessDuration.Permanent && combatState != null)
		{
			CardEditorTemporaryUpgradeController.Apply(combatState, selected, duration, effect.CardCostsLessTurns);
		}
	}

	private static async Task UpgradeCardsInEachPile(PlayerChoiceContext choiceContext, CombatState? combatState, Player owner, int amount, CardExtraEffect effect, CardModel? sourceCard)
	{
		if (choiceContext == null || owner == null || effect == null || amount <= 0)
		{
			return;
		}

		List<CardModel> selected = new();
		foreach (PileType pileType in GetCombatCardPileTypes())
		{
			CardPile? pile = pileType.GetPile(owner);
			if (pile == null)
			{
				continue;
			}

			List<CardModel> candidates = pile.Cards
				.Where(card => card != null
					&& card.IsUpgradable
					&& !(ShouldExcludeSourceCardFromSelection(effect) && ReferenceEquals(card, sourceCard))
					&& MatchesCardSelectionFilters(owner, card, effect, includeCostFilter: false))
				.ToList();
			if (candidates.Count == 0)
			{
				continue;
			}

			int count = Math.Min(Math.Max(0, amount), candidates.Count);
			if (count <= 0)
			{
				continue;
			}

			List<CardModel> pileSelected = await SelectCardsFromCandidates(
				choiceContext,
				owner,
				candidates,
				count,
				CardExtraEffectCardSelectionMode.Choose,
				pileType,
				CardSelectorPrefs.UpgradeSelectionPrompt,
				sourceCard,
				ShouldExcludeSourceCardFromSelection(effect),
				preferHandDiscardSelector: false,
				owner.RunState?.Rng?.CombatCardSelection,
				ResolveCardSelectionOfferCount(effect, null, count));
			selected.AddRange(pileSelected.Where(card => card != null));
		}

		if (selected.Count == 0)
		{
			return;
		}

		int upgraded = UpgradeCardsWithFatalFinalKillFallback(selected, GetCardModificationPreviewStyle(selected.Count));
		CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(upgraded);

		var duration = effect.CardCostsLessDuration;
		if (duration != CardExtraEffectCardCostsLessDuration.Permanent && combatState != null)
		{
			CardEditorTemporaryUpgradeController.Apply(combatState, selected, duration, effect.CardCostsLessTurns);
		}
	}

	private static async Task DiscardCards(PlayerChoiceContext choiceContext, Player owner, int amount, CardExtraEffect effect, CardModel? sourceCard)
	{
		if (choiceContext == null || owner == null || effect == null || amount <= 0)
		{
			return;
		}

		PileType fromPileType = effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles
			? PileType.None
			: ResolvePileType(effect.CardSelectionPile);

		List<CardModel> candidates = GetCandidatesFromConfiguredPile(
			owner,
			effect,
			sourceCard,
			includeDeck: false,
			requireDeckVersion: false,
			includeCostFilter: true);
		if (candidates.Count == 0)
		{
			return;
		}

		int count = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All
			? candidates.Count
			: Math.Max(0, Math.Min(amount, candidates.Count));
		if (count <= 0)
		{
			return;
		}

		List<CardModel> selected = await SelectCardsFromCandidates(
			choiceContext,
			owner,
			candidates,
			count,
			effect.CardSelectionMode,
			fromPileType,
			CardSelectorPrefs.DiscardSelectionPrompt,
			sourceCard,
			ShouldExcludeSourceCardFromSelection(effect),
			preferHandDiscardSelector: true,
			owner.RunState?.Rng?.CombatCardSelection,
			ResolveCardSelectionOfferCount(effect, null, count));

		if (selected.Count == 0)
		{
			return;
		}

		await CardCmd.Discard(choiceContext, selected);
		CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(selected.Count);
	}

	private static async Task ExhaustCards(PlayerChoiceContext choiceContext, Player owner, int amount, CardExtraEffect effect, CardModel? sourceCard)
	{
		if (choiceContext == null || owner == null || effect == null || amount <= 0)
		{
			return;
		}

		PileType fromPileType = effect.CardSelectionPile == CardExtraEffectCardPile.AllPiles
			? PileType.None
			: ResolvePileType(effect.CardSelectionPile);

		List<CardModel> candidates = GetCandidatesFromConfiguredPile(
			owner,
			effect,
			sourceCard,
			includeDeck: false,
			requireDeckVersion: false,
			includeCostFilter: true);
		if (candidates.Count == 0)
		{
			return;
		}

		int count = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All
			? candidates.Count
			: Math.Max(0, Math.Min(amount, candidates.Count));
		if (count <= 0)
		{
			return;
		}

		List<CardModel> selected = await SelectCardsFromCandidates(
			choiceContext,
			owner,
			candidates,
			count,
			effect.CardSelectionMode,
			fromPileType,
			CardSelectorPrefs.ExhaustSelectionPrompt,
			sourceCard,
			ShouldExcludeSourceCardFromSelection(effect),
			preferHandDiscardSelector: false,
			owner.RunState?.Rng?.CombatCardSelection,
			ResolveCardSelectionOfferCount(effect, null, count));

		if (selected.Count == 0)
