	private static int ResolveEnergyXValueForCostEffect(CardModel card, CardPlay? play)
	{
		try
		{
			if (play != null && card != null && ReferenceEquals(play.Card, card))
			{
				ResourceInfo resources = play.Resources;
				if (card.EnergyCost.CostsX)
				{
					bool hasEnergyXContext = IsRecordedCardPlay(play)
						|| resources.EnergySpent > 0
						|| resources.EnergyValue > 0;
					if (hasEnergyXContext)
					{
						try
						{
							return Math.Max(0, card.ResolveEnergyXValue());
						}
						catch
						{
							// Fall back to the raw resource value below.
						}
					}
				}

				return Math.Max(0, play.Resources.EnergyValue);
			}
		}
		catch
		{
			// ignored
		}

		try
		{
			return Math.Max(0, card?.EnergyCost?.Canonical ?? 0);
		}
		catch
		{
			return 0;
		}
	}

	private static bool TryResolveSignedAmountForCostEffect(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffect effect, out int signedAmount)
	{
		signedAmount = 0;
		if (combatState == null || ownerCreature == null || cardPlay == null || effect == null)
		{
			return false;
		}

		int baseAmount;
		if (effect.AmountIsX)
		{
			int x = effect.Kind is CardExtraEffectKind.CardStarCostsLess or CardExtraEffectKind.CardTypeStarCostsLess
				? ResolveStarXValueForCostEffect(cardPlay.Card, cardPlay)
				: ResolveXAmountWithPlus(cardPlay, effect.AmountXPlus);
			if (effect.Kind is CardExtraEffectKind.CardStarCostsLess or CardExtraEffectKind.CardTypeStarCostsLess)
			{
				x += effect.AmountXPlus;
			}
			x = Math.Max(0, x);
			int sign = effect.Amount < 0 ? -1 : 1;
			baseAmount = sign * x;
		}
		else
		{
			baseAmount = effect.Amount;
		}

		if (baseAmount == 0)
		{
			return false;
		}

		int resolved = baseAmount;
		if (effect.ScaleMode != CardExtraEffectScaleMode.None)
		{
			int multiplier = GetHistoryCountMultiplier(combatState, ownerCreature, cardPlay, effect);
			if (!DoesCountConditionPass(multiplier, effect))
			{
				return false;
			}

			if (effect.ScaleMode == CardExtraEffectScaleMode.ConditionOnly)
			{
				multiplier = 1;
			}

			if (effect.ScaleMode == CardExtraEffectScaleMode.PerHistoryCount)
			{
				int scalingMultiplier = ResolveHistoryScalingMultiplier(effect, multiplier);
				long scaled = (long)resolved * scalingMultiplier;
				long total = effect.HistoryScalingIncludesBase
					? (long)ResolveHistoryScalingBaseAmount(effect, resolved) + scaled
					: scaled;
				if (total >= int.MaxValue)
				{
					resolved = int.MaxValue;
				}
				else if (total <= -int.MaxValue)
				{
					resolved = -int.MaxValue;
				}
				else
				{
					resolved = (int)total;
				}
			}
		}

		int repeats = ResolveRepeatCount(cardPlay, effect);
		if (repeats <= 0)
		{
			return false;
		}
		if (repeats > 1)
		{
			long repeated = (long)resolved * repeats;
			if (repeated >= int.MaxValue)
			{
				resolved = int.MaxValue;
			}
			else if (repeated <= -int.MaxValue)
			{
				resolved = -int.MaxValue;
			}
			else
			{
				resolved = (int)repeated;
			}
		}

		if (resolved == 0)
		{
			return false;
		}

		signedAmount = resolved;
		return true;
	}

	private static int ResolveStarXValueForCostEffect(CardModel card, CardPlay? play)
	{
		try
		{
			if (play != null && card != null && ReferenceEquals(play.Card, card))
			{
				ResourceInfo resources = play.Resources;
				if (card.HasStarCostX)
				{
					bool hasStarXContext = IsRecordedCardPlay(play)
						|| resources.StarsSpent > 0
						|| resources.StarValue > 0;
					if (hasStarXContext)
					{
						try
						{
							return Math.Max(0, card.ResolveStarXValue());
						}
						catch
						{
							// Fall back to the raw resource value below.
						}
					}
				}

				return Math.Max(0, play.Resources.StarValue);
			}
		}
		catch
		{
			// ignored
		}

		try
		{
			int cost = card?.CurrentStarCost ?? -1;
			return Math.Max(0, cost);
		}
		catch
		{
			return 0;
		}
	}

	private static int CountMatchingCardsInConfiguredPile(Player ownerPlayer, CardExtraEffect effect, CardModel? sourceCard)
	{
		if (ownerPlayer == null || effect == null)
		{
			return 0;
		}

		int inPileCount = 0;
		if (effect.CountCardPile == CardExtraEffectCardPile.AllPiles)
		{
			foreach (PileType countPileType in new[] { PileType.Hand, PileType.Draw, PileType.Discard, PileType.Exhaust })
			{
				CardPile? countPile = countPileType.GetPile(ownerPlayer);
				if (countPile == null)
				{
					continue;
				}

				foreach (CardModel? c in countPile.Cards)
				{
					if (c == null)
					{
						continue;
					}
					if (effect.CountExcludeSourceCard && sourceCard != null && ReferenceEquals(c, sourceCard))
					{
						continue;
					}
					if (!MatchesCountCardFilters(ownerPlayer, c, effect))
					{
						continue;
					}
					inPileCount += UsesCountCardAggregateAmount(effect)
						? GetCountAggregationAmount(c, effect)
						: 1;
				}
			}
			return inPileCount;
		}

		PileType pileType = ResolvePileType(effect.CountCardPile);
		CardPile? pile = pileType.GetPile(ownerPlayer);
		if (pile == null)
		{
			return 0;
		}

		foreach (CardModel? c in pile.Cards)
		{
			if (c == null)
			{
				continue;
			}
			if (effect.CountExcludeSourceCard && sourceCard != null && ReferenceEquals(c, sourceCard))
			{
				continue;
			}
			if (!MatchesCountCardFilters(ownerPlayer, c, effect))
			{
				continue;
			}
			inPileCount += UsesCountCardAggregateAmount(effect)
				? GetCountAggregationAmount(c, effect)
				: 1;
		}

		return inPileCount;
	}

	private static int GetHistoryCountMultiplier(CombatState combatState, Creature ownerCreature, CardPlay? cardPlay, CardExtraEffect effect, CardModel? sourceCardOverride = null)
	{
		try
		{
			if (combatState == null || ownerCreature == null || effect == null)
			{
				return 0;
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.EffectResult)
			{
				return ResolveEffectResultCount(effect);
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.InPile)
			{
				Player? ownerPlayer = ownerCreature.Player;
				CardModel? sourceCard = sourceCardOverride ?? cardPlay?.Card;
				if (ownerPlayer == null)
				{
					return 0;
				}

				return CountMatchingCardsInConfiguredPile(ownerPlayer, effect, sourceCard);
			}

			CombatHistory? history = CombatManager.Instance?.History;
			if (history != null && TryGetResourceHistoryCountMultiplier(history, combatState, ownerCreature, cardPlay, effect, sourceCardOverride, out int resourceCount))
			{
				return resourceCount;
			}
			if (history == null
				&& effect.CountEvent is CardExtraEffectCountEvent.EnergyGained
					or CardExtraEffectCountEvent.EnergyLost
					or CardExtraEffectCountEvent.BlockLost
					or CardExtraEffectCountEvent.HealingReceived)
			{
				TryGetRecordedResourceCountMultiplier(combatState, ownerCreature, effect, out int recordedCount);
				return recordedCount;
			}

			Player? owner = ownerCreature.Player;
			if (owner == null)
			{
				return 0;
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.LastCardPlayed)
			{
				CardModel? lastCard = GetLastPlayedCardForOwner(combatState, owner);
				if (lastCard == null)
				{
					return 0;
				}

				if (!MatchesCountCardFilters(owner, lastCard, effect))
				{
					return 0;
				}

				return UsesCountCardAggregateAmount(effect)
					? GetCountAggregationAmount(lastCard, effect)
					: 1;
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.CurrentOrbs)
			{
				return owner.PlayerCombatState?.OrbQueue?.Orbs?.Count(orb => orb != null && OrbMatchesType(orb, effect.CountOrbType)) ?? 0;
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.CurrentStars)
			{
				return owner.PlayerCombatState?.Stars ?? 0;
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.CurrentEnergy)
			{
				return owner.PlayerCombatState?.Energy ?? 0;
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.CurrentOrbSlots)
			{
				return owner.PlayerCombatState?.OrbQueue?.Capacity ?? 0;
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.CurrentTurnNumber)
			{
				return combatState?.RoundNumber ?? 0;
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.NumberOfEnemies)
			{
				return combatState?.Enemies?.Count(enemy => enemy != null && enemy.IsEnemy && enemy.IsAlive) ?? 0;
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.OstyCurrentHp)
			{
				return owner.Osty?.CurrentHp ?? 0;
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.OstyMaxHp)
			{
				return owner.Osty?.MaxHp ?? 0;
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.EnemyHasStatus)
			{
				return GetRelevantEnemyConditionTargets(combatState, cardPlay)
					.Count(enemy => EnemyHasConfiguredStatus(enemy, effect.CountEnemyStatus, effect.CountPowerId));
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.EnemyIntent)
			{
				return GetRelevantEnemyConditionTargets(combatState, cardPlay)
					.Count(enemy => EnemyHasIntent(enemy, effect.CountEnemyIntent));
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.PlayedCardEnergyCost)
			{
				return Math.Max(0, cardPlay?.Resources.EnergyValue ?? 0);
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.EmptyOrbSlots)
			{
				OrbQueue? orbQueue = owner.PlayerCombatState?.OrbQueue;
				if (orbQueue == null)
				{
					return 0;
				}
				return Math.Max(0, orbQueue.Capacity - orbQueue.Orbs.Count);
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.OrbInPosition)
			{
				OrbModel? orb = GetOrbInPosition(owner, effect.CountOrbSelection);
				if (orb == null)
				{
					return 0;
				}
				return OrbMatchesType(orb, effect.CountOrbType) ? 1 : 0;
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.OrbChanneled)
			{
				if (history == null)
				{
					return 0;
				}
				return history.Entries
					.OfType<OrbChanneledEntry>()
					.Count(e => e != null
						&& ReferenceEquals(e.Actor, ownerCreature)
						&& MatchesCountWindow(e, combatState, effect)
						&& e.Orb != null
						&& OrbMatchesType(e.Orb, effect.CountOrbType));
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.OrbEvoked)
			{
				if (!_orbEvokeHistory.TryGetValue(combatState, out List<OrbEvokeCountEntry>? orbEntries))
				{
					return 0;
				}

				return orbEntries.Count(e => e != null
					&& ReferenceEquals(e.Actor, ownerCreature)
					&& MatchesCountWindow(e.RoundNumber, combatState, effect)
					&& e.Orb != null
					&& OrbMatchesType(e.Orb, effect.CountOrbType));
			}

			if (history == null)
			{
				return 0;
			}

			if (effect.CountEvent == CardExtraEffectCountEvent.ThisCardDamageDealt)
			{
				CardModel? sourceCard = sourceCardOverride ?? cardPlay?.Card;
				if (sourceCard == null)
				{
					return 0;
				}

				long thisCardDamage = history.Entries
					.OfType<DamageReceivedEntry>()
					.Where(e => e != null
						&& MatchesCountWindow(e, combatState, effect)
						&& ReferenceEquals(e.CardSource, sourceCard))
					.Sum(e => (long)Math.Max(0, e.Result.UnblockedDamage));
				return ClampLongToInt(thisCardDamage);
			}

			if (IsThisCardHistoryCountEvent(effect.CountEvent))
			{
				CardModel? sourceCard = sourceCardOverride ?? cardPlay?.Card;
				if (sourceCard == null)
				{
					return 0;
				}

				return effect.CountEvent switch
				{
					CardExtraEffectCountEvent.ThisCardDrawn => history.Entries
						.OfType<CardDrawnEntry>()
						.Count(e => e != null
							&& ReferenceEquals(e.Actor, ownerCreature)
							&& MatchesCountWindow(e, combatState, effect)
							&& ReferenceEquals(e.Card, sourceCard)),
					CardExtraEffectCountEvent.ThisCardDiscarded => history.Entries
						.OfType<CardDiscardedEntry>()
						.Count(e => e != null
							&& ReferenceEquals(e.Actor, ownerCreature)
							&& MatchesCountWindow(e, combatState, effect)
							&& ReferenceEquals(e.Card, sourceCard)),
					CardExtraEffectCountEvent.ThisCardExhausted => history.Entries
						.OfType<CardExhaustedEntry>()
						.Count(e => e != null
							&& ReferenceEquals(e.Actor, ownerCreature)
							&& MatchesCountWindow(e, combatState, effect)
							&& ReferenceEquals(e.Card, sourceCard)),
					_ => history.Entries
						.OfType<CardPlayStartedEntry>()
						.Count(e => e != null
							&& (cardPlay == null || !ReferenceEquals(e.CardPlay, cardPlay))
							&& ReferenceEquals(e.Actor, ownerCreature)
							&& MatchesCountWindow(e, combatState, effect)
							&& ReferenceEquals(e.CardPlay?.Card, sourceCard))
				};
			}

			if (TryGetPlayedCardResourceAggregation(history, combatState, ownerCreature, owner, cardPlay, effect, out int playedResourceTotal))
			{
				return playedResourceTotal;
			}

			IEnumerable<CardModel> cards = effect.CountEvent switch
			{
				CardExtraEffectCountEvent.Drawn => history.Entries
					.OfType<CardDrawnEntry>()
					.Where(e => e != null && ReferenceEquals(e.Actor, ownerCreature) && MatchesCountWindow(e, combatState, effect))
					.Select(e => e.Card),
				CardExtraEffectCountEvent.Discarded => history.Entries
					.OfType<CardDiscardedEntry>()
					.Where(e => e != null && ReferenceEquals(e.Actor, ownerCreature) && MatchesCountWindow(e, combatState, effect))
					.Select(e => e.Card),
				CardExtraEffectCountEvent.Exhausted => history.Entries
					.OfType<CardExhaustedEntry>()
					.Where(e => e != null && ReferenceEquals(e.Actor, ownerCreature) && MatchesCountWindow(e, combatState, effect))
					.Select(e => e.Card),
				CardExtraEffectCountEvent.Generated => history.Entries
					.OfType<CardGeneratedEntry>()
					.Where(e => e != null && e.Creator != null && ReferenceEquals(e.Actor, ownerCreature) && MatchesCountWindow(e, combatState, effect))
					.Select(e => e.Card),
				_ => history.Entries
					.OfType<CardPlayStartedEntry>()
					.Where(e => e != null
						&& (cardPlay == null || !ReferenceEquals(e.CardPlay, cardPlay))
						&& ReferenceEquals(e.Actor, ownerCreature)
						&& MatchesCountWindow(e, combatState, effect))
					.Select(e => e.CardPlay.Card)
			};

			int count = 0;
			foreach (CardModel? historyCard in cards)
			{
				if (historyCard == null)
				{
					continue;
				}
				if (!MatchesCountCardFilters(owner, historyCard, effect))
				{
					continue;
				}
				count += UsesCountCardAggregateAmount(effect)
					? GetCountAggregationAmount(historyCard, effect)
					: 1;
			}

			return count;
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] Failed computing history scaling multiplier: {ex}");
			return 0;
		}
	}

	private static int ResolveEffectResultCount(string? effectId, CardExtraEffectResultMetric metric)
	{
		if (string.IsNullOrWhiteSpace(effectId))
		{
			return 0;
		}

		return metric switch
		{
			CardExtraEffectResultMetric.AppliedCount => CardEditorEffectExecutionAmountContext.TryGetAppliedCount(effectId, out int appliedCount)
				? appliedCount
				: 0,
			CardExtraEffectResultMetric.HpDamage => CardEditorEffectExecutionAmountContext.TryGetAppliedAmount(effectId, out int hpDamageAmount)
				? hpDamageAmount
				: 0,
			CardExtraEffectResultMetric.BlockedDamage => CardEditorEffectExecutionAmountContext.TryGetBlockedDamageAmount(effectId, out int blockedDamageAmount)
				? blockedDamageAmount
				: 0,
			CardExtraEffectResultMetric.TotalDamage => CardEditorEffectExecutionAmountContext.TryGetTotalDamageAmount(effectId, out int totalDamageAmount)
				? totalDamageAmount
				: 0,
			CardExtraEffectResultMetric.OverkillDamage => CardEditorEffectExecutionAmountContext.TryGetOverkillDamageAmount(effectId, out int overkillDamageAmount)
				? overkillDamageAmount
				: 0,
			CardExtraEffectResultMetric.TotalAndOverkillDamage => ResolveTotalAndOverkillDamageAmount(effectId),
			CardExtraEffectResultMetric.Kills => CardEditorEffectExecutionAmountContext.TryGetKillCount(effectId, out int killCount)
				? killCount
				: 0,
			_ => CardEditorEffectExecutionAmountContext.TryGetAppliedAmount(effectId, out int appliedAmount)
				? appliedAmount
			: 0
		};
	}

	private static int ResolveEffectResultCount(CardExtraEffect effect)
	{
		if (effect == null)
		{
			return 0;
		}

		string? effectId = string.IsNullOrWhiteSpace(effect.CountResultEffectId)
			? effect.EffectId
			: effect.CountResultEffectId;
		return ResolveEffectResultCount(effectId, effect.CountResultMetric);
	}

	private static bool TryGetPlayedCardResourceAggregation(
		CombatHistory history,
		CombatState combatState,
		Creature ownerCreature,
		Player owner,
		CardPlay? currentPlay,
		CardExtraEffect effect,
		out int multiplier)
	{
		multiplier = 0;
		if (history == null
			|| combatState == null
			|| ownerCreature == null
			|| owner == null
			|| effect == null
			|| effect.CountEvent != CardExtraEffectCountEvent.Played
			|| !UsesCountCardAggregateAmount(effect))
		{
			return false;
		}

		CardExtraEffectCountAggregationMode aggregationMode = GetEffectiveCountAggregationMode(effect);
		if (aggregationMode is not (CardExtraEffectCountAggregationMode.CurrentEnergyCost
			or CardExtraEffectCountAggregationMode.CurrentStarCost))
		{
			return false;
		}

		long total = 0;
		foreach (CardPlayStartedEntry entry in history.Entries.OfType<CardPlayStartedEntry>())
		{
			CardPlay? play = entry?.CardPlay;
			CardModel? playedCard = play?.Card;
			if (entry == null
				|| play == null
				|| playedCard == null
				|| (currentPlay != null && ReferenceEquals(play, currentPlay))
				|| !ReferenceEquals(entry.Actor, ownerCreature)
				|| !MatchesCountWindow(entry, combatState, effect)
				|| !MatchesCountCardFilters(owner, playedCard, effect))
			{
				continue;
			}

			ResourceInfo resources = play.Resources;
			total += aggregationMode == CardExtraEffectCountAggregationMode.CurrentStarCost
				? Math.Max(0, resources.StarValue)
				: Math.Max(0, resources.EnergyValue);
			if (total >= int.MaxValue)
			{
				multiplier = int.MaxValue;
				return true;
			}
		}

		multiplier = ClampLongToInt(total);
		return true;
	}

	private static bool TryGetResourceHistoryCountMultiplier(CombatHistory history, CombatState combatState, Creature ownerCreature, CardPlay? cardPlay, CardExtraEffect effect, CardModel? sourceCardOverride, out int multiplier)
	{
		multiplier = 0;
		switch (effect.CountEvent)
		{
			case CardExtraEffectCountEvent.StarsGained:
			{
				long gainedStars = history.Entries
					.OfType<StarsModifiedEntry>()
					.Where(e => e != null
						&& ReferenceEquals(e.Actor, ownerCreature)
						&& MatchesCountWindow(e, combatState, effect)
						&& e.Amount > 0)
					.Sum(e => (long)e.Amount);
				multiplier = ClampLongToInt(gainedStars);
				return true;
			}
			case CardExtraEffectCountEvent.StarsLost:
			{
				long lostStars = history.Entries
					.OfType<StarsModifiedEntry>()
					.Where(e => e != null
						&& ReferenceEquals(e.Actor, ownerCreature)
						&& MatchesCountWindow(e, combatState, effect)
						&& e.Amount < 0)
					.Sum(e => -(long)e.Amount);
				multiplier = ClampLongToInt(lostStars);
				return true;
			}
			case CardExtraEffectCountEvent.EnergyUsed:
			{
				long usedEnergy = history.Entries
					.OfType<EnergySpentEntry>()
					.Where(e => e != null
						&& ReferenceEquals(e.Actor, ownerCreature)
						&& MatchesCountWindow(e, combatState, effect)
						&& e.Amount > 0)
					.Sum(e => (long)e.Amount);
				multiplier = ClampLongToInt(usedEnergy);
				return true;
			}
			case CardExtraEffectCountEvent.StarsSpent:
			{
				if (!_resourceCountHistory.TryGetValue(combatState, out List<ResourceCountEntry>? starsSpentEntries))
				{
					multiplier = 0;
					return true;
				}
				long spentStars = starsSpentEntries
					.Where(e => e != null
						&& e.CountEvent == CardExtraEffectCountEvent.StarsSpent
						&& ReferenceEquals(e.Actor, ownerCreature)
						&& MatchesCountWindow(e.RoundNumber, combatState, effect)
						&& e.Amount > 0)
					.Sum(e => (long)e.Amount);
				multiplier = ClampLongToInt(spentStars);
				return true;
			}
			case CardExtraEffectCountEvent.BlockGained:
			{
				long gainedBlock = history.Entries
					.OfType<BlockGainedEntry>()
					.Where(e => e != null
						&& ReferenceEquals(e.Actor, ownerCreature)
						&& MatchesCountWindow(e, combatState, effect)
						&& e.Amount > 0)
					.Sum(e => (long)e.Amount);
				multiplier = ClampLongToInt(gainedBlock);
				return true;
			}
			case CardExtraEffectCountEvent.StatusGained:
			{
				long gainedStatus = history.Entries
					.OfType<PowerReceivedEntry>()
					.Where(e => e != null
						&& ReferenceEquals(e.Actor, ownerCreature)
						&& MatchesCountWindow(e, combatState, effect)
						&& e.Amount > 0
						&& PowerMatchesConfiguredStatus(e.Power, effect.CountEnemyStatus, effect.CountPowerId))
					.Sum(e => (long)e.Amount);
				multiplier = ClampLongToInt(gainedStatus);
				return true;
			}
			case CardExtraEffectCountEvent.StatusLost:
			{
				long lostStatus = history.Entries
					.OfType<PowerReceivedEntry>()
					.Where(e => e != null
						&& ReferenceEquals(e.Actor, ownerCreature)
						&& MatchesCountWindow(e, combatState, effect)
						&& e.Amount < 0
						&& PowerMatchesConfiguredStatus(e.Power, effect.CountEnemyStatus, effect.CountPowerId))
					.Sum(e => (long)Math.Abs(e.Amount));
				multiplier = ClampLongToInt(lostStatus);
				return true;
			}
			case CardExtraEffectCountEvent.DamageDealt:
			{
				long dealtDamage = history.Entries
					.OfType<DamageReceivedEntry>()
					.Where(e => e != null
						&& ReferenceEquals(e.Dealer, ownerCreature)
						&& MatchesCountWindow(e, combatState, effect))
					.Sum(e => (long)Math.Max(0, e.Result.TotalDamage));
				multiplier = ClampLongToInt(dealtDamage);
				return true;
			}
			case CardExtraEffectCountEvent.DamageTaken:
			{
				long takenDamage = history.Entries
					.OfType<DamageReceivedEntry>()
					.Where(e => e != null
						&& ReferenceEquals(e.Actor, ownerCreature)
						&& MatchesCountWindow(e, combatState, effect))
					.Sum(e => (long)Math.Max(0, e.Result.UnblockedDamage));
				multiplier = ClampLongToInt(takenDamage);
				return true;
			}
			case CardExtraEffectCountEvent.TimesLostHp:
			{
				long timesHit = history.Entries
					.OfType<DamageReceivedEntry>()
					.Count(e => e != null
						&& ReferenceEquals(e.Actor, ownerCreature)
						&& MatchesCountWindow(e, combatState, effect)
						&& e.Result.UnblockedDamage > 0);
				multiplier = ClampLongToInt(timesHit);
				return true;
			}
			case CardExtraEffectCountEvent.TimesDealtDamage:
			{
				long timesDealtDamage = history.Entries
					.OfType<DamageReceivedEntry>()
					.Count(e => e != null
						&& ReferenceEquals(e.Dealer, ownerCreature)
						&& MatchesCountWindow(e, combatState, effect)
						&& e.Result.TotalDamage > 0);
				multiplier = ClampLongToInt(timesDealtDamage);
				return true;
			}
			case CardExtraEffectCountEvent.TimesGainedHp:
			{
				if (!_resourceCountHistory.TryGetValue(combatState, out List<ResourceCountEntry>? rcEntries))
				{
					multiplier = 0;
					return true;
				}
				long timesHealed = rcEntries
					.Count(e => e != null
						&& e.CountEvent == CardExtraEffectCountEvent.HealingReceived
						&& ReferenceEquals(e.Actor, ownerCreature)
						&& MatchesCountWindow(e.RoundNumber, combatState, effect)
						&& e.Amount > 0);
				multiplier = ClampLongToInt(timesHealed);
				return true;
			}
			case CardExtraEffectCountEvent.OstyAttacked:
			{
				Creature? osty = ownerCreature.Player?.Osty;
				if (osty == null)
				{
					multiplier = 0;
					return true;
				}
				long timesOstyAttacked = history.Entries
					.OfType<CreatureAttackedEntry>()
					.Count(e => e != null
						&& ReferenceEquals(e.Actor, osty)
						&& MatchesCountWindow(e, combatState, effect));
				multiplier = ClampLongToInt(timesOstyAttacked);
				return true;
			}
			case CardExtraEffectCountEvent.OstyAlive:
			{
				multiplier = ownerCreature.Player?.IsOstyAlive == true ? 1 : 0;
				return true;
			}
			case CardExtraEffectCountEvent.Summoned:
			{
				long summons = history.Entries
					.OfType<SummonedEntry>()
					.Where(e => e != null
						&& ReferenceEquals(e.Actor, ownerCreature)
						&& MatchesCountWindow(e, combatState, effect)
						&& e.Amount > 0)
					.Sum(e => (long)e.Amount);
				multiplier = ClampLongToInt(summons);
				return true;
			}
			case CardExtraEffectCountEvent.DamageHistory:
			{
				multiplier = GetDamageHistoryCountMultiplier(history, combatState, ownerCreature, cardPlay, effect, sourceCardOverride);
				return true;
			}
			case CardExtraEffectCountEvent.EnergyGained:
			case CardExtraEffectCountEvent.EnergyLost:
			case CardExtraEffectCountEvent.BlockLost:
			case CardExtraEffectCountEvent.HealingReceived:
				return TryGetRecordedResourceCountMultiplier(combatState, ownerCreature, effect, out multiplier);
			default:
				return false;
		}
	}

	private static int GetDamageHistoryCountMultiplier(CombatHistory history, CombatState combatState, Creature ownerCreature, CardPlay? cardPlay, CardExtraEffect effect, CardModel? sourceCardOverride)
	{
		if (history == null || combatState == null || ownerCreature == null || effect == null)
		{
			return 0;
		}

		CardModel? sourceCard = sourceCardOverride ?? cardPlay?.Card;
		List<CombatHistoryEntry> entries = history.Entries?.ToList() ?? new List<CombatHistoryEntry>();
		int currentPlayStartIndex = -1;
		if (cardPlay != null)
		{
			for (int i = entries.Count - 1; i >= 0; i--)
			{
				if (entries[i] is CardPlayStartedEntry started && ReferenceEquals(started.CardPlay, cardPlay))
				{
					currentPlayStartIndex = i;
					break;
				}
			}
		}

		long total = 0;
		for (int i = 0; i < entries.Count; i++)
		{
			if (entries[i] is not DamageReceivedEntry entry || entry.Result == null)
			{
				continue;
			}

			if (!MatchesCountWindow(entry, combatState, effect)
				|| !MatchesDamageHistoryTarget(entry, ownerCreature, cardPlay, effect.CountDamageTarget)
				|| !MatchesDamageHistoryDealer(entry, ownerCreature, sourceCard, effect.CountDamageDealer)
				|| !MatchesDamageHistorySource(entry, effect.CountDamageSource))
			{
				continue;
			}

			if (effect.CountDamageCurrentInclusion == CardExtraEffectDamageHistoryCurrentInclusion.BeforeCurrentPlay
				&& IsCurrentPlayDamageHistoryEntry(entry, i, currentPlayStartIndex, sourceCard))
			{
				continue;
			}

			total += GetDamageHistoryAggregationAmount(entry.Result, effect.CountDamageAggregation);
			if (total >= int.MaxValue)
			{
				return int.MaxValue;
			}
		}

		return ClampLongToInt(total);
	}

	private static bool IsCurrentPlayDamageHistoryEntry(DamageReceivedEntry entry, int entryIndex, int currentPlayStartIndex, CardModel? sourceCard)
	{
		if (CardEditorEffectExecutionAmountContext.ContainsCurrentPlayDamageResult(entry.Result))
		{
			return true;
		}

		return currentPlayStartIndex >= 0
			&& entryIndex > currentPlayStartIndex
			&& sourceCard != null
			&& ReferenceEquals(entry.CardSource, sourceCard);
	}

	private static bool MatchesDamageHistoryTarget(DamageReceivedEntry entry, Creature ownerCreature, CardPlay? cardPlay, CardExtraEffectDamageHistoryTarget target)
	{
		Creature? receiver = entry.Receiver;
		if (receiver == null)
		{
			return false;
		}

		return target switch
		{
			CardExtraEffectDamageHistoryTarget.CurrentTarget => cardPlay?.Target != null && ReferenceEquals(receiver, cardPlay.Target),
			CardExtraEffectDamageHistoryTarget.Self => ReferenceEquals(receiver, ownerCreature),
			CardExtraEffectDamageHistoryTarget.Enemies => receiver.Side != ownerCreature.Side,
			CardExtraEffectDamageHistoryTarget.Allies => receiver.Side == ownerCreature.Side,
			_ => true
		};
	}

	private static bool MatchesDamageHistoryDealer(DamageReceivedEntry entry, Creature ownerCreature, CardModel? sourceCard, CardExtraEffectDamageHistoryDealer dealer)
	{
		Creature? entryDealer = entry.Dealer;
		return dealer switch
		{
			CardExtraEffectDamageHistoryDealer.Self => ReferenceEquals(entryDealer, ownerCreature),
			CardExtraEffectDamageHistoryDealer.ThisCard => sourceCard != null && ReferenceEquals(entry.CardSource, sourceCard),
			CardExtraEffectDamageHistoryDealer.Osty => entryDealer != null && ReferenceEquals(entryDealer, ownerCreature.Player?.Osty),
			CardExtraEffectDamageHistoryDealer.Allies => entryDealer != null && entryDealer.Side == ownerCreature.Side,
			CardExtraEffectDamageHistoryDealer.AlliesExceptSelf => entryDealer != null && entryDealer.Side == ownerCreature.Side && !ReferenceEquals(entryDealer, ownerCreature),
			CardExtraEffectDamageHistoryDealer.Enemies => entryDealer != null && entryDealer.Side != ownerCreature.Side,
			_ => true
		};
	}

	private static bool MatchesDamageHistorySource(DamageReceivedEntry entry, CardExtraEffectDamageHistorySource source)
	{
		return source switch
		{
			CardExtraEffectDamageHistorySource.PoweredAttack => entry.Result.Props.IsPoweredAttack(),
			CardExtraEffectDamageHistorySource.Unpowered => !entry.Result.Props.IsPoweredAttack(),
			CardExtraEffectDamageHistorySource.Card => entry.CardSource != null,
			CardExtraEffectDamageHistorySource.NonCard => entry.CardSource == null,
			_ => true
		};
	}

	private static int GetDamageHistoryAggregationAmount(DamageResult result, CardExtraEffectDamageHistoryAggregation aggregation)
	{
		if (result == null)
		{
			return 0;
		}

		return aggregation switch
		{
			CardExtraEffectDamageHistoryAggregation.HpDamage => Math.Max(0, result.UnblockedDamage),
			CardExtraEffectDamageHistoryAggregation.BlockedDamage => Math.Max(0, result.BlockedDamage),
			CardExtraEffectDamageHistoryAggregation.TotalDamage => Math.Max(0, result.TotalDamage),
			CardExtraEffectDamageHistoryAggregation.OverkillDamage => Math.Max(0, result.OverkillDamage),
			_ => 1
		};
	}

	private static bool TryGetRecordedResourceCountMultiplier(CombatState combatState, Creature ownerCreature, CardExtraEffect effect, out int multiplier)
	{
		multiplier = 0;
		if (!_resourceCountHistory.TryGetValue(combatState, out List<ResourceCountEntry>? resourceEntries))
		{
			return true;
		}

		bool includeBetweenTurns = effect.CountEvent != CardExtraEffectCountEvent.BlockLost
			|| effect.BlockLostCountingMode == CardExtraEffectBlockLostCountingMode.IncludeBetweenTurns;

		long total = resourceEntries
			.Where(e => e != null
				&& e.CountEvent == effect.CountEvent
				&& ReferenceEquals(e.Actor, ownerCreature)
				&& MatchesCountWindow(e.RoundNumber, combatState, effect)
				&& (includeBetweenTurns || e.Source != ResourceCountSource.BetweenTurnsBlockClear))
			.Sum(e => (long)e.Amount);
		multiplier = ClampLongToInt(total);
		return true;
	}

	private static int ClampLongToInt(long value)
	{
		if (value <= 0)
		{
			return 0;
		}
		return value >= int.MaxValue ? int.MaxValue : (int)value;
	}

	private static bool MatchesCountWindow(CombatHistoryEntry entry, CombatState combatState, CardExtraEffect effect)
	{
		if (!CountEventUsesWindow(effect.CountEvent))
		{
			return true;
		}

		return MatchesCountWindow(GetCombatHistoryEntryRoundNumber(entry, combatState), combatState, effect);
	}

	private static MemberInfo? _combatHistoryEntryRoundNumberMember;
	private static bool _combatHistoryEntryRoundNumberMemberResolved;

	private static int GetCombatHistoryEntryRoundNumber(CombatHistoryEntry entry, CombatState combatState)
	{
		try
		{
			if (!_combatHistoryEntryRoundNumberMemberResolved)
			{
				// RoundNumber is declared PRIVATE on the abstract base CombatHistoryEntry; reflection on the
				// derived runtime type never returns private base members, so walk the hierarchy explicitly.
				const BindingFlags flags = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.DeclaredOnly;
				for (Type? type = entry.GetType(); type != null && _combatHistoryEntryRoundNumberMember == null; type = type.BaseType)
				{
					_combatHistoryEntryRoundNumberMember = (MemberInfo?)type.GetProperty("RoundNumber", flags)
						?? (MemberInfo?)type.GetField("RoundNumber", flags)
						?? type.GetField("<RoundNumber>k__BackingField", flags);
				}
				_combatHistoryEntryRoundNumberMemberResolved = true;
				if (_combatHistoryEntryRoundNumberMember == null)
				{
					Log.Warn("[CardEditor] CombatHistoryEntry.RoundNumber not found via reflection; ThisTurn/LastTurns count windows will behave as This Combat (game update changed the type?).");
				}
			}
			object? value = _combatHistoryEntryRoundNumberMember switch
			{
				PropertyInfo property => property.GetValue(entry),
				FieldInfo field => field.GetValue(entry),
				_ => null
			};
			return value == null ? combatState.RoundNumber : Convert.ToInt32(value, CultureInfo.InvariantCulture);
		}
		catch
		{
			return combatState.RoundNumber;
		}
	}

	private static bool MatchesCountWindow(int roundNumber, CombatState combatState, CardExtraEffect effect)
	{
		if (!CountEventUsesWindow(effect.CountEvent))
		{
			return true;
		}
		int turns = Math.Max(1, effect.CountTurns);
		return effect.CountWindow switch
		{
			CardExtraEffectCountWindow.ThisTurn => roundNumber == combatState.RoundNumber,
			CardExtraEffectCountWindow.LastTurns => effect.CountWindowInclusion == CardExtraEffectCountWindowInclusion.ExcludeThisTurn
				? roundNumber < combatState.RoundNumber && roundNumber >= combatState.RoundNumber - turns
				: roundNumber >= combatState.RoundNumber - (turns - 1),
			_ => true
		};
	}

private static bool MatchesCountCardFilters(Player owner, CardModel card, CardExtraEffect effect)
{
	if (card == null || owner == null || effect == null)
	{
		return false;
	}

	CardExtraEffectCountCardFilter filter = GetEffectiveCountCardFilter(effect);

	if (filter == CardExtraEffectCountCardFilter.CreatesCards)
	{
		if (!CardCreatesMatchingCards(owner, card, effect.CountCardPool, effect.CountCardType, effect))
		{
			return false;
		}
	}
	else
	{
		if (filter != CardExtraEffectCountCardFilter.Any && !MatchesCountCardEffectFilter(card, filter))
		{
			return false;
		}

		if (!PassesCostFilter(card, effect, effect.CountCardType))
		{
			return false;
		}

		if (!MatchesCountPool(owner, card, effect.CountCardPool))
		{
			return false;
		}

		if (!MatchesGeneratedCardType(card, effect.CountCardType))
		{
			return false;
		}

		if (!PassesRarityFilter(card, effect.CountCardRarity))
		{
			return false;
		}

		if (!PassesNameFilter(card, effect))
		{
			return false;
		}
	}

	if (!PassesCardMatchFilter(card, effect))
	{
		return false;
		}

		return true;
	}

	internal static bool MatchesQuestObjectiveCard(Player owner, CardModel card, CardExtraEffect effect)
	{
		return MatchesCountCardFilters(owner, card, effect);
	}

	private static int GetCountAggregationAmount(CardModel card, CardExtraEffect effect)
	{
		if (card == null || effect == null)
		{
			return 0;
		}

		return GetEffectiveCountAggregationMode(effect) switch
		{
			CardExtraEffectCountAggregationMode.MatchingEffectAmount => GetCountCardFilterAmount(card, effect),
			CardExtraEffectCountAggregationMode.CurrentEnergyCost => GetCardEnergyCostAmount(card, useBaseCost: false),
			CardExtraEffectCountAggregationMode.BaseEnergyCost => GetCardEnergyCostAmount(card, useBaseCost: true),
			CardExtraEffectCountAggregationMode.CurrentStarCost => GetCardStarCostAmount(card, useBaseCost: false),
			CardExtraEffectCountAggregationMode.BaseStarCost => GetCardStarCostAmount(card, useBaseCost: true),
			_ => 1
		};
	}

	private static int GetCardEnergyCostAmount(CardModel card, bool useBaseCost)
	{
		if (card == null)
		{
			return 0;
		}

		try
		{
			if (card.EnergyCost.CostsX)
			{
				return 0;
			}

			int cost;
			if (useBaseCost)
			{
				cost = card.EnergyCost.GetWithModifiers(CostModifiers.None);
			}
			else
			{
				using IDisposable _ = CardEditorEnergyCostVisibilityHelper.SuppressCardEditorCostHooksScoped();
				cost = card.EnergyCost.GetWithModifiers(CostModifiers.All);
			}
			return Math.Max(0, cost);
		}
		catch
		{
			return 0;
		}
	}

	private static int GetCardStarCostAmount(CardModel card, bool useBaseCost)
	{
		if (card == null)
		{
			return 0;
		}

		try
		{
			if (card.HasStarCostX)
			{
				return 0;
			}

			int cost;
			if (useBaseCost)
			{
				cost = card.BaseStarCost;
			}
			else
			{
				using IDisposable _ = CardEditorEnergyCostVisibilityHelper.SuppressCardEditorCostHooksScoped();
				cost = card.CurrentStarCost;
			}
			return Math.Max(0, cost);
		}
		catch
		{
			return 0;
		}
	}

	private static int GetCountCardFilterAmount(CardModel card, CardExtraEffect effect)
	{
		if (card == null || effect == null)
		{
			return 0;
		}

		CardExtraEffectCountCardFilter filter = GetEffectiveCountCardFilter(effect);
		if (!CountCardFilterSupportsAmount(filter))
		{
			return MatchesCountCardEffectFilter(card, filter) ? 1 : 0;
		}

		int currentDynamicAmount = GetCountCardFilterDynamicAmount(card, filter);
		int currentExtraAmount = GetCountCardFilterExtraEffectAmount(card, filter);

		if (!TryBuildCanonicalCountAmountCard(card, out CardModel? canonicalCard) || canonicalCard == null)
		{
			return Math.Max(currentDynamicAmount, currentExtraAmount);
		}

		int canonicalDynamicAmount = GetCountCardFilterDynamicAmount(canonicalCard, filter);
		int canonicalExtraAmount = GetCountCardFilterExtraEffectAmount(canonicalCard, filter);

		int totalAmount = currentDynamicAmount > 0 ? currentDynamicAmount : currentExtraAmount;
		int additionalExtraAmount = Math.Max(0, currentExtraAmount - canonicalExtraAmount);
		int dynamicIncrease = Math.Max(0, currentDynamicAmount - canonicalDynamicAmount);
		totalAmount += Math.Max(0, additionalExtraAmount - dynamicIncrease);

		return Math.Max(0, totalAmount);
	}

	private static bool TryBuildCanonicalCountAmountCard(CardModel card, out CardModel? canonicalCard)
	{
		canonicalCard = null;
		if (card == null)
		{
			return false;
		}

		try
		{
			CardModel canonical = ModelDb.GetById<CardModel>(card.Id);
			CardModel preview = canonical.ToMutable();
			int upgradeLevels = card.GetSafeCurrentUpgradeLevel();
			bool prevSuppressAll = CardEditorOverrides.SuppressAllOverrides;
			bool prevSuppressUpgrade = CardEditorOverrides.SuppressUpgradeOverrides;
			try
			{
				CardEditorOverrides.SuppressAllOverrides = true;
				CardEditorOverrides.SuppressUpgradeOverrides = true;
				for (int i = 0; i < upgradeLevels && preview.IsUpgradable; i++)
				{
					preview.UpgradeInternal();
					preview.FinalizeUpgradeInternal();
				}
			}
			finally
			{
				CardEditorOverrides.SuppressAllOverrides = prevSuppressAll;
				CardEditorOverrides.SuppressUpgradeOverrides = prevSuppressUpgrade;
			}

			canonicalCard = preview;
			return true;
		}
		catch
		{
			return false;
		}
	}

	private static int GetCountCardFilterExtraEffectAmount(CardModel card, CardExtraEffectCountCardFilter filter)
	{
		if (card == null || filter == CardExtraEffectCountCardFilter.Any)
		{
			return 0;
		}

		int total = 0;
		try
		{
			foreach (CardExtraEffect effect in GetRuntimeEffectsIncludingBorrowedSources(card.GetConcreteCombatState(), card))
			{
				if (effect == null || !DoesEffectContributeToCountCardFilter(effect, filter))
				{
					continue;
				}

				total += GetConfiguredCountableEffectAmount(effect);
			}
		}
		catch
		{
		}

		return Math.Max(0, total);
	}

	private static int GetConfiguredCountableEffectAmount(CardExtraEffect effect)
	{
		if (effect == null)
		{
			return 0;
		}

		return effect.AmountIsX
			? Math.Max(0, effect.Amount + effect.AmountXPlus)
			: Math.Max(0, effect.Amount);
	}

	private static bool DoesEffectContributeToCountCardFilter(CardExtraEffect effect, CardExtraEffectCountCardFilter filter)
	{
		return filter switch
		{
			CardExtraEffectCountCardFilter.GainBlock => effect.Kind == CardExtraEffectKind.GainBlock,
			CardExtraEffectCountCardFilter.DealDamage => effect.Kind == CardExtraEffectKind.DealDamage,
			CardExtraEffectCountCardFilter.DrawCards => effect.Kind == CardExtraEffectKind.DrawCards,
			CardExtraEffectCountCardFilter.GainEnergy => effect.Kind == CardExtraEffectKind.GainEnergy,
			CardExtraEffectCountCardFilter.GainStars => effect.Kind == CardExtraEffectKind.GainStars,
			CardExtraEffectCountCardFilter.Heal => effect.Kind == CardExtraEffectKind.Heal,
			CardExtraEffectCountCardFilter.LoseHp => effect.Kind == CardExtraEffectKind.LoseHp,
			CardExtraEffectCountCardFilter.Strength => effect.Kind is CardExtraEffectKind.GainStrength or CardExtraEffectKind.LoseStrength,
			CardExtraEffectCountCardFilter.Dexterity => effect.Kind is CardExtraEffectKind.GainDexterity or CardExtraEffectKind.LoseDexterity,
			CardExtraEffectCountCardFilter.Focus => effect.Kind is CardExtraEffectKind.GainFocus or CardExtraEffectKind.LoseFocus,
			CardExtraEffectCountCardFilter.Weak => effect.Kind == CardExtraEffectKind.ApplyWeak,
			CardExtraEffectCountCardFilter.Frail => effect.Kind == CardExtraEffectKind.ApplyFrail,
			CardExtraEffectCountCardFilter.Vulnerable => effect.Kind == CardExtraEffectKind.ApplyVulnerable,
			CardExtraEffectCountCardFilter.Poison => effect.Kind == CardExtraEffectKind.ApplyPoison,
			CardExtraEffectCountCardFilter.Doom => effect.Kind == CardExtraEffectKind.ApplyDoom,
			CardExtraEffectCountCardFilter.Constrict => effect.Kind == CardExtraEffectKind.ApplyConstrict,
			CardExtraEffectCountCardFilter.Artifact => effect.Kind == CardExtraEffectKind.GainArtifact,
			CardExtraEffectCountCardFilter.Thorns => effect.Kind == CardExtraEffectKind.GainThorns,
			CardExtraEffectCountCardFilter.Regen => effect.Kind == CardExtraEffectKind.GainRegen,
			CardExtraEffectCountCardFilter.Plating => effect.Kind == CardExtraEffectKind.GainPlating,
			CardExtraEffectCountCardFilter.Intangible => effect.Kind == CardExtraEffectKind.GainIntangible,
			CardExtraEffectCountCardFilter.Buffer => effect.Kind == CardExtraEffectKind.GainBuffer,
			CardExtraEffectCountCardFilter.Vigor => effect.Kind == CardExtraEffectKind.GainVigor,
			CardExtraEffectCountCardFilter.Blur => effect.Kind == CardExtraEffectKind.GainBlur,
			CardExtraEffectCountCardFilter.Ritual => effect.Kind == CardExtraEffectKind.GainRitual,
			CardExtraEffectCountCardFilter.Summon => effect.Kind == CardExtraEffectKind.Summon,
			CardExtraEffectCountCardFilter.Forge => effect.Kind == CardExtraEffectKind.Forge,
			CardExtraEffectCountCardFilter.EnergyCostModifier => effect.Kind is CardExtraEffectKind.CardCostsLess or CardExtraEffectKind.CardTypeCostsLess or CardExtraEffectKind.DrawnCardsCostLess or CardExtraEffectKind.GeneratedCardsCostLess,
			CardExtraEffectCountCardFilter.StarCostModifier => effect.Kind is CardExtraEffectKind.CardStarCostsLess or CardExtraEffectKind.CardTypeStarCostsLess,
			CardExtraEffectCountCardFilter.ActsThroughOsty => effect.Kind == CardExtraEffectKind.OstyAction,
			_ => false
		};
	}

	private static int GetCountCardFilterDynamicAmount(CardModel card, CardExtraEffectCountCardFilter filter)
	{
		return filter switch
		{
			CardExtraEffectCountCardFilter.DealDamage => GetMaxDynamicVarAmount(card, "Damage", "CalculatedDamage", "ExtraDamage", "OstyDamage"),
			CardExtraEffectCountCardFilter.GainBlock => GetMaxDynamicVarAmount(card, "Block"),
			CardExtraEffectCountCardFilter.DrawCards => GetMaxDynamicVarAmount(card, "Cards"),
			CardExtraEffectCountCardFilter.GainEnergy => GetMaxDynamicVarAmount(card, "Energy"),
			CardExtraEffectCountCardFilter.GainStars => GetMaxDynamicVarAmount(card, "Stars"),
			CardExtraEffectCountCardFilter.Heal => GetMaxDynamicVarAmount(card, "Heal"),
			CardExtraEffectCountCardFilter.LoseHp => GetMaxDynamicVarAmount(card, "HpLoss"),
			CardExtraEffectCountCardFilter.Strength => GetMaxDynamicVarAmount(card, "StrengthPower"),
			CardExtraEffectCountCardFilter.Dexterity => GetMaxDynamicVarAmount(card, "DexterityPower"),
			CardExtraEffectCountCardFilter.Focus => GetMaxDynamicVarAmount(card, "FocusPower"),
			CardExtraEffectCountCardFilter.Weak => GetMaxDynamicVarAmount(card, "WeakPower"),
			CardExtraEffectCountCardFilter.Frail => GetMaxDynamicVarAmount(card, "FrailPower"),
			CardExtraEffectCountCardFilter.Vulnerable => GetMaxDynamicVarAmount(card, "VulnerablePower"),
			CardExtraEffectCountCardFilter.Poison => GetMaxDynamicVarAmount(card, "PoisonPower"),
			CardExtraEffectCountCardFilter.Doom => GetMaxDynamicVarAmount(card, "DoomPower"),
			CardExtraEffectCountCardFilter.Constrict => GetMaxDynamicVarAmount(card, "ConstrictPower"),
			CardExtraEffectCountCardFilter.Artifact => GetMaxDynamicVarAmount(card, "ArtifactPower"),
			CardExtraEffectCountCardFilter.Thorns => GetMaxDynamicVarAmount(card, "ThornsPower"),
			CardExtraEffectCountCardFilter.Regen => GetMaxDynamicVarAmount(card, "RegenPower"),
			CardExtraEffectCountCardFilter.Plating => GetMaxDynamicVarAmount(card, "PlatingPower"),
			CardExtraEffectCountCardFilter.Intangible => GetMaxDynamicVarAmount(card, "IntangiblePower"),
			CardExtraEffectCountCardFilter.Buffer => GetMaxDynamicVarAmount(card, "BufferPower"),
			CardExtraEffectCountCardFilter.Vigor => GetMaxDynamicVarAmount(card, "VigorPower"),
			CardExtraEffectCountCardFilter.Blur => GetMaxDynamicVarAmount(card, "BlurPower"),
			CardExtraEffectCountCardFilter.Ritual => GetMaxDynamicVarAmount(card, "RitualPower"),
			CardExtraEffectCountCardFilter.Summon => GetMaxDynamicVarAmount(card, "Summon"),
			CardExtraEffectCountCardFilter.Forge => GetMaxDynamicVarAmount(card, "Forge", "CalculatedForge"),
			_ => 0
		};
	}

	private static int GetMaxDynamicVarAmount(CardModel card, params string[] keys)
	{
		if (card == null || keys == null || keys.Length == 0)
		{
			return 0;
		}

		int best = 0;
		foreach (string key in keys)
		{
			best = Math.Max(best, GetDynamicVarAmount(card, key));
		}

		return best;
	}

	private static int GetDynamicVarAmount(CardModel card, string key)
	{
		if (card == null || string.IsNullOrWhiteSpace(key))
		{
			return 0;
		}

		CardModel? cursor = card;
		for (int i = 0; i < 8 && cursor != null; i++)
		{
			try
			{
				if (cursor.DynamicVars.TryGetValue(key, out var dynamicVar))
				{
					return Math.Max(0, (int)decimal.Round(dynamicVar.BaseValue, 0, MidpointRounding.AwayFromZero));
				}
			}
			catch
			{
			}

			try
			{
				cursor = cursor.CloneOf;
			}
			catch
			{
				break;
			}
		}

		return 0;
	}

	private static OrbModel? GetOrbInPosition(Player player, CardExtraEffectOrbSelection selection)
	{
		IReadOnlyList<OrbModel>? orbs = player?.PlayerCombatState?.OrbQueue?.Orbs;
		if (orbs == null || orbs.Count == 0)
		{
			return null;
		}

		return selection switch
		{
			// Orbs[0] (oldest, next to evoke) renders RIGHTMOST on screen; the newest channel is
			// leftmost. This must agree with SelectOrb so a card's condition and action halves
			// look at the same orb.
			CardExtraEffectOrbSelection.Rightmost => orbs[0],
			CardExtraEffectOrbSelection.Middle => orbs[(orbs.Count - 1) / 2],
			_ => orbs[orbs.Count - 1]
		};
	}

	internal static void RecordOrbEvoked(CombatState combatState, OrbModel orb)
	{
		if (combatState == null || orb?.Owner?.Creature == null)
		{
			return;
		}

		List<OrbEvokeCountEntry> entries = _orbEvokeHistory.GetOrCreateValue(combatState);
		entries.Add(new OrbEvokeCountEntry
		{
			Actor = orb.Owner.Creature,
			Orb = orb,
			RoundNumber = combatState.RoundNumber,
			CurrentSide = combatState.CurrentSide
		});
	}

	internal static void RecordResourceCount(CombatState combatState, Creature actor, CardExtraEffectCountEvent countEvent, int amount)
	{
		RecordResourceCount(combatState, actor, countEvent, amount, ResourceCountSource.Other);
	}

	internal static void RecordBetweenTurnsBlockClear(CombatState combatState, Creature actor, int amount)
	{
		RecordResourceCount(combatState, actor, CardExtraEffectCountEvent.BlockLost, amount, ResourceCountSource.BetweenTurnsBlockClear);
	}

	internal static Task TriggerPowerCountEventAsync(CombatState combatState, Creature actor, CardExtraEffectCountEvent countEvent, ResourceCountSource source = ResourceCountSource.Other, PowerModel? triggeringPower = null, CardModel? triggeringCard = null, int amount = 1)
	{
		if (combatState == null || actor == null)
		{
			return Task.CompletedTask;
		}

		ulong? netId = LocalContext.NetId;
		if (!netId.HasValue)
		{
			return Task.CompletedTask;
		}

		return TriggerPowerCountEventAsync(combatState, actor, actor, countEvent, source, triggeringPower, triggeringCard, netId.Value, amount);
	}

	internal static Task TriggerPowerCountEventWithContextAsync(CombatState combatState, PlayerChoiceContext choiceContext, Creature actor, CardExtraEffectCountEvent countEvent, ResourceCountSource source = ResourceCountSource.Other, PowerModel? triggeringPower = null, CardModel? triggeringCard = null, CardPlay? triggeringPlay = null, int amount = 1)
	{
		if (combatState == null || choiceContext == null || actor == null)
		{
			return Task.CompletedTask;
		}

		return TriggerPowerCountEventWithContextAsync(
			combatState,
			choiceContext,
			actor,
			actor,
			countEvent,
			source,
			triggeringPower,
			triggeringCard,
			triggeringPlay,
			amount);
	}

	private static async Task TriggerPowerCountEventWithContextAsync(
		CombatState combatState,
		PlayerChoiceContext choiceContext,
		Creature powerOwner,
		Creature eventActor,
		CardExtraEffectCountEvent countEvent,
		ResourceCountSource source,
		PowerModel? triggeringPower,
		CardModel? triggeringCard,
		CardPlay? triggeringPlay,
		int amount)
	{
		if (combatState == null || choiceContext == null || powerOwner == null || eventActor == null)
		{
			return;
		}

		HashSet<Creature> listeners = new HashSet<Creature>(ReferenceEqualityComparer<Creature>.Instance);
		if (powerOwner != null)
		{
			listeners.Add(powerOwner);
		}

		foreach (Player player in combatState.Players)
		{
			if (player?.Creature != null)
			{
				listeners.Add(player.Creature);
			}
		}

		foreach (Creature enemy in combatState.Enemies)
		{
			if (enemy != null)
			{
				listeners.Add(enemy);
			}
		}

		foreach (Creature listener in listeners)
		{
			CardEditorExtraEffectPower? power = listener.GetPower<CardEditorExtraEffectPower>();
			if (power == null)
			{
				continue;
			}

			choiceContext.PushModel(power);
			try
			{
				await power.TriggerCountEvent(choiceContext, countEvent, source, triggeringPlay, triggeringCard, triggeringPower, eventActor, amount);
				power.InvokeExecutionFinished();
			}
			finally
			{
				choiceContext.PopModel(power);
			}
		}
	}

	private static async Task TriggerPowerCountEventAsync(
		CombatState combatState,
		Creature powerOwner,
		Creature eventActor,
		CardExtraEffectCountEvent countEvent,
		ResourceCountSource source,
		PowerModel? triggeringPower,
		CardModel? triggeringCard,
		ulong netId,
		int amount)
	{
		if (combatState == null || powerOwner == null || eventActor == null)
		{
			return;
		}

		HashSet<Creature> listeners = new HashSet<Creature>(ReferenceEqualityComparer<Creature>.Instance);
		if (powerOwner != null)
		{
			listeners.Add(powerOwner);
		}

		foreach (Player player in combatState.Players)
		{
			if (player?.Creature != null)
			{
				listeners.Add(player.Creature);
			}
		}

		foreach (Creature enemy in combatState.Enemies)
		{
			if (enemy != null)
			{
				listeners.Add(enemy);
			}
		}

		foreach (Creature listener in listeners)
		{
			CardEditorExtraEffectPower? power = listener.GetPower<CardEditorExtraEffectPower>();
			if (power == null)
			{
				continue;
			}

			HookPlayerChoiceContext choiceContext = CardEditorCombatStateCompat.CreateHookPlayerChoiceContext(power, netId, combatState, GameActionType.Combat);
			Task task = power.TriggerCountEvent(choiceContext, countEvent, source, triggeringCard: triggeringCard, triggeringPower: triggeringPower, eventActor: eventActor, amount: amount);
			bool completed = await choiceContext.AssignTaskAndWaitForPauseOrCompletion(task);
			if (!completed && choiceContext.GameAction != null)
			{
				await choiceContext.GameAction.CompletionTask;
			}
		}
	}

	internal static void TriggerPowerCountEvent(CombatState combatState, Creature actor, CardExtraEffectCountEvent countEvent, ResourceCountSource source = ResourceCountSource.Other, PowerModel? triggeringPower = null, CardModel? triggeringCard = null, int amount = 1)
	{
		TaskHelper.RunSafely(TriggerPowerCountEventAsync(combatState, actor, countEvent, source, triggeringPower, triggeringCard, amount));
	}

	private static void RecordResourceCount(CombatState combatState, Creature actor, CardExtraEffectCountEvent countEvent, int amount, ResourceCountSource source)
	{
		if (combatState == null || actor == null || amount <= 0)
		{
			return;
		}

		List<ResourceCountEntry> entries = _resourceCountHistory.GetOrCreateValue(combatState);
		entries.Add(new ResourceCountEntry
		{
			Actor = actor,
			CountEvent = countEvent,
			Amount = amount,
			RoundNumber = combatState.RoundNumber,
			CurrentSide = combatState.CurrentSide,
			Source = source
		});
	}

	internal static void ClearOrbCountHistory(CombatState combatState)
	{
		if (combatState == null)
		{
			return;
		}

		_orbEvokeHistory.Remove(combatState);
	}

	internal static void ClearResourceCountHistory(CombatState combatState)
	{
		if (combatState == null)
		{
			return;
		}

		_resourceCountHistory.Remove(combatState);
	}

private static bool MatchesGrantCardFilters(Player owner, CardModel card, CardExtraEffect effect)
{
	if (card == null || owner == null || effect == null)
	{
		return false;
	}

	CardExtraEffectCountCardFilter filter = effect.CardSelectionFilter;
	if (filter == CardExtraEffectCountCardFilter.CreatesCards)
	{
		if (!CardCreatesMatchingCards(owner, card, effect.CardSelectionPool, effect.CardSelectionType, effect))
		{
			return false;
		}
	}
	else
	{
		if (filter != CardExtraEffectCountCardFilter.Any && !MatchesCountCardEffectFilter(card, filter))
		{
			return false;
		}

		if (!PassesCostFilter(card, effect, effect.CardSelectionType))
		{
			return false;
		}

		if (!MatchesCountPool(owner, card, effect.CardSelectionPool))
		{
			return false;
		}

		if (!MatchesGeneratedCardType(card, effect.CardSelectionType))
		{
			return false;
		}

		if (!PassesRarityFilter(card, effect.CardSelectionRarity))
		{
			return false;
		}

		if (!PassesNameFilter(card, effect))
		{
			return false;
		}
	}

	return true;
}

	private static bool HasPowerTriggerCardFilters(CardExtraEffect effect)
	{
		if (effect == null)
		{
			return false;
		}

		bool hasCardMatchFilter = effect.CardMatchMode switch
		{
			CardExtraEffectCardMatchMode.CardId => !string.IsNullOrWhiteSpace(effect.MatchCardId)
				&& TryParseSpecificCardId(effect.MatchCardId.Trim(), out _),
			CardExtraEffectCardMatchMode.NameContains => NormalizeNameFilterText(effect.MatchCardId) != null,
			CardExtraEffectCardMatchMode.Tag when effect.MatchTagKind == CardExtraEffectCardMatchTagKind.Custom => !string.IsNullOrWhiteSpace(effect.MatchCustomTag),
			CardExtraEffectCardMatchMode.Tag => effect.MatchVanillaTag != CardTag.None,
			CardExtraEffectCardMatchMode.CustomKeyword => NormalizeCustomKeywordName(effect.MatchCustomKeyword) != null,
			_ => false
		};

		return !IsUnrestrictedGeneratedPool(effect.TriggerCardPool)
			|| effect.TriggerCardType != CardGeneratedCardType.Any
			|| effect.TriggerCardRarity != CardExtraEffectCardRarityFilter.Any
			|| effect.TriggerCardFilter != CardExtraEffectCountCardFilter.Any
			|| hasCardMatchFilter
			|| effect.CostFilterEnabled
			|| (effect.NameFilterEnabled && NormalizeNameFilterText(effect.NameFilterText) != null);
	}

	internal static bool MatchesPowerTriggerCardFilters(Player? owner, CardModel? triggeringCard, CardExtraEffect effect)
	{
		if (effect == null)
		{
			return true;
		}

		if (!IsPowerEffect(effect))
		{
			return true;
		}

		// Timed powers don't have a "triggering card" filter.
		if (effect.Trigger is CardExtraEffectTrigger.TurnBoundary
			or CardExtraEffectTrigger.EndOfTurnInHand
			or CardExtraEffectTrigger.StartOfTurn
			or CardExtraEffectTrigger.EndOfTurn
			or CardExtraEffectTrigger.StartOfEnemyTurn
			or CardExtraEffectTrigger.EndOfEnemyTurn)
		{
			return true;
		}

		if (triggeringCard == null)
		{
			return !HasPowerTriggerCardFilters(effect);
		}

	CardExtraEffectCountCardFilter filter = effect.TriggerCardFilter;
	if (filter == CardExtraEffectCountCardFilter.CreatesCards)
	{
		if (!CardCreatesMatchingCards(owner, triggeringCard, effect.TriggerCardPool, effect.TriggerCardType, effect))
		{
			return false;
		}
	}
	else
	{
		if (filter != CardExtraEffectCountCardFilter.Any && !MatchesCountCardEffectFilter(triggeringCard, filter))
		{
			return false;
		}

		if (!PassesCostFilter(triggeringCard, effect, effect.TriggerCardType))
		{
			return false;
		}

		if (owner != null && !MatchesCountPool(owner, triggeringCard, effect.TriggerCardPool))
		{
			return false;
		}

		if (!IsUnrestrictedGeneratedPool(effect.TriggerCardPool) && owner == null)
		{
			return false;
		}

		if (!MatchesGeneratedCardType(triggeringCard, effect.TriggerCardType))
		{
			return false;
		}

		if (!PassesRarityFilter(triggeringCard, effect.TriggerCardRarity))
		{
			return false;
		}

		if (!PassesNameFilter(triggeringCard, effect))
		{
			return false;
		}
	}

	if (!PassesCardMatchFilter(triggeringCard, effect))
	{
		return false;
		}

		return true;
	}

	internal static Creature? ResolvePowerHostCreature(CombatState combatState, CardPlay cardPlay, CardExtraEffect effect)
	{
		return ResolvePowerHostCreatures(combatState, cardPlay, effect).FirstOrDefault();
	}

	internal static IReadOnlyList<Creature> ResolvePowerHostCreatures(CombatState combatState, CardPlay cardPlay, CardExtraEffect effect)
	{
		if (combatState == null || cardPlay?.Card?.Owner?.Creature == null || effect == null)
		{
			return Array.Empty<Creature>();
		}

		Creature ownerCreature = cardPlay.Card.Owner.Creature;
		switch (GetEffectivePowerHost(effect))
		{
			case CardExtraEffectPowerHost.CardOwner:
				return new[] { ownerCreature };
			case CardExtraEffectPowerHost.EffectTargets:
				return ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target)
					.Where(creature => creature != null && creature.IsAlive)
					.Distinct(ReferenceEqualityComparer<Creature>.Instance)
					.ToList();
			case CardExtraEffectPowerHost.TriggerTarget:
			default:
				Creature? target = effect.Target switch
				{
					CardExtraEffectTarget.Self => ownerCreature,
					CardExtraEffectTarget.RandomEnemy => combatState.RunState.Rng.CombatTargets.NextItem(combatState.GetOpponentsOf(ownerCreature).Where(c => c.IsAlive)),
					CardExtraEffectTarget.AnyPlayer => ResolveFriendlySingleTarget(combatState, ownerCreature, cardPlay, includeSelf: true),
					CardExtraEffectTarget.AnyAlly => ResolveFriendlySingleTarget(combatState, ownerCreature, cardPlay, includeSelf: false),
					CardExtraEffectTarget.AllAllies => ResolveFriendlySingleTarget(combatState, ownerCreature, cardPlay, includeSelf: true),
					CardExtraEffectTarget.EventTarget => cardPlay.Target,
					CardExtraEffectTarget.AllEnemies => ResolveSingleTarget(combatState, ownerCreature, cardPlay),
					_ => ResolveSingleTarget(combatState, ownerCreature, cardPlay)
				};
				return target != null ? new[] { target } : Array.Empty<Creature>();
		}
	}

	internal static bool MatchesAffectedCardFilters(Player owner, CardModel card, CardExtraEffect effect)
	{
		if (owner == null || card == null || effect == null)
		{
			return true;
		}

	CardExtraEffectCountCardFilter filter = effect.TriggerCardFilter;
	if (filter == CardExtraEffectCountCardFilter.CreatesCards)
	{
		if (!CardCreatesMatchingCards(owner, card, effect.TriggerCardPool, effect.TriggerCardType, effect))
		{
			return false;
		}
	}
	else
	{
		if (filter != CardExtraEffectCountCardFilter.Any && !MatchesCountCardEffectFilter(card, filter))
		{
			return false;
		}

		if (!PassesCostFilter(card, effect, effect.TriggerCardType))
		{
			return false;
		}

		if (!MatchesCountPool(owner, card, effect.TriggerCardPool))
		{
			return false;
		}

		if (!MatchesGeneratedCardType(card, effect.TriggerCardType))
		{
			return false;
		}

		if (!PassesRarityFilter(card, effect.TriggerCardRarity))
		{
			return false;
		}

		if (!PassesNameFilter(card, effect))
		{
			return false;
		}
	}

	if (!PassesCardMatchFilter(card, effect))
	{
		return false;
		}

		return true;
	}

	private static CardType GetEffectiveCardType(CardModel card)
	{
		if (card == null)
		{
			return CardType.None;
		}

		try
		{
			CardType type = card.Type;
			if (type != CardType.None)
			{
				return type;
			}
		}
		catch
		{
			// ignored
		}

		try
		{
			// Some special cards can report Type=None but still have a meaningful rarity bucket.
			// Use rarity as a best-effort fallback so type-based filters work for Status/Curse/Quest cards.
			CardType fromRarity = card.Rarity switch
			{
				CardRarity.Status => CardType.Status,
				CardRarity.Curse => CardType.Curse,
				CardRarity.Quest => CardType.Quest,
				_ => CardType.None
			};
			if (fromRarity != CardType.None)
			{
				return fromRarity;
			}
		}
		catch
		{
			// ignored
		}

		try
		{
			CardModel? cursor = card.CloneOf;
			for (int i = 0; i < 8 && cursor != null; i++)
			{
				CardType type = cursor.Type;
				if (type != CardType.None)
				{
					return type;
				}
				cursor = cursor.CloneOf;
			}
		}
		catch
		{
			// ignored
		}

		try
		{
			return ModelDb.GetById<CardModel>(card.Id).Type;
		}
		catch
		{
			return CardType.None;
		}
	}

	private static bool MatchesCountCardEffectFilter(CardModel card, CardExtraEffectCountCardFilter filter)
	{
		bool HasExtraEffectKind(CardExtraEffectKind kind)
		{
			try
			{
				foreach (CardExtraEffect effect in GetRuntimeEffectsIncludingBorrowedSources(card.GetConcreteCombatState(), card))
				{
					if (effect.Kind == kind)
					{
						return true;
					}
				}
			}
			catch
			{
			}
			return false;
		}

		bool HasAnyExtraEffectKind(params CardExtraEffectKind[] kinds)
		{
			try
			{
				foreach (CardExtraEffect effect in GetRuntimeEffectsIncludingBorrowedSources(card.GetConcreteCombatState(), card))
				{
					for (int i = 0; i < kinds.Length; i++)
					{
						if (effect.Kind == kinds[i])
						{
							return true;
						}
					}
				}
			}
			catch
			{
			}
			return false;
		}

		switch (filter)
		{
			case CardExtraEffectCountCardFilter.GainBlock:
				return CardGainsBlock(card) || HasExtraEffectKind(CardExtraEffectKind.GainBlock);
			case CardExtraEffectCountCardFilter.DealDamage:
				return HasAnyDamageVar(card) || HasExtraEffectKind(CardExtraEffectKind.DealDamage);
			case CardExtraEffectCountCardFilter.ActsThroughOsty:
				return HasDynamicVar(card, "OstyDamage") || HasExtraEffectKind(CardExtraEffectKind.OstyAction);
			case CardExtraEffectCountCardFilter.DrawCards:
				return HasDynamicVar(card, "Cards") || HasExtraEffectKind(CardExtraEffectKind.DrawCards);
			case CardExtraEffectCountCardFilter.GainEnergy:
				return HasDynamicVar(card, "Energy") || HasExtraEffectKind(CardExtraEffectKind.GainEnergy);
			case CardExtraEffectCountCardFilter.GainStars:
				return HasDynamicVar(card, "Stars") || HasExtraEffectKind(CardExtraEffectKind.GainStars);
			case CardExtraEffectCountCardFilter.Heal:
				return HasDynamicVar(card, "Heal") || HasExtraEffectKind(CardExtraEffectKind.Heal);
			case CardExtraEffectCountCardFilter.LoseHp:
				return HasDynamicVar(card, "HpLoss") || HasExtraEffectKind(CardExtraEffectKind.LoseHp);
			case CardExtraEffectCountCardFilter.Strength:
				return HasDynamicVar(card, "StrengthPower")
					|| HasPowerHoverTip(card, "StrengthPower")
					|| HasAnyExtraEffectKind(CardExtraEffectKind.GainStrength, CardExtraEffectKind.LoseStrength);
			case CardExtraEffectCountCardFilter.Dexterity:
				return HasDynamicVar(card, "DexterityPower")
					|| HasPowerHoverTip(card, "DexterityPower")
					|| HasAnyExtraEffectKind(CardExtraEffectKind.GainDexterity, CardExtraEffectKind.LoseDexterity);
			case CardExtraEffectCountCardFilter.Focus:
				return HasDynamicVar(card, "FocusPower")
					|| HasPowerHoverTip(card, "FocusPower")
					|| HasAnyExtraEffectKind(CardExtraEffectKind.GainFocus, CardExtraEffectKind.LoseFocus);
			case CardExtraEffectCountCardFilter.Weak:
				return HasDynamicVar(card, "WeakPower") || HasPowerHoverTip(card, "WeakPower") || HasExtraEffectKind(CardExtraEffectKind.ApplyWeak);
			case CardExtraEffectCountCardFilter.Frail:
				return HasDynamicVar(card, "FrailPower") || HasPowerHoverTip(card, "FrailPower") || HasExtraEffectKind(CardExtraEffectKind.ApplyFrail);
			case CardExtraEffectCountCardFilter.Vulnerable:
				return HasDynamicVar(card, "VulnerablePower") || HasPowerHoverTip(card, "VulnerablePower") || HasExtraEffectKind(CardExtraEffectKind.ApplyVulnerable);
			case CardExtraEffectCountCardFilter.Poison:
				return HasDynamicVar(card, "PoisonPower") || HasPowerHoverTip(card, "PoisonPower") || HasExtraEffectKind(CardExtraEffectKind.ApplyPoison);
			case CardExtraEffectCountCardFilter.Doom:
				return HasDynamicVar(card, "DoomPower") || HasPowerHoverTip(card, "DoomPower") || HasExtraEffectKind(CardExtraEffectKind.ApplyDoom);
			case CardExtraEffectCountCardFilter.Constrict:
				return HasDynamicVar(card, "ConstrictPower") || HasPowerHoverTip(card, "ConstrictPower") || HasExtraEffectKind(CardExtraEffectKind.ApplyConstrict);
			case CardExtraEffectCountCardFilter.Artifact:
				return HasDynamicVar(card, "ArtifactPower") || HasPowerHoverTip(card, "ArtifactPower") || HasExtraEffectKind(CardExtraEffectKind.GainArtifact);
			case CardExtraEffectCountCardFilter.Thorns:
				return HasDynamicVar(card, "ThornsPower") || HasPowerHoverTip(card, "ThornsPower") || HasExtraEffectKind(CardExtraEffectKind.GainThorns);
			case CardExtraEffectCountCardFilter.Regen:
				return HasDynamicVar(card, "RegenPower") || HasPowerHoverTip(card, "RegenPower") || HasExtraEffectKind(CardExtraEffectKind.GainRegen);
			case CardExtraEffectCountCardFilter.Plating:
				return HasDynamicVar(card, "PlatingPower") || HasPowerHoverTip(card, "PlatingPower") || HasExtraEffectKind(CardExtraEffectKind.GainPlating);
			case CardExtraEffectCountCardFilter.Intangible:
				return HasDynamicVar(card, "IntangiblePower") || HasPowerHoverTip(card, "IntangiblePower") || HasExtraEffectKind(CardExtraEffectKind.GainIntangible);
			case CardExtraEffectCountCardFilter.Buffer:
				return HasDynamicVar(card, "BufferPower") || HasPowerHoverTip(card, "BufferPower") || HasExtraEffectKind(CardExtraEffectKind.GainBuffer);
			case CardExtraEffectCountCardFilter.Vigor:
				return HasDynamicVar(card, "VigorPower") || HasPowerHoverTip(card, "VigorPower") || HasExtraEffectKind(CardExtraEffectKind.GainVigor);
			case CardExtraEffectCountCardFilter.Blur:
				return HasDynamicVar(card, "BlurPower") || HasPowerHoverTip(card, "BlurPower") || HasExtraEffectKind(CardExtraEffectKind.GainBlur);
			case CardExtraEffectCountCardFilter.Ritual:
				return HasDynamicVar(card, "RitualPower") || HasPowerHoverTip(card, "RitualPower") || HasExtraEffectKind(CardExtraEffectKind.GainRitual);
			case CardExtraEffectCountCardFilter.Summon:
				return HasDynamicVar(card, "Summon") || HasExtraEffectKind(CardExtraEffectKind.Summon);
			case CardExtraEffectCountCardFilter.Forge:
				return HasDynamicVar(card, "Forge") || HasDynamicVar(card, "CalculatedForge") || HasExtraEffectKind(CardExtraEffectKind.Forge);
			case CardExtraEffectCountCardFilter.EnergyCostModifier:
				return HasAnyExtraEffectKind(CardExtraEffectKind.CardCostsLess, CardExtraEffectKind.CardTypeCostsLess, CardExtraEffectKind.DrawnCardsCostLess, CardExtraEffectKind.GeneratedCardsCostLess);
			case CardExtraEffectCountCardFilter.StarCostModifier:
				return HasAnyExtraEffectKind(CardExtraEffectKind.CardStarCostsLess, CardExtraEffectKind.CardTypeStarCostsLess);
			case CardExtraEffectCountCardFilter.CanBePlayed:
				return CanCardBePlayed(card);
			case CardExtraEffectCountCardFilter.Exhaust:
				return card.Keywords.Contains(CardKeyword.Exhaust);
			case CardExtraEffectCountCardFilter.Ethereal:
				return card.Keywords.Contains(CardKeyword.Ethereal);
			case CardExtraEffectCountCardFilter.Innate:
				return card.Keywords.Contains(CardKeyword.Innate);
			case CardExtraEffectCountCardFilter.Retain:
				return card.Keywords.Contains(CardKeyword.Retain);
			case CardExtraEffectCountCardFilter.Sly:
				return card.Keywords.Contains(CardKeyword.Sly);
			case CardExtraEffectCountCardFilter.Eternal:
				return card.Keywords.Contains(CardKeyword.Eternal);
			case CardExtraEffectCountCardFilter.CreatesCards:
				return CardCreatesCards(card);
			case CardExtraEffectCountCardFilter.HasStarCost:
				return GetCardStarCostAmount(card, useBaseCost: true) > 0;
			case CardExtraEffectCountCardFilter.HasEnergyCost:
				return GetCardEnergyCostAmount(card, useBaseCost: true) > 0;
			default:
				return true;
		}
	}

	private static bool CanCardBePlayed(CardModel? card)
	{
		if (card == null || card.Keywords.Contains(CardKeyword.Unplayable))
		{
			return false;
		}

		CardType effectiveType = GetEffectiveCardType(card);
		return effectiveType is CardType.Attack or CardType.Skill or CardType.Power;
	}

	private static bool CardCreatesCards(CardModel? card, HashSet<string>? visitedSourceCardIds = null)
	{
		if (card == null)
		{
			return false;
		}

		visitedSourceCardIds ??= new HashSet<string>(StringComparer.Ordinal);
		string visitKey = card.Id.ToString();
		if (!visitedSourceCardIds.Add(visitKey))
		{
			return false;
		}

		try
		{
			foreach (CardExtraEffect effect in GetRuntimeEffectsIncludingBorrowedSources(card.GetConcreteCombatState(), card))
			{
				if (EffectCreatesCards(effect, visitedSourceCardIds))
				{
					return true;
				}
			}
		}
		catch
		{
		}

		try
		{
			CombatState? combatState = card.GetConcreteCombatState();
			if (combatState != null)
			{
				foreach (CardExtraEffect effect in CardEditorTemporaryExtraEffectController.GetEffects(combatState, card))
				{
					if (EffectCreatesCards(effect, visitedSourceCardIds))
					{
						return true;
					}
				}
			}
		}
		catch
		{
		}

		return CardTypeCreatesCardsViaIl(card.GetType());
	}

	private static bool EffectCreatesCards(CardExtraEffect? effect, HashSet<string> visitedSourceCardIds)
	{
		if (effect == null)
		{
			return false;
		}

		if (effect.BranchEffect != null && EffectCreatesCards(effect.BranchEffect, visitedSourceCardIds))
		{
			return true;
		}

		switch (effect.Kind)
		{
			case CardExtraEffectKind.AddRandomCardToHand:
			case CardExtraEffectKind.ChooseOneOfThreeCardsToHand:
			case CardExtraEffectKind.PlayRandomGeneratedCard:
			case CardExtraEffectKind.AddCopyOfThisCard:
			case CardExtraEffectKind.AddExactCopyOfThisCardToDeck:
			case CardExtraEffectKind.AddSpecificCardToHand:
			case CardExtraEffectKind.CopyCardsFromPileToDeck:
			case CardExtraEffectKind.CopyExactCardsFromPileToDeck:
				return true;
			case CardExtraEffectKind.RunEffectSourceCard:
				if (!string.IsNullOrWhiteSpace(effect.SpecificCardId)
					&& TryParseSpecificCardId(effect.SpecificCardId.Trim(), out ModelId sourceId))
				{
					try
					{
						CardModel? sourceCard = ModelDb.GetByIdOrNull<CardModel>(sourceId);
						return sourceCard != null && CardCreatesCards(sourceCard, visitedSourceCardIds);
					}
					catch
					{
					}
				}
				return false;
			default:
				return false;
		}
	}

	private static bool CardTypeCreatesCardsViaIl(Type? cardType)
	{
		if (cardType == null)
		{
			return false;
		}

		lock (_cardCreatesCardsIlCacheLock)
		{
			if (_cardCreatesCardsIlCache.TryGetValue(cardType, out bool cached))
			{
				return cached;
			}
		}

		MethodInfo? onPlay = cardType.GetMethod("OnPlay", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
		bool createsCards = MethodCallsGeneratedCardAdd(onPlay, cardType, new HashSet<MethodBase>(), remainingDepth: 2);

		lock (_cardCreatesCardsIlCacheLock)
		{
			_cardCreatesCardsIlCache[cardType] = createsCards;
		}

		return createsCards;
	}

	private static bool MethodCallsGeneratedCardAdd(MethodBase? method, Type ownerType, HashSet<MethodBase> visitedMethods, int remainingDepth)
	{
		if (method == null || remainingDepth < 0 || !visitedMethods.Add(method))
		{
			return false;
		}

		foreach (MethodBase calledMethod in EnumerateCalledMethods(method))
		{
			if (calledMethod.DeclaringType == typeof(CardPileCmd)
				&& string.Equals(calledMethod.Name, nameof(CardPileCmd.AddGeneratedCardToCombat), StringComparison.Ordinal))
			{
				return true;
			}

			if (remainingDepth > 0
				&& calledMethod.DeclaringType == ownerType
				&& MethodCallsGeneratedCardAdd(calledMethod, ownerType, visitedMethods, remainingDepth - 1))
			{
				return true;
			}
		}

		return false;
	}

	private static IEnumerable<MethodBase> EnumerateCalledMethods(MethodBase method)
	{
		MethodBody? body = method.GetMethodBody();
		byte[]? il = body?.GetILAsByteArray();
		if (il == null || il.Length == 0)
		{
			yield break;
		}

		Module module = method.Module;
		Type[] typeArgs = method.DeclaringType?.GetGenericArguments() ?? Type.EmptyTypes;
		Type[] methodArgs = method is MethodInfo methodInfo && methodInfo.IsGenericMethod
			? methodInfo.GetGenericArguments()
			: Type.EmptyTypes;

		int position = 0;
		while (position < il.Length)
		{
			OpCode opCode = ReadNextOpCode(il, ref position);
			if (string.IsNullOrEmpty(opCode.Name))
			{
				yield break;
			}

			int operandStart = position;
			int operandSize = GetOperandSize(opCode.OperandType, il, operandStart);
			if (operandSize < 0 || operandStart + operandSize > il.Length)
			{
				yield break;
			}

			if (opCode.OperandType == OperandType.InlineMethod)
			{
				int metadataToken = BitConverter.ToInt32(il, operandStart);
				MethodBase? resolvedMethod = null;
				try
				{
					resolvedMethod = module.ResolveMethod(metadataToken, typeArgs, methodArgs);
				}
				catch
				{
				}

				if (resolvedMethod != null)
				{
					yield return resolvedMethod;
				}
			}

			position = operandStart + operandSize;
		}
	}

	private static OpCode ReadNextOpCode(byte[] il, ref int position)
	{
		if (position >= il.Length)
		{
			return default;
		}

		byte first = il[position++];
		if (first != 0xFE)
		{
			return _oneByteOpCodes[first];
		}

		if (position >= il.Length)
		{
			return default;
		}

		byte second = il[position++];
		return _twoByteOpCodes[second];
	}

	private static int GetOperandSize(OperandType operandType, byte[] il, int operandStart)
	{
		return operandType switch
		{
			OperandType.InlineNone => 0,
			OperandType.ShortInlineBrTarget => 1,
			OperandType.ShortInlineI => 1,
			OperandType.ShortInlineVar => 1,
			OperandType.InlineVar => 2,
			OperandType.InlineI => 4,
			OperandType.InlineBrTarget => 4,
			OperandType.InlineField => 4,
			OperandType.InlineMethod => 4,
			OperandType.InlineSig => 4,
			OperandType.InlineString => 4,
			OperandType.InlineTok => 4,
			OperandType.InlineType => 4,
			OperandType.ShortInlineR => 4,
			OperandType.InlineI8 => 8,
			OperandType.InlineR => 8,
			OperandType.InlineSwitch => operandStart + 4 > il.Length ? -1 : 4 + (4 * BitConverter.ToInt32(il, operandStart)),
			_ => 0
		};
	}

	private static OpCode[] BuildOpCodeMap(bool twoByte)
	{
		OpCode[] map = new OpCode[256];
		foreach (FieldInfo field in typeof(OpCodes).GetFields(BindingFlags.Public | BindingFlags.Static))
		{
			if (field.FieldType != typeof(OpCode))
			{
				continue;
			}

			OpCode opCode = (OpCode)field.GetValue(null)!;
			ushort value = unchecked((ushort)opCode.Value);
			if (!twoByte)
			{
				if (value < 0x100)
				{
					map[value] = opCode;
				}
			}
			else if ((value & 0xFF00) == 0xFE00)
			{
				map[value & 0xFF] = opCode;
			}
		}

		return map;
	}

	private static bool HasDynamicVar(CardModel card, string varName)
	{
		CardModel? cursor = card;
		for (int i = 0; i < 8 && cursor != null; i++)
		{
			try
			{
				if (cursor.DynamicVars.ContainsKey(varName))
				{
					return true;
				}
			}
			catch
			{
				// ignored
			}
			try
			{
				cursor = cursor.CloneOf;
			}
			catch
			{
				break;
			}
		}

		try
		{
			return ModelDb.GetById<CardModel>(card.Id).DynamicVars.ContainsKey(varName);
		}
		catch
		{
			return false;
		}
	}

	private static bool HasAnyDamageVar(CardModel card)
	{
		if (HasDynamicVar(card, "Damage")
			|| HasDynamicVar(card, "CalculatedDamage")
			|| HasDynamicVar(card, "ExtraDamage")
			|| HasDynamicVar(card, "OstyDamage"))
		{
			return true;
		}

		CardModel? cursor = card;
		for (int i = 0; i < 8 && cursor != null; i++)
		{
			try
			{
				foreach (string key in cursor.DynamicVars.Keys)
				{
					if (!string.IsNullOrEmpty(key) && key.Contains("Damage", StringComparison.OrdinalIgnoreCase))
					{
						return true;
					}
				}
			}
			catch
			{
				// ignored
			}

			try
			{
				cursor = cursor.CloneOf;
			}
			catch
			{
				break;
			}
		}

		try
		{
			foreach (string key in ModelDb.GetById<CardModel>(card.Id).DynamicVars.Keys)
			{
				if (!string.IsNullOrEmpty(key) && key.Contains("Damage", StringComparison.OrdinalIgnoreCase))
				{
					return true;
				}
			}
		}
		catch
		{
			// ignored
		}

		return false;
	}

	private static bool HasPowerHoverTip(CardModel card, string powerTypeName)
	{
		CardModel? cursor = card;
		for (int i = 0; i < 8 && cursor != null; i++)
		{
			try
			{
				foreach (var tip in cursor.HoverTips)
				{
					string? canonicalName = tip?.CanonicalModel?.GetType().Name;
					if (!string.IsNullOrEmpty(canonicalName) && string.Equals(canonicalName, powerTypeName, StringComparison.Ordinal))
					{
						return true;
					}
				}
			}
			catch
			{
				// ignored
			}

			try
			{
				cursor = cursor.CloneOf;
			}
			catch
			{
				break;
			}
		}

		return false;
	}

	private static bool CardGainsBlock(CardModel card)
	{
		CardModel? cursor = card;
		for (int i = 0; i < 8 && cursor != null; i++)
		{
			try
			{
				if (cursor.GainsBlock)
				{
					return true;
				}
			}
			catch
			{
				// ignored
			}

			try
			{
				cursor = cursor.CloneOf;
			}
			catch
			{
				break;
			}
		}

		try
		{
			return ModelDb.GetById<CardModel>(card.Id).GainsBlock;
		}
		catch
		{
			return false;
		}
	}

	internal static bool MatchesCountPool(Player owner, CardModel card, CardGeneratedCardPool pool)
	{
		CardPoolModel classPool = GetClassFilterPool(card);
		switch (pool)
		{
			case CardGeneratedCardPool.Any:
			case CardGeneratedCardPool.All:
			case CardGeneratedCardPool.AllPools:
				return true;
			case CardGeneratedCardPool.Ancient:
				return card.Rarity == CardRarity.Ancient;
			case CardGeneratedCardPool.Colorless:
				// Base game generally treats "colorless" as a property of the (visual) pool, which includes Tokens.
				return card.VisualCardPool != null && card.VisualCardPool.IsColorless;
			case CardGeneratedCardPool.Status:
				return IsCardInSpecificPool(card, ModelDb.CardPool<StatusCardPool>());
			case CardGeneratedCardPool.Curse:
				return IsCardInSpecificPool(card, ModelDb.CardPool<CurseCardPool>());
			case CardGeneratedCardPool.Quest:
				return IsCardInSpecificPool(card, ModelDb.CardPool<QuestCardPool>());
			case CardGeneratedCardPool.Token:
				return IsCardInSpecificPool(card, ModelDb.CardPool<TokenCardPool>());
			case CardGeneratedCardPool.Event:
				return IsCardInSpecificPool(card, ModelDb.CardPool<EventCardPool>());
			case CardGeneratedCardPool.Ironclad:
				return ReferenceEquals(classPool, ModelDb.CardPool<IroncladCardPool>());
			case CardGeneratedCardPool.Silent:
				return ReferenceEquals(classPool, ModelDb.CardPool<SilentCardPool>());
			case CardGeneratedCardPool.Defect:
				return ReferenceEquals(classPool, ModelDb.CardPool<DefectCardPool>());
			case CardGeneratedCardPool.Regent:
				return ReferenceEquals(classPool, ModelDb.CardPool<RegentCardPool>());
			case CardGeneratedCardPool.Necrobinder:
				return ReferenceEquals(classPool, ModelDb.CardPool<NecrobinderCardPool>());
			case CardGeneratedCardPool.OtherColors:
				return IsAnyClassPool(classPool) && !ReferenceEquals(classPool, owner.Character.CardPool);
			default:
				return ReferenceEquals(classPool, owner.Character.CardPool);
		}
	}

	private static bool IsCardInSpecificPool(CardModel card, CardPoolModel pool)
	{
		if (card == null || pool == null)
		{
			return false;
		}

		return ReferenceEquals(card.Pool, pool)
			|| ReferenceEquals(card.VisualCardPool, pool)
			|| string.Equals(card.Pool?.Title, pool.Title, StringComparison.OrdinalIgnoreCase)
			|| string.Equals(card.VisualCardPool?.Title, pool.Title, StringComparison.OrdinalIgnoreCase);
	}

	private static CardPoolModel GetClassFilterPool(CardModel card)
	{
		if (card == null)
		{
			return null;
		}

		CardPoolModel visualPool = card.VisualCardPool;
		if (IsAnyClassPool(visualPool))
		{
			return visualPool;
		}

		return card.Pool;
	}

	private static bool IsAnyClassPool(CardPoolModel pool)
	{
		return pool != null
			&& (ReferenceEquals(pool, ModelDb.CardPool<IroncladCardPool>())
				|| ReferenceEquals(pool, ModelDb.CardPool<SilentCardPool>())
				|| ReferenceEquals(pool, ModelDb.CardPool<DefectCardPool>())
				|| ReferenceEquals(pool, ModelDb.CardPool<RegentCardPool>())
				|| ReferenceEquals(pool, ModelDb.CardPool<NecrobinderCardPool>()));
	}

	private static CardModel CreateDeckCopyFromSource(Player owner, CardModel source, bool exact)
	{
		if (owner == null || source == null)
		{
			throw new ArgumentNullException();
		}

		if (exact)
		{
			return owner.RunState.CloneCard(source);
		}

		CardModel canonical = source.CanonicalInstance ?? ModelDb.GetById<CardModel>(source.Id);
		CardModel copy = owner.RunState.CreateCard(canonical, owner);
		int upgradeLevels = Math.Clamp(source.GetSafeCurrentUpgradeLevel(), 0, copy.MaxUpgradeLevel);
		for (int i = 0; i < upgradeLevels && copy.IsUpgradable; i++)
		{
			copy.UpgradeInternal();
			copy.FinalizeUpgradeInternal();
		}
		return copy;
	}

	private static CardModel CreateCombatCopyFromSource(CombatState combatState, Player owner, CardModel source, bool exact)
	{
		if (combatState == null || owner == null || source == null)
		{
			throw new ArgumentNullException();
		}

		if (exact)
		{
			return source.CreateClone();
		}

		CardModel canonical = source.CanonicalInstance ?? ModelDb.GetById<CardModel>(source.Id);
		CardModel copy = combatState.CreateCard(canonical, owner);
		int upgradeLevels = Math.Clamp(source.GetSafeCurrentUpgradeLevel(), 0, copy.MaxUpgradeLevel);
		for (int i = 0; i < upgradeLevels && copy.IsUpgradable; i++)
		{
			copy.UpgradeInternal();
			copy.FinalizeUpgradeInternal();
		}
		return copy;
	}

	private static async Task<CardModel?> AddDeckCardCopy(Player owner, CardModel source, bool exact, List<(CardPileAddResult Result, PileType PileType)> results)
	{
		if (owner == null || source == null || results == null)
		{
			return null;
		}

		CardModel deckCard = CreateDeckCopyFromSource(owner, source, exact);
		results.Add((await CardPileCmd.Add(deckCard, PileType.Deck), PileType.Deck));
		return deckCard;
	}

	private sealed class EmptyGeneratedSourceScope : IDisposable
	{
		public static readonly EmptyGeneratedSourceScope Instance = new EmptyGeneratedSourceScope();

		public void Dispose()
		{
		}
	}

	private static IDisposable PushGeneratedCardSourceScope(CardModel? sourceCard)
		=> sourceCard != null ? CardEditorEffectSourceContext.PushScoped(sourceCard) : EmptyGeneratedSourceScope.Instance;

	private static async Task AutoPlayCardUsingVanillaSelections(PlayerChoiceContext choiceContext, CardModel card, Player? owner)
	{
		if (choiceContext == null || card == null || CombatManager.Instance.IsOverOrEnding)
		{
			return;
		}

		await CardCmd.AutoPlay(choiceContext, card, target: null);
	}

	private static async Task<bool> AutoPlayGeneratedCard(PlayerChoiceContext choiceContext, CombatState combatState, CardModel card, Player owner)
	{
		if (choiceContext == null || combatState == null || card == null || owner == null)
		{
			return false;
		}

		if (CombatManager.Instance.IsOverOrEnding || card.Owner.Creature.IsDead)
		{
			return false;
		}

		PlayerCombatState? playerCombatState = card.Owner.PlayerCombatState;
		if (playerCombatState == null)
		{
			if (card.Pile == null)
			{
				await AddGeneratedCardToPlayForAutoPlay(combatState, card, owner);
			}
			await card.MoveToResultPileWithoutPlaying(choiceContext);
			return true;
		}

		if (card.Pile == null)
		{
			await AddGeneratedCardToPlayForAutoPlay(combatState, card, owner);
		}

		await AutoPlayCardUsingVanillaSelections(choiceContext, card, owner);
		return true;
	}

	private static async Task AddGeneratedCardToPlayForAutoPlay(CombatState combatState, CardModel card, Player owner)
	{
		if (combatState == null || card == null || owner == null || card.Pile != null)
		{
			return;
		}

		CombatManager.Instance.History.CardGenerated(combatState, card, owner);
		await CardPileCmd.Add(card, PileType.Play);
		await Hook.AfterCardGeneratedForCombat(combatState, card, owner);
	}

	private static async Task<CardPileAddResult?> TryAddGeneratedCardToCombat(CombatState? combatState, CardModel card, PileType toPileType, Player owner, CardPilePosition position)
	{
		if (combatState == null || card == null || owner == null || !toPileType.IsCombatPile())
		{
			return null;
		}

		if (CombatManager.Instance.IsOverOrEnding || owner.Creature.GetConcreteCombatState() == null)
		{
			CardEditorMod.VerboseLog($"[CardEditor] Skipped generated card add for {card.Id.Entry}; combat is not active.");
			return null;
		}

		IReadOnlyList<CardPileAddResult> results = await CardPileCmd.AddGeneratedCardsToCombat(new[] { card }, toPileType, owner, position);
		if (results.Count == 0)
		{
			CardEditorMod.VerboseLog($"[CardEditor] Skipped generated card add for {card.Id.Entry}; no pile add result was produced.");
			return null;
		}

		return results[0];
	}

	private static async Task AddCardCopyToConfiguredDestinations(CombatState combatState, Player owner, CardModel source, bool exact, IReadOnlyList<(PileType PileType, CardPilePosition Position)> destinations, List<(CardPileAddResult Result, PileType PileType)> results, CardModel? sourceCard, List<CardModel>? generatedCards = null)
	{
		if (combatState == null || owner == null || source == null || destinations == null || results == null)
		{
			return;
		}

		using IDisposable _ = PushGeneratedCardSourceScope(sourceCard);
		foreach ((PileType toPileType, CardPilePosition position) in destinations)
		{
			if (toPileType == PileType.Deck)
			{
				CardModel? deckCard = await AddDeckCardCopy(owner, source, exact, results);
				if (deckCard != null)
				{
					generatedCards?.Add(deckCard);
				}
			}
			else if (toPileType.IsCombatPile())
			{
				CardModel copy = CreateCombatCopyFromSource(combatState, owner, source, exact);
				CardPileAddResult? addResult = await TryAddGeneratedCardToCombat(combatState, copy, toPileType, owner, position);
				if (addResult.HasValue)
				{
					results.Add((addResult.Value, toPileType));
					generatedCards?.Add(copy);
				}
			}
		}
	}

	private static async Task AddCanonicalCardToConfiguredDestinations(CombatState combatState, Player owner, CardModel canonical, IReadOnlyList<(PileType PileType, CardPilePosition Position)> destinations, List<(CardPileAddResult Result, PileType PileType)> results, CardModel? sourceCard, CardExtraEffect? effect, List<CardModel>? generatedCards = null)
	{
		if (combatState == null || owner == null || canonical == null || destinations == null || results == null)
		{
			return;
		}

		using IDisposable _ = PushGeneratedCardSourceScope(sourceCard);
		foreach ((PileType toPileType, CardPilePosition position) in destinations)
		{
			if (toPileType == PileType.Deck)
			{
				CardModel generated = owner.RunState.CreateCard(canonical, owner);
				ApplySpecificCardUpgradeMode(generated, canonical, effect);
				results.Add((await CardPileCmd.Add(generated, PileType.Deck), PileType.Deck));
				generatedCards?.Add(generated);
			}
			else if (toPileType.IsCombatPile())
			{
				CardModel generated = combatState.CreateCard(canonical, owner);
				ApplySpecificCardUpgradeMode(generated, canonical, effect);
				CardPileAddResult? addResult = await TryAddGeneratedCardToCombat(combatState, generated, toPileType, owner, position);
				if (addResult.HasValue)
				{
					results.Add((addResult.Value, toPileType));
					generatedCards?.Add(generated);
				}
			}
		}
	}

	private static async Task<int> AddGeneratedChoiceToConfiguredDestinations(Player owner, CardModel selected, IReadOnlyList<(PileType PileType, CardPilePosition Position)> destinations, CardModel? sourceCard, List<CardModel>? generatedCards = null)
	{
		if (owner == null || selected == null || destinations == null || destinations.Count == 0)
		{
			return 0;
		}

		List<(CardPileAddResult Result, PileType PileType)> results = new();
		bool usedSelectedCombatCard = false;
		using IDisposable _ = PushGeneratedCardSourceScope(sourceCard);
		foreach ((PileType toPileType, CardPilePosition position) in destinations)
		{
			if (toPileType == PileType.Deck)
			{
				CardModel? deckCard = await AddDeckCardCopy(owner, selected, exact: false, results);
				if (deckCard != null)
				{
					generatedCards?.Add(deckCard);
				}
			}
			else if (toPileType.IsCombatPile())
			{
				CardModel cardToAdd = !usedSelectedCombatCard ? selected : selected.CreateClone();
				usedSelectedCombatCard = true;
				CardPileAddResult? addResult = await TryAddGeneratedCardToCombat(owner.Creature.GetConcreteCombatState(), cardToAdd, toPileType, owner, position);
				if (addResult.HasValue)
				{
					results.Add((addResult.Value, toPileType));
					generatedCards?.Add(cardToAdd);
				}
			}
		}
		PreviewGeneratedPileAdds(results);
		return results.Count;
	}

	private static async Task RecoverCanceledGeneratedChoice(PlayerChoiceContext choiceContext, CardExtraEffect? effect)
	{
		string effectLabel = effect?.EffectId ?? effect?.Kind.ToString() ?? "unknown";
		Log.Warn($"[CardEditor] Generated card choice canceled for {effectLabel}; treating as skipped.");
		if (choiceContext == null)
		{
			return;
		}

		try
		{
			await choiceContext.SignalPlayerChoiceEnded().WaitAsync(TimeSpan.FromSeconds(3));
		}
		catch (TimeoutException)
		{
			Log.Warn($"[CardEditor] Timed out while ending canceled generated card choice for {effectLabel}.");
		}
		catch (Exception ex)
		{
			Log.Warn($"[CardEditor] Failed to end canceled generated card choice for {effectLabel}: {ex}");
		}
	}

	private static IReadOnlyList<Player> ResolveGeneratedCardOwners(CombatState combatState, Player owner, CardPlay? cardPlay, CardExtraEffect? effect)
	{
		if (combatState == null || owner == null)
		{
			return Array.Empty<Player>();
		}

		if (effect?.GeneratedCardOwnerMode != CardExtraEffectGeneratedCardOwnerMode.EffectTarget)
		{
			return new[] { owner };
		}

		Creature? ownerCreature = CardEditorPowerExecutionHostContext.Current
			?? cardPlay?.Card?.Owner?.Creature
			?? owner.Creature;
		IReadOnlyList<Player> targetPlayers = ResolveTargetPlayers(combatState, owner, ownerCreature, cardPlay, effect);
		return targetPlayers.Count > 0
			? targetPlayers
			: new[] { owner };
	}

	private static MegaCrit.Sts2.Core.Random.Rng? ResolveGeneratedCardRng(Player sourceOwner, Player generatedOwner)
		=> sourceOwner?.RunState?.Rng?.CombatCardGeneration ?? generatedOwner?.RunState?.Rng?.CombatCardGeneration;

	private static async Task AddRandomCardsToHand(CombatState combatState, Player owner, CardPlay? cardPlay, int amount, CardGeneratedCardPool pool, CardGeneratedCardType type, CardExtraEffect effect, CardModel? sourceCard)
	{
		if (combatState == null || owner == null || amount <= 0)
		{
			return;
		}

		List<(PileType PileType, CardPilePosition Position)> destinations = ResolveGeneratedCombatDestinations(effect, effect?.MoveToPile ?? CardExtraEffectCardPile.Hand, effect?.MoveToPosition ?? CardExtraEffectCardPilePosition.Bottom);
		List<(CardPileAddResult Result, PileType PileType)> results = new();
		List<CardModel> generatedCards = new();
		foreach (Player generatedOwner in ResolveGeneratedCardOwners(combatState, owner, cardPlay, effect))
		{
			if (generatedOwner == null)
			{
				continue;
			}

			List<CardModel> candidates = GetCardGenerationCandidates(generatedOwner, pool, type, effect.GeneratedCardCustomTag, effect);
			if (candidates.Count == 0)
			{
				continue;
			}

			MegaCrit.Sts2.Core.Random.Rng? rng = ResolveGeneratedCardRng(owner, generatedOwner);
			for (int i = 0; i < amount; i++)
			{
				CardModel? canonical = rng != null
					? rng.NextItem(candidates)
					: candidates.FirstOrDefault();
				if (canonical == null)
				{
					continue;
				}

				await AddCanonicalCardToConfiguredDestinations(combatState, generatedOwner, canonical, destinations, results, sourceCard, effect, generatedCards);
			}
		}
		PreviewGeneratedPileAdds(results);
		CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(results.Count);
		CardEditorEffectExecutionAmountContext.ReplaceCurrentSelectedCards(generatedCards);
	}

	private static async Task ChooseOneOfThreeCardsToHand(CombatState combatState, PlayerChoiceContext choiceContext, Player owner, CardPlay? cardPlay, int times, CardGeneratedCardPool pool, CardGeneratedCardType type, CardExtraEffect effect, CardModel? sourceCard)
	{
		if (combatState == null || choiceContext == null || owner == null)
		{
			return;
		}
		times = Math.Max(1, times);

		List<(PileType PileType, CardPilePosition Position)> destinations = ResolveGeneratedCombatDestinations(effect, effect?.MoveToPile ?? CardExtraEffectCardPile.Hand, effect?.MoveToPosition ?? CardExtraEffectCardPilePosition.Bottom);
		int added = 0;
		List<CardModel> generatedCards = new();
		foreach (Player generatedOwner in ResolveGeneratedCardOwners(combatState, owner, cardPlay, effect))
		{
			if (generatedOwner == null)
			{
				continue;
			}

			List<CardModel> candidates = GetCardGenerationCandidates(generatedOwner, pool, type, effect.GeneratedCardCustomTag, effect);
			if (candidates.Count == 0)
			{
				continue;
			}

			MegaCrit.Sts2.Core.Random.Rng? rng = ResolveGeneratedCardRng(owner, generatedOwner);
			for (int i = 0; i < times; i++)
			{
				List<CardModel> options = new List<CardModel>();
				HashSet<ModelId> used = new HashSet<ModelId>();
				int tries = 0;
				while (options.Count < 3 && used.Count < candidates.Count && tries < 50)
				{
					tries++;
					CardModel? canonical = rng != null
						? rng.NextItem(candidates)
						: candidates.FirstOrDefault(card => card != null && !used.Contains(card.Id));
					if (canonical == null || used.Contains(canonical.Id))
					{
						continue;
					}
					used.Add(canonical.Id);
					CardModel optionCard = combatState.CreateCard(canonical, generatedOwner);
					ApplySpecificCardUpgradeMode(optionCard, canonical, effect);
					options.Add(optionCard);
				}

				if (options.Count == 0)
				{
					continue;
				}

				CardModel? selected;
				try
				{
					selected = await CardSelectCmd.FromChooseACardScreen(choiceContext, options, generatedOwner, canSkip: true);
				}
				catch (OperationCanceledException)
				{
					await RecoverCanceledGeneratedChoice(choiceContext, effect);
					return;
				}

				if (selected != null)
				{
					added += await AddGeneratedChoiceToConfiguredDestinations(generatedOwner, selected, destinations, sourceCard, generatedCards);
				}
			}
		}
		CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(added);
		CardEditorEffectExecutionAmountContext.ReplaceCurrentSelectedCards(generatedCards);
	}

	internal static async Task CreatePotions(Player owner, CardExtraEffect effect, int amount)
	{
		if (owner == null || amount <= 0)
		{
			return;
		}

		if (effect?.PotionMode == CardExtraEffectPotionMode.Specific)
		{
			PotionModel? specific = ResolveSpecificPotionModel(effect.SpecificPotionId);
			if (specific == null)
			{
				Log.Warn($"[CardEditor] Failed to create specific potion: '{effect.SpecificPotionId}' was not found.");
				return;
			}

			for (int i = 0; i < amount; i++)
			{
				await PotionCmd.TryToProcure(specific.ToMutable(), owner);
			}

			return;
		}

		HashSet<ModelId> chosenIds = new();
		for (int i = 0; i < amount; i++)
		{
			List<PotionModel> candidates = GetPotionCandidates(owner, effect, chosenIds);
			if (candidates.Count == 0)
			{
				return;
			}

			PotionModel? potion = SelectRandomPotionCandidate(owner, candidates, effect);
			if (potion == null)
			{
				return;
			}

			if (effect?.PotionAllowDuplicates != true)
			{
				chosenIds.Add(potion.Id);
			}

			await PotionCmd.TryToProcure(potion.ToMutable(), owner);
		}
	}

	internal static void AddCombatCardReward(Player owner, CardExtraEffect effect, int optionCount)
	{
		if (owner == null || optionCount <= 0)
		{
			return;
		}

		if (owner.RunState?.CurrentRoom is not CombatRoom combatRoom)
		{
			return;
		}

		int count = Math.Clamp(optionCount, 1, 99);
		CardCreationOptions options = BuildCardRewardCreationOptions(owner, combatRoom.RoomType, effect);
		CardReward reward = new CardReward(options, count, owner);
		CardEditorCardRewardSpecs.Attach(reward, CardEditorCardRewardSpecs.FromEffect(effect));
		combatRoom.AddExtraReward(owner, reward);
	}

	internal static void AddCombatRelicReward(Player owner, int amount)
	{
		if (owner == null || amount <= 0)
		{
			return;
		}

		if (owner.RunState?.CurrentRoom is not CombatRoom combatRoom)
		{
			return;
		}

		for (int i = 0; i < Math.Clamp(amount, 1, 99); i++)
		{
			combatRoom.AddExtraReward(owner, new RelicReward(owner));
		}
	}

	internal static CardCreationOptions BuildCardRewardCreationOptions(Player owner, RoomType roomType, CardExtraEffect effect)
	{
		CardCreationOptions defaults = CardCreationOptions.ForRoom(owner, roomType);
		IEnumerable<CardPoolModel> pools = ResolveCardRewardPools(owner, effect?.GeneratedCardPool ?? CardGeneratedCardPool.Default);
		CardCreationSource source = ResolveCardRewardSource(defaults.Source, effect?.CardRewardSource ?? CardExtraEffectCardRewardSource.RoomDefault);
		CardRarityOddsType odds = ResolveCardRewardRarityOdds(defaults.RarityOdds, effect?.CardRewardRarityOdds ?? CardExtraEffectCardRewardRarityOdds.RoomDefault);
		return new CardCreationOptions(pools, source, odds);
	}

	private static IEnumerable<CardPoolModel> ResolveCardRewardPools(Player owner, CardGeneratedCardPool pool)
	{
		return pool switch
		{
			CardGeneratedCardPool.Colorless => new[] { ModelDb.CardPool<ColorlessCardPool>() },
			CardGeneratedCardPool.Ironclad => new[] { ModelDb.CardPool<IroncladCardPool>() },
			CardGeneratedCardPool.Silent => new[] { ModelDb.CardPool<SilentCardPool>() },
			CardGeneratedCardPool.Defect => new[] { ModelDb.CardPool<DefectCardPool>() },
			CardGeneratedCardPool.Regent => new[] { ModelDb.CardPool<RegentCardPool>() },
			CardGeneratedCardPool.Necrobinder => new[] { ModelDb.CardPool<NecrobinderCardPool>() },
			CardGeneratedCardPool.Status => new[] { ModelDb.CardPool<StatusCardPool>() },
			CardGeneratedCardPool.Curse => new[] { ModelDb.CardPool<CurseCardPool>() },
			CardGeneratedCardPool.Quest => new[] { ModelDb.CardPool<QuestCardPool>() },
			CardGeneratedCardPool.Token => new[] { ModelDb.CardPool<TokenCardPool>() },
			CardGeneratedCardPool.Event => new[] { ModelDb.CardPool<EventCardPool>() },
			CardGeneratedCardPool.OtherColors => ModelDb.AllCharacterCardPools.Where(poolModel => !ReferenceEquals(poolModel, owner.Character.CardPool)).ToArray(),
			CardGeneratedCardPool.Any => ModelDb.AllCharacterCardPools.ToArray(),
			CardGeneratedCardPool.Ancient => ModelDb.AllCardPools.ToArray(),
			CardGeneratedCardPool.AllPools => GetAllSupportedCardPools().ToArray(),
			CardGeneratedCardPool.All => ModelDb.AllCardPools.ToArray(),
			_ => new[] { owner.Character.CardPool }
		};
	}

	private static CardCreationSource ResolveCardRewardSource(CardCreationSource roomDefault, CardExtraEffectCardRewardSource source)
	{
		return source switch
		{
			CardExtraEffectCardRewardSource.Encounter => CardCreationSource.Encounter,
			CardExtraEffectCardRewardSource.Shop => CardCreationSource.Shop,
			CardExtraEffectCardRewardSource.Other => CardCreationSource.Other,
			_ => roomDefault
		};
	}

	private static CardRarityOddsType ResolveCardRewardRarityOdds(CardRarityOddsType roomDefault, CardExtraEffectCardRewardRarityOdds odds)
	{
		return odds switch
		{
			CardExtraEffectCardRewardRarityOdds.RegularEncounter => CardRarityOddsType.RegularEncounter,
			CardExtraEffectCardRewardRarityOdds.EliteEncounter => CardRarityOddsType.EliteEncounter,
			CardExtraEffectCardRewardRarityOdds.BossEncounter => CardRarityOddsType.BossEncounter,
			CardExtraEffectCardRewardRarityOdds.Shop => CardRarityOddsType.Shop,
			CardExtraEffectCardRewardRarityOdds.Uniform => CardRarityOddsType.Uniform,
			_ => roomDefault
		};
	}

	// Quest rewards completing OUT of combat must honor the same rarity/pool filters as the
	// in-combat path; a bare PotionReward would roll any rarity from the default pools.
	internal static PotionModel? CreateFilteredPotionForReward(Player owner, CardExtraEffect? effect, HashSet<ModelId> chosenIds)
	{
		List<PotionModel> candidates = GetPotionCandidates(owner, effect, chosenIds);
		if (candidates.Count == 0)
		{
			return null;
		}

		PotionModel? potion = SelectRandomPotionCandidate(owner, candidates, effect);
		if (potion != null && effect?.PotionAllowDuplicates != true)
		{
			chosenIds.Add(potion.Id);
		}

		return potion;
	}

	private static List<PotionModel> GetPotionCandidates(Player owner, CardExtraEffect? effect, HashSet<ModelId> chosenIds)
	{
		if (owner == null)
		{
			return new List<PotionModel>();
		}

		IEnumerable<PotionModel> source = (effect?.PotionPoolFilter ?? CardExtraEffectPotionPoolFilter.Vanilla) switch
		{
			CardExtraEffectPotionPoolFilter.Character => owner.Character.PotionPool.GetUnlockedPotions(owner.UnlockState),
			CardExtraEffectPotionPoolFilter.Shared => ModelDb.PotionPool<SharedPotionPool>().GetUnlockedPotions(owner.UnlockState),
			CardExtraEffectPotionPoolFilter.Event => ModelDb.PotionPool<EventPotionPool>().GetUnlockedPotions(owner.UnlockState),
			CardExtraEffectPotionPoolFilter.Token => ModelDb.PotionPool<TokenPotionPool>().GetUnlockedPotions(owner.UnlockState),
			CardExtraEffectPotionPoolFilter.All => ModelDb.AllPotions,
			_ => PotionFactory.GetPotionOptions(owner)
		};

		bool inCombatOnly = effect?.PotionInCombatOnly != false;
		CardExtraEffectPotionRarityFilter rarityFilter = effect?.PotionRarityFilter ?? CardExtraEffectPotionRarityFilter.Any;
		PotionRarity? exactRarity = ToPotionRarity(rarityFilter);
		IEnumerable<PotionModel> filtered = source;
		if (inCombatOnly)
		{
			filtered = filtered.Where(p => p.CanBeGeneratedInCombat);
		}

		if (exactRarity.HasValue)
		{
			filtered = filtered.Where(p => p.Rarity == exactRarity.Value);
		}
		else
		{
			filtered = filtered.Where(p => p.Rarity != PotionRarity.None);
		}

		if (effect?.PotionAllowDuplicates != true && chosenIds.Count > 0)
		{
			filtered = filtered.Where(p => !chosenIds.Contains(p.Id));
		}

		return filtered
			.GroupBy(p => p.Id)
			.Select(g => g.First())
			.ToList();
	}

	private static PotionModel? SelectRandomPotionCandidate(Player owner, List<PotionModel> candidates, CardExtraEffect? effect)
	{
		if (owner == null || candidates == null || candidates.Count == 0)
		{
			return null;
		}

		CardExtraEffectPotionRarityFilter rarityFilter = effect?.PotionRarityFilter ?? CardExtraEffectPotionRarityFilter.Any;
		PotionRarity? exactRarity = ToPotionRarity(rarityFilter);
		if (exactRarity.HasValue)
		{
			return owner.RunState.Rng.CombatPotionGeneration.NextItem(candidates);
		}

		float roll = owner.RunState.Rng.CombatPotionGeneration.NextFloat();
		PotionRarity vanillaRarity = roll <= 0.1f
			? PotionRarity.Rare
			: roll <= 0.35f
				? PotionRarity.Uncommon
				: PotionRarity.Common;
		List<PotionModel> rarityCandidates = candidates.Where(p => p.Rarity == vanillaRarity).ToList();
		if (rarityCandidates.Count > 0)
		{
			return owner.RunState.Rng.CombatPotionGeneration.NextItem(rarityCandidates);
		}

		return owner.RunState.Rng.CombatPotionGeneration.NextItem(candidates);
	}

	private static PotionRarity? ToPotionRarity(CardExtraEffectPotionRarityFilter rarity)
	{
		return rarity switch
		{
			CardExtraEffectPotionRarityFilter.Common => PotionRarity.Common,
			CardExtraEffectPotionRarityFilter.Uncommon => PotionRarity.Uncommon,
			CardExtraEffectPotionRarityFilter.Rare => PotionRarity.Rare,
			CardExtraEffectPotionRarityFilter.Event => PotionRarity.Event,
			CardExtraEffectPotionRarityFilter.Token => PotionRarity.Token,
			CardExtraEffectPotionRarityFilter.None => PotionRarity.None,
			_ => null
		};
	}

	private static async Task PlayRandomGeneratedCards(CombatState combatState, PlayerChoiceContext choiceContext, Player owner, int amount, CardGeneratedCardPool pool, CardGeneratedCardType type, CardExtraEffect effect, CardModel? sourceCard)
	{
		if (combatState == null || choiceContext == null || owner == null || amount <= 0)
		{
			return;
		}

		List<CardModel> candidates = GetCardGenerationCandidates(owner, pool, type, effect.GeneratedCardCustomTag, effect);
		if (candidates.Count == 0)
		{
			return;
		}

		bool consumeActivation = !CardEditorAutoPlayLoopGuard.IsAutoPlayEffectPrecounted(combatState, owner, sourceCard, effect);
		if (!CardEditorAutoPlayLoopGuard.TryEnterAutoPlayEffect(combatState, owner, sourceCard, effect, out IDisposable autoScope, consumeActivation: consumeActivation))
		{
			return;
		}

		using (autoScope)
		{
			using IDisposable sourceScope = PushGeneratedCardSourceScope(sourceCard);
			int played = 0;
			List<CardModel> generatedCards = new();
			for (int i = 0; i < amount; i++)
			{
				CardModel? canonical = owner.RunState.Rng.CombatCardGeneration.NextItem(candidates);
				if (canonical == null)
				{
					continue;
				}

				if (!CardEditorAutoPlayLoopGuard.TryEnterAutoPlayedCard(combatState, owner, sourceCard, effect, canonical))
				{
					continue;
				}

				CardModel generated = combatState.CreateCard(canonical, owner);
				ApplySpecificCardUpgradeMode(generated, canonical, effect);
				if (!await AutoPlayGeneratedCard(choiceContext, combatState, generated, owner))
				{
					continue;
				}
				generatedCards.Add(generated);
				played++;
			}
			CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(played);
			CardEditorEffectExecutionAmountContext.ReplaceCurrentSelectedCards(generatedCards);
		}
	}

private static CardModel? ResolveChooseOneQueryRepresentativeCard(Player owner, CardExtraEffectChooseOneOption option)
{
	if (owner == null || option == null)
	{
		return null;
	}

	if (option.QueryMatchMode == CardExtraEffectCardMatchMode.CardId
		&& TryParseSpecificCardId(option.QueryMatchCardId ?? string.Empty, out ModelId exactId))
	{
		CardModel? exactCard = ModelDb.GetByIdOrNull<CardModel>(exactId);
		if (exactCard != null)
		{
			return exactCard;
		}
	}

	CardExtraEffect queryEffect = BuildChooseOneQueryEffect(option);
	if (option.QuerySource == CardExtraEffectChooseOneQuerySource.Compendium)
	{
		return GetCardGenerationCandidates(owner, option.QueryPool, option.QueryType, null, queryEffect).FirstOrDefault();
	}

	return GetCandidatesFromConfiguredPile(
		owner,
		queryEffect,
		sourceCard: null,
		includeDeck: true,
		requireDeckVersion: false,
		includeCostFilter: true).FirstOrDefault();
}

private static CardModel? BuildChooseOneQueryDisplayCard(Player owner, CardModel hostCard, CardExtraEffectChooseOneOption option)
{
	CardModel? representative = ResolveChooseOneQueryRepresentativeCard(owner, option) ?? hostCard;
	if (representative == null)
	{
		return null;
	}

	try
	{
		CombatState? hostCombatState = hostCard.GetConcreteCombatState();
		CardExtraEffect queryEffect = BuildChooseOneQueryEffect(option);
		if (hostCombatState != null)
		{
			CardModel display = hostCombatState.CreateCard(representative, owner);
			ApplySpecificCardUpgradeMode(display, representative, queryEffect);
			return display;
		}

		CardModel preview = representative.ToMutable();
		ApplySpecificCardUpgradeMode(preview, representative, queryEffect);
		return preview;
	}
	catch
	{
		return representative;
	}
}

private static async Task PlayMatchingGeneratedCards(CombatState? combatState, PlayerChoiceContext choiceContext, Player owner, CardModel? sourceCard, CardExtraEffect effect, int amount)
{
	if (combatState == null || choiceContext == null || owner == null || effect == null || amount <= 0)
	{
		return;
	}

	List<CardModel> candidates = GetCardGenerationCandidates(owner, effect.CardSelectionPool, effect.CardSelectionType, null, effect);
	if (candidates.Count == 0)
	{
		return;
	}

	int count = effect.CardSelectionMode == CardExtraEffectCardSelectionMode.All
		? candidates.Count
		: Math.Max(0, Math.Min(amount, candidates.Count));
	if (count <= 0)
	{
		return;
	}

	List<CardModel> selected = await SelectCardsFromCandidates(
		choiceContext,
		owner,
		candidates,
		count,
		effect.CardSelectionMode,
		PileType.None,
		new LocString("gameplay_ui", "CHOOSE_CARD_HEADER"),
		sourceCard: null,
		excludeSourceCardInHandSelector: true,
		preferHandDiscardSelector: false,
		owner.RunState?.Rng?.CombatCardSelection,
		ResolveCardSelectionOfferCount(effect, null, count));
	if (selected.Count == 0)
	{
		return;
	}

	bool consumeActivation = !CardEditorAutoPlayLoopGuard.IsAutoPlayEffectPrecounted(combatState, owner, sourceCard, effect);
	if (!CardEditorAutoPlayLoopGuard.TryEnterAutoPlayEffect(combatState, owner, sourceCard, effect, out IDisposable autoScope, consumeActivation: consumeActivation))
	{
		return;
	}

	using (autoScope)
	{
		using IDisposable sourceScope = PushGeneratedCardSourceScope(sourceCard);
		int played = 0;
		List<(CardPileAddResult Result, PileType PileType)> deckCopies = new();
		List<CardModel> generatedCards = new();
		bool addCopyToDeck = effect.ChooseOneExecutionMode == CardExtraEffectChooseOneExecutionMode.CreatePlayAndAddToDeck;
		foreach (CardModel canonical in selected)
		{
			if (canonical == null)
			{
				continue;
			}

			if (!CardEditorAutoPlayLoopGuard.TryEnterAutoPlayedCard(combatState, owner, sourceCard, effect, canonical))
			{
				continue;
			}

			CardModel generated = combatState.CreateCard(canonical, owner);
			ApplySpecificCardUpgradeMode(generated, canonical, effect);
			if (!await AutoPlayGeneratedCard(choiceContext, combatState, generated, owner))
			{
				continue;
			}
			generatedCards.Add(generated);
			if (addCopyToDeck)
			{
				CardModel? deckCard = await AddDeckCardCopy(owner, generated, exact: false, deckCopies);
				if (deckCard != null)
				{
					generatedCards.Add(deckCard);
				}
			}
			played++;
		}
		PreviewGeneratedPileAdds(deckCopies);
		CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(played);
		CardEditorEffectExecutionAmountContext.ReplaceCurrentSelectedCards(generatedCards);
	}
}

private static async Task ExecuteChooseOneQueryOption(PlayerChoiceContext choiceContext, Player owner, CardModel hostCard, CardExtraEffectChooseOneOption option, CardExtraEffect rootEffect)
{
	if (choiceContext == null || owner == null || option == null)
	{
		return;
	}

	CardExtraEffect queryEffect = BuildChooseOneQueryEffect(option);
	queryEffect.ChooseOneExecutionMode = rootEffect?.ChooseOneExecutionMode ?? CardExtraEffectChooseOneExecutionMode.BorrowEffectsOnly;
	int count = Math.Clamp(option.QueryCount <= 0 ? 1 : option.QueryCount, 1, 99);
	if (option.QuerySource == CardExtraEffectChooseOneQuerySource.Compendium)
	{
		await PlayMatchingGeneratedCards(hostCard.GetConcreteCombatState() ?? owner.Creature.GetConcreteCombatState(), choiceContext, owner, hostCard, queryEffect, count);
		return;
	}

	await PlayCardsFromPile(hostCard.GetConcreteCombatState() ?? owner.Creature.GetConcreteCombatState(), choiceContext, owner, count, queryEffect, sourceCard: hostCard);
}

private static async Task ExecuteChooseOneExactOption(PlayerChoiceContext choiceContext, Player owner, CardModel hostCard, CardPlay cardPlay, CardExtraEffect effect, CardExtraEffectChooseOneOption option, ModelId sourceId, string runtimeKey)
{
	if (choiceContext == null || owner == null || hostCard == null || cardPlay == null || effect == null || sourceId == ModelId.none)
	{
		return;
	}

	if (effect.ChooseOneExecutionMode == CardExtraEffectChooseOneExecutionMode.BorrowEffectsOnly)
	{
		await CardEditorCreatedCardEffectSourceSupport.RunSingleEffectSourceOnPlay(hostCard, choiceContext, cardPlay, sourceId, runtimeKey);
		return;
	}

	CombatState? combatState = hostCard.GetConcreteCombatState() ?? owner.Creature.GetConcreteCombatState();
	if (combatState == null)
	{
		return;
	}

	CardModel? canonical = ModelDb.GetByIdOrNull<CardModel>(sourceId);
	if (canonical == null)
	{
		return;
	}

	if (!CardEditorAutoPlayLoopGuard.TryEnterAutoPlayEffect(combatState, owner, hostCard, effect, out IDisposable autoScope))
	{
		return;
	}

	using (autoScope)
	{
		CardExtraEffect upgradeEffect = CloneEffect(effect);
		upgradeEffect.SpecificCardUpgradeMode = option?.UpgradeMode ?? CardExtraEffectSpecificCardUpgradeMode.MatchSource;
		CardModel generated = combatState.CreateCard(canonical, owner);
		ApplySpecificCardUpgradeMode(generated, canonical, upgradeEffect);
		using IDisposable sourceScope = PushGeneratedCardSourceScope(hostCard);
		if (!await AutoPlayGeneratedCard(choiceContext, combatState, generated, owner))
		{
			return;
		}
		List<CardModel> generatedCards = new() { generated };

		if (effect.ChooseOneExecutionMode == CardExtraEffectChooseOneExecutionMode.CreatePlayAndAddToDeck)
		{
			List<(CardPileAddResult Result, PileType PileType)> deckCopies = new();
			CardModel? deckCard = await AddDeckCardCopy(owner, generated, exact: false, deckCopies);
			if (deckCard != null)
			{
				generatedCards.Add(deckCard);
			}
			PreviewGeneratedPileAdds(deckCopies);
		}
		CardEditorEffectExecutionAmountContext.ReportCurrentAppliedCount(generatedCards.Count);
		CardEditorEffectExecutionAmountContext.ReplaceCurrentSelectedCards(generatedCards);
	}
}

private static async Task ExecuteChooseOneResolvedOption(PlayerChoiceContext choiceContext, Player owner, CardModel hostCard, CardPlay cardPlay, CardExtraEffect effect, CardExtraEffectChooseOneOption option, ModelId sourceId, string runtimeKey)
{
	if (sourceId != ModelId.none || TryGetChooseOneExactSourceId(option, out sourceId))
	{
		await ExecuteChooseOneExactOption(choiceContext, owner, hostCard, cardPlay, effect, option, sourceId, runtimeKey);
		return;
	}

	await ExecuteChooseOneQueryOption(choiceContext, owner, hostCard, option, effect);
}

private static async Task ChooseOneEffectSourceCard(PlayerChoiceContext choiceContext, Player owner, CardModel hostCard, CardPlay cardPlay, CardExtraEffect effect)
{
	List<CardExtraEffectChooseOneOption> options = GetChooseOneOptions(effect);
	if (options.Count == 0)
	{
		return;
	}

	List<CardModel> optionCards = new();
	List<CardExtraEffectChooseOneOption> resolvedOptions = new();
	List<ModelId> optionSourceIds = new();
	List<string> optionRuntimeKeys = new();
	for (int optionIndex = 0; optionIndex < options.Count; optionIndex++)
	{
		CardExtraEffectChooseOneOption option = options[optionIndex];
		ModelId sourceId = ModelId.none;
		string runtimeKey = string.Empty;
		CardModel? optionCard;
		if (TryGetChooseOneExactSourceId(option, out sourceId))
		{
			runtimeKey = GetChooseOneEffectSourceRuntimeInstanceKey(hostCard, effect, optionIndex, sourceId);
			optionCard = CardEditorCreatedCardEffectSourceSupport.BuildRuntimeEffectSourceCard(hostCard, sourceId, isUpgradePreview: false, runtimeKey);
			if (optionCard != null && ModelDb.GetByIdOrNull<CardModel>(sourceId) is CardModel canonical)
			{
				CardExtraEffect upgradeEffect = CloneEffect(effect);
				upgradeEffect.SpecificCardUpgradeMode = option.UpgradeMode;
				ApplySpecificCardUpgradeMode(optionCard, canonical, upgradeEffect);
			}
		}
		else
		{
			optionCard = BuildChooseOneQueryDisplayCard(owner, hostCard, option);
		}

		if (optionCard == null)
		{
			continue;
		}

		optionCards.Add(optionCard);
		resolvedOptions.Add(option);
		optionSourceIds.Add(sourceId);
		optionRuntimeKeys.Add(runtimeKey);
	}

		if (optionCards.Count == 0)
		{
			return;
		}

	if (optionCards.Count == 1)
	{
		if (effect.ChooseOneResolveMode == CardExtraEffectChooseOneResolveMode.PlayerChoice
			&& effect.ChooseOneChoiceRule == CardExtraEffectChooseOneChoiceRule.UpTo)
		{
			CardModel? selectedCard = await CardSelectCmd.FromChooseACardScreen(choiceContext, optionCards, owner, canSkip: true);
			if (selectedCard == null)
			{
				return;
			}
		}

		await ExecuteChooseOneResolvedOption(choiceContext, owner, hostCard, cardPlay, effect, resolvedOptions[0], optionSourceIds[0], optionRuntimeKeys[0]);
		return;
	}

	if (effect.ChooseOneResolveMode == CardExtraEffectChooseOneResolveMode.All)
	{
		for (int i = 0; i < resolvedOptions.Count; i++)
		{
			await ExecuteChooseOneResolvedOption(choiceContext, owner, hostCard, cardPlay, effect, resolvedOptions[i], optionSourceIds[i], optionRuntimeKeys[i]);
		}

		return;
	}

	int targetCount = ResolveChooseOneTargetCount(effect, optionCards.Count);
	if (targetCount <= 0)
	{
		return;
	}

	if (effect.ChooseOneResolveMode == CardExtraEffectChooseOneResolveMode.Random)
	{
		List<int> selectedIndices = PickRandomDistinctIndices(optionCards.Count, targetCount, owner.RunState?.Rng?.CombatCardSelection);
		selectedIndices.Sort();
		foreach (int selectedIndex in selectedIndices)
		{
			if (selectedIndex < 0 || selectedIndex >= resolvedOptions.Count)
			{
				continue;
			}

			await ExecuteChooseOneResolvedOption(choiceContext, owner, hostCard, cardPlay, effect, resolvedOptions[selectedIndex], optionSourceIds[selectedIndex], optionRuntimeKeys[selectedIndex]);
		}

		return;
	}

	bool canSkip = effect.ChooseOneChoiceRule == CardExtraEffectChooseOneChoiceRule.UpTo;
	List<int> remainingIndices = Enumerable.Range(0, optionCards.Count).ToList();
	for (int pick = 0; pick < targetCount && remainingIndices.Count > 0; pick++)
	{
		List<CardModel> presentedCards = remainingIndices.Select(index => optionCards[index]).ToList();
		CardModel? selectedCard = await CardSelectCmd.FromChooseACardScreen(choiceContext, presentedCards, owner, canSkip);
		if (selectedCard == null)
		{
			return;
		}

		int presentedIndex = presentedCards.IndexOf(selectedCard);
		if (presentedIndex < 0 || presentedIndex >= remainingIndices.Count)
		{
			return;
		}

		int selectedIndex = remainingIndices[presentedIndex];
		await ExecuteChooseOneResolvedOption(choiceContext, owner, hostCard, cardPlay, effect, resolvedOptions[selectedIndex], optionSourceIds[selectedIndex], optionRuntimeKeys[selectedIndex]);
		remainingIndices.RemoveAt(presentedIndex);
	}
}

private static List<int> PickRandomDistinctIndices(int availableCount, int count, MegaCrit.Sts2.Core.Random.Rng? rng)
{
	if (availableCount <= 0 || count <= 0)
	{
		return new List<int>();
	}

	int take = Math.Min(count, availableCount);
	List<int> pool = Enumerable.Range(0, availableCount).ToList();
	if (pool.Count <= take)
	{
		return pool;
	}

	for (int i = 0; i < take; i++)
	{
		int j = rng == null ? i : i + rng.NextInt(pool.Count - i);
		(pool[i], pool[j]) = (pool[j], pool[i]);
	}

	return pool.Take(take).ToList();
}

	private static string GetRunEffectSourceRuntimeInstanceKey(CardModel card, CardExtraEffect effect)
	{
		if (card == null || effect == null || string.IsNullOrWhiteSpace(effect.SpecificCardId) || !TryParseSpecificCardId(effect.SpecificCardId, out ModelId sourceId))
		{
			return CardEditorCreatedCardEffectSourceSupport.CreateRuntimeSourceInstanceKey(ModelId.none, 0, "runEffectSource");
		}

		int occurrence = 0;
		foreach (CardExtraEffect candidate in GetEffectsForDescription(card, isUpgradePreview: false))
		{
			if (candidate == null || candidate.Kind != CardExtraEffectKind.RunEffectSourceCard)
			{
				continue;
			}

			if (!string.Equals(candidate.SpecificCardId?.Trim(), effect.SpecificCardId?.Trim(), StringComparison.Ordinal))
			{
				continue;
			}

			if (ReferenceEquals(candidate, effect))
			{
				break;
			}

			occurrence++;
		}

		return CardEditorCreatedCardEffectSourceSupport.CreateRuntimeSourceInstanceKey(sourceId, occurrence, "runEffectSource");
	}

	private static string GetScalingStageRuntimeInstanceKey(CardModel card, CardExtraEffect effect)
	{
		if (card == null || effect == null || string.IsNullOrWhiteSpace(effect.SpecificCardId) || !TryParseSpecificCardId(effect.SpecificCardId, out ModelId sourceId))
		{
			return CardEditorCreatedCardEffectSourceSupport.CreateRuntimeSourceInstanceKey(ModelId.none, 0, "scalingStage");
		}

		int occurrence = 0;
		foreach (CardExtraEffect candidate in GetEffectsForDescription(card, isUpgradePreview: false))
		{
			if (candidate == null || candidate.Kind != CardExtraEffectKind.ScalingStage)
			{
				continue;
			}

			if (!string.Equals(candidate.SpecificCardId?.Trim(), effect.SpecificCardId?.Trim(), StringComparison.Ordinal))
			{
				continue;
			}

			if (ReferenceEquals(candidate, effect))
			{
				break;
			}

			occurrence++;
		}

		return CardEditorCreatedCardEffectSourceSupport.CreateRuntimeSourceInstanceKey(sourceId, occurrence, "scalingStage");
	}

	private static string GetEffectSourceRuntimeInstanceKey(CardModel card, CardExtraEffect effect)
	{
		return effect.Kind == CardExtraEffectKind.ScalingStage
			? GetScalingStageRuntimeInstanceKey(card, effect)
			: GetRunEffectSourceRuntimeInstanceKey(card, effect);
	}

	private static string GetChooseOneEffectSourceRuntimeInstanceKey(CardModel hostCard, CardExtraEffect effect, int optionIndex, ModelId sourceId)
	{
		int occurrence = 0;
		foreach (CardExtraEffect candidate in GetEffectsForDescription(hostCard, isUpgradePreview: false))
		{
			if (candidate == null || candidate.Kind != CardExtraEffectKind.ChooseOneEffectSource)
			{
				continue;
			}

			if (ReferenceEquals(candidate, effect))
			{
				break;
			}

			occurrence++;
		}

		return CardEditorCreatedCardEffectSourceSupport.CreateRuntimeSourceInstanceKey(sourceId, Math.Max(0, optionIndex), $"chooseOne:{occurrence}");
	}

	private static List<(PileType PileType, CardPilePosition Position)> ResolveGeneratedCombatDestinations(CardExtraEffect? effect, CardExtraEffectCardPile configuredPile, CardExtraEffectCardPilePosition configuredPosition)
	{
		return GetGeneratedCardDestinations(effect, configuredPile, configuredPosition)
			.Select(dest => (ResolvePileType(dest.Pile), ResolvePilePosition(dest.Position)))
			.ToList();
	}

	private static void PreviewGeneratedPileAdds(IReadOnlyList<(CardPileAddResult Result, PileType PileType)> results)
	{
		if (results == null || results.Count == 0)
		{
			return;
		}

		foreach (IGrouping<PileType, CardPileAddResult> group in results.GroupBy(r => r.PileType, r => r.Result))
		{
			if (group.Key == PileType.Hand)
			{
				continue;
			}

			List<CardPileAddResult> pileResults = group.ToList();
			CardPreviewStyle style = pileResults.Count > 5 ? CardPreviewStyle.MessyLayout : CardPreviewStyle.HorizontalLayout;
			CardCmd.PreviewCardPileAdd(pileResults, 1.2f, style);
		}
	}

	private static List<CardModel> GetCardGenerationCandidates(Player owner, CardGeneratedCardPool pool, CardGeneratedCardType type, string? customTag, CardExtraEffect? effect = null)
	{
		if (owner == null)
		{
			return new List<CardModel>();
		}

		IEnumerable<CardModel> baseCards = pool switch
		{
			CardGeneratedCardPool.Colorless => ModelDb.CardPool<ColorlessCardPool>().GetUnlockedCards(owner.UnlockState, owner.RunState.CardMultiplayerConstraint),
			CardGeneratedCardPool.Ironclad => ModelDb.CardPool<IroncladCardPool>().GetUnlockedCards(owner.UnlockState, owner.RunState.CardMultiplayerConstraint),
			CardGeneratedCardPool.Silent => ModelDb.CardPool<SilentCardPool>().GetUnlockedCards(owner.UnlockState, owner.RunState.CardMultiplayerConstraint),
			CardGeneratedCardPool.Defect => ModelDb.CardPool<DefectCardPool>().GetUnlockedCards(owner.UnlockState, owner.RunState.CardMultiplayerConstraint),
			CardGeneratedCardPool.Regent => ModelDb.CardPool<RegentCardPool>().GetUnlockedCards(owner.UnlockState, owner.RunState.CardMultiplayerConstraint),
			CardGeneratedCardPool.Necrobinder => ModelDb.CardPool<NecrobinderCardPool>().GetUnlockedCards(owner.UnlockState, owner.RunState.CardMultiplayerConstraint),
			CardGeneratedCardPool.OtherColors => GetOtherColorCards(owner),
			CardGeneratedCardPool.Any => GetAllClassCards(owner),
			CardGeneratedCardPool.All => GetAllCards(owner),
			CardGeneratedCardPool.AllPools => GetAllPoolCards(owner),
			CardGeneratedCardPool.Ancient => GetAllPoolCards(owner).Where(c => c.Rarity == CardRarity.Ancient),
			CardGeneratedCardPool.Status => ModelDb.CardPool<StatusCardPool>().GetUnlockedCards(owner.UnlockState, owner.RunState.CardMultiplayerConstraint),
			CardGeneratedCardPool.Curse => ModelDb.CardPool<CurseCardPool>().GetUnlockedCards(owner.UnlockState, owner.RunState.CardMultiplayerConstraint),
			CardGeneratedCardPool.Quest => ModelDb.CardPool<QuestCardPool>().GetUnlockedCards(owner.UnlockState, owner.RunState.CardMultiplayerConstraint),
			CardGeneratedCardPool.Token => ModelDb.CardPool<TokenCardPool>().GetUnlockedCards(owner.UnlockState, owner.RunState.CardMultiplayerConstraint),
			CardGeneratedCardPool.Event => ModelDb.CardPool<EventCardPool>().GetUnlockedCards(owner.UnlockState, owner.RunState.CardMultiplayerConstraint),
			_ => owner.Character.CardPool.GetUnlockedCards(owner.UnlockState, owner.RunState.CardMultiplayerConstraint)
		};

		IEnumerable<CardModel> filtered = baseCards.Where(c => c != null && c.CanBeGeneratedInCombat && c.CanBeGeneratedByModifiers);

		filtered = pool switch
		{
			CardGeneratedCardPool.Ancient => filtered.Where(c => c.Rarity == CardRarity.Ancient),
			CardGeneratedCardPool.All => filtered.Where(c => c.Rarity != CardRarity.Basic && c.Rarity != CardRarity.Event),
			CardGeneratedCardPool.AllPools => filtered.Where(c => c.Rarity != CardRarity.Basic),
			CardGeneratedCardPool.Event => filtered.Where(c => c.Rarity != CardRarity.Basic),
			_ => filtered.Where(c => c.Rarity != CardRarity.Basic && c.Rarity != CardRarity.Ancient && c.Rarity != CardRarity.Event)
		};

		if (type != CardGeneratedCardType.Any)
		{
			if (type == CardGeneratedCardType.Playable)
			{
				filtered = filtered.Where(c => c.Type is CardType.Attack or CardType.Skill or CardType.Power);
			}
			else if (type == CardGeneratedCardType.NonAttack)
			{
				filtered = filtered.Where(c => c.Type != CardType.Attack);
			}
			else if (type == CardGeneratedCardType.NonSkill)
			{
				filtered = filtered.Where(c => c.Type != CardType.Skill);
			}
			else if (type == CardGeneratedCardType.NonPower)
			{
				filtered = filtered.Where(c => c.Type != CardType.Power);
			}
			else
			{
				CardType desired = type switch
				{
					CardGeneratedCardType.Attack => CardType.Attack,
					CardGeneratedCardType.Skill => CardType.Skill,
					CardGeneratedCardType.Power => CardType.Power,
					CardGeneratedCardType.Status => CardType.Status,
					CardGeneratedCardType.Curse => CardType.Curse,
					CardGeneratedCardType.Quest => CardType.Quest,
					_ => CardType.Skill
				};
				filtered = filtered.Where(c => c.Type == desired);
			}
		}

		string requiredCustomTag = customTag?.Trim() ?? string.Empty;
		if (!string.IsNullOrWhiteSpace(requiredCustomTag))
		{
			filtered = filtered.Where(card =>
				CardEditorOverrides.TryGetEffectiveOverride(card.Id, out CardOverride overrideData)
				&& overrideData.CustomTags != null
				&& overrideData.CustomTags.Contains(requiredCustomTag));
		}

	if (effect != null && effect.CostFilterEnabled)
	{
		filtered = filtered.Where(card => PassesCostFilter(card, effect, type));
	}

	if (effect != null && effect.CardSelectionRarity != CardExtraEffectCardRarityFilter.Any)
	{
		filtered = filtered.Where(card => PassesRarityFilter(card, effect.CardSelectionRarity));
	}

	if (effect != null && effect.CardMatchMode != CardExtraEffectCardMatchMode.Any)
	{
		filtered = filtered.Where(card => PassesCardMatchFilter(card, effect));
	}

	if (effect != null && effect.NameFilterEnabled)
	{
		filtered = filtered.Where(card => PassesNameFilter(card, effect));
	}

	return filtered.Distinct().ToList();
}

	private static IEnumerable<CardModel> GetAllClassCards(Player owner)
	{
		CardMultiplayerConstraint constraint = owner.RunState.CardMultiplayerConstraint;
		var unlockState = owner.UnlockState;

		return ModelDb.CardPool<IroncladCardPool>().GetUnlockedCards(unlockState, constraint)
			.Concat(ModelDb.CardPool<SilentCardPool>().GetUnlockedCards(unlockState, constraint))
			.Concat(ModelDb.CardPool<DefectCardPool>().GetUnlockedCards(unlockState, constraint))
			.Concat(ModelDb.CardPool<RegentCardPool>().GetUnlockedCards(unlockState, constraint))
			.Concat(ModelDb.CardPool<NecrobinderCardPool>().GetUnlockedCards(unlockState, constraint))
			.Distinct();
	}

	private static IEnumerable<CardModel> GetAllCards(Player owner)
	{
		CardMultiplayerConstraint constraint = owner.RunState.CardMultiplayerConstraint;
		var unlockState = owner.UnlockState;

		return GetAllClassCards(owner)
			.Concat(ModelDb.CardPool<ColorlessCardPool>().GetUnlockedCards(unlockState, constraint))
			.Distinct();
	}

	private static IEnumerable<CardModel> GetAllPoolCards(Player owner)
	{
		CardMultiplayerConstraint constraint = owner.RunState.CardMultiplayerConstraint;
		var unlockState = owner.UnlockState;

		return GetAllSupportedCardPools()
			.SelectMany(pool => pool.GetUnlockedCards(unlockState, constraint))
			.Distinct();
	}

	private static IEnumerable<CardPoolModel> GetAllSupportedCardPools()
	{
		return ModelDb.AllCardPools.Where(pool => pool is not DeprecatedCardPool);
	}

	private static IEnumerable<CardModel> GetOtherColorCards(Player owner)
	{
		CardPoolModel myPool = owner.Character.CardPool;
		if (myPool == null)
		{
			return GetAllClassCards(owner);
		}

		return GetAllClassCards(owner).Where(c => c != null && !ReferenceEquals(c.Pool, myPool));
	}

	private static async Task ApplyPowerWithDuration<TPower, TTracker>(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffectTarget target, int amount, CardExtraEffect effect)
		where TPower : PowerModel
		where TTracker : PowerModel
	{
		await ApplyPower<TPower>(combatState, ownerCreature, cardPlay, target, amount, effect);
		await TrackBuiltInPowerPersistence<TPower>(combatState, ownerCreature, cardPlay, target, amount, effect);
		await TrackBuiltInPowerDuration<TPower, TTracker>(combatState, ownerCreature, cardPlay, target, amount, effect);
	}

	private static async Task TrackBuiltInPowerPersistence<TPower>(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffectTarget target, int amount, CardExtraEffect? effect)
		where TPower : PowerModel
	{
		if (effect == null || amount <= 0 || effect.PowerPersistenceMode == CardExtraEffectPowerPersistenceMode.Normal)
		{
			return;
		}

		ModelId powerId = ModelDb.GetId<TPower>();
		await TrackConfiguredPowerPersistence(combatState, ownerCreature, cardPlay, target, powerId.ToString(), amount, effect);
	}

	private static async Task TrackBuiltInPowerDuration<TPower, TTracker>(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffectTarget target, int amount, CardExtraEffect? effect)
		where TPower : PowerModel
		where TTracker : PowerModel
	{
		if (effect == null
			|| amount == 0
			|| effect.Duration == CardExtraEffectDuration.Permanent
			|| effect.PowerPersistenceMode != CardExtraEffectPowerPersistenceMode.Normal)
		{
			return;
		}

		if (effect.Duration == CardExtraEffectDuration.ThisTurn)
		{
			await ApplyPower<TTracker>(combatState, ownerCreature, cardPlay, target, amount);
			return;
		}

		ModelId powerId = ModelDb.GetId<TPower>();
		await TrackConfiguredPowerDuration(combatState, ownerCreature, cardPlay, target, powerId.ToString(), amount, effect, targetHadPowerBefore: false);
	}

	private static async Task TrackConfiguredPowerDuration(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffectTarget target, string? powerId, int amount, CardExtraEffect? effect, bool targetHadPowerBefore)
	{
		if (effect == null
			|| amount == 0
			|| effect.Duration == CardExtraEffectDuration.Permanent
			|| effect.PowerPersistenceMode != CardExtraEffectPowerPersistenceMode.Normal
			|| string.IsNullOrWhiteSpace(powerId))
		{
			return;
		}

		foreach (Creature applyTarget in ResolveTargets(combatState, ownerCreature, cardPlay, target))
		{
			await TrackConfiguredPowerDuration(combatState, applyTarget, powerId, amount, effect.Duration, targetHadPowerBefore);
		}
	}

	private static async Task TrackConfiguredPowerDuration(CombatState combatState, Creature? target, string? powerId, int amount, CardExtraEffectDuration duration, bool targetHadPowerBefore)
	{
		if (target == null
			|| amount == 0
			|| duration == CardExtraEffectDuration.Permanent
			|| string.IsNullOrWhiteSpace(powerId))
		{
			return;
		}

		CardEditorPowerDurationTrackerPower? tracker = await PowerCmd.Apply<CardEditorPowerDurationTrackerPower>(target, 1, target, null, silent: true);
		tracker?.Track(powerId, amount, targetHadPowerBefore, duration, combatState);
	}

	private static async Task TrackConfiguredPowerPersistence(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffectTarget target, string? powerId, int amount, CardExtraEffect? effect)
	{
		if (effect == null
			|| effect.PowerPersistenceMode == CardExtraEffectPowerPersistenceMode.Normal
			|| amount <= 0
			|| string.IsNullOrWhiteSpace(powerId))
		{
			return;
		}

		foreach (Creature applyTarget in ResolveTargets(combatState, ownerCreature, cardPlay, target))
		{
			await TrackConfiguredPowerPersistence(combatState, applyTarget, powerId, amount, effect);
		}
	}

	private static async Task TrackConfiguredPowerPersistence(CombatState combatState, Creature? target, string? powerId, int amount, CardExtraEffect? effect)
	{
		if (target == null
			|| effect == null
			|| effect.PowerPersistenceMode == CardExtraEffectPowerPersistenceMode.Normal
			|| amount <= 0
			|| string.IsNullOrWhiteSpace(powerId))
		{
			return;
		}

		if (effect.PowerPersistenceMode == CardExtraEffectPowerPersistenceMode.RestOfRun)
		{
			CardEditorRunPowerState.Add(target, powerId, amount, effect.Duration);
		}

		CardEditorPowerPersistenceTrackerPower? tracker = await PowerCmd.Apply<CardEditorPowerPersistenceTrackerPower>(target, 1, target, null, silent: true);
		tracker?.Track(powerId, amount, effect.Duration, combatState);
	}

	internal static async Task ApplyConfiguredPowerForCardEditor(Creature? target, string? powerId, int amount, Creature? applier, CardModel? cardSource, CardExtraEffect? effect = null)
	{
		if (target == null || amount == 0 || string.IsNullOrWhiteSpace(powerId))
		{
			return;
		}

		if (CardEditorCustomStatusRegistry.IsCustomStatusId(powerId))
		{
			await ApplyCustomStatusPower(target, powerId, amount, applier ?? target, cardSource, effect);
			return;
		}

		if (!TryResolveConfiguredPowerModel(powerId, out PowerModel? canonical) || canonical == null)
		{
			return;
		}

		await PowerCmd.Apply(canonical.ToMutable(), target, amount, applier ?? target, cardSource, silent: true);
	}

	private static async Task ApplyPower<TPower>(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffectTarget target, int amount, CardExtraEffect? effect = null) where TPower : PowerModel
	{
		IReadOnlyList<Creature> targets = ResolveTargets(combatState, ownerCreature, cardPlay, target).ToList();
		if (targets.Count == 0)
		{
			return;
		}

		if (effect?.DurationTickPolicy is CardExtraEffectDurationTickPolicy.SuppressNextTick or CardExtraEffectDurationTickPolicy.TickNormally)
		{
			foreach (Creature applyTarget in targets)
			{
				if (applyTarget == null)
				{
					continue;
				}
				bool targetAlreadyHadPower = TargetAlreadyHasPower<TPower>(applyTarget);
				TPower? power = await PowerCmd.Apply<TPower>(applyTarget, amount, ownerCreature, cardPlay.Card);
				ApplyDurationTickPolicy(power, effect, targetAlreadyHadPower);
			}
			return;
		}

		await PowerCmd.Apply<TPower>(targets, amount, ownerCreature, cardPlay.Card);
	}

	private static bool TargetAlreadyHasPower<TPower>(Creature? target) where TPower : PowerModel
	{
		if (target == null)
		{
			return false;
		}

		try
		{
			return target.GetPower<TPower>() != null;
		}
		catch
		{
			return target.Powers?.OfType<TPower>().Any() == true;
		}
	}

	private static bool TargetAlreadyHasPower(Creature? target, PowerModel? power)
	{
		return GetActivePowerById(target, power) != null;
	}

	private static PowerModel? GetActivePowerById(Creature? target, PowerModel? power)
	{
		if (target == null || power == null)
		{
			return null;
		}

		try
		{
			return target.GetPowerById(power.Id);
		}
		catch
		{
			return target.Powers?.FirstOrDefault(active => active != null && Equals(active.Id, power.Id));
		}
	}

	private static bool ShouldSuppressNextDurationTick(CardExtraEffect? effect, bool targetAlreadyHadPower)
	{
		return effect?.DurationTickPolicy == CardExtraEffectDurationTickPolicy.SuppressNextTick
			&& !targetAlreadyHadPower;
	}

	private static void ApplyDurationTickPolicy(PowerModel? power, CardExtraEffect? effect, bool targetAlreadyHadPower)
	{
		if (power == null || effect == null)
		{
			return;
		}

		try
		{
			switch (effect.DurationTickPolicy)
			{
				case CardExtraEffectDurationTickPolicy.SuppressNextTick:
					if (!targetAlreadyHadPower)
					{
						power.SkipNextDurationTick = true;
					}
					break;
				case CardExtraEffectDurationTickPolicy.TickNormally:
					power.SkipNextDurationTick = false;
					break;
			}
		}
		catch
		{
			// Some custom powers may not participate in duration ticking.
		}
	}

	private static IReadOnlyList<Player> ResolveTargetPlayers(
		CombatState? combatState,
		Player? owner,
		Creature? ownerCreature,
		CardPlay? cardPlay,
		CardExtraEffect? effect)
	{
		if (combatState == null || owner == null || ownerCreature == null || cardPlay == null || effect == null)
		{
			return Array.Empty<Player>();
		}

		List<Player> players = ResolveTargets(combatState, ownerCreature, cardPlay, effect.Target)
			.Where(creature => creature?.Player != null)
			.Select(creature => creature.Player!)
			.Distinct(ReferenceEqualityComparer<Player>.Instance)
			.ToList();

		if (players.Count == 0 && effect.Target == CardExtraEffectTarget.Self)
		{
			players.Add(owner);
		}

		return players;
	}

	private static IEnumerable<Creature> ResolveTargets(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, CardExtraEffectTarget target)
	{
		if (_eachTargetCurrent != null)
		{
			return new[] { _eachTargetCurrent };
		}

		target = GetEffectiveResolvedTarget(cardPlay, target);

		switch (target)
		{
			case CardExtraEffectTarget.Self:
				return new[] { ownerCreature };
			case CardExtraEffectTarget.AllAllies:
				return ResolveFriendlyGroupTargets(combatState, ownerCreature, includeSelf: true);
			case CardExtraEffectTarget.AnyPlayer:
			{
				Creature? picked = ResolveFriendlySingleTarget(combatState, ownerCreature, cardPlay, includeSelf: true);
				return picked != null ? new[] { picked } : Array.Empty<Creature>();
			}
			case CardExtraEffectTarget.AnyAlly:
			{
				Creature? picked = ResolveFriendlySingleTarget(combatState, ownerCreature, cardPlay, includeSelf: false);
				return picked != null ? new[] { picked } : Array.Empty<Creature>();
			}
			case CardExtraEffectTarget.AllEnemies:
				return combatState.GetOpponentsOf(ownerCreature).Where(c => c.IsAlive);
			case CardExtraEffectTarget.OtherEnemies:
				return ResolveOtherEnemyTargets(combatState, ownerCreature, cardPlay);
			case CardExtraEffectTarget.RandomEnemy:
			{
				Creature? picked = combatState.RunState.Rng.CombatTargets.NextItem(combatState.GetOpponentsOf(ownerCreature).Where(c => c.IsAlive));
				return picked != null ? new[] { picked } : Array.Empty<Creature>();
			}
			case CardExtraEffectTarget.EventTarget:
				return cardPlay?.Target != null ? new[] { cardPlay.Target } : Array.Empty<Creature>();
			default:
			{
				Creature? picked = ResolveSingleTarget(combatState, ownerCreature, cardPlay);
				return picked != null ? new[] { picked } : Array.Empty<Creature>();
			}
		}
	}

	private static IEnumerable<Creature> ResolveOtherEnemyTargets(CombatState combatState, Creature ownerCreature, CardPlay cardPlay)
	{
		Creature? excludedTarget = ResolveSingleTarget(combatState, ownerCreature, cardPlay);
		IEnumerable<Creature> source = excludedTarget != null
			? combatState.GetTeammatesOf(excludedTarget)
			: combatState.GetOpponentsOf(ownerCreature);
		return source.Where(creature => creature != null && creature.IsAlive && !ReferenceEquals(creature, excludedTarget));
	}

	private static IEnumerable<Creature> ResolveFriendlyGroupTargets(CombatState combatState, Creature ownerCreature, bool includeSelf)
	{
		IEnumerable<Creature> source = ownerCreature.IsPlayer
			? combatState.PlayerCreatures
			: combatState.GetTeammatesOf(ownerCreature);
		return source.Where(creature => creature != null && creature.IsAlive && (includeSelf || creature != ownerCreature));
	}

	private static Creature? ResolveFriendlySingleTarget(CombatState combatState, Creature ownerCreature, CardPlay cardPlay, bool includeSelf)
	{
		if (cardPlay.Target != null && cardPlay.Target.IsAlive && IsFriendlyTarget(ownerCreature, cardPlay.Target, includeSelf))
		{
			return cardPlay.Target;
		}

		if (TryGetManualTarget(cardPlay.Card, out Creature? manualTarget)
			&& manualTarget != null
			&& manualTarget.IsAlive
			&& IsFriendlyTarget(ownerCreature, manualTarget, includeSelf))
		{
			return manualTarget;
		}

		if (includeSelf && ownerCreature.IsAlive)
		{
			return ownerCreature;
		}

		return ResolveFriendlyGroupTargets(combatState, ownerCreature, includeSelf).FirstOrDefault();
	}

	private static bool IsFriendlyTarget(Creature ownerCreature, Creature candidate, bool includeSelf)
	{
		if (candidate == null || !candidate.IsAlive)
		{
			return false;
		}

		if (!includeSelf && candidate == ownerCreature)
		{
			return false;
		}

		if (ownerCreature.IsPlayer)
		{
			return candidate.IsPlayer;
		}

		return candidate == ownerCreature || candidate.PetOwner == ownerCreature.PetOwner || candidate.IsPlayer == ownerCreature.IsPlayer;
	}

	private static Creature? ResolveSingleTarget(CombatState combatState, Creature ownerCreature, CardPlay cardPlay)
	{
		if (cardPlay.Target != null && cardPlay.Target.IsAlive)
		{
			return cardPlay.Target;
		}
		if (cardPlay?.Target != null && CardEditorCreatorPresetStore.GetStopDeadTargetFollowups())
		{
			return null;
		}
		if (cardPlay?.Card?.TargetType == TargetType.Self)
		{
			return ownerCreature.IsAlive ? ownerCreature : null;
		}
		if (cardPlay?.Card?.TargetType == TargetType.Osty)
		{
			Creature? osty = ownerCreature.Player?.Osty;
			return osty != null && osty.IsAlive ? osty : null;
		}
		if (TryGetManualTarget(cardPlay.Card, out Creature? manualTarget) && manualTarget != null && manualTarget.IsAlive)
		{
			return manualTarget;
		}
		if (manualTarget != null && CardEditorCreatorPresetStore.GetStopDeadTargetFollowups())
		{
			return null;
		}
		if (cardPlay.IsFirstInSeries && RequiresManualEnemyTarget(cardPlay.Card))
		{
			Log.Warn($"[CardEditor] Missing manual target for {cardPlay.Card.Id.Entry}; falling back to random enemy.");
		}
		return combatState.RunState.Rng.CombatTargets.NextItem(combatState.GetOpponentsOf(ownerCreature).Where(c => c.IsAlive));
	}

	private static CardExtraEffectTarget GetEffectiveResolvedTarget(CardPlay cardPlay, CardExtraEffectTarget requestedTarget)
	{
		if (requestedTarget != CardExtraEffectTarget.Target || cardPlay?.Card == null)
		{
			return requestedTarget;
		}

		return cardPlay.Card.TargetType switch
		{
			TargetType.Self => CardExtraEffectTarget.Self,
			TargetType.RandomEnemy => CardExtraEffectTarget.RandomEnemy,
			TargetType.AllEnemies => CardExtraEffectTarget.AllEnemies,
			TargetType.AnyAlly => CardExtraEffectTarget.AnyAlly,
			TargetType.AllAllies => CardExtraEffectTarget.AllAllies,
			TargetType.AnyPlayer => CardExtraEffectTarget.AnyPlayer,
			_ => requestedTarget
		};
	}

	private static IReadOnlyList<CardExtraEffect> GetEffectiveExtraEffects(CardModel card, CardOverride? overrideData, bool considerUpgrade, int? upgradeApplicationCountOverride = null)
	{
		if (overrideData == null)
		{
			IReadOnlyList<CardExtraEffect> result = Array.Empty<CardExtraEffect>();
			CardEditorUpgradeDeltaDebugLog.LogEffectiveEffectsResult("ExtraEffects.GetEffective.noOverride", card, result);
			return result;
		}

		IReadOnlyList<CardExtraEffect>? baseEffects = (overrideData.ExtraEffects != null && overrideData.ExtraEffects.Count > 0)
			? overrideData.ExtraEffects
			: null;

		if (!considerUpgrade
			|| overrideData.Upgrade == null
			|| overrideData.Upgrade.ExtraEffects == null
			|| overrideData.Upgrade.ExtraEffects.Count == 0)
		{
			IReadOnlyList<CardExtraEffect> result = ApplyEffectLimitRows(NormalizeSignedEffectAmounts(baseEffects));
			CardEditorUpgradeDeltaDebugLog.LogEffectiveEffectsResult("ExtraEffects.GetEffective.baseOnly", card, result);
			return result;
		}

		IReadOnlyList<CardExtraEffect> upgradeEffects = overrideData.Upgrade.ExtraEffects;
		if (baseEffects == null)
		{
			IReadOnlyList<CardExtraEffect> result = ApplyEffectLimitRows(NormalizeSignedEffectAmounts(upgradeEffects));
			CardEditorUpgradeDeltaDebugLog.LogEffectiveEffectsResult("ExtraEffects.GetEffective.upgradeOnly", card, result);
			return result;
		}

		List<CardExtraEffect> fused = baseEffects.Select(CloneEffect).ToList();
		bool numericFieldsAreDeltas = overrideData.Upgrade.ExtraEffectNumericFieldsAreDeltas;
		UpgradeEffectAlignment alignment = AlignUpgradeEffectsToBaseSlots(baseEffects, upgradeEffects);
		int upgradeApplications = GetExtraEffectUpgradeApplicationCount(card, overrideData, upgradeApplicationCountOverride);
		CardEditorUpgradeDeltaDebugLog.LogEffectiveEffectsStart(
			"ExtraEffects.GetEffective.start",
			card,
			overrideData,
			considerUpgrade,
			upgradeApplications);

		for (int baseSlotIndex = 0; baseSlotIndex < alignment.BaseSlotEffects.Length; baseSlotIndex++)
		{
			CardExtraEffect? upgradeEffect = alignment.BaseSlotEffects[baseSlotIndex];
			if (upgradeEffect == null)
			{
				continue;
			}

			if (upgradeEffect.DisableOnUpgrade)
			{
				fused[baseSlotIndex] = null!;
				continue;
			}

			CardExtraEffect baseEffect = baseEffects[baseSlotIndex];
			if (!HasMeaningfulUpgradeBaseSlotDelta(baseEffect, upgradeEffect, numericFieldsAreDeltas))
			{
				continue;
			}

			CardExtraEffect mergedEffect = CloneEffect(baseEffect);
			CardExtraEffect? repeatedEndlessDeltaEffect = !numericFieldsAreDeltas && overrideData.EndlessUpgrades == true && upgradeApplications > 1
				? BuildRepeatedEndlessUpgradeDeltaEffect(baseEffect, upgradeEffect)
				: null;
			for (int applicationIndex = 0; applicationIndex < upgradeApplications; applicationIndex++)
			{
				bool applyAsDelta = numericFieldsAreDeltas || (applicationIndex > 0 && repeatedEndlessDeltaEffect != null);
				CardExtraEffect appliedUpgradeEffect = applyAsDelta && repeatedEndlessDeltaEffect != null
					? repeatedEndlessDeltaEffect
					: upgradeEffect;
				CardExtraEffect beforeMerge = mergedEffect;
				mergedEffect = MergeUpgradeBaseSlotEffect(mergedEffect, appliedUpgradeEffect, applyAsDelta);
				CardEditorUpgradeDeltaDebugLog.LogMergeSlot(
					"ExtraEffects.GetEffective.mergeBaseSlot",
					card,
					baseSlotIndex,
					applicationIndex,
					beforeMerge,
					appliedUpgradeEffect,
					mergedEffect,
					applyAsDelta);
			}

			fused[baseSlotIndex] = mergedEffect;
		}

		for (int i = 0; i < upgradeEffects.Count; i++)
		{
			CardExtraEffect? upgradeEffect = upgradeEffects[i];
			if (upgradeEffect == null || alignment.UpgradeIndexToBaseSlot[i] >= 0)
			{
				continue;
			}

			if (!ShouldTreatUnmatchedUpgradeEffectAsAbsolute(baseEffects.Count, i, alignment.LastMatchedUpgradeIndex))
			{
				continue;
			}

			if (!upgradeEffect.DisableOnUpgrade)
			{
				fused.Add(CloneEffect(upgradeEffect));
			}
		}

		IReadOnlyList<CardExtraEffect> finalEffects = ApplyEffectLimitRows(NormalizeSignedEffectAmounts(fused));
		CardEditorUpgradeDeltaDebugLog.LogEffectiveEffectsResult("ExtraEffects.GetEffective.final", card, finalEffects);
		return finalEffects;
	}

	private static int GetExtraEffectUpgradeApplicationCount(CardModel card, CardOverride overrideData, int? upgradeApplicationCountOverride = null)
	{
		if (overrideData?.EndlessUpgrades != true || card == null)
		{
			return 1;
		}

		return Math.Max(1, upgradeApplicationCountOverride ?? card.GetSafeCurrentUpgradeLevel());
	}

	private static CardExtraEffect BuildRepeatedEndlessUpgradeDeltaEffect(CardExtraEffect baseEffect, CardExtraEffect upgradeEffect)
	{
		CardExtraEffect delta = CloneEffect(upgradeEffect);
		if (baseEffect == null || upgradeEffect == null)
		{
			return delta;
		}

		delta.Amount = baseEffect.AmountIsX
			? upgradeEffect.Amount - baseEffect.AmountXPlus
			: upgradeEffect.Amount - baseEffect.Amount;
		delta.Turns = upgradeEffect.Turns - baseEffect.Turns;
		delta.RepeatCount = upgradeEffect.RepeatCount - baseEffect.RepeatCount;
		delta.TriggerEveryN = upgradeEffect.TriggerEveryN - baseEffect.TriggerEveryN;
		delta.TriggerMaxFires = upgradeEffect.TriggerMaxFires - baseEffect.TriggerMaxFires;
		delta.TriggerMaxTurns = upgradeEffect.TriggerMaxTurns - baseEffect.TriggerMaxTurns;
		delta.AutoPlayLoopLimit = upgradeEffect.AutoPlayLoopLimit - baseEffect.AutoPlayLoopLimit;
		delta.StatefulTransformDurationAmount = upgradeEffect.StatefulTransformDurationAmount - baseEffect.StatefulTransformDurationAmount;
		delta.CreatedCardsCostTurns = upgradeEffect.CreatedCardsCostTurns - baseEffect.CreatedCardsCostTurns;
		delta.CardCostsLessTurns = upgradeEffect.CardCostsLessTurns - baseEffect.CardCostsLessTurns;
		delta.MatchingCostUseLimit = upgradeEffect.MatchingCostUseLimit - baseEffect.MatchingCostUseLimit;
		delta.CountTurns = upgradeEffect.CountTurns - baseEffect.CountTurns;
		delta.CountConditionAmount = upgradeEffect.CountConditionAmount - baseEffect.CountConditionAmount;
		delta.HistoryScalingBaseAmount =
			ResolveHistoryScalingBaseAmount(upgradeEffect, upgradeEffect.Amount)
			- ResolveHistoryScalingBaseAmount(baseEffect, baseEffect.Amount);
		delta.HistoryScalingCountStep =
			ResolveHistoryScalingCountStep(upgradeEffect)
			- ResolveHistoryScalingCountStep(baseEffect);
		delta.RepeatScalingExtraTimes =
			ResolveRepeatScalingExtraTimes(upgradeEffect)
			- ResolveRepeatScalingExtraTimes(baseEffect);
		delta.CardGrantTurns = upgradeEffect.CardGrantTurns - baseEffect.CardGrantTurns;
		delta.CardSelectionCount = upgradeEffect.CardSelectionCount - baseEffect.CardSelectionCount;
		delta.CardSelectionOfferCount = upgradeEffect.CardSelectionOfferCount - baseEffect.CardSelectionOfferCount;
		delta.EnchantmentTurns = upgradeEffect.EnchantmentTurns - baseEffect.EnchantmentTurns;
		delta.ConditionalBonusAmount = upgradeEffect.ConditionalBonusAmount - baseEffect.ConditionalBonusAmount;
		return delta;
	}

	private static CardExtraEffect MergeUpgradeBaseSlotEffect(CardExtraEffect baseEffect, CardExtraEffect upgradeEffect, bool numericFieldsAreDeltas)
	{
		CardExtraEffect fused = CloneEffect(baseEffect);
		bool repeatModeChanged = baseEffect.RepeatIsX != upgradeEffect.RepeatIsX;

		if (baseEffect.AmountIsX)
		{
			fused.AmountXPlus = numericFieldsAreDeltas
				? baseEffect.AmountXPlus + upgradeEffect.Amount
				: upgradeEffect.Amount;
		}
		else
		{
			int mergedAmount = numericFieldsAreDeltas
				? (baseEffect.Kind == CardExtraEffectKind.CreatedCardsCostLess
					&& (baseEffect.Amount == -1 || upgradeEffect.Amount == -1)
						? -1
						: baseEffect.Amount + upgradeEffect.Amount)
				: upgradeEffect.Amount;
			fused.Amount = IsValidEffectAmount(baseEffect.Kind, mergedAmount) ? mergedAmount : 0;
		}

		fused.RepeatIsX = upgradeEffect.RepeatIsX;

		if (numericFieldsAreDeltas)
		{
			fused.Turns = AddUpgradeDelta(baseEffect.Turns, upgradeEffect.Turns, 0, 99);
			if (fused.RepeatIsX)
			{
				fused.RepeatCount = repeatModeChanged
					? Math.Clamp(upgradeEffect.RepeatCount, 0, 99)
					: Math.Clamp(baseEffect.RepeatCount + upgradeEffect.RepeatCount, 0, 99);
			}
			else
			{
				fused.RepeatCount = repeatModeChanged
					? Math.Clamp(upgradeEffect.RepeatCount <= 0 ? 1 : upgradeEffect.RepeatCount, 1, 99)
					: AddUpgradeDelta(baseEffect.RepeatCount, upgradeEffect.RepeatCount, 1, 99);
			}
			fused.TriggerEveryN = AddUpgradeDelta(baseEffect.TriggerEveryN, upgradeEffect.TriggerEveryN, 1, 999);
			fused.TriggerMaxFires = AddUpgradeDelta(baseEffect.TriggerMaxFires, upgradeEffect.TriggerMaxFires, 0, 999);
			fused.TriggerMaxTurns = AddUpgradeDelta(baseEffect.TriggerMaxTurns, upgradeEffect.TriggerMaxTurns, 0, 999);
			fused.AutoPlayLoopLimit = AddUpgradeDelta(baseEffect.AutoPlayLoopLimit, upgradeEffect.AutoPlayLoopLimit, 0, 999);
			fused.StatefulTransformDurationAmount = AddUpgradeDelta(baseEffect.StatefulTransformDurationAmount, upgradeEffect.StatefulTransformDurationAmount, 1, 99);
			fused.CreatedCardsCostTurns = AddUpgradeDelta(baseEffect.CreatedCardsCostTurns, upgradeEffect.CreatedCardsCostTurns, 1, 99);
			fused.CardCostsLessTurns = AddUpgradeDelta(baseEffect.CardCostsLessTurns, upgradeEffect.CardCostsLessTurns, 1, 99);
			fused.MatchingCostUseLimit = AddUpgradeDelta(baseEffect.MatchingCostUseLimit, upgradeEffect.MatchingCostUseLimit, 1, 999);
			fused.CountTurns = AddUpgradeDelta(baseEffect.CountTurns, upgradeEffect.CountTurns, 1, 99);
			fused.CountConditionAmount = AddUpgradeDelta(baseEffect.CountConditionAmount, upgradeEffect.CountConditionAmount, 0, 999);
			int mergedHistoryBaseAmount = AddUpgradeDelta(
				ResolveHistoryScalingBaseAmount(baseEffect, baseEffect.Amount),
				upgradeEffect.HistoryScalingBaseAmount.GetValueOrDefault(),
				0,
				999);
			fused.HistoryScalingBaseAmount = mergedHistoryBaseAmount == fused.Amount ? null : mergedHistoryBaseAmount;
			fused.HistoryScalingCountStep = AddUpgradeDelta(
				ResolveHistoryScalingCountStep(baseEffect),
				NormalizeUpgradeHistoryScalingCountStepDelta(upgradeEffect),
				1,
				999);
			fused.RepeatScalingExtraTimes = AddUpgradeDelta(
				ResolveRepeatScalingExtraTimes(baseEffect),
				NormalizeUpgradeRepeatScalingExtraTimesDelta(upgradeEffect),
				1,
				99);
			fused.CardGrantTurns = AddUpgradeDelta(baseEffect.CardGrantTurns, upgradeEffect.CardGrantTurns, 1, 99);
			fused.CardSelectionCount = AddUpgradeDelta(baseEffect.CardSelectionCount, upgradeEffect.CardSelectionCount, 0, 99);
			fused.CardSelectionOfferCount = AddUpgradeDelta(baseEffect.CardSelectionOfferCount, upgradeEffect.CardSelectionOfferCount, 0, 99);
			fused.EnchantmentTurns = AddUpgradeDelta(baseEffect.EnchantmentTurns, upgradeEffect.EnchantmentTurns, 1, 99);
			fused.ConditionalBonusAmount = Math.Clamp(baseEffect.ConditionalBonusAmount + upgradeEffect.ConditionalBonusAmount, -99, 99);
		}
		else
		{
			fused.Turns = upgradeEffect.Turns;
			fused.RepeatCount = Math.Clamp(upgradeEffect.RepeatCount, fused.RepeatIsX ? 0 : 1, 99);
			fused.TriggerEveryN = upgradeEffect.TriggerEveryN;
			fused.TriggerMaxFires = upgradeEffect.TriggerMaxFires;
			fused.TriggerMaxTurns = upgradeEffect.TriggerMaxTurns;
			fused.AutoPlayLoopLimit = Math.Clamp(upgradeEffect.AutoPlayLoopLimit, 0, 999);
			fused.StatefulTransformDurationAmount = Math.Clamp(upgradeEffect.StatefulTransformDurationAmount, 1, 99);
			fused.CreatedCardsCostTurns = upgradeEffect.CreatedCardsCostTurns;
			fused.CardCostsLessTurns = upgradeEffect.CardCostsLessTurns;
			fused.MatchingCostUseLimit = Math.Clamp(upgradeEffect.MatchingCostUseLimit, 1, 999);
			fused.CountTurns = upgradeEffect.CountTurns;
			fused.CountConditionAmount = upgradeEffect.CountConditionAmount;
			fused.HistoryScalingBaseAmount = upgradeEffect.HistoryScalingBaseAmount;
			fused.HistoryScalingCountStep = ResolveHistoryScalingCountStep(upgradeEffect);
			fused.RepeatScalingExtraTimes = ResolveRepeatScalingExtraTimes(upgradeEffect);
			fused.CardGrantTurns = upgradeEffect.CardGrantTurns;
			fused.CardSelectionCount = upgradeEffect.CardSelectionCount;
			fused.CardSelectionOfferCount = upgradeEffect.CardSelectionOfferCount;
			fused.EnchantmentTurns = upgradeEffect.EnchantmentTurns;
			fused.ConditionalBonusAmount = upgradeEffect.ConditionalBonusAmount;
		}

		// Some upgrade deltas are absolute (not additive) even when numeric fields are deltas.
		// Only merge fields that are safe and exposed in the upgrade delta UI.
		if (baseEffect.Kind == CardExtraEffectKind.OrbAction && upgradeEffect.Kind == CardExtraEffectKind.OrbAction)
		{
			fused.OrbAction = upgradeEffect.OrbAction;
			fused.OrbScope = upgradeEffect.OrbScope;
			fused.OrbType = upgradeEffect.OrbType;
			fused.OrbSelection = upgradeEffect.OrbSelection;
			fused.OrbFollowUp = upgradeEffect.OrbFollowUp;
		}

		fused.CountExcludeSourceCard = upgradeEffect.CountExcludeSourceCard;
		fused.ConditionProgressDisplay = upgradeEffect.ConditionProgressDisplay;
		fused.AutoPlayAllowSelfTrigger = upgradeEffect.AutoPlayAllowSelfTrigger;
		fused.AutoPlayLoopScope = upgradeEffect.AutoPlayLoopScope;
		fused.UseLimitWindow = upgradeEffect.UseLimitWindow;
		fused.EffectLimitTargetEffectIds = upgradeEffect.EffectLimitTargetEffectIds;
		fused.PowerStackMode = upgradeEffect.PowerStackMode;
		fused.PowerPersistenceMode = upgradeEffect.PowerPersistenceMode;
		fused.DurationTickPolicy = upgradeEffect.DurationTickPolicy;
		fused.AutoPlayForceExhaust = upgradeEffect.AutoPlayForceExhaust;
		fused.PlayPreventionBlockMode = upgradeEffect.PlayPreventionBlockMode;
		fused.PlayPreventionExemption = upgradeEffect.PlayPreventionExemption;
		fused.GlowColorMode = upgradeEffect.GlowColorMode;
		fused.GlowCustomColor = upgradeEffect.GlowCustomColor;
		fused.QuestMode = upgradeEffect.QuestMode;
		fused.QuestActIndex = upgradeEffect.QuestActIndex;
		fused.QuestEventId = upgradeEffect.QuestEventId;
		fused.QuestActiveScope = upgradeEffect.QuestActiveScope;
		fused.QuestCompletionLimit = upgradeEffect.QuestCompletionLimit;
		fused.ChooseOneExecutionMode = upgradeEffect.ChooseOneExecutionMode;
		fused.ChooseOneResolveMode = upgradeEffect.ChooseOneResolveMode;
		fused.ChooseOneChoiceRule = upgradeEffect.ChooseOneChoiceRule;
		fused.ChooseOneResolveCount = upgradeEffect.ChooseOneResolveCount;
		fused.PayloadOnly = upgradeEffect.PayloadOnly;
		fused.PotionMode = upgradeEffect.PotionMode;
		fused.PotionPoolFilter = upgradeEffect.PotionPoolFilter;
		fused.PotionRarityFilter = upgradeEffect.PotionRarityFilter;
		fused.PotionInCombatOnly = upgradeEffect.PotionInCombatOnly;
		fused.PotionAllowDuplicates = upgradeEffect.PotionAllowDuplicates;
		fused.SpecificPotionId = upgradeEffect.SpecificPotionId;
		fused.CardRewardRarityFilter = upgradeEffect.CardRewardRarityFilter;
		fused.CardRewardSource = upgradeEffect.CardRewardSource;
		fused.CardRewardRarityOdds = upgradeEffect.CardRewardRarityOdds;
		fused.CountAggregationMode = GetEffectiveCountAggregationMode(upgradeEffect);
		fused.CountUsesCardEffectAmount = fused.CountAggregationMode == CardExtraEffectCountAggregationMode.MatchingEffectAmount;
		fused.CreatedCardsCostDuration = upgradeEffect.CreatedCardsCostDuration;
		fused.CreatedCardsCostResource = upgradeEffect.CreatedCardsCostResource;
		fused.CardCostsLessModifier = upgradeEffect.CardCostsLessModifier;
		fused.MatchingCostUseLimitMode = upgradeEffect.MatchingCostUseLimitMode;
		fused.UseMoveDestinationForGeneratedCards = upgradeEffect.UseMoveDestinationForGeneratedCards;
		fused.AdditionalMoveToPiles = upgradeEffect.AdditionalMoveToPiles;
		fused.CopyMode = upgradeEffect.CopyMode;
		fused.GeneratedCardOwnerMode = upgradeEffect.GeneratedCardOwnerMode;
		fused.DelayedPileAction = upgradeEffect.DelayedPileAction;
		fused.DelayedPileCounterUnit = upgradeEffect.DelayedPileCounterUnit;
		fused.DelayedPileCounterScope = upgradeEffect.DelayedPileCounterScope;
		fused.ConsumedCardAction = upgradeEffect.ConsumedCardAction;
		fused.ConsumedCardValueSource = upgradeEffect.ConsumedCardValueSource;
		fused.PowerTriggerEnemyStatus = upgradeEffect.PowerTriggerEnemyStatus;
		fused.PowerTriggerPowerId = upgradeEffect.PowerTriggerPowerId;
		fused.PowerTriggerUsesEventAmount = upgradeEffect.PowerTriggerUsesEventAmount;
		fused.ConditionalBonusConditionType = upgradeEffect.ConditionalBonusConditionType;
		fused.ConditionalBonusCondition = upgradeEffect.ConditionalBonusCondition;
		fused.ConditionalBonusEnemyStatus = upgradeEffect.ConditionalBonusEnemyStatus;
		fused.ConditionalBonusEnemyIntent = upgradeEffect.ConditionalBonusEnemyIntent;
		fused.BranchMode = upgradeEffect.BranchMode;
		fused.BranchConditionType = upgradeEffect.BranchConditionType;
		fused.BranchCondition = upgradeEffect.BranchCondition;
		fused.BranchEnemyStatus = upgradeEffect.BranchEnemyStatus;
		fused.BranchEnemyIntent = upgradeEffect.BranchEnemyIntent;
		fused.BranchCountEvent = upgradeEffect.BranchCountEvent;
		fused.BranchCountWindow = upgradeEffect.BranchCountWindow;
		fused.BranchCountWindowInclusion = upgradeEffect.BranchCountWindowInclusion;
		fused.BranchBlockLostCountingMode = upgradeEffect.BranchBlockLostCountingMode;
		fused.BranchCountTurns = upgradeEffect.BranchCountTurns;
		fused.BranchCountCardPile = upgradeEffect.BranchCountCardPile;
		fused.BranchCountCardPool = upgradeEffect.BranchCountCardPool;
		fused.BranchCountCardType = upgradeEffect.BranchCountCardType;
		fused.BranchCountCardRarity = upgradeEffect.BranchCountCardRarity;
		fused.BranchCountCardFilter = upgradeEffect.BranchCountCardFilter;
		fused.BranchCountCardMatchMode = upgradeEffect.BranchCountCardMatchMode;
		fused.BranchCountMatchCardId = upgradeEffect.BranchCountMatchCardId;
		fused.BranchCountMatchTagKind = upgradeEffect.BranchCountMatchTagKind;
		fused.BranchCountMatchVanillaTag = upgradeEffect.BranchCountMatchVanillaTag;
		fused.BranchCountMatchCustomTag = upgradeEffect.BranchCountMatchCustomTag;
		fused.BranchCountMatchCustomKeyword = upgradeEffect.BranchCountMatchCustomKeyword;
		fused.BranchCountAggregationMode = GetEffectiveBranchCountAggregationMode(upgradeEffect);
		fused.BranchCountUsesCardEffectAmount = fused.BranchCountAggregationMode == CardExtraEffectCountAggregationMode.MatchingEffectAmount;
		fused.BranchCountExcludeSourceCard = upgradeEffect.BranchCountExcludeSourceCard;
		fused.BranchCountOrbType = upgradeEffect.BranchCountOrbType;
		fused.BranchCountOrbSelection = upgradeEffect.BranchCountOrbSelection;
		fused.BranchCountEnemyStatus = upgradeEffect.BranchCountEnemyStatus;
		fused.BranchCountPowerId = upgradeEffect.BranchCountPowerId;
		fused.BranchCountEnemyIntent = upgradeEffect.BranchCountEnemyIntent;
		fused.BranchCountDamageTarget = upgradeEffect.BranchCountDamageTarget;
		fused.BranchCountDamageDealer = upgradeEffect.BranchCountDamageDealer;
		fused.BranchCountDamageSource = upgradeEffect.BranchCountDamageSource;
		fused.BranchCountDamageAggregation = upgradeEffect.BranchCountDamageAggregation;
		fused.BranchCountDamageCurrentInclusion = upgradeEffect.BranchCountDamageCurrentInclusion;
		fused.BranchCountResultEffectId = upgradeEffect.BranchCountResultEffectId;
		fused.BranchCountResultMetric = upgradeEffect.BranchCountResultMetric;
		fused.BranchCountComparison = upgradeEffect.BranchCountComparison;
		fused.BranchCountConditionAmount = upgradeEffect.BranchCountConditionAmount;
		fused.BranchEffect = upgradeEffect.BranchEffect != null ? CloneEffect(upgradeEffect.BranchEffect) : null;
		fused.ConditionalBonusPowerId = upgradeEffect.ConditionalBonusPowerId;
		fused.BranchPowerId = upgradeEffect.BranchPowerId;
		fused.CountPowerId = upgradeEffect.CountPowerId;
		fused.CountCardRarity = upgradeEffect.CountCardRarity;
		fused.CountDamageTarget = upgradeEffect.CountDamageTarget;
		fused.CountDamageDealer = upgradeEffect.CountDamageDealer;
		fused.CountDamageSource = upgradeEffect.CountDamageSource;
		fused.CountDamageAggregation = upgradeEffect.CountDamageAggregation;
		fused.CountDamageCurrentInclusion = upgradeEffect.CountDamageCurrentInclusion;
		fused.CountResultEffectId = upgradeEffect.CountResultEffectId;
		fused.CountResultMetric = upgradeEffect.CountResultMetric;
		// Any is the unset default: an upgrade row with no match filter inherits the base row's
		// restriction (same rule as CustomKeywordName below) instead of erasing it.
		if (upgradeEffect.CardMatchMode != CardExtraEffectCardMatchMode.Any)
		{
			fused.CardMatchMode = upgradeEffect.CardMatchMode;
			fused.MatchCardId = upgradeEffect.MatchCardId;
			fused.MatchTagKind = upgradeEffect.MatchTagKind;
			fused.MatchVanillaTag = upgradeEffect.MatchVanillaTag;
			fused.MatchCustomTag = upgradeEffect.MatchCustomTag;
			fused.MatchCustomKeyword = upgradeEffect.MatchCustomKeyword;
		}
		fused.NameFilterEnabled = upgradeEffect.NameFilterEnabled;
		fused.NameFilterText = upgradeEffect.NameFilterText;
		fused.CostFilterEnabled = upgradeEffect.CostFilterEnabled;
		fused.CostFilterMode = upgradeEffect.CostFilterMode;
		fused.CostFilterMax = upgradeEffect.CostFilterMax;
		fused.CardSelectionRarity = upgradeEffect.CardSelectionRarity;
		fused.TriggerCardRarity = upgradeEffect.TriggerCardRarity;
		string? upgradeKeyword = NormalizeCustomKeywordName(upgradeEffect.CustomKeywordName);
		if (upgradeKeyword != null)
		{
			fused.CustomKeywordName = upgradeKeyword;
		}
		string? upgradePowerName = string.IsNullOrWhiteSpace(upgradeEffect.CustomPowerName) ? null : upgradeEffect.CustomPowerName.Trim();
		if (upgradePowerName != null)
		{
			fused.CustomPowerName = upgradePowerName;
		}
		string? upgradePowerDescription = string.IsNullOrWhiteSpace(upgradeEffect.CustomPowerDescription) ? null : upgradeEffect.CustomPowerDescription.Trim();
		if (upgradePowerDescription != null)
		{
			fused.CustomPowerDescription = upgradePowerDescription;
		}
		fused.StatusIconMode = upgradeEffect.StatusIconMode;
		fused.StatusIconPowerId = upgradeEffect.StatusIconPowerId;
		fused.StatusCustomPackedIconPath = upgradeEffect.StatusCustomPackedIconPath;
		fused.StatusCustomBigIconPath = upgradeEffect.StatusCustomBigIconPath;
		fused.PowerId = upgradeEffect.PowerId;
		fused.CreatureCommandId = upgradeEffect.CreatureCommandId;
		fused.PowerHost = GetEffectivePowerHost(upgradeEffect);
		fused.PowerTriggerFrom = GetEffectivePowerTriggerFrom(upgradeEffect);
		fused.PowerTargeting = upgradeEffect.PowerTargeting;
		fused.CardReferenceDisplayMode = upgradeEffect.CardReferenceDisplayMode;
		fused.SpecificCardUpgradeMode = upgradeEffect.SpecificCardUpgradeMode;
		// Fixed/blank is the unset default: an upgrade row with no amount link authored inherits
		// the base row's amount/value sources instead of erasing them (same rule as CardMatch*) -
		// "Deal damage equal to the Poison applied" must survive upgrading.
		if (upgradeEffect.AmountSourceMode != CardExtraEffectAmountSourceMode.Fixed
			|| !string.IsNullOrWhiteSpace(upgradeEffect.AmountSourceEffectId))
		{
			fused.AmountSourceMode = upgradeEffect.AmountSourceMode;
			fused.AmountSourceEffectId = upgradeEffect.AmountSourceEffectId;
			fused.AmountSourceMultiplier = upgradeEffect.AmountSourceMultiplier;
			fused.ValueSourceMode = upgradeEffect.ValueSourceMode;
			fused.ValueSourceActor = upgradeEffect.ValueSourceActor;
			fused.ValueSourceAggregation = upgradeEffect.ValueSourceAggregation;
			fused.ValueSourceKind = upgradeEffect.ValueSourceKind;
			fused.ValueSourcePowerId = upgradeEffect.ValueSourcePowerId;
		}
		if (upgradeEffect.MultiplierSourceMode != default)
		{
			fused.MultiplierSourceMode = upgradeEffect.MultiplierSourceMode;
			fused.MultiplierPowerId = upgradeEffect.MultiplierPowerId;
		}
		if (!string.IsNullOrWhiteSpace(upgradeEffect.CardSelectionSourceEffectId))
		{
			fused.CardSelectionSourceEffectId = upgradeEffect.CardSelectionSourceEffectId;
		}
		fused.IncludeSourceCardInSelection = upgradeEffect.IncludeSourceCardInSelection;
		fused.FutureMatchingCards = upgradeEffect.FutureMatchingCards;
		fused.ResourceConsumptionMode = upgradeEffect.ResourceConsumptionMode;
		fused.ResourceConsumptionStat = upgradeEffect.ResourceConsumptionStat;
		fused.StatusToStatusMode = upgradeEffect.StatusToStatusMode;
		fused.ActivePowerSelection = upgradeEffect.ActivePowerSelection;
		fused.SelfScalingOperation = upgradeEffect.SelfScalingOperation;
		fused.SelfScalingTargetType = upgradeEffect.SelfScalingTargetType;
		fused.SelfScalingField = upgradeEffect.SelfScalingField;
		fused.SelfScalingRecipientMode = upgradeEffect.SelfScalingRecipientMode;
		fused.SelfScalingNumberSelectionMode = upgradeEffect.SelfScalingNumberSelectionMode;
		fused.SelfScalingNumberFilter = upgradeEffect.SelfScalingNumberFilter;
		fused.SelfScalingTargetEffectId = upgradeEffect.SelfScalingTargetEffectId;
		fused.SelfScalingDynamicVarKey = upgradeEffect.SelfScalingDynamicVarKey;

		if (baseEffect.Kind == CardExtraEffectKind.TransformCards && upgradeEffect.Kind == CardExtraEffectKind.TransformCards)
		{
			fused.TransformMode = upgradeEffect.TransformMode;
			fused.SpecificCardId = upgradeEffect.SpecificCardId;
		}

		if (baseEffect.Kind == CardExtraEffectKind.StatefulTransform && upgradeEffect.Kind == CardExtraEffectKind.StatefulTransform)
		{
			fused.StatefulTransformMode = upgradeEffect.StatefulTransformMode;
			fused.StatefulTransformDuration = upgradeEffect.StatefulTransformDuration;
			fused.SpecificCardId = upgradeEffect.SpecificCardId;
		}

	if (baseEffect.Kind == CardExtraEffectKind.ChooseOneEffectSource && upgradeEffect.Kind == CardExtraEffectKind.ChooseOneEffectSource)
	{
		fused.SpecificCardId = upgradeEffect.SpecificCardId;
		fused.SpecificCardId2 = upgradeEffect.SpecificCardId2;
		fused.SpecificCardId3 = upgradeEffect.SpecificCardId3;
		fused.ChooseOneExecutionMode = upgradeEffect.ChooseOneExecutionMode;
		fused.ChooseOneResolveMode = upgradeEffect.ChooseOneResolveMode;
		fused.ChooseOneChoiceRule = upgradeEffect.ChooseOneChoiceRule;
		fused.ChooseOneResolveCount = upgradeEffect.ChooseOneResolveCount;
		fused.ChooseOneOption1 = CloneChooseOneOption(upgradeEffect.ChooseOneOption1);
		fused.ChooseOneOption2 = CloneChooseOneOption(upgradeEffect.ChooseOneOption2);
		fused.ChooseOneOption3 = CloneChooseOneOption(upgradeEffect.ChooseOneOption3);
	}

		CardEditorUpgradeDeltaDebugLog.LogMergeFunction(
			"ExtraEffects.MergeUpgradeBaseSlotEffect",
			baseEffect,
			upgradeEffect,
			fused,
			numericFieldsAreDeltas);

		return fused;
	}

	private static int AddUpgradeDelta(int baseValue, int deltaValue, int minValue, int maxValue)
	{
		return Math.Clamp(baseValue + deltaValue, minValue, maxValue);
	}

	internal static bool EffectsMatchExceptAmount(CardExtraEffect a, CardExtraEffect b)
	{
		if (a == null || b == null)
		{
			return false;
		}
		return a.Kind == b.Kind
			&& a.Target == b.Target
			&& a.PayloadOnly == b.PayloadOnly
			&& a.AmountIsX == b.AmountIsX
			&& a.AmountSourceMode == b.AmountSourceMode
			&& string.Equals(a.AmountSourceEffectId ?? string.Empty, b.AmountSourceEffectId ?? string.Empty, StringComparison.Ordinal)
			&& a.AmountSourceMultiplier == b.AmountSourceMultiplier
			&& a.ValueSourceMode == b.ValueSourceMode
			&& a.ValueSourceActor == b.ValueSourceActor
			&& a.ValueSourceAggregation == b.ValueSourceAggregation
			&& a.ValueSourceKind == b.ValueSourceKind
			&& string.Equals(a.ValueSourcePowerId ?? string.Empty, b.ValueSourcePowerId ?? string.Empty, StringComparison.Ordinal)
			&& a.Trigger == b.Trigger
