	internal static bool IsDuplicateGrantedEffect(CardExtraEffect? existing, CardExtraEffect? candidate)
	{
		if (existing == null || candidate == null)
		{
			return false;
		}

		string? existingPackageKey = GetCanonicalGrantPackageKey(existing);
		string? candidatePackageKey = GetCanonicalGrantPackageKey(candidate);
		if (!string.IsNullOrWhiteSpace(existingPackageKey)
			&& !string.IsNullOrWhiteSpace(candidatePackageKey)
			&& string.Equals(existingPackageKey, candidatePackageKey, StringComparison.Ordinal))
		{
			return true;
		}

		if (!EffectsMatchExceptAmount(existing, candidate))
		{
			return false;
		}
		if (existing.Amount != candidate.Amount
			|| existing.AmountXPlus != candidate.AmountXPlus)
		{
			return false;
		}

		bool existingHasId = !string.IsNullOrWhiteSpace(existing.EffectId);
		bool candidateHasId = !string.IsNullOrWhiteSpace(candidate.EffectId);
		if (existingHasId || candidateHasId)
		{
			if (existingHasId && candidateHasId && string.Equals(existing.EffectId, candidate.EffectId, StringComparison.Ordinal))
			{
				return true;
			}

			return IsNonStackingGrantedEffectKind(existing.Kind);
		}

		return true;
	}

	// Vanilla parity (bug list #3): re-granting an equivalent magnitude effect to a card STACKS its
	// amount ("gains Gain 1 Thorns" twice = Gain 2 Thorns) instead of being silently ignored.
	// Returns true when `candidate` matched `existing` and its amount was folded into existing.Amount.
	// Keyword grant packages keep identity semantics (re-granting the same keyword stays a no-op),
	// and X-amount or non-magnitude kinds never stack.
	internal static bool TryStackDuplicateGrantedEffect(CardExtraEffect? existing, CardExtraEffect? candidate)
	{
		if (existing == null || candidate == null)
		{
			return false;
		}

		string? existingPackageKey = GetCanonicalGrantPackageKey(existing);
		string? candidatePackageKey = GetCanonicalGrantPackageKey(candidate);
		if (!string.IsNullOrWhiteSpace(existingPackageKey) || !string.IsNullOrWhiteSpace(candidatePackageKey))
		{
			return false;
		}

		if (existing.AmountIsX
			|| candidate.AmountIsX
			|| existing.AmountXPlus != candidate.AmountXPlus
			|| IsNonStackingGrantedEffectKind(existing.Kind)
			|| !EffectsMatchExceptAmount(existing, candidate))
		{
			return false;
		}

		existing.Amount += candidate.Amount;
		return true;
	}

	internal static bool PowerEffectEntriesMatch(CardExtraEffect? existing, CardExtraEffect? candidate)
	{
		if (existing == null
			|| candidate == null
			|| existing.PowerStackMode != CardExtraEffectPowerStackMode.Merge
			|| candidate.PowerStackMode != CardExtraEffectPowerStackMode.Merge
			|| existing.PowerPersistenceMode != candidate.PowerPersistenceMode)
		{
			return false;
		}

		return existing.Amount == candidate.Amount
			&& existing.AmountXPlus == candidate.AmountXPlus
			&& existing.TriggerEveryN == candidate.TriggerEveryN
			&& PowerEffectEntriesMatchExceptRuntimeCounters(existing, candidate);
	}

	private static bool PowerEffectEntriesMatchExceptRuntimeCounters(CardExtraEffect existing, CardExtraEffect candidate)
	{
		CardExtraEffect normalizedExisting = CloneEffect(existing);
		CardExtraEffect normalizedCandidate = CloneEffect(candidate);
		NormalizePowerMergeRuntimeCounters(normalizedExisting);
		NormalizePowerMergeRuntimeCounters(normalizedCandidate);
		return EffectsMatchExceptAmount(normalizedExisting, normalizedCandidate);
	}

	private static void NormalizePowerMergeRuntimeCounters(CardExtraEffect? effect)
	{
		if (effect == null)
		{
			return;
		}

		effect.AutoPlayLoopLimit = effect.AutoPlayLoopLimit > 0 ? 1 : 0;
		effect.TriggerMaxFires = effect.TriggerMaxFires > 0 ? 1 : 0;
		effect.TriggerMaxTurns = effect.TriggerMaxTurns > 0 ? 1 : 0;
		NormalizePowerMergeRuntimeCounters(effect.BranchEffect);
	}

	private static bool IsNonStackingGrantedEffectKind(CardExtraEffectKind kind)
	{
		return !SupportsRepeat(kind)
			|| kind is CardExtraEffectKind.IgnoreBlock
				or CardExtraEffectKind.HitsAllEnemies
				or CardExtraEffectKind.DoesNotConsumeVigor;
	}

	internal static CardExtraEffect CloneEffect(CardExtraEffect source)
	{
		// Memberwise copy so newly added fields can never be silently dropped again; only the
		// mutable reference-typed members need explicit deep copies.
		CardExtraEffect clone = source.ShallowCopy();
		clone.BranchEffect = source.BranchEffect != null ? CloneEffect(source.BranchEffect) : null;
		clone.ChooseOneOption1 = CloneChooseOneOption(source.ChooseOneOption1);
		clone.ChooseOneOption2 = CloneChooseOneOption(source.ChooseOneOption2);
		clone.ChooseOneOption3 = CloneChooseOneOption(source.ChooseOneOption3);
		return clone;
	}

	private static bool BranchEffectsMatch(CardExtraEffect? a, CardExtraEffect? b)
	{
		if (a == null || b == null)
		{
			return a == b;
		}

		return a.Amount == b.Amount
			&& a.AmountXPlus == b.AmountXPlus
			&& EffectsMatchExceptAmount(a, b);
	}

	private static int ResolveXAmountWithPlus(CardPlay cardPlay, int plus)
	{
		long value = (long)ResolveXAmount(cardPlay) + plus;
		if (value >= int.MaxValue)
		{
			return int.MaxValue;
		}
		if (value <= int.MinValue)
		{
			return int.MinValue;
		}
		return (int)value;
	}

	internal static CardExtraEffect CloneForDeferredExecution(CardPlay? sourcePlay, CardExtraEffect source)
	{
		CardExtraEffect clone = CloneEffect(source);
		CaptureDeferredXValues(sourcePlay, clone);
		return clone;
	}

	private static void CaptureDeferredXValues(CardPlay? sourcePlay, CardExtraEffect? effect)
	{
		if (sourcePlay == null || effect == null)
		{
			return;
		}

		if (effect.AmountIsX)
		{
			int resolvedAmount = ResolveXAmountWithPlus(sourcePlay, effect.AmountXPlus);
			int resolvedMagnitude = resolvedAmount == int.MinValue ? int.MaxValue : Math.Abs(resolvedAmount);
			if (effect.Amount < 0 && IsValidEffectAmount(effect.Kind, -resolvedMagnitude))
			{
				resolvedAmount = -resolvedMagnitude;
			}

			effect.Amount = resolvedAmount;
			effect.AmountIsX = false;
			effect.AmountXPlus = 0;
		}

		if (effect.RepeatIsX)
		{
			int resolvedRepeat = Math.Clamp(ResolveXAmountWithPlus(sourcePlay, effect.RepeatCount), 0, 99);
			effect.RepeatIsX = false;
			effect.RepeatCount = resolvedRepeat > 0 ? resolvedRepeat : -1;
		}

		if (effect.CardSelectionCountIsX)
		{
			effect.CardSelectionCount = Math.Max(0, ResolveXAmountWithPlus(sourcePlay, effect.CardSelectionCount));
			effect.CardSelectionCountIsX = false;
		}

		if (effect.CardSelectionOfferCountIsX)
		{
			effect.CardSelectionOfferCount = Math.Max(0, ResolveXAmountWithPlus(sourcePlay, effect.CardSelectionOfferCount));
			effect.CardSelectionOfferCountIsX = false;
		}

		if (effect.BranchEffect != null)
		{
			CaptureDeferredXValues(sourcePlay, effect.BranchEffect);
		}
	}

	private static string FormatXPlusText(int plus)
	{
		if (plus == 0)
		{
			return "X";
		}
		return plus > 0
			? "X+" + plus.ToString(CultureInfo.InvariantCulture)
			: "X" + plus.ToString(CultureInfo.InvariantCulture);
	}
}
